local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:516"] = {n="博伦的巢穴",s="博伦的巢穴是部落的一项任务，由瑟伯切尔的暗影牧师奥利斯特指派。被遗忘者的特工们获悉，一群天灾军团正隐藏在银松森林南部群山中一处隐秘的洞穴里集结，他们必须在敌人发动进攻前将其铲除。",h="博伦的巢穴是部落的一项任务，由瑟伯切尔的暗影牧师奥利斯特指派。被遗忘者的特工们获悉，一群天灾军团正隐藏在银松森林南部群山中一处隐秘的洞穴里集结，他们必须在敌人发动进攻前将其铲除。",kw={"安伯米尔","博伦的巢穴","鸦爪苦工","鸦爪守卫","天灾军团","暗影牧师奥利斯特","银松森林","瑟伯切尔"},ang={["class:Priest"]="在暗影牧师奥利斯特的命令下，黑暗施法者通过消灭敌对的亡灵恐怖势力，协助巩固瑟伯切尔的权威。",["faction:Horde"]="清理银松森林边境隐藏的天灾军团残部，有助于为整个部落稳定洛丹伦北部局势。",["race:Undead"]="对于被遗忘者来说，清除像博伦的巢穴这样的天灾军团残党是纯粹的生存问题，这巩固了他们对抗巫妖王挥之不去的阴影的统治权。"},sec={{t="先发制人",b="瑟伯切尔的暗影牧师奥利斯特得到消息，巫妖王的无脑仆从们正在银松森林南部深处集结。如果不加干预，这支天灾军团将直接威胁到被遗忘者在整个地区的行动。奥利斯特没有坐以待毙，而是指示斥候主动出击，在这些集结的部落发动攻势前，将其消灭在隐秘的巢穴中。"},{t="隐秘洞穴",b="博伦的巢穴本身是一个错综复杂的洞穴网络，位于达拉然控制的安伯米尔以南的群山之中。由于地形险恶，这个洞穴很容易被忽略，只能通过绕过南侧山坡才能找到入口。在阴影中栖息着鸦爪苦工和守卫，他们是瘟疫留下的残余势力，消灭他们有助于确保被遗忘者维持对这片森林的微弱控制。"}},faq={{q="什么是博伦的巢穴？",a="博伦的巢穴是一个位于银松森林南部山区，安伯米尔以南的隐秘洞穴。它作为天灾军团残党——鸦爪亡灵的藏身处。",al={"博伦的巢穴","博伦的巢穴在哪里","这个洞穴是什么"}},{q="谁指派了前往博伦的巢穴的任务？",a="驻扎在银松森林瑟伯切尔的暗影牧师奥利斯特，在得知敌对亡灵正利用该洞穴进行集结准备进攻后，将此任务交给了部落冒险者。",al={"谁给予博伦的巢穴任务","博伦的巢穴任务发布者","暗影牧师奥利斯特任务"}},{q="为什么被遗忘者要攻击那里的亡灵？",a="博伦的巢穴里的亡灵效忠于巫妖王，是天灾军团的一部分。被遗忘者已经摆脱了巫妖王的控制，并积极战斗以清除领地内残存的爪牙。",al={"为什么要杀死亡灵","为什么要与鸦爪亡灵战斗","被遗忘者不是亡灵吗"}},{q="如何找到洞穴入口？",a="该洞穴隐藏在安伯米尔南部的群山中。由于山脊陡峭，必须从山丘的南侧进入，而不能直接从北面进入。",al={"如何前往博伦的巢穴","洞穴入口位置","洞穴入口在哪里"}},{q="博伦的巢穴里有什么敌人？",a="洞穴内居住着天灾军团的奴仆，具体来说是鸦爪苦工和鸦爪守卫，他们似乎正在集结，准备袭击附近的定居点。",al={"博伦的巢穴怪物","博伦的巢穴里面有什么"}},{q="达拉然在这个任务中扮演什么角色？",a="达拉然在任务本身中没有直接的作用，尽管来自达拉然的人类法师占领了附近的安伯米尔。奥利斯特提到他们仅仅是为了将这些法师作为地标，帮助斥候定位这个隐藏的洞穴。",al={"达拉然的联系","安伯米尔的联系"}}},fp="13,289,19.433.0,15.428.0,22.200.0,41.184.0,48.209.0,41.183.0,35.168.0,44.196.0"}
P.entries["quest:517"] = {n="苦楚药剂",s="这个任务是药剂师林度恩在塔伦米尔不懈开发一种毁灭性被遗忘者毒药的第四个篇章。致命的痛苦药剂终于酿制完成，林度恩派遣部落勇士前往丹加洛克，去偷取一桶矿工烈酒送过来。",h="这个任务是药剂师林度恩在塔伦米尔不懈开发一种毁灭性被遗忘者毒药的第四个篇章。致命的痛苦药剂终于酿制完成，林度恩派遣部落勇士前往丹加洛克，去偷取一桶矿工烈酒送过来。",kw={"药剂师林度恩","丹加洛克","矮人","痛苦药剂","希尔斯布莱德","矿工烈酒","塔伦米尔","乌比"},ang={["class:Rogue"]="在丹加洛克拥挤的食堂里潜行而不被发现，是在登山者眼皮底下进行隐秘盗窃的大师级示范。",["faction:Horde"]="削弱联盟在丹加洛克的势力，有助于塔伦米尔维持对南方无情威胁的微妙立足点。",["race:Dwarf"]="将传统的矮人啤酒亵渎为化学屠杀的容器，是对铁炉堡工艺的深刻侮辱。",["race:Undead"]="林度恩完善的每一批药剂，都让被遗忘者离针对侵入洛丹伦的活人敌人们实施死亡武器化更近了一步。"},sec={{t="苦涩的酿造",b="在塔伦米尔潮湿的角落里，药剂师林度恩代表皇家药剂师协会和希尔瓦娜斯女王不知疲倦地工作着。在收集了整个希尔斯布莱德的致命原料后，他的新药剂终于完成了。林度恩没兴趣在青蛙或流浪狗这种琐碎生物身上浪费如此强效的药剂；他寻求的是在活生生的敌人身上进行真实的、切实的测试。"},{t="潜入丹加洛克",b="为了实施他的实验，林度恩需要一个不起眼的投毒载体。在希尔斯布莱德南部，铁炉堡矮人加固了丹加洛克的要塞。林度恩指示部落的特工潜入地下军营和食堂，绕过矮人的火枪和斧头，偷走一桶珍贵的矿工烈酒。"},{t="灾难配方",b="林度恩打算把他那致命的毒素直接掺进矮人最爱的酒里。一旦注入这桶偷来的酒中，这种药剂就可以伪装成节日饮料，倾倒在毫无防备的目标身上，把深受矮人喜爱的烈酒变成一种恐怖痛苦的工具。"}},faq={{q="药剂师林度恩是谁？",a="药剂师林度恩是一位驻扎在塔伦米尔的被遗忘者炼金术士。他代表皇家药剂师协会，为希尔瓦娜斯·风行者女王进行实验，开发致命的瘟疫和药剂。",al={"林度恩","谁发布了这个任务","药剂师林度恩背景故事"}},{q="林度恩为什么需要一桶矿工烈酒？",a="林度恩想要在活体目标身上测试完成后的痛苦药剂。通过将毒素掺入一桶广受欢迎的矮人啤酒中，他创造了一种隐蔽且有效的投毒方式来毒害他的受害者。",al={"为什么使用矮人啤酒","为什么是矿工烈酒","酒桶的用途"}},{q="丹加洛克在哪里？",a="丹加洛克是一座防御严密的矮人堡垒，位于希尔斯布莱德丘陵东南部，由铁炉堡的登山者和火枪手驻守，以保卫他们在北方的利益。",al={"丹加洛克在哪里","丹加洛克位置","我在哪里可以找到酒桶"}},{q="乌比是谁？",a="乌比是药剂师林度恩在塔伦米尔的助手。林度恩打趣说，在实验室周围打开甲醛罐子往往会让乌比明显感到不安。",al={"乌比","乌比是谁","林度的助手"}},{q="痛苦药剂的最终目的是什么？",a="痛苦药剂是皇家药剂师协会设计的一种实验性毒药，旨在根除活人，为被遗忘者将洛丹伦从人类和矮人的立足点中解放出来的战役服务。",al={"痛苦药剂有什么作用","瘟疫的目的","被遗忘者的毒药目标"}},{q="取回酒桶后接下来要做什么？",a="一旦拿到酒桶，林度恩就会在矿工烈酒中加入毒药，并派你去把这些被污染的酒送到一个毫无戒心的实验对象手中。",al={"下一个任务","丹加洛克之后是什么","药剂第五部分"}}},fx={["9a9bdb3b"]={q="你要在丹加洛克对付谁？",a="你将潜入丹加洛克，这是一座位于希尔斯布莱德丘陵东南部、戒备森严的矮人哨站。驻扎在那里的铁炉堡山地步兵和火枪手隶属于联盟，负责保卫矮人在当地的利益，并持续威胁着塔伦米尔的被遗忘者势力。",al={"丹加洛克的矮人","丹加洛克有什么人","谁在看守烈酒"}}},fp="15,277,13.380.0,22.329.0,21.278.1,24.209.0,46.194.0,27.175.0,12.159.0,49.199.0,41.158.1"}
P.entries["quest:518"] = {n="意志之冠",s="在塔伦米尔，梅里萨拉希望在对穆格索尔发动真正的打击之前，先削减碎颅食人魔的数量，穆格索尔的食人魔现在占据了奥特兰克废墟。你被派去击杀碎颅重击者。",h="在塔伦米尔，梅里萨拉希望在对穆格索尔发动真正的打击之前，先削减碎颅食人魔的数量，穆格索尔的食人魔现在占据了奥特兰克废墟。你被派去击杀碎颅重击者。",kw={"碎颅重击者","梅里萨拉","穆格索尔","奥特兰克废墟","沙琳德拉","塔伦米尔","意志之冠"},sec={{t="削弱碎颅者",b="穆格索尔和碎颅食人魔已经占领了奥特兰克废墟。梅里萨拉说，在有这么多食人魔在场的情况下，很难惩罚穆格索尔。必须先减少他们的数量，之后才能采取下一步行动。你的任务是猎杀碎颅重击者。"},{t="还不能休息",b="当重击者被消灭后，梅里萨拉看着雪地被食人魔的鲜血染红，并表示在碎颅者从精神上和数量上彻底崩溃之前，行动不会停止。"}},faq={{q="谁发放了意志之冠任务的这一部分？",a="塔伦米尔的梅里萨拉会将任务交给你，你也要向她回报。",al={"意志之冠任务发放人","梅里萨拉任务发放人","意志之冠后续任务发放人"}},{q="碎颅食人魔在哪里？",a="他们占据了奥特兰克废墟，穆格索尔和他的食人魔已经蹂躏了那里。",al={"碎颅重击者位置","碎颅食人魔在哪里","奥特兰克废墟的食人魔"}},{q="为什么梅里萨拉首先针对重击者？",a="梅里萨拉说，在食人魔数量众多的情况下，很难惩罚穆格索尔，所以在计划进一步推进之前，必须先削减他们的数量。",al={"为什么要杀碎颅重击者","为什么要削减食人魔数量"}}},fp="17,200,24.279.0,11.178.1,41.76.0,39.74.0,44.137.0"}
P.entries["quest:519"] = {n="意志之冠",s="随着食人魔防御力量的削弱，位于塔伦米尔的梅里萨拉希望在对付马克戈尔本人之前，先拿到他手下三名副官——塔格、马克雷克和格洛姆斯——的头颅。",h="随着食人魔防御力量的削弱，位于塔伦米尔的梅里萨拉希望在对付马克戈尔本人之前，先拿到他手下三名副官——塔格、马克雷克和格洛姆斯——的头颅。",kw={"奥特兰克","意志之冠","格洛姆斯","希尔斯布莱德","梅里萨拉","马克雷克","马克戈尔","塔格","塔伦米尔"},sec={{t="狙击首领",b="马克戈尔的副官是塔格、马克雷克和格洛姆斯，他们都对他忠心耿耿，尽管梅里萨拉很奇怪食人魔究竟是什么样的忠诚。你必须杀死这三名副官并将他们的头颅带回塔伦米尔。在那之后，就只剩下马克戈尔的脑袋需要被取下了，连同他的意志之冠一起。"},{t="头颅的下场",b="梅里萨拉感叹食人魔闻起来有多么恶臭。一旦马克戈尔的头颅也送达，这四个头颅都将被插在奥特兰克的长矛上，以此警告任何胆敢冒犯黑暗女王的人。"}},faq={{q="谁发放了意志之冠的这一部分任务？",a="位于塔伦米尔的梅里萨拉会将任务交给你，你也是将头颅带给她的人。",al={"谁开启了意志之冠","梅里萨拉的位置","在哪里交还意志之冠"}},{q="塔格、马克雷克和格洛姆斯是谁？",a="他们是马克戈尔的副官，对他忠心耿耿。梅里萨拉想要他们的头颅。",al={"马克戈尔的副官","食人魔副官是谁","塔格 马克雷克 格洛姆斯"}},{q="这一部分之前发生了什么？",a="意志之冠的第二部分，任务是削减食人魔的数量。",al={"意志之冠任务线","在此之前的任务是什么","之前的意志之冠任务"}}},fp="17,174,25.269.0,25.174.1,41.85.0,36.74.0,27.79.0"}
P.entries["quest:52"] = {n="保卫边境",s="“保卫边境”是卫兵托马斯在艾尔文森林东部桥梁处发布的一项联盟任务。随着暴风城的军事力量向边境收缩，野生捕食者变得越来越大胆，开始骚扰往来旅人和东谷伐木场的工人。卫兵托马斯正在寻找有能力的冒险者，去猎杀那些威胁东部边境的狼和熊。",h="“保卫边境”是卫兵托马斯在艾尔文森林东部桥梁处发布的一项联盟任务。随着暴风城的军事力量向边境收缩，野生捕食者变得越来越大胆，开始骚扰往来旅人和东谷伐木场的工人。卫兵托马斯正在寻找有能力的冒险者，去猎杀那些威胁东部边境的狼...",kw={"东谷伐木场","艾尔文森林","灰林狼","卫兵托马斯","保卫边境","徘徊者","幼年森林熊"},ang={["class:Hunter"]="在艾尔文森林东部潜行的狼和熊，为对抗凶猛的当地野兽提供了追踪和射术的初步考验。",["faction:Alliance"]="确保东部道路的安全有助于维持来自东谷的木材运输，从而支持整个联盟领地的重建和防御工作。"},sec={{t="日益薄弱的防御",b="虽然闪金镇和北郡山谷都有明显的暴风城驻军，但艾尔文森林的最东端却鲜有保护。卫兵托马斯站在横跨河流的桥上守卫，作为文明腹地与危险荒野之间为数不多的哨兵之一。由于王国各地的资源捉襟见肘，孤身守卫的士兵只能依靠过往的志愿者来保持重要补给线的畅通。"},{t="捕食者的威胁",b="东谷伐木场对于向暴风城供应木材至关重要，但在林木线附近砍伐树木使伐木工与当地野生动物直接发生了冲突。徘徊者、灰林狼和幼年森林熊变得越来越具有攻击性，在道路和伐木场附近游荡。减少它们的数量可以暂时缓解当地劳工面临的压力，尽管卫兵托马斯怀疑森林深处某种看不见的骚乱可能正在驱使这些野兽靠近定居点。"}},faq={{q="谁发布了“保卫边境”任务？",a="卫兵托马斯发布了这项任务。他驻守在贯穿艾尔文森林的主干道上的东部桥梁处，守卫着森林内部与东谷地区之间的边界。",al={"保卫边境任务发布者","谁开启保卫边境","卫兵托马斯任务"}},{q="为什么狼和熊会攻击边境？",a="这些具有攻击性的捕食者经常侵入东谷伐木场附近的道路和工作场所。虽然狼和熊天生具有领地意识，但卫兵托马斯指出，周围荒野深处似乎有什么东西正在激怒它们，并驱使它们向文明区域靠近。",al={"为什么熊具有攻击性","为什么狼攻击东谷","艾尔文森林动物攻击"}},{q="东谷伐木场在哪里？",a="东谷伐木场位于艾尔文森林东部，就在卫兵托马斯的桥东面。它为暴风城和边境定居点提供重要的木材。",al={"东谷位置","艾尔文森林伐木场位置","东谷伐木场"}},{q="为什么卫兵托马斯独自看守桥梁？",a="暴风城的常备军和城市卫队在王国各地的力量极其薄弱。河流沿岸和外围路口的哨所通常只有一两名卫兵驻守以监视公路，这使得他们不得不依赖过往的冒险者来处理大规模的野生动物威胁。",al={"为什么卫兵托马斯是单人","卫兵托马斯岗位","暴风城卫兵东谷"}},{q="这项任务需要猎杀哪些动物？",a="你的任务是猎杀八只狼（徘徊者或灰林狼）以及五只在艾尔文森林东部林区游荡的幼年森林熊。",al={"保卫边境任务目标","要杀的狼和熊","保卫边境任务怪物"}},{q="猎杀这些野生动物后会发生什么？",a="向卫兵托马斯汇报可以获得他的感激，并确保伐木车队有更安全的通行环境。然而，他仍然担心，无论是什么黑暗势力激怒了这些野兽，都可能会在森林中引起进一步的麻烦。",al={"保卫边境后续","交还保卫边境任务"}}},fp="20,265,18.376.0,20.371.0,41.142.0,48.194.0,35.150.0,46.217.0,45.128.0,41.196.0"}
P.entries["quest:520"] = {n="意志之冠",s="随着Mug'Thol的副手们被杀，塔伦米尔的梅里萨拉派你去对付Mug'Thol本人。你要带回他的头颅和意志之冠，这样碎颅者的反抗就结束了。",h="随着Mug'Thol的副手们被杀，塔伦米尔的梅里萨拉派你去对付Mug'Thol本人。你要带回他的头颅和意志之冠，这样碎颅者的反抗就结束了。",kw={"奥特兰克","意志之冠","碎颅者","希尔斯布莱德丘陵","梅里萨拉","mug'thol","塔伦米尔"},sec={{t="最后的头颅",b="现在只剩下Mug'Thol了。梅里萨拉认为他不会轻易交出意志之冠，并觉得鉴于他的副手们的下场，他很可能已经在等你到来了。找到他，杀了他，然后带着他的头颅和意志之冠回到塔伦米尔。"},{t="梅里萨拉的回复",b="梅里萨拉对你的工作感到满意。Mug'Thol的头颅将被陈列在奥特兰克废墟的最高峰，而死卫部队将去粉碎碎颅者剩余的残部。"}},faq={{q="是谁派你去杀掉Mug'Thol的？",a="塔伦米尔的梅里萨拉，你也是把头颅带给她的人。",al={"意志之冠任务发布者","谁发布意志之冠任务","梅里萨拉任务"}},{q="梅里萨拉要求从Mug'Thol那里得到什么？",a="他的头颅，以及意志之冠。",al={"mug'thol任务目标","从mug'thol那里得到什么","mug'thol物品"}},{q="为什么梅里萨拉认为Mug'Thol会有所预料？",a="他的副手们已经被杀，所以梅里萨拉怀疑他已经在等你，并且不会轻易交出意志之冠。",al={"为什么mug'thol有准备","mug'thol预料到战斗","mug'thol被警告"}},{q="这属于意志之冠任务线的哪一部分？",a="它位于第三部分之后，即猎杀Mug'Thol副手之后，后面还有第五部分。",al={"意志之冠任务链","意志之冠第4部分之前是什么任务","意志之冠进度"}}},fp="17,189,13.243.0,16.173.1,31.68.0,41.32.0,49.129.0,42.108.0"}
P.entries["quest:521"] = {n="意志之冠",s="只剩下一件事了。意志之冠必须送到幽暗城的沙琳德拉手中，她会确保将其交给希尔瓦娜斯女王。",h="只剩下一件事了。意志之冠必须送到幽暗城的沙琳德拉手中，她会确保将其交给希尔瓦娜斯女王。",kw={"意志之冠","希尔斯布莱德","梅里萨拉","马格托尔","沙琳德拉","希尔瓦娜斯","幽暗城"},sec={{t="前往幽暗城",b="梅里萨拉说，剩下的事就是把意志之冠送到幽暗城的沙琳德拉那里，她会把它转交给希尔瓦娜斯女王。梅里萨拉还警告你不要妄想把它据为己用。她说，马格托尔的下场就是最好的前车之鉴。"},{t="沙琳德拉的反应",b="沙琳德拉认出这就是那个食人魔用来摆脱黑暗女王意志的遗物。沙琳德拉觉得奇怪，如此平庸的东西竟然拥有这种力量，而且最终落到了如此笨拙的手里。沙琳德拉会把它带给希尔瓦娜斯女王，并将你的所作所为告诉她。"}},faq={{q="谁在幽暗城接收意志之冠？",a="幽暗城的沙琳德拉。梅里萨拉说她会确保希尔瓦娜斯女王收到它。",al={"谁获得了意志之冠","我应该把王冠送到哪里","沙琳德拉交任务"}},{q="为什么梅里萨拉警告不要使用这顶王冠？",a="梅里萨拉告诫你不要为了自己的目的使用它，并指出马格托尔的遭遇足以作为警告。",al={"我可以装备这顶王冠吗","为什么不能使用意志之冠","马格托尔命运的警告"}},{q="是谁派你带着王冠去？",a="梅里萨拉，这是意志之冠任务线的第五部分，也是最后一部分，紧接在第四部分之后。",al={"意志之冠最终部分","谁发布了意志之冠5"}}},fp="17,119,16.257.0,21.278.1,48.84.0,47.110.0,29.76.0"}
P.entries["quest:522"] = {n="刺客的契约",s="一位潜行刺客在希尔斯布莱德丘陵携带了一份契约，上面下令要除掉赫尼·马雷布镇长。契约由红蜡封住，上面盖着一枚独特的印戒，你要把它交给南海镇的马雷布镇长。",h="一位潜行刺客在希尔斯布莱德丘陵携带了一份契约，上面下令要除掉赫尼·马雷布镇长。契约由红蜡封住，上面盖着一枚独特的印戒，你要把它交给南海镇的马雷布镇长。",kw={"刺客契约","希尔斯布莱德丘陵","赫尼·马雷布镇长","潜行刺客","印戒","南海镇","辛迪加"},sec={{t="被标记的镇长",b="这张纸条上下令要除掉赫尼·马雷布镇长。契约由红蜡封住，上面盖着一枚独特的印戒。一位潜行刺客在希尔斯布莱德丘陵携带了它，你应该把它出示给南海镇的马雷布。"},{t="马雷布的裁决",b="马雷布查看了契约，并表示这就是近期袭击南海镇的原因。马雷布确信辛迪加想要他的命，就像他们曾经想要上一任镇长的命一样。"}},faq={{q="契约上写了什么？",a="上面下令要除掉赫尼·马雷布镇长，并用红蜡封住，还盖有一枚独特的印戒。",al={"契约上写了什么","刺客契约详情","目标是谁"}},{q="这份契约来自哪里？",a="它是由希尔斯布莱德丘陵的一位潜行刺客所携带的。",al={"谁掉落了契约","在哪里寻找契约","潜行刺客掉落"}},{q="这份契约应该交给谁？",a="交给南海镇的赫尼·马雷布镇长，他就是契约上标明要被处决的目标。",al={"我应该把契约给谁","在哪里上交刺客契约","马雷布的位置"}}},fp="19,217,19.228.0,15.193.1,32.110.0,35.59.0,41.85.0"}
P.entries["quest:523"] = {n="男爵之死",s="你回收的契约上签着巴隆·瓦杜斯的名字，他是一位来自旧奥特兰克王国的贵族。南海镇的赫尼·马雷布镇长想要找到他并将他绳之以法，并要求取得这个男爵的首级。",h="你回收的契约上签着巴隆·瓦杜斯的名字，他是一位来自旧奥特兰克王国的贵族。南海镇的赫尼·马雷布镇长想要找到他并将他绳之以法，并要求取得这个男爵的首级。",kw={"奥特兰克山脉","巴隆·瓦杜斯","巴隆之死","赫尼·马雷布镇长","南海镇","斯坦恩布莱德","辛迪加"},sec={{t="契约的代价",b="在完成“刺客契约”后，赫尼·马雷布镇长告诉你，巴隆·瓦杜斯在契约上签了字。瓦杜斯是旧奥特兰克王国的一位贵族，此人冷酷无情、手段残暴，马雷布并不惊讶竟然是他幕后指使。南海镇绝不会坐视男爵派暴徒来袭击城镇而不予以还击。马雷布要求你在辛迪加的巢穴中找到他，也许是在斯坦恩布莱德的废墟中，或者是废墟北面的山谷里，并要你带回这个男爵的首级。"},{t="马雷布的宽慰",b="当你带回男爵的首级时，马雷布向你表示感谢，并说得知这个恶棍也丢了性命，让他这位镇长能稍微安心一些。"}},faq={{q="巴隆·瓦杜斯是谁？",a="他是一位来自旧奥特兰克王国的贵族，冷酷无情、手段残暴。那份意图谋杀马雷布的契约上签的就是他的名字。",al={"巴隆·瓦杜斯背景故事","瓦杜斯是谁","瓦杜斯 奥特兰克"}},{q="为什么马雷布镇长想要巴隆·瓦杜斯死？",a="瓦杜斯在你回收的契约上签了字，马雷布绝不会让他派暴徒袭击南海镇而不付出代价。",al={"为什么要杀死巴隆·瓦杜斯","马雷布 瓦杜斯","巴隆之死的理由"}},{q="在哪里可以找到巴隆·瓦杜斯？",a="马雷布认为瓦杜斯应该就在辛迪加的巢穴某处，也许是在斯坦恩布莱德的废墟中，或者是废墟北面的山谷里。",al={"巴隆·瓦杜斯位置","瓦杜斯在哪里","斯坦恩布莱德 瓦杜斯"}},{q="这个任务的前置是什么？",a="它紧随“刺客契约”之后，也就是你回收的那个签有男爵名字的契约。",al={"巴隆之死前置任务","巴隆之死前的任务线","刺客契约前置条件"}}},fp="14,210,22.484.0,14.142.1,20.135.0,49.133.0,32.121.0,23.92.0"}
P.entries["quest:524"] = {n="苦楚药剂",s="苦痛药剂是药剂师林度恩在塔伦米尔进行邪恶酿造实验的结晶。受皇家药剂师协会的指派，林度恩试图测试一种伪装成被窃矮人麦酒的致命毒药，而受害者正是被囚禁在定居点内的那些人类俘虏。",h="苦痛药剂是药剂师林度恩在塔伦米尔进行邪恶酿造实验的结晶。受皇家药剂师协会的指派，林度恩试图测试一种伪装成被窃矮人麦酒的致命毒药，而受害者正是被囚禁在定居点内的那些人类俘虏。",kw={"药剂师林度恩","被俘农民","丹加洛克","苦痛药剂","高级执行官达萨利亚","希尔斯布莱德","被污染的酒桶","塔伦米尔"},ang={["faction:Horde"]="这场残酷的实验展示了被遗忘者行动中更黑暗、更赤裸的一面，同时也考验了协助塔伦米尔的其他部落种族的道德底线。",["race:Human"]="对无助的洛丹伦农民的屠杀，突显了被遗忘者在对待他们曾经的生者同胞时那冷酷、算计的残忍。",["race:Undead"]="对于被遗忘者而言，完善皇家药剂师协会的毒药对生存至关重要，这能确保通过任何必要手段将希尔斯布莱德丘陵从人类的复苏中隔离出来。"},sec={{t="致命佳酿",b="在整个希尔斯布莱德丘陵，药剂师林度恩四处搜集污秽的原料以及从丹加洛克山中要塞偷来的矮人麦酒。他的目的既单一又冷酷：受皇家药剂师协会的委托，调配一种名为苦痛药剂的剧毒新药。一旦混合完毕，这瓶黑暗的混合物就会被装入一个看似无害的山地黑啤酒桶中，等待着展现其效力。"},{t="不幸的客人们",b="塔伦米尔的死亡卫兵最近抓捕了当地的人类农夫，最初他们怀疑有一位狡猾的暴风城军事战略家混迹其中。当得知该战略家已死于瘟疫之地后，高级执行官达萨利亚认为幸存的农民对军事调查已毫无价值。她没有将他们释放，而是将其交给林度恩，作为他化学实验的小白鼠。"},{t="测试药剂",b="被搬到楼上的拘留室后，那个被污染的酒桶被放在了干渴的俘虏面前的地毯上。农夫们口干舌燥，且完全不知道林度恩的残忍行径，他们急切地冲向木桶想要畅饮。毒药的作用速度快得惊人：在喝下这杯矮人麦酒仅仅片刻之后，这些不幸的俘虏便倒地身亡，证明了这种药剂那摧枯拉朽般的致死性。"}},faq={{q="为什么这些人类农夫会被俘虏？",a="死亡卫兵拘留他们是因为怀疑有一位来自暴风城的军事战略家潜伏在他们的社区中。一旦得知战略家死在瘟疫之地，这些俘虏对高级执行官达萨利亚来说就失去了情报价值。",al={"为何使用囚犯","为何囚禁农民","塔伦米尔囚犯"}},{q="药剂师林度恩是谁？",a="药剂师林度恩是驻扎在塔伦米尔的被遗忘者皇家药剂师协会的一员。他负责开发和测试旨在消灭生者的致命瘟疫和毒药，并经常利用被俘的当地人作为活体实验对象。",al={"药剂师林度恩背景故事","林度恩是谁","林度恩 塔伦米尔"}},{q="桶里的麦酒从哪儿来的？",a="这桶麦酒是直接从希尔斯布莱德丘陵南部的坚固山中要塞——丹加洛克——的矮人们那里偷来的。林度恩用他恶臭的试剂污染了这桶偷来的麦酒，好让这致命的毒药看起来像是普通的矮人佳酿。",al={"麦酒来源","丹加洛克麦酒","酒桶起源"}},{q="当你送去那个被污染的酒桶后会发生什么？",a="林度恩要求你把被污染的酒桶放在囚室的地毯上，以便进行他的实验。",al={"农民遭遇了什么","农民饮用酒桶","瘟疫酿造结果"}},{q="谁授权将囚犯作为测试对象的？",a="塔伦米尔被遗忘者部队的指挥官高级执行官达萨利亚，在这些囚犯对她来说已无军事价值后，将他们交给了药剂师林度恩。",al={"谁允许林度恩测试农民","达萨利亚的角色","达萨利亚 囚犯"}},{q="皇家药剂师协会在这里试图达成什么目标？",a="皇家药剂师协会致力于制造一种能够消灭天灾军团和生者的致命瘟疫。像苦痛药剂这样的实地实验，旨在测试新的化学药剂投送方式，并确定对人类生物的毒性水平。",al={"药剂师在希尔斯布莱德的目标","为何制造苦痛药剂","被遗忘者瘟疫测试"}}},fx={["34bdf792"]={q="为什么药剂师林度恩想毒害囚犯？",a="药剂师林度恩需要活着的人类来验证他新近制成的苦痛精华药剂的致命效力。皇家药剂师协会一直致力于改良致命瘟疫和毒剂，以消灭人类和天灾军团。如今，高级执行官达萨利亚已不再需要那些被俘农民接受审讯，林度恩便把他们视为方便且可牺牲的试验对象，用来确认药剂效果符合预期，然后再报告成功。",al={"为什么要毒害农民","林度恩的动机","为什么要测试苦痛精华药剂","林度恩为什么想让你做这件事"}}},fp="15,256,16.414.0,18.438.1,16.389.1,55.267.0,24.226.0,43.236.0,46.91.1,52.168.0,60.255.0"}
P.entries["quest:525"] = {n="更大的谜团",s="勘察员塔伯斯·雷矛已经破译了你在奥特兰克山脉的窃贼身上找到的那封信，但他却无法理解信中的内容。他让你把它交给南海镇的镇长。",h="勘察员塔伯斯·雷矛已经破译了你在奥特兰克山脉的窃贼身上找到的那封信，但他却无法理解信中的内容。他让你把它交给南海镇的镇长。",kw={"奥特兰克","破译后的信件","更多谜团","赫尼·马雷布镇长","勘察员塔伯斯·雷矛","南海镇","辛迪加"},sec={{t="毫无意义的信",b="在交给勘察员塔伯斯·雷矛那封信之后，他说他已经破译了信的内容，但无法理解其中的含义。他觉得你在奥特兰克山脉的窃贼身上得到这封信非常奇怪。这封信写得很隐晦，但南海镇距离奥特兰克最近，如果那里正在酝酿什么威胁，那里的镇长应该知道。你需要把破译后的信带给赫尼·马雷布镇长。"},{t="马雷布的解读",b="马雷布仔细研究了这封信，断定没有任何窃贼或奥特兰克贵族能写出这样的信。在马雷布看来，这指向了辛迪加背后的某种黑暗力量，想到这种力量可能是谁，马雷布不寒而栗。"}},faq={{q="是谁让你带着破译后的信出发的？",a="是勘察员塔伯斯·雷矛，他在破译了信件但无法理解其含义后，让你把它带给南海镇的镇长。",al={"谁发布更多谜团任务","更多谜团任务发布者","更多谜团任务起始地点"}},{q="谁需要看这封破译后的信？",a="南海镇的赫尼·马雷布镇长。塔伯斯·雷矛指出南海镇距离奥特兰克最近，因此如果有什么威胁正在酝酿，镇长应该知晓。",al={"谁接收破译后的信","更多谜团任务交付对象","我该把信带到哪里"}},{q="最初那封加密的信是从哪里来的？",a="你在交给勘察员塔伯斯·雷矛之前，是在奥特兰克山脉的窃贼身上找到它的。",al={"破译后的信件来源","在哪里找到信件","谁持有信件"}}},fp="17,181,24.385.0,16.206.1,40.121.0,38.154.0,50.91.0"}
P.entries["quest:5261"] = {n="伊根·派特斯金纳",s="这项简短的入门任务指引新抵达北郡山谷的士兵与Eagan Peltskinner交谈，他是一位驻扎在北郡修道院外的当地毛皮商。由于山谷边缘的掠食者数量不断增加，Eagan需要有能力的冒险者去猎杀森林狼并收集毛皮。",h="这项简短的入门任务指引新抵达北郡山谷的士兵与Eagan Peltskinner交谈，他是一位驻扎在北郡修道院外的当地毛皮商。由于山谷边缘的掠食者数量不断增加，Eagan需要有能力的冒险者去猎杀森林狼并收集毛皮。",kw={"维里副队长","eagan peltskinner","北郡修道院","北郡山谷","森林狼","边境的狼"},ang={["faction:Alliance"]="北郡的每一项小任务都有助于保卫暴风城的领土，而此时王国的核心军队仍在其他地方疲于奔命。",["race:Human"]="对于从北郡修道院走出来的年轻人类来说，帮助像Eagan这样的当地工匠是他们保卫家园的第一课。"},sec={{t="与毛皮商交谈",b="北郡山谷看起来或许宁静祥和，但其宁静的果园和农田却被野外森林所包围，那里到处都是森林狼。维里副队长经常指引修道院外的新兵去找Eagan Peltskinner，他就在附近的修道院庭院里工作。Eagan渴望让新人参与进来，削减那些具有攻击性的狼群数量，同时为他的手艺收集珍贵的毛皮。"},{t="边界的麻烦",b="北郡周边狼群数量的激增不仅仅是个麻烦，它还威胁着工人们、修道院的学徒以及进出山谷的补给线。指引年轻的勇士去找Eagan对暴风城的治安官来说有双重目的：既能保障附近道路的安全，又不会占用卫戍部队为数不多的守卫，他们已经在艾尔文森林各地面临着日益紧张的局势。"}},faq={{q="是谁让你去和Eagan Peltskinner交谈的？",a="维里副队长，驻扎在北郡修道院入口外，在向有前途的新兵介绍山谷的安全隐患后，会指引他们去找Eagan交谈。",al={"谁发布此任务","谁开启eagan peltskinner任务"}},{q="Eagan Peltskinner在哪里？",a="Eagan Peltskinner站在北郡修道院的外墙附近，位于主建筑左侧，周围有他的晾皮架和装备。",al={"eagan在哪里","eagan peltskinner位置","找到eagan"}},{q="Eagan Peltskinner需要什么帮助？",a="Eagan正在寻找愿意猎杀在周边森林中徘徊的凶猛森林狼，并带回它们的毛皮的冒险者，这有助于清理北郡的周边地区。",al={"eagan想要什么","为什么要猎杀狼","eagan的目的"}},{q="你可以直接跳过这个任务去和Eagan交谈吗？",a="可以。Eagan会直接向任何靠近他的人提供狩猎任务。先完成这个引导任务只是为了获得维里副队长的正式介绍。",al={"我可以跳过eagan任务吗","直接去处理边境的狼"}},{q="为什么北郡山谷里有这么多狼？",a="北郡山谷毗邻茂密且未开发的林地，那里是森林狼自由游荡的地方。由于当地卫兵人手紧张，且正忙于应付王国各地的其他威胁，野生掠食者的数量已经不受控制地增长。",al={"为什么北郡有狼","艾尔文森林的狼患"}},{q="和Eagan Peltskinner交谈后会有什么任务？",a="和Eagan交谈后，他会立即提出请求，要求去修道院庭院边界外猎杀森林狼并收集它们坚韧的毛皮。",al={"eagan之后的下一个任务","eagan接下来提供什么"}}},fp="17,175,23.281.0,24.264.0,46.137.0,35.136.0,43.143.0,51.149.0,50.185.0,50.117.0"}
P.entries["quest:527"] = {n="希尔斯布莱德之战",s="“希尔斯布莱德之战”是亡灵族为了铲除希尔斯布莱德人类定居点而发起的首次攻势。这项任务由瓦里玛萨斯下令，并由高级执行官达萨利亚传达，旨在针对希尔斯布莱德农场北部的农夫和基础设施，以切断该镇的粮食供应。",h="“希尔斯布莱德之战”是亡灵族为了铲除希尔斯布莱德人类定居点而发起的首次攻势。这项任务由瓦里玛萨斯下令，并由高级执行官达萨利亚传达，旨在针对希尔斯布莱德农场北部的农夫和基础设施，以切断该镇的粮食供应。",kw={"希尔斯布莱德之战","达萨利亚","盖兹农夫","雷农夫","希尔斯布莱德农场","the new plague","塔伦米尔","瓦里玛萨斯"},ang={["faction:Alliance"]="对北部家园居民的屠杀，展示了洛丹伦残存的人类聚集地所面临的可怕现实。",["faction:Horde"]="虽然萨尔倡导荣耀，但从塔伦米尔发起的北部战役揭示了 Sylvanas Windrunner 对联盟战争中毫不妥协的残暴。",["race:Undead"]="对于亡灵来说，收复洛丹伦意味着消灭每一个幸存的生者聚集点，因为他们将这片家园视为被窃取的土地。"},sec={{t="饿死抵抗者",b="塔伦米尔是亡灵帝国南下的先锋堡垒，面对着盘踞在希尔斯布莱德丘陵的人类居民。高级执行官达萨利亚奉命行事，直接听命于幽暗城的瓦里玛萨斯。她的策略是进行全面消耗：在直接向重兵防守的希尔斯布莱德镇进军之前，她下令系统性地破坏其农业。打击北部农场不仅剥夺了人类民兵的关键补给，还在他们的家园中播下了混乱的种子。"},{t="延缓行动",b="针对希尔斯布莱德人类势力的更大规模战役有着残酷的战术目的。当亡灵军队牵制并消耗当地守军时，皇家药剂师学会正在夜以继日地研制一种名为 The New Plague 的瘟疫，这种瘟疫能够将生者和天灾军团一并抹除。高级执行官达萨利亚认为这些早期的遭遇战，以及像雷农夫和盖兹农夫这样的当地地主的死亡，都是在终极武器准备就绪前抑制人类滋扰的必要步骤。"}},faq={{q="为什么亡灵要攻击普通的农夫？",a="希尔斯布莱德农场的人类农夫和帮工是希尔斯布莱德镇的后勤基石。通过摧毁他们的劳动力并杀死雷农夫和盖兹农夫这样的知名地主，亡灵切断了人类驻军的粮食供应，并在正面进攻前削弱了他们的防御。",al={"为什么要杀农夫","希尔斯布莱德农场目标","为什么要攻击农场"}},{q="谁下达了这次攻击的命令？",a="驻扎在塔伦米尔的亡灵军事指挥官高级执行官达萨利亚下达了这项任务。她直接听命于恐惧魔王瓦里玛萨斯和 Sylvanas Windrunner 女士。",al={"谁发布任务","达萨利亚的命令","谁是达萨利亚"}},{q="皇家药剂师学会在这次战役中扮演什么角色？",a="达萨利亚指出，针对人类的常规战争旨在平定当地生者人口，并为亡灵药剂师研制能够彻底消灭敌人的 The New Plague 争取时间。",al={"the new plague 的目的","希尔斯布莱德的药剂师","亡灵瘟疫计划"}},{q="雷农夫和盖兹农夫在哪里？",a="这两位地主都负责监管希尔斯布莱德农场的北部区域。雷农夫通常在大型农舍附近，或在农舍东侧的花园里劳作，而盖兹农夫则经常出没于谷仓、副房或周围的耕地中。",al={"寻找雷农夫","寻找盖兹农夫","雷农夫和盖兹农夫的位置"}},{q="完成这次突袭后会发生什么？",a="带着胜利的消息回到达萨利亚身边，将推动对南部农场和希尔斯布莱德镇本身的进攻，同时还会开启诸如在“死亡纪念品”中收集残酷战利品之类的支线任务。",al={"希尔斯布莱德之战后续","what comes next","任务链进度"}},{q="为什么达萨利亚威胁她的士兵？",a="高级执行官达萨利亚要求绝对的纪律和冷酷。她认为在对联盟的战争中表现出任何犹豫或轻率都视为叛国，并将立即处决。",al={"达萨利亚的对话","达萨利亚的斩首威胁"}}},fx={a66392fb={q="你要在希尔斯布莱德农场对付谁？",a="你将奉命袭击在希尔斯布莱德农场北部田地劳作的人类农民和农场工人，特别是地主农夫雷和农夫盖兹。这些居民构成了该地区农业生产的支柱，他们种植作物、饲养牲畜，为附近的人类聚居地希尔斯布莱德和驻守当地的联盟部队提供给养。",al={"希尔斯布莱德之战的目标","我们要在希尔斯布莱德袭击谁","农夫雷和农夫盖兹是谁"}}},fp="19,302,23.523.0,17.505.0,46.318.0,23.197.0,61.208.0,45.258.0,40.201.0,41.198.0"}
P.entries["quest:528"] = {n="希尔斯布莱德之战",s="希尔斯布莱德之战是一场由塔伦米尔的高级执行官达萨利亚指挥的被遗忘者军事任务。在对北部的那些人类农场发动了初步打击后，部落特工被派遣至南方，屠杀那些在果园中寻求庇护的希尔斯布莱德农夫。",h="希尔斯布莱德之战是一场由塔伦米尔的高级执行官达萨利亚指挥的被遗忘者军事任务。在对北部的那些人类农场发动了初步打击后，部落特工被派遣至南方，屠杀那些在果园中寻求庇护的希尔斯布莱德农夫。",kw={"希尔斯布莱德之战","黑暗女王","达萨利亚","死亡猎手","被遗忘者","希尔斯布莱德农场","希尔斯布莱德农夫","塔伦米尔"},ang={["faction:Alliance"]="在南部果园中屠杀手无寸铁的难民，凸显了被遗忘者针对洛丹伦剩余生者所发动的冷酷且全面的战争。",["faction:Horde"]="塔伦米尔是部落在丘陵地区的关键堡垒。攻克希尔斯布莱德可以确保部落的通讯和补给线在面对联盟入侵时保持安全。",["race:Undead"]="对于被遗忘者来说，这场清洗是务实且不妥协的：消灭活着的劳动者剥夺了联盟的补给，并巩固了黑暗女王对洛丹伦南部的统治。"},sec={{t="在农场中播撒恐惧",b="针对希尔斯布莱德丘陵人类势力的战役正在冷酷地推进。在部落军队袭击了北部的农场后，恐慌席卷了整个定居点。许多劳动者并没有拿起武器，而是逃往南方，躲进希尔斯布莱德农场的果园和牧场中，希望能从步步紧逼的亡灵手中逃脱。高级执行官达萨利亚看待他们的恐惧时，不仅没有丝毫怜悯，反而将其视为彻底瓦解希尔斯布莱德剩余劳动力和士气的战略良机。"},{t="黑暗女王的进军",b="在塔伦米尔的直接命令下，部落的勇士们在田野中追捕这些流离失所的劳动者。失去保护的农夫被系统地清除，以切断希尔斯布莱德的食物供应并粉碎平民的抵抗意志。对于达萨利亚和被遗忘者来说，每杀死一个人，死亡的魔爪就向幸存的城镇紧缩一分，从而确保洛丹伦牢牢掌握在被遗忘者手中。"}},faq={{q="为什么被遗忘者要以平民为目标？",a="以农夫为目标可以摧毁希尔斯布莱德定居点的农业根基。通过杀掉躲在南部果园里的劳动者，高级执行官达萨利亚确保了城镇进一步陷入恐慌并遭受饥荒，这使得最终的征服变得容易得多。",al={"为什么要杀农夫","为什么要针对农场主","达萨利亚的农夫计划"}},{q="是谁下达了这次袭击的命令？",a="驻扎在塔伦米尔的被遗忘者指挥官高级执行官达萨利亚，以希尔瓦娜斯·风行者女士的名义指挥着针对当地人类定居点的整个军事行动。",al={"谁发布了希尔斯布莱德之战2","希尔斯布莱德之战任务发布者","达萨利亚的命令"}},{q="这些农夫是从哪里逃出来的？",a="他们在遭受早期的部落打击后，从希尔斯布莱德北部的农场逃了出来。他们惊慌失措且毫无防备，躲藏在南部希尔斯布莱德农场的树林和牧场中。",al={"农夫从哪来","希尔斯布莱德北部农场"}},{q="在哪里可以找到那些逃亡的农夫？",a="这些农夫散布在希尔斯布莱德农场的南部果园和牧场中，就在穿过丘陵的主干道南侧。",al={"希尔斯布莱德农夫位置","希尔斯布莱德农夫在哪里"}},{q="杀死农夫之后要做什么？",a="在清除了南部田野中的劳动者后，高级执行官达萨利亚升级了战役，目标转向了Blacksmith Verringtan和武装希尔斯布莱德防御者的铁匠铺，将战火进一步推向城镇中心。",al={"杀完农夫后做什么","希尔斯布莱德之战下一步"}},{q="为什么部落在这里战斗得如此冷酷？",a="希尔斯布莱德的人类城镇是洛丹伦境内最后一批联盟据点之一。被遗忘者将该地区视为他们合法的领土，并寻求驱逐或消灭任何威胁其南部边界的联盟飞地。",al={"为什么部落要攻击希尔斯布莱德","被遗忘者与希尔斯布莱德的战争"}}},fx={cca64c76={q="希尔斯布莱德的农民是谁？",a="他们是希尔斯布莱德的平民，在北部农场遭到最初袭击后逃离了那里。被逼近的被遗忘者吓坏后，他们四散逃往希尔斯布莱德农场南部的果园，希望躲过屠杀，但达萨利亚的斥候很快就发现了他们的藏身之处。",al={"希尔斯布莱德农民","农民是谁","果园里的农民"}}},fp="19,271,27.478.0,23.422.0,47.266.0,24.186.0,35.185.0,40.148.0,38.220.1,45.259.0"}
P.entries["quest:529"] = {n="希尔斯布莱德之战",s="这场行动是被遗忘者征服希尔斯布莱德丘陵战役中的关键阶段。高级执行官达萨利亚下令摧毁希尔斯布莱德农场的当地铁匠铺，以切断那些顽固人类平民的武器来源。",h="这场行动是被遗忘者征服希尔斯布莱德丘陵战役中的关键阶段。高级执行官达萨利亚下令摧毁希尔斯布莱德农场的当地铁匠铺，以切断那些顽固人类平民的武器来源。",kw={"铁匠学徒","希尔斯布莱德战役","达萨利亚","希尔斯布莱德农场","一箱铁材","塔伦米尔","维林坦"},ang={["faction:Alliance"]="屠杀维林坦并窃取定居点的铁材，剥夺了南海镇外围农场唯一的自卫手段。",["profession:Blacksmithing"]="维林坦的熔炉是当地抵抗力量的核心，事实证明，对于一支入侵的军队来说，铁砧可能和步兵团一样危险。",["race:Undead"]="对于被遗忘者来说，摧毁人类的铁匠铺是确保洛丹伦南部边界安全以及为他们自身艰难的战争努力储备金属的务实一步。"},sec={{t="击碎铁砧",b="被遗忘者在推进穿越希尔斯布莱德丘陵时，遭遇的抵抗比高级执行官达萨利亚预期的更为激烈。当地的人类并没有轻易溃散或向死亡猎手以及从塔伦米尔派出的士兵投降。调查显示，当地的农民并不是在使用普通的草叉和镰刀进行战斗；他们正在农场里积极地武装自己，准备开战。"},{t="切断补给线",b="在希尔斯布莱德农场的西南边缘，铁匠维林坦和他的学徒们在熔炉旁不知疲倦地工作着，将矿石锻造成民兵使用的刀剑和盔甲。通过派遣特工除掉维林坦，屠杀他的学徒，并夺取他们储备的一箱铁材，达萨利亚旨在削弱该定居点的防御力量，同时将这些金属用于最终对南海镇的突袭。"}},faq={{q="为什么高级执行官达萨利亚专门针对铁匠？",a="当地的人类镇民和农民正在对被遗忘者的推进进行出乎意料的军事抵抗。达萨利亚发现铁匠维林坦和他的学徒们正在为民兵积极锻造武器，将普通的农民变成了武装威胁。",al={"为什么要杀维林坦","铁匠任务目标","维林坦任务"}},{q="铁匠铺在哪里？",a="铁匠铺位于希尔斯布莱德农场的西南侧，周围有正在工作的学徒、守卫和当地巡逻队。",al={"维林坦位置","铁匠在哪里","希尔斯布莱德铁匠铺"}},{q="那一箱铁材是用来做什么的？",a="达萨利亚没收了这些铁材来供养被遗忘者的战争机器。她打算利用这些缴获的原材料为计划中针对联盟港口城镇南海镇的突袭锻造武器和补给。",al={"铁材发生了什么","一箱铁材背景故事"}},{q="这如何融入更宏大的希尔斯布莱德战役？",a="这标志着达萨利亚系统性瓦解丘陵地区人类势力的第三阶段，从屠杀乡村劳工和农民转变为剥离他们的领导层、后勤和生产能力。",al={"希尔斯布莱德战役任务链","达萨利亚战役"}},{q="希尔斯布莱德农场的人属于联盟军队吗？",a="虽然在文化上与南海镇和联盟保持一致，但农场的居民主要是当地的农民、劳工和镇民，他们组成了临时的民兵队伍来保卫家园，抵御被遗忘者。",al={"希尔斯布莱德农民是联盟吗","希尔斯布莱德民兵"}},{q="谁下达了这次袭击的命令？",a="高级执行官达萨利亚，她是负责监督被遗忘者在塔伦米尔据点行动的军事指挥官。",al={"任务发布者","达萨利亚是谁"}}},fx={c3d79e95={q="铁匠Verringtan是谁？",a="铁匠Verringtan是当地的金属匠，驻扎在希尔斯布莱德农场西南边缘的铁匠铺。他和学徒们一起为当地的人类居民制造武器和工具，助长了他们对抗被遗忘者进犯丘陵的激烈抵抗。",al={"verringtan是谁","铁匠verringtan","希尔斯布莱德铁匠"}}},fp="19,249,18.390.0,24.422.0,68.262.0,28.129.0,38.214.0,64.233.0,65.211.0,23.123.0"}
P.entries["quest:530"] = {n="丈夫的复仇",s="“丈夫的复仇”是这一段悲剧故事的终章，讲述了往日的背叛如何延续到了亡灵的诅咒之中。拉林夫·安迪恩是一位居住在幽暗城的被遗忘者，他委托旅行者去搜寻他曾经的朋友瓦德雷·莫雷，此人在生前杀害了他的妻子。",h="“丈夫的复仇”是这一段悲剧故事的终章，讲述了往日的背叛如何延续到了亡灵的诅咒之中。拉林夫·安迪恩是一位居住在幽暗城的被遗忘者，他委托旅行者去搜寻他曾经的朋友瓦德雷·莫雷，此人在生前杀害了他的妻子。",kw={"黛莉亚","刻字的戒指","格雷迈恩之墙","拉林夫·安迪恩","蔑视之戒","银松森林","幽暗城","瓦德雷·莫雷"},ang={["faction:Horde"]="在银松森林执行正义有助于巩固幽暗城周围的边界，抵御残留的人类不法之徒。",["race:Undead"]="拉林夫对亡妻的冷漠疏离，以及他对仇恨和复仇的执念，鲜明地描绘出了亡灵的诅咒是如何扭曲凡人心理的。"},sec={{t="苦涩的回忆",b="当拉林夫·安迪恩收到那枚从银松森林带回的刻字戒指时，那尘封的往事再次被唤醒。亡灵的诅咒虽然让他大半生的人性消逝，但那些记忆却如鲠在喉。在这些记忆中，最令他刻骨铭心的背叛是：他最亲密的朋友，瓦德雷·莫雷，竟杀害了他的妻子黛莉亚。虽然天灾军团的严寒和随后成为被遗忘者的经历磨灭了拉林夫感受悲伤与爱的能力，但他对复仇的渴望却丝毫未减。"},{t="格雷迈恩之墙的正义",b="为了逃避往日罪行的代价以及洛丹伦的恐怖，瓦德雷·莫雷一路向南逃往银松森林，试图躲进格雷迈恩之墙后方那个奉行孤立主义的人类王国。然而，那巨大的城门紧闭，拒绝接纳任何难民和流亡者。瓦德雷被困在石墙之下，最终死在了他曾背叛过的朋友手中，他的双手被砍下，送回了幽暗城。"},{t="冰冷的纪念品",b="在收到昔日好友的双手的时刻，拉林夫心中没有感受到一丝温暖或救赎，只有冰冷的终结。既然已大仇得报，他便冷漠地交出了黛莉亚的婚戒，声称那只是个无用的玩物。取而代之的，是瓦德雷·莫雷那双被砍下的手，它们留在幽暗城中，成为了拉林夫心中关于凡世背叛的残酷永恒纪念。"}},faq={{q="为什么拉林夫一定要瓦德雷的手？",a="拉林夫索要瓦德雷的双手，因为正是这两只手亲手终结了他妻子的生命。他打算将它们留在幽暗城中，作为朋友背叛自己的一种永久战利品和提醒。",al={"为什么要手","瓦德雷的手","拉林夫要手"}},{q="瓦德雷·莫雷躲在哪里？",a="瓦德雷·莫雷位于银松森林的最南端，他露宿在巨大的格雷迈恩之墙下，因为无法进入封闭的吉尔尼斯王国而困在那里。",al={"瓦德雷在哪里","瓦德雷的位置","瓦德雷·莫雷的地点"}},{q="为什么拉林夫把结婚戒指还了回来？",a="在成为亡灵后，拉林夫对黛莉亚的情感依恋已经荡然无存。由于失去了感受悲伤或爱慕的能力，这枚戒指对他而言只是一件空洞的饰品；唯有复仇的恶意才具有真正的价值。",al={"为什么交出戒指","蔑视之戒背景故事","为什么丢弃戒指"}},{q="瓦德雷·莫雷能进入吉尔尼斯吗？",a="不能。吉恩·格雷迈恩国王在第二次战争后筑起了格雷迈恩之墙，将吉尔尼斯与外界隔绝，城门至今依然紧闭。瓦德雷就像许多绝望的难民一样，最终被困在了紧闭的大门外。",al={"格雷迈恩之墙封闭","为什么瓦德雷在墙外"}},{q="哪些任务会引出这个任务？",a="这条任务线始于银松森林的“刻字的戒指”，该任务会引导你去往幽暗城完成“拉林夫与幽暗城”，进而解锁“丈夫的复仇”。",al={"丈夫的复仇任务线","前置任务","上一个任务"}}},fx={f744ed49={q="拉林夫·安迪恩为什么想要复仇？",a="Valdred Moray曾是拉林夫的密友，却杀害了拉林夫的妻子Deliah。亡灵的冰冷力量剥夺了拉林夫哀悼和悲伤的能力，但他心中复仇的烈焰依然熊熊燃烧。为她报仇并惩罚背叛他的旧友，是他如今仅存的愿望。",al={"拉林夫为什么想杀死valdred","拉林夫·安迪恩的动机","为什么杀死valdred moray"}},["71a98bea"]={q="Valdred Moray是谁？他为什么在格雷迈恩之墙？",a="Valdred Moray是拉林夫·安迪恩的旧友，曾杀害拉林夫的妻子Deliah。犯下罪行后，他向南逃进银松森林，躲在格雷迈恩之墙封闭的大门旁，急切地想逃进吉尔尼斯这个闭关锁国的王国，以免过去的罪行追上他。",al={"valdred moray是谁","valdred moray为什么在银松森林","valdred moray与格雷迈恩之墙"}}},fp="19,249,15.439.0,19.433.1,14.357.1,51.203.0,30.166.0,44.212.1,32.209.0,33.163.0"}
P.entries["quest:532"] = {n="希尔斯布莱德之战",s="这场针对南海镇周边属地的被遗忘者战役的关键阶段，目标直指希尔斯布莱德镇的市政领导层。在塔伦米尔的高级执行官达萨利亚的指挥下，部落军队将矛头对准了伯恩赛德镇长、他的议会以及他们的行政档案，旨在彻底粉碎人类在山麓丘陵地区的统治。",h="这场针对南海镇周边属地的被遗忘者战役的关键阶段，目标直指希尔斯布莱德镇的市政领导层。在塔伦米尔的高级执行官达萨利亚的指挥下，部落军队将矛头对准了伯恩赛德镇长、他的议会以及他们的行政档案，旨在彻底粉碎人类在山麓丘陵地区的统...",kw={"希尔斯布莱德之战","达萨利亚","希尔斯布莱德议员","希尔斯布莱德公告","希尔斯布莱德城镇文档","伯恩赛德镇长","塔伦米尔","市政厅"},ang={["faction:Alliance"]="伯恩赛德镇长的屠杀和城镇宪章的焚毁，标志着希尔斯布莱德最后一个合法地方政府的灾难性倒台。",["faction:Horde"]="对市政厅的打击削弱了联盟协调当地民兵的能力，从而牢牢稳固了塔伦米尔南部边境，抵御人类的反攻。",["race:Undead"]="对于被遗忘者来说，根除希尔斯布莱德的人类治理既是战略扩张，也是对那些质疑洛丹伦边界的生者进行的无情报复。"},sec={{t="斩首镇议会",b="即使在田野和巡逻队遭受重创后，希尔斯布莱德的人类守军依然紧紧抓住残存的民政权力不放。高级执行官达萨利亚意识到，普通的平民和民兵都是依靠他们的市政领导人来集结的。为了确保该镇彻底崩溃，被遗忘者的特工被直接派遣至市政厅，以处决伯恩赛德镇长和他的五名议员，从而切断他们的指挥链。"},{t="抹除市政记录",b="除了肉体上的刺杀，达萨利亚还寻求从心理和行政上彻底瓦解希尔斯布莱德。特工们必须烧毁“希尔斯布莱德公告”，这是一份象征着定居点宪章和骄傲的受人尊敬的政治文件。在销毁它的同时，还要夺取城镇登记册，这不仅剥夺了幸存的联盟忠诚者们的官方记录和公民登记册，还为幽暗城的情报机构提供了有关当地民众的详细内幕。"}},faq={{q="谁下达了这次打击命令？",a="驻扎在塔伦米尔的被遗忘者指挥官高级执行官达萨利亚策划了这次袭击，作为她将联盟定居点从山麓丘陵地区抹去的大规模战役的一部分。",al={"谁发布了这个任务","希尔斯布莱德之战任务发布者","达萨利亚 希尔斯布莱德"}},{q="谁是伯恩赛德镇长？",a="伯恩赛德镇长是希尔斯布莱德人类城镇的镇长和政治领袖。他与议员们一同驻扎在市政厅内，并利用奥术魔法来捍卫定居点残存的权力。",al={"伯恩赛德镇长","伯恩赛德是谁","希尔斯布莱德领导人"}},{q="什么是希尔斯布莱德公告？",a="希尔斯布莱德公告是一份存放在市政厅显眼位置的受人尊敬的政治宪章。它体现了该镇居民的合法治理和精神，因此它的销毁是对市政士气的沉重打击。",al={"什么是公告","希尔斯布莱德公告背景故事","摧毁公告"}},{q="为什么达萨利亚想要城镇登记册？",a="城镇登记册包含了希尔斯布莱德人口的完整普查和市政档案。窃取它剥夺了幸存人类的行政记忆，同时也为被遗忘者提供了关于该地区还剩下什么人的重要情报。",al={"为什么要偷登记册","希尔斯布莱德城镇文档","登记册有什么用"}},{q="这场战斗在哪里进行？",a="目标位于希尔斯布莱德人类定居点内的大型市政厅建筑及其周边，该定居点位于塔伦米尔和南海镇之间的南部山麓丘陵地区。",al={"伯恩赛德镇长在哪里","希尔斯布莱德市政厅位置","议员们在哪里"}},{q="议员们扮演什么角色？",a="希尔斯布莱德议员是辅助伯恩赛德镇长的管理机构。他们是能够施法的施法者，负责保卫市政厅内部及其周围的场地。",al={"希尔斯布莱德议员","议员们是谁"}}},fx={["1e1aeb4f"]={q="高级执行官达萨利亚为什么要完成这件事？",a="希尔斯布莱德镇在被遗忘者的多次袭击后陷入混乱，但只要当地领导层还在，人类守军就拒绝投降。高级执行官达萨利亚打算彻底摧毁他们的斗志，将他们永远从丘陵中抹去。她要刺杀治安官Burnside和议会成员，摧毁他们珍视的《希尔斯布莱德宣言》，并夺取他们的档案，以此瓦解维系希尔斯布莱德农场秩序的残余架构。",al={"为什么袭击希尔斯布莱德领导层","达萨利亚在希尔斯布莱德之战中的动机","达萨利亚为什么要杀死burnside"}},acee9bfa={q="你奉命在希尔斯布莱德对付谁？",a="你奉命前往希尔斯布莱德镇政厅，刺杀治安官Burnside和他的五名议员。尽管农场和果园各处伤亡惨重，Burnside和他的议会仍在组织当地防御，号召人类居民对抗塔伦米尔。除掉治安官和政治议会，就能剥夺这座城镇的统治权。",al={"我们在希尔斯布莱德要杀谁","希尔斯布莱德之战的目标","治安官burnside和议会成员是谁"}},["827d131a"]={q="《希尔斯布莱德城镇文档》有什么用？",a="《希尔斯布莱德城镇文档》是记录希尔斯布莱德当地居民和财产的官方民事档案。夺走它会剥夺幸存人类的行政人口记录，同时让高级执行官达萨利亚掌握聚居地每位居民、业主和纳税人的详尽情报。",al={"什么是希尔斯布莱德城镇文档","希尔斯布莱德文档的用途","为什么偷走城镇文档"}}},fp="19,335,29.444.0,24.472.0,23.179.0,27.221.0,35.223.0,42.237.0,33.182.0,33.185.0"}
P.entries["quest:5321"] = {n="昏昏欲睡",s="克罗尼亚·恒影，一位刚苏醒不久的利爪德鲁伊，在前往灰谷迈斯特拉岗哨的旅途中努力保持清醒。他随身携带着唤醒号角，旅行者们必须在森林边缘护送这位昏昏欲睡的德鲁伊，在他陷入沉睡时唤醒他，并保护他免受野性熊怪和邪恶教徒的袭击。",h="克罗尼亚·恒影，一位刚苏醒不久的利爪德鲁伊，在前往灰谷迈斯特拉岗哨的旅途中努力保持清醒。他随身携带着唤醒号角，旅行者们必须在森林边缘护送这位昏昏欲睡的德鲁伊，在他陷入沉睡时唤醒他，并保护他免受野性熊怪和邪恶教徒的袭击。",kw={"灰谷","暮光之锤","黑海岸","利爪德鲁伊","恒影","唤醒号角","克罗尼亚","利拉迪斯","迈斯特拉岗哨","暮光谷"},ang={["class:Druid"]="德鲁伊们会明白与翡翠梦境进行深度交流所带来的沉重代价，因为长期的冬眠往往会使清醒的头脑难以恢复完全的意识。",["faction:Alliance"]="确保旅行者在黑海岸和灰谷北部之间的安全通行，有助于维持奥伯丁与外围哨所之间重要的通讯线路。",["race:NightElf"]="对于暗夜精灵来说，克罗尼亚是他们文化剧变的一个缩影，代表了成千上万在第三次战争中响应号角召唤，如今正在适应白昼生活的德鲁伊们。"},sec={{t="沉睡的思绪",b="数千年来，利爪德鲁伊们一直在翡翠梦境中与荒野之灵交流，在兽穴中沉睡。虽然第三次战争迫使他们苏醒，但要摆脱数百年的冬眠状态对每个人的心智来说都不容易。克罗尼亚·恒影从黑海岸出发向南前往灰谷，准备与利拉迪斯·月河会合，但他在旅途开始不久后就因极度疲惫而倒下。他发现自己会在野外不由自主地陷入沉睡，因此只能依靠一把黄铜制的唤醒号角和过往的盟友来让他继续前行。"},{t="路途中的危险",b="连接黑海岸与灰谷的道路绝非安宁之地。当克罗尼亚蜿蜒向南行进时，他脆弱的状态引来了周围荒野生物的攻击。在暮光谷，腐化的黑木熊怪潜伏在道路旁，而在更南方的灰谷，阴影中的暮光之锤教派成员也在伺机伏击。护送这位昏沉的德鲁伊需要保持警惕，因为如果不使用号角强行唤醒他，克罗尼亚随时都会倒地入睡。"},{t="抵达哨所",b="在躲过伏击并抵达迈斯特拉岗哨后，克罗尼亚很快就会溜走，去寻找另一块舒适的草地继续他未完成的小憩。他的联络人利拉迪斯·月河对他那习以为常的昏沉状态并没有感到惊讶，只是以一种宠溺又无奈的态度迎接了他的到来。克罗尼亚的挣扎反映了许多德鲁伊共同的困扰——与翡翠梦境中永恒的宁静相比，清醒的世界让他们感到难以适应。"}},faq={{q="为什么克罗尼亚一直睡觉？",a="克罗尼亚·恒影是一位利爪德鲁伊，不久前才从翡翠梦境中数百年的冬眠中苏醒。回归清醒的世界会让许多德鲁伊感到迷失方向且极度昏沉，这使得他如果没有持续的外部刺激就几乎无法保持清醒。",al={"克罗尼亚为什么在睡觉","他为什么这么困","德鲁伊睡觉"}},{q="当克罗尼亚睡觉时，如何唤醒他？",a="你必须使用唤醒号角，它可以在旅程开始时从克罗尼亚身旁的箱子中获得。每当他在路途中陷入沉睡时，吹响号角就能让他清醒过来，以便他能继续跟随你前进。",al={"如何唤醒克罗尼亚","克罗尼亚号角","唤醒号角的使用"}},{q="在迈斯特拉岗哨，谁在等待克罗尼亚？",a="他正前往会见利拉迪斯·月河，这是一位驻守在灰谷北部的迈斯特拉岗哨的精灵。她很了解他那习惯性的嗜睡，看到他平安抵达只是感到宽慰。",al={"利拉迪斯是谁","克罗尼亚要去见谁"}},{q="沿途会有什么敌人攻击？",a="道路经过暮光谷时，敌对的黑木熊怪会伏击队伍。再往南进入灰谷后，属于隐秘的暮光之锤教派的挖掘者、教徒和邪教分子会从阴影中发动袭击。",al={"护送途中的伏击","什么在攻击克罗尼亚","暮光谷伏击"}},{q="“沉睡者已苏醒”这个标题从何而来？",a="这是利爪德鲁伊在第三次战争中被召集参战时所说的标志性问候语，突显了克罗尼亚作为一名苏醒的变形者的本质。",al={"沉睡者已苏醒引用","德鲁伊语音"}},{q="如果花的时间太长，号角会怎么样？",a="唤醒号角的使用时间有限，之后就会从你的物品栏中消失。如果护送过程花费时间太长，或者因失败需要重新开始，则必须从克罗尼亚休息地点的箱子中重新领取。",al={"号角过期","唤醒号角消失"}}},fp="24,229,17.518.0,20.326.0,22.324.1,39.238.0,42.188.0,47.159.0,34.150.0,58.193.0,46.205.0"}
P.entries["quest:533"] = {n="秘密潜入",s="在塔伦米尔，克鲁斯克终于听到了关于戈尔迪尔的消息和传闻，这是一名被辛迪加囚禁的兽人。那些人类一直在转移他们的俘虏，所以克鲁斯克已经将搜索范围缩小到了镇子北边辛迪加的大营地，他想让你带回任何你能找到的情报。",h="在塔伦米尔，克鲁斯克终于听到了关于戈尔迪尔的消息和传闻，这是一名被辛迪加囚禁的兽人。那些人类一直在转移他们的俘虏，所以克鲁斯克已经将搜索范围缩小到了镇子北边辛迪加的大营地，他想让你带回任何你能找到的情报。",kw={"奥特兰克","戈尔迪尔","希尔斯布莱德","渗透","克鲁斯克","信函","辛迪加","塔伦米尔"},sec={{t="戈尔迪尔的消息",b="克鲁斯克开始听到关于戈尔迪尔的消息和传闻。辛迪加的人类一直在转移这名兽人，但搜索范围已经缩小到了塔伦米尔北边他们的大营地。克鲁斯克派你去那里，尽你所能搜集任何情报并带回来。克鲁斯克担心每一天过去，戈尔迪尔的处境就越危险。"},{t="给克鲁斯克的消息",b="你带回来的东西告诉了克鲁斯克戈尔迪尔被关押在哪里。那个营地离塔伦米尔不远，克鲁斯克希望那里的守卫会比第一次俘虏克鲁斯克和其他人的那些人准备得更不充分。"}},faq={{q="克鲁斯克在寻找谁？",a="戈尔迪尔，一名被辛迪加囚禁的兽人，那些人类一直在转移他。",al={"克鲁斯克在寻找谁","戈尔迪尔是谁","谁需要被营救"}},{q="克鲁斯克派你去哪里寻找情报？",a="去塔伦米尔北边辛迪加的大营地，带回任何你能找到的关于戈尔迪尔下落的情报。",al={"我该去哪里执行渗透任务","辛迪加营地位置","辛迪加信函在哪里"}},{q="定位戈尔迪尔需要什么情报？",a="任何显示戈尔迪尔下落的东西。带回给克鲁斯克的是一份辛迪加的信函。",al={"我需要找什么","克鲁斯克在找什么物品","什么是信函"}},{q="谁在关押戈尔迪尔？",a="辛迪加。他们的人类一直在转移他。",al={"谁俘虏了戈尔迪尔","谁在囚禁这名兽人"}}},fp="12,299,15.328.0,14.214.1,25.83.0,50.136.0,45.91.0,23.48.0"}
P.entries["quest:535"] = {n="仆从瓦里克",s="仆从瓦里克躺在辛迪加营地里，身负重伤，奄奄一息，面对着一名敌人。他确信你无论如何都会杀了他，于是提出了一笔交易：用南海镇烈酒换取他回答你的问题。",h="仆从瓦里克躺在辛迪加营地里，身负重伤，奄奄一息，面对着一名敌人。他确信你无论如何都会杀了他，于是提出了一笔交易：用南海镇烈酒换取他回答你的问题。",kw={"奥特兰克山脉","仆从瓦里克","南海镇烈酒","辛迪加","瓦里克"},sec={{t="垂死的交易",b="瓦里克受了重伤，生命垂危，发现你站在面前，以为你是敌人。瓦里克料定你无论如何都会杀了他，便提出了一笔交易：将一杯南海镇烈酒带到辛迪加营地，他就回答你的问题。瓦里克甚至还大声怀疑你们这类人到底喝不喝酒。"},{t="瓦里克的最后一杯酒",b="瓦里克声称这杯烈酒是他尝过最甜的东西，因为死亡就在眼前。他交出了死人已无用处之物，然后让你赶紧动手。"}},faq={{q="瓦里克是谁？",a="仆从瓦里克是辛迪加的一名受伤且奄奄一息的仆从，可以在辛迪加营地找到他。",al={"仆从瓦里克","瓦里克是谁","奥特兰克 瓦里克"}},{q="瓦里克想要什么？",a="一杯南海镇烈酒，带到辛迪加营地。",al={"瓦里克需要什么","瓦里克的饮品","瓦里克 烈酒"}},{q="瓦里克用烈酒换取什么承诺？",a="瓦里克承诺分享你想要的情报，尽管他预料到之后还是会被杀掉。",al={"瓦里克奖励剧情","瓦里克告诉你什么","瓦里克交易"}}},fp="5,193,15.291.0,18.165.1,13.94.0,21.57.0,48.91.0"}
P.entries["quest:536"] = {n="清理海岸",s="“顺海岸而下”是一项由南海镇的法尔林·奥里涅尔中尉发布的联盟任务。这位卫兵中尉对从暴风城调任边境感到十分不满，他宁愿喝酒也不愿巡逻，并雇佣冒险者去清除沿西部海岸侵扰的碎鳍鱼人。",h="“顺海岸而下”是一项由南海镇的法尔林·奥里涅尔中尉发布的联盟任务。这位卫兵中尉对从暴风城调任边境感到十分不满，他宁愿喝酒也不愿巡逻，并雇佣冒险者去清除沿西部海岸侵扰的碎鳍鱼人。",kw={"顺海岸而下","法尔林·奥里涅尔","希尔斯布莱德","鱼人","雷德帕斯","南海镇","碎鳍","西部海岸"},ang={["faction:Alliance"]="南海镇是联盟在北方主要的沿海堡垒，因此即便卫戍部队中出现微小的玩忽职守，也会对城镇的生存构成威胁。",["race:Human"]="暴风城优渥的中心地带与北方定居点艰苦生存环境之间的对比，因奥里涅尔的懒散而显得愈发刺眼。"},sec={{t="不情愿的驻守",b="法尔林·奥里涅尔中尉从暴风城卫兵那整洁的石板街道被调往了偏远且充满海腥味的南海镇。他觉得这个镇子沉闷乏味，港口的鱼腥味也让人难以忍受，因此奥里涅尔整天躲在当地旅店里借酒消愁，而不去前线巡逻。当治安官雷德帕斯下令保护南海镇免受周边威胁时，奥里涅尔选择了将自己的职责外包给过路的雇佣兵。"},{t="碎鳍鱼人的威胁",b="这项任务主要针对的是西部海岸，即从南海镇向西延伸的海岸线。虽然奥里涅尔对“长大的鱼”的威胁嗤之以鼻，但碎鳍鱼人部落确实对沿海交通和当地航运构成了真正的危害。它们在碎浪边紧密扎营，其潮汐猎人和神秘的神谕者很容易伏击任何走得离镇墙太远的行人，使得清理海岸线成为了一项血腥的工作。"}},faq={{q="为什么法尔林·奥里涅尔不亲自处理鱼人？",a="法尔林认为南海镇是他从暴风城卫兵生涯中被流放到了一个他不想要的地方。他对自己的驻扎地感到怨恨，对这个沿海城镇感到厌恶，他宁愿坐在酒馆里喝酒，也不愿冲入海浪中与鱼人战斗，于是他花钱雇佣冒险者来替他干活。",al={"为什么法尔林在喝酒","法尔林·奥里涅尔性格","为什么雇佣冒险者"}},{q="奥里涅尔提到的“雷德帕斯老兄”是谁？",a="他指的是治安官雷德帕斯，南海镇的治安官。雷德帕斯负责维护这个多灾多难的定居点的秩序和防御，其中包括发布奥里涅尔中尉公然想要逃避的军事指令。",al={"雷德帕斯是谁","治安官雷德帕斯","奥里涅尔指挥官"}},{q="碎鳍鱼人位于何处？",a="碎鳍鱼人栖息在西部海岸，即希尔斯布莱德丘陵中南海镇正西方的海岸沙滩上。",al={"碎鳍鱼人位置","希尔斯布莱德鱼人位置","西部海岸位置"}},{q="需要消灭哪些种类的鱼人？",a="任务要求消灭碎鳍潮汐猎人，即部落的前线战士，以及能够使用元素和水系魔法来加强同伴的碎鳍神谕者。",al={"鱼人目标","要杀哪些鱼人","潮汐猎人神谕者"}},{q="在为奥里涅尔清理完海滩后会发生什么？",a="在完成扫荡后，奥里涅尔意识到他需要实质性的证据来应付治安官雷德帕斯的审查，这开启了一系列旨在收集被杀鱼人的物证的任务。",al={"顺海岸而下后续任务","顺海岸而下任务链","法尔林的证明后续"}},{q="鱼人的威胁是真实的，还是仅仅是个借口？",a="虽然法尔林嘲笑这些生物只是无害的“长大的鱼”，但碎鳍鱼人数量众多、极具攻击性，且位置紧邻南海镇码头，威胁着贸易路线和渔民。",al={"希尔斯布莱德的鱼人危险吗","南海镇鱼人威胁"}}},fx={dc8aa8a8={q="法尔林·奥里涅尔中尉为什么要杀死鱼人？",a="奥里涅尔中尉厌恶南海镇，觉得自己从暴风城卫队调来这里就像遭到流放。他的上司治安官雷德帕斯命令他守卫海岸，抵御当地鱼人。法尔林认为这项差事有失身份，还嘲笑这些长满苔藓的鱼不过是微不足道的麻烦。他让你削弱鱼人的数量，是想装出积极服从命令、保护南海镇的样子，同时自己喝着麦酒，盼望调回首都。",al={"法尔林的动机","法尔林为什么要杀鱼人","法尔林为什么想杀死鱼人"}},["11ea9e8a"]={q="海岸沿线的裂鳍鱼人是什么？",a="裂鳍鱼人是一个好斗的部族，盘踞在希尔斯布莱德丘陵的西部海岸和南部海岸。他们聚集在水边的渔营中，潮猎者和秘法预言者会袭击海岸线，持续骚扰南海镇。尽管奥里涅尔中尉不把他们放在眼里，称他们不过是一群鱼，但他们在浪涛间数量庞大，始终给当地港口和沿海旅行者带来麻烦。",al={"裂鳍鱼人是谁","裂鳍鱼人","希尔斯布莱德鱼人"}}},fp="14,293,19.458.0,19.442.0,58.293.0,42.242.0,39.139.0,44.179.0,51.196.1,56.195.0"}
P.entries["quest:5361"] = {n="兄弟",s="峭壁卫兵图林·长角请你将一份报告带给纳塔卡·长角，他是峭壁卫兵的兄弟，驻扎在凄凉之地。关于半人马异常活动的讯息需要传达到幽灵岗哨。",h="峭壁卫兵图林·长角请你将一份报告带给纳塔卡·长角，他是峭壁卫兵的兄弟，驻扎在凄凉之地。关于半人马异常活动的讯息需要传达到幽灵岗哨。",kw={"半人马","焦炭谷","峭壁卫兵图林·长角","凄凉之地","家谱","幽灵岗哨","纳塔卡·长角","石爪山","千针石林"},sec={{t="兄弟的报告",b="峭壁卫兵的兄弟纳塔卡在凄凉之地的幽灵岗哨驻守。峭壁卫兵已经有一年没有写信了，在这段时间里，半人马的行为很不寻常。纳塔卡应该知道这件事，所以有人委托你来递送这份报告。"},{t="旅途之路",b="这条路通往石爪山，它位于十字路口的北面，然后向西进入焦炭谷。从那里折向南进入凄凉之地，沿着一条路向南即可到达幽灵岗哨。"},{t="岗哨的欢迎",b="纳塔卡·长角虽然不知道你是如何认识峭壁卫兵的，但看起来峭壁卫兵很信任你。纳塔卡欢迎你来到幽灵岗哨，这里有很多需要解决的问题，他建议你和那里的其他人谈谈，也许有人需要你的帮助。"}},faq={{q="峭壁卫兵图林·长角想要联系谁？",a="纳塔卡·长角，峭壁卫兵的兄弟，他驻守在凄凉之地的幽灵岗哨。",al={"纳塔卡是谁","长角兄弟","谁接收报告"}},{q="为什么峭壁卫兵图林·长角现在要发送一份报告？",a="峭壁卫兵已经一年没有写信了，而半人马自那以后表现得非常异常，所以应该告知纳塔卡。",al={"为什么发送报告","半人马活动报告","消息原因"}},{q="纳塔卡·长角在哪里？",a="在凄凉之地的幽灵岗哨，你可以沿着一条向南的路到达那里。",al={"纳塔卡位置","幽灵岗哨在哪里","去哪里递交报告"}},{q="从千针石林前往幽灵岗哨的路径是什么？",a="前往十字路口北面的石爪山。从那里向西进入焦炭谷，然后向南进入凄凉之地，沿着路走就能到达幽灵岗哨。",al={"如何前往凄凉之地","幽灵岗哨路线","旅行路径"}}},fp="11,192,22.255.0,13.192.0,21.239.1,47.88.0,50.122.0,33.74.0,59.161.0"}
P.entries["quest:537"] = {n="黑暗议会",s="南海镇的赫尼·马雷布镇长得知你带来的信件来自一个名叫纳加兹的生物，他属于阿古斯苏醒者。马雷布说，如果阿古斯苏醒者与辛迪加结盟，他们就必然是个威胁。你被派去高地猎杀纳加兹和阿古斯暗影法师。",h="南海镇的赫尼·马雷布镇长得知你带来的信件来自一个名叫纳加兹的生物，他属于阿古斯苏醒者。马雷布说，如果阿古斯苏醒者与辛迪加结盟，他们就必然是个威胁。你被派去高地猎杀纳加兹和阿古斯暗影法师。",kw={"阿古斯暗影法师","阿古斯苏醒者","黑暗议会","赫尼·马雷布","纳加兹","南海镇","斯坦恩布莱德","辛迪加","高地"},sec={{t="高地的特使",b="在完成“进一步的谜团”之后，马雷布告诉你那封信来自一个名叫纳加兹的生物，他属于阿古斯苏醒者。马雷布不知道阿古斯苏醒者是什么，但如果他们与辛迪加结盟，就会构成威胁。马雷布要求找到并杀死信中提到的纳加兹和阿古斯暗影法师，并带回纳加兹的头颅。你要去搜寻斯坦恩布莱德以北的高地，那里是辛迪加势力最强的地方。马雷布希望阿古斯苏醒者的特使就在那里。"},{t="马雷布的结论",b="马雷布认为像阿古斯苏醒者这样的组织可能在操控辛迪加，这绝非好消息。他还补充说，纳加兹只是别人的仆从，而阿古斯苏醒者的触手可能已经深入整片大陆，甚至遍及全世界。"}},faq={{q="是谁派你去追踪纳加兹的？",a="南海镇的赫尼·马雷布镇长，他阅读了你带给他的信件。",al={"谁给予黑暗议会任务","黑暗议会任务发布者","哪里接取黑暗议会"}},{q="纳加兹和阿古斯暗影法师在哪里？",a="马雷布让你去搜寻斯坦恩布莱德以北的高地，那里是辛迪加势力最强的地方。",al={"纳加兹在哪里","阿古斯暗影法师位置","高地在哪里"}},{q="阿古斯苏醒者是什么？",a="马雷布不知道。他只知道纳加兹属于该组织，并且如果它与辛迪加结盟，那一定是个威胁。",al={"阿古斯苏醒者是谁","什么是阿古斯苏醒者","阿古斯苏醒者背景故事"}},{q="在此之前发生了什么？",a="这紧接在“进一步的谜团”之后，在那个任务中你将破译后的信件带给了马雷布。",al={"黑暗议会前置任务","上一个任务","在此之前的任务是什么"}}},fp="12,301,21.471.0,20.214.1,26.74.0,51.93.0,23.126.0,25.81.0"}
P.entries["quest:5381"] = {n="埃鲁索斯之手",s="葬影村的泰迦·慧鬃说火刃氏族拥有一个恶魔之盒，里面藏着一个名为伊鲁克索斯之手的强大物体。在玛诺洛克集会所，火刃氏族利用它来开启恶魔传送门。泰迦派你去雷斧堡垒取回这个盒子。",h="葬影村的泰迦·慧鬃说火刃氏族拥有一个恶魔之盒，里面藏着一个名为伊鲁克索斯之手的强大物体。在玛诺洛克集会所，火刃氏族利用它来开启恶魔传送门。泰迦派你去雷斧堡垒取回这个盒子。",kw={"火刃氏族","恶魔之盒","恶魔之镐","伊鲁克索斯之手","玛诺洛克集会所","红色水晶","葬影村","泰迦·慧鬃","雷斧堡垒"},sec={{t="堡垒中的盒子",b="泰迦·慧鬃想要阻止恶魔源源不断地涌入我们的世界。你得到了一把恶魔之镐，用来对付雷斧堡垒里的红色水晶，从而开启通往恶魔之盒的道路。盒子和镐都需要带回给葬影村的泰迦。"}},faq={{q="谁索要恶魔之盒？",a="葬影村的泰迦·慧鬃。",al={"任务发布者","谁开启了伊鲁克索斯之手任务","在哪里接任务"}},{q="什么是伊鲁克索斯之手？",a="藏在恶魔之盒里的强大物体。在玛诺洛克集会所，火刃氏族利用它来为恶魔开启传送门。",al={"什么是伊鲁克索斯之手","伊鲁克索斯之手神器","伊鲁克索斯之手有什么用"}},{q="恶魔之盒在哪里？",a="在雷斧堡垒，那里有一块红色水晶可以让你接触到它。",al={"恶魔之盒在哪里","恶魔之盒位置","寻找恶魔之盒"}},{q="如何获得恶魔之盒？",a="你得到了一把恶魔之镐，用它去对付雷斧堡垒里的红色水晶。",al={"如何获取恶魔之盒","恶魔之镐用法","雷斧堡垒红色水晶"}}},fp="14,282,23.264.0,27.38.0,27.131.0,23.64.0,32.90.0"}
P.entries["quest:5386"] = {n="食鱼度日",s="幽灵岗哨已经很久没有闻到煮鱼的味道了，纳塔卡·长角想改变这种状况。纳塔卡认为葬影村的巨魔是周围最好的捕鱼能手，但半人马的活动让他没时间亲自去一趟。你受托代替纳塔卡去那里，带回两条血腹鱼。",h="幽灵岗哨已经很久没有闻到煮鱼的味道了，纳塔卡·长角想改变这种状况。纳塔卡认为葬影村的巨魔是周围最好的捕鱼能手，但半人马的活动让他没时间亲自去一趟。你受托代替纳塔卡去那里，带回两条血腹鱼。",kw={"血腹鱼","海岸的美味","半人马","凄凉之地","幽灵岗哨","吉纳泽林","纳塔卡·长角","葬影村"},sec={{t="海岸的美味",b="幽灵岗哨已经很久没有闻到煮鱼的味道了。纳塔卡·长角认为葬影村的巨魔是最好的捕鱼能手，但半人马的活动让他没时间亲自去一趟。因此，你受托前往那里，与当地的渔夫吉纳泽林交谈，并带回两条纳塔卡最喜欢的血腹鱼。岗哨南部的道路向西弯曲，可以带你到达那个巨魔村庄。"}},faq={{q="谁在寻找血腹鱼？",a="凄凉之地的幽灵岗哨的纳塔卡·长角。血腹鱼是纳塔卡的最爱。",al={"谁发布了海岸的美味任务","纳塔卡·长角任务"}},{q="为什么纳塔卡·长角不能亲自去捕鱼？",a="由于半人马活动频繁，纳塔卡没时间前往巨魔村庄。",al={"为什么纳塔卡不能离开","为什么纳塔卡需要帮助"}},{q="在哪里可以找到血腹鱼？",a="纳塔卡派你去葬影村（一个巨魔村庄）找当地的渔夫吉纳泽林谈谈。",al={"在哪里获取血腹鱼","吉纳泽林位置"}},{q="从幽灵岗哨怎么去葬影村？",a="从岗哨向南沿路走，向西拐就能到达那个巨魔村庄。",al={"前往葬影村的路径","如何到达巨魔村庄"}},{q="纳塔卡想要多少条血腹鱼？",a="两条。",al={"需要多少鱼","血腹鱼数量"}}},fp="16,338,20.435.0,35.88.0,47.88.0,39.104.0,59.61.0,42.4.0"}
P.entries["quest:539"] = {n="希尔斯布莱德之战",s="这份来自高级执行官达萨利亚的作战指令指示部落特工深入碧玉矿洞——一处位于希尔斯布莱德农场南方的关键铁矿开采点。被遗忘者旨在通过消灭工头邦兹及其手下，切断对联盟军械库的铁矿供应，并将这些矿道据为己有。",h="这份来自高级执行官达萨利亚的作战指令指示部落特工深入碧玉矿洞——一处位于希尔斯布莱德农场南方的关键铁矿开采点。被遗忘者旨在通过消灭工头邦兹及其手下，切断对联盟军械库的铁矿供应，并将这些矿道据为己有。",kw={"碧玉矿洞","邦兹","达萨利亚","希尔斯布莱德","铁","矿工","南海镇","塔伦米尔","幽暗城"},ang={["faction:Horde"]="扰乱联盟在希尔斯布莱德的主要金属供应，减轻了塔伦米尔前线的压力，确保人类部队无法轻易更换他们的装备。",["profession:Mining"]="碧玉矿洞是山麓地带最富饶的铁矿作业点之一，这使它成为任何争夺宝贵矿脉的势力眼中的焦点。",["race:Undead"]="夺取碧玉矿洞能为死亡卫士获取至关重要的铁矿，将人类的工业力量转化为装备Sylvanas军队的利器，助其征服整个洛丹伦。"},sec={{t="切断铁矿供应",b="在早先的突袭中夺取了希尔斯布莱德城镇文档后，高级执行官达萨利亚认定碧玉矿洞是该地区人类军事持久战的核心支柱。该矿场位于争议农场的正南方，持续不断地挖掘富饶的铁矿脉，为联盟的武器锻造师和军械库提供资源。如果对其放任不管，南海镇的部队就能重新武装并加强其驻军，从而使塔伦米尔此前的胜利变得毫无意义。"},{t="决定性的讯息",b="为了彻底破坏其生产，达萨利亚将领导层和劳动力同时列为目标。部落部队奉命消灭负责管理矿场的工头邦兹，以及他手下的绝大部分工人。深入黑暗的矿井进行打击，向南海镇传达了一个明确无误的讯息：无论是他们的补给线还是孤立的劳工营，都逃不出被遗忘者的手掌心。"},{t="黑暗女王的战利品",b="除了阻止联盟获得战争物资外，这次袭击还为幽暗城提供了一个现实的次要动机。占领矿场使Sylvanas Windrunner的部队能够将富饶的矿脉据为己有。塔伦米尔需要稳定的金属供应来制造武器和板甲，以支持整个洛丹伦的战争行动，将以前的人类资产转化为被遗忘者征服的动力引擎。"}},faq={{q="为什么碧玉矿洞对被遗忘者如此重要？",a="碧玉矿洞直接为联盟军械库提供优质铁矿。夺取该矿洞不仅能让南海镇等地的人类驻军因为缺乏锻造材料而陷入困境，还能将丰富的原材料交给幽暗城，以装备被遗忘者的部队。",al={"为什么要攻击碧玉矿洞","碧玉矿洞的作用","为什么要以矿洞为目标"}},{q="谁是工头邦兹？",a="工头邦兹是负责碧玉矿洞开采工作的人类监工。他管理着矿工，并且在深陷下层矿洞走投无路时，能召唤坚韧的矮人守卫。",al={"工头邦兹","谁是邦兹","谁领导这个矿场"}},{q="碧玉矿洞位于哪里？",a="碧玉矿洞开凿在希尔斯布莱德农场南面的山丘中，坐落在海岸悬崖边，南海镇的西侧。",al={"碧玉矿洞在哪里","碧玉矿洞位置","如何找到矿洞"}},{q="达萨利亚是如何得知矿场运作的？",a="达萨利亚是通过查阅希尔斯布莱德城镇文档发现了矿场的后勤价值及其活跃状态，这些文档是部落特工在先前突袭人类定居点时回收的。",al={"达萨利亚是怎么知道的","城镇文档矿洞","希尔斯布莱德情报"}},{q="消灭工头邦兹后会发生什么？",a="随着矿场陷入瘫痪且其资源被标记为由被遗忘者控制，高级执行官达萨利亚升级了攻势，将部落的注意力转向破坏希尔斯布莱德其余的基础设施，并进一步逼近南海镇。",al={"希尔斯布莱德之战后续","击杀邦兹之后","任务后续影响"}},{q="联盟会防守这个矿场吗？",a="是的。除了在矿井中工作的人类矿工外，联盟还在入口处部署了武装警卫，而工头邦兹在矿井深处也安排了强悍的矮人援军。",al={"矿洞守卫","碧玉矿洞的联盟力量","矿洞里的矮人"}}},fp="19,299,24.454.0,18.389.0,24.402.1,51.235.0,21.187.0,36.121.0,55.191.0,42.247.1,34.187.0"}
P.entries["quest:54"] = {n="去闪金镇报到",s="“向闪金镇报到”标志着冒险者从受保护的北郡山谷正式踏入了艾尔文森林的广阔辖区。带着治安官玛克布莱德发给治安官杜汉的公文，新兵们在暴风城贵族对地区防务日益忽视的背景下，被授予了代理副官的身份。",h="“向闪金镇报到”标志着冒险者从受保护的北郡山谷正式踏入了艾尔文森林的广阔辖区。带着治安官玛克布莱德发给治安官杜汉的公文，新兵们在暴风城贵族对地区防务日益忽视的背景下，被授予了代理副官的身份。",kw={"代理副官","艾尔文森林","闪金镇","治安官杜汉","治安官玛克布莱德","北郡","向闪金镇报到","暴风城治安官"},ang={["faction:Alliance"]="随着暴风城的军队被调往他处，艾尔文森林的防御日益依赖于新获得副官头衔的当地新兵和志愿者。",["race:Human"]="从北郡毕业并前往闪金镇服役，标志着人类冒险者首次获得暴风城军事体系的正式认可。"},sec={{t="从北郡到大森林",b="在证明了自己的实力，解决了北郡山谷内的当地麻烦后，治安官玛克布莱德正式批准新兵离开北郡卫队。为了表彰他们的贡献，玛克布莱德准备了调令，指示他们南下，穿过边境大门，沿着道路前往闪金镇，将他们的职责范围转移到更广阔的艾尔文森林。"},{t="治安官的重担",b="抵达闪金镇后，治安官杜汉接受了玛克布莱德的公文，并正式任命该新兵为暴风城治安官旗下的代理副官。然而，杜汉的欢迎辞中带着严厉的警告：与艾尔文森林四处游荡的危险相比，北郡只是个和平的后花园，特别是当暴风城的皇家军队为了遥远贵族的政治博弈而分身乏术，无法保护家园领土时更是如此。"}},faq={{q="治安官杜汉是谁？",a="治安官杜汉是驻扎在闪金镇的暴风城治安官的指挥官，负责管理整个艾尔文森林的防御和巡逻工作。",al={"治安官杜汉是谁","杜汉在哪里","杜汉的职责"}},{q="为什么新兵会被派往闪金镇？",a="在处理完北郡山谷宁静区域内的紧迫威胁后，治安官玛克布莱德会将有能力的新兵重新分配到南方的闪金镇，以协助应对威胁艾尔文森林的更广泛的危险。",al={"为什么要去闪金镇","离开北郡","北郡之后的下一步"}},{q="代理副官是什么意思？",a="代理副官身份是治安官玛克布莱德的文书所授予的一种临时外勤军衔，旨在将有前途的新兵编入暴风城治安官的行列，协助当地执法。",al={"代理副官","什么是代理副官身份","副官身份的含义"}},{q="暴风城的军队在哪里？",a="据治安官杜汉所言，大部分暴风城的常备军已被调走，忙于应付宫廷贵族指派的差事和任务，而不是在当地定居点进行巡逻。",al={"暴风城军队在哪里","暴风城军队失踪","为什么艾尔文森林缺乏保护"}},{q="治安官玛克布莱德是谁？",a="治安官玛克布莱德监管着北郡修道院的驻军，负责训练新的保卫者，然后将那些证明了自己的士兵派往闪金镇的前线。",al={"玛克布莱德是谁","玛克布莱德的职责"}},{q="如何从北郡找到去往闪金镇的路？",a="闪金镇位于从北郡山谷向南延伸的主干道上，穿过边界大门即进入艾尔文森林的腹地。",al={"闪金镇之路","如何前往闪金镇","去往闪金镇的方向"}}},fp="19,313,37.373.0,26.407.0,22.161.0,35.211.0,36.191.0,28.177.0,23.155.0,42.134.0"}
P.entries["quest:540"] = {n="保全书籍",s="位于南海镇的博学者迪布斯让你前往奥特兰克废墟，食人魔已经在那里留下的珍贵书籍中安营扎寨。你必须找回被食人魔掠夺的卷轴，其中最重要的一本是：一本破旧的皮革书，记载着《格里莱克之臂》，那是古代巨魔传说的一部作品。",h="位于南海镇的博学者迪布斯让你前往奥特兰克废墟，食人魔已经在那里留下的珍贵书籍中安营扎寨。你必须找回被食人魔掠夺的卷轴，其中最重要的一本是：一本破旧的皮革书，记载着《格里莱克之臂》，那是古代巨魔传说的一部作品。",kw={"格里莱克之臂","希尔斯布莱德丘陵","博学者迪布斯","食人魔","保存知识","奥特兰克废墟","南海镇","巨魔传说"},sec={{t="食人魔手中的书籍",b="食人魔已经在奥特兰克废墟安家落户，迪布斯担心他们会毁掉那里幸存的书籍。你必须进入废墟，搜寻被食人魔掠夺的卷轴，并尽可能找回它们。迪布斯自己也想去废墟看看，但他担心自己的一把老骨头经不起攀登高山的折腾。"},{t="格里莱克之臂",b="在所有的卷轴中，迪布斯最想要的一本是：那本记载着《格里莱克之臂》的破旧皮革书。迪布斯一心想要学习其中记载的古代巨魔传说，而奥特兰克废墟是已知保留有完整副本的最后一个地方。"}},faq={{q="谁提供了这个任务？在哪里可以找到他？",a="博学者迪布斯，在南海镇。",al={"谁给予了保存知识任务","博学者迪布斯在哪里","保存知识任务给予者"}},{q="博学者迪布斯在寻找哪本书？",a="那本记载着《格里莱克之臂》的破旧皮革书，这是一部古代巨魔传说的作品。",al={"迪布斯想要哪本书","我需要什么卷轴","格里莱克之臂书籍"}},{q="这些书籍在哪里？",a="在奥特兰克废墟，那里现在住着食人魔，他们掠夺了这些卷轴。那是已知存有《格里莱克之臂》完整副本的最后一个地方。",al={"哪里能找到这些卷轴","废墟在哪里","格里莱克之臂在哪里"}},{q="为什么迪布斯想要奥特兰克的书籍？",a="迪布斯担心食人魔可能会毁掉废墟中幸存的珍贵书籍，所以他希望能找回尽可能多的书。他最想要《格里莱克之臂》，因为他必须学习其中记载的古代巨魔传说。",al={"为什么要保存知识","为什么是奥特兰克的书籍","迪布斯要这些书做什么"}}},fp="20,269,19.311.0,18.228.0,41.32.0,53.84.0,28.147.0,39.206.0"}
P.entries["quest:541"] = {n="希尔斯布莱德之战",s="在希尔斯布莱德，被遗忘者战役的关键阶段指向了矮人的据点丹加洛克。高级执行官达萨利亚派遣部落勇士去摧毁协助当地人类的矮人驻军，并处决他们的指挥官，铁丘上尉。",h="在希尔斯布莱德，被遗忘者战役的关键阶段指向了矮人的据点丹加洛克。高级执行官达萨利亚派遣部落勇士去摧毁协助当地人类的矮人驻军，并处决他们的指挥官，铁丘上尉。",kw={"希尔斯布莱德之战","铁丘上尉","丹加洛克","高级执行官达萨利亚","山地猎人","火枪手","塔伦米尔","索拉丁之墙"},ang={["faction:Horde"]="攻击丹加洛克切断了铁炉堡为援助南海镇受困人类而派遣的关键军事增援。",["race:Dwarf"]="丹加洛克代表了铁炉堡对人类盟友的坚定忠诚，忍受着被遗忘者的围攻以坚守北部边境。",["race:Undead"]="对被遗忘者而言，消灭矮人驻军巩固了洛丹伦东南部，并确保没有任何南部的联盟先遣队能轻易穿过索拉丁之墙。"},sec={{t="试探联盟",b="在向丘陵各地的人类农夫和城镇民兵施压后，高级执行官达萨利亚将塔伦米尔的怒火转向了铁炉堡的军事分遣队。矮人军队已武装起来支持南海镇，加强了人类在洛丹伦的势力。对达萨利亚来说，这种团结必须被粉碎，以向联盟证明援助人类残余势力只会带来毁灭。"},{t="丹加洛克的陷落",b="丹加洛克坐落在希尔斯布莱德东南部的索拉丁之墙古老城墙边，是一座防御森严的矮人堡垒。强攻该前哨站需要突破纪律严明的山地猎人、精锐火枪手和身经百战的牧师的防线。这次突袭最终以铁丘上尉的死亡而告终，瓦解了铁炉堡在该地区的前沿战术指挥，并使剩余的人类据点陷入孤立。"}},faq={{q="为什么矮人在希尔斯布莱德作战？",a="铁炉堡的矮人与联盟保持着紧密的联系，并向北派遣了武装部队前往丹加洛克，以援助南海镇和希尔斯布莱德的幸存人类，抵御被遗忘者的扩张。",al={"为什么希尔斯布莱德会有矮人","丹加洛克的矮人","为什么矮人要帮助人类"}},{q="丹加洛克在哪里？",a="丹加洛克位于希尔斯布莱德丘陵的东南角，直接建在索拉丁之墙的基座中。",al={"丹加洛克位置","丹加洛克在哪","寻找丹加洛克"}},{q="铁丘上尉是谁？",a="铁丘上尉是负责丹加洛克驻军的矮人指挥官。他的存在使山地猎人在该地区保持着组织性和作战能力。",al={"铁丘上尉","铁丘上尉是谁","丹加洛克首领"}},{q="谁下达了这项命令？",a="高级执行官达萨利亚，驻扎在塔伦米尔的被遗忘者军事指挥官，发布了粉碎矮人驻军的任务。",al={"谁发布的任务","任务发布者达萨利亚","达萨利亚 希尔斯布莱德"}},{q="如果部落军队在这里失败会怎样？",a="高级执行官达萨利亚明确表示绝不容忍失败，并警告说任何无法攻克丹加洛克的人都将被降职回提瑞斯法林地去挖坟墓。",al={"如果失败会怎样","达萨利亚的威胁","后果"}},{q="为什么丹加洛克难以攻打？",a="与希尔斯布莱德的乡村民兵不同，丹加洛克由训练有素的矮人战士、火枪小队和神圣牧师驻守，他们在地下和高处的掩体中以严密的防御阵型进行战斗。",al={"丹加洛克精英","为什么丹加洛克很难打","丹加洛克防御"}}},fx={b055c9ea={q="高级执行官达萨利亚为什么要袭击丹加洛克？",a="被遗忘者正在全力以赴地打击人类对希尔斯布莱德丘陵的控制，但铁炉堡的矮人介入其中，增援他们的联盟盟友。高级执行官达萨利亚打算让联盟付出保卫南海镇的代价，以此粉碎他们的决心。她要摧毁丹加洛克的兵营并杀死他们的指挥官，切断人类援军，让这片地区彻底归于黑暗女士的统治。",al={"为什么袭击丹加洛克","达萨利亚的动机","为什么杀死矮人"}}},fp="19,270,20.421.0,21.433.0,38.202.0,27.128.0,24.158.0,21.132.0,39.172.0,41.205.0"}
P.entries["quest:5421"] = {n="坐享其成",s="位于凄凉之地葬影村的吉纳泽林喜欢尽可能少做事。村子码头下方放置着许多贝壳陷阱，任何收集这些贝壳的人都会得到有价值的回报。",h="位于凄凉之地葬影村的吉纳泽林喜欢尽可能少做事。村子码头下方放置着许多贝壳陷阱，任何收集这些贝壳的人都会得到有价值的回报。",kw={"血腹鱼","凄凉之地","桶中鱼","吉纳泽林","葬影村","贝壳"},sec={{t="坐享其成",b="吉纳泽林在葬影村的码头下放置了许多贝壳陷阱，他宁愿让别人去收集。任何愿意承担这项工作的人都会得到回报：每上交五个贝壳，就能换到一条美味的血腹鱼。"}},faq={{q="是谁提供这笔交易？",a="位于凄凉之地葬影村的吉纳泽林。",al={"谁提供桶中鱼","吉纳泽林","任务发布者"}},{q="贝壳陷阱在哪里？",a="在葬影村的码头下方。",al={"陷阱位置","去哪里找贝壳","贝壳陷阱"}},{q="为什么吉纳泽林要找别人去收集贝壳？",a="吉纳泽林喜欢尽可能少做事，所以任何从陷阱里收集贝壳的人都能得到回报。",al={"为什么他需要贝壳","吉纳泽林的动机"}},{q="吉纳泽林用什么来交换贝壳？",a="每五个贝壳换一条美味的血腹鱼。",al={"桶中鱼奖励","我能得到什么"}}},fp="16,222,25.273.0,22.48.0,30.38.0,64.119.0,56.50.0"}
P.entries["quest:543"] = {n="匹瑞诺德王冠",s="“匹瑞诺德王冠”是一项由居住在暴风城的贵族雷明顿·瑞治维尔伯爵所委托的任务。他雇佣冒险者前往北方的危险地带奥特兰克废墟，以找回一件丢失的王室传家宝。这顶王冠曾属于覆灭的奥特兰克王朝，据传现正被一名食人魔术士所持有。",h="“匹瑞诺德王冠”是一项由居住在暴风城的贵族雷明顿·瑞治维尔伯爵所委托的任务。他雇佣冒险者前往北方的危险地带奥特兰克废墟，以找回一件丢失的王室传家宝。这顶王冠曾属于覆灭的奥特兰克王朝，据传现正被一名食人魔术士所持有。",kw={"奥特兰克","碎颅氏族","格雷尔伯格","吝啬鬼","匹瑞诺德","瑞治维尔","暴风城","王冠"},ang={["faction:Alliance"]="前往北方的奥特兰克山脉这一无法无天的地带，可以让联盟特工在清除危险的碎颅食人魔的同时，为暴风城的贵族找回无价的历史文物。",["race:Dwarf"]="这顶王冠由铁炉堡的珠宝大师打造，代表了矮人工匠令人称赞的工艺水平，他们的杰作即便在人类王国覆灭后依然得以留存。",["race:Human"]="对于联盟的人类来说，这顶王冠是一个令人不悦的提醒，让人想起在第二次战争期间奥特兰克的背叛，当时人类王室竟与部落结盟，对抗自己的同胞。"},sec={{t="覆灭王国的遗物",b="匹瑞诺德王冠是一件来自已覆灭的人类王国奥特兰克的精美遗物。这顶装饰华丽的头饰由铁炉堡的矮人珠宝大师打造，并镶嵌了最上等的祖母绿，供匹瑞诺德统治家族佩戴。然而，在第二次战争期间，国王艾登·匹瑞诺德背叛了联盟，投靠了兽人部落，直接导致了他的王国覆灭、被征服并最终沦为废墟。在混乱以及随后的奥特兰克城陷落过程中，许多王室王朝最伟大的珍宝都消失在了奥特兰克山脉的积雪废墟之中。"},{t="废墟中的吝啬鬼",b="这顶王冠并没有存放在联盟的宝库或王室墓穴中，而是落入了吝啬鬼格雷尔伯格贪婪的手中。作为盘踞在奥特兰克废墟中的碎颅食人魔的一员，格雷尔伯格整日在这片破败的石堆中翻找，搜寻闪亮的饰品和被遗弃的财富。雷明顿·瑞治维尔伯爵是暴风城的一位历史珍奇收藏家，他在得知王冠尚存的消息后，便招募勇敢的雇佣兵深入食人魔控制的领地，除掉这个吝啬的野兽，并将这件无价之宝带回他的私人展馆。"}},faq={{q="匹瑞诺德家族是谁？",a="匹瑞诺德家族是统治北方人类王国奥特兰克的王室血脉。在第二次战争期间，艾登·匹瑞诺德国王为了保全自己的王国，与入侵的兽人部落勾结，犯下了叛国罪。他的背叛行为被洛丹伦联盟揭发，导致奥特兰克遭到军事占领，王权被瓦解，王国随之彻底陷入混乱和毁灭。",al={"匹瑞诺德家族","匹瑞诺德家族成员","匹瑞诺德历史"}},{q="谁制作了匹瑞诺德王冠？",a="这顶王冠由矮人城市铁炉堡的珠宝大师打造。它用精良的金属制成，并镶嵌了光泽莹润的祖母绿，在国家衰落之前，它是奥特兰克统治家族尊贵与财富的象征。",al={"王冠起源","匹瑞诺德王冠的制造者"}},{q="谁现在持有这顶王冠？",a="王冠落入了吝啬鬼格雷尔伯格的手中，这名拾荒的食人魔术士游荡在北部山区的奥特兰克废墟中，贪婪地搜寻着这座被摧毁的人类城市遗留下的古代珍宝。",al={"格雷尔伯格","谁持有匹瑞诺德王冠","王冠位置"}},{q="为什么雷明顿·瑞治维尔伯爵想要这顶王冠？",a="雷明顿·瑞治维尔伯爵是一位居住在暴风城的富裕贵族和古物收藏家。他四处搜寻艾泽拉斯各地著名的文物和历史珍品以扩充他那显赫的私人收藏，并雇佣有能力的雇佣兵从危险的地方找回遗失的宝藏。",al={"雷明顿·瑞治维尔的目的","为什么要获取王冠"}},{q="奥特兰克废墟位于哪里？",a="奥特兰克废墟位于东部王国北部寒冷的奥特兰克山脉，坐落在希尔斯布莱德丘陵以北和敦霍尔德地区以北。这座废弃的城市目前被充满敌意的碎颅食人魔和辛迪加亡命徒所占据。",al={"奥特兰克废墟位置","奥特兰克在哪里"}},{q="你找回王冠后会发生什么？",a="在收到这件沾满泥土且失去光泽的传家宝后，雷明顿·瑞治维尔伯爵会安排专业的修复师进行清洗和打磨，随后立即将其作为展品陈列在他的私人藏品中。",al={"王冠上交","王冠的命运"}}},fp="19,231,27.373.0,22.391.0,29.339.0,29.132.0,24.139.0,50.213.0,39.188.0,47.157.1"}
P.entries["quest:544"] = {n="入室偷窃",s="大法师沃迪恩·伍德格莱尔正在塔伦米尔进行研究，但他现在面临一场危机。几个月前，四名被遗忘者从幽暗城窃取了保险库中的宝物并逃离，希尔瓦娜斯想要追回它们。",h="大法师沃迪恩·伍德格莱尔正在塔伦米尔进行研究，但他现在面临一场危机。几个月前，四名被遗忘者从幽暗城窃取了保险库中的宝物并逃离，希尔瓦娜斯想要追回它们。",kw={"阿琳娜","血石","达拉然","德莫特","凯根·达克玛","洛丹米尔收容所","里克特","塔伦米尔","沃迪恩·伍德格莱尔"},sec={{t="黑暗女王的盗贼",b="伍德格莱尔来到塔伦米尔进行研究，现在必须解决一场危机。四名被遗忘者背叛了他们的同胞，更糟糕的是，他们还偷窃了黑暗女王的东西。他们闯入了一座保险库，拿走了药剂师们进行某项研究所需的四件宝物。希尔瓦娜斯想要追回它们。"},{t="收容所",b="这些盗贼从幽暗城逃到了达拉然，那里的法师将他们隔离在洛丹米尔收容所。你需要找到这些叛徒，取回宝物并向塔伦米尔的伍德格莱尔汇报。共有四件：血石之楔、大理石、碎片和椭圆体。德莫特持有楔子，里克特持有大理石，阿琳娜持有碎片，而凯根·达克玛持有椭圆体。"}},faq={{q="大法师沃迪恩·伍德格莱尔是谁？",a="一位正在塔伦米尔进行研究的法师，现在面临一场危机：四件从黑暗女王那里偷来的宝物。",al={"法师伍德格莱尔","沃迪恩·伍德格莱尔","任务发布者"}},{q="被遗忘者盗贼偷了什么？",a="从保险库偷走的四件药剂师进行某项研究所需的宝物：血石之楔、大理石、碎片和椭圆体。",al={"偷了什么","血石","被盗宝物"}},{q="盗贼被关在哪里？",a="在洛丹米尔收容所，达拉然的法师们将他们隔离在那里。",al={"收容所位置","叛徒在哪里","凯根在哪里"}},{q="这四名叛徒是谁？",a="德莫特持有血石之楔，里克特持有大理石，阿琳娜持有碎片，凯根·达克玛持有椭圆体。",al={"盗贼名单","四名被遗忘者","谁偷了血石"}}},fp="15,203,24.293.0,19.360.0,31.107.0,36.130.0,33.83.0,26.97.0"}
P.entries["quest:545"] = {n="达拉然巡逻队",s="塔伦米尔的大法师沃迪恩·伍德格莱尔根本不在乎达拉然的法师们为什么要用一个巨大的魔法穹顶罩住他们的城市中心。重要的是，穹顶之外的废墟外围可能隐藏着真正的魔法宝藏，而法师们和他们的元素奴仆正在该地区巡逻。伍德格莱尔希望削减这些巡逻队的人数。",h="塔伦米尔的大法师沃迪恩·伍德格莱尔根本不在乎达拉然的法师们为什么要用一个巨大的魔法穹顶罩住他们的城市中心。重要的是，穹顶之外的废墟外围可能隐藏着真正的魔法宝藏，而法师们和他们的元素奴仆正在该地区巡逻。伍德格莱尔希望削减这...",kw={"达拉然","达拉然召唤师","元素奴仆","希尔斯布莱德丘陵","魔法穹顶","塔伦米尔","沃迪恩·伍德格莱尔"},sec={{t="废墟中的宝藏",b="在完成“越狱”之后，伍德格莱尔将目光转向了达拉然的法师们，他们用一个巨大的魔法穹顶罩住了城市的中心。有人说这保护了他们免受这个时代的暴力侵害；也有人说他们只是想要寻求清静来研究和策划。伍德格莱尔并不关心真相如何。穹顶之外的废墟外围可能隐藏着真正的魔法宝藏，但法师们和他们的元素奴仆正在那里巡逻。你去猎杀六名达拉然召唤师和十二名元素奴仆，然后回到塔伦米尔找伍德格莱尔复命。"}},faq={{q="大法师沃迪恩·伍德格莱尔为什么要削减巡逻队？",a="伍德格莱尔认为，达拉然穹顶之外的废墟外围可能隐藏着真正的魔法宝藏，但法师和他们的元素奴仆正在那里巡逻。",al={"为什么要杀达拉然巡逻队","大法师沃迪恩的目标","达拉然巡逻队的动机"}},{q="达拉然周围的魔法穹顶是什么？",a="达拉然的法师们在城市中心上方升起的一个巨大魔法穹顶。有人说这保护了他们免受这个时代的暴力侵害；也有人说他们只是想要寻求清静来研究和策划。",al={"什么是达拉然穹顶","为什么达拉然在泡泡里","达拉然护盾"}},{q="是什么在达拉然外围巡逻？",a="达拉然的法师和他们的元素奴仆。伍德格莱尔想要猎杀的目标正是达拉然召唤师和元素奴仆。",al={"谁守卫达拉然","达拉然废墟的敌人","谁在巡逻达拉然"}},{q="这个任务之前有什么任务？",a="“越狱”，同样来自塔伦米尔的伍德格莱尔。",al={"前置任务","达拉然巡逻队的前置任务是什么"}}},fp="15,341,22.518.0,50.169.0,40.195.0,38.126.0,28.52.0"}
P.entries["quest:546"] = {n="死亡的纪念品",s="“死亡纪念品”是一个由塔伦米尔的亡灵卫兵沙穆萨提供给部落勇士的任务，旨在对抗希尔斯布莱德丘陵的人类定居点。由于嫉妒那些被派往前线的士兵，沙穆萨请求勇士在战斗中收集三十个头颅来丰富他的病态收藏。",h="“死亡纪念品”是一个由塔伦米尔的亡灵卫兵沙穆萨提供给部落勇士的任务，旨在对抗希尔斯布莱德丘陵的人类定居点。由于嫉妒那些被派往前线的士兵，沙穆萨请求勇士在战斗中收集三十个头颅来丰富他的病态收藏。",kw={"希尔斯布莱德之战","达萨利亚","亡灵卫兵沙穆萨","被遗忘者","希尔斯布莱德","希尔斯布莱德人类颅骨","死亡纪念品","塔伦米尔"},ang={["faction:Alliance"]="这种系统性地收集人类头颅的行为，凸显了被遗忘者对希尔斯布莱德幸存平民所构成的残酷而真实的生存威胁。",["faction:Horde"]="针对希尔斯布莱德的战役代表了部落为了瓦解洛丹伦境内残余的联盟据点而采取的直接行动，旨在确保塔伦米尔北部的补给路线安全。",["race:Undead"]="亡灵卫兵沙穆萨反映了许多被遗忘者对那些视他们为怪物的活人所怀有的冷漠残忍和根深蒂固的敌意。"},sec={{t="守卫的嫉妒",b="当高级执行官达萨利亚指挥被遗忘者大军全力进攻希尔斯布莱德的人类定居点时，亡灵卫兵沙穆萨却发现自己被困在塔伦米尔执行岗哨任务。因为对那些被派去劫掠、焚烧和抢劫的士兵怀有强烈的嫉妒心，沙穆萨将对活人的公开屠杀视为一种令驻守城镇的卫兵垂涎不已的特权。"},{t="令人毛骨悚然的战利品",b="由于无法擅离职守，沙穆萨通过收集在持续不断的战役中被杀死的希尔斯布莱德人类头颅来满足他的仇恨。他索要三十个头颅并非为了任何奥术仪式或战术策略，纯粹是他个人的爱好——那是他渴望亲手参与的战争所留下的战利品。"}},faq={{q="谁提供了这个任务？他在哪里？",a="由亡灵卫兵沙穆萨提供该任务。他作为岗哨驻扎在塔伦米尔，那是被遗忘者在希尔斯布莱德丘陵北部的主要据点。",al={"任务发布者","谁发布死亡纪念品任务","沙穆萨位置"}},{q="亡灵卫兵沙穆萨想要什么？",a="沙穆萨要求三十个希尔斯布莱德人类头颅，这些头颅可以通过在希尔斯布莱德农场和希尔斯布莱德镇作战时击杀人类战斗人员和平民来获得。",al={"任务目标","所需物品","要求的头颅数量"}},{q="为什么沙穆萨想要人类头颅？",a="沙穆萨是一个热衷于收集可怕战利品的人。当其他人进行全面战争时，他被困在塔伦米尔担任驻军任务，于是他通过收集头颅来间接参与对活人的屠杀。",al={"为什么收集头颅","沙穆萨的动机","头颅用途"}},{q="这个任务什么时候可用？",a="只有当你向高级执行官达萨利亚报到并完成“希尔斯布莱德之战”任务线中的开场突袭后，沙穆萨才会找你。",al={"任务前置条件","如何解锁","死亡纪念品的前置任务"}},{q="这些头颅是用于被遗忘者的炼金术或魔法吗？",a="不是。与皇家药剂师协会为了寻找制作The New Plague的生物试剂而发布的任务不同，沙穆萨的请求完全是出于个人目的。他觉得这些被砍下的头颅很美，并将它们视为战争的纪念品而珍藏起来。",al={"头颅是否用于药剂师","魔法头颅","死灵法术用途"}},{q="哪些人类可以提供这些头颅？",a="当你在为塔伦米尔作战时，任何生活在希尔斯布莱德农场或希尔斯布莱德镇的人类农夫、平民、民兵和守卫都可以掉落这些头颅。",al={"哪里刷头颅","哪些怪物掉落头颅","希尔斯布莱德人类"}}},fx={["0c405e10"]={q="亡灵卫兵沙穆萨为什么需要冒险者，而不自己去猎取头骨？",a="亡灵卫兵沙穆萨被职责束缚在塔伦米尔的岗位上。被遗忘者正在对希尔斯布莱德发动积极战役，沙穆萨却只能站岗，无法参与突袭。高级执行官达萨利亚已经征召你加入前线战斗，于是沙穆萨请你体谅一位老兵，代他收集这些阴森的战利品。",al={"亡灵卫兵沙穆萨为什么找我","沙穆萨为什么不能自己找头骨","沙穆萨为什么不去狩猎"}},["3446168a"]={q="你在希尔斯布莱德对抗的人类是谁？",a="目标是希尔斯布莱德农场和希尔斯布莱德镇的人类居民、劳工和守军。作为洛丹伦境内仅存的人类主权据点之一，希尔斯布莱德直接与被遗忘者的前哨塔伦米尔对立。被遗忘者认为他们继续存在并效忠联盟，对自身的领土优势构成了无法容忍的威胁。",al={"希尔斯布莱德的人类是谁","希尔斯布莱德的目标","希尔斯布莱德的人类为何在此"}}},fp="18,285,14.373.0,17.303.0,49.147.0,32.170.0,33.185.0,38.151.0,50.222.0,32.173.0"}
P.entries["quest:547"] = {n="亨伯特的长剑",s="奉高级执行官达萨利亚之命，亡灵卫兵亨伯特在侦察铁炉堡的据点丹加洛克时，为了收集柴火暂时离开了营地。矮人侦察兵洗劫了他的营地，抢走了他的随身武器，这让这位羞愧难当的哨兵急于在指挥官察觉之前找回它。",h="奉高级执行官达萨利亚之命，亡灵卫兵亨伯特在侦察铁炉堡的据点丹加洛克时，为了收集柴火暂时离开了营地。矮人侦察兵洗劫了他的营地，抢走了他的随身武器，这让这位羞愧难当的哨兵急于在指挥官察觉之前找回它。",kw={"达萨利亚","亡灵卫兵","丹加洛克","柴火","希尔斯布莱德","亨伯特","长剑","塔伦米尔"},ang={["faction:Horde"]="对丹加洛克的每一次打击都是为了打破铁炉堡在希尔斯布莱德丘陵的军事控制，并保护塔伦米尔免受来自南方的入侵。",["race:Dwarf"]="丹加洛克的山地队员对家门口的被遗忘者毫无好感，他们抓住一切机会骚扰塔伦米尔的哨兵，并将他们的营地洗劫一空。",["race:Undead"]="希尔斯布莱德的被遗忘者士兵都明白高级执行官达萨利亚所执行的残酷纪律；在塔伦米尔，失败或疏忽面临的不是宽大处理，而是无情的处决。"},sec={{t="侦察兵的疏忽",b="高级执行官达萨利亚指派亡灵卫兵亨伯特监视丹加洛克，他在该矮人堡垒附近设立了隐蔽的岗哨。黎明时分，他短暂离开了无人看守的岗哨去收集柴火烧水。这个疏忽正是那些投机取巧的铁炉堡矮人所需要的。当亨伯特回来时，发现营地已被洗劫，他那把可靠的长剑也不翼而飞，被带入了防御森严的碉堡深处。"},{t="对绞刑架的恐惧",b="在被监视的敌人手中丢失武器，在被遗忘者军令中是应处以死刑的耻辱。亨伯特非常清楚，如果高级执行官达萨利亚知道了他的失职，一定会把他吊在塔伦米尔的房梁上。由于无法独自强攻据点，他只能寄希望于路过的部落冒险者潜入丹加洛克，在达萨利亚察觉异样之前帮他取回长剑。"}},faq={{q="谁是亡灵卫兵亨伯特？",a="亡灵卫兵亨伯特是一名驻扎在希尔斯布莱德丘陵的塔伦米尔的被遗忘者士兵。高级执行官达萨利亚指派他侦察并监视位于丘陵东南部的重兵把守的矮人前哨站——丹加洛克。",al={"亡灵卫兵亨伯特","谁是亨伯特","亨伯特"}},{q="亨伯特是怎么丢失长剑的？",a="在丹加洛克附近维持观察哨期间，亨伯特为了在早晨烧水而离开去收集柴火。在他离开期间，矮人侦察兵发现了他的营地，洗劫了他的财物，并带走了他的长剑。",al={"亨伯特怎么丢失武器的","谁偷了亨伯特的长剑","被偷的长剑"}},{q="为什么亨伯特如此急于悄悄找回他的长剑？",a="亨伯特的指挥官，高级执行官达萨利亚，在塔伦米尔执行严厉的纪律。亨伯特担心，如果她发现他把装备丢给了自己负责监视的那些矮人，她会下令处决他并将他吊在房梁上。",al={"亨伯特为什么担心","达萨利亚的惩罚","为什么害怕达萨利亚"}},{q="长剑在哪里？",a="长剑被矮人侦察兵带入了丹加洛克。它可以在占据碉堡的铁炉堡山地队员、火枪手和军官中找到。",al={"长剑位置","亨伯特的长剑在哪里","丹加洛克的长剑"}},{q="矮人还从亨伯特那里偷了别的东西吗？",a="是的。亨伯特回来时发现营地里的装备不见了，不仅仅是他的长剑，但他只请求你从丹加洛克取回那把长剑。",al={"亨伯特丢失的其他装备","亨伯特的盔甲部件","亨伯特的裤子"}},{q="什么是丹加洛克？",a="丹加洛克是位于希尔斯布莱德丘陵东南角的一个铁炉堡矮人据点，那里的矮人协助保护希尔斯布莱德的人类和附近的碧玉矿洞。那里的联盟守军与塔伦米尔的被遗忘者处于直接的敌对状态。",al={"丹加洛克要塞","丹加洛克背景故事","希尔斯布莱德的矮人"}}},fx={["65d1b07f"]={q="亨伯特的长剑为什么对他如此重要？",a="对亡灵卫兵亨伯特而言，这把武器既是个人的骄傲，也是职责的象征。没有它，他在为塔伦米尔执行侦察任务时便会手无寸铁，完全暴露在高级执行官达萨利亚的怒火之下。它没有魔力或强大的附魔，只是他珍视的佩剑；找回它能恢复他的尊严，也能掩盖在指挥官面前犯下的丢脸错误。",al={"什么是亨伯特的长剑","亨伯特为什么需要他的长剑","亨伯特长剑的用途"}},c70ad326={q="拿走亨伯特长剑的矮人是谁？",a="这些窃贼属于驻扎在丹加洛克的矮人部队。丹加洛克是坐落于希尔斯布莱德丘陵东南部的联盟据点。这些来自铁炉堡的山地步兵和火枪手经常派斥候穿越丘陵，阻止被遗忘者扩张。一支巡逻队趁亨伯特收集柴火时发现了无人看守的营地，洗劫了他的武器并将其带回他们设有防御工事的城墙后。",al={"谁偷走了亨伯特的长剑","丹加洛克的矮人","谁拿着这把长剑"}},["6c936ae5"]={q="亨伯特为什么要你帮他找回长剑，而不是自己去？",a="亨伯特无法独自攻入防守森严的矮人堡垒，也不能向其他亡灵卫兵求助，否则就得承认自己擅离岗位去烧水，结果让装备被偷。要是高级执行官达萨利亚听说他把武器丢给矮人窃贼，她一定会拿他严惩示众。独自行动的冒险者可以悄悄潜入，找回长剑。",al={"亨伯特为什么不能自己拿回长剑","为什么让我找亨伯特的长剑","亨伯特为什么需要帮助"}}},fp="15,329,20.425.0,19.435.0,26.235.0,31.231.0,58.246.0,27.167.0,49.148.0,18.279.0"}
P.entries["quest:5481"] = {n="葛尔多的任务",s="“戈多任务”是提瑞斯法林地的一个差事，由戈多——一只在去往布瑞尔的路上试图采集植物的游荡缝合怪——委派。由于他不适合进行精细的田间工作，他会招募过路人去采摘阴暗草，并将其交给他的主管，初级药剂师霍兰德。",h="“戈多任务”是提瑞斯法林地的一个差事，由戈多——一只在去往布瑞尔的路上试图采集植物的游荡缝合怪——委派。由于他不适合进行精细的田间工作，他会招募过路人去采摘阴暗草，并将其交给他的主管，初级药剂师霍兰德。",kw={"缝合怪","药剂师","布瑞尔","毁灭草","阴暗草","戈多","霍兰德","提瑞斯法林地"},ang={["profession:Herbalism"]="受过训练的草药师会发现这个任务毫不费力，因为他们的追踪感应可以轻松地在枯萎的草丛中高亮出阴暗草群落。",["race:Undead"]="对于刚从丧钟镇出发的被遗忘者新兵来说，这个任务提供了对缝合怪劳作笨拙现实以及皇家药剂师协会暴躁脾气的初次接触。"},sec={{t="笨拙的劳工",b="戈多是一只在丧钟镇和布瑞尔之间的乡间小路上来回蹒跚行走的缝合怪。虽然缝合怪擅长粗暴的战斗和沉重的搬运工作，但他们那巨大而缝合的手掌几乎无法进行精细的操作。为了皇家药剂师协会采集原料而被派往草地的戈多很快意识到，他那粗钝的手指压碎的茎干比采摘到的还要多，这促使他威逼利诱过路人替他完成这些繁琐的工作。"},{t="药剂师的挫败感",b="初级药剂师霍兰德正在布瑞尔市政厅后的墓地里等待交付，但这个差事出了岔子。戈多完全误解了他的命令，指挥过路人采集无害的阴暗草，而不是炼金研究所需的具有挥发性的毁灭草。霍兰德对这个缝合巨人的无能感到十分恼火，将这次错误的交付视为该缝合怪毫无用处的证明，并立即指派玩家去纠正这个错误。"}},faq={{q="戈多是谁？",a="戈多是一只效忠于皇家药剂师协会的缝合怪。他在布瑞尔西边的草地上巡逻，试图完成他的主人初级药剂师霍兰德指派的劳动任务。",al={"戈多是谁","提瑞斯法林地的戈多","戈多npc","什么是戈多"}},{q="为什么戈多需要帮助采集杂草？",a="戈多的手是由缝合的死肉构成的巨大而笨拙的肢体。他缺乏采摘娇嫩植物所需的灵巧性，否则就会损坏它们，所以他招募路过的被遗忘者冒险者来替他采集这些植物。",al={"为什么戈多需要杂草","为什么戈多不能采草","戈多的手"}},{q="霍兰德大师是谁？",a="初级药剂师霍兰德是驻扎在布瑞尔墓地的一名皇家药剂师协会的炼金术士。他负责监管戈多，并对当地的植物和枯萎的土壤进行研究，以辅助被遗忘者的战争努力。",al={"霍兰德大师","霍兰德是谁","药剂师霍兰德"}},{q="为什么霍兰德在收到阴暗草时会生气？",a="戈多声称霍兰德想要阴暗草，并请求你替他采集。将这些植物交给布瑞尔的初级药剂师霍兰德。",al={"为什么霍兰德生气","阴暗草错误","错误的草药"}},{q="在哪里可以找到阴暗草？",a="阴暗草生长在丧钟镇和布瑞尔之间荒野的地面低处，特别是在索利丹农场以东的开阔草地上。",al={"哪里找阴暗草","阴暗草位置","寻找阴暗草"}},{q="完成“戈多任务”后会发生什么？",a="霍兰德会在布瑞尔的墓地提供后续任务“毁灭草”。",al={"what comes next","戈多任务后续","戈多之后的任务"}}},fx={["2383074c"]={q="戈多为什么要收集阴暗草？",a="戈多说霍兰德大师需要一些草药，并请你帮忙采集阴暗草。他的大手不便采摘，于是让旅行者把植物送到布瑞尔墓地的霍兰德那里。",al={"戈多为什么要草药","戈多的动机","为什么采集阴暗草"}},a763e1e7={q="阴暗草有什么用途？",a="在霍兰德大师看来，阴暗草完全没有用。它只是一种常见、无害的野草，在提瑞斯法林地各处都能生长。霍兰德对采雏菊毫无兴趣，他需要的是用于调配药剂的末日草。",al={"阴暗草有什么用","阴暗草的用途","阴暗草的用处"}}},fp="12,264,16.465.0,23.484.1,13.201.0,41.229.0,22.218.0,54.120.1,30.150.0,43.71.1"}
P.entries["quest:5482"] = {n="末日草",s="“末日草”是布瑞尔的初级药剂师霍兰德发布的一项任务，要求收集提瑞斯法林地北部乱葬岗附近滋生的有毒植物。在对憎恶戈多笨拙的采集工作感到失望后，霍兰德开始招募路过的冒险者。",h="“末日草”是布瑞尔的初级药剂师霍兰德发布的一项任务，要求收集提瑞斯法林地北部乱葬岗附近滋生的有毒植物。在对憎恶戈多笨拙的采集工作感到失望后，霍兰德开始招募路过的冒险者。",kw={"布瑞尔","末日草","戈多","初级药剂师霍兰德","乱葬岗","腐皮豺狼人","皇家药剂师协会","提瑞斯法林地"},ang={["faction:Horde"]="布瑞尔发生的不安的炼金实验揭示了被遗忘者与他们在卡利姆多的萨满教和游牧盟友的运作方式有何不同。",["profession:Herbalism"]="虽然普通的草药在林地各处生长，但像末日草这样的腐化变种说明了天灾军团的瘟疫所造成的非自然的植物变化。",["race:Undead"]="为皇家药剂师协会的初级成员服务是新觉醒的被遗忘者建立其对Sylvanas领地价值的常见成人礼。"},sec={{t="药剂师的野心",b="初级药剂师霍兰德在布瑞尔定居点代表皇家药剂师协会进行研究。为了推进他的实验，他需要大量的末日草，这是一种侵蚀了提瑞斯法林地被污染土地的恶劣植物。发现戈多无法分辨出正确的试剂后，霍兰德转而寻求更敏锐的帮手来挽救他的收成。"},{t="乱葬岗的收成",b="末日草在遭受死亡和瘟疫严重腐蚀的地方生长繁茂，在布瑞尔墓地以北的乱葬岗附近密集生长。由于潜伏在这些亵渎的土堆中、在遗骸间觅食并保卫那些杂草丛生的沟渠的腐皮豺狼人非常凶猛，采集这种植物变得危机四伏。"}},faq={{q="初级药剂师霍兰德为什么需要末日草？",a="初级药剂师霍兰德需要末日草来为皇家药剂师协会进行炼金工作。他声称这项服务直接协助了Sylvanas Windrunner女士，尽管他那贪婪的热情表明他在推动自己在协会内的职业生涯方面同样投入。",al={"霍兰德 末日草","为什么需要末日草","末日草的用途"}},{q="为什么戈多不亲自去采集这些草药？",a="戈多是一个被指派在布瑞尔周围采集草药的憎恶，但他缺乏辨别特定植物的智力。霍兰德抱怨说这个笨重的生物带回来的草药完全不对，迫使药剂师转而雇佣有能力的冒险者。",al={"为什么不用戈多","戈多任务失败","戈多是谁"}},{q="末日草生长在哪里？",a="末日草生长在布瑞尔墓地正北面的乱葬岗周围，那里到处都是枯萎的植物。它通过被墓葬沟渠和残留瘟疫严重污染的土壤进行传播。",al={"末日草位置","末日草在哪里","乱葬岗的草药"}},{q="末日草丛附近潜伏着什么危险？",a="乱葬岗周围的土地被腐皮豺狼人占领了。这些野蛮、满身疾病的食腐动物会猛烈攻击任何在采集草药时靠近墓地的人。",al={"末日草怪物","乱葬岗敌人","布瑞尔附近的豺狼人"}},{q="皇家药剂师协会对提瑞斯法林地的植物有什么兴趣？",a="皇家药剂师协会一直在研究整个提瑞斯法林地的植物、毒药和受瘟疫改变的真菌。采集像末日草这样的试剂是为了提炼毒素、发现炼金药方，并开发新的武器来帮助被遗忘者对抗他们的敌人。",al={"药剂师的兴趣","皇家药剂师协会 提瑞斯法","被遗忘者草药采集"}},{q="霍兰德提到的“女士”是谁？",a="这位女士指的是Sylvanas Windrunner女士，她是女妖之王，也是被遗忘者的统治者。幽暗城和布瑞尔的药剂师经常祈求她的名字，因为他们的炼金工作正式为她的命令服务。",al={"女士是谁","霍兰德 sylvanas女士","女士 幽暗城"}}},fp="9,259,20.366.0,22.333.0,50.278.0,43.266.0,26.209.0,45.201.0,66.262.0,39.211.0"}
P.entries["quest:549"] = {n="通缉：辛迪加成员",s="这条法令发布在塔伦米尔的悬赏公告板上，并得到Sylvanas Windrunner女士的授权，判处所有辛迪加成员死刑。被遗忘者试图在敦霍尔德城堡的废墟中集结的强盗威胁到部落在山脚下的行动之前，先将其彻底铲除。",h="这条法令发布在塔伦米尔的悬赏公告板上，并得到Sylvanas Windrunner女士的授权，判处所有辛迪加成员死刑。被遗忘者试图在敦霍尔德城堡的废墟中集结的强盗威胁到部落在山脚下的行动之前，先将其彻底铲除。",kw={"敦霍尔德城堡","高级执行官达萨利亚","希尔斯布莱德丘陵","辛迪加","辛迪加潜行者","辛迪加守望者","塔伦米尔","通缉"},ang={["class:Rogue"]="辛迪加在整个敦霍尔德区域部署了熟练的扒手和伏击者，使得这份契约成为潜行者同行之间的直接冲突。",["faction:Horde"]="敦霍尔德城堡曾是关押兽人的拘留要塞，承载着惨痛的记忆；现在清除占据其废墟的强盗对于部落而言具有象征意义。",["race:Undead"]="对于被遗忘者来说，清除奥特兰克贵族的残余势力是确保完全控制洛丹伦丘陵的必要举措。"},sec={{t="常备处决令",b="辛迪加突然出现在塔伦米尔东南方，这并没有逃过被遗忘者的眼睛。Sylvanas Windrunner女士和她的指挥官们并没有打算与他们谈判，也没有将他们视为流离失所的贵族，而是将辛迪加视为一种活跃的瘟疫。这份悬赏令要求立即处决，并明确指出任何被带回的俘虏都将未经审判直接处死。"},{t="敦霍尔德废墟",b="敦霍尔德城堡曾是一座臭名昭著的拘留营要塞，如今却已残破不堪，毫无秩序可言。辛迪加潜行者和守望者溜进了它崩塌的城墙和塔楼，将这座历史悠久的堡垒用作行动中心。对于高级执行官达萨利亚来说，清理废墟中这些武装强盗对于确保道路安全和保护塔伦米尔的东南入口至关重要。"}},faq={{q="是谁张贴了辛迪加人员的悬赏令？",a="该悬赏令是在Sylvanas Windrunner女士的直接授权下发布，并张贴在塔伦米尔的公告板上的。处决证明将由该定居点的军事指挥官高级执行官达萨利亚收集。",al={"谁发布了辛迪加人员的悬赏","谁想要处死辛迪加","悬赏发布者"}},{q="这些辛迪加成员位于何处？",a="他们聚集在敦霍尔德城堡破碎的石块间，该城堡位于塔伦米尔东南方的河对岸，以及主堡垒南侧的废弃岗哨塔周围。",al={"辛迪加潜行者在哪里","敦霍尔德辛迪加位置","在哪里找到守望者"}},{q="为什么被遗忘者想要处死他们而不是将其俘虏？",a="被遗忘者将辛迪加视为阴险的害虫，也是侵犯他们领土的武装威胁。该法令明确规定，任何被拘捕的成员都必须立即处决，因此抓捕他们毫无意义。",al={"为什么要杀死辛迪加","为什么不抓俘虏","达萨利亚 辛迪加"}},{q="辛迪加在敦霍尔德城堡做什么？",a="辛迪加主要由名誉扫地的奥特兰克贵族和雇佣兵组成，他们利用洛丹伦各地的废弃城堡、废墟和塔楼作为据点，袭击定居点、抢劫旅行者，并重建他们破碎的权力基础。",al={"为什么辛迪加在敦霍尔德","希尔斯布莱德的辛迪加目的","敦霍尔德城堡占领者"}},{q="清除这些辛迪加成员之后会发生什么？",a="在削减了潜行者和守望者的数量后，高级执行官达萨利亚会发布一项高优先级的悬赏，目标是他们的当地首领，即瓦尔杜斯男爵。",al={"下一个任务是什么","完成“通缉：辛迪加人员”之后","下一个悬赏"}}},fx={["6d6e03d8"]={q="高级执行官达萨利亚为什么要依靠冒险者来完成这份悬赏？",a="高级执行官达萨利亚受希尔瓦娜斯女士直接委派，负责管理塔伦米尔，但她的常驻卫戍部队已捉襟见肘，既要防御南海镇对被遗忘者领土的进攻，也要应对希尔斯布莱德地区的威胁。她会直截了当地提醒来访者，自己还有远比亲自处理每个盗贼营地更紧要的指挥事务。公开悬赏能吸引愿意效力的雇佣兵和部落勇士前来清剿敦霍尔德城堡的害虫，同时不必削弱城镇的前线防御。",al={"为什么派冒险者","达萨利亚为什么悬赏","为什么不派塔伦米尔卫兵"}}},fp="27,273,26.365.0,22.379.0,46.225.0,42.187.0,55.236.0,46.236.0,54.168.1"}
P.entries["quest:55"] = {n="摩本特·费尔",s="这个任务是与摩本特·费尔进行的最后清算。他是一位潜伏在乌鸦岭墓地上方高处的死灵法师。带着附魔圣物摩本特的克星，英雄们被悲痛欲绝的斯温·约根派遣前往，去粉碎这位巫师的结界，终结他在暮色森林西部的恐怖统治。",h="这个任务是与摩本特·费尔进行的最后清算。他是一位潜伏在乌鸦岭墓地上方高处的死灵法师。带着附魔圣物摩本特的克星，英雄们被悲痛欲绝的斯温·约根派遣前往，去粉碎这位巫师的结界，终结他在暮色森林西部的恐怖统治。",kw={"暮色森林","摩本特·费尔","摩本特的克星","死灵法师","乌鸦岭","乌鸦岭墓地","斯温·约根"},ang={["class:Paladin"]="击倒一个邪恶的死灵法师，并净化乌鸦岭让他那些非自然的结界消失，这是圣光骑士们的基本使命。",["class:Priest"]="乌鸦岭墓地的亵渎呼唤着精神上的净化，这使得驱散费尔的巫术结界成为了一种神圣的职责。",["faction:Alliance"]="击杀摩本特·费尔消除了笼罩在暮色森林人民头上最严重的威胁之一，确保了道路的安全，并慰藉了乌鸦岭等西部定居点的苦难。"},sec={{t="死者之上的栖木",b="摩本特·费尔的巢穴位于斯温营地东侧的一处岩石山脊上，那是一栋俯瞰乌鸦岭墓地全景的废弃房屋。从这个阴森的有利位置，这位死灵法师指挥着一波又一波的不死生物，恐吓着周围的森林，玷污着暮色森林的坟墓。受到强大的黑暗魔法保护，并由忠诚的不死爪牙侍奉，普通的钢铁对他来说根本无法触及。"},{t="斯温的复仇",b="当黑暗势力屠杀了他的家人并将他逼入隐居状态时，斯温·约根因悲痛而陷入疯狂。虽然斯温知道卡拉赞的神秘黑暗骑士才是他农场惨案的真正元凶，但摩本特·费尔的邪恶巫术使该地区的噩梦延续至今。击杀这位死灵法师，是斯温在这片被诅咒的土地上唯一能获得的切实正义。"},{t="摩本特的克星",b="如果没有超自然力量的援助，直接攻击摩本特·费尔无异于自杀；他的防御巫术会弹开常规攻击。为了绕过这些结界，斯温将“摩本特的克星”托付给冒险者，这件附魔神器专为瓦解死灵法师的魔法护盾而设计。一旦发动，屏障就会崩塌，让费尔暴露在致命一击之下。"}},faq={{q="摩本特·费尔是谁？",a="摩本特·费尔是一位强大的死灵法师，负责监视乌鸦岭地区出没的不死生物。他潜伏在乌鸦岭墓地上方山顶的一间房子里，利用黑暗巫术保护自己，同时折磨着暮色森林的生者。",al={"摩本特·费尔背景故事","摩本特·费尔是谁","摩本特·费尔背景"}},{q="为什么要用“摩本特的克星”来杀死他？",a="摩本特·费尔用强大的结界将自己包围，使他几乎完全免疫凡俗伤害。“摩本特的克星”是一件专门锻造用来驱散这些保护性附魔的附魔圣物，能使他暴露在伤害之中。",al={"摩本特的克星","为什么使用摩本特的克星","如何击败摩本特·费尔"}},{q="斯温·约根和摩本特·费尔有什么关系？",a="斯温失去了家人和农场，是被潜伏在暮色森林的黑暗实体所害。虽然神秘的黑暗骑士对屠杀负责，但摩本特·费尔对周边地区的死灵掌控代表了困扰暮色森林西部的溃烂邪恶，这使他成为了斯温复仇的首要目标。",al={"为什么斯温想要摩本特死","斯温·约根 摩本特·费尔","斯温复仇"}},{q="在哪里可以找到摩本特·费尔？",a="他住在斯温·约根营地正东面山坡上一栋破败的废弃房屋的顶层，俯瞰着乌鸦岭墓地的西侧。",al={"摩本特·费尔位置","摩本特·费尔在哪里","摩本特的房子"}},{q="是摩本特·费尔杀了斯温的家人吗？",a="不是。斯温的家人是被寻求埃露恩镰刀的神秘黑暗骑士屠杀的。然而，摩本特·费尔的死灵术毒害了周边地区并亵渎了暮色森林的坟墓，因此消灭他对于重获和平至关重要。",al={"摩本特杀了斯温家人吗","谁屠杀了斯温的家人"}},{q="摩本特·费尔被杀后会发生什么？",a="将“摩本特的克星”还给斯温，能给这位悲伤的隐士带来一丝安慰。虽然那些难以捉摸的黑暗骑士仍然逍遥法外，但除掉费尔打破了对乌鸦岭的死灵掌控，并巩固了冒险者在暮色森林的声望。",al={"摩本特·费尔之后","任务总结","斯温能得到平静吗"}}},fx={bd8ba8cc={q="斯温·约根为什么需要你去对付摩本特·费尔，而不是亲自出手？",a="斯温是个与世隔绝、饱受创伤折磨的隐士，悲痛与偏执几乎令他发疯。他躲在暮色森林西部边缘的临时营地里，既没有独自攻入乌鸦岭的力量，也缺少防护结界和战斗本领。摩本特·费尔掌握黑暗魔法，栖身于墓地山丘之上，周围有亡灵守卫。斯温需要一位身经百战的勇士把摩本特的克星带入死灵法师的巢穴，替他完成自己无力实现的复仇。",al={"斯温为什么需要我","斯温为什么不杀摩本特·费尔","斯温·约根为什么找我"}}},fp="11,289,24.408.0,16.390.1,14.367.0,19.237.0,44.233.0,48.301.0,31.166.0,35.250.1,40.258.1"}
P.entries["quest:550"] = {n="希尔斯布莱德之战",s="这项任务标志着被遗忘者针对希尔斯布莱德人类城镇的战役告一段落。在击溃当地的联盟部队后，你被高级执行官达萨利亚派往幽暗城的Royal Quarter，向瓦里玛萨斯呈交一份官方奖状。",h="这项任务标志着被遗忘者针对希尔斯布莱德人类城镇的战役告一段落。在击溃当地的联盟部队后，你被高级执行官达萨利亚派往幽暗城的Royal Quarter，向瓦里玛萨斯呈交一份官方奖状。",kw={"希尔斯布莱德之战","达萨利亚","希尔斯布莱德丘陵","royal quarter","密封的奖状","塔伦米尔","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="通过击退洛丹伦的联盟部队，你为部落在东部王国确保了至关重要的领土。",["race:Undead"]="向Royal Quarter报告你在希尔斯布莱德战胜生者的胜利，会赢得他们的直接嘉奖，这也肯定了你在女妖之王日益壮大的帝国中的地位。"},sec={{t="决定性的战役",b="希尔斯布莱德丘陵的战役代表了对洛丹伦南部的一场残酷斗争。在塔伦米尔协调的一系列持久打击中，部落的勇士们瓦解了该人类城镇的农夫、民兵、铁匠和市政领导。随着联盟势力的瘫痪和该领土被被遗忘者所掌控，高级执行官达萨利亚起草了一份官方奖状，以确保勇士的功绩能上达最高指挥层。"},{t="觐见恐惧魔王",b="带着达萨利亚的奖状，你将直接前往幽暗城的Royal Quarter，觐见瓦里玛萨斯。这位恐惧魔王与Sylvanas Windrunner并肩站立，负责监督整个洛丹伦的军事行动。尽管来自北方瘟疫之地（Plaguelands）的天灾军团仍然是女妖之王所面临的最大生存威胁，但保障南部边境不受残存人类飞地的侵扰，对于尚在萌芽阶段的被遗忘者国家至关重要。"}},faq={{q="这是什么任务？",a="这是宏大的希尔斯布莱德之战任务线的最后交接步骤。在完成了塔伦米尔高级执行官达萨利亚派给你的任务后，她会给你一份密封的奖状，让你亲自交给幽暗城的瓦里玛萨斯。",al={"希尔斯布莱德之战结局","希尔斯布莱德最终任务","任务550"}},{q="我该在哪里上交达萨利亚的奖状？",a="你需要将其交给瓦里玛萨斯，他正站在幽暗城Royal Quarter的Sylvanas Windrunner身边。",al={"瓦里玛萨斯在哪里","提交奖状","达萨利亚的信函提交"}},{q="为什么瓦里玛萨斯会关心希尔斯布莱德？",a="作为女妖之王的主要军事副官，瓦里玛萨斯负责监督战略防御和扩张。虽然北方的天灾军团是幽暗城面临的最大威胁，但南方的人类定居点不断骚扰着被遗忘者的防线。消除希尔斯布莱德的威胁能够保卫他们的南部边境。",al={"为什么是瓦里玛萨斯","瓦里玛萨斯在希尔斯布莱德的角色"}},{q="谁是高级执行官达萨利亚？",a="高级执行官达萨利亚是驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者高级指挥官，指挥着针对附近人类定居点的进攻行动。",al={"达萨利亚","谁发布的任务"}},{q="这个任务还会开启希尔斯布莱德的后续任务吗？",a="不会。向瓦里玛萨斯递交奖状标志着希尔斯布莱德之战故事线的正式结束，并奖励你摧毁该城镇防御的功勋。",al={"希尔斯布莱德之战后的下一个任务","任务550之后的内容"}},{q="被遗忘者当初为什么要攻击希尔斯布莱德？",a="希尔斯布莱德镇是洛丹伦最后一批有组织的人类立足点之一。它与联盟结盟，其民兵和地理位置对塔伦米尔以及幽暗城的南部入口构成了直接的军事威胁。",al={"为什么要攻击希尔斯布莱德","希尔斯布莱德背景故事"}}},fx={["8522c300"]={q="高级执行官达萨利亚为什么要送出这份嘉奖状？",a="你在希尔斯布莱德丘陵的残酷战役中英勇奋战，坚持不懈。高级执行官达萨利亚希望被遗忘者的高层指挥部在幽暗城正式表彰你在战场上的英勇表现。她派你亲自将密封的嘉奖状交给瓦里玛萨斯，以确保领导层认可这位能力出众的勇士——你在南部前线的果断打击瓦解了人类的抵抗。",al={"为什么送嘉奖状","达萨利亚的动机","为什么送去见瓦里玛萨斯"}}},fp="19,252,19.464.0,27.452.0,19.247.0,51.112.0,42.304.0,31.181.0,54.159.0,61.236.0"}
P.entries["quest:5501"] = {n="集骨者",s="在凄凉之地的考米克小屋，地精比布里·弗斯巴克坚信科多兽骨头即将改变世界。他需要从小屋南边的科多兽坟场收集十根骨头，并且承诺会给予回报。",h="在凄凉之地的考米克小屋，地精比布里·弗斯巴克坚信科多兽骨头即将改变世界。他需要从小屋南边的科多兽坟场收集十根骨头，并且承诺会给予回报。",kw={"比布里·弗斯巴克","骨头收集者","凄凉之地","goblin'preneur","科多兽骨头","科多兽坟场","考米克小屋","葬影村"},sec={{t="古老骸骨中的财富",b="比布里坚称这间小屋坐落在一座金矿上。顾客们用科多兽骨头制作家具、乐器甚至炸药。比布里派你去南边的科多兽坟场带回十根骨头，并承诺给予回报。"},{t="在路上的商队",b="一支商队会路过并收走比布里的科多兽骨头，然后将它们卖到葬影村。商队随时都会到，而比布里还差十根骨头就能达成所谓的职业巅峰。"},{t="比布里的远大梦想",b="当骨头送达时，比布里幻想着家乡的伙伴们看到他的脸登上《Goblin'preneur》杂志，并想象着自己成为世界上最富有的地精。比布里还想起一位体育老师曾说他永远也不会有什么成就。"}},faq={{q="比布里·弗斯巴克是谁？",a="比布里·弗斯巴克是凄凉之地考米克小屋的一名地精，他坚信科多兽骨头是一座金矿，并想要收集十根骨头。",al={"骨头收集者任务发布者","比布里·弗斯巴克","考米克小屋的地精"}},{q="为什么比布里需要科多兽骨头？",a="比布里的顾客会将科多兽骨头制作成家具、乐器，甚至炸药。",al={"科多兽骨头的用途","为什么要科多兽骨头"}},{q="比布里收集到科多兽骨头后，它们会被送到哪里？",a="一支商队会顺路收走比布里的科多兽骨头，然后将它们在葬影村出售。",al={"骨头被送到哪","商队目的地"}},{q="在哪里可以找到科多兽骨头？",a="比布里让你去科多兽坟场，它位于凄凉之地的考米克小屋南边。",al={"科多兽骨头位置","哪里寻找科多兽骨头"}},{q="考米克小屋在哪里？",a="考米克小屋位于凄凉之地，在科多兽坟场的北边。",al={"考米克小屋位置","比布里在哪里"}}},fp="14,222,20.243.0,20.174.0,19.260.1,26.130.0,32.102.0,50.89.0,34.85.0,22.57.0"}
P.entries["quest:5502"] = {n="部落孤儿的看护者",s="“部落的守护者”在儿童周结束时，将Grunth送回了位于奥格瑞玛的荣誉谷的孤儿监护员巴特维尔身边。在与他的监护人看遍世界之后，这位年轻的孤儿希望自己也能成为一名英雄。",h="“部落的守护者”在儿童周结束时，将Grunth送回了位于奥格瑞玛的荣誉谷的孤儿监护员巴特维尔身边。在与他的监护人看遍世界之后，这位年轻的孤儿希望自己也能成为一名英雄。",kw={"巴特维尔","儿童周","grunth","奥格瑞玛","孤儿","兽人孤儿哨","valley of honor"},ang={["faction:Horde"]="对于部落而言，力量不仅是武力上的强悍，更是保护和扶持那些终将扛起大酋长旗帜的弱者的共同意志。",["race:Orc"]="兽人文化珍视勇气与荣誉，而向Grunth这样的孤儿展现同情心，正是萨尔试图在新部落中灌输的崇高精神的体现。"},sec={{t="孤儿的告别",b="在经历了儿童周的冒险之后，Grunth感谢他的监护人让他看到了远超他梦想的景象。铭记着父母关于超越苦难的教诲，他说他希望像The Adventurer一样成为一名英雄。他最后的请求是回到家，并向监护员讲述他们在一起的时光。"},{t="回到荣誉谷",b="回到荣誉谷的孤儿院，冒险者们将他们照顾的孩子送回了孤儿监护员巴特维尔的身边。在新部落中，承担照顾幼小的责任被视为一项重大的义务，因为战争让无数儿童失去了父母。巴特维尔称赞你的同情心是部落英雄真正的衡量标准，而Grunth与你分道扬镳，并赠予你一件珍爱的宠物，以确保你记住在旅途中建立的羁绊。"}},faq={{q="这个任务的目的是什么？",a="这个任务是部落儿童周庆典的终章。将Grunth和兽人孤儿哨带回荣誉谷的孤儿监护员巴特维尔那里。",al={"部落的守护者概述","部落儿童周结束"}},{q="Grunth是谁？",a="Grunth是一名居住在荣誉谷奥格瑞玛孤儿院的兽人少年。在儿童周期间，他会与一位部落勇士结伴，由这位勇士带着他游历卡利姆多，去见识那些传奇人物和宏伟壮丽的景色。",al={"谁是兽人孤儿","grunth背景故事"}},{q="我需要给监护员带回什么？",a="当Grunth准备回家时，将兽人孤儿哨带回给孤儿监护员巴特维尔。",al={"归还孤儿哨","归还grunth哨子"}},{q="谁在管理奥格瑞玛的孤儿？",a="孤儿监护员巴特维尔管理着位于荣誉谷的奥格瑞玛孤儿院，她致力于庇护和抚养那些在部落战争中失去双亲的孤儿。",al={"部落孤儿监护员","谁运营孤儿院"}},{q="为什么Grunth想回家？",a="他的儿童周外出活动已经结束，他想向监护员讲述这些冒险经历，以及带他一同前往的那位善良的监护人。",al={"grunth回家","儿童周告别"}},{q="为什么儿童周对部落很重要？",a="几十年来与恶魔、人类和半人马的持续战争，让无数部落的孩子失去了家庭。儿童周是战士们放下战场、向杜隆塔尔及其他地区的未来一代致敬的时刻。",al={"儿童周背景故事","为什么部落要照顾孤儿"}}},fp="21,175,20.289.0,27.362.0,34.159.0,14.196.0,35.96.0,38.159.0,36.136.0,46.235.0"}
P.entries["quest:551"] = {n="附有魔法的羊皮纸",s="羊皮纸上施加的法术使其文字无法辨认，只有顶端的一个词除外：Nagaz。你需要把它交给南海镇的博学者迪布斯。",h="羊皮纸上施加的法术使其文字无法辨认，只有顶端的一个词除外：Nagaz。你需要把它交给南海镇的博学者迪布斯。",kw={"奥特兰克","迪布斯","附有魔法","nagaz","羊皮纸","南海镇"},sec={{t="被法术笼罩的羊皮纸",b="羊皮纸上施加的法术使其上的文字无法破译。只有顶端的一个词清晰可见，那就是Nagaz。你需要把它交给南海镇的博学者迪布斯。"},{t="迪布斯的见解",b="迪布斯询问这是否又是那些加密的笔记。迪布斯希望能破译所有从奥特兰克漂流出来的奇怪文字碎片，但他承认自己缺乏相关的知识。"}},faq={{q="羊皮纸上写着什么？",a="一道法术阻止了文字被阅读，只留下了顶端的一个词：Nagaz。",al={"附有魔法的羊皮纸上写了什么","羊皮纸文字","附有魔法的羊皮纸上的词汇"}},{q="谁应该查看这张羊皮纸？",a="南海镇的博学者迪布斯，他负责收集从山里搜集来的知识碎片。",al={"博学者迪布斯","迪布斯是谁","南海镇博学者"}}},fp="25,145,24.191.0,22.171.1,33.84.0,29.88.0"}
P.entries["quest:552"] = {n="赫尔库拉的复仇",s="塔伦米尔的学徒塞万德想要为赫尔库拉大师复仇。赫尔库拉是一位即将成为巫妖的伟大巫师，他被一群发现了他仪式巢穴的人类暴徒杀害了。在向南海镇复仇之前，塞万德需要赫尔库拉的魔棒，那东西肯定被那里的雪人拿走了。",h="塔伦米尔的学徒塞万德想要为赫尔库拉大师复仇。赫尔库拉是一位即将成为巫妖的伟大巫师，他被一群发现了他仪式巢穴的人类暴徒杀害了。在向南海镇复仇之前，塞万德需要赫尔库拉的魔棒，那东西肯定被那里的雪人拿走了。",kw={"奥特兰克","赫尔库拉","希尔斯布莱德","巫妖","魔棒","南海镇","塔伦米尔","塞万德","雪人"},ang={["faction:Horde"]="这是为部落冒险者准备的任务；塔伦米尔的塞万德是发布任务的人。"},sec={{t="被打断的大师",b="赫尔库拉大师在即将成为巫妖时，被一群发现他在山中仪式巢穴的人类暴徒杀害。他们随后将他的尸体埋在了南海镇的墓地里。他的学徒塞万德认为这种对一位伟大巫师的蔑视是不可接受的，并发誓要让复仇之雨降临在南海镇。"},{t="失踪的魔棒",b="塞万德说首先需要赫尔库拉的魔棒。雪人已经占领了那个仪式巢穴，塞万德确信其中一只野兽拿走了魔棒。该地区的雪人数量非常多，想要找到它会很困难。无草洞和达隆山都是可以找到它们的地方。"}},faq={{q="赫尔库拉大师是谁？",a="一位即将成为巫妖的伟大巫师，被一群在山上发现了他仪式巢穴的人类暴徒杀害。他的尸体被埋在南海镇的墓地里。",al={"赫尔库拉是谁","赫尔库拉背景故事","赫尔库拉历史"}},{q="为什么学徒塞万德想要赫尔库拉的魔棒？",a="塞万德是赫尔库拉的学徒，他计划向南海镇复仇，并声称首先需要那根魔棒。",al={"为什么要魔棒","赫尔库拉的魔棒用途","塞万德目标"}},{q="魔棒去哪了？",a="雪人已经占领了赫尔库拉的仪式巢穴，塞万德确信其中一只雪人拿走了魔棒。在无草洞和达隆山等地都可以找到雪人。",al={"魔棒在哪里","雪人怎么拿到魔棒","魔棒位置"}},{q="学徒塞万德在哪里？",a="在希尔斯布莱德丘陵的塔伦米尔。",al={"塞万德位置","赫尔库拉的复仇任务提交地点","学徒塞万德"}}},fp="18,290,20.368.0,15.276.0,24.164.0,45.110.0,21.156.0,33.43.0"}
P.entries["quest:553"] = {n="赫尔库拉的复仇",s="学徒塞万德将赫尔库拉魔棒交给你。赫尔库拉为他最强大的法术制作了三座仪式火堆，必须用每一座火堆为魔棒充能，然后将其插在南海镇的赫尔库拉之墓上。",h="学徒塞万德将赫尔库拉魔棒交给你。赫尔库拉为他最强大的法术制作了三座仪式火堆，必须用每一座火堆为魔棒充能，然后将其插在南海镇的赫尔库拉之墓上。",kw={"奥特兰克","阿泽尔","达隆山","无草洞","赫尔库拉","希尔斯布莱德","南海镇","塞万德","乌泽尔","维拉兹"},sec={{t="三道火焰",b="赫尔库拉为他最强大的法术制作了三座仪式火堆，魔棒必须从每一座火堆中汲取能量。阿泽尔和维拉兹的火焰位于丘陵洞穴内，达隆山的雪人洞穴里。第三道火焰，也就是乌泽尔之焰，位于洞穴上方的一处小洞穴中，在更北边的群山里，靠近无草洞。"},{t="南海镇的墓地",b="一旦魔棒从全部三道火焰中充能完毕，就要把它插在南海镇的赫尔库拉之墓上，这是一个守卫森严的人类城镇。墓地位于城镇的东北角，靠近河边，坟墓则位于墓地的东南角。"},{t="仪式之后",b="当充能后的魔棒被插入坟墓时，地面传来一阵轰鸣，赫尔库拉复活了，在南海镇的墓地游荡并攻击附近的人。"}},faq={{q="三座仪式火堆在哪里？",a="阿泽尔之焰和维拉兹之焰位于希尔斯布莱德丘陵的达隆山雪人洞穴中，也就是丘陵洞穴内。乌泽尔之焰位于那些洞穴上方的一处小洞穴中，在奥特兰克山脉靠近无草洞的更北边的山区里。",al={"火焰位置","阿泽尔之焰的位置","乌泽尔之焰的位置","寻找仪式火堆"}},{q="赫尔库拉的坟墓在哪里？",a="在南海镇，一个守卫森严的人类城镇。墓地位于城镇的东北角，靠近河边，坟墓则位于墓地的东南角。",al={"赫尔库拉之墓位置","坟墓在哪里","南海镇墓地"}},{q="谁提供了赫尔库拉魔棒？",a="学徒塞万德给了你这根魔棒。",al={"谁提供魔棒","任务提供者","学徒塞万德"}},{q="这个任务之前发生了什么？",a="“赫尔库拉的复仇”，在该任务中，学徒塞万德需要找到赫尔库拉魔棒。塞万德是赫尔库拉的学徒，赫尔库拉被一群人类暴民杀害，并被埋葬在南海镇的墓地里。",al={"前序任务","赫尔库拉任务线第一部分"}}},fp="18,207,16.334.0,23.261.0,16.172.1,46.250.0,26.173.0,33.34.0,28.192.0"}
P.entries["quest:554"] = {n="解码高手",s="博学者迪布斯让你带着附有魔法的羊皮纸前往铁炉堡，希望勘察员塔伯斯·雷矛这位解密与破译大师能弄懂其中的含义。",h="博学者迪布斯让你带着附有魔法的羊皮纸前往铁炉堡，希望勘察员塔伯斯·雷矛这位解密与破译大师能弄懂其中的含义。",kw={"解密","迪布斯","附有魔法的羊皮纸","铁炉堡","勘察员总部","雷矛"},sec={{t="解密大师",b="在完成“附有魔法的羊皮纸”任务后，迪布斯让你把东西带给正在铁炉堡勘察员总部潜心研究的勘察员塔伯斯·雷矛。迪布斯让你提一下是他派你来的，因为他最近给雷矛介绍了不少活计。"},{t="时间问题",b="雷矛发现羊皮纸上覆盖着一道非常复杂、交织精密的法术。他说他可以将其解开，但需要时间，而他的时间很宝贵，所以他提出向你购买。一旦你同意，他说他相信除了自己以外，没有学者有能力翻译它，并承诺如果其中的内容证明很有趣，就会派人去找你。"}},faq={{q="是谁派你去找勘察员塔伯斯·雷矛的？",a="博学者迪布斯，他称雷矛为解密与破译大师。",al={"谁给予任务","任务发布者","博学者迪布斯任务"}},{q="在哪里可以找到勘察员塔伯斯·雷矛？",a="他在铁炉堡的勘察员总部里做研究。",al={"雷矛位置","雷矛在哪里","勘察员总部"}},{q="为什么羊皮纸难以阅读？",a="上面有一道法术阻止了文字被破译，只有顶部的名字“Nagaz”可以被读出。",al={"为什么附有魔法的羊皮纸","羊皮纸法术","为什么解密"}},{q="这一步之前是什么？",a="它是“附有魔法的羊皮纸”的后续，该任务将附魔的羊皮纸带给了迪布斯。",al={"前置任务","任务链开始","前置条件"}}},fp="23,162,22.254.0,16.345.1,38.77.0,40.60.0,39.111.0,28.85.0"}
P.entries["quest:5541"] = {n="海格纳的弹药",s="枪匠海格纳·重枪的弹药和火药快用完了，他正为在安威玛尔外练习的火枪手提供补给。一箱丢失的弹药在灰色洞穴附近的雪地荒野中被遗弃了，当时一名信使被饥饿的温迪戈赶跑了。",h="枪匠海格纳·重枪的弹药和火药快用完了，他正为在安威玛尔外练习的火枪手提供补给。一箱丢失的弹药在灰色洞穴附近的雪地荒野中被遗弃了，当时一名信使被饥饿的温迪戈赶跑了。",kw={"弹药","安威玛尔","冷脊谷","灰色洞穴","海格纳","罗斯洛·鲁治","重枪","温迪戈"},ang={["class:Hunter"]="冷脊谷的每一位神枪手都对海格纳的店铺了如指掌；让他的货架上储备充足的新鲜火药和弹丸，能确保你不会在面对荒野时手里拿着一把空枪。",["profession:Engineering"]="矮人的枪械和迫击炮需要精磨的火药和统一规格的弹丸，这使得重枪的库存对于当地的技师和炮手来说至关重要。",["race:Dwarf"]="矮人的手工艺依赖于安威玛尔的锻造铺与像重枪这样的一线枪匠之间坚不可摧的供应链。"},sec={{t="信使的逃亡",b="位于钢架补给站的罗斯洛·鲁治为整个丹莫罗的商人们维持着稳定的补给线，但山谷里的野生生物经常进行干扰。他最新运送的一批重型弹药从未抵达海格纳·重枪的路边工坊。在被称为灰色洞穴的洞穴系统附近露营时，惊恐的信使遭遇了当地的温迪戈并落荒而逃，将沉重的木箱丢弃在雪地里。"},{t="火药与弹丸",b="海格纳·重枪经营着一家枪械店，就坐落在通往安威玛尔的主路旁。他锻造铺外的空地上总是挤满了铁炉堡的火枪手、山地探险队员和矮人迫击炮小队，他们来到这里校准瞄准镜并进行实弹演习。如果没有来自罗斯洛这类供应商提供的稳定火药和铅弹补给，火枪手们的射击训练很快就会被迫中止。"}},faq={{q="弹药箱是在哪里丢失的？",a="罗斯洛·鲁治受惊的信使在灰色洞穴外露营时丢掉了这批货物，这是一个位于卡拉诺斯西南方雪山中、被温迪戈占据的洞穴。",al={"弹药位置","重枪的弹药在哪里","货箱位置"}},{q="海格纳·重枪是谁？",a="海格纳·重枪是一位矮人枪匠，在安威玛尔附近的路边经营着一家武器店。他为在附近演习的山地探险队员、猎人和攻城小队提供火药、子弹和枪械。",al={"海格纳是谁","重枪","海格纳·重枪"}},{q="信使为什么会被赶跑？",a="信使犯了个错误，他在灰色洞穴附近露营，那是游荡在卡拉诺斯西南方山丘上的残暴且具有领地意识的温迪戈的巢穴。",al={"为什么信使逃跑","温迪戈袭击","信使的故事"}},{q="为什么海格纳·重枪的弹药告罄了？",a="矮人火枪手和迫击炮小队在海格纳的店铺附近不断进行打靶演习，消耗了大量的火药和铅弹，使得他的库存一直供不应求。",al={"为什么弹药不足","重枪弹药用尽"}},{q="罗斯洛·鲁治是谁？",a="罗斯洛·鲁治是钢架补给站的一名矮人工程学供应商，他的生意就是向海格纳·重枪运送弹药。",al={"罗斯洛·鲁治","罗斯洛是谁"}},{q="找回来的弹药会被雪损坏吗？",a="矮人的弹药通常包装在沉重的、密封防风雨的木箱中，以确保黑火药即使在丹莫罗零度以下的暴风雪中也能保持干燥并随时可以使用。",al={"弹药被雪毁坏","受潮的火药"}}},fx={["76205b16"]={q="罗斯洛·鲁治为什么需要你送去这批弹药？",a="罗斯洛·鲁治以钢架补给站为据点，为丹莫罗各地的商贩供货。海格纳·重枪正等着一批迟到的货物，好为当地的步枪手和迫击炮小队补充练习弹药。一名信使遭遇温迪戈袭击营地后惊慌逃走，把货箱丢下了，导致罗斯洛未能履行生意约定，也让这位重要客户迟迟拿不到货，直到你找回货箱。",al={"罗斯洛为什么在意","罗斯洛·鲁治的动机","为什么要送弹药"}},c1dcb566={q="海格纳的弹药有什么用途？",a="货箱里装的是新弹药，原本要送到通往安威玛尔的路旁、海格纳·重枪经营的店铺。矮人步枪手和迫击炮小队经常在附近训练，弹药消耗很快，他们依靠海格纳补满火药囊和弹药袋。",al={"海格纳的弹药是什么","海格纳的货箱用途","为什么需要弹药"}}},fp="19,236,18.424.0,15.410.0,30.174.0,25.197.0,31.148.0,43.156.0,20.122.0,44.165.0"}
P.entries["quest:5545"] = {n="木材危机",s="东谷伐木场的管理员莱琳正面临一项迫在眉睫的木材交付截止日期，已经没有时间可以浪费了。当地的熊和狼将她的劳工从刚砍伐的木材旁驱赶走，导致成捆的珍贵木材被遗弃在北部的森林里。她寄希望于热心的冒险者，希望他们能进入野兽出没的森林，在合同作废之前把木材取回来。",h="东谷伐木场的管理员莱琳正面临一项迫在眉睫的木材交付截止日期，已经没有时间可以浪费了。当地的熊和狼将她的劳工从刚砍伐的木材旁驱赶走，导致成捆的珍贵木材被遗弃在北部的森林里。她寄希望于热心的冒险者，希望他们能进入野兽出没的森...",kw={"熊","一捆木柴","瑞尼尔副队长","东谷","艾尔文森林","伐木场","管理员莱琳","木材","狼"},ang={["class:Hunter"]="在充满掠食者的树林中穿行以回收补给，同时应对危险的当地野兽，这直接考验着追踪者的核心生存本能。",["faction:Alliance"]="确保从东谷运出木材，能保障暴风城的重建和各地区哨所的维护工作得以持续，避免造成代价高昂的补给中断。"},sec={{t="迫在眉睫的截止日期",b="东谷伐木场为暴风城王国的重建和防御工作提供了至关重要的木材。在荒野边缘进行商业伐木作业充满了危险，管理员莱琳目前正陷入困境。由于遭到干扰，她的团队在一批关键的木材运输任务上落后于进度，时间正在一分一秒地流逝。"},{t="林中的掠食者",b="问题不在于没有砍伐的树木，而在于当地具有攻击性的野生动物。伐木场北面饥饿的狼群和领地意识极强的熊赶走了伐木工，迫使他们丢下了散落在林地上的、捆扎整齐的木材。虽然镇上的当局已经获悉了野兽的威胁，但莱琳等不起卫兵来清理该区域，她必须雇佣路过的英雄冲进去收集木材。"}},faq={{q="管理员莱琳是谁？",a="管理员莱琳负责管理艾尔文森林东部东谷伐木场的日常运营。她监管伐木团队，并确保木材的运输能够满足暴风城和当地定居点的需求。",al={"管理员莱琳","莱琳","东谷管理员"}},{q="为什么木材会被遗弃在森林里？",a="工人们在野熊和出没的狼群将他们赶出林间空地之前，已经砍伐、修整并将原木捆成了木束。工人们出于对生命的恐惧，在没有搬运货物的情况下逃回了伐木场。",al={"为什么木材被遗弃","被遗弃的木材","森林木材"}},{q="为什么莱琳提到了瑞尼尔副队长？",a="莱琳声称她就这些具有攻击性的掠食者一事联系了瑞尼尔副队长。令人好奇的是，瑞尼尔副队长驻扎在远隔整个艾尔文森林的西泉要塞，这表明要么消息是通过官方卫兵渠道传递的，要么是该地区的治安力量在整个省份内显得捉襟见肘。",al={"瑞尼尔副队长与莱琳","为什么是瑞尼尔副队长","瑞尼尔的关系"}},{q="这些木材是送到哪里去的？",a="东谷伐木场为整个王国的各项工作提供木材，从重建城镇基础设施到加固栅栏和桥梁。错过交货期限会损害当地经济，并导致整个艾尔文地区的建筑项目停滞。",al={"谁需要这些木材","木材交付","木材用途"}},{q="为什么伐木工不能自己去收集这些木材？",a="伐木工只是普通的劳工，他们的装备是为了砍树，而不是为了与野生掠食者战斗。在被具有攻击性的狼和熊袭击并驱散后，没有一个工人愿意冒着生命危险手无寸铁地回到那片灌木丛中。",al={"为什么伐木工害怕","为什么不是伐木工去","伐木工与狼群"}},{q="在哪里可以找到这些木材？",a="成捆的木材就散落在东谷伐木场正北方的林地区域，那里是工人们在被当地野兽赶走前工作的地方。",al={"木材位置","木束在哪里","寻找木束"}}},fp="19,187,18.206.0,23.235.0,25.175.0,39.131.0,38.220.0,27.187.0,50.166.0,39.134.0"}
P.entries["quest:555"] = {n="海龟汤",s="南海镇的厨师杰森引以为傲地宣称，他烹饪的佳肴是暴风城以北最棒的，但最近的动荡切断了他新鲜啮齿龟肉的来源。为了让那道著名的舒缓龟汤重回旅店的菜单，他请求具有厨艺天赋的旅行者们前往达拉然和洛丹米尔湖附近那片危险的北部水域进行冒险。",h="南海镇的厨师杰森引以为傲地宣称，他烹饪的佳肴是暴风城以北最棒的，但最近的动荡切断了他新鲜啮齿龟肉的来源。为了让那道著名的舒缓龟汤重回旅店的菜单，他请求具有厨艺天赋的旅行者们前往达拉然和洛丹米尔湖附近那片危险的北部水域进行...",kw={"厨师杰森","烹饪","达拉然","希尔斯布莱德","洛丹米尔湖","啮齿龟","舒缓龟汤","南海镇","龟肉"},ang={["faction:Alliance"]="恢复南海镇的舒适生活有助于保持当地的士气，因为该镇目前正处于孤立无援的境地，必须独自面对敌对的辛迪加歹徒和被遗忘者的扩张。",["profession:Cooking"]="厨师杰森只会与同行分享他的技艺，作为报酬，他会奖励你制作舒缓龟汤的配方。",["race:Human"]="对于从南部王国前来的旅行者来说，杰森的厨艺是在这饱经战火的北方地区难得的一口家乡味道与热情款待。"},sec={{t="北方的美味",b="南海镇是洛丹伦境内为数不多依然完好的联盟沿海城镇之一，在日益严峻的地区冲突中自豪地坚守着平民生活。厨师杰森声称他的厨艺足以匹敌暴风城以北的任何旅店，据说还有顾客为了品尝他的招牌菜——舒缓龟汤，甚至不远万里从暮色森林的夜色镇赶来。这种浓郁的滋补汤品完全依赖于产自北部山脉河流与湖泊中的啮齿龟的新鲜肉质。"},{t="洛丹米尔的危机",b="在局势平稳的年月里，杰森总是亲自前往达拉然以北的洛丹米尔湖东岸猎捕龟肉。然而，日益紧张的局势、凶猛的野生动物、辛迪加以及被遗忘者的入侵，使得镇上的普通居民在城外觅食变得九死一生。为了让锅里的汤继续熬煮并满足顾客，这位厨师不得不依赖那些愿意在河岸和北岸潜伏的啮齿龟身上采集肉类的全副武装的冒险者。"}},faq={{q="谁提供了关于舒缓龟汤的任务？",a="位于希尔斯布莱德丘陵的联盟沿海城镇南海镇，这里的烹饪大师厨师杰森会向来访的厨师们发出这项请求。",al={"谁给予舒缓龟汤任务","我在哪里开始舒缓龟汤任务","厨师杰森任务"}},{q="为什么厨师杰森需要外人帮忙收集龟肉？",a="杰森过去常亲自在达拉然和洛丹米尔湖附近猎捕啮齿龟，但由于政治动荡和凶猛野兽的肆虐，该地区变得极其危险，迫使他不得不雇佣冒险者。",al={"为什么杰森无法获得肉类","为什么杰森需要龟肉"}},{q="啮齿龟在这一地区哪里可以找到？",a="啮齿龟栖息在流经希尔斯布莱德丘陵与奥特兰克山脉之间的淡水河流沿岸，以及达拉然以北的洛丹米尔湖岸边。",al={"龟肉地点","啮齿龟在哪里","去哪里刷龟肉"}},{q="接取此任务需要学习烹饪技能吗？",a="是的。厨师杰森只会向那些已经习得烹饪专业的旅行者分享此请求和他的烹饪秘诀，尽管接取任务并不需要特定的技能等级。",al={"是否需要烹饪","烹饪专业要求","任何人都能接取舒缓龟汤任务吗"}},{q="为什么南海镇的饮食如此出名？",a="厨师杰森夸口说南海镇提供着暴风城以北最顶级的佳肴，而他那著名的龟汤据说吸引了远至夜色镇的食客前来品尝。",al={"南海镇食物","为什么杰森出名","去夜色镇的旅行与汤"}},{q="厨师杰森感叹的动荡是指什么？",a="希尔斯布莱德和奥特兰克正陷入公开的冲突之中，来自北方的被遗忘者、徘徊在废墟中的辛迪加歹徒以及因洛丹伦陷落而流离失所的野生捕食者，让平民的出行变得危机四伏。",al={"希尔斯布莱德动荡","为什么现在很危险","什么动荡"}}},fx={d8a3c1e1={q="厨师杰森为什么要你做这件事？",a="厨师杰森对南海镇的美食声誉极为自豪，声称镇上有暴风城以北最精美的佳肴。他秘不外传的安抚海龟浓汤配方闻名遐迩，连夜色镇的旅人也会慕名前来；但近期的地区冲突切断了他的食材供应。收集所需的龟肉，就能让他重新端出招牌菜，为饱受困扰的镇民带来慰藉。",al={"为什么做海龟浓汤","厨师杰森的动机","杰森为什么要龟肉"}},bb599998={q="这些龟肉有什么用？",a="龟肉是厨师杰森秘制安抚海龟浓汤的关键食材。采集者通常会从北方水域的钳嘴龟身上获取龟肉，例如洛丹米尔湖一带，这样厨师就能再次熬制这道深受喜爱的地方特色菜。",al={"龟肉有什么用途","为什么要龟肉","龟肉的用途"}}},fp="22,334,19.495.0,18.451.0,48.147.0,61.203.0,46.175.0,47.178.0,35.180.0,39.212.0"}
P.entries["quest:556"] = {n="石雕",s="“石质徽记”是塔伦米尔的看守者贝瓦里尔发布的一项部落任务，要求回收从奥特兰克地区的达拉然特工手中获取的魔法束缚神器。被遗忘者试图研究达拉然法师奴役和指挥强大元素生物所使用的奥术手段。收集这些惰性徽记是法师进行元素征服研究的基础。",h="“石质徽记”是塔伦米尔的看守者贝瓦里尔发布的一项部落任务，要求回收从奥特兰克地区的达拉然特工手中获取的魔法束缚神器。被遗忘者试图研究达拉然法师奴役和指挥强大元素生物所使用的奥术手段。收集这些惰性徽记是法师进行元素征服研究...",kw={"奥特兰克山脉","束缚","达拉然","元素","希尔斯布莱德丘陵","看守者贝瓦里尔","虚空之光法师","石质徽记","塔伦米尔","用旧的石雕"},ang={["class:Mage"]="达拉然的召唤师以将元素束缚于其意志之下而闻名；检查这些徽记可以揭示人类法师是如何将异界之灵与物质焦点相连的。",["class:Shaman"]="虽然萨满通过互惠契约来尊崇元素，但达拉然的巫师使用奥术徽记来支配和奴役它们，这种做法与精神和谐背道而驰。",["race:Undead"]="对于塔伦米尔的被遗忘者来说，解开达拉然的奥术秘密对于保护洛丹伦免受潜伏在达拉然城墙之外的人类法师的威胁至关重要。"},sec={{t="奥术征服",b="达拉然的法师长期以来对元素实体拥有强大的控制力，他们使用特殊的导管和附魔焦点，将来自其他维度的生物束缚为奴仆。虽然城市本身仍在重建，但其特工和残余部队在周边地区巡逻，依靠元素作为劳动力和防御性突击部队。正在为塔伦米尔的被遗忘者工作的奥术研究员虚空之光法师，试图解析达拉然用于强制这些实体服从的精确法术。"},{t="惰性样本收集",b="看守者贝瓦里尔并没有立即要求强大的、不稳定的魔法器具，而是指示特工去获取磨损且褪色的徽记。通过从驻扎在周边地区和附近拘留营的达拉然人员手中收集这些耗尽能量的护身符，虚空之光法师可以安全地分析残留的附魔，而不会冒着失控的位面反噬的风险。这些饱经风霜的徽记为测试更强大的束缚机制提供了所需的基础理论知识。"}},faq={{q="石质徽记有什么用途？",a="达拉然的巫师制作并携带这些石质徽记作为魔法焦点，以指挥和征服元素，强迫来自其他维度的生物充当守卫、哨兵和劳工。",al={"石质徽记的目的","达拉然巫师为何持有石质徽记","徽记的作用"}},{q="为什么虚空之光法师特别需要磨损的徽记？",a="磨损的石质徽记保留了达拉然束缚法术的基础魔法矩阵，同时其活跃的奥术能量已经消退。这使得虚空之光法师在进行初步实验时，可以更安全地对其进行解剖和研究，而不必担心猛烈的元素反击或爆炸性的魔法反馈。",al={"为何需要磨损的石质徽记","为何不要活跃的徽记"}},{q="谁是看守者贝瓦里尔？",a="看守者贝瓦里尔是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者任务发布者。他协助研究员虚空之光法师从附近地区获取魔法神器和试剂。",al={"贝瓦里尔","谁发布石质徽记任务"}},{q="达拉然部队在哪里持有这些徽记？",a="这些徽记由占据希尔斯布莱德西部和奥特兰克山脉之间前沿地带的达拉然巫师及其人员携带，特别是在达拉然本身和附近旧兽人拘留营遗址附近。",al={"石质徽记的寻找位置","达拉然部队的位置"}},{q="交付这些徽记后会发生什么？",a="当贝瓦里尔检查过这些惰性样本后，虚空之光法师会将他的研究从理论学习推进到物理收容阶段，委托代理人直接从元素生物自身那里获取更重的“束缚护腕”。",al={"石质徽记后的后续","石质徽记后续任务"}},{q="为什么部落要研究达拉然的魔法？",a="被遗忘者认为，洛丹伦地区幸存的达拉然法师是一个直接的领土和魔法威胁。破译他们的奥术手段可以让被遗忘者的施法者反制肯瑞托的行动，保护他们的边界，并有可能将元素力量转化为自己的优势。",al={"部落为何想要达拉然魔法","被遗忘者对达拉然的兴趣"}}},fx={["618b6456"]={q="看守者贝瓦里尔为什么要收集这些石制徽记？",a="看守者贝瓦里尔受塔伦米尔的一名被遗忘者法师玛格斯·虚空之光委托，后者想要破解达拉然的奥术技艺。肯瑞托法师以精通异次元元素生物而闻名，并能借助附魔石块操控它们。虚空之光打算研究这些徽记，揭开其中的束缚奥秘，从而增进被遗忘者对元素控制的了解。",al={"看守者贝瓦里尔为什么要石制徽记","贝瓦里尔收集石制徽记的动机","为什么收集破旧的石制徽记"}},["4e88982b"]={q="守卫着收容所营地的达拉然部队是谁？",a="你奉命对付占据希尔斯布莱德以西、奥特兰克边境沿线废弃收容所营地及周边土地的肯瑞托法师和守卫。第三次战争结束、达拉然毁灭后，这些残存的人类势力仍顽固地盘踞一方，利用元素仆从和结界守护领地，抵御被遗忘者及其他地区威胁。",al={"希尔斯布莱德的达拉然部队是谁","达拉然法师为什么在收容所营地","达拉然为何要石制徽记"}}},fp="12,374,18.535.0,24.482.1,35.194.0,55.302.0,24.205.0,50.231.0,46.231.1,42.296.0"}
P.entries["quest:5561"] = {n="诱捕科多兽",s="在凄凉之地的瑟卡布斯库的营地，斯米德·瑟卡布斯库正在等待一支商队，他需要五头被驯服的科多兽来做准备。你带着斯米德的科多兽诱引器去寻找那些远古、年迈和濒死的科多兽，并将被它驯服的科多兽带回营地。",h="在凄凉之地的瑟卡布斯库的营地，斯米德·瑟卡布斯库正在等待一支商队，他需要五头被驯服的科多兽来做准备。你带着斯米德的科多兽诱引器去寻找那些远古、年迈和濒死的科多兽，并将被它驯服的科多兽带回营地。",kw={"比布利","寇克","凄凉之地","科多兽","科多兽诱引器","里格","瑟卡布斯库的营地","斯米德·瑟卡布斯库"},sec={{t="路上的商队",b="比布利认为凄凉之地没有别的地精懂得如何赚钱。斯米德·瑟卡布斯库却不这么认为：唯一愿意在这片土地上冒险的商队依靠的是斯米德，而且斯米德已经与寇克和里格建立了合作伙伴关系。商队很快就会抵达营地。"},{t="科多兽诱引器",b="斯米德制造了一种能够让年迈和濒死的科多兽恢复活力并加以控制的装置。对准一头远古、年迈或濒死的科多兽使用它，电击会使这头野兽变成一头跟随你的驯服科多兽。你需要将五头这样的科多兽和这个装置一起带回瑟卡布斯库的营地。"}},faq={{q="斯米德·瑟卡布斯库是谁？",a="斯米德·瑟卡布斯库位于凄凉之地的瑟卡布斯库的营地。斯米德发明了科多兽诱引器，并与寇克和里格建立了合作伙伴关系。比布利认为凄凉之地没有别的地精懂得如何赚钱，但斯米德并不这么认为。",al={"谁是斯米德","斯米德·瑟卡布斯库背景故事","瑟卡布斯库"}},{q="为什么斯米德需要驯服的科多兽？",a="依赖斯米德的那支商队很快就要抵达营地了，斯米德正在等待五头刚驯服的科多兽。",al={"为什么要驯服科多兽","科多兽围捕任务目的","斯米德为什么需要科多兽"}},{q="什么是科多兽诱引器？",a="这是斯米德的发明，用来使年迈或濒死的科多兽恢复活力并加以控制。对它们使用后，电击会使野兽变成一头跟随你的驯服科多兽。",al={"诱引器的作用","科多兽诱引器背景故事"}},{q="你可以对哪些科多兽使用诱引器？",a="远古、年迈和濒死的科多兽。一旦驯服，它就会跟随你回到瑟卡布斯库的营地。",al={"要驯服哪些科多兽","科多兽围捕科多兽"}},{q="比布利是谁？",a="比布利是凄凉之地的一名地精，他认为当地没有别的地精懂得如何赚钱。斯米德·瑟卡布斯库对此有不同的看法。",al={"比布利的竞争对手","谁是比布利"}}},fp="12,246,20.260.0,21.258.0,27.239.0,32.108.0,30.161.0,44.94.0,14.130.0"}
P.entries["quest:557"] = {n="地缚护腕",s="塔伦米尔的看守者贝瓦里尔说，法师在研究你收集到的石制符文时，最终会需要与之对应的物品：束缚护腕。你需要从达拉然废墟的元素生物身上收集四个地缚护腕。",h="塔伦米尔的看守者贝瓦里尔说，法师在研究你收集到的石制符文时，最终会需要与之对应的物品：束缚护腕。你需要从达拉然废墟的元素生物身上收集四个地缚护腕。",kw={"奥特兰克","贝瓦里尔","束缚","护腕","达拉然","地缚","元素生物","法师","塔伦米尔"},sec={{t="地缚护腕",b="当法师正在研究你收集的石制符文时，贝瓦里尔预料到他会有进一步的需求：与之匹配的物品样本，即束缚护腕。护腕戴在元素生物的手腕上，将它们束缚在法师的差遣之下。在达拉然废墟中，元素生物戴着这种护腕。贝瓦里尔希望你带四个地缚护腕回塔伦米尔。"}},faq={{q="谁给予了这个任务？",a="看守者贝瓦里尔，位于塔伦米尔，在你收集了石制符文之后。",al={"任务发布者","谁发布束缚护腕任务","看守者贝瓦里尔任务"}},{q="护腕有什么用途？",a="它们被戴在元素生物的手腕上，并将它们束缚在法师的差遣之下。",al={"束缚护腕的作用","护腕的目的","为什么要获取护腕"}},{q="元素生物在哪里可以找到？",a="在位于奥特兰克山脉的达拉然废墟中。",al={"元素生物位置","哪里寻找护腕","哪里有被奴役的元素生物"}},{q="为什么看守者贝瓦里尔想要这些护腕？",a="贝瓦里尔知道法师最终会需要这些护腕的样本，因为这是法师正在研究的石制符文的对应物。",al={"为什么贝瓦里尔需要护腕","谁想要护腕"}},{q="这个任务之前有什么任务？",a="石制符文，在那项任务中你收集了法师目前正在研究的石制符文。",al={"前置任务","任务先决条件","石制符文后续"}}},fp="18,241,24.323.0,21.70.0,30.81.0,31.60.0,36.130.0,28.79.0"}
P.entries["quest:5581"] = {n="燃烧军团的传送门",s="在完成“伊鲁索之手”任务后，葬影村的泰迦·慧鬃会将伊鲁索之手交给你，并要求你封印玛诺洛克集会所的六个恶魔传送门，同时提醒你要小心传送门的守卫。",h="在完成“伊鲁索之手”任务后，葬影村的泰迦·慧鬃会将伊鲁索之手交给你，并要求你封印玛诺洛克集会所的六个恶魔传送门，同时提醒你要小心传送门的守卫。",kw={"恶魔传送门","凄凉之地","伊鲁索之手","燃烧军团","玛诺洛克集会所","葬影村","泰迦·慧鬃"},sec={{t="关闭大门",b="泰迦·慧鬃举起伊鲁索之手，那东西看起来十分可怕。她说，如果想要关闭玛诺洛克集会所周围的恶魔传送门，你就必须带着它。恶魔的威胁日益增长，关闭这些传送门将能阻止源源不断的恶魔涌入这个世界。她要求你封印全部六个传送门，并警告你要当心它们的守卫。"}},faq={{q="恶魔传送门在哪里？",a="位于凄凉之地的玛诺洛克集会所。",al={"传送门位置","玛诺洛克集会所在哪里","燃烧军团传送门在哪里"}},{q="需要什么东西才能封印传送门？",a="伊鲁索之手。泰迦·慧鬃说你必须持有它才能封印传送门。",al={"如何封印传送门","什么物品可以关闭传送门","伊鲁索之手的用途"}},{q="是谁要求你封印传送门的？",a="葬影村的泰迦·慧鬃。",al={"任务发布者","谁发布了“燃烧军团的传送门”任务","泰迦·慧鬃的位置"}},{q="需要封印多少个传送门？",a="六个，都在玛诺洛克集会所。",al={"传送门数量","传送门计数"}},{q="这个任务之前有什么任务？",a="“伊鲁索之手”，在那项任务中，泰迦·慧鬃派遣你去雷斧堡垒寻找恶魔之盒。",al={"前置任务","前置条件","前置要求"}}},fp="21,185,17.363.0,28.30.0,37.91.0,35.38.0,34.23.0,22.91.0"}
P.entries["quest:559"] = {n="法尔林的证据",s="“法尔林的证明”是南海镇的一个联盟任务，由法尔林·奥里涅尔中尉发布。为了向他的上级治安官雷德帕斯证明他在海岸巡逻方面的努力，法尔林派遣新兵前往西部海岸收集鱼人的头颅。",h="“法尔林的证明”是南海镇的一个联盟任务，由法尔林·奥里涅尔中尉发布。为了向他的上级治安官雷德帕斯证明他在海岸巡逻方面的努力，法尔林派遣新兵前往西部海岸收集鱼人的头颅。",kw={"法尔林","头颅","希尔斯布莱德","鱼人","奥里涅尔","雷德帕斯","南海镇","海滩"},ang={["faction:Alliance"]="守住南海镇需要保障其海岸线免受当地掠食者的侵害，这样哨所才能专注于来自辛迪加和部落的威胁。",["profession:Cooking"]="对于南海镇的鱼类厨师来说，法尔林对海鲜那种挑剔的厌恶让人难以理解，尽管在海滩边战斗往往能收获额外的生鱼。"},sec={{t="不情愿的请求",b="在完成了“沿海岸线”任务中对海岸线的初步清理后，法尔林·奥里涅尔中尉发现自己受到了治安官雷德帕斯和镇领导层的审视。声称清理了当地鱼人是一回事；向怀疑的上级展示确凿的证据则是另一回事。法尔林不愿亲手做这种可怕的屠宰工作，于是指派路过的联盟冒险者回到海岸线去收集足以证明杀戮的有形证据。"},{t="可怕的证据",b="这项任务要求战士前往南海镇西部的西部海岸，那里是鱼人在浅滩筑巢的地方。这位中尉需要十个鱼人的头颅来安抚镇上的驻军军官。法尔林本人非常厌恶这些生物，他承认这种两栖鱼人令人作呕的外表和气味已经彻底毁了他对南海镇主要出口产品和主食的胃口。"}},faq={{q="谁是法尔林·奥里涅尔中尉？",a="法尔林·奥里涅尔中尉是驻扎在南海镇的一名联盟城镇军官。虽然他急于向上级汇报成功，但他更喜欢将海岸线安全工作中暴力和肮脏的部分委派给有能力的冒险者。",al={"法尔林·奥里涅尔","谁发布法尔林的证明","法尔林中尉"}},{q="为什么法尔林需要鱼人的头颅？",a="治安官雷德帕斯和镇官员对西部海岸已被清理的简单口头报告并不满意。他们要求在正式承认巡逻任务取得成功之前，必须提供死亡鱼人的实物证据。",al={"为什么需要鱼人头颅","法尔林的证明原因","为什么收集头颅"}},{q="这些鱼人在哪里？",a="鱼人栖息在西部海岸，即从南海镇向西一直延伸到银松森林边界的沿海沙滩。",al={"鱼人头颅位置","西部海岸在哪里","希尔斯布莱德鱼人点"}},{q="上交“法尔林的证明”后会发生什么？",a="法尔林会让你向治安官雷德帕斯汇报鱼人被消灭的情况。在接受了证明之后，雷德帕斯会将注意力转向东部海滩的威胁，并随后传达暴风城对法尔林的重新指派命令。",al={"法尔林的证明之后的任务","法尔林任务线","法尔林的证明后续"}},{q="为什么法尔林对鱼人感到厌恶？",a="法尔林觉得这种会走路的两足鱼类本身就很令人反感。处理它们冰冷、黏糊糊的尸体让他完全失去了吃鱼的胃口，这使得他在南海镇这个捕鱼社区的日常生活变得苦不堪言。",al={"法尔林吃鱼","为什么法尔林不喜欢鱼"}},{q="谁是治安官雷德帕斯？",a="治安官雷德帕斯是南海镇防御部队中的一名指挥官，负责监督像法尔林·奥里涅尔这样的初级军官在区域安全方面的表现。",al={"雷德帕斯队长","谁是雷德帕斯"}}},fx={fff9ab4a={q="法尔林中尉为什么让你收集头颅，而不是亲自去做？",a="法尔林中尉对鱼人厌恶至极。他很乐意把清理海岸的功劳揽到自己身上，但一想到要砍下那些冰冷黏滑的头颅，就恶心得直反胃，几周来连鱼都吃不下。他宁愿雇一名冒险者去忍受这场血腥屠戮，也不愿弄脏自己的双手。",al={"法尔林为什么需要我","法尔林为什么不自己取头颅","法尔林的证明为什么要我去"}}},fp="14,256,18.467.0,15.392.0,34.226.0,42.222.0,32.138.0,45.214.1,39.217.0,23.187.0"}
P.entries["quest:56"] = {n="守夜人",s="这项任务由夜色镇的指挥官阿尔泰娅·埃伯洛克发起，旨在招募冒险者去清理附近静谧花园墓场中不断涌出的亡灵。由于暴风城的正规守军已经撤离，夜色镇的民兵只能依靠路过的雇佣兵来抵御不断蔓延的恐怖威胁。",h="这项任务由夜色镇的指挥官阿尔泰娅·埃伯洛克发起，旨在招募冒险者去清理附近静谧花园墓场中不断涌出的亡灵。由于暴风城的正规守军已经撤离，夜色镇的民兵只能依靠路过的雇佣兵来抵御不断蔓延的恐怖威胁。",kw={"althea ebonlocke","夜色镇","暮色森林","守夜人","骷髅法师","骷髅战士","暴风城","静谧花园"},ang={["class:Paladin"]="静谧花园的存在是对圣光的亵渎，那些阵亡公民被亵渎的坟墓需要神圣的钢铁和正义的裁决。",["class:Priest"]="让这些饱受折磨、不得安宁的骷髅归于尘土，是在这片被邪恶诅咒所压迫的土地上，一种精神上的慈悲之举。",["faction:Alliance"]="对于联盟的忠诚者来说，这项职责揭示了暴风城疏忽治理的残酷事实，即边境公民在没有王室援助的情况下，被迫为自己的生存而流血牺牲。"},sec={{t="被王室抛弃",b="暮色森林曾经处于暴风城的庇护之下，但随着王室资源的紧缺和首都政治矛盾的激化，暴风城撤走了驻扎在那里的士兵。夜色镇在面对不断逼近的阴影时，几乎陷入了孤立无援的境地。作为应对，森林里的居民组建了守夜人，这是一支由指挥官阿尔泰娅·埃伯洛克领导的本土民兵组织，他们坚守在被诅咒的森林与镇上幸存居民之间。"},{t="清理静谧花园",b="夜色镇南面是静谧花园墓场，这个曾经宁静的安息之地如今遍布着不得安宁的骷髅和复生的施法者。由于守夜人不得不分散在暮色森林的边境线上，力量极为薄弱，埃伯洛克指挥官指示前来的冒险者在墓场里的死者蔓延到道路上之前，先行消灭那些骷髅战士和骷髅法师。"}},faq={{q="为什么守夜人需要外界的帮助？",a="暴风城已经从暮色森林撤回了正规守军，让夜色镇独自应对困境。守夜人仅仅是一支地方民兵组织，如果没有外界的支援，他们没有足够的人手和补给来抗击整个地区不断涌现的亡灵。",al={"为什么需要帮助","为什么夜色镇虚弱","为什么没有守卫"}},{q="谁是指挥官阿尔泰娅·埃伯洛克？",a="阿尔泰娅·埃伯洛克是夜色镇镇长艾尔罗·埃伯洛克公爵的亲属，也是守夜人坚定的指挥官。她担负起组织小镇防御的职责，召集任何有能力的人，共同抵御暮色森林中的黑暗威胁。",al={"阿尔泰娅是谁","埃伯洛克指挥官","阿尔泰娅·埃伯洛克背景故事"}},{q="静谧花园墓场在哪里？",a="静谧花园墓场位于夜色镇的正南方。它原本是一个活跃的墓地，但如今已受到渗透在暮色森林中的黑暗魔法的影响，导致死者复生，并不断骚扰小镇周边地区的旅行者。",al={"静谧花园位置","墓场在哪里","去哪里找骷髅"}},{q="静谧花园里复生的是什么生物？",a="墓场里主要是横行的骷髅战士和骷髅法师。与普通的尸体不同，这些遗骸保留了残存的战斗技巧和奥术力量，这对普通的镇民来说是致命的威胁。",al={"那里有什么亡灵","暮色森林的骷髅"}},{q="暴风城会派援军吗？",a="不会。暴风城已经撤回了驻扎在岗哨的卫兵，将暮色森林这一偏远的边境地区完全弃之不顾。",al={"暴风城帮助暮色森林","暴风城会派兵吗"}},{q="这项任务能彻底解决墓场的威胁吗？",a="不能，清理静谧花园的骷髅只是初步尝试。守夜人正面临着森林深处日益严重的威胁，需要进一步的远征来控制该地区不断恶化的腐化状况。",al={"这是唯一的任务吗","守夜人任务线"}}},fx={bf57f222={q="指挥官阿尔泰娅·埃伯洛克为什么要你做这件事？",a="指挥官阿尔泰娅·埃伯洛克立誓保护夜色镇的居民，但暴风城撤走王家卫戍部队后，守卫重担全落在本地的守夜人肩上。静谧花园墓场就在镇子南边，近在咫尺，危险重重。如果不趁墓穴中爬出的亡者数量激增前将其消灭，夜色镇就有被森林中的恐怖彻底吞没的危险。",al={"阿尔泰娅为什么要你做这件事","阿尔泰娅·埃伯洛克的动机","为什么要消灭夜色镇的骷髅"}}},fp="15,294,22.441.0,29.371.0,43.267.0,34.254.0,39.225.0,50.218.0,40.138.0,52.211.0"}
P.entries["quest:560"] = {n="法尔林的证据",s="“法尔林的证明”是南海镇的一个短途运送任务，冒险者需要将一袋血淋淋的鱼人头颅从法尔林·奥里涅尔中尉那里送到治安官雷德帕斯手中。这位胆小的中尉让别人代劳了海岸上的血腥狩猎工作，现在连汇报工作也一并甩给了别人。这是在希尔斯布莱德海岸确保城镇认可度的一个中间步骤。",h="“法尔林的证明”是南海镇的一个短途运送任务，冒险者需要将一袋血淋淋的鱼人头颅从法尔林·奥里涅尔中尉那里送到治安官雷德帕斯手中。这位胆小的中尉让别人代劳了海岸上的血腥狩猎工作，现在连汇报工作也一并甩给了别人。这是在希尔斯布...",kw={"联盟","跑腿工","法尔林·奥里涅尔","法尔林的证明","希尔斯布莱德丘陵","治安官雷德帕斯","鱼人头颅","南海镇"},ang={["faction:Alliance"]="南海镇的每一项琐事都有助于加固联盟在洛丹伦的主要堡垒，以抵御从北方和海上侵入的敌对势力。",["race:Human"]="对于人类旅行者来说，与法尔林和雷德帕斯打交道可以直观地了解到希尔斯布莱德驻军那种紧张的官僚作风和边境疲态。"},sec={{t="一位胆小的军官",b="法尔林·奥里涅尔中尉的任务是巡逻并保卫希尔斯布莱德丘陵的南部海岸线，但他对边境战争的残酷现实毫无胃口。在派遣冒险者出去清理肆虐海滩的鱼人后，他甚至不愿意触碰作为证据带回来的那些断头。法尔林并不亲自将这些滴着血的战利品送到南海镇的城镇指挥部，而是很乐意把这个跑腿的任务扔回给送信人。"},{t="向雷德帕斯汇报",b="在南海镇，治安官雷德帕斯负责监督城镇的防御行动和军事战备，以应对来自塔伦米尔和野生生物群日益增长的威胁。对于通过信使而非直接从他下属的中尉那里收到一袋鱼人头颅，他一点也不感到惊讶。虽然意识到这位冒险者已经成了法尔林的跑腿工，但雷德帕斯务实地接受了这份协助，因为他知道南海镇需要一切能争取到的勤劳人手来维持边境的安宁。"}},faq={{q="为什么法尔林中尉不亲自去递送鱼人头颅？",a="法尔林中尉只是不想触碰那一袋滴着血的鱼人断头。既然已经雇佣了一名冒险者去进行战斗，他发现把这件麻烦的递送工作也交给对方处理要舒服得多。",al={"为什么法尔林不去","法尔林的证明为什么要递送","为什么要当跑腿"}},{q="治安官雷德帕斯是谁？",a="治安官雷德帕斯是驻守在南海镇的资深联盟军事指挥官。他负责监督当地的防御，协调城镇卫兵，并处理威胁着希尔斯布莱德丘陵人类定居点的各种区域性威胁。",al={"雷德帕斯是谁","治安官雷德帕斯背景故事","南海镇治安官"}},{q="这次递送任务在任务链中接下来会导向哪里？",a="递交证明后，会引出治安官雷德帕斯和法尔林中尉的进一步指派，最终会演变成关于部队部署的官方公文和送回暴风城首都的文书工作。",al={"what comes next","法尔林的证明后续任务","雷德帕斯后续任务"}},{q="为什么鱼人是南海镇驻军的首要关注对象？",a="鱼人部落在希尔斯布莱德海岸的海滩上密集筑巢。如果不加遏制，它们就会袭击沿海补给路线，骚扰当地渔民，并威胁南海镇的南侧入口，而此时城镇已经忙于应对北方的被遗忘者了。",al={"为什么要杀鱼人","南海镇鱼人问题","希尔斯布莱德鱼人"}},{q="治安官雷德帕斯如何看待法尔林中尉的行为？",a="治安官雷德帕斯非常清楚法尔林的习惯，他冷淡地指出送信人已经成了“法尔林的跑腿工”。然而，无论如何，雷德帕斯都欢迎这份帮助，因为南海镇正处于困境中，需要任何能争取到的得力人手。",al={"雷德帕斯对法尔林的看法","雷德帕斯喜欢法尔林吗"}},{q="治安官雷德帕斯在南海镇的什么位置？",a="治安官雷德帕斯可以在南海镇的镇中心和议会大厅附近找到，他负责监督定居点的日常防御工作。",al={"寻找雷德帕斯","治安官雷德帕斯在哪","雷德帕斯位置"}}},fx={["8013187e"]={q="法尔林中尉为什么要把鱼人头颅送给治安官雷德帕斯？",a="法尔林中尉需要确凿证据，证明南海镇海岸的鱼人威胁正在得到处理。把砍下的头颅交给治安官雷德帕斯，就能表明法尔林下达的巡逻命令已得到执行，南海镇的海岸也得到了保护——即使中尉本人宁愿不拎着一袋恶臭的东西穿过镇子。",al={"法尔林的动机","为什么要送鱼人头颅","法尔林的证明有什么用"}}},fp="14,384,19.481.0,17.495.0,63.239.0,23.229.0,54.204.0,53.260.0,63.230.0,47.147.0"}
P.entries["quest:561"] = {n="法尔林的证据",s="“法尔林的证明”是南海镇港口小镇内的一项联盟信使任务。冒险者受治安官雷德帕斯之托，去向法尔林·奥里涅尔中尉传达指令，要求他将军事重心转移到入侵东部海滩的纳迦身上。",h="“法尔林的证明”是南海镇港口小镇内的一项联盟信使任务。冒险者受治安官雷德帕斯之托，去向法尔林·奥里涅尔中尉传达指令，要求他将军事重心转移到入侵东部海滩的纳迦身上。",kw={"东部海滩","法尔林·奥里涅尔","法尔林的证明","希尔斯布莱德","治安官雷德帕斯","纳迦","晋升","南海镇"},ang={["class:Warrior"]="在联盟旗帜下服役的士兵常常会感到一种熟悉的挫败感，那就是要在官僚政治的嫉妒漩涡中穿行，战场上的实力往往会与指挥官的野心发生冲突。",["faction:Alliance"]="这次交流让人们得以窥见南海镇驻军内部弥漫的官僚作风和职业竞争，表明即使在被围困的北方前哨，军官们也在争夺名望。"},sec={{t="指挥权的更迭",b="南海镇的军事领导层正面临周边威胁的巨大压力，但治安官雷德帕斯始终密切关注着南部海岸线的海上危险。在收到有关纳迦入侵东部海滩的最新情报后，雷德帕斯派遣了一名传令兵穿过城镇，向法尔林·奥里涅尔中尉下达直接命令：放弃外围的干扰，消灭这些两栖威胁，并亲自向治安官汇报进展。"},{t="海岸线上的竞争",b="收到消息后，奥里涅尔中尉揭露了南海镇驻军军官之间日益激化的矛盾。奥里涅尔不但没有服从命令，反而怀疑雷德帕斯是在利用最近共享的情报来抢占平定海岸线的功劳。为了不让自己的指挥官踩着士兵的汗水获得晋升，奥里涅尔立即开始谋划自己的一条路来讨好王室。"}},faq={{q="这项任务的目的是什么？",a="治安官雷德帕斯意图将法尔林·奥里涅尔的部队重新部署到希尔斯布莱德东部海滩，去对抗那里的纳迦。他要求奥里涅尔在取得实质进展后直接向他汇报。",al={"雷德帕斯想要什么","为什么要给法尔林发送消息","法尔林的证明任务目标"}},{q="为什么法尔林·奥里涅尔对雷德帕斯的命令反应如此激烈？",a="奥里涅尔认为雷德帕斯是根据他们两人刚收到的同一份情报在行动。他担心治安官想要借平定海岸线之功，踩着奥里涅尔的辛苦劳动来换取晋升。",al={"法尔林与雷德帕斯的竞争","为什么奥里涅尔很生气","奥里涅尔的晋升"}},{q="东部海滩在哪里？",a="东部海滩沿着希尔斯布莱德丘陵的南部咸水海岸线延伸，位于南海镇东南方。入侵的纳迦已经在沙滩上建立了肮脏的营地。",al={"东部海滩位置","纳迦在哪里","希尔斯布莱德海岸"}},{q="送达这条消息后接下来会发生什么？",a="这次接触后，奥里涅尔并没有完全服从雷德帕斯的权威，而是策划了自己的计谋。他在后续的任务“暴风城，冲啊！”中，引导冒险者信使前往海岸，并最终转向高级指挥部。",al={"后续任务","接下来发生什么","暴风城，冲啊！后续"}},{q="参与这次交涉的领导人是谁？",a="治安官雷德帕斯是南海镇的主要驻军指挥官，而法尔林·奥里涅尔中尉在他手下担任负责海岸防御工作的野战中尉。",al={"法尔林和雷德帕斯是谁","南海镇军官","法尔林·奥里涅尔和雷德帕斯"}},{q="这项任务需要战斗吗？",a="不需要。这一特定步骤纯粹是南海镇军官之间的内部联络跑腿任务，尽管其内容直接涉及针对沿岸纳迦敌对势力的军事反应。",al={"有战斗吗","我需要和纳迦战斗吗","法尔林的证明战斗"}}},fx={["4fc43d37"]={q="治安官雷德帕斯为什么派你去找法尔林中尉？",a="治安官雷德帕斯负责南海镇的防御，他希望法尔林·奥里涅尔中尉别再把时间浪费在鱼人身上，转而关注威胁东部海滩的娜迦。他需要法尔林拿出真正的战术成果，并直接向自己负责，而不是一味追逐无关紧要的个人计划。",al={"雷德帕斯为什么送这条消息","雷德帕斯让法尔林去做的动机","为什么转而对付娜迦"}}},fp="14,268,18.467.0,20.452.1,37.209.0,60.210.0,36.198.0,46.211.1,46.174.0,40.187.0"}
P.entries["quest:562"] = {n="升官之道",s="法尔林·奥里涅尔中尉急于逃离他在南海镇的驻地，并回到南方的暴风城。在听说联盟最高指挥部对纳迦日益严重的威胁感到担忧后，他从中嗅到了职业发展的良机，于是雇佣了一名冒险者来消灭这些蛇人，以便自己能抢占功劳并争取调职。",h="法尔林·奥里涅尔中尉急于逃离他在南海镇的驻地，并回到南方的暴风城。在听说联盟最高指挥部对纳迦日益严重的威胁感到担忧后，他从中嗅到了职业发展的良机，于是雇佣了一名冒险者来消灭这些蛇人，以便自己能抢占功劳并争取调职。",kw={"刺鳍","法尔林·奥里涅尔","希尔斯布莱德丘陵","纳迦","调职","萨缪尔森","南海镇","暴风城，出发！"},ang={["faction:Alliance"]="希尔斯布莱德的联盟指挥系统力量薄弱，让普通的城市卫兵在面对像刺鳍纳迦这样的恐怖威胁时力不从心。",["race:Human"]="对于在洛丹伦服役的人类来说，南海镇是一个关于北方昔日荣耀的惨淡记忆，与南方暴风城重建后的宏伟与安全形成了鲜明对比。"},sec={{t="离开南海镇的通行证",b="南海镇坐落在洛丹伦的刀锋边缘，被被遗忘者军队、辛迪加盗贼以及无情的深海怪物所包围。对于习惯了暴风城里酒鬼和小型斗殴的普通卫兵法尔林·奥里涅尔中尉来说，这个驻地简直苦不堪言。当他从昔日的导师那里得知联盟最高指挥部对纳迦在海岸线上的侵扰日益焦虑时，法尔林看到了他离开北方的黄金机会。"},{t="海岸窃取的功勋",b="尽管野心勃勃，法尔林对自己的懦弱却供认不讳：在正面战斗中面对凶残的刺鳍海妖和岸行者远超出了他的勇气和能力。为了避免以身犯险，他委托一位冒险者去清理南海镇东南方的海滩，屠戮纳迦军队，并提供他所需的武功证明，以便草拟一份令人印象深刻的报告呈交给暴风城的萨缪尔森少校。"}},faq={{q="为什么法尔林·奥里涅尔想杀掉纳迦？",a="他个人并不关心纳迦；他只是想离开南海镇。法尔林从他的导师那里得知联盟最高指挥部对纳迦的威胁感到担忧，这使得针对纳迦的成功行动成为晋升或调回暴风城的捷径。",al={"为什么要杀纳迦","法尔林的动机","为什么在南海镇杀纳迦"}},{q="法尔林·奥里涅尔中尉能亲自与纳迦战斗吗？",a="不能。法尔林公开承认他只是个普通的城市卫兵，只适合处理酒馆里的醉酒闹事或是逮捕喧哗的乞丐。野蛮的刺鳍纳迦让他感到恐惧，迫使他完全依赖路过的冒险者来替他战斗。",al={"为什么法尔林不亲自战斗","法尔林是否软弱","法尔林的战斗能力"}},{q="刺鳍纳迦位于哪里？",a="刺鳍岸行者和海妖在南海镇正东南方的海岸线上建立了营地，在希尔斯布莱德丘陵的无尽之海沿岸四处游荡。",al={"纳迦的位置","刺鳍营地位置","南海镇纳迦海滩"}},{q="萨缪尔森少校是谁？",a="萨缪尔森少校是法尔林·奥里涅尔在暴风城卫队时期的昔日导师。法尔林为他准备了详细记录消灭纳迦数量的报告，希望能让萨缪尔森动用关系，为他争取调回南方的机会。",al={"萨缪尔森少校","萨缪尔森暴风城","谁收到了信"}},{q="完成这项任务后会发生什么？",a="一旦纳迦威胁被消除，法尔林便会窃取你的战功，并派遣你前往南方的Stormwind Keep，亲自将他的报告和调职申请交给萨缪尔森少校。",al={"what comes next","暴风城，出发！之后的任务","调职任务"}},{q="为什么法尔林如此痛恨南海镇？",a="法尔林将南海镇视为一个阴郁、危险的前线哨所，远离暴风城文明与安全的怀抱。夹在亡灵邻居和海岸怪物之间，他痛苦地称这里为“被圣光遗弃的港口”。",al={"为什么法尔林讨厌南海镇","被圣光遗弃的港口"}}},fx={d5622c58={q="威胁南海镇的匕击娜迦是谁？",a="匕击娜迦是一群蛇形怪物，正沿着希尔斯布莱德丘陵东部海岸侵扰而来。联盟最高指挥部对它们有组织地出现在沿岸一带日益担忧。凶猛的海岸猎手与操纵海洋魔法的海妖一同巡逻海滩，骚扰当地渔场；若不加以遏制，它们还可能击溃南海镇脆弱的防御。",al={"匕击娜迦","南海镇的娜迦是谁","匕击海岸猎手"}}},fp="13,322,26.475.0,25.402.0,47.272.0,54.243.0,39.195.0,23.229.0,40.184.1,40.215.0"}
P.entries["quest:5621"] = {n="月光之衣",s="“月之服饰”是多兰纳尔年轻暗夜精灵牧师的一项入门仪式。该任务由牧师训练师劳尔娜·晨光指派，要求学徒照料哨兵莎娅，这是一位在定居点南部树林巡逻时受伤的防御者。完成此职责标志着学徒正式获得了The Sisterhood of Elune的认可。",h="“月之服饰”是多兰纳尔年轻暗夜精灵牧师的一项入门仪式。该任务由牧师训练师劳尔娜·晨光指派，要求学徒照料哨兵莎娅，这是一位在定居点南部树林巡逻时受伤的防御者。完成此职责标志着学徒正式获得了The Sisterhood...",kw={"多兰纳尔","“月之服饰”","“in favor of elune”","劳尔娜·晨光","哨兵莎娅","the sisterhood of elune","泰达希尔"},ang={["class:Priest"]="这一仪式展示了牧师修行的两大支柱：通过恢复祈祷来治愈受伤的盟友，以及通过神圣结界保护他们免受未来的危险。",["race:NightElf"]="对于卡多雷而言，The Sisterhood of Elune和哨兵部队数千年来一直携手合作，保护森林和人民免受黑暗的侵蚀。"},sec={{t="神圣的召唤",b="在泰达希尔的枝叶间，The Sisterhood of Elune既照料着卡多雷的精神生活，也负责他们边境的实际防御。当哨兵莎娅在多兰纳尔南部的危险荒野巡逻时受伤，牧师训练师劳尔娜·晨光无法离开岗位去提供援助。因此，她委派一名刚受训的学徒去通过治愈莎娅的伤口并用保护魔法增强她的体质，来证明他们的虔诚。"},{t="姐妹会的法衣",b="恢复了哨兵莎娅活力的牧师将返回多兰纳尔，领取他们的正式法衣。这些服饰象征着年轻的侍僧已经超越了单纯的课堂教学，开始在月神的恩泽下从事实际的救生服务。在卡多雷社会中，支持哨兵不仅是一项军事任务，更是与艾露恩的交流，也是对泰达希尔安全的基本职责。"}},faq={{q="谁提供了“月之服饰”任务？",a="该任务由多兰纳尔北部建筑中的牧师训练师劳尔娜·晨光提供，她位于泰达希尔。",al={"谁提供“月之服饰”","在哪里开始“月之服饰”","“月之服饰”任务发布者"}},{q="在此任务中谁需要帮助？",a="哨兵莎娅，一位在巡逻荒野时受伤的暗夜精灵守卫，正驻扎在多兰纳尔以南等待救援。",al={"我要治疗谁","受伤哨兵的位置","哨兵莎娅在哪里"}},{q="帮助哨兵莎娅需要什么魔法？",a="你必须使用治疗魔法愈合哨兵莎娅的伤口，并施放保护结界来增强她的耐力，然后才能返回多兰纳尔。",al={"对莎娅施放什么法术","如何完成“月之服饰”","莎娅任务目标"}},{q="任何职业都可以接受这个任务吗？",a="不可以。“月之服饰”仅提供给暗夜精灵牧师，作为他们精神修行早期的里程碑。",al={"“月之服饰”是牧师专属吗","“月之服饰”职业要求","德鲁伊可以做“月之服饰”吗"}},{q="奖励的法衣象征着什么？",a="劳尔娜·晨光授予的法衣是入门的象征，标志着你已经忠诚地侍奉了艾露恩，并在当地神职人员中赢得了认可的地位。",al={"“月之服饰”法衣含义","法衣奖励背景","“月之服饰”的意义"}},{q="此任务与“In Favor of Elune”之间有什么关系？",a="“In Favor of Elune”作为前往多兰纳尔拜访训练师的入门传唤。虽然完成它并不是领取“月之服饰”的硬性要求，但一旦“月之服饰”完成后，该任务将无法完成。",al={"“in favor of elune”前置条件","错过“in favor of elune”","多兰纳尔牧师任务顺序"}}},fp="20,181,16.335.0,27.332.0,42.101.0,32.101.0,46.122.0,30.108.0,36.121.0,66.187.0"}
P.entries["quest:5622"] = {n="月神的恩赐",s="“艾露恩的眷顾”是年轻暗夜精灵牧师准备走出奥达希尔庇护之所时的成人礼。在珊达祭司的指引下，受教者将踏上前往多兰纳尔的道路，去寻求劳尔娜·晨光的进一步指导与训练。",h="“艾露恩的眷顾”是年轻暗夜精灵牧师准备走出奥达希尔庇护之所时的成人礼。在珊达祭司的指引下，受教者将踏上前往多兰纳尔的道路，去寻求劳尔娜·晨光的进一步指导与训练。",kw={"多兰纳尔","月神法衣","艾露恩的眷顾","劳尔娜·晨光","牧师","幽影谷","珊达","泰达希尔"},ang={["class:Priest"]="这项任务代表着你从简单的初学者学习迈向正式侍奉的阶段，指引你踏上获得第一套受祝神职法衣的道路。",["race:NightElf"]="The Sisterhood of Elune构成了卡多雷社会的精神核心和历史领导层，因此前往多兰纳尔的旅程对信徒来说是一个极具传统意义的里程碑。"},sec={{t="离开幽影谷",b="对于在奥达希尔与世隔绝的庇护所中侍奉艾露恩的初学者来说，学习始于珊达祭司注视下的简单祈祷和防御性祷言。然而，幽影谷中与世隔绝的生活无法让牧师们为这个危机四伏的广大世界做好准备。一旦初学者展现出坚定的信仰和纪律，珊达就会指引他们踏上前往多兰纳尔的阴影森林小径，以继续深造。"},{t="踏入圣职之路",b="到达多兰纳尔是暗夜精灵神职生涯中的一个重要里程碑。在那里，备受尊崇的祭司劳尔娜·晨光正在等待，她的职责是为即将面对泰达希尔严峻考验的追随者们做好准备。除了传授月光法术的高阶知识，抵达多兰纳尔还意味着受教者已准备好领取第一套正式法袍，标志着他们已在The Sisterhood of Elune中获得了正式地位。"}},faq={{q="谁指引我踏上这段旅程？",a="珊达祭司，即驻守在幽影谷奥达希尔枝叶间的暗夜精灵牧师训练师，会在你完成初步训练后为你提供这项指引。",al={"任务发布者","谁开启艾露恩的眷顾","我在哪里接到这个任务"}},{q="我该去哪里寻找劳尔娜·晨光？",a="劳尔娜·晨光住在泰达希尔幽影谷大门南侧的第一个大型定居点——多兰纳尔。她位于村庄北侧的建筑物内。",al={"劳尔娜·晨光位置","多兰纳尔在哪里","晨光在哪里"}},{q="任何职业都可以接这个任务吗？",a="不可以。这个任务是专门为那些刚刚踏入圣职、开始侍奉艾露恩的年轻暗夜精灵牧师所设计的。",al={"这是牧师专属任务吗","谁能做艾露恩的眷顾","德鲁伊任务"}},{q="在与劳尔娜·晨光交谈后会发生什么？",a="劳尔娜·晨光会欢迎你，并提供名为“月神法衣”的试炼。在授予你第一件正式的神职法袍之前，她会考验你保护并治疗受伤防御者的能力。",al={"what comes next","后续任务","月神法衣任务"}},{q="这是继续牧师训练的必做任务吗？",a="这是一个可选的引导任务。如果你自行前往多兰纳尔，劳尔娜·晨光依然会为你提供训练和后续任务，无需通过此任务进行引荐。",al={"我必须做艾露恩的眷顾吗","我可以跳过艾露恩的眷顾吗","可选引导任务"}},{q="为什么获得法衣对圣职姐妹会如此重要？",a="在暗夜精灵文化中，法衣不仅仅是布料，它们是神圣的象征，标志着一个人的正式职位、虔诚度，以及为族人引导月神祝福的能力与准备。",al={"法袍的重要性","法衣的意义","艾露恩祭司的职位"}}},fp="17,153,17.429.0,26.351.0,29.147.0,50.132.0,30.123.0,50.186.0,52.161.0,55.194.0"}
P.entries["quest:5623"] = {n="圣光的恩赐",s="“圣光的恩泽”是北郡山谷内新手牧师训练的一个早期里程碑。这个任务由女牧师安妮塔发布，指引初出茅庐的牧师离开隐蔽的修道院，前往闪金镇。在那里，女牧师洁塞塔正等待着他们，以加深他们的精神修行，并引导他们进一步领悟圣光的信仰。",h="“圣光的恩泽”是北郡山谷内新手牧师训练的一个早期里程碑。这个任务由女牧师安妮塔发布，指引初出茅庐的牧师离开隐蔽的修道院，前往闪金镇。在那里，女牧师洁塞塔正等待着他们，以加深他们的精神修行，并引导他们进一步领悟圣光的信仰。",kw={"安妮塔","教会","艾尔文森林","闪金镇","圣光","洁塞塔","北郡","牧师任务"},ang={["class:Priest"]="这一成人礼将你在北郡受到的庇护式学习与在艾尔文森林的公民和驻军中进行的积极牧师工作连接起来。",["faction:Alliance"]="圣光教会是联盟的关键支柱之一，培养能够维持前线防御者的忠诚治疗者。",["race:Human"]="对于暴风城的人类来说，寻求闪金镇牧师的指导是维护王国道德和精神支柱的重要一步。"},sec={{t="走出北郡",b="北郡修道院为新晋牧师提供庇护和初步指导，但在圣光教会中，神职人员的训练要求在世界各地进行实际的牧师工作。一旦新晋牧师展现出对祈祷和神圣治疗的基本掌握，女牧师安妮塔就会派他们沿着阳光明媚的道路向南前往闪金镇。这段旅程标志着他们从与世隔绝的学生转变为在艾尔文森林民众日常考验中服务的活跃教区成员。"},{t="闪金镇的教导",b="在闪金镇的Lion's Pride Inn，女牧师洁塞塔负责照看当地的精神需求并指导初露头角的侍僧。洁塞塔在修道院所奠定的基础之上更进一步，考验侍僧提供慰藉、守护信徒以及治愈伤者的能力。在她的指导下，年轻的牧师开始了解教会仆人在整个王国中所需的职责。"}},faq={{q="谁发布这个任务，我应该找谁交付？",a="北郡修道院内的女牧师安妮塔会发布该任务，并指引你沿路前往闪金镇会见女牧师洁塞塔。",al={"谁发布圣光的恩泽","任务交付","在哪里交付圣光的恩泽"}},{q="为什么牧师这么早就被派离北郡？",a="北郡提供关于圣光的基础课程，但年轻的牧师被期望能尽快服务于现实社区。闪金镇提供了一个直接的教区环境，侍僧可以在洁塞塔的指导下协助日常的镇民和城镇守卫。",al={"为什么要前往闪金镇","为什么要离开北郡修道院"}},{q="在闪金镇哪里可以找到女牧师洁塞塔？",a="女牧师洁塞塔住在闪金镇的Lion's Pride Inn内，担任当地的牧师训练师。",al={"女牧师洁塞塔在哪里","寻找洁塞塔","洁塞塔位置"}},{q="见到女牧师洁塞塔后会发生什么？",a="女牧师洁塞塔会立即通过后续任务“圣光的法袍”来测试你的训练成果，该任务要求你为一名受伤的守卫提供治疗，并获得仪式性的牧师法袍。",al={"圣光的恩泽后的下一个任务","圣光的恩泽之后的内容"}},{q="这个任务是牧师专属的吗？",a="是的。这项任务代表了圣光教会内部正式的精神指导，仅提供给牧师新学徒。",al={"任何职业都能做圣光的恩泽吗","这是牧师专属吗"}},{q="圣光教会在艾尔文森林中扮演什么角色？",a="教会为面对森林中日益严重的强盗和野生生物入侵的镇民与保卫者们提供慰藉、精神领导和身体上的治疗。",al={"圣光教会的角色","艾尔文森林的牧师"}}},fp="21,191,26.266.0,21.330.0,45.136.0,51.186.0,50.88.0,45.142.0,36.93.0,59.154.0"}
P.entries["quest:5624"] = {n="圣光之衣",s="“圣光的法衣”是闪金镇为新手牧师提供的早期试炼，由女牧师洁塞塔指派。教会并不是要进行一场抽象的信仰测试，而是派遣侍僧前往东边的水晶湖，治疗并加固负伤的守卫罗伯茨。完成这项职责证明了学生对治疗术的掌握，并使他们赢得了圣光教会认可的首套正式法衣。",h="“圣光的法衣”是闪金镇为新手牧师提供的早期试炼，由女牧师洁塞塔指派。教会并不是要进行一场抽象的信仰测试，而是派遣侍僧前往东边的水晶湖，治疗并加固负伤的守卫罗伯茨。完成这项职责证明了学生对治疗术的掌握，并使他们赢得了圣光教...",kw={"水晶湖","艾尔文森林","圣光的法衣","闪金镇","守卫罗伯茨","次级治疗术","真言术：韧","牧师长袍","女牧师洁塞塔"},ang={["class:Priest"]="这一通过仪式架起了北郡课堂神学与一线外勤服务之间的桥梁，强化了一个理念：牧师最崇高的召唤是通过直接治疗和强化结界来保持前线盟友的存活。",["faction:Alliance"]="由于暴风城军队兵力紧张且远离当地村落，城镇守卫非常依赖当地教会弟子的协助，以抵御不断逼近的威胁。",["race:Human"]="人类文化对圣光教会怀有极大的敬畏；从城镇女牧师那里获得授职法衣，标志着侍僧生活中一个重要的公民与精神里程碑。"},sec={{t="一场信仰的实践测试",b="在圣光教会的传统中，新手弟子的晋升很少仅仅基于教义。从北郡修道院来到闪金镇的女牧师洁塞塔，在授予教会正式认可之前，会测试受训者对神圣力量的实际掌控能力。当镇上收到守卫罗伯茨在闪金镇东侧湖边负伤的消息时，洁塞塔将这一日常不幸转化为了一块试金石，派遣年轻的牧师前去照料他。"},{t="维护王国",b="这项任务不仅仅需要闭合伤口；侍僧必须用恢复性的祈祷来治愈守卫的伤势，并用真言术：韧来增强他的坚韧度。在这些动荡的日子里，暴风城的军队兵力捉襟见肘，当地驻军又受到狗头人和强盗的骚扰，洁塞塔强调牧师的职责直接关系到军事生存。让守卫罗伯茨重返现役不仅能立即帮助镇子，还能证明受训者有能力在战火中维持防御者的生命。"},{t="教团法衣",b="在治疗士兵后返回Lion's Pride Inn，年轻的牧师将获得他们的第一套正式长袍。这些服饰象征着暴风城牧师教团的对外认可与接纳。虽然穿着它们对于未来的训练并非强制，但长袍是教会认可穿戴者为圣光正式仆役的显眼标志。"}},faq={{q="我在哪里可以找到守卫罗伯茨？",a="守卫罗伯茨驻扎在闪金镇正东方，靠近水晶湖岸边。他被发现躺在路边和水边，正在从执勤时受的伤中恢复。",al={"守卫罗伯茨位置","守卫罗伯茨在哪里","找到守卫罗伯茨"}},{q="完成此任务需要什么法术？",a="你必须使用次级治疗术（等级2）来恢复守卫罗伯茨的生命值，然后施放真言术：韧来增加他的耐力，最后返回女牧师洁塞塔处。",al={"所需法术","对罗伯茨施放什么法术","如何治疗守卫罗伯茨"}},{q="谁是女牧师洁塞塔？",a="女牧师洁塞塔是一位圣光教会的牧师训练师，居住在闪金镇的Lion's Pride Inn。她指导从北郡修道院出来的年轻侍僧，教导他们实际的教务和神圣魔法。",al={"洁塞塔背景故事","闪金镇女牧师洁塞塔","谁给予圣光的法衣任务"}},{q="为什么教会要为这项任务发放长袍？",a="长袍是圣光教会正式批准该侍僧并支持其教务的外部标志。完成这项实际的治疗职责，证明了受训者拥有承担教会法衣的资格与纪律。",al={"为什么要做圣光的法衣","牧师长袍奖励背景","教会长袍含义"}},{q="其他职业可以完成这个任务吗？",a="不能。此任务是专门针对联盟牧师的入门级职业任务线的一部分，适用于那些已经掌握了基本治疗和防护祈祷的牧师。",al={"圣光的法衣是牧师专属吗","圣骑士能做圣光的法衣吗","牧师职业任务"}},{q="完成“圣光的法衣”后会发生什么？",a="“圣光的法衣”结束了闪金镇早期的4级牧师启蒙任务线。虽然没有直接的后续任务，但随着你经验的增长，女牧师洁塞塔以及王国各地的其他训练师将提供更高级的训练和进一步的试炼。",al={"圣光的法衣之后做什么任务","圣光的法衣后续"}}},fp="21,263,25.354.0,20.367.0,22.300.0,31.154.0,48.149.0,25.192.0,49.205.0,38.137.0,52.209.0"}
P.entries["quest:5625"] = {n="圣光之衣",s="“圣光的法衣”是丹莫罗的矮人牧师新兵早期的成人礼。在卡拉诺斯的牧师训练师马克萨恩·安沃尔的指导下，受训者需要救助城外的一名受伤的山地探险者，以获得他们的法衣。",h="“圣光的法衣”是丹莫罗的矮人牧师新兵早期的成人礼。在卡拉诺斯的牧师训练师马克萨恩·安沃尔的指导下，受训者需要救助城外的一名受伤的山地探险者，以获得他们的法衣。",kw={"丹莫罗","真言术：韧","圣光的法衣","圣光","铁炉堡","卡拉诺斯","次级治疗术","马克萨恩·安沃尔","山地探险者多尔夫","牧师"},ang={["class:Priest"]="这一成人礼标志着你从一个未经考验的新手转变为一名受认可的圣光牧师，被托付在最前线保障同伴的生命。",["faction:Alliance"]="圣光构成了联盟的精神支柱，为那些在前线抵御石腭怪、野兽以及更可怕威胁的士兵提供慰藉和战场支援。",["race:Dwarf"]="铁炉堡的山地探险者守卫着丹莫罗危险的山口；照顾像多尔夫这样的伤员，巩固了矮人信仰与军事防御之间的重要纽带。"},sec={{t="紧急考验",b="传统上，圣光的侍僧要经过正式的考验，以证明他们有资格穿上教会的法衣。然而在卡拉诺斯，牧师训练师马克萨恩·安沃尔更看重实际成果，而非繁文缛节。当地的巡逻队在应对石腭怪和野兽时压力重重，当真正的卫兵在雪地中流血时，理论考试便显得无足轻重了。"},{t="援助山地探险者",b="为了获得他们的长袍，年轻的牧师会被派往城南，寻找在执行任务时受伤的山地探险者多尔夫。通过用治疗祈言来治愈多尔夫的伤势，并用真言术：韧来增强他的体质，受训者证明了他们的信仰可以直接转化为铁炉堡守卫者的生存保障。"},{t="教会法袍",b="在救助了山地探险者之后，马克萨恩·安沃尔会授予侍僧正式的法衣。这些法袍不仅能提供抵御丹莫罗寒冷的保暖功能，还是一种职位的视觉标志，向受伤的旅者和当地的卫兵发出信号，表明有一位圣光的仆从在此提供援助。"}},faq={{q="这个任务的目的是什么？",a="该任务考验新手牧师对他们早期法术的实际应用能力。训练师马克萨恩·安沃尔没有进行学术考试，而是让你去卡拉诺斯南面找到受伤的山地探险者多尔夫，治愈他的伤口，并用真言术：韧增强他的韧性。",al={"我该怎么做","圣光的法衣目标"}},{q="谁是马克萨恩·安沃尔？",a="马克萨恩·安沃尔是驻扎在卡拉诺斯的矮人牧师训练师。他务实且朴实无华，指导从寒脊山谷赶来的年轻牧师，并强调圣光在拯救生命方面的直接实用性，而非严格的正式礼仪。",al={"谁是马克萨恩·安沃尔","卡拉诺斯牧师训练师"}},{q="谁是山地探险者多尔夫？",a="多尔夫是驻扎在卡拉诺斯附近的一名铁炉堡山地探险者，在巡逻时负伤。他正等在定居点南面，作为对受训者的实际测试，接受治愈并获得韧性加持。",al={"多尔夫位置","谁是多尔夫"}},{q="为什么牧师完成这项任务会获得特定的法衣？",a="法衣和长袍在视觉上标志着修行者对圣光的虔诚和品级。对于社区成员和士兵来说，看到身穿法袍的牧师，能立刻识别出这是一位有能力处理危及生命的伤势并提供精神指引的人。",al={"牧师为什么要穿长袍","牧师法衣背景故事"}},{q="矮人为什么要信仰圣光？",a="铁炉堡的矮人通过与Lordaeron和暴风城人类数世纪的密切文化交流与结盟，接受了圣光的哲学。矮人牧师将传统的高原坚韧与对圣光所倡导的怜悯、坚毅和保护等美德的虔诚敬意结合在了一起。",al={"矮人圣光背景故事","矮人信仰圣光吗"}},{q="完成这次考验后会发生什么？",a="马克萨恩·安沃尔鼓励新受领法衣的侍僧外出冒险，练习他们的战斗和支援法术，并与其他旅行者一起测试自己的极限。随着牧师经验和力量的增长，教会内还有更艰难的考验在等待着他们。",al={"圣光的法衣之后是什么","下一个牧师考验"}}},fx={["21e41a20"]={q="为什么马克萨恩·安沃尔要你治疗多尔夫？",a="通常，你这样的牧师要经过正式考验，证明自己配得上穿戴教会礼服。然而，马克萨恩·安沃尔眼下有更紧要的事。他接到消息，说山地矮人多尔夫在卡拉诺斯正南方受了伤。马克萨恩没有安排一场无关紧要的测试，而是借这次真正的紧急情况，看看你能否将信仰付诸实践，在战场上治疗并援助同伴。",al={"为何马克萨恩派你去","马克萨恩·安沃尔的动机","为何帮助山地矮人多尔夫"}},["574078e1"]={q="为什么马克萨恩·安沃尔派你去，而不是亲自照料多尔夫？",a="马克萨恩肩负着卡拉诺斯教区和教会事务等更广泛的职责，而你正好站在他面前，需要接受考验。派你去雪地里能一举两得：既能及时援助受伤的山地矮人，也能证明你在圣光方面的训练是否让你做好准备，面对丹莫罗严酷的现实。",al={"马克萨恩为何不能治疗多尔夫","马克萨恩为何需要我","为何派一名新人去"}}},fp="21,246,15.353.0,23.345.0,19.304.0,34.274.0,19.237.0,24.223.0,58.268.0,38.304.0,41.237.0"}
P.entries["quest:5626"] = {n="圣光的恩赐",s="“圣光之愿”标志着年轻牧师从与世隔绝的寒脊山谷训练场走向丹莫罗更广阔世界的成人礼。在布兰斯托克·卡德尔的指导下，初学者们会被送往山隧，前往卡拉诺斯，在牧师训练师马克萨恩·安沃尔的教导下继续深造。这标志着一名侍僧已准备好承担真正的责任，并获得他们职业传统的法袍。",h="“圣光之愿”标志着年轻牧师从与世隔绝的寒脊山谷训练场走向丹莫罗更广阔世界的成人礼。在布兰斯托克·卡德尔的指导下，初学者们会被送往山隧，前往卡拉诺斯，在牧师训练师马克萨恩·安沃尔的教导下继续深造。这标志着一名侍僧已准备好承...",kw={"布兰斯托克·卡德尔","寒脊山谷","丹莫罗","圣光之愿","卡拉诺斯","圣光","马克萨恩·安沃尔","牧师","法袍"},ang={["class:Priest"]="这项任务是年轻牧师的一个里程碑，代表着他们从基础训练正式毕业进入现役，并获得了他们的第一套法袍。",["race:Dwarf"]="矮人牧师教义将精神虔诚与实际的韧性相结合，直接将侍僧从寒脊山的火炉旁送入丹莫罗严酷冰冷的寒风中。"},sec={{t="离开铁砧",b="在寒脊山谷这个隐蔽的摇篮里，矮人牧师们在布兰斯托克·卡德尔等导师的注视下开始学习。一旦新手展现出足够的奉献精神和对神圣魔法的掌握，他们的初步指导课程便告结束。卡德尔并没有让他们继续安逸地待在安威玛尔，而是将有前途的学生送往山脉另一侧的卡拉诺斯，在那里，牧师职责与防御需求同丹莫罗人民的日常斗争交织在一起。"},{t="前往卡拉诺斯的一步",b="前往卡拉诺斯需要穿过寒脊山小径的隧道，进入丹莫罗中部风雪交加的地带。在定居点等待着他们的是高级牧师马克萨恩·安沃尔，他的职责是指导学生超越基础祈祷。安沃尔坚信，对圣光的虔诚需要高尚的道德品格、强健的体魄以及不屈的意志。对于在他指导下证明了自己决心的侍僧，安沃尔准备授予他们第一套正式的职业法袍。"}},faq={{q="谁派遣你踏上这段旅程？",a="布兰斯托克·卡德尔，驻扎在寒脊山谷安威玛尔的矮人牧师训练师，会在你展现出足够的圣光天赋以进行深入学习后，将你送往卡拉诺斯。",al={"谁发布任务","任务发布者","布兰斯托克·卡德尔"}},{q="马克萨恩·安沃尔是谁？",a="马克萨恩·安沃尔是驻扎在卡拉诺斯山村的牧师训练师。他指导成长中的牧师，教导他们将虔诚与体能耐力及意志坚定结合起来。",al={"马克萨恩·安沃尔背景故事","马克萨恩·安沃尔是谁","卡拉诺斯牧师训练师"}},{q="到达马克萨恩·安沃尔处后会发生什么？",a="马克萨恩·安沃尔会要求你通过任务“圣光法袍”来证明你的价值，他会指派你帮助受伤的当地人，然后授予你第一件正式的牧师长袍。",al={"下一个任务","圣光之愿之后是什么","圣光法袍"}},{q="为什么牧师必须这么早离开寒脊山谷？",a="寒脊山谷只能提供战斗和法术的基础知识。像卡拉诺斯这样更广阔的社区面临着紧迫的后勤和防御威胁，为年轻牧师提供了服务人民的实战经验。",al={"为什么要离开寒脊山谷","离开安威玛尔","为什么要前往卡拉诺斯"}},{q="人类牧师会接到同样的任务吗？",a="艾尔文森林的人类牧师会进行一场同名的成人礼，在北郡修道院的女牧师安妮塔的指引下，前往闪金镇拜访女牧师洁塞塔。",al={"人类版的圣光之愿","北郡版本"}},{q="矮人对圣光的看法在这里有何不同？",a="矮人在虔诚之外，非常强调体力、意志和实际的耐力。正如马克萨恩·安沃尔所言，在冰冷的巅峰之上侍奉圣光，既需要信仰，也需要强健的体魄。",al={"矮人的圣光信仰","矮人与圣光"}}},fx={["7dcff5c0"]={q="为什么布兰斯托克·卡德尔让你去卡拉诺斯？",a="布兰斯托克认为你已经超越了在寒脊山谷学到的基础教诲。为了继续你的精神之旅，并获得与圣光正式侍奉者身份相称的礼服，他让你去找卡拉诺斯的资深牧师马克萨恩·安沃尔，由他考验你是否合格，并指引你接下来的道路。",al={"为何派我去卡拉诺斯","布兰斯托克·卡德尔的动机","为何拜访马克萨恩·安沃尔"}}},fp="21,430,17.478.0,22.495.0,30.192.0,19.195.0,40.178.0,49.222.0,41.181.0,51.211.0"}
P.entries["quest:5627"] = {n="艾露恩之星*",s="“艾露恩之星”标志着年轻的暗夜精灵牧师在与月亮女神交流的过程中迈出了重要的一步。在证明了对族人的忠诚后，侍僧们会被邀请前往达纳苏斯的月神殿，学习艾露恩姐妹会独有的神圣技艺。",h="“艾露恩之星”标志着年轻的暗夜精灵牧师在与月亮女神交流的过程中迈出了重要的一步。在证明了对族人的忠诚后，侍僧们会被邀请前往达纳苏斯的月神殿，学习艾露恩姐妹会独有的神圣技艺。",kw={"达纳苏斯","女祭司阿兰希雅","回家之路","艾露恩姐妹会","艾露恩之星","星辰碎片","temple of the moon"},ang={["class:Priest"]="这一仪式标志着卡多雷牧师与其他种族牧师的分歧，解锁了仅由月亮女神授予的星界法术。",["faction:Alliance"]="当人类和矮人牧师宣扬对圣光的虔诚时，暗夜精灵对艾露恩的虔诚为联盟的队伍带来了古老而独特的星界魔法。",["race:NightElf"]="对于卡多雷而言，侍奉艾露恩与公民和文化生活密不可分；响应姐妹会的召唤，代表着在为泰达希尔的服务中走向成熟。"},sec={{t="奉献仪式",b="暗夜精灵牧师不像人类和矮人那样从圣光的广义哲学原则中汲取神圣力量，而是直接从他们的女神艾露恩那里获得。当一名侍僧在为国效力时展现出坚定的奉献精神，达纳苏斯的姐妹会便会认可这种虔诚。受召前往月神殿的牧师被认为有资格进行更深层次的交流，并被传授数千年来供奉仪式中流传下来的神圣法术的奥秘。"},{t="月亮女神的恩赐",b="在响应女祭司阿兰希雅的召唤后，初学者将接受直接指导，学习他们种族特有的神圣奥秘，例如“星辰碎片”。这些法术引导着白女士那光芒四射、星光熠熠的愤怒与恩典。接受这项指导标志着侍僧已经完成了基础训练，并准备好以艾露恩的名义走出泰达希尔的保护伞，踏上旅程。"}},faq={{q="这个任务的目的是什么？",a="“艾露恩之星”代表着初学者正式获得艾露恩姐妹会的认可。完成后，女祭司阿兰希雅会指导年轻的牧师学习暗夜精灵特有的种族法术，例如“星辰碎片”，这标志着他们作为月亮女神选定容器的成长。",al={"艾露恩之星任务","我能得到什么","为什么要完成这个任务"}},{q="谁发布“艾露恩之星”？",a="该任务由女祭司阿兰希雅发布并完成，她是艾露恩姐妹会的一位授命领袖，驻扎在达纳苏斯宏伟的月神殿内。",al={"谁给予艾露恩之星","艾露恩之星任务发布者","阿兰希雅在哪里"}},{q="为什么这个任务仅限暗夜精灵？",a="本任务中教授的仪式属于艾露恩姐妹会，这是统治暗夜精灵信仰的古老祭司组织。与学习通用圣光的其他联盟祭司不同，卡多雷牧师直接通过与艾露恩的交流获得他们独特的魔法。",al={"人类可以做这个任务吗","这是暗夜精灵专属吗","谁可以完成艾露恩之星"}},{q="这个任务在牧师剧情线中处于什么位置？",a="该任务紧接在“回家之路”之后。在那项任务中，一名已经在泰达希尔各地提供帮助的准牧师会被指引回首都，前往月神殿寻求进一步的指导。",al={"艾露恩之星的前置任务是什么","艾露恩之星前提","回家之路任务"}},{q="艾露恩赐予她牧师什么样的魔法？",a="侍奉艾露恩的牧师交织着月光、星光和阴影。“星辰碎片”等独特的仪式允许卡多雷信徒将炽热的星界之火降临在敌人身上，将神圣的审判与星界的愤怒融合在一起。",al={"艾露恩法术","暗夜精灵牧师魔法","星辰碎片背景故事"}},{q="这发生在达纳苏斯的什么地方？",a="它发生于月神殿内。这座闪耀的大理石圣殿矗立在达纳苏斯的南部区域，是卡多雷民族的信仰中心。",al={"艾露恩之星位置","女祭司阿兰希雅在哪里","月神殿位置"}}},fp="14,187,18.389.0,25.326.0,34.147.0,26.114.0,44.212.0,55.149.0,52.201.0,40.153.0"}
P.entries["quest:5628"] = {n="回家",s="“回归”是发给那些远游至艾尔文森林人类领地的年轻暗夜精灵牧师的召集令。闪金镇的女牧师洁塞塔传达了一封来自达纳苏斯的紧急信件，要求新手牧师回到Temple of the Moon，在女祭司阿兰希雅的指导下进一步提升他们的精神修行。",h="“回归”是发给那些远游至艾尔文森林人类领地的年轻暗夜精灵牧师的召集令。闪金镇的女牧师洁塞塔传达了一封来自达纳苏斯的紧急信件，要求新手牧师回到Temple of the...",kw={"达纳苏斯","艾露恩","闪金镇","女祭司阿兰希雅","女牧师洁塞塔","回归","艾露恩之星","temple of the moon"},ang={["class:Priest"]="每个牧师教团都有着深厚的传统渊源；对于卡多雷侍僧来说，月神仪式的真正进阶只能由Temple of the Moon的资深女祭司批准。",["faction:Alliance"]="艾尔文森林的圣光教会与达纳苏斯的The Sisterhood of Elune之间展现出的互助友好，体现了联盟各族之间日益紧密的合作纽带。",["race:NightElf"]="远渡重洋前往年轻种族的领地是一条充满雄心的道路，但泰达希尔的召唤与艾露恩的祝福总是会将卡多雷引回他们神圣的庇护所。"},sec={{t="闪金镇的消息",b="在艾尔文森林中，暗夜精灵并不多见，而一位在人类聚居地游荡的年轻侍僧会立刻引起人们的注意。当这样的牧师到达闪金镇时，女牧师洁塞塔会热情地迎接他们并带来消息。The Sisterhood of Elune的一位成员不远万里横跨大陆寻找这位年轻的信徒，并带来了来自Temple of the Moon的紧急命令：是时候回到卡利姆多去精进他们的使命了。"},{t="圣殿的召唤",b="达纳苏斯的中心矗立着Temple of the Moon，那是暗夜精灵信仰和领导层的核心。女祭司阿兰希雅和泰兰德·语风大祭司负责监管The Sisterhood of Elune的指导工作，即便弟子因好奇而远赴重洋，她们依然密切关注着他们。回归之后，新手们会受到母亲般的关怀，并立即投入到关于月亮女神天体奥秘的更深层研究中。"}},faq={{q="为什么要召回身处人类领地的暗夜精灵牧师？",a="远赴东部王国的年轻暗夜精灵牧师依然受泰达希尔神圣教团的约束。女祭司阿兰希雅会追踪他们的进度，一旦他们准备好学习更高阶的艾露恩仪式，就会召回他们回到Temple of the Moon。",al={"为什么要召回我","为什么要完成回归任务","闪金镇牧师任务"}},{q="女牧师洁塞塔是谁？",a="女牧师洁塞塔是驻扎在闪金镇Lion's Pride Inn的人类牧师训练师。她侍奉圣光，但同时也尊重前来造访的卡多雷侍僧，并在达纳苏斯的使者寻找他们流浪的族人时担任联络人。",al={"谁发布了回归任务","闪金镇牧师训练师","女牧师洁塞塔"}},{q="女祭司阿兰希雅是谁？",a="女祭司阿兰希雅是一位资深的The Sisterhood of Elune成员，负责在达纳苏斯的Temple of the Moon训练侍僧。她与泰兰德·语风大祭司紧密合作，监督年轻暗夜精灵牧师的成长与精神奉献。",al={"阿兰希雅是谁","圣殿牧师训练师","女祭司阿兰希雅"}},{q="回到达纳苏斯后会发生什么？",a="一旦你向Temple of the Moon的女祭司阿兰希雅报到，她会欢迎你平安归来，并引出你的下一个修行任务：“艾露恩之星”，该任务将带你深入探究女神所赐予的神圣力量。",al={"what comes next","回归之后的下一个任务","后续任务"}},{q="这与正常的训练路径有何不同？",a="这是一个替代性的引导任务，专门为那些选择在艾尔文森林等人族领地升级，而不是留在泰达希尔的暗夜精灵牧师设计。它确保他们能被重新指引回达纳苏斯的种族训练师处，以解锁他们种族专属的牧师技能。",al={"所有牧师都要做这个任务吗","这个任务是必须完成的吗","艾尔文森林牧师任务"}},{q="信使是如何在遥远的艾尔文森林找到侍僧的？",a="The Sisterhood of Elune的一位女祭司从达纳苏斯一路远行至东部王国，并叮嘱像闪金镇女牧师洁塞塔这样的联盟训练师，留意这位游历的新手并将他们指引回家。",al={"他们怎么知道我在这里","是谁追踪我到闪金镇的"}}},fp="14,275,19.368.0,22.417.0,58.246.0,25.225.0,25.227.0,42.187.0,51.206.0,67.207.0"}
P.entries["quest:5629"] = {n="回家",s="“回归家园”标志着在泰达希尔各地服务的年轻暗夜精灵牧师的一次成年礼。在荒野中证明了自己之后，见习生们会被召唤到位于达纳苏斯的雄伟的Temple of the Moon，向女祭司阿兰希雅和泰兰德·语风大祭司觐见。",h="“回归家园”标志着在泰达希尔各地服务的年轻暗夜精灵牧师的一次成年礼。在荒野中证明了自己之后，见习生们会被召唤到位于达纳苏斯的雄伟的Temple of the Moon，向女祭司阿兰希雅和泰兰德·语风大祭司觐见。",kw={"达纳苏斯","多兰纳尔","艾露恩","劳尔娜·晨光","女祭司阿兰希雅","回归家园","the sisterhood of elune","泰达希尔","temple of the moon","泰兰德"},ang={["class:Priest"]="这次召唤反映了一位牧师从普通的森林侍僧转变为The Sisterhood of Elune的正式仆从，直接向达纳苏斯负责。",["race:NightElf"]="对于卡多雷来说，响应前往Temple of the Moon的召唤代表着与他们文化根源的交流，以及泰兰德·语风大祭司的注视。"},sec={{t="来自达纳苏斯的召唤",b="在多兰纳尔周围花费初期时间照料伤员并净化腐蚀的牧师，很快就会吸引The Sisterhood of Elune的注意。训练师劳尔娜·晨光会拦截有前途的入门者，并解释说女祭司阿兰希雅已经传话要求召见。虽然帮助当地定居点至关重要，但每一位信徒都必须培养自己与月之女的交流，并回应信仰的更高召唤。"},{t="在Temple of the Moon内",b="这条道路通向泰达希尔的枝叶之外，进入达纳苏斯的宏伟中心：Temple of the Moon。这座圣殿在艾露恩恩典的柔和光辉下耸立于城市之上，既是最高的礼拜堂，也是卡多雷的精神首都。能被邀请回到这些大厅，意味着一个人不再仅仅被视为羽翼未丰的学生，而是被牧师领导层直接认可的入门者。"},{t="泰兰德和阿兰希雅的青睐",b="当旅行者走到女祭司阿兰希雅面前时，迎接他们的是温暖和慈母般的问候。阿兰希雅分享了领导层那警觉的自豪感，并指出，每当入门者冒险进入未知的外部世界并安然无恙地返回时，她和泰兰德·语风大祭司都会感到高兴。这次回归标志着在阿兰希雅的直接指导下，更深层次的神圣试炼开始了。"}},faq={{q="谁提供了“回归家园”这个任务？",a="驻扎在泰达希尔内多兰纳尔的牧师训练师劳尔娜·晨光，会在年轻的暗夜精灵牧师获得足够的训练和经验后，发布该任务。",al={"谁发布回归家园","回归家园任务发布者","劳尔娜·晨光任务"}},{q="女祭司阿兰希雅在哪里？",a="女祭司阿兰希雅居住在达纳苏斯的Temple of the Moon内，位于泰达希尔暗夜精灵首都的中心地带。",al={"阿兰希雅在哪里","女祭司阿兰希雅位置","temple of the moon的女祭司"}},{q="为什么女祭司阿兰希雅想见我？",a="The Sisterhood of Elune的长老和领导层注意到了你在泰达希尔荒野中的奉献服务。阿兰希雅认为你已经准备好接受进阶指导和更重要的精神任务。",al={"为什么被召唤到达纳苏斯","为什么去temple of the moon"}},{q="任何职业都能接取这个任务吗？",a="不能。“回归家园”是专门为暗夜精灵牧师量身定做的，作为他们早期职业发展和神圣入门仪式的一部分，以进入The Sisterhood of Elune的更高职责。",al={"回归家园所有职业都能接吗","德鲁伊能做回归家园吗","仅限牧师的任务"}},{q="“回归家园”之后是什么任务？",a="在向女祭司阿兰希雅汇报并完成此差事后，她会委托你进行后续任务，名为“艾露恩之星”。",al={"回归家园后续是什么","回归家园后续任务","下一个任务"}},{q="Temple of the Moon对暗夜精灵有什么意义？",a="Temple of the Moon是女神艾露恩的主要礼拜中心，也是泰兰德·语风大祭司指导The Sisterhood of Elune和卡多雷民族的行政大厅。",al={"temple of the moon背景","达纳苏斯的temple of the moon"}}},fp="14,254,24.371.0,29.346.0,32.263.0,36.132.0,35.116.0,42.176.0,30.133.0,34.86.0,61.152.0"}
P.entries["quest:563"] = {n="人事调动",s="“调离”是法尔林·奥里涅尔中尉为逃离他在南海镇的驻扎任务所进行的最终行动。法尔林编纂了一份夸大其词的报告，声称自己在沿海对抗纳迦，并派遣一名冒险者长途跋涉前往Stormwind Keep，将文件送到他昔日的导师萨缪尔森少校手中。",h="“调离”是法尔林·奥里涅尔中尉为逃离他在南海镇的驻扎任务所进行的最终行动。法尔林编纂了一份夸大其词的报告，声称自己在沿海对抗纳迦，并派遣一名冒险者长途跋涉前往Stormwind...",kw={"刺棘","法尔林·奥里涅尔","萨缪尔森少校","调职","雷德帕斯","南海镇","stormwind keep"},ang={["faction:Alliance"]="这个差事展现了联盟军队日常的官僚政治，像南海镇这样偏远的边境驻军，往往与那些渴望回到暴风城的军官们安逸的野心发生冲突。",["race:Human"]="这次投递揭示了在洛丹伦坚守阵地的人类难民和守卫者，与Stormwind Keep高墙内政治博弈之间的鲜明对比。"},sec={{t="逃离南海镇的门票",b="法尔林·奥里涅尔中尉毫不掩饰他对自己在希尔斯布莱德丘陵驻地的厌恶。他被困在南海镇，远离首都的舒适，并在治安官雷德帕斯严厉的注视下，整日谋划着调回南方。通过将清理附近刺棘纳迦的功劳揽在自己身上，他希望将自己包装成一名不可或缺、身经百战且即将被提拔的军官。"},{t="利用关系",b="为了在不引起治安官雷德帕斯怀疑的情况下确保调职，法尔林完全绕过了当地的指挥链。他转而依赖自己与萨缪尔森少校的私人关系，后者是Stormwind Keep的一名高级军官，曾是他的导师。将这份润色过的报告直接送到萨缪尔森手中，可以确保法尔林所谓的成就摆在有权调动驻军人员的长官案头。"},{t="官僚主义作风",b="在Stormwind Keep收到档案后，萨缪尔森少校对自己昔日学生在应对纳迦威胁方面表现出的主动性表示了轻微的赞许。然而，军事官僚机构运转缓慢。萨缪尔森没有立即下达调职令，只是承诺在下个月的例行人事审查中权衡这份报告，这使得法尔林在南海镇的命运悬而未决。"}},faq={{q="为什么法尔林·奥里涅尔想要调职？",a="法尔林·奥里涅尔中尉厌恶驻扎在南海镇，他认为这个偏远的北方前哨站枯燥、危险，且与他的身份不符。他渴望回到相对奢华和安全的暴风城，并试图利用他关于纳迦的报告来证明调职的正当性。",al={"为什么要离开南海镇","法尔林的动机","法尔林为什么要离开"}},{q="萨缪尔森少校是谁？",a="萨缪尔森少校是Stormwind Keep的一名高级军官，负责监督城市卫队的指派工作。在担任现职之前，他曾在法尔林·奥里涅尔中尉在首都早期的职业生涯中担任其导师。",al={"萨缪尔森是谁","萨缪尔森背景"}},{q="为什么法尔林不能亲自递交报告？",a="法尔林在南海镇现役，没有许可不能擅离职守。此外，他正试图绕过他的直属上级治安官雷德帕斯，后者很可能会阻挠这种利己的调职请求。",al={"为什么要我来投递","为什么他不亲自投递"}},{q="法尔林真的亲自击败了纳迦吗？",a="没有。法尔林派遣冒险者去杀死东部海滩的刺棘纳迦，然后利用他们的成功作为支持他调职请求的报告内容。",al={"法尔林杀了纳迦吗","法尔林报告的真相"}},{q="法尔林真的被调回了暴风城吗？",a="没有立即调回。萨缪尔森少校只是承诺在下个月的人事审查中考虑这份报告。在王国军事官僚机构缓慢运转的同时，法尔林在可预见的未来仍将驻扎在南海镇。",al={"法尔林会被调职吗","调职成功了吗"}},{q="萨缪尔森少校在哪里？",a="萨缪尔森少校站在Stormwind Keep内，这是位于暴风城中心的一座堡垒，也是最高指挥部和摄政议会的所在地。",al={"萨缪尔森的位置","萨缪尔森少校在哪里"}}},fp="12,312,26.432.0,16.435.0,19.386.1,45.274.0,23.217.0,44.226.0,44.157.0,55.245.1,33.140.0"}
P.entries["quest:5630"] = {n="回家*",s="“重返家园”是发给那些远离卡利姆多，在丹莫罗寒冷的岩架上进行试炼的暗夜精灵牧师的召唤。在矮人牧师训练师马克萨恩·安沃尔的指引下，这名新手被要求返回达纳苏斯的Temple of the Moon，向女祭司阿兰希雅报告。",h="“重返家园”是发给那些远离卡利姆多，在丹莫罗寒冷的岩架上进行试炼的暗夜精灵牧师的召唤。在矮人牧师训练师马克萨恩·安沃尔的指引下，这名新手被要求返回达纳苏斯的Temple of the Moon，向女祭司阿兰希雅报告。",kw={"达纳苏斯","丹莫罗","卡拉诺斯","马克萨恩·安沃尔","女祭司阿兰希雅","重返家园","艾露恩之星","泰达希尔","temple of the moon"},ang={["class:Priest"]="这场通过仪式将游历的侍僧与The Sisterhood of Elune的领导层重新联系起来，确保即使在遥远的土地上旅行，对月亮女神的虔诚依然坚定不移。",["race:NightElf"]="对于一名在丹莫罗的凛冽寒风中磨砺的卡多雷来说，这份召唤提供了一个重返泰达希尔熟悉圣地和祖先森林的契机。"},sec={{t="跨越海洋的召唤",b="选择与矮人盟友并肩开启冒险旅程的暗夜精灵，必须面对丹莫罗苦寒刺骨的天气，这与泰达希尔宁静的森林截然不同。在卡拉诺斯，矮人牧师训练师马克萨恩·安沃尔在注意到这位精灵的坚韧之后，便传达了一份紧急信件：一位艾露恩的女祭司曾途经此处寻找他们，并带来了要求他们立即返回达纳苏斯的命令。"},{t="月神殿",b="这次旅程需要跋涉回到泰达希尔的神圣枝叶中，直接前往Temple of the Moon。在那里，女祭司阿兰希雅欢迎这位旅行者回到The Sisterhood of Elune的怀抱。看到另一位信徒从异国他乡安然无恙地归来，阿兰希雅深感欣慰，随即准备让这位牧师开始下一次的虔诚仪式，首先便是“艾露恩之星”。"}},faq={{q="谁派我执行这个任务？",a="马克萨恩·安沃尔，驻扎在丹莫罗卡拉诺斯的矮人牧师训练师，会将这份信件交给你。他提到另一位暗夜精灵女祭司不久前曾路过此地寻找你。",al={"任务给予者","谁开启重返家园","马克萨恩·安沃尔"}},{q="我需要去哪里完成任务？",a="你必须启程返回位于卡利姆多北部泰达希尔岛上的达纳苏斯。女祭司阿兰希雅正在Temple of the Moon内等待着你。",al={"任务完成地点","女祭司阿兰希雅在哪里","我该去哪"}},{q="为什么Temple of the Moon要召唤我回去？",a="女祭司阿兰希雅和高阶女祭司泰兰德·语风时刻关注着年轻初学者的成长。阿兰希雅希望确认你的安全，聆听你在艾露恩恩泽下的游历见闻，并通过“艾露恩之星”开启你精神修行的下一阶段。",al={"为什么重返家园","牧师召唤原因"}},{q="与女祭司阿兰希雅交谈后会发生什么？",a="一旦你报告了你的归来，女祭司阿兰希雅就会提供任务“艾露恩之星”，继续你作为卡多雷牧师的基础仪式。",al={"下一个任务","what comes next"}},{q="为什么暗夜精灵会在10级时出现在丹莫罗？",a="暗夜精灵冒险者经常乘坐从黑海岸到米奈希尔港的船只前往东部王国，以探索联盟的土地，或是与矮人和侏儒伙伴并肩冒险。",al={"为什么在丹莫罗","铁炉堡的暗夜精灵"}},{q="其他种族可以接这个任务吗？",a="不可以，这个任务是专门为在矮人领地进行训练的暗夜精灵牧师设计的，目的是指引他们回到位于达纳苏斯的文化和精神家园。",al={"矮人能做重返家园吗","谁能接这个任务"}}},fp="14,204,24.301.0,22.344.0,27.158.0,37.112.0,46.253.0,51.126.0,51.173.0,39.136.0"}
P.entries["quest:5631"] = {n="回家",s="\"Returning Home\" 是一项联盟牧师任务，旨在将那些在国外游历的暗夜精灵年轻侍僧召回泰达希尔。这些年轻的牧师在人类领地受到乔舒修士的指引，随后被女祭司阿兰希雅召回达纳苏斯的 Temple of the Moon，以接受关于艾露恩奥秘的高级指导。",h="\"Returning Home\" 是一项联盟牧师任务，旨在将那些在国外游历的暗夜精灵年轻侍僧召回泰达希尔。这些年轻的牧师在人类领地受到乔舒修士的指引，随后被女祭司阿兰希雅召回达纳苏斯的 Temple of the...",kw={"乔舒修士","达纳苏斯","牧师","女祭司阿兰希雅","回家","stars of elune","泰达希尔","temple of the moon","泰兰德"},ang={["class:Priest"]="这个任务架起了圣光教会与 The Sisterhood of Elune 之间的友谊桥梁，标志着一名年轻侍僧回归族群，以掌握独特的卡多雷仪式。",["faction:Alliance"]="东部王国的乔舒修士与达纳苏斯的女祭司们之间的无缝合作，反映了维持联盟统一的精神外交。",["race:NightElf"]="对于那些曾在海上的人类或矮人中游历过的暗夜精灵牧师来说，这次朝圣标志着回归泰达希尔圣所的神圣时刻。"},sec={{t="跨海召集",b="虽然暗夜精灵牧师偶尔会前往暴风城等人类领地，与圣光教会分享精神交流，但他们与 The Sisterhood of Elune 的联系依然最为紧密。当乔舒修士告知一名侍僧，有一位暗夜精灵使者前来寻找他们时，这标志着他们早期的游历已经结束。他们的家园神殿需要他们回去，在泰兰德·语风高阶女祭司的核心圈指导下进行更深层次的修行。"},{t="Temple of the Moon",b="跨海回到达纳苏斯，旅行者便会直接来到 Temple of the Moon 的密室。女祭司阿兰希雅热情地迎接回归的侍僧，庆贺他们平安度过了这个动荡的世界。年轻弟子的平安归来让阿兰希雅和泰兰德都感到欣慰，但这同时也是更艰巨的精神试炼的序幕。"}},faq={{q="为什么乔舒修士要给暗夜精灵牧师下达指令？",a="乔舒修士在人类领地为圣光教会服务，那里的联盟年轻牧师经常在一起共同训练。一位 The Sisterhood of Elune 的姐妹特地拜访了他的驻地，传达了召回你前往达纳苏斯的消息，因此乔舒修士将此召集令传达给了你。",al={"乔舒修士的指引","乔舒修士与暗夜精灵","召回我的人"}},{q="谁是女祭司阿兰希雅？",a="女祭司阿兰希雅是驻扎在达纳苏斯 Temple of the Moon 的 The Sisterhood of Elune 的资深成员。她与泰兰德·语风高阶女祭司紧密合作，负责监督和指导那些有前途的暗夜精灵牧师进行修行和晋升。",al={"女祭司阿兰希雅","阿兰希雅与达纳苏斯","阿兰希雅的身份"}},{q="到达 Temple of the Moon 后会发生什么？",a="向女祭司阿兰希雅汇报你已安全抵达后，她会欢迎你回家，并引导你进行下一阶段的试炼，开启任务“Stars of Elune”，以加深你与月神之间的交流。",al={"回家后的任务","下一步修行","stars of elune 任务"}},{q="任何联盟种族都能做这个任务吗？",a="这项特定的召集令是针对那些在早期训练中远离卡利姆多的暗夜精灵牧师的。它确保他们能回到祖居之地，在 The Sisterhood of Elune 的指导下学习种族特有的牧师传统。",al={"是否仅限暗夜精灵","人类能否进行回家任务","任务接取条件"}},{q="Temple of the Moon 在哪里？",a="Temple of the Moon 矗立在达纳苏斯的南部区域，坐落在泰达希尔的树冠之上。它既是暗夜精灵文化的精神中心，也是泰兰德·语风高阶女祭司的权力之座。",al={"temple of the moon 的位置","神殿所在地","阿兰希雅的位置"}},{q="为什么阿兰希雅会提到泰兰德·语风？",a="泰兰德·语风是艾露恩的高阶女祭司，也是暗夜精灵的精神领袖。像阿兰希雅这样的资深女祭司代表她行事，确保所有在外弘扬信仰的新手都能得到追踪，并按照泰兰德的标准接受指导。",al={"提及泰兰德的原因","泰兰德·语风女祭司","阿兰希雅与泰兰德的关系"}}},fp="14,250,21.421.0,22.279.0,64.230.0,25.227.0,51.161.0,36.204.0,40.201.0,45.243.0"}
P.entries["quest:5632"] = {n="回家",s="“Returning Home”是发给在外服役、表现出色的暗夜精灵牧师的一道征召令。女祭司阿兰希雅将这些见习者召回达纳苏斯的Temple of the Moon，以表彰她们在The Sisterhood of Elune中的成长，并传授进阶的指导。",h="“Returning Home”是发给在外服役、表现出色的暗夜精灵牧师的一道征召令。女祭司阿兰希雅将这些见习者召回达纳苏斯的Temple of the Moon，以表彰她们在The Sisterhood of...",kw={"达纳苏斯","娜拉·梅德隆","牧师任务","女祭司阿兰希雅","返乡","the sisterhood of elune","艾露恩之星","temple of the moon","泰兰德·语风"},ang={["class:Priest"]="这道征召令标志着你牧师生涯中的一个重要里程碑，它以直接的沟通和在The Sisterhood of Elune指导下的进一步磨练，作为对你早期服务的回报。",["faction:Alliance"]="The Sisterhood of Elune构成了联盟中暗夜精灵的精神核心，培养着精通治疗的医师和神圣战士，以应对卡利姆多各处的威胁。",["race:NightElf"]="对于卡多雷来说，平安回到Temple of the Moon是一次意义深远的归乡，它巩固了艾露恩神职人员长久以来的文化和精神领导地位。"},sec={{t="来自The Sisterhood of Elune的信使",b="当初出茅庐的牧师们在外游历并服务于族人时，她们的精神成长并没有被忽视。在拜访暴风城公园区的娜拉·梅德隆时，一位来自The Sisterhood of Elune的信使带来了紧急消息：组织的首领要求见习者前往达纳苏斯。这既是一次评估，也是一种认可仪式，标志着她们从羽翼未丰的见习生转变为月神母亲的活跃仆从。"},{t="在Temple of the Moon觐见",b="这道征召令指引旅行者直接前往达纳苏斯至高无上的圣所——Temple of the Moon，去见女祭司阿兰希雅。在泰兰德·语风大祭司的监督下，The Sisterhood of Elune密切关注着分散各地的成员。平安回到神殿不仅是对族群和女神的尊崇，也证明了艾露恩的恩典在牧师早期的野外试炼中一直指引并庇护着她们。"}},faq={{q="为什么女祭司要召我回达纳苏斯？",a="女祭司阿兰希雅和The Sisterhood of Elune一直在追踪门徒的精神成长。你被召回Temple of the Moon是因为你在组织修行道路上取得了飞速进步，这将引导你直接进入更深层的训练并获得神圣的祝福。",al={"为什么回家","征召原因","为什么要拜访阿兰希雅"}},{q="谁是女祭司阿兰希雅？",a="女祭司阿兰希雅是The Sisterhood of Elune中驻守于Temple of the Moon的一位高级导师。她直接效力于泰兰德·语风大祭司麾下，负责训练有前途的暗夜精灵牧师，并引导她们进行神圣仪式。",al={"阿兰希雅是谁","阿兰希雅背景故事","女祭司阿兰希雅的身份"}},{q="这道征召令接下来会指引我去哪里？",a="向女祭司阿兰希雅报到后，你将立即参与被称为“艾露恩之星”的试炼。这是一个古老的牧师任务，你将在其中学习引导女神的星辰之力来保卫你的族人。",al={"返乡任务之后是什么","返乡的下一步","艾露恩之星的引入"}},{q="谁通过娜拉·梅德隆传达了这条消息？",a="一位由The Sisterhood of Elune直接派出的信使将消息传达给了娜拉·梅德隆。为了监督见习者，该组织与驻扎在海外的女祭司（如暴风城公园区的娜拉）保持着畅通的联络渠道。",al={"谁派出了娜拉","the sisterhood of elune的信使"}},{q="其他种族或职业会收到这道征召令吗？",a="不会。该任务专门针对暗夜精灵牧师和The Sisterhood of Elune。其他种族和信仰的见习者会寻求各自独特的精神导师和圣职组织来获得晋升。",al={"非暗夜精灵可以完成吗","这是牧师专属吗"}},{q="为什么阿兰希雅提到了泰兰德·语风？",a="泰兰德·语风是艾露恩的大祭司，也是The Sisterhood of Elune和暗夜精灵政府的最高领袖。阿兰希雅在Temple of the Moon直接隶属于她，确保泰兰德的意志和精神指引能够传达给每一位见习者。",al={"泰兰德的联系","泰兰德与阿兰希雅的关系"}}},fp="14,195,31.379.0,34.383.0,52.230.0,25.222.0,34.152.0,44.211.0,47.169.0,45.223.0"}
P.entries["quest:5633"] = {n="回家*",s="“重返家园”是一项召集令，要求身处铁炉堡的暗夜精灵牧师返回达纳苏斯的月神殿。艾露恩姐妹会的信使一直在寻找流浪的侍僧，指引他们回到女祭司阿兰希雅身边，进行紧急的训练并履行神职。",h="“重返家园”是一项召集令，要求身处铁炉堡的暗夜精灵牧师返回达纳苏斯的月神殿。艾露恩姐妹会的信使一直在寻找流浪的侍僧，指引他们回到女祭司阿兰希雅身边，进行紧急的训练并履行神职。",kw={"布莱纳·火崖","达纳苏斯","牧师任务","女祭司阿兰希雅","重返家园","艾露恩之星","temple of the moon"},ang={["class:Priest"]="这个任务连接了你在联盟盟友中的早期旅行，并带你回到了暗夜精灵牧师的精神核心家园——月神殿。",["faction:Alliance"]="铁炉堡的矮人教士与达纳苏斯的艾露恩姐妹会之间的合作，展示了联盟各阵营是如何协同支持流浪冒险者的。",["race:NightElf"]="对于年轻的卡多雷来说，离开卡利姆多前往东部王国是一次罕见的旅程，但艾露恩的指引和泰兰德的牧师教团跨越了无尽之海，触及了每一位族人。"},sec={{t="来自山中之城的召唤",b="即使远在泰达希尔之外，身处铁炉堡熙熙攘攘的地下大厅中，暗夜精灵牧师们依然与艾露恩姐妹会紧密相连。身为Mystic Ward的矮人牧师训练师，布莱纳·火崖传达了一位来访的暗夜精灵女祭司留下的口信。这位信使此行是为了寻找在外的年轻学徒，并传达导师们要求他们立即返回首都的命令。"},{t="月神殿",b="在抵达达纳苏斯的月神殿后，归来的侍僧需直接向女祭司阿兰希雅报告。阿兰希雅在大祭司泰兰德·语风的注视下欢迎学生归来，并对他们能够横跨大洋平安归来感到欣慰。这次紧急召集是通往更深层次信仰的门槛，为“艾露恩之星”等神圣职责铺平了道路。"}},faq={{q="谁发布了这个任务？",a="该任务由布莱纳·火崖发布，她是位于铁炉堡Mystic Ward的矮人牧师训练师。",al={"谁发布重返家园","重返家园任务发布者","布莱纳·火崖位置"}},{q="我应该向达纳苏斯的谁报告？",a="你必须与女祭司阿兰希雅交谈，她就居住在达纳苏斯的月神殿内。",al={"重返家园交任务地点","女祭司阿兰希雅位置","重返家园任务交付"}},{q="艾露恩姐妹会为什么要召回牧师？",a="艾露恩姐妹会密切关注着每一位初学者。一旦侍僧证明了自己在外的能力，达纳苏斯的领导层就会召回他们，以进行进阶训练和诸如“艾露恩之星”之类的神圣仪式。",al={"为什么要重返家园","为什么要回达纳苏斯"}},{q="其他职业可以接这个任务吗？",a="不能，该任务是专门为在冒险初期前往丹莫罗和铁炉堡的暗夜精灵牧师准备的。",al={"战士能做重返家园吗","牧师职业任务"}},{q="交掉这个任务后会发生什么？",a="女祭司阿兰希雅会欢迎你回到达纳苏斯，并提供后续任务“艾露恩之星”，该任务将更深入地探索女神的教义。",al={"重返家园后续任务","重返家园后续"}},{q="布莱纳是怎么知道要找你的？",a="一位直接从月神殿派来的女祭司曾路过铁炉堡寻找侍僧，并向布莱纳这样的当地训练师留下了明确指示，要求她们将任何流浪的暗夜精灵指引回家。",al={"布莱纳为什么认识我","铁炉堡女祭司的口信"}}},fp="14,209,31.345.0,22.313.0,22.90.0,32.71.0,43.123.0,41.110.0,41.121.0,38.174.0"}
P.entries["quest:5634"] = {n="绝望祷言",s="“绝望祷言”是暴风城人类新手牧师的成人礼。它由光明大教堂的高阶牧师劳瑞娜授予，标志着一位侍僧致力于在动荡的联盟疆域中守护生命。通过完成这项精神试炼，牧师将获得一项紧急祝福，可以在万不得已之时治愈自己的伤口。",h="“绝望祷言”是暴风城人类新手牧师的成人礼。它由光明大教堂的高阶牧师劳瑞娜授予，标志着一位侍僧致力于在动荡的联盟疆域中守护生命。通过完成这项精神试炼，牧师将获得一项紧急祝福，可以在万不得已之时治愈自己的伤口。",kw={"cathedral of light","cathedral square","绝望祷言","高阶牧师劳瑞娜","圣光","劳瑞娜","牧师","暴风城"},ang={["class:Priest"]="这个仪式代表着你从一名学徒侍僧转变为圣光的现役仆人，能够在实地的致命考验中存活下来。",["faction:Alliance"]="通过“绝望祷言”之类的祝福来保护前线治疗者，对于在危险前线维持联盟士兵的战力至关重要。",["race:Human"]="人类牧师直接从光明大教堂的教阶体系中获得这一教导，这巩固了暴风城作为人类信仰中心地位的角色。"},sec={{t="黑暗中的祈求",b="在光明大教堂服役的牧师们被教导如何将信仰外化，以庇护战友、治愈凡人的创伤并惩戒邪恶。然而，即便是圣光最虔诚的仆人，有时也会发现自己陷入孤立无援、走投无路或是命悬一线的绝境。“绝望祷言”代表了一种私密的紧急沟通——当侍僧的个人生存命悬一线时，向神圣力量发出的原始呼唤。"},{t="大教堂的祝福",b="高阶牧师劳瑞娜监管着暴风城大教堂广场内的大多数神职人员，评估侍僧何时有资格获得更深奥的教义秘密。通过在王国各地展现对圣光美德的真正奉献，人类新晋成员获得的不仅是一项生存手段，更是一份庄严的肯定，确认他们持续的服役对王国依然至关重要。"}},faq={{q="绝望祷言的目的是什么？",a="“绝望祷言”是授予人类和矮人牧师的一项圣光紧急祷告。它允许受伤的牧师立即召唤神圣能量来治愈自己的严重创伤，而无需花费时间吟唱冗长的咒语。",al={"绝望祷言的作用","为什么要学习绝望祷言","绝望祷言的目的"}},{q="在暴风城是谁传授这一课程？",a="高阶牧师劳瑞娜，在暴风城大教堂广场的宏伟的光明大教堂内进行布道，她会在侍僧展现出足够的虔诚并在广阔的世界中积累了足够的经验后，传授这一课程。",al={"谁教授绝望祷言","在哪里学习绝望祷言","高阶牧师劳瑞娜的任务"}},{q="为什么牧师会获得这项特殊的教导？",a="圣光牧师经常为了帮助他人而将自己置于险境。“绝望祷言”作为一种神圣的保障，确保当治疗者发现自己被遗弃或身受重伤时，他们的信仰能够保全他们的生命。",al={"为什么牧师要学习绝望祷言","绝望祷言的背景故事"}},{q="任何冒险者都能在这里学习“绝望祷言”吗？",a="不能。这个任务和课程严格限定于那些潜心于圣光教义，并在圣光教会指导下学习的牧师。",al={"谁可以学习绝望祷言","这个任务是牧师专属吗"}},{q="这个仪式在哪里举行？",a="它在光明大教堂举行，那里是联盟的精神中心，高耸于暴风城的北区。",al={"绝望祷言的位置","劳瑞娜在哪里"}},{q="“绝望祷言”是人类牧师所独有的吗？",a="在联盟境内，人类和矮人神职人员都可以学习“绝望祷言”，因为这两个种族通过以暴风城和铁炉堡为中心的紧密盟友神职传统，共同崇敬着圣光。",al={"其他种族有绝望祷言吗","矮人绝望祷言"}}},fp="16,192,18.289.0,24.275.0,40.128.0,36.170.0,46.138.0,47.101.0,32.91.0,44.177.0"}
P.entries["quest:5635"] = {n="绝望祷言",s="“绝望祷言”是为那些服务于圣光教会的联盟新手牧师准备的入门任务。在艾尔文森林展现了初步的虔诚与修养后，那些极具潜力的侍僧们会被召集到暴风城的圣光大教堂，在高阶牧师劳瑞娜的指导下进一步进行神圣的修行。",h="“绝望祷言”是为那些服务于圣光教会的联盟新手牧师准备的入门任务。在艾尔文森林展现了初步的虔诚与修养后，那些极具潜力的侍僧们会被召集到暴风城的圣光大教堂，在高阶牧师劳瑞娜的指导下进一步进行神圣的修行。",kw={"cathedral of light","绝望祷言","闪金镇","高阶牧师劳瑞娜","圣光","牧师","女牧师洁塞塔","暴风城"},ang={["class:Priest"]="这项任务标志着你正式从闪金镇的教区见习生，转变为受到圣光大教堂高级领导层所托付的受认可门徒。",["faction:Alliance"]="圣光教会仍然是联盟在面对迫在眉睫的威胁时，凝聚彼此最重要的文化与道德支柱之一。",["race:Human"]="对于信仰圣光的人类来说，踏入巍峨的圣光大教堂是一次意义深远的朝圣，它将坚定你对王国精神核心的责任。"},sec={{t="来自首都的传唤",b="在艾尔文森林偏远定居点服务的见习牧师们，最初都是在当地导师（如闪金镇的女牧师洁塞塔）的指导下开启修行之路的。当某位门徒在精神与行为上证明了自己的能力后，消息很快会传到首都的高阶神职人员耳中。他们会收到直接前往圣光大教堂的传唤——那是暴风城王国的精神核心，意味着是时候开始承担教会更正式、更深层的职责了。"},{t="高阶牧师的指引",b="到达大教堂后，侍僧们会前往拜见高阶牧师劳瑞娜。作为城内教会最杰出的领袖之一，劳瑞娜负责监督新晋升牧师的精神基础和实践训练。她的教导将帮助信徒们为联盟所面临的严峻考验做好准备，传授关于圣光奇迹的关键知识——其中包括人类修行者所熟知的、那至关重要的救赎祈求：绝望祷言。"}},faq={{q="“绝望祷言”任务的目的是什么？",a="该任务指引那些达到10级的潜力牧师从闪金镇前往暴风城的圣光大教堂，让这些见习修行者与高阶牧师劳瑞娜建立联系，从而推进他们的神圣修行。",al={"绝望祷言任务","什么是绝望祷言任务","为什么要完成绝望祷言"}},{q="谁发布“绝望祷言”任务？",a="驻扎在闪金镇狮王之傲旅店的牧师训练师女牧师洁塞塔，会在你证明了虔诚之后发布这项传唤任务。",al={"谁发布绝望祷言","绝望祷言任务发布者"}},{q="高阶牧师劳瑞娜是谁？",a="高阶牧师劳瑞娜是圣光教会内的一位高级领袖，她居住在暴风城的圣光大教堂内，负责培训进阶侍僧。",al={"劳瑞娜是谁","高阶牧师劳瑞娜背景故事"}},{q="圣光大教堂位于哪里？",a="圣光大教堂耸立在暴风城北区的大教堂广场，是该王国牧师与圣骑士的精神中心。",al={"圣光大教堂在哪里","暴风城大教堂位置"}},{q="为什么任务被称为“绝望祷言”？",a="因为它标志着牧师在暴风城开始了进阶训练，在这里，人类牧师通常会学习被称为“绝望祷言”的祷文——这是一种向圣光祈求即时救赎、以保全自身的呼求。",al={"为什么叫绝望祷言","绝望祷言名称含义"}},{q="其他种族或职业可以接这个任务吗？",a="这一特定的任务线是专门为从艾尔文森林进阶、并准备在首都暴风城开始更高级学习的牧师设计的。",al={"矮人可以做绝望祷言任务吗","绝望祷言是牧师专属吗"}}},fp="16,228,24.392.0,32.399.0,50.140.0,37.128.0,30.132.0,40.157.0,40.147.0,41.99.0"}
P.entries["quest:5636"] = {n="绝望祷言",s="绝望祷言是一项联盟牧师任务，旨在引导圣光的旅行仆从返回暴风城。该任务由多兰纳尔的暗夜精灵牧师劳尔娜·晨光发起，要求前往泰达希尔的人类牧师返回家园，在高阶牧师劳瑞娜的指导下完成重要的修行。",h="绝望祷言是一项联盟牧师任务，旨在引导圣光的旅行仆从返回暴风城。该任务由多兰纳尔的暗夜精灵牧师劳尔娜·晨光发起，要求前往泰达希尔的人类牧师返回家园，在高阶牧师劳瑞娜的指导下完成重要的修行。",kw={"cathedral of light","绝望祷言","多兰纳尔","高阶牧师劳瑞娜","劳尔娜·晨光","牧师任务","暴风城","泰达希尔"},ang={["class:Priest"]="这项任务是10级时的一个重要成年仪式，引导牧师回归Cathedral of Light的怀抱，学习独特的种族信仰祝福。",["faction:Alliance"]="这次召唤展示了联盟内部日益增长的合作关系，暗夜精灵女祭司们非常乐意与暴风城的教会领袖进行协调。",["race:NightElf"]="尽管暗夜精灵崇拜月亮女神艾露恩，但牧师劳尔娜·晨光对漫步在泰达希尔枝桠下的圣光外族信徒表现出了礼貌的尊重。"},sec={{t="来自家乡的消息",b="当圣光信仰的牧师造访泰达希尔的远古枝桠时，可能会引起当地艾露恩姐妹会的注意。在多兰纳尔，牧师劳尔娜·晨光担任了一个意想不到的联络人，传达了一位来自你家乡的牧师跨越大陆寻找你的消息。意识到这份召唤的紧迫性，劳尔娜鼓励你立即返回家园，并献上艾露恩的祝福以及对你信仰的诚挚祝愿。"},{t="暴风城的召唤",b="这段旅程需要横跨无尽之海，前往位于暴风城中心的大教堂Cathedral of Light。在那里，高阶牧师劳瑞娜负责监管联盟信徒的精神成长。展现出早期潜力的侍僧会被传唤至她面前，以掌握更深奥的奉献奥秘，特别是被称为“绝望祷言”的紧急祈求——这是一种只授予在最黑暗时刻依然虔诚的信徒的救命恩赐。"}},faq={{q="谁在泰达希尔发布绝望祷言任务？",a="位于泰达希尔多兰纳尔的暗夜精灵牧师训练师劳尔娜·晨光会提供此任务。她会转达一封由来自你家乡的牧师留下的紧急信件。",al={"谁给予绝望祷言","泰达希尔绝望祷言任务发布者","劳尔娜·晨光任务"}},{q="这项任务引导玩家去哪里？",a="该任务引导你前往暴风城内的Cathedral of Light，在那里你必须直接与高阶牧师劳瑞娜交谈。",al={"我该去哪里","绝望祷言任务提交","劳瑞娜在哪里"}},{q="为什么暗夜精灵会指引牧师前往暴风城？",a="暗夜精灵牧师崇拜艾露恩，但冒险来到泰达希尔的外族牧师——如人类或矮人——仍然属于圣光信仰的传统。劳尔娜·晨光慷慨地尊重他们的信仰，并代为转达来自他们家乡宗教高层的讯息。",al={"为什么暗夜精灵送我去暴风城","暗夜精灵圣光"}},{q="完成此任务的奖励是什么？",a="向高阶牧师劳瑞娜报到将开启进阶的精神指导，并允许你学习瞬间施法的治疗法术：绝望祷言。",al={"绝望祷言奖励","我能学到什么法术"}},{q="暗夜精灵牧师可以接取这项特定的任务吗？",a="不能。暗夜精灵牧师崇拜艾露恩并学习星辰碎片，而不是绝望祷言。这项召唤专门针对在低等级阶段探索卡利姆多的人类牧师。",al={"暗夜精灵能做绝望祷言吗","暗夜精灵牧师绝望祷言"}},{q="如何从泰达希尔返回暴风城？",a="穿过达纳苏斯前往鲁瑟兰村，搭乘船只前往黑海岸的奥伯丁，然后从那里乘船直接横跨海洋抵达暴风城港口。",al={"如何从多兰纳尔去暴风城","泰达希尔到暴风城的路线"}}},fp="16,173,19.253.0,24.301.0,52.140.0,27.92.0,51.196.0,45.132.0,47.127.0,52.154.0"}
P.entries["quest:5637"] = {n="绝望祷言",s="“绝望祷言”是一项成人礼任务，召唤丹莫罗那些前途无量的矮人牧师前往暴风城宏伟的Cathedral of Light。高阶牧师劳瑞娜召唤这些新晋的侍僧，以提升他们的精神境界并解锁专门的神圣技能。它标志着牧师从地方训练迈向服务联盟更广阔领域的转变。",h="“绝望祷言”是一项成人礼任务，召唤丹莫罗那些前途无量的矮人牧师前往暴风城宏伟的Cathedral of...",kw={"cathedral of light","绝望祷言","丹莫罗","卡拉诺斯","劳瑞娜","马克萨恩·安沃尔","牧师","暴风城"},ang={["class:Priest"]="这个任务是你精神旅程中的一个里程碑，它连接了基本的教区职责与由教会领导层直接传授的高级神圣技能。",["faction:Alliance"]="铁炉堡和暴风城之间的精神合作确保了圣光修行者们能够超越种族界限团结一致。",["race:Dwarf"]="前往暴风城的大教堂加强了山脉王国铁炉堡与人类王国暴风城之间共同的精神盟约。"},sec={{t="大教堂的召唤",b="在丹莫罗冰雪中开始服役的牧师，终将超越卡拉诺斯的马克萨恩·安沃尔等当地导师的指导。当一名侍僧展现出真正的潜质时，高阶牧师劳瑞娜本人会发出正式的召唤。来自Cathedral of Light领导层的直接关注，意味着这位年轻的牧师已经准备好去探索信仰中更深奥的奥秘，并承担更大的责任。"},{t="跨越王国的羁绊",b="虽然铁炉堡在Mystic Ward保持着自己的神圣传统，但暴风城的圣光教会是人类和矮人共同的精神中心。通过矿道地铁向南旅行，将矮人侍僧与更广泛的教会团体联系起来，巩固了两个联盟王国之间共同的精神兄弟情谊。"}},faq={{q="为什么高阶牧师劳瑞娜要召唤矮人牧师前往暴风城？",a="高阶牧师劳瑞娜负责Cathedral of Light的高级宗教指导。当马克萨恩·安沃尔这样的当地导师发现侍僧已经掌握了基本教义时，就会将他们送往劳瑞娜处，接受诸如“绝望祷言”这类强力技能的专门训练。",al={"为什么劳瑞娜要召唤我","为什么牧师要去暴风城","谁是高阶牧师劳瑞娜"}},{q="“绝望祷言”在背景故事中是什么？",a="“绝望祷言”是人类和矮人圣光牧师所修行的一种紧急祈祷。当被逼至死亡边缘时，牧师会释放出一种本能的、急切的信仰呼喊，从而立即愈合伤口并恢复生命力。",al={"绝望祷言背景故事","什么是绝望祷言","绝望祷言如何运作"}},{q="这个任务在哪里进行？",a="召唤始于丹莫罗的卡拉诺斯，在那里马克萨恩·安沃尔会指引你前往暴风城。任务在暴风城Cathedral Square的Cathedral of Light内完成，高阶牧师劳瑞娜就在那里主持教务。",al={"任务地点","我该去哪里","劳瑞娜在哪里"}},{q="为什么矮人牧师会接受人类高阶牧师的训练？",a="矮人和人类拥有同样的圣光信仰，这种纽带在第二次战争期间得到了加强。虽然矮人牧师通常在铁炉堡的Mystic Ward服务，但暴风城的Cathedral of Light是该信仰最重要的中心之一，欢迎所有联盟的圣光修行者。",al={"为什么矮人要找人类导师","矮人圣光教会","铁炉堡与暴风城的圣光"}},{q="年轻的旅者应该如何从丹莫罗前往暴风城？",a="最快且最安全的路线是穿过铁炉堡的Tinker Town，那里的矿道地铁提供直接穿过山脉地下的交通工具，直达暴风城的Dwarven District。",al={"如何前往暴风城","矮人前往暴风城","矿道地铁"}},{q="马克萨恩·安沃尔是谁？",a="马克萨恩·安沃尔是一位驻扎在丹莫罗卡拉诺斯的矮人牧师训练师。他负责照看新晋的牧师，教导他们基础知识，直到他们训练有素，足以在暴风城的教会高层领导下学习。",al={"马克萨恩·安沃尔背景故事","谁给的任务","卡拉诺斯牧师训练师"}}},fp="16,223,26.310.0,21.291.0,67.260.0,37.181.0,33.195.0,60.234.0,60.119.0,19.177.0"}
P.entries["quest:5638"] = {n="绝望祷言*",s="“绝望祷言”是一项为在暴风城公园区修行的牧师所准备的成人仪式。在暗夜精灵牧师娜拉·梅德隆的指引下，新晋牧师们会被派往运河对岸的圣光大教堂，在高阶牧师劳瑞娜的指导下继续接受神圣的教导。这标志着一位新徒从基础的实地职责向更深层次、更专业的圣光交流迈进。",h="“绝望祷言”是一项为在暴风城公园区修行的牧师所准备的成人仪式。在暗夜精灵牧师娜拉·梅德隆的指引下，新晋牧师们会被派往运河对岸的圣光大教堂，在高阶牧师劳瑞娜的指导下继续接受神圣的教导。这标志着一位新徒从基础的实地职责向更深...",kw={"cathedral of light","绝望祷言","高阶牧师劳瑞娜","圣光","娜拉·梅德隆","牧师任务","暴风城","公园区"},ang={["class:Priest"]="这个召唤标志着你正式步入更高阶的精神修习，并开启了掌握救命法术“绝望祷言”的道路。",["faction:Alliance"]="公园区的娜拉·梅德隆与大教堂广场的神职人员之间的合作，凸显了达纳苏斯与暴风城神圣组织之间静默的团结。",["race:Human"]="圣光大教堂是东部王国南部人类崇拜的至高圣殿，劳瑞娜的指导在文化和精神层面上都是一个里程碑。"},sec={{t="公园中的讯息",b="在公园区宁静的树林中，像娜拉·梅德隆这样的暗夜精灵牧师在暴风城的喧嚣中依然与艾露恩保持着交流。然而，联盟精神导师们之间的信仰纽带跨越了文化隔阂。当来自大教堂广场的使者寻找有前途的学生时，娜拉会悄声鼓励并传达召唤，让新徒不必惊慌，因为这是一个好消息。"},{t="大教堂的召唤",b="穿过大教堂广场，步入圣光大教堂高耸的白色石拱门下，新徒需要向高阶牧师劳瑞娜报到。作为暴风城资历最深的教士领袖之一，劳瑞娜不仅指导年轻侍僧研习基础祷言，还会传授那被称为“绝望祷言”的神圣祈祷——这是一份向神灵寻求干预的个人恳求，当圣光的仆人在面对死亡的边缘时，它能瞬间治愈严重的创伤。"}},faq={{q="谁派我执行这个任务？",a="娜拉·梅德隆，一位位于暴风城公园区的暗夜精灵牧师，她会传达大教堂领导层正在寻找你的消息。",al={"任务发布者","谁传授绝望祷言","娜拉·梅德隆"}},{q="我需要去暴风城的什么地方报到？",a="你必须与高阶牧师劳瑞娜交谈，她位于暴风城大教堂广场的圣光大教堂内。",al={"去哪里","任务交还","劳瑞娜是谁"}},{q="绝望祷言有什么意义？",a="绝望祷言是人类和矮人圣光教士所研习的一项重要修行。它是一种瞬间的祈祷，能够在极度危险的时刻召唤神圣的恩典，瞬间恢复施法者的生命。",al={"绝望祷言的作用","牧师技能背景","绝望祷言法术"}},{q="为什么暗夜精灵会引导牧师去人类的大教堂？",a="虽然暗夜精灵牧师崇拜艾露恩，而不是人类和矮人所践行的圣光，但暴风城的宗教团体之间保持着密切的联系和相互尊重，当联盟的教士需要培训时，他们会分享讯息。",al={"为什么是娜拉·梅德隆","从公园区去大教堂","暗夜精灵艾露恩暴风城"}},{q="这个召唤出现在修行的什么阶段？",a="这个召唤大约在第十等级左右出现，标志着年轻的牧师已经在实战中证明了自己的能力，可以处理要求更高的神圣仪式了。",al={"这是什么等级的任务","我什么时候能获得绝望祷言"}},{q="圣光大教堂在哪里？",a="圣光大教堂坐落在大教堂广场，位于暴风城北部的矮人区和公园区之间。",al={"大教堂位置","大教堂广场在哪里"}}},fp="16,162,18.295.0,25.368.0,27.122.0,40.97.0,45.179.0,60.206.0,50.145.0,40.120.0"}
P.entries["quest:5639"] = {n="绝望祷言*",s="“绝望祷言”是矮人牧师在铁炉堡成年礼中的一项仪式。受高阶牧师洛汉派遣，侍僧们必须搭乘矿道地铁前往暴风城，在高阶牧师劳瑞娜的指导下继续他们的训练。抵达宏伟的圣光大教堂，标志着一名新晋牧师在治疗与生存之道的修行上迈向了更深奥的领域。",h="“绝望祷言”是矮人牧师在铁炉堡成年礼中的一项仪式。受高阶牧师洛汉派遣，侍僧们必须搭乘矿道地铁前往暴风城，在高阶牧师劳瑞娜的指导下继续他们的训练。抵达宏伟的圣光大教堂，标志着一名新晋牧师在治疗与生存之道的修行上迈向了更深奥...",kw={"cathedral of light","绝望祷言","铁炉堡","劳瑞娜","mystic ward","牧师","洛汉","暴风城"},ang={["class:Priest"]="这次朝圣标志着你从铁炉堡的地方训练中毕业，正式步入圣光教会更广阔的等级体系之中。",["faction:Alliance"]="牧师的共同训练体现了铁炉堡与暴风城之间深厚的精神团结与机构合作。",["race:Dwarf"]="对于年轻的卡兹莫丹矮人来说，前往暴风城能让他们初次领略人类文化、宏伟建筑以及共同的精神信仰。"},sec={{t="暴风城的召唤",b="在铁炉堡秘法区的石拱拱顶下，高阶牧师洛汉负责指导那些致力于圣光的矮人学徒。当侍僧展现出足够的纪律与信仰时，洛汉会指引他们前往西南方的人类王国暴风城。人类与矮人牧师之间保持着紧密的精神纽带，而高等神学教育便集中在暴风城那宏伟的大厅之中。"},{t="圣光大教堂",b="通过地下的矿道地铁抵达后，侍僧们会前往大教堂广场。在那里，在那雄伟的圣光大教堂内，高阶牧师劳瑞娜将代表教会对候选人进行考验。她的教导侧重于牧师在战斗的严酷考验中必须发出的绝望呼求——当体力耗尽、死亡临近时，向神圣力量祈求干预。"}},faq={{q="谁派我执行这项任务？",a="这项任务由高阶牧师洛汉提供。他负责管理铁炉堡秘法区内秘法大厅的矮人神职人员。",al={"谁给予任务","任务发放人","洛汉位置"}},{q="我需要去哪里完成这个任务？",a="你需要前往暴风城大教堂广场中心的圣光大教堂。高阶牧师劳瑞娜就在主圣殿内等候。",al={"劳瑞娜在哪里","在哪里交任务","暴风城交任务"}},{q="从铁炉堡前往暴风城的最佳方式是什么？",a="最快且最安全的路线是搭乘矿道地铁，这是一项由侏儒建造的工程奇迹。它的入口位于铁炉堡的东部，直接连接着暴风城的矮人区。",al={"如何前往暴风城","前往暴风城","地铁位置"}},{q="为什么矮人牧师必须到人类城市去训练？",a="圣光教会深深扎根于人类传统之中，其主要的学术殿堂便是圣光大教堂。矮人与人类的牧师阶层协同工作，在整个联盟内分享教义与传统。",al={"为什么去暴风城","矮人人类教会","为什么要找劳瑞娜"}},{q="这项训练能解锁什么技能？",a="这条任务线将引导你学习“绝望祷言”，这是一个瞬发的自我保护祷言，能在危急时刻迅速恢复牧师的生命值。",al={"任务奖励","我获得了什么法术","绝望祷言技能"}},{q="这项任务包含战斗吗？",a="不包含。这纯粹是一次朝圣与外交使命，你只需要安全地从铁炉堡旅行至暴风城，向高阶牧师劳瑞娜引荐自己即可。",al={"有战斗吗","任务战斗","旅行任务"}}},fx={c0c688ec={q="高阶牧师洛汉为什么派你去暴风城？",a="暴风城的高阶牧师劳瑞娜来信要求你前去，认为你已准备好证明自己，接受下一阶段的神圣训练。洛汉尊重来自Cathedral of Light的召唤，相信你在劳瑞娜的指导下将更加虔诚，也会更深入地掌握圣光的恩赐。",al={"洛汉为什么派你去","牧师为什么要去暴风城","洛汉绝望祷言的用意"}}},fp="16,346,22.399.0,22.379.0,27.132.0,39.161.0,56.217.0,52.225.0,39.167.0,31.166.0"}
P.entries["quest:564"] = {n="损失惨重",s="南海镇的达伦·玛尔维对于丢失镇上漂亮的马匹感到非常痛恨。亡灵、辛迪加匪徒和各种恶棍已经造成了巨大的损失，但达伦说，没有什么比从奥特兰克山脉走下来的那些山地狮对它们的威胁更大了。",h="南海镇的达伦·玛尔维对于丢失镇上漂亮的马匹感到非常痛恨。亡灵、辛迪加匪徒和各种恶棍已经造成了巨大的损失，但达伦说，没有什么比从奥特兰克山脉走下来的那些山地狮对它们的威胁更大了。",kw={"奥特兰克山脉","昂贵的威胁","达伦·玛尔维","希尔斯布莱德丘陵","马匹","巨型山地狮","山地狮","南海镇"},sec={{t="损失的马匹",b="南海镇的达伦·玛尔维无法忍受那里漂亮的马匹不断丢失。有不少马匹被亡灵生物、辛迪加匪徒和在这一带游荡的恶棍夺去了性命。不过，照达伦的话说，对马匹最大的威胁还是那些从奥特兰克山上不断跑下来的山地狮。"},{t="山中的雄狮",b="达伦希望你能去对付这些狮子：杀死八只山地狮和十只巨型山地狮。山地狮出没于奥特兰克山脉的低矮山丘中。"}},faq={{q="达伦·玛尔维是谁？",a="达伦·玛尔维来自希尔斯布莱德丘陵的南海镇，他对于不断丢失镇上的马匹感到厌烦。",al={"达伦·玛尔维","谁发布了昂贵的威胁","达伦·玛尔维 南海镇 马匹"}},{q="山地狮从哪里来？",a="它们从奥特兰克山上下来。山地狮出没于奥特兰克山脉的低矮山丘中。",al={"山地狮位置","山地狮在哪里","去哪里找狮子"}},{q="达伦提到了哪些对马匹的威胁？",a="亡灵生物、辛迪加匪徒和该地区的其他恶棍导致南海镇损失了许多马匹，但达伦说奥特兰克山的山地狮是最大的威胁。",al={"南海镇的威胁","什么攻击了南海镇的马匹","达伦·玛尔维的敌人"}},{q="需要消灭哪些特定的野兽？",a="八只山地狮和十只巨型山地狮。",al={"要杀哪些狮子","巨型山地狮 昂贵的威胁","昂贵的威胁 目标"}}},fp="13,255,11.322.0,18.157.0,21.99.0,41.111.0,47.174.0,39.52.0"}
P.entries["quest:5640"] = {n="绝望祷言",s="“绝望祷言”是一个给予造访达纳苏斯的年轻人类和矮人牧师的任务，指引他们回到暴风城的自身信仰传统中。女祭司阿兰希雅认识到，虽然暗夜精灵从艾露恩那里汲取力量，但圣光信徒必须寻求自己信仰的导师。完成这趟旅程后，侍僧将回到光明大教堂的高阶牧师劳瑞娜身边。",h="“绝望祷言”是一个给予造访达纳苏斯的年轻人类和矮人牧师的任务，指引他们回到暴风城的自身信仰传统中。女祭司阿兰希雅认识到，虽然暗夜精灵从艾露恩那里汲取力量，但圣光信徒必须寻求自己信仰的导师。完成这趟旅程后，侍僧将回到光明大...",kw={"阿兰希雅","cathedral of light","达纳苏斯","绝望祷言","艾露恩","圣光","劳瑞娜","暴风城"},ang={["class:Priest"]="这个任务突显了联盟中的圣光魔法是如何在艾露恩崇拜和圣光信仰之间划分的，指引年轻的侍僧回到他们合适的导师身边。",["race:Dwarf"]="崇尚圣光的矮人牧师与暴风城的大教堂有着紧密的联系，并与他们的人类同胞一起学习高级的祷言。",["race:Human"]="远离家乡的人类牧师被提醒，他们真正的精神家园和训练等待着他们回到暴风城的光明大教堂。",["race:NightElf"]="艾露恩的暗夜精灵姐妹以礼貌的姿态承认外来信仰的力量，但她们始终只保持对月亮女神的忠诚。"},sec={{t="信仰的两条道路",b="行走在联盟信仰道路上的牧师所引用的圣洁源头有着本质的不同。在达纳苏斯，艾露恩祭司守护着月亮女神，引导着她柔和的光辉与天界的愤怒。当人类和矮人侍僧在泰达希尔的枝叶下旅行时，像女祭司阿兰希雅这样的导师会礼貌地指出这种分歧：虽然她尊崇艾露恩并尊重圣光，但她无法教导其他种族那些与完全不同的信仰相关联的深奥祈祷。"},{t="回到大教堂",b="为了掌握源于绝对信仰的能力——例如在身陷绝境时召唤紧急的神圣干预——圣光的新手们被告知要回到家乡。高阶牧师劳瑞娜在暴风城光明大教堂高耸的大理石拱门下主持训练，随时准备引导回归的牧师学习他们职业中更深奥的仪式。"}},faq={{q="为什么达纳苏斯的牧师要派我去暴风城？",a="女祭司阿兰希雅传授月亮女神艾露恩的教义。由于人类和矮人的信仰与神迹源自圣光，阿兰希雅礼貌地将他们指引向自己传统的导师，例如暴风城的高阶牧师劳瑞娜。",al={"为什么要去暴风城","为什么阿兰希雅要打发我走","达纳苏斯到暴风城的牧师任务"}},{q="女祭司阿兰希雅是谁？",a="女祭司阿兰希雅是一位驻守在达纳苏斯月神殿的暗夜精灵女祭司。她指导艾露恩的追求者，并为造访世界之树的外族牧师提供尊重的指引。",al={"阿兰希雅背景故事","谁是阿兰希雅"}},{q="高阶牧师劳瑞娜是谁？",a="高阶牧师劳瑞娜是一位驻守在暴风城光明大教堂内的人类精神领袖。她担任圣光忠实信徒的导师，帮助他们掌握高级祈祷和庄严的职责。",al={"谁是劳瑞娜","高阶牧师劳瑞娜暴风城"}},{q="在背景故事中，绝望祷言是什么？",a="绝望祷言代表了当牧师濒临死亡或处于致命危险时，对神圣援助的即时呼唤。这是授予圣光忠实信徒的一项标志性祈祷，旨在为他们提供即时的恢复。",al={"什么是绝望祷言","绝望祷言技能背景"}},{q="暗夜精灵可以教授圣光吗？",a="不能。暗夜精灵几乎只崇拜艾露恩并引导她的月亮力量。虽然他们以外交礼仪尊重圣光，但他们不传道也不教授圣光的特定祷文，这些工作留给了人类和矮人的牧师群体。",al={"暗夜精灵了解圣光吗","艾露恩与圣光"}},{q="我在哪里可以找到高阶牧师劳瑞娜？",a="高阶牧师劳瑞娜居住在暴风城的Cathedral Square，站在光明大教堂内，周围是她的教士同僚和白银之手骑士团的圣骑士们。",al={"劳瑞娜位置","劳瑞娜在哪里"}}},fp="16,271,18.353.0,23.227.0,49.185.0,25.185.0,30.174.0,37.161.0,37.191.0,40.145.0"}
P.entries["quest:5643"] = {n="暗影守卫",s="暗影守卫是一项指引暗矛巨魔牧师的圣职，这些牧师在远离家乡的幽暗城。艾萨莱斯特意识到这名年轻的巨魔已经成长到可以进行他们部落的神圣仪式了，于是指引他们回到奥格瑞玛。在Valley of Spirits，牧师训练师乌尔库正等待着引导他们获得至关重要的精神防护。",h="暗影守卫是一项指引暗矛巨魔牧师的圣职，这些牧师在远离家乡的幽暗城。艾萨莱斯特意识到这名年轻的巨魔已经成长到可以进行他们部落的神圣仪式了，于是指引他们回到奥格瑞玛。在Valley of...",kw={"艾萨莱斯特","奥格瑞玛","成人礼","暗影守卫","巨魔牧师","幽暗城","乌尔库","valley of spirits"},ang={["class:Priest"]="这场仪式是牧师道路上的一个决定性里程碑，将神圣和暗影魔法的通用基础与他们民族独特的文化传统区分开来。",["race:Troll"]="对于暗矛巨魔来说，牧师训练与和洛阿的交流以及保卫部落是密不可分的，这是乌尔库在Valley of Spirits所保存的遗产。",["race:Undead"]="像艾萨莱斯特这样的训练师承认其活着的盟友拥有独特的传统，确保造访的巨魔能从他们自己的长者那里获得指导，而不是强迫他们接受被遗忘者的教条。"},sec={{t="跨越大陆的召唤",b="即使在幽暗城的阴影中，信仰和部落传统的纽带依然牢固。被遗忘者牧师训练师艾萨莱斯特密切观察着前来拜访的巨魔牧师，注意着每一位新兵何时足够强大，能够面对他们文化中的试炼。她没有将被遗忘者牧师那凄凉的哲学强加给他们，而是指引这名巨魔跨越无尽之海，回到他们祖先传统的道路上。"},{t="Valley of Spirits",b="在抵达杜隆塔尔后，牧师会前往奥格瑞玛内神秘的Valley of Spirits。在那里，乌尔库照看着暗矛巨魔部落的精神需求和古老仪式。他欢迎归来的新兵，为他们准备了一场至关重要的成人礼，将牧师与洛阿的纽带与对抵御伤害至关重要的实用法术联系起来。"}},faq={{q="谁会发布这个任务？",a="该任务由艾萨莱斯特发布，她是一位居住在幽暗城War Quarter的牧师训练师。她能看出巨魔牧师何时达到了他们部落进行精神试炼所需的成熟度。",al={"任务发布者","任务起始地点","谁提供暗影守卫任务"}},{q="为什么幽暗城的训练师要送我去奥格瑞玛？",a="虽然被遗忘者牧师转向了暗影，但暗矛巨魔从洛阿和他们的部落传统中汲取精神力量。艾萨莱斯特尊重这种差异，并将成长的巨魔牧师送回家乡，向他们自己的长者学习独特的种族技艺。",al={"为什么要前往奥格瑞玛","从幽暗城到奥格瑞玛","为什么找乌尔库"}},{q="乌尔库是谁？",a="乌尔库是一位著名的暗矛巨魔牧师训练师，驻扎在奥格瑞玛的Valley of Spirits。他担任巨魔精神习俗和成人礼的导师。",al={"乌尔库背景故事","乌尔库是谁","牧师训练师乌尔库"}},{q="暗影守卫技能的重要性是什么？",a="暗影守卫是巨魔牧师特有的一种防护结界。通过呼唤暗影之灵和洛阿的祝福，它会显化为绕身旋转的暗影，对任何胆敢攻击施法者的敌人进行反击。",al={"什么是暗影守卫","暗影守卫法术背景","为什么它很重要"}},{q="其他种族会接到这个任务吗？",a="这次特别的召唤仅针对那些在二十岁经验左右造访幽暗城的暗矛巨魔牧师。被遗忘者牧师在幽暗城有自己独立的仪式和训练。",al={"不死族可以做这个任务吗","这是巨魔专属任务吗","牧师种族任务"}},{q="乌尔库在奥格瑞玛的什么位置？",a="可以在奥格瑞玛的Valley of Spirits找到乌尔库，这是奥格瑞玛南部为暗矛巨魔及其神秘习俗划定的区域。",al={"乌尔库在哪里","乌尔库位置","寻找乌尔库"}}},fp="11,188,27.299.0,21.258.0,22.163.0,51.253.0,14.135.0,52.143.0,34.167.0,37.132.0"}
P.entries["quest:5644"] = {n="噬灵瘟疫",s="“噬灵瘟疫”是远离洛丹伦远行的被遗忘者牧师的成人礼任务。在雷霆崖的被遗忘者牧师训练师麦尔斯·威尔什的指引下，这位学徒被指引跨越海洋，回到幽暗城的艾萨莱斯特那里，以解锁暗影魔法的一种标志性表现形式。",h="“噬灵瘟疫”是远离洛丹伦远行的被遗忘者牧师的成人礼任务。在雷霆崖的被遗忘者牧师训练师麦尔斯·威尔什的指引下，这位学徒被指引跨越海洋，回到幽暗城的艾萨莱斯特那里，以解锁暗影魔法的一种标志性表现形式。",kw={"艾萨莱斯特","噬灵瘟疫","被遗忘者","麦尔斯·威尔什","暗影牧师","雷霆崖","幽暗城","war quarter"},ang={["class:Priest"]="这个任务标志着被遗忘者牧师教育中的一个重要里程碑，使他们从基础信条转向亡灵特有的恐怖暗影传统。",["faction:Horde"]="该任务阐明了连接莫高雷偏远的部落哨站与幽暗城黑暗核心之间的后勤和精神纽带。",["race:Undead"]="与生前所信奉的圣光不同，被遗忘者牧师拥抱残酷的折磨和诸如噬灵瘟疫之类的暗影魔法。"},sec={{t="归乡的召唤",b="在造访雷霆崖期间，那些已磨练出对神圣和暗影法术掌握能力的被遗忘者牧师会接受驻扎在牛头人中的被遗忘者牧师麦尔斯·威尔什的评估。麦尔斯认识到这位侍僧的力量已经足够强大，便要求他们返回洛丹伦废墟，而不是尝试自己在卡利姆多亲自传授这些更高深的奥秘。"},{t="艾萨莱斯特的秘密",b="在幽暗城War Quarter的城市废墟之下，艾萨莱斯特正在等待，她是受人尊崇的被遗忘者牧师导师之一。她看管着暗影织造侍僧的成长，确保那种被称为噬灵瘟疫的强效吸取性疫病，只被传授给那些有能力驾驭其腐化力量而不被其反噬的人。"}},faq={{q="谁指派给你这个任务？",a="麦尔斯·威尔什，一位驻扎在雷霆崖灵魂高地下方预见之池的被遗忘者牧师训练师，会在你的能力得到充分发展后指派你踏上这段旅程。",al={"谁开启噬灵瘟疫任务","噬灵瘟疫任务发布者","麦尔斯·威尔什的角色"}},{q="艾萨莱斯特在哪里？",a="艾萨莱斯特居住在幽暗城的War Quarter，站在被遗忘者牧师们聚集的训练环和黑暗导管之中。",al={"艾萨莱斯特的位置","艾萨莱斯特在哪里","噬灵瘟疫任务交付"}},{q="为什么麦尔斯·威尔什不能亲自传授这个法术？",a="法术本身并非秘密：每位牧师在20级时都能从牧师训练师那里学会噬灵瘟疫。但威尔什通过将值得栽培的高阶学徒送回家乡来尊重被遗忘者牧师的等级制度，这样像艾萨莱斯特这样的大师级导师就能在幽暗城的心脏地带考验他们。",al={"为什么要前往幽暗城","为什么要见艾萨莱斯特","幽暗城牧师训练师"}},{q="从背景设定来看，什么是噬灵瘟疫？",a="这是一种被遗忘者牧师所施展的毁灭性诅咒，使受害者受到一种恶毒的魔法折磨，这种魔法会消耗受害者的生命力来恢复施法者自身。",al={"什么是噬灵瘟疫","噬灵瘟疫的背景设定","被遗忘者疾病法术"}},{q="这个任务其他种族可以接吗？",a="不可以。这次召唤仅针对被遗忘者牧师，尽管每位牧师，无论其种族为何，都能在20级时从牧师训练师那里学会噬灵瘟疫。",al={"巨魔可以做噬灵瘟疫任务吗","兽人可以做噬灵瘟疫吗","这个任务仅限亡灵吗"}},{q="为什么雷霆崖会有被遗忘者的训练师？",a="在被遗忘者加入部落后，各大主城之间便开始了外交官和导师的互派。像麦尔斯·威尔什这样的牧师代表了幽暗城的精神传统，并为在卡利姆多旅行的被遗忘者提供指导。",al={"为什么雷霆崖有亡灵","雷霆崖的被遗忘者背景设定","麦尔斯·威尔什雷霆崖"}}},fx={ec2983f6={q="麦尔斯·威尔什为什么派你去幽暗城？",a="麦尔斯·威尔什明白，你对牧师之道的领悟已超出异乡基础课程所能传授的范围。作为驻扎在牛头人中间的代表，他有责任辨识出哪位有潜力的被遗忘者牧师已准备好探寻更深奥的奥秘。他没有阻碍你的进步，而是送你回到艾萨莱斯特身边，让你接受被遗忘者牧师职业的黑暗教诲。",al={"麦尔斯·威尔什为什么要我完成这件事","麦尔斯·威尔什的用意","为什么去幽暗城"}},["988f0d1b"]={q="麦尔斯·威尔什为什么要你亲自前往，而不是自己去传话？",a="麦尔斯·威尔什是驻扎在雷霆崖高台上的被遗忘者访客的使节与导师；他的职责要求他留在高台，教导并代表自己的族人。更重要的是，这趟旅程关乎你个人的晋升。幽暗城的高阶女牧师要求你亲自到场，以便在传授致命的教诲前，亲自判断你的灵性成长。",al={"为什么是我","为什么派我去","麦尔斯为什么需要我"}}},fp="16,291,14.368.0,26.361.0,28.184.0,29.139.0,46.266.0,49.165.0,39.149.0,62.235.0"}
P.entries["quest:5645"] = {n="毫无畏惧",s="“无畏”是矮人牧师的成人仪式召唤，旨在将有前途的门徒召回铁炉堡的宏伟殿堂。高阶牧师洛汉在Mystic Ward等待着他们，以考验他们的纪律，并传授根据他们不断增长的韧性而定制的教义。",h="“无畏”是矮人牧师的成人仪式召唤，旨在将有前途的门徒召回铁炉堡的宏伟殿堂。高阶牧师洛汉在Mystic Ward等待着他们，以考验他们的纪律，并传授根据他们不断增长的韧性而定制的教义。",kw={"阿兰希雅","恐惧结界","hall of mysteries","铁炉堡","劳瑞娜","mystic ward","牧师","洛汉"},ang={["class:Priest"]="这次召唤标志着你在牧师教团中的成人仪式，使你有资格学习由铁炉堡坚定神职人员所磨炼出的特定神圣技巧。",["faction:Alliance"]="联盟的牧师教团在各个主城之间保持着密切的交流，派遣侍僧跨越疆界前往铁炉堡，向资深神职人员学习。",["race:Dwarf"]="回到洛汉身边，是对你族人那不可动摇的信仰、身体的坚韧以及在圣光服务中所展现出的战斗毅力这一独特结合的敬意。"},sec={{t="铁炉堡的召唤",b="在外服役的联盟牧师通常会得到当地导师的指引，向教会的高级神职人员报到。对于矮人门徒来说，这条指引将他们直接带到位于铁炉堡Mystic Ward中心的高阶牧师洛汉面前。这次召唤标志着一个转折点，从基础的灵性修行转向更深奥、经受过考验的神圣魔法应用。"},{t="坚韧的试炼",b="高阶牧师洛汉并不只是传授圣礼；矮人传统将圣光视为物理冲突中的盾牌和坚不可摧的堡垒。前来参加这项测试意味着新手已经在更广阔的世界中经受了战火的洗礼，并拥有在前线掌控恐惧本身所需的勇气。"}},faq={{q="这个任务的目的是什么？",a="这是一个来自当地牧师训练师，要求前往铁炉堡高阶牧师洛汉处的正式召唤，旨在指引经验丰富的入门者接受进阶指导，并获得该城牧师所修习的专门灵性天赋。",al={"为什么要去找洛汉","无畏的作用","牧师任务 20级 铁炉堡"}},{q="高阶牧师洛汉是谁？",a="高阶牧师洛汉是铁炉堡矮人牧师的资深领袖。他在Mystic Ward的Hall of Mysteries内训练门徒，专注于坚定的奉献和战斗韧性。",al={"洛汉是谁","高阶牧师洛汉背景故事"}},{q="在哪里可以找到高阶牧师洛汉？",a="洛汉位于Hall of Mysteries内，该地点位于铁炉堡西区的Mystic Ward中。",al={"洛汉在哪里","洛汉位置","如何找到高阶牧师洛汉"}},{q="为什么这个任务被称为“无畏”？",a="这个名字指的是“恐惧结界”，这是圣光为心灵提供的免受恐慌和超自然恐惧侵害的保护。每位牧师，无论种族为何，都能在20级时从牧师训练师那里学习“恐惧结界”。",al={"无畏的含义","恐惧结界任务"}},{q="谁将牧师派往铁炉堡？",a="入门者通常由当地训练师派遣，例如暴风城的高阶牧师劳瑞娜或达纳苏斯的女祭司阿兰希雅，她们指引学生去传承他们的血统，或在洛汉的教导下学习。",al={"谁发布无畏任务","无畏的任务发布者"}},{q="这个任务需要战斗吗？",a="不需要。该任务只需要前往铁炉堡并与高阶牧师洛汉交谈。",al={"需要战斗吗","无畏任务有战斗吗"}}},fx={["54793667"]={q="为什么有人召你去见高阶牧师洛汉？",a="其他城市的牧师训练师都看出，你的信仰与战斗本领已有显著长进。铁炉堡的高阶牧师洛汉负责监督当地联盟牧师的训练，尤其是矮人独有的修行方式与仪式。他召见你，是因为你已证明自己准备好迎接下一场考验，学习更高深的神圣教诲。",al={"为什么去见洛汉","无所畏惧的用意","为什么派我去铁炉堡"}}},fp="14,258,22.369.0,23.326.0,34.231.0,25.202.0,37.112.0,36.196.0,34.221.0,31.80.0"}
P.entries["quest:5646"] = {n="噬灵瘟疫",s="“噬灵瘟疫”是亡灵牧师的一个成人礼任务，他们前往卡利姆多向暗矛巨魔学习。奥格瑞玛的巨魔牧师训练师乌尔库指引这些前途无量的亡灵新兵返回家园幽暗城，在那里，艾萨莱斯特正等待着向他们传授更深奥的暗影教义。",h="“噬灵瘟疫”是亡灵牧师的一个成人礼任务，他们前往卡利姆多向暗矛巨魔学习。奥格瑞玛的巨魔牧师训练师乌尔库指引这些前途无量的亡灵新兵返回家园幽暗城，在那里，艾萨莱斯特正等待着向他们传授更深奥的暗影教义。",kw={"艾萨莱斯特","噬灵瘟疫","亡灵牧师","奥格瑞玛","暗影牧师","幽暗城","乌尔库","war quarter"},ang={["class:Priest"]="亡灵牧师利用独特的种族暗影和腐朽学说，学会将身体的痛苦转化为像虚弱之触和黑暗牺牲这样的黑暗仪式。",["faction:Horde"]="杜隆塔尔的乌尔库和提瑞斯法林地的艾萨莱斯特之间共同的训练职责，说明了将遥远的部落首府紧密联系在一起的实际合作与相互尊重。",["race:Undead"]="回到幽暗城的War Quarter提醒亡灵冒险者，无论部落职责将他们带到多远的地方，他们真正的效忠对象和精神根源始终位于洛丹伦废墟之下。"},sec={{t="信仰的交流",b="虽然兽人和牛头人对牧师信仰兴趣不大，但暗矛巨魔和亡灵在部落内部有着一种奇特的宗教纽带。在奥格瑞玛，巨魔牧师训练师乌尔库指引着那些被精神力量所吸引的人。然而他也认识到，亡灵新兵最终必须掌握其自身种族特有的邪恶艺术。出于种族间相互尊重，乌尔库指引游历的亡灵回到洛丹伦完成他们的训练。"},{t="幽暗城的War Quarter",b="在洛丹伦废墟之下，牧师艾萨莱斯特在幽暗城的War Quarter照料着信徒。亡灵牧师走的是一条孤独而艰苦的道路，这条道路由他们转向暗影所塑造，用暗影魔法的毁灭性折磨来调和圣光带来的痛苦触感。当新兵达到足够的造诣时，艾萨莱斯特会将他们召集到身边，传授他们种族特有的法术——噬灵瘟疫。"}},faq={{q="谁会派我去执行这个任务？",a="乌尔库，这位在奥格瑞玛的精神世界中被发现的巨魔牧师训练师，会向达到二十级力量的亡灵牧师提供此任务。",al={"任务发布者","谁开启噬灵瘟疫","乌尔库位置"}},{q="我需要去哪里？",a="你必须穿越无尽之海前往提瑞斯法林地的幽暗城。找到在War Quarter主持亡灵牧师训练的艾萨莱斯特牧师。",al={"我在哪里交任务","艾萨莱斯特位置","幽暗城牧师训练师"}},{q="为什么乌尔库会把亡灵送回洛丹伦？",a="乌尔库遵循着与艾萨莱斯特牧师的约定。虽然巨魔暗影牧师了解洛阿神灵和灵魂，但亡灵所操纵的暗影艺术与他们作为亡灵的本质紧密相连，需要直接接受他们自己领袖的指导。",al={"为什么要回幽暗城","为什么巨魔牧师要把我送走"}},{q="噬灵瘟疫有什么意义？",a="噬灵瘟疫是一种强大的暗影折磨，每位牧师在20级时都会学习它。它会对目标施加毁灭性的疾病，同时直接将目标的生命力汲取回施法者体内。",al={"噬灵瘟疫背景故事","亡灵牧师瘟疫"}},{q="其他部落种族可以接受这个任务吗？",a="不能。这个任务专门提供给亡灵牧师，代表了他们与其祖国独特的暗影学派的共鸣。",al={"巨魔能做这个吗","这是亡灵专属任务吗"}},{q="这如何融入部落牧师的关系中？",a="部落依赖于卡利姆多的暗矛巫医和妖术师与东部王国的亡灵暗影牧师之间的相互交流，双方都指引旅行者去寻找最适合其文化的导师。",al={"巨魔和亡灵牧师","部落牧师背景"}}},fp="16,231,21.415.0,28.419.0,27.146.0,22.146.0,48.211.0,49.189.0,40.125.0,46.211.0"}
P.entries["quest:5648"] = {n="灵魂之衣",s="Garments of Spirituality 是杜隆塔尔的部落牧师的成年礼，由剃刀岭的泰金委派。新手会被派往野外，寻找并治愈一名正在警戒库尔提拉斯幸存者的受伤步兵 Grunt Kor'ja。完成此任务后，牧师将获得他们第一套礼仪法袍，并获得部落灵性修行者间的正式认可。",h="Garments of Spirituality 是杜隆塔尔的部落牧师的成年礼，由剃刀岭的泰金委派。新手会被派往野外，寻找并治愈一名正在警戒库尔提拉斯幸存者的受伤步兵 Grunt...",kw={"杜隆塔尔","真言术韧","garments of spirituality","步兵 kor'ja","次级治疗术","proudmoore","剃刀岭","泰金"},ang={["class:Priest"]="这项成年礼是杜隆塔尔部落牧师早期的决定性测试，旨在验证他们的战地分流技能并授予他们第一套法袍。",["faction:Horde"]="步兵 Kor'ja 的幸存直接加强了剃刀岭对附近盘踞的库尔提拉斯人类侵略者的防御。",["race:Troll"]="泰金的教导将巨魔祖先的灵性融入了实际的战场职责中，确保年轻的暗矛巨魔能够运用他们的信仰来保护盟友。"},sec={{t="A Healer's Trial",b="在剃刀岭南部的干旱灌木丛中，部落面临着与 Grand Admiral Daelin Proudmoore 军队残余势力的不断交火。巨魔训练师泰金并没有让准牧师们进行抽象的仪式，而是在真实的战斗分流中考验他们的纪律。新手们被要求寻找步兵 Grunt Kor'ja，她在抵御人类渗透者时受了重伤，需在她伤重不治前为其治疗伤口并增强其体质。"},{t="Vestments of the Faithful",b="让 Kor'ja 恢复战斗状态证明了这位年轻牧师已经准备好承担起部落精神传统的重任。为了表彰其拯救了一名前线保卫者，泰金赐予了 Garments of Spirituality。对于兽人盟友和暗矛巨魔来说，这些长袍标志着穿戴者不仅仅是一名研究咒语的学徒，而是一条能够在战斗中确保部落战士存活的可靠生命线。"}},faq={{q="步兵 Kor'ja 是谁，她为什么需要治疗？",a="步兵 Kor'ja 是驻扎在剃刀岭南部的部落战士。她在与 Admiral Proudmoore 的库尔提拉斯远征军的幸存士兵的一次小规模冲突中受伤，这些士兵至今仍在骚扰杜隆塔尔的海岸线。",al={"步兵 korja","korja 是谁","南部的受伤步兵"}},{q="我在哪里可以找到泰金？",a="泰金位于杜隆塔尔的剃刀岭。她是离开试炼谷的部落年轻冒险者的精神导师和牧师训练师。",al={"泰金的位置","谁授予 garments of spirituality","剃刀岭牧师训练师"}},{q="治疗 Kor'ja 需要什么力量？",a="牧师必须使用 Lesser Heal 处理 Kor'ja 的伤势，并在返回泰金身边前使用 Power Word: Fortitude 的祝福增强她的耐力。",al={"需要使用什么法术","如何完成 garments of spirituality","治疗 korja 的法术"}},{q="为什么库尔提拉斯士兵还在杜隆塔尔作战？",a="在 Grand Admiral Proudmoore 入侵并战败后，他舰队的残余势力分散在杜隆塔尔的东海岸。他们不断发动绝望的袭击，并建立了像提拉加德城堡这样的据点。",al={"杜隆塔尔的 proudmoore 军队","为什么剃刀岭有人类","库尔提拉斯残余势力"}},{q="授予的长袍有什么意义？",a="泰金授予的长袍标志着新手完成了向部落现役治疗者的转变。通过这项实践测试，学生便有权穿上他们职业的法袍。",al={"garments 奖励背景","为什么要送长袍","剃刀岭牧师法袍"}},{q="Garments of Spirituality 的前置任务是什么？",a="这项试炼接在 In Favor of Spirituality 之后，这是一个引导任务，任务中试炼谷的肯杰会派遣年轻牧师前往剃刀岭寻找泰金。",al={"前置任务","garments of spirituality 之前","如何开始 garments 任务"}}},fp="24,279,16.344.0,25.332.0,50.193.0,25.96.0,40.128.0,53.192.0,49.186.0,45.124.0"}
P.entries["quest:5649"] = {n="部族的传统",s="“信仰之灵”是年轻的暗矛牧师在离开试炼谷时的一项基本成年仪式。肯杰指引他们前往剃刀岭向牧师训练师泰金报到，这标志着这些新人迈出了走出封闭的训练场、迎接杜隆塔尔更广阔挑战的第一步。这段旅程突显了暗矛巨魔在尊崇祖先传统与融入新建立的部落之间所寻求的微妙平衡。",h="“信仰之灵”是年轻的暗矛牧师在离开试炼谷时的一项基本成年仪式。肯杰指引他们前往剃刀岭向牧师训练师泰金报到，这标志着这些新人迈出了走出封闭的训练场、迎接杜隆塔尔更广阔挑战的第一步。这段旅程突显了暗矛巨魔在尊崇祖先传统与融入...",kw={"暗矛","杜隆塔尔","信仰之灵","肯杰","牧师","剃刀岭","泰金","试炼谷"},ang={["class:Priest"]="此任务标志着你完成了新手峡谷的训练，离开那里去剃刀岭接受泰金的正式教导与法衣授予。",["faction:Horde"]="它展示了杜隆塔尔内不同文化是如何相互协作的，将回音群岛的原始传统与剃刀岭的军事前哨连接在了一起。",["race:Troll"]="该任务说明了暗矛巨魔每天都要面对的紧张局势，即如何在忠于部落与保存古老的部落精神之间保持平衡。"},sec={{t="离开赤红峡谷",b="在试炼谷的封闭环境中跟随肯杰掌握了基本仪式后，暗矛侍僧们便准备好离开训练场了。通往杜隆塔尔的蜿蜒小径将他们直接引向剃刀岭的十字路口定居点。对于一名年轻的牧师来说，这次旅程代表了一个重要的里程碑：从尘土中基本的生存演练，转变为承担起部落的精神与文化重任。"},{t="古老的信仰与崭新的盟约",b="肯杰坦诚地谈到了暗矛部族在萨尔部落中的地位。虽然巨魔非常看重兽人的忠诚与荣誉教诲，但并非所有的祖先传统都能在盟友眼中顺利存续。暗矛的精神领袖告诫学生要静静地守护自己的文化遗产，在坚持自身认同的同时继续效忠部落。剃刀岭的泰金欢迎这些侍僧深入理解这一道理，引导他们走向自力更生与集体强大。"}},faq={{q="谁发放“信仰之灵”任务？",a="该任务由肯杰发放，他是位于试炼谷大兽穴内的巨魔牧师训练师。",al={"信仰之灵起始","信仰之灵任务发放者","肯杰牧师任务"}},{q="我可以在哪里找到泰金？",a="泰金位于剃刀岭的营房内，就在杜隆塔尔主路旁，镇中心以东的位置。",al={"泰金位置","泰金在哪里","找到泰金"}},{q="哪些职业可以接受这个任务？",a="该任务仅供在杜隆塔尔开启旅程的巨魔牧师接取。",al={"这是牧师专属任务吗","谁能接取信仰之灵","剃刀岭牧师职业任务"}},{q="为什么肯杰强调要对某些传统保密？",a="肯杰意识到，虽然兽人是重视荣誉的忠诚盟友，但他们并不认同每一个古老的巨魔仪式或习俗。他教导年轻的牧师要谨慎地尊崇祖先传统，以维持部落内部的和谐。",al={"为什么巨魔传统要保密","兽人与巨魔宗教摩擦","为什么要秘密修行"}},{q="泰金在年轻牧师到达时传授了什么？",a="泰金解释说，暗矛部族通过适应部落的生活变得更加强大。比起等待从倒下的敌人身上汲取力量，部族现在学会了未雨绸缪，在战斗开始前就已经做好了准备。",al={"泰金谈话","泰金说了什么","暗矛适应力"}},{q="“信仰之灵”之后紧接着是什么任务？",a="在交付此任务后，泰金会提供“灵性法衣”，该任务会指引侍僧去协助野外一名受伤的部落士兵。",al={"信仰之灵之后的内容","信仰之灵后续任务","泰金之后的下一个牧师任务"}}},fp="24,243,22.339.0,28.416.0,45.86.0,25.92.0,35.68.0,58.221.0,54.213.0,56.125.0"}
P.entries["quest:565"] = {n="巴图罗的雪人毛皮披风",s="“雪人毛皮披风”是南海镇的古怪工匠巴托洛·吉塞蒂提供的一项任务。巴托洛声称他能制作出一件在联盟中享有盛誉、品质无可匹敌的披风，这需要冒险者收集裁缝基本材料、一件制皮师制作的披风，以及原始的雪人的毛皮。",h="“雪人毛皮披风”是南海镇的古怪工匠巴托洛·吉塞蒂提供的一项任务。巴托洛声称他能制作出一件在联盟中享有盛誉、品质无可匹敌的披风，这需要冒险者收集裁缝基本材料、一件制皮师制作的披风，以及原始的雪人的毛皮。",kw={"巴托洛·吉塞蒂","粗布卷","细线","山地披风","希尔斯布莱德丘陵","南海镇","雪人的毛皮","雪人毛皮披风"},ang={["faction:Alliance"]="巴托洛吹嘘他的雪人毛皮披风在整个联盟中都享有盛誉，并在联盟的南海镇据点直接提供他的裁缝服务。",["profession:Tailoring"]="制作这件奢华服饰依赖于核心裁缝材料，具体来说是粗布卷和细线，并结合了异域野兽的毛皮。"},sec={{t="南海镇的大裁缝",b="在南海镇的海岸避风港，一位名叫巴托洛·吉塞蒂的工匠向过往旅人提供机会，让他们可以委托制作他自诩的杰作：举世闻名的雪人毛皮披风。巴托洛一直以其浮夸的自信而闻名，声称这世上不存在比它更好的衣物。虽然他那自夸的举止引人注目，但他的手艺确实结合了当地野外采集和相关专业的精炼工艺。"},{t="制作组件",b="制作这件奢华的披风并非简单地缝合一张毛皮。巴托洛需要冒险者收集一系列特定的物品：包括粗布卷和细线在内的裁缝基本材料、一件被称为山地披风的耐用皮革基底，以及十团从丘陵漫游的野兽身上采集到的厚实的雪人的毛皮。一旦收集完毕，巴托洛就会将这些原材料加工成他标志性的御寒披风。"}},faq={{q="巴托洛·吉塞蒂是谁？",a="巴托洛·吉塞蒂是一位古怪且自夸的工匠，居住在希尔斯布莱德丘陵的南海镇。他自豪地宣称自己是举世无双、名扬世界的雪人毛皮披风的创造者。",al={"谁是巴托洛","巴托洛·吉塞蒂","谁提供这个任务"}},{q="巴托洛需要什么材料来制作披风？",a="为了制作他那件名声在外的披风，巴托洛·吉塞蒂需要一个粗布卷、一件由制皮师制作的山地披风、一轴细线以及十团厚实的雪人的毛皮。",al={"披风所需材料","巴托洛需要什么物品","雪人毛皮披风材料"}},{q="巴托洛在哪里制作他的披风？",a="南海镇是一座位于希尔斯布莱德丘陵的沿海人类城镇，也是联盟在该地区的主要据点。巴托洛·吉塞蒂就在这个定居点工作，欢迎过往的冒险者。",al={"为什么是南海镇","南海镇在哪里","任务发生在哪里"}},{q="冒险者在希尔斯布莱德哪里可以获得雪人的毛皮？",a="雪人的毛皮团是从栖息在希尔斯布莱德和奥特兰克地区丘陵与山脉中的野生雪人身上采集到的，因其浓密且保暖的毛皮而备受珍视。",al={"哪里获取毛皮","哪些雪人","雪人的毛皮哪里掉落"}},{q="山地披风是如何获得的？",a="山地披风是巴托洛作品的基底衣物。它是由熟练的制皮师裁剪和缝合的，之后巴托洛再将其与细线、羊毛和毛皮层层结合。",al={"谁制作山地披风","山地披风制作","制皮披风"}},{q="为什么巴托洛声称他的披风举世闻名？",a="据巴托洛本人所言，这世上不存在比它更好的披风。他吹嘘这是联盟中享有盛誉的服饰，能为每一位穿着者提供无与伦比的温暖、奢华与威望。",al={"为什么披风有名","世界最好的披风","巴托洛的披风好吗"}}},fp="24,269,30.446.0,23.437.0,24.196.0,54.176.0,35.193.0,50.174.0,36.191.0,49.186.0"}
P.entries["quest:5650"] = {n="黑暗之衣",s="“黑暗之袍”是布瑞尔的被遗忘者牧师新手的入门试炼。黑暗牧师贝里尔会指派学徒去治疗并强化一名受伤的死亡卫士，以此测试他们对辅助魔法的掌握程度，然后再让他们深入接触暗影之道。",h="“黑暗之袍”是布瑞尔的被遗忘者牧师新手的入门试炼。黑暗牧师贝里尔会指派学徒去治疗并强化一名受伤的死亡卫士，以此测试他们对辅助魔法的掌握程度，然后再让他们深入接触暗影之道。",kw={"布瑞尔","黑暗牧师贝里尔","死亡卫士凯尔","坚韧","黑暗之袍","次级治疗术","牧师","暗影","提瑞斯法林地"},ang={["class:Priest"]="这项仪式概括了被遗忘者对牧师职业的哲学：平衡暗影的残酷功用与强化及治疗盟友不可替代的职责。",["race:Undead"]="对于被遗忘者来说，治疗魔法是一种实用的生存工具，用来维持像死亡卫士凯尔这样的前线士兵，以对抗豺狼人和天灾军团的残党。"},sec={{t="暗影与圣光的平衡",b="虽然被遗忘者牧师的声望与独特身份源于暗影与黑暗，但其长者也意识到恢复能力在务实方面的必要性。黑暗牧师贝里尔教导说，想要理解黑暗，就必须理解圣光与恢复系法术。如果一名牧师只追求毁灭，那么他最好去研究奥术魔法；牧师真正的使命不仅在于折磨敌人，更在于增强和保护盟友。"},{t="墓地的职责",b="为了展示其实力，学徒会被派往布瑞尔墓地的北边，去援助死亡卫士凯尔。凯尔在防守阵线对抗徘徊的豺狼人时身受重伤。通过施放治疗法术缝合伤口，并用保护结界强化其耐力，侍僧证明了自己有能力守护提瑞斯法林地的防卫者，从而赢得贝里尔赐予的长袍，并被接纳进入牧师更高深的奥秘之中。"}},faq={{q="既然被遗忘者牧师的力量来源于黑暗，他们为什么还要使用治疗魔法？",a="黑暗牧师贝里尔解释说，尽管被遗忘者牧师能从暗影中汲取强大的力量，但治疗依然不可或缺。在掌握黑暗之前，侍僧必须先理解辅助与恢复魔法，才能让被遗忘者的守卫在战场上站稳脚跟。",al={"亡灵为什么要治疗","被遗忘者牧师治疗背景","亡灵的暗影与圣光"}},{q="死亡卫士凯尔是谁？",a="死亡卫士凯尔是一名驻扎在布瑞尔墓地北部的被遗忘者哨兵。他负责保卫当地定居点，抵御在森林中游荡的凶猛豺狼人，并在履行职责时若受了伤，就需要援助。",al={"死亡卫士凯尔背景","死亡卫士凯尔是谁","受伤的死亡卫士"}},{q="谁发布了这个任务？",a="黑暗牧师贝里尔，位于提瑞斯法林地布瑞尔的牧师训练师。在你完成初步任务“黑暗的恩赐”后，她会提供该任务。",al={"谁发布黑暗之袍任务","黑暗之袍任务发布者"}},{q="完成试炼后会获得什么样的长袍？",a="贝里尔会授予一件量身定制的长袍作为身份与成就的象征，这标志着该牧师已经掌握了其基本职责，并获得了同伴的认可。",al={"获得什么长袍","黑暗之袍牧师奖励"}},{q="死亡卫士凯尔在与什么样的威胁战斗？",a="凯尔在与布瑞尔墓地以北、提瑞斯法林地周边荒野中出没的当地豺狼人战斗时负伤。",al={"凯尔遭到了什么袭击","凯尔 豺狼人"}},{q="黑暗牧师贝里尔暗示了哪些更黑暗的力量？",a="贝里尔暗示了被遗忘者牧师独有的暗影技巧——这是其他种族的牧师所不会使用的、独特的暗影魔法与精神折磨的表现形式。",al={"被遗忘者牧师独特法术","更黑暗的力量暗示"}}},fx={["933f71c0"]={q="黑暗牧师贝里尔为什么要你完成这件事？",a="黑暗牧师贝里尔想要检验你在被遗忘者牧师职业中的纪律与准备程度。被遗忘者牧师能从黑暗与暗影中汲取强大的力量，但贝里尔认为，若不先理解光明及其治愈之术，就无法真正掌握黑暗。她让你治愈并增强受伤的亡灵卫兵凯尔，以检验你对基本治疗术的实际掌握，然后才会引你深入牧师职业的黑暗教诲。",al={"贝里尔的用意","贝里尔为什么派你去","贝里尔为什么要治愈凯尔"}},a6afe368={q="黑暗牧师贝里尔为什么派你去，而不是亲自照料亡灵卫兵凯尔？",a="这项任务专为考验你这位入门者而设，是你的成人仪式。贝里尔早已掌握这些能力，但要评估你的成长，就得让你走出驻地，亲自运用所学。治愈并增强亡灵卫兵凯尔这样的现役守卫，能向贝里尔和同伴证明，你有能力在战斗中支援被遗忘者。",al={"为什么派我去治愈凯尔","贝里尔为什么不亲自去","贝里尔为什么需要我"}}},fp="20,264,27.460.0,23.433.0,77.263.0,22.212.0,21.158.0,52.170.0,41.134.0,50.174.0"}
P.entries["quest:5651"] = {n="黑暗的恩赐",s="“拥抱黑暗”标志着被遗忘者牧师从丧钟镇的起始墓穴迈向布瑞尔进行进阶训练的过程。在黑暗牧师杜斯滕的嘱托下，这位初出茅庐的信徒将前往黑暗牧师贝里尔门下学习，以掌握圣光与暗影之间微妙的平衡。",h="“拥抱黑暗”标志着被遗忘者牧师从丧钟镇的起始墓穴迈向布瑞尔进行进阶训练的过程。在黑暗牧师杜斯滕的嘱托下，这位初出茅庐的信徒将前往黑暗牧师贝里尔门下学习，以掌握圣光与暗影之间微妙的平衡。",kw={"贝里尔","布瑞尔","丧钟镇","杜斯滕","圣光","牧师","暗影","提瑞斯法"},ang={["class:Priest"]="这个任务概括了被遗忘者牧师哲学的根本：以冷酷的审慎而非宗教的崇敬来运用圣光与暗影。",["race:Undead"]="从丧钟镇到布瑞尔的旅程是深入了解更广阔的被遗忘者国度的首次例行游历，展示了他们的人民如何在洛丹伦废墟上进行重建。"},sec={{t="腐朽中开辟的道路",b="其他种族的牧师将圣光视为道德美德的无瑕源泉，而对被遗忘者而言，信仰则是透过他们自身亡灵身份这副严苛透镜所看到的景象。正如黑暗牧师杜斯滕所教导的那样，被遗忘者在腐化中重铸，并像腐肉一样被抛弃。他们的生存需要不带任何感伤地去理解圣光与暗影。任务“拥抱黑暗”指引新晋信徒走出丧钟镇与世隔绝的墓地，去直面提瑞斯法林地等待着他们的更广阔的现实。"},{t="布瑞尔的教导",b="从丧钟镇向东北方向出发，路经一座木质廊桥，便能抵达破败的布瑞尔小镇。在那里，在当地旅店的上层，黑暗牧师贝里尔正等待着考验这位初学者的决心。贝里尔看重野心和冷酷的实用主义，而非盲目的虔诚，他要求被遗忘者牧师将神圣力量视为武器和工具，而不是道德的拐杖。"}},faq={{q="这个任务的目的是什么？",a="这是被遗忘者牧师离开丧钟镇的成人礼。黑暗牧师杜斯滕会派你去布瑞尔找黑暗牧师贝里尔，以继续你的训练并接受下一项牧师挑战。",al={"这个任务做什么","为什么叫拥抱黑暗","拥抱黑暗的目的"}},{q="如果被遗忘者牧师拥抱黑暗，为什么还要使用圣光？",a="被遗忘者教士承认世界是在圣光与暗影的平衡中运作的。尽管圣光会给亡灵的躯体带来剧痛，且他们的起源在于腐朽与黑暗，但为了生存与必要的实用性，他们必须研究这两种力量。",al={"亡灵牧师为什么使用圣光","被遗忘者牧师背景","亡灵的圣光与暗影"}},{q="我在哪里可以找到黑暗牧师贝里尔？",a="黑暗牧师贝里尔位于丧钟镇东北方向的布瑞尔镇。他就在定居点东侧恐惧之末旅店的二楼。",al={"黑暗牧师贝里尔在哪","贝里尔位置","寻找贝里尔"}},{q="这个任务接下来会接到什么任务？",a="与黑暗牧师贝里尔交谈即可完成此任务，并开启后续任务“黑暗之衣”，在那项任务中，他将考验你利用新学到的知识来治疗并维持盟友的能力。",al={"what comes next","拥抱黑暗后的任务","拥抱黑暗后续"}},{q="黑暗牧师杜斯滕是谁？",a="黑暗牧师杜斯滕是驻扎在丧钟镇的牧师训练师。他引导刚苏醒的被遗忘者牧师理解他们痛苦的存在，并运用他们的精神力量。",al={"谁给予这个任务","杜斯滕背景","黑暗牧师杜斯滕"}},{q="为什么贝里尔提倡野心而不是信仰？",a="在被生前崇拜的力量抛弃后，被遗忘者牧师认为传统的虔诚信仰已不足够。黑暗牧师贝里尔希望学徒们依靠个人野心、紧迫感和实际的力量来生存。",al={"贝里尔对话含义","为什么是野心而非信仰","被遗忘者信仰"}}},fx={["066c2d01"]={q="黑暗牧师杜斯滕为什么派你去布瑞尔？",a="杜斯滕已经教会你被遗忘者牧师职业的基本真理：你或许能审慎地运用圣光与黑暗，但你的存在是在腐朽与黑暗中铸就的。如今你已在丧钟镇领悟这些基础，他便派你前往布瑞尔拜访黑暗牧师贝里尔，继续为被遗忘者效力并精进训练。",al={"杜斯滕为什么派我离开","黑暗的恩赐中杜斯滕的用意","为什么去找黑暗牧师贝里尔"}}},fp="20,304,20.495.0,20.409.0,34.199.0,63.260.0,34.172.0,31.192.0,27.187.0,43.232.0"}
P.entries["quest:5654"] = {n="虚弱妖术",s="“虚弱妖术”是给予在剃刀岭证明了自己初步价值的年轻暗矛巨魔牧师的一项早期成人礼任务。泰金将新兵派往北方的奥格瑞玛，去寻找乌尔库，从而更深入地融入部落的灵性圈子，并学习洛阿神灵更黑暗的法术。",h="“虚弱妖术”是给予在剃刀岭证明了自己初步价值的年轻暗矛巨魔牧师的一项早期成人礼任务。泰金将新兵派往北方的奥格瑞玛，去寻找乌尔库，从而更深入地融入部落的灵性圈子，并学习洛阿神灵更黑暗的法术。",kw={"暗矛","杜隆塔尔","虚弱妖术","洛阿","奥格瑞玛","森金村","泰金","乌尔库","valley of spirits"},ang={["class:Priest"]="与圣光或被遗忘的暗影教条不同，巨魔牧师教义汲取了与原始灵魂的深层交流，将部落妖术与传统的暗影和恢复法术交织在一起。",["faction:Horde"]="从剃刀岭到精神谷的旅程反映了巨魔文化融入萨尔不断发展的堡垒首都的过程。",["race:Troll"]="这项仪式标志着你从剃刀岭的一名新手转变为暗矛巨魔部落公认的牧师，学习世代相传的古老诅咒。"},sec={{t="圈子的召唤",b="对于杜隆塔尔的一位初出茅庐的巨魔牧师来说，课程在剃刀岭的兵营里，在泰金的注视下继续进行。一旦侍僧对精神交流和暗影魔法的基本平衡表现出足够的掌握，基础教导就结束了。泰金会将这些有前途的牧师从剃刀岭引开，向北穿过红土峡谷前往部落主城，在那里，更年长的修行者会指导部落更广泛的魔法传统。"},{t="精神谷中的古老之道",b="在奥格瑞玛内，暗矛巨魔在精神谷中保持着他们自己独特的文化圣所，这里与兽人叮当作响的锻造厂和战士营地隔离开来。在这里，耸立的图腾和阴凉的小屋之中，年长的牧师乌尔库等待着新兵。进入他的圈子意味着拥抱丛林巨魔的祖先传统——在崇敬祖先洛阿神灵的同时，掌握那些能在战斗中削弱敌人力量的强大诅咒和妖术。"}},faq={{q="这个任务的目的是什么？",a="该任务代表了新兵在暗矛巨魔牧师阶层中的正式晋升。泰金将正在成长的巨魔牧师从杜隆塔尔的海岸派往奥格瑞玛的乌尔库那里，正式将他们引入部落的灵性修行者核心圈子。",al={"为什么要做这个任务","虚弱妖术的目的","虚弱妖术任务是做什么的"}},{q="泰金是谁？",a="泰金是驻扎在杜隆塔尔剃刀岭兵营的一位巨魔牧师训练师。她在这些最年轻的暗矛巨魔施法者前往主城之前，引导他们完成早期的试炼。",al={"谁是任务发布者","泰金的背景故事","泰金"}},{q="乌尔库是谁？",a="乌尔库是一位居住在奥格瑞玛精神谷的年长巨魔牧师训练师。他负责监督高级灵性训练，将部落的妖术和深奥的祖先仪式传授给暗矛巨魔牧师。",al={"乌尔库是谁","乌尔库牧师训练师","乌尔库"}},{q="精神谷在哪里？",a="精神谷是奥格瑞玛西部一个隐蔽的沼泽区域。它是暗矛巨魔在兽人堡垒城市内的主要家园，容纳了他们的训练师、住所和图腾。",al={"精神谷位置","乌尔库在哪里","去哪里寻找乌尔库"}},{q="这种训练侧重于哪种魔法？",a="暗矛巨魔牧师援引“古老之道”，从洛阿神灵和古老的丛林巨魔传统中汲取力量。巨魔牧师并不完全依赖人类或矮人所推崇的圣光，而是将恢复性的灵魂魔法与诸如“虚弱妖术”之类的削弱诅咒结合起来。",al={"巨魔牧师魔法","什么是古老之道","妖术背景故事"}},{q="非巨魔玩家可以进行这个任务吗？",a="不可以。该任务专门与暗矛巨魔的文化传统和独特法术相关。亡灵牧师则会前往提瑞斯法林地和幽暗城，寻求他们自己的导师和暗影哲学。",al={"亡灵可以做这个吗","这是巨魔专属的吗"}}},fp="15,228,23.362.0,37.374.0,34.234.0,15.185.0,14.184.0,31.188.0,47.231.0,36.185.0"}
P.entries["quest:566"] = {n="通缉：瓦杜斯男爵",s="一张带有高级执行官达萨利亚命令的告示通缉Baron Vardus。他是辛迪加的一名人类高层成员，因对被遗忘者犯下的罪行而遭通缉，必须处死。其死亡证明必须送交塔伦米尔的达萨利亚。",h="一张带有高级执行官达萨利亚命令的告示通缉Baron Vardus。他是辛迪加的一名人类高层成员，因对被遗忘者犯下的罪行而遭通缉，必须处死。其死亡证明必须送交塔伦米尔的达萨利亚。",kw={"奥特兰克山脉","baron vardus","达萨利亚","高级执行官达萨利亚","希尔斯布莱德丘陵","斯坦恩布莱德","辛迪加","塔伦米尔","高地","vardus"},sec={{t="男爵的悬赏",b="达萨利亚对Baron Vardus发出了悬赏。此人是辛迪加的一名人类高层成员，因对被遗忘者犯下的罪行而受到指控。据最后的消息，他位于塔伦米尔北部的奥特兰克山脉的高地。命令很明确：他必须死，谁能带给达萨利亚他死亡的证明，谁就能得到赏金。"},{t="他可能所在之处",b="Vardus可能藏身于高地各处的辛迪加营地中。他也可能躲在斯坦恩布莱德旅店的地窖里。"},{t="达萨利亚的判决",b="随着男爵的死亡，达萨利亚宣布辛迪加的领袖少了一个，并预计他们的愤怒和抵抗将不会长久。"}},faq={{q="Baron Vardus是谁？",a="他是辛迪加的一名人类高层成员，因对被遗忘者犯下的罪行而受到通缉。",al={"baron vardus","谁是vardus","谁是男爵"}},{q="在哪里可以找到Baron Vardus？",a="他最后一次被人看见是在塔伦米尔以北，属于奥特兰克山脉的高地。他可能在那里的某个辛迪加营地，或者躲在斯坦恩布莱德旅店的地窖里。",al={"baron vardus位置","vardus在哪里","找到baron vardus"}},{q="是谁提供了Baron Vardus的赏金？",a="塔伦米尔的高级执行官达萨利亚，死亡证明必须交予此人。",al={"谁发布了悬赏","谁要vardus死","达萨利亚悬赏"}}},fp="20,231,20.341.0,17.131.0,19.132.1,20.91.0,32.188.0,38.89.0"}
P.entries["quest:567"] = {n="危险！",s="这张悬赏令张贴在塔伦米尔的公告板上，旨在通缉四名希尔斯布莱德的知名人类，并处决他们。高级执行官达萨利亚因这几人实施的暗杀和物资伏击行动，宣布他们为被遗忘者的危险敌人。",h="这张悬赏令张贴在塔伦米尔的公告板上，旨在通缉四名希尔斯布莱德的知名人类，并处决他们。高级执行官达萨利亚因这几人实施的暗杀和物资伏击行动，宣布他们为被遗忘者的危险敌人。",kw={"药剂师伊莱","平民威尔克斯","书记官霍拉斯·怀特斯蒂德","危险","死亡卫士托玛","死亡猎手弗莱","农夫卡拉巴","高级执行官达萨利亚","希尔斯布莱德","矿工哈克特","塔伦米尔","幽暗城"},ang={["class:Rogue"]="在敌对领土追踪潜伏的头目，这反映了死亡猎手弗莱的隐秘工作，而这份契约正是为了给他的死亡复仇。",["faction:Horde"]="确保希尔斯布莱德丘陵的安全需要击破人类民兵中最凶狠的人物，以保障部落在该地区的行动安全。",["race:Undead"]="为牺牲的死亡卫士、药剂师和死亡猎手复仇，是任何效忠于黑暗女王的忠诚仆从心中阴沉的骄傲。"},sec={{t="复仇之事",b="整个希尔斯布莱德丘陵的战线残酷而又充满私人恩怨。对高级执行官达萨利亚和塔伦米尔的被遗忘者守军来说，普通的希尔斯布莱德平民已经变成了致命的战斗人员。这张通缉令特别点名了四名人物，他们的抵抗行为导致了被遗忘者士兵的牺牲，以及从幽暗城运送的重要补给物资的损失。"},{t="塔伦米尔的目标",b="这份悬赏令点名了杀害了死亡卫士托玛的书记官霍拉斯·怀特斯蒂德，谋杀了药剂师伊莱的平民威尔克斯，杀死死亡猎手弗莱的矿工哈克特，以及破坏从幽暗城运送的补给车队的农夫卡拉巴。每个目标都在希尔斯布莱德抵抗力量的不同据点活动，在更广泛的冲突混乱中保持行踪不定。"}},faq={{q="是谁张贴了“危险！”悬赏令？",a="驻扎在塔伦米尔的被遗忘者军队指挥官，高级执行官达萨利亚，针对四名希尔斯布莱德知名人类发布了这份悬赏令。",al={"谁张贴了危险悬赏","谁发布了危险任务","达萨利亚悬赏"}},{q="为什么这些特定的人类会被通缉？",a="他们每个人都曾打击过被遗忘者：书记官霍拉斯·怀特斯蒂德杀死了死亡卫士托玛，平民威尔克斯谋杀了药剂师伊莱，矿工哈克特杀害了死亡猎手弗莱，农夫卡拉巴伏击了从幽暗城运送的重要补给物资。",al={"为什么他们很危险","他们做了什么","希尔斯布莱德目标的罪行"}},{q="这些目标位于何处？",a="这四个目标全部盘踞在希尔斯布莱德丘陵的人类定居点和工作场所中，藏匿在镇民、农场和矿坑之间。",al={"哪里可以找到目标","危险任务地点","哈克特的位置"}},{q="这份契约的战略目的是什么？",a="除了纯粹的复仇之外，铲除这些头目还能削弱当地人类的抵抗力量，保护往返于塔伦米尔和幽暗城之间的被遗忘者巡逻队和补给线。",al={"为什么要杀死他们","希尔斯布莱德悬赏目标","塔伦米尔战略"}},{q="这与希尔斯布莱德之战有关吗？",a="是的。悬赏令的目标正居住在被遗忘者军队在希尔斯布莱德之战的更大规模攻势中所要袭击的农场、矿坑和城镇中心里。",al={"与希尔斯布莱德之战的联系","达萨利亚的战斗","希尔斯布莱德攻势"}},{q="谁会在目标被杀后提交悬赏？",a="清除这些目标的证明将直接上交给塔伦米尔的高级执行官达萨利亚。",al={"谁来完成危险任务","危险任务交付","交付给达萨利亚"}}},fx={ed73acb1={q="高级执行官达萨利亚为什么要除掉这四个人类？",a="高级执行官达萨利亚悬赏缉拿这四人，是因为他们直接重创了塔伦米尔的关键行动。文书官惠特斯蒂德、市民威尔克斯和矿工哈克特分别刺杀了重要的被遗忘者人员：一名亡灵卫兵、一名药剂师和一名亡灵哨兵斥候。农夫卡拉巴则拦截了从幽暗城运来的重要补给车队。除掉他们既能为阵亡同伴报仇、确保补给线安全，也能清除希尔斯布莱德前线的危险游击威胁。",al={"为什么杀掉他们","达萨利亚的用意","为什么悬赏杀掉他们"}},["4592bc02"]={q="“危险！”悬赏令上标记的目标是谁？",a="你的目标是四名拿起武器反抗被遗忘者、颇有影响力的希尔斯布莱德居民：文书官Horrace Whitesteed、市民Wilkes、矿工Hackett和农夫Kalaba。表面上，他们只是普通的镇民、矿工和劳工，但每个人都极其危险且足智多谋，藏身于山麓和田野各处，对塔伦米尔发动非正规战。",al={"目标是谁","危险悬赏令的目标","要杀谁"}},["7da50b6a"]={q="高级执行官达萨利亚为什么依靠冒险者，而不派自己的亡灵卫兵？",a="塔伦米尔的军队已捉襟见肘，既要守住防线，又要在希尔斯布莱德各处展开激战。此外，目标并未公开行军，而是藏匿在民用农场、矿井和乡间小路上。达萨利亚依靠四处活动的赏金猎人和能干的冒险者，他们可以独立行动、追踪难以捉摸的目标，并在敌后将其搜捕出来，而无需调走整支驻军。",al={"为什么不派卫兵","危险任务为什么选我","为什么派冒险者"}}},fp="10,235,23.338.0,22.381.0,33.142.0,37.241.0,30.144.0,47.175.0,45.160.0,44.91.0"}
P.entries["quest:5672"] = {n="艾露恩的赐福",s="艾露恩的恩赐是一项为达纳苏斯虔诚的暗夜精灵牧师提供的认可仪式。在通过早期的旅程证明了他们的信仰与自律后，牧师们会被召唤到女祭司阿兰希雅面前，接受关于月亮女神神圣奥秘的更深层次教导。",h="艾露恩的恩赐是一项为达纳苏斯虔诚的暗夜精灵牧师提供的认可仪式。在通过早期的旅程证明了他们的信仰与自律后，牧师们会被召唤到女祭司阿兰希雅面前，接受关于月亮女神神圣奥秘的更深层次教导。",kw={"阿兰希雅","达纳苏斯","艾露恩","艾露恩的恩赐","牧师任务","女祭司阿兰希雅","艾露恩姐妹会","temple of the moon"},ang={["class:Priest"]="这一仪式标志着kaldorei信仰与人类和矮人神职人员基于圣光的教义之间的分歧，使牧师的技艺牢牢扎根于艾露恩的庇护之中。",["race:NightElf"]="对于kaldorei来说，艾露恩的恩赐代表了与The Sisterhood of Elune内保存的古老传统之间不间断的连续性。"},sec={{t="神圣的召唤",b="在达纳苏斯的Temple of the Moon内，The Sisterhood of Elune引导年轻的侍僧完成从最初的祈祷到精通月亮魔法的修行。暗夜精灵对圣光的看法与人类或矮人不同；他们的信仰与月亮女神艾露恩有着不可分割的联系。当一位见习牧师在虔诚之路上达成重要的里程碑时，资深导师就会注意到他们，并认可这位门徒已准备好肩负更强大的神圣力量。"},{t="月亮女神的祝福",b="女祭司阿兰希雅代表The Sisterhood of Elune发出此项召唤。她认可这位侍僧的奉献精神已使他们超越了普通的信徒，并授予他们接触千百年来所传承传统的权利。接受这一仪式将巩固牧师与艾露恩的羁绊，解锁kaldorei信仰独有的特定防护结界和月亮祈祷。"}},faq={{q="这个任务的目的是什么？",a="这项任务代表了暗夜精灵牧师的一个精神基准点。它将侍僧召唤回达纳苏斯，以便女祭司阿兰希雅能认可他们的成长，并引导他们学习由The Sisterhood of Elune授予的更高阶种族教义。",al={"为什么进行艾露恩的恩赐","艾露恩的恩赐有什么作用","任务目的"}},{q="女祭司阿兰希雅是谁？",a="女祭司阿兰希雅是The Sisterhood of Elune在达纳苏斯的一位受人尊敬的训练师。她看护着成长中的kaldorei牧师，帮助他们加深与月亮女神的交流。",al={"阿兰希雅的角色","谁发布任务","阿兰希雅是谁"}},{q="为什么这份礼物只针对暗夜精灵？",a="与那些汲取圣光力量的人类或矮人牧师不同，暗夜精灵牧师直接崇拜艾露恩。姊妹会的祈祷——例如艾露恩的恩赐——反映了kaldorei数千年来所培养的月亮保护和防御性附魔。",al={"为什么只有暗夜精灵","种族技能背景","艾露恩牧师的区别"}},{q="仪式在什么地方举行？",a="召唤将在达纳苏斯得到回应，中心位于城市牧师集会和传教的Temple of the Moon。",al={"阿兰希雅在哪里","任务地点","达纳苏斯月神殿"}},{q="其他联盟牧师会收到类似的召唤吗？",a="是的。每种文化对待牧师职业的方式各不相同：人类和矮人在暴风城和铁炉堡由各自的导师教授圣光的信条，从而获得不同于暗夜精灵所修习的月亮魔法的种族纪律。",al={"人类是否会接到此任务","矮人牧师的对应任务","其他种族"}},{q="阿兰希雅所指的虔诚状态是什么？",a="阿兰希雅指的是通过在广阔世界中的试炼所获得的坚韧精神和成熟度。生存能力、自律以及对艾露恩美德的坚定恪守，证明了一位侍僧能够更安全地引导强大的月亮祝福。",al={"达到某种状态","阿兰希雅对话","什么是虔诚"}}},fp="13,162,16.391.0,29.304.0,34.209.0,25.174.0,41.259.0,36.113.0,52.239.0,47.223.0"}
P.entries["quest:5674"] = {n="艾露恩的赐福",s="埃露恩的优雅是暗夜精灵牧师的一种晋升仪式，标志着他们已准备好运用其种族特有的神圣天赋。在多兰纳尔等当地哨所的指引下，候选者回到达纳苏斯的Temple of the Moon，在女祭司阿兰希雅面前展示他们的虔诚。",h="埃露恩的优雅是暗夜精灵牧师的一种晋升仪式，标志着他们已准备好运用其种族特有的神圣天赋。在多兰纳尔等当地哨所的指引下，候选者回到达纳苏斯的Temple of the Moon，在女祭司阿兰希雅面前展示他们的虔诚。",kw={"达纳苏斯","多兰纳尔","埃露恩的优雅","劳尔娜·晨光","女祭司阿兰希雅","the sisterhood of elune","泰达希尔","temple of the moon"},ang={["class:Priest"]="这一仪式标志着暗夜精灵牧师的一个决定性转变，将他们的身份根植于The Sisterhood of Elune独特的星界魔法中，而不是通用的圣光修行。",["race:NightElf"]="前往Temple of the Moon的朝圣之旅加强了埃露恩的崇拜在卡多雷社会中的核心作用，将远方的侍僧召回到达纳苏斯的中心。"},sec={{t="一个神圣的里程碑",b="在The Sisterhood of Elune中，牧师的旅程不仅仅是掌握标准的恢复和惩击祷言。随着侍僧经验的增长，他们达到了一个阈值，被认为可以接受卡多雷独有的祝福。像多兰纳尔的劳尔娜·晨光这样的当地导师没有权力传授这些深奥的技艺，因此将有前途的弟子指引回他们教派的文化和精神中心。"},{t="神殿觐见",b="该任务引导新兵穿过泰达希尔，前往达纳苏斯的宏伟的Temple of the Moon。在那里，在高阶祭司的注视下，女祭司阿兰希雅会评估申请者是否真正准备好承担女神的防御斗篷。学习埃露恩的优雅象征着在圣职中达到了真正的成熟，架起了原始潜力和对女神正式服务之间的桥梁。"}},faq={{q="这个任务的目的是什么？",a="这个任务将获得足够实践经验的暗夜精灵牧师送回达纳苏斯。它作为一种通过仪式，引导他们前往Temple of the Moon的女祭司阿兰希雅处，接受测试并学习被称为埃露恩的优雅的防御艺术。",al={"此任务的作用","埃露恩的优雅任务目的","为什么拜访阿兰希雅"}},{q="女祭司阿兰希雅是谁？",a="女祭司阿兰希雅是一位高级牧师训练师，驻扎在达纳苏斯的Temple of the Moon内。她负责监督暗夜精灵侍僧的正式训练和晋升，确保他们拥有掌握进阶种族祷言所需的精神专注。",al={"女祭司阿兰希雅背景故事","阿兰希雅是谁","阿兰希雅 达纳苏斯"}},{q="为什么当地导师不能传授这项能力？",a="像劳尔娜·晨光这样的前哨基地训练师指导新手完成基础教义，但The Sisterhood of Elune保留了神圣的、卡多雷特有的祝福，以供正式授予。侍僧必须亲自前往达纳苏斯该教派的中心，在学习这些深层天赋之前接受评估。",al={"为什么不在多兰纳尔训练","为什么去达纳苏斯"}},{q="埃露恩的优雅在卡多雷信仰中实际上代表什么？",a="埃露恩的优雅代表了月亮女神的直接保护和监护。通过祷告编织而成，它能减弱即将到来的攻击的影响，反映了当危险临近时，埃露恩对她忠实拥护者的庇护。",al={"什么是埃露恩的优雅","埃露恩的优雅背景故事"}},{q="其他种族的牧师能获得这种祝福吗？",a="不能。埃露恩的优雅这一艺术严格地与卡多雷的祖先信仰和崇拜相联系。只有直接与月亮女神交流的暗夜精灵牧师才能被传授其祈祷方法。",al={"人类可以学习埃露恩的优雅吗","埃露恩的优雅是暗夜精灵专属吗"}},{q="这段旅程始于何处，终于何处？",a="召唤由位于泰达希尔多兰纳尔定居点的导师劳尔娜·晨光传达，将侍僧向西送往坐落在达纳苏斯的Temple of the Moon。",al={"任务起点和终点","前往何处"}}},fp="13,150,18.377.0,22.281.0,34.207.0,25.237.0,43.299.0,61.212.0,49.170.0,38.107.0"}
P.entries["quest:5676"] = {n="奥术回馈者*",s="“奥术反馈”是暴风城联盟牧师的成人礼，由圣光大教堂的高阶牧师劳瑞娜授予。在与信仰达到更深层次的共鸣后，牧师将学习如何构建结界，以对抗敌对的奥术使用者。这代表了教会针对原始魔法和流氓施法者的实际防御手段。",h="“奥术反馈”是暴风城联盟牧师的成人礼，由圣光大教堂的高阶牧师劳瑞娜授予。在与信仰达到更深层次的共鸣后，牧师将学习如何构建结界，以对抗敌对的奥术使用者。这代表了教会针对原始魔法和流氓施法者的实际防御手段。",kw={"反魔法","奥术反馈","cathedral of light","高阶牧师劳瑞娜","圣光","人类牧师","劳瑞娜","牧师","暴风城"},ang={["class:Priest"]="这项仪式深化了牧师的战术储备，提供了在神圣外交失败时压制敌方法力使用者的手段。",["faction:Alliance"]="随着东部王国各地叛逆阴谋集团和黑暗修行者带来的紧张局势加剧，联盟依赖其牧师来消除魔法威胁。",["race:Human"]="暴风城的人类牧师遵循圣光大教堂特定的教义训练，将正直的虔诚与对抗魔法的严格纪律相结合。"},sec={{t="抵御奥术的护盾",b="在圣光大教堂阳光明媚的回廊中，高阶牧师劳瑞娜提醒着侍僧们一种经久不衰的危险：奥术魔法。虽然圣光带来治愈、温暖和神圣的秩序，但原始的魔法能量却反复无常，且往往招致腐化或灾难。为了在术士、叛逆法师和魔法野兽面前生存，虔诚的牧师被教导，有时必须将纯粹的信仰转化为一种针对环境魔法的主动防御手段。"},{t="反制洪流",b="“奥术反馈”旨在训练心灵和精神，惩罚那些对信徒施法的敌对施法者。这种训练并非仅仅是偏转魔法箭矢，而是将奥术能量反射回施法者自身，在造成痛苦的同时耗尽施法者自身的法力储备。劳瑞娜将这个法术传授给即将踏入广阔世界的牧师们，确保大教堂的使者在面对魔法时不会毫无防备。"}},faq={{q="“奥术反馈”任务的目的是什么？",a="这项任务代表了人类牧师在圣光教会指导下不断提升的修行。高阶牧师劳瑞娜会传授给修行者一种特定的防护仪式，旨在反制并回击敌对的施法者。",al={"奥术反馈任务","什么是奥术反馈","为什么要完成这个任务"}},{q="谁提供这个任务？她位于哪里？",a="由高阶牧师劳瑞娜提供。她驻扎在圣光大教堂，这是位于暴风城大教堂广场的联盟宏伟的精神中心。",al={"谁提供奥术反馈","奥术反馈任务发布者","劳瑞娜在哪里"}},{q="圣光教会为何将奥术魔法视为敌人？",a="教会教导人们要依靠道德清晰、虔诚和神圣的恩典。相比之下，奥术魔法依靠的是反复无常且令人上瘾的力量，历史上曾招致恶魔入侵并给艾泽拉斯带来浩劫，这使得人类牧师将不受控制的魔法视为一种时刻存在的威胁。",al={"为什么牧师讨厌奥术","教会与奥术","奥术是邪恶的吗"}},{q="“奥术反馈”结界在概念上是如何运作的？",a="该法术在牧师周围创造了一个反击光环。每当敌对法术击中结界时，传入的魔法会引发反噬，从而耗尽攻击者的法力储备并对其造成物理冲击。",al={"奥术反馈如何运作","奥术反馈背景故事"}},{q="任何牧师都能从劳瑞娜那里学到这个技能吗？",a="在暴风城，这门特殊的法术是专门为人类牧师量身定制的，属于他们国家教会传统的一部分，反映了圣光大教堂内传授的特定战斗教条。",al={"矮人能学奥术反馈吗","谁能获得奥术反馈","牧师种族法术"}},{q="接受此训练的侍僧需要达到什么等级？",a="牧师通常在二十岁左右被召唤学习这项技术，这个年纪的侍僧通常已经离开基础教会职责，准备前往危险的边境地区闯荡。",al={"奥术反馈需要什么等级","奥术反馈等级要求"}}},fp="15,202,27.381.0,23.319.0,49.173.0,49.108.0,68.229.0,52.155.0,39.110.0,63.137.0"}
P.entries["quest:5677"] = {n="奥术回馈者",s="“奥术反馈”是一项牧师任务，由铁炉堡的高阶牧师洛汉发布给前往卡兹莫丹的德莱尼以外的种族（人类）侍僧。洛汉指引这位初出茅庐的牧师回到暴风城的Cathedral of Light，去学习专门针对人类传统的教义。这标志着年轻门徒开始掌握自身种族信仰表现形式的关键进阶时刻。",h="“奥术反馈”是一项牧师任务，由铁炉堡的高阶牧师洛汉发布给前往卡兹莫丹的德莱尼以外的种族（人类）侍僧。洛汉指引这位初出茅庐的牧师回到暴风城的Cathedral of...",kw={"奥术反馈","cathedral of light","高阶牧师洛汉","高阶牧师劳瑞娜","铁炉堡","mystic ward","牧师任务","暴风城"},ang={["class:Priest"]="这项任务代表了一个关键的里程碑，牧师们在此发现不同种族通过独特的文化传统来引导和表达圣光。",["race:Dwarf"]="像高阶牧师洛汉这样的矮人导师尊重他们与人类的联盟，同时也保持卡兹莫丹的特定仪式仅在自己族人中流传。",["race:Human"]="人类牧师被温和地从矮人圣所召回暴风城，以便在Cathedral of Light的神圣方式中夯实基础。"},sec={{t="温和的指引",b="当一名人类牧师在Mystic Ward的大厅寻求高级精神教导时，高阶牧师洛汉会以恭敬的态度迎接他们，但也会划定界限。虽然矮人和人类牧师同样虔诚于圣光，但每个文明都有其独特的仪式、纪律和防御祈祷。洛汉并没有传授铁炉堡的独特秘诀，而是让这位人类牧师回到他们在艾尔文森林的文化根源，确保他们掌握本民族独特的遗产。"},{t="回到大教堂",b="回到暴风城后，侍僧需向大教堂内的高阶牧师劳瑞娜汇报。劳瑞娜很高兴看到洛汉的指引对这位旅行者起到了作用，并在他们初生的力量开始萌芽时表示欢迎。这次回归为更深入地了解暴风王国的精神修行铺平了道路，使修行者准备好运用圣光来对抗环绕王国的日益严重的威胁。"}},faq={{q="为什么高阶牧师洛汉拒绝教导人类牧师？",a="高阶牧师洛汉尊重人类修行者，但矮人神职人员拥有通过自身文化血脉传承下来的独特仪式和祝福。他认为人类牧师必须学习由暴风城的导师们所保留的特定的专业技术。",al={"为什么要派往暴风城","为什么洛汉不进行教导","矮人牧师不教我"}},{q="谁是高阶牧师劳瑞娜？",a="高阶牧师劳瑞娜是一位著名的精神领袖和训练师，驻守在暴风城的Cathedral of Light内。她负责监督有前途的人类牧师的成长，指导他们的进阶学习和仪式。",al={"高阶牧师劳瑞娜","劳瑞娜是谁","大教堂牧师训练师"}},{q="在哪里可以找到高阶牧师洛汉？",a="高阶牧师洛汉居住在铁炉堡这座伟大的矮人山城中，位于Mystic Ward内的Hall of Mysteries。",al={"洛汉的位置","高阶牧师洛汉在哪里","寻找洛汉"}},{q="这项任务的目的是什么？",a="它是一项引导性的任务，将中级人类牧师从矮人领地引导回他们主要的种族训练中心——Cathedral of Light，使他们能够追求特定种族的精神技术。",al={"奥术反馈任务目的","为什么要做这个任务","这个任务有什么作用"}}},fp="15,380,20.477.0,23.446.0,57.267.0,30.223.0,37.131.0,34.219.0"}
P.entries["quest:5678"] = {n="Arcane Feedback",s="“奥术反馈”是一项联盟牧师任务，指引在达纳苏斯受训的人类牧师返回故乡暴风城。这项任务由月神殿的女祭司阿兰希雅发布，凸显了暗夜精灵与东部王国在魔法观念上的深刻文化隔阂。当回到暴风城的圣光大教堂后，高阶牧师劳瑞娜将为这位侍僧准备更深奥的神学指导。",h="“奥术反馈”是一项联盟牧师任务，指引在达纳苏斯受训的人类牧师返回故乡暴风城。这项任务由月神殿的女祭司阿兰希雅发布，凸显了暗夜精灵与东部王国在魔法观念上的深刻文化隔阂。当回到暴风城的圣光大教堂后，高阶牧师劳瑞娜将为这位侍僧...",kw={"奥术反馈","cathedral of light","达纳苏斯","高阶牧师劳瑞娜","圣光","牧师任务","女祭司阿兰希雅","暴风城"},ang={["class:Priest"]="这趟朝圣之旅标志着你灵性道路上的一个关键门槛，提醒着你艾露恩姐妹会与圣光教义之间存在着尖锐的哲学分歧。",["race:Human"]="回到暴风城意味着你回到了圣光教会的核心，将那封闭且多疑的卡多雷祭司阶层抛在了身后。",["race:NightElf"]="女祭司阿兰希雅直言不讳的警惕，生动展现了卡多雷内心深处那种挥之不去的恐惧：年轻的凡人种族若是滥用奥术，可能会导致灾难重演。"},sec={{t="不情愿的召唤",b="女祭司阿兰希雅在达纳苏斯月神殿宁静的大厅中照看着来访的牧师们。虽然她认可卡多雷与暴风城人类之间正式的盟友关系，但她对人类的魔法和灵性实践怀有深深的疑虑。暗夜精灵社会将奥术力量视为天生反复无常且危险的事物，这种认知源于上古之战后那一万年的悲痛。即便是人类那些模糊了圣洁信仰与奥术机制界限的神圣仪式，也会让暗夜精灵教士感到明显的不安。"},{t="返回大教堂",b="尽管心存顾虑，阿兰希雅还是尊重联盟种族之间的羁绊，并放行了来访的侍僧，让他回应来自圣光大教堂的召回。高阶牧师劳瑞娜已派遣信使跨越重洋，召集不断成长的人类牧师进行进阶训练。当再次踏入暴风城时，侍僧将抛下艾露恩那月光照耀的树林，转而拥抱宏伟的石质圣所和圣光那金色的光辉。"}},faq={{q="为什么女祭司阿兰希雅要我离开达纳苏斯？",a="女祭司阿兰希雅是在执行你在暴风城的上级所发出的召回令，但她本人也对人类的神学实践感到不适。她公开承认自己对奥术魔法——无论是否受到神圣影响——有着根深蒂固的不信任，这使得她急于将人类侍僧送回他们自己的大教堂。",al={"为什么阿兰希雅让我离开","为什么要回暴风城","阿兰希雅奥术反馈"}},{q="为什么暗夜精灵不信任人类的牧师魔法？",a="暗夜精灵文化从根本上是由灾难性的大分裂所定义的，而大分裂是由一万年前鲁莽的奥术施法造成的。卡多雷的崇拜中心是艾露恩，她们的女祭司以极大的怀疑目光看待任何边缘化或结合了奥术操纵的传统，即使这些传统是由圣光信仰的盟友所实践的。",al={"为什么暗夜精灵厌恶奥术","暗夜精灵对奥术的不信任","艾露恩与圣光"}},{q="高阶牧师劳瑞娜是谁？",a="高阶牧师劳瑞娜是暴风城圣光大教堂内一位杰出的精神领袖。她监督着初出茅庐的人类牧师的训练与晋升，在他们力量增长的过程中指导他们理解圣光。",al={"劳瑞娜是谁","高阶牧师劳瑞娜暴风城"}},{q="这个任务后续会衔接什么？",a="向高阶牧师劳瑞娜复命标志着你迈向了暴风城更高阶的人类牧师进修，从而解锁人类圣光信徒独有的戒律与祝福。",al={"奥术反馈后续任务","奥术反馈奖励背景"}}},fp="15,228,19.438.0,23.341.0,54.252.0,49.314.0,30.150.0,31.180.0"}
P.entries["quest:5679"] = {n="噬灵瘟疫",s="噬灵瘟疫是一项传授给遗忘者牧师的仪式，旨在奖励那些证明了自己对暗影魔法虔诚的牧师。这项教导由幽暗城的艾萨莱斯特女祭司授予，标志着侍僧正式开始接触亡灵祭司阶层中最令人畏惧的诅咒之一。",h="噬灵瘟疫是一项传授给遗忘者牧师的仪式，旨在奖励那些证明了自己对暗影魔法虔诚的牧师。这项教导由幽暗城的艾萨莱斯特女祭司授予，标志着侍僧正式开始接触亡灵祭司阶层中最令人畏惧的诅咒之一。",kw={"艾萨莱斯特","噬灵瘟疫","遗忘者","洛丹伦","牧师","暗影","幽暗城","war quarter"},ang={["class:Priest"]="这项仪式为遗忘者牧师提供了他们最令人畏惧的法术之一，将他们的生存直接与施加给敌人的苦难绑定在一起。",["faction:Horde"]="虽然部落的其他盟友依靠先祖之魂或元素平衡，但遗忘者将残忍的、类似疾病的诅咒带入了该阵营的集体军火库中。",["race:Undead"]="拥抱瘟疫般的暗影技艺，反映了遗忘者在第三次战争后与洛丹伦传统信仰的分道扬镳。"},sec={{t="暗影的诅咒",b="在War Quarter阴暗的修道院中，艾萨莱斯特女祭司指引着遗忘者修行者研习残酷的暗影艺术。其他种族的活体牧师依靠圣光或先祖之魂来获取力量，而遗忘者则构建了属于他们自己的精神教条。噬灵瘟疫正是他们哲学思想的结晶：在折磨敌人的同时，将窃取的生命力回馈给他们自身腐朽的躯体。"},{t="大师的试炼",b="艾萨莱斯特不会轻率地传授这种瘟疫的知识。该法术被视为一种充满恶意的武器，旨在扭转对抗天灾军团和血色十字军的战局。在传授法术时，艾萨莱斯特告诫她的弟子们要通过不断的练习来磨练对它的掌控，并警示那些寻求掌握暗影艺术的人，前方还有更严峻的考验在等待着他们。"}},faq={{q="这个任务的目的是什么？",a="该任务是为达到资深地位的遗忘者牧师提供的正式课程。通过与艾萨莱斯特女祭司交谈，牧师可以学会如何施放噬灵瘟疫，这是一种暗影折磨，可以通过吸取受害者的生命力来治疗施法者。",al={"为什么学习噬灵瘟疫","噬灵瘟疫任务做什么","噬灵瘟疫的用途"}},{q="谁是艾萨莱斯特女祭司？",a="艾萨莱斯特女祭司是一位遗忘者牧师训练师，常驻于幽暗城的War Quarter。她负责监督新晋暗影施法者的成长，并确保他们能为遗忘者有效地运用这些毁灭性的赐福。",al={"谁是艾萨莱斯特","艾萨莱斯特背景故事","艾萨莱斯特幽暗城"}},{q="其他种族的牧师能从艾萨莱斯特那里学到噬灵瘟疫吗？",a="噬灵瘟疫并非她独有：每一位牧师，无论种族，都能在20级时从各自的牧师训练师那里习得。遗忘者自身的种族特有技能是虚弱之触和暗影魔。",al={"巨魔能学噬灵瘟疫吗","噬灵瘟疫是亡灵专属吗","其他种族的噬灵瘟疫"}},{q="我在哪里交这个任务？",a="艾萨莱斯特女祭司位于幽暗城的War Quarter，徘徊在遗忘者的牧师导师和修行者之间。",al={"艾萨莱斯特位置","噬灵瘟疫任务在哪里","幽暗城牧师训练师位置"}},{q="为什么遗忘者牧师专注于瘟疫和暗影魔法？",a="由于亡灵的体质，遗忘者牧师在引导圣光时会承受剧烈的身体痛苦。因此，许多人转向了暗影的教义，利用折磨、诅咒和窃取的生命力来生存并参与战争。",al={"为什么有遗忘者暗影牧师","亡灵牧师的背景故事","遗忘者牧师魔法"}},{q="艾萨莱斯特所提到的考验是指什么？",a="艾萨莱斯特警告说，随着牧师力量的增长，在洛丹伦各地所面临的考验将会加剧。操纵黑暗魔法会招致危险的审视和致命的敌人，这要求侍僧对武器库中的每一种诅咒都必须拥有绝对的掌控力。",al={"未来的考验含义","艾萨莱斯特未来的考验","什么考验"}}},fx={["7f0f5b4f"]={q="为什么女祭司艾萨莱斯特要你学习噬灵瘟疫？",a="女祭司艾萨莱斯特认为，噬灵瘟疫是被遗忘者生存所必需的强大武器。她教导被遗忘者牧师这门黑暗技艺，让你做好充分准备，保卫幽暗城，并在洛丹伦等待被遗忘者的无尽考验与冲突中取得胜利。",al={"艾萨莱斯特的动机","为什么教噬灵瘟疫","艾萨莱斯特为什么要你做这件事"}}},fp="16,281,21.464.0,17.391.0,34.238.0,29.233.0,67.200.0,30.140.0,62.242.0,39.236.0"}
P.entries["quest:568"] = {n="格罗姆高保卫战",s="指挥官阿格罗戈什试图维护部落在荆棘谷的立足点，并保障他们通往斯通纳德的补给线。为了确保这条补给线的安全，他指示部落勇士去清理格罗姆高营地外的鞭尾迅猛龙。",h="指挥官阿格罗戈什试图维护部落在荆棘谷的立足点，并保障他们通往斯通纳德的补给线。为了确保这条补给线的安全，他指示部落勇士去清理格罗姆高营地外的鞭尾迅猛龙。",kw={"阿格罗戈什","格罗姆高","部落","鞭尾","迅猛龙","斯通纳德","荆棘谷"},ang={["faction:Horde"]="格罗姆高营地为部落提供了在丛林中的立足点，以及通往斯通纳德的安全补给链。"},sec={{t="确保立足点",b="在格罗姆高营地，指挥官阿格罗戈什肩负着保护丛林中每一位部落成员的职责。这个营地的存在是为了确保补给能安全地运往斯通纳德，但当地的一些原住民却阻碍了这一进程。"},{t="清理丛林掠食者",b="格罗姆高外的迅猛龙就是其中的障碍。阿格罗戈什号召忠诚的战士去清理那里的鞭尾迅猛龙，然后回来找他接受新的任务。"}},faq={{q="谁下令保卫营地？",a="负责格罗姆高营地大酋长据点的指挥官阿格罗戈什，下令清理营地外的迅猛龙。",al={"谁提供任务","指挥官阿格罗戈什","任务发布者"}},{q="为什么格罗姆高营地对部落很重要？",a="这个前哨站对于建立通往位于悲伤沼泽的斯通纳德部落据点的安全补给线至关重要。",al={"格罗姆高的作用","为什么选择格罗姆高","补给线"}},{q="什么威胁正在针对营地的行动？",a="一些当地的原住民阻碍了部落通往斯通纳德的补给线，阿格罗戈什希望清理掉营地外的鞭尾迅猛龙。",al={"什么敌人","为什么是迅猛龙","什么野兽"}},{q="清理迅猛龙之后会发生什么？",a="向指挥官阿格罗戈什汇报你的成功，他会在“格罗姆高的防卫”后续任务中发布新的命令。",al={"接下来做什么","任务后续","后续任务"}}},fp="23,245,21.238.0,29.172.0,35.151.0,49.121.0,49.151.0,39.123.0"}
P.entries["quest:569"] = {n="格罗姆高保卫战",s="指挥官阿格罗戈什试图保护格罗姆高营地穿过荆棘谷的补给线。在早先为了清理营地外迅猛龙而进行的狩猎之后，一伙驻扎在附近米扎废墟的食人魔继续骚扰前往斯通纳德的补给商队。",h="指挥官阿格罗戈什试图保护格罗姆高营地穿过荆棘谷的补给线。在早先为了清理营地外迅猛龙而进行的狩猎之后，一伙驻扎在附近米扎废墟的食人魔继续骚扰前往斯通纳德的补给商队。",kw={"阿格罗戈什","格罗姆高","米扎废墟","莫什奥格","食人魔蛮兵","斯通纳德","荆棘谷","巫医"},ang={["faction:Horde"]="往返于格罗姆高和斯通纳德之间的商队对于维持部落在东部王国南部的存在至关重要。"},sec={{t="保护商队",b="部落在北荆棘谷的行动重心是为斯通纳德提供补给，这是一个具有重要战略意义的前哨站。虽然指挥官阿格罗戈什到来时并没有打算与每一支当地势力交战，但一伙当地的莫什奥格食人魔已经占据了营地东南方的米扎废墟。警告未能阻止他们对部落补给运输队的持续袭击，这促使指挥官下令打击占据废墟的食人魔蛮兵和巫医。"}},faq={{q="食人魔的据点在哪里？",a="食人魔占领了米扎废墟，它位于北荆棘谷格罗姆高营地的东南方。",al={"食人魔位置","米扎废墟在哪里","食人魔营地"}},{q="为什么格罗姆高要针对这些食人魔？",a="格罗姆高的主要目的是为斯通纳德运送补给。米扎废墟的食人魔尽管收到过正式警告，仍反复伏击这些商队。",al={"为什么击杀食人魔","格罗姆高的防卫理由","为什么与莫什奥格战斗"}},{q="谁下达了这次打击命令？",a="驻扎在格罗姆高营地的军事领导人指挥官阿格罗戈什指挥了这次镇压食人魔威胁的行动。",al={"任务发布者","谁发布了任务","谁是阿格罗戈什"}},{q="这项请求之前发生了什么？",a="这是在那场早期的狩猎之后发生的，在那场狩猎中，阿格罗戈什清理了格罗姆高营地外的迅猛龙。",al={"先决条件","上一个任务","系列任务起始"}}},fp="23,265,21.488.0,26.115.0,38.173.0,23.122.0,31.95.0"}
P.entries["quest:57"] = {n="守夜人",s="冒险者受指挥官阿尔泰娅·埃伯洛克直接委派，深入暮色森林那闹鬼的坟场，去清理不断涌现的躁动亡者。这项持续进行的战役旨在针对那些从静谧花园墓场和乌鸦岭中爬出的骷髅恐怖生物。击退这股骷髅天灾，对于防止夜色镇这片脆弱的避风港彻底沦陷于黑暗至关重要。",h="冒险者受指挥官阿尔泰娅·埃伯洛克直接委派，深入暮色森林那闹鬼的坟场，去清理不断涌现的躁动亡者。这项持续进行的战役旨在针对那些从静谧花园墓场和乌鸦岭中爬出的骷髅恐怖生物。击退这股骷髅天灾，对于防止夜色镇这片脆弱的避风港彻底...",kw={"althea ebonlocke","夜色镇","暮色森林","守夜人","乌鸦岭","骷髅恶魔","骷髅恐怖生物","静谧花园"},ang={["class:Paladin"]="对于白银之手和圣光的骑士们来说，在静谧花园面对受亵渎的死者，是一项净化被腐蚀的安息之地的神圣职责。",["class:Priest"]="走在乌鸦岭受污染土地上的牧师们，面对的是对埋葬传统的原始亵渎，他们利用自己的信仰为受折磨的灵魂带来宁静。",["faction:Alliance"]="夜色镇是联盟在东部王国南部脆弱的东南边界。援助守夜人能确保小镇维持一个可行的立足点，而不至于彻底沦为废墟。",["race:Human"]="从暮色森林土地中爬出的许多骷髅，都是现今暴风城和夜色镇居民的祖先，这使得这场战斗对人类保卫者而言显得格外切身。"},sec={{t="死者不安",b="暮色森林从一片翠绿的森林堕落成雾气笼罩的暮色之地，这一悲剧使得当地的墓地变得异常躁动不安。指挥官阿尔泰娅·埃伯洛克率领着夜色镇的志愿民兵组织“守夜人”，正面临着无休止的围攻。由于得不到暴风城的援助，她的兵力已捉襟见肘，形势岌岌可危。有报告称，活过来的骷髅恶魔和恐怖生物正从泥土中爬出，威胁要吞没东部的定居点，这迫使民兵组织不得不招募任何愿意进入这片死亡之地的健壮旅者。"},{t="受诅之地",b="这项战役将招募者带往两个死灵动乱的中心点：镇子南面的静谧花园墓场，以及远在西侧广袤荒芜的乌鸦岭墓地。骸骨从被遗忘的坟墓和路边浅埋的墓穴中爬出，被森林中徘徊的黑暗魔法所唤醒。斩杀这些恶魔能为夜色镇饱受困扰的居民争取宝贵的喘息之机，但这终究是一场对抗根深蒂固的邪恶的持久战。"}},faq={{q="为什么守夜人要依赖旅者，而不是暴风城的卫兵？",a="暴风城在很大程度上已经放弃了暮色森林，将该地区的防务留给了指挥官阿尔泰娅·埃伯洛克和她当地的志愿民兵。面对内部的政治动荡和国王的失踪，暴风城无法提供守军增援，迫使守夜人不得不雇佣路过的冒险者。",al={"为什么没有暴风城的援助","暴风城的军队在哪里","为什么夜色镇孤立无援"}},{q="这些骷髅是从哪里来的？",a="这些骷髅恶魔和恐怖生物正从静谧花园墓场和广袤的乌鸦岭墓地的神圣土地中爬出。弥漫在森林中的黑暗魔法力量扰动了数个世纪的埋葬地，将古老的遗骸唤醒为毫无心智、充满暴力的哨兵。",al={"暮色森林骷髅的起源","为什么会有骷髅","暮色森林亡灵的源头"}},{q="谁领导着守夜人？",a="指挥官阿尔泰娅·埃伯洛克统领着守夜人。她是夜色镇镇长艾尔罗·埃伯洛克公爵的亲属，她亲自指挥着小镇的防卫，并协调对抗暮色森林亡灵和怪物威胁的行动。",al={"守夜人指挥官","谁是阿尔泰娅·埃伯洛克","指挥官埃伯洛克"}},{q="静谧花园和乌鸦岭有什么区别？",a="静谧花园墓场位于夜色镇的正南面，对小镇构成了直接的局部威胁。而乌鸦岭墓地位于森林对面的极西之处，是一片巨大的埋葬地，也是暮色森林亡灵侵扰的核心地带。",al={"静谧花园与乌鸦岭","哪个墓地更好","暮色森林墓地位置"}},{q="清理完这些骷髅后会怎样？",a="清理骷髅恐怖生物和恶魔只是阿尔泰娅战役的一个阶段。守夜人持续监测着森林中不断升高的威胁，从食尸鬼和骷髅，逐渐升级为更危险的亡灵，以及那些在暮色森林深处操纵它们的邪恶死灵法师。",al={"守夜人下一步行动","守夜人任务线","守夜人之后"}},{q="为什么夜色镇总是处于危险之中？",a="曾经作为暴风城王国的一片宁静省份，暮色森林被魔法暮光所吞噬，并遭受着阴影诅咒的折磨。森林现在遍布着野性的狼人、贪婪的蜘蛛和躁动的亡灵，使夜色镇成为了该地区人类文明最后的堡垒。",al={"为什么暮色森林危险","夜色镇的危险","是什么诅咒了暮色森林"}}},fx={dfb05d16={q="指挥官阿尔泰娅·埃伯洛克为什么要你完成这件事？",a="指挥官阿尔泰娅·埃伯洛克负责保护处境艰难的夜色镇及其周边森林。当地墓地不断传来亡灵大举出动、来势汹汹的报告，夜色镇正面临生死存亡的威胁。击退乌鸦岭和静谧花园墓场中四处游荡的恐怖怪物与恶魔，对于防止小镇彻底沦陷至关重要。",al={"为什么替阿尔泰娅杀骷髅","阿尔泰娅·埃伯洛克的动机","为什么清除暮色森林的亡灵"}},["8863b63d"]={q="骷髅恶魔和骷髅恐魔是什么？",a="它们是被黑暗死灵魔法赋予活力的人类遗骸，从暮色森林墓地遭亵渎的土壤中爬出。这些亡灵恶魔和恐魔比普通的蹒跚骷髅更加坚韧、凶残，在乌鸦岭墓地和静谧花园中徘徊，袭击所有路过的生者。",al={"骷髅恶魔和骷髅恐魔","夜色镇要猎杀谁","暮色森林的骷髅目标"}}},fp="15,389,20.512.0,12.482.0,73.312.0,36.275.0,26.240.0,63.272.0,43.279.0,36.282.0"}
P.entries["quest:570"] = {n="摩克萨尔丁的魔法",s="先知摩克萨尔丁试图驾驭荆棘谷的自然魔法，以造福部落。在他之前于格罗姆高营地进行的仪式基础上，他要求获得锋利的爪子和一颗原始的雌虎尖牙，以编织一道强大的附魔。",h="先知摩克萨尔丁试图驾驭荆棘谷的自然魔法，以造福部落。在他之前于格罗姆高营地进行的仪式基础上，他要求获得锋利的爪子和一颗原始的雌虎尖牙，以编织一道强大的附魔。",kw={"附魔","先知","格罗姆高","米扎","摩克萨尔丁","影牙","荆棘谷","雌虎"},ang={["faction:Horde"]="先知摩克萨尔丁进行仪式以驾驭丛林的魔法来帮助部落。"},sec={{t="驾驭丛林",b="在格罗姆高营地内，先知摩克萨尔丁正致力于理解并引导荒野的原始力量，以增强部落的实力。由于他最初的仪式已经取得了成功，他承诺为那些愿意闯入茂密灌木丛并猎杀潜伏在周边地区的致命掠食者的冒险者制作一件特殊的附魔圣物。"},{t="米扎的潜行者",b="仪式需要从影牙猎豹身上获取八只爪子，以及一颗来自雌虎的原始尖牙。摩克萨尔丁指出，虽然这些凶猛的猫科动物在整个荆棘谷四处游荡，但有一群野兽潜伏在东南方向，就在流经米扎废墟的河流彼岸。"}},faq={{q="谁在请求这些野兽的部位？",a="先知摩克萨尔丁，一位驻扎在荆棘谷格罗姆高营地的兽人萨满，正在寻求举行仪式所需的材料。",al={"谁发布摩克萨尔丁的附魔任务","任务发布者摩克萨尔丁","摩克萨尔丁是谁"}},{q="在哪里可以找到猎豹和雌虎？",a="这些野兽在茂密的丛林中广泛分布，但摩克萨尔丁指引猎人们前往米扎废墟东南方的河对岸。",al={"影牙之爪位置","原始雌虎尖牙位置","去哪里狩猎野兽"}},{q="先知摩克萨尔丁为什么要这些物品？",a="摩克萨尔丁正在致力于驾驭丛林中固有的魔法，以施展强大的附魔并为部落的勇士制作一件特殊的物品。",al={"为什么要收集爪子和尖牙","摩克萨尔丁仪式的目的","为什么需要影牙之爪"}},{q="摩克萨尔丁的仪式工作接下来要做什么？",a="在向摩克萨尔丁上交爪子和尖牙后，这位先知将在附魔系列的下一阶段继续他的仪式制作工作。",al={"摩克萨尔丁的附魔2之后是什么","影牙之爪后续任务","摩克萨尔丁任务后续"}}},fp="25,249,21.337.0,22.272.0,36.139.0,46.144.0,47.147.0,45.139.0"}
P.entries["quest:571"] = {n="摩克萨尔丁的魔法",s="格罗姆高营地的先知摩克萨尔丁需要一种坚固的魔法束缚，以便将目前收集到的荆棘谷战利品连接在一起。为了稳固地捆扎这些羽毛、爪子和尖牙，他需要一种从荆棘谷南部的年长灵长类动物身上采集到的陈年肌腱。",h="格罗姆高营地的先知摩克萨尔丁需要一种坚固的魔法束缚，以便将目前收集到的荆棘谷战利品连接在一起。为了稳固地捆扎这些羽毛、爪子和尖牙，他需要一种从荆棘谷南部的年长灵长类动物身上采集到的陈年肌腱。",kw={"陈年猩猩肌腱","藏宝海湾","猩猩","格罗姆高","迷雾谷","摩克萨尔丁","肌腱","荆棘谷"},ang={["faction:Horde"]="先知摩克萨尔丁在格罗姆高营地协助部落冒险者，制造强大的丛林魔法以增强他们在荆棘谷的地位。"},sec={{t="魔法束缚",b="在收集了羽毛、爪子和一枚完美的尖牙后，先知摩克萨尔丁的仪式进入了下一个阶段。为了将这些强大的遗物固定在一起，他需要一种韧性极佳的魔法束缚。只有迷雾谷老猩猩身上陈年的肌腱，才能承受他打算编织的魔法。"},{t="猎杀迷雾谷长者",b="携带必要肌腱的野兽在藏宝海湾以东的丛林中觅食。摩克萨尔丁警告说，只有完美的肌腱才有用，这意味着猎人们可能需要追踪并击杀几头老猩猩，才能获得适合施法的样本。"}},faq={{q="陈年猩猩肌腱是用来做什么的？",a="先知摩克萨尔丁需要它作为一种魔法束缚，将之前收集的羽毛、爪子和完美的尖牙稳固地连接在一起，以进行他的附魔仪式。",al={"为什么需要肌腱","摩克萨尔丁需要肌腱做什么","猩猩肌腱的用途"}},{q="迷雾谷老猩猩在哪里？",a="迷雾谷老猩猩在荆棘谷南部的丛林中觅食，具体来说是在藏宝海湾的东边。",al={"哪里可以找到迷雾谷老猩猩","迷雾谷猩猩的位置","猩猩在哪里"}},{q="谁请求这次狩猎？",a="驻扎在荆棘谷格罗姆高营地的兽人精神向导先知摩克萨尔丁请求获得这种肌腱。",al={"谁给予任务","任务发布者"}},{q="这在摩克萨尔丁的附魔工作中处于什么位置？",a="这次狩猎发生在收集爪子和完美的尖牙之后，而先知摩克萨尔丁的附魔工作将在之后继续进行。",al={"之前有什么任务","任务链顺序","先决条件"}}},fp="25,280,16.310.0,27.259.0,42.158.0,46.116.0,23.118.0,56.137.0"}
P.entries["quest:5713"] = {n="一击必杀",s="在运送一封紧急信件前往奥伯丁的途中，哨兵阿娜莎遭到了一个名叫狡诈的马洛什的敌对熊怪及其追踪者小队的伏击并被下毒。在调制解毒剂时她无法行动，只能依靠附近的旅行者来抵御来袭的攻击者，以求生存并完成她的任务。",h="在运送一封紧急信件前往奥伯丁的途中，哨兵阿娜莎遭到了一个名叫狡诈的马洛什的敌对熊怪及其追踪者小队的伏击并被下毒。在调制解毒剂时她无法行动，只能依靠附近的旅行者来抵御来袭的攻击者，以求生存并完成她的任务。",kw={"伏击","解毒剂","阿娜莎","黑海岸","熊怪","迈斯特拉岗哨","马洛什","奥奈雅","哨兵"},ang={["class:Hunter"]="阿娜莎展现了神射手坚定不移的决心，即使在受到烈毒侵蚀的情况下，依然不断向灌木丛射出致命的箭矢。",["faction:Alliance"]="保持森林道路畅通、不受侵略性熊怪小队的威胁，能确保灰谷与北方联盟据点之间的安全通行。",["race:NightElf"]="保卫阿娜莎既保护了哨兵的一员，也保护了在灰谷和北黑海岸各岗哨之间传递的重要通讯。"},sec={{t="森林之路的伏击",b="随着腐蚀在野生族群中扎根愈深，穿越卡利姆多北部的道路变得愈发凶险。哨兵阿娜莎在前往奥伯丁运送重要通讯的途中，遭到了一群敌对熊怪的拦截。在狡诈的马洛什的带领下，伏击者迅速发动攻击，并使她中了致命的剧毒，导致这位斥候身体虚弱，无法步行完成路程。"},{t="坚守防线",b="虽然精通天然药剂，但在被追杀的情况下，在树冠下调制和服用解毒剂需要阿娜莎没有的时间。随着马洛什的追踪者不断逼近，阿娜莎必须依靠旅行者在她工作时守卫她的位置。尽管体力正在衰退，她依然稳住长弓向灌木丛中射出掩护火力，决心不让自己和信件倒在这荒野之中。"},{t="向迈斯特拉岗哨报告",b="一旦袭击被击退且马洛什被杀，解毒剂将恢复阿娜莎足够的体力，让她完成前往奥伯丁的旅程。为了确保灰谷南部的岗哨能收到针对威胁区域补给路线的侵略性熊怪活动的预警，她请求她的保护者直接向迈斯特拉岗哨的哨兵奥奈雅报告。"}},faq={{q="哨兵阿娜莎是谁？",a="哨兵阿娜莎是一位暗夜精灵斥候，负责在黑海岸和灰谷的边界运送重要信件。她擅长弓箭和丛林生存，在执行任务时，因一场突如其来的下毒伏击而几乎丧命。",al={"哨兵阿娜莎","阿娜莎","阿娜莎是谁"}},{q="是谁袭击了哨兵阿娜莎？",a="她遭到了由狡诈的马洛什率领的一群敌对熊怪的伏击。他们在最初的冲突中让她中了毒，企图在无法行动的斥候恢复之前将其压制。",al={"谁袭击了她","狡诈的马洛什","马洛什","谁给她下的毒"}},{q="哨兵阿娜莎要去哪里？",a="阿娜莎原定前往奥伯丁递送一份重要快件，但在路上被马洛什及其追踪者围困。",al={"阿娜莎要去哪里","阿娜莎的目的地"}},{q="为什么必须向哨兵奥奈雅报告？",a="因为阿娜莎必须立即赶往奥伯丁递送信件，她请求你前往灰谷南部的迈斯特拉岗哨，将熊怪的敌对行为告知哨兵奥奈雅。",al={"哨兵奥奈雅","为什么要去迈斯特拉岗哨","奥奈雅"}},{q="该地区的熊怪为什么具有敌意？",a="在黑海岸和灰谷，许多熊怪部落屈服于第三次战争留下的恶魔污染与疯狂，这驱使他们无差别地攻击往来的哨兵和路人。",al={"为什么熊怪在攻击","熊怪的敌意","受腐蚀的熊怪"}},{q="阿娜莎在伏击中会战斗吗？",a="是的。尽管剧毒让她几乎无法站立，她依然会在调制解毒剂的同时，用长弓提供掩护火力来支持她的防御者。",al={"阿娜莎是否提供帮助","阿娜莎的弓","她是否参加战斗"}}},fp="19,220,25.240.0,16.286.0,24.277.1,24.185.0,30.146.0,37.115.0,39.161.0,41.187.0,37.125.0"}
P.entries["quest:572"] = {n="摩克萨尔丁的魔法",s="先知摩克萨尔丁继续收集各种组件，试图制造一件强力的萨满祭司物品来帮助部落。在处理完猫科动物的战利品后，他将注意力转向了荆棘谷猛禽身上的羽毛。",h="先知摩克萨尔丁继续收集各种组件，试图制造一件强力的萨满祭司物品来帮助部落。在处理完猫科动物的战利品后，他将注意力转向了荆棘谷猛禽身上的羽毛。",kw={"附魔","羽毛","格罗姆高","丛林潜行者","摩克萨尔丁","猛禽","荆棘谷"},ang={["class:Shaman"]="先知将丛林小饰品与他的萨满仪式结合，以制造一件附魔物品。",["faction:Horde"]="先知摩克萨尔丁打算让完成后的附魔成为对部落和大酋长有用的工具。"},sec={{t="潜行者的羽毛",b="在从丛林猫科掠食者身上收集完材料后，先知摩克萨尔丁表示，在他的萨满仪式开始前还需要更多的组件。为了打造一件能够协助大酋长的工具，他需要丛林潜行者身上的羽毛。这些猛禽栖息在格罗姆高营地南部的茂密丛林中，离古拉巴什竞技场不远。"}},faq={{q="是谁在索要这些羽毛？",a="先知摩克萨尔丁，一位驻扎在荆棘谷格罗姆高营地的兽人萨满祭司，他寻求这些羽毛是为了完成一项仪式附魔。",al={"任务发布者","摩克萨尔丁","谁需要羽毛"}},{q="丛林潜行者在哪里？",a="在格罗姆高营地正南方的丛林中，靠近古拉巴什竞技场的地方，可以找到一群这样的猛禽。",al={"丛林潜行者位置","猛禽在哪里","丛林潜行者羽毛在哪里"}},{q="为什么先知摩克萨尔丁需要丛林潜行者的羽毛？",a="摩克萨尔丁正通过萨满仪式将各种丛林奇珍和野兽战利品结合起来，以制造一件旨在帮助部落和大酋长的附魔工具。",al={"羽毛的用途","为什么要潜行者羽毛","摩克萨尔丁仪式"}},{q="在这项请求之前发生了什么？",a="冒险者们此前曾协助摩克萨尔丁猎杀荆棘谷的猫科野兽，为他计划中的附魔收集了初步组件。",al={"之前的任务","前置步骤"}}},fp="25,226,23.361.0,31.143.0,38.122.0,59.174.0,30.143.0"}
P.entries["quest:5722"] = {n="寻找背包",s="“寻找遗失的挎包”是一项由雷霆崖长者高地的拉哈罗所提供的部落任务。冒险者受长者格雷姆玛加萨·野性图腾之托，被指派前往奥格瑞玛下方的怒焰裂谷，寻找玛尔·恐怖图腾的遗骸。玛尔是一名使者，他在洞穴怪中发现了异常情况后不幸遇难。",h="“寻找遗失的挎包”是一项由雷霆崖长者高地的拉哈罗所提供的部落任务。冒险者受长者格雷姆玛加萨·野性图腾之托，被指派前往奥格瑞玛下方的怒焰裂谷，寻找玛尔·恐怖图腾的遗骸。玛尔是一名使者，他在洞穴怪中发现了异常情况后不幸遇难。",kw={"长者高地","玛加萨·野性图腾","玛尔·恐怖图腾","怒焰裂谷","拉哈罗","寻找遗失的挎包","雷霆崖","洞穴怪"},ang={["faction:Horde"]="当萨尔专注于清除部落主城下方的黑暗邪教徒时，从莫高雷传来的低语揭示了恐怖图腾氏族正在同一个洞穴中追求他们自己的隐秘目标。",["race:Tauren"]="恐怖图腾氏族的动机往往与凯恩·血蹄的公开领导方针背道而驰，这使得玛加萨对盟友城市下方地下生物所表现出的隐秘好奇心值得密切关注。"},sec={{t="奥格瑞玛之下的恐怖图腾任务",b="当萨尔酋长和他的顾问们专注于清除潜伏在怒焰裂谷内的暗影议会势力时，恐怖图腾氏族也在谋划着他们自己的秘密勾当。雷霆崖长者高地的玛加萨·野性图腾得到消息，称她的使者玛尔·恐怖图腾进入了奥格瑞玛下方的地下洞穴，试图研究洞穴怪并与它们进行交涉。玛尔此后再也没有回来，但有传言称他在遇害前曾有惊人的发现。"},{t="阵亡的使者",b="受玛加萨委托，她的侍从拉哈罗直接派遣勇士前往怒焰裂谷。在遍布岩浆的坑道深处，玛尔伤痕累累的尸体躺在洞穴怪营地附近，他遭到了粗糙棍棒和赤手空拳的猛烈殴打。这些野兽完全无视了他的财物，将这位牛头人的随身物品和他试图寻回的秘密遗留在了原地，等待玛加萨的代理人去取回。"}},faq={{q="谁发布了这个任务？",a="拉哈罗，一位在雷霆崖长者高地侍奉玛加萨·野性图腾的侍从，发布了这个任务。",al={"任务发布者","谁开启寻找遗失的挎包任务","在哪里领取任务"}},{q="玛尔·恐怖图腾是谁？",a="玛尔是恐怖图腾部族的一名特使，他受玛加萨·野性图腾的派遣进入怒焰裂谷，负责调查并尝试与洞穴怪进行沟通。他在洞穴深处被人殴打致死。",al={"玛尔·恐怖图腾","玛尔是谁","玛尔发生了什么事"}},{q="为什么玛加萨·野性图腾会对怒焰裂谷感兴趣？",a="玛加萨对盘踞在奥格瑞玛下方隧道中的洞穴怪很感兴趣，并派玛尔去尝试与它们沟通。当玛尔在临死前在它们之中发现了某种奇特的事物时，她希望他发现的东西能直接被带回给她。",al={"玛加萨与洞穴怪","为什么玛加萨关心怒焰裂谷","为什么要派遣玛尔"}},{q="玛尔·恐怖图腾的尸体在哪里？",a="玛尔的尸体位于奥格瑞玛下方的怒焰裂谷深处，躺在地下通道沿线的洞穴怪领地附近，遍体鳞伤。",al={"找到玛尔","玛尔·恐怖图腾的位置","玛尔的尸体在哪里"}},{q="洞穴怪在杀死玛尔后搜刮他了吗？",a="没有。洞穴怪对财富、工具或书面文件毫无兴趣，因此玛尔的衣服和挎包在他残破的遗骸旁原封未动。",al={"洞穴怪的战利品","玛尔被洗劫了吗"}},{q="找到玛尔的尸体后会发生什么？",a="搜查玛尔的尸体可以获得他的挎包，这将触发后续任务“归还遗失的挎包”，要求将他的发现带回给雷霆崖的玛加萨·野性图腾。",al={"后续任务","遗失的挎包之后的任务","如何处理挎包"}}},fp="30,171,37.404.0,19.350.1,36.104.0,22.169.0,55.192.0,41.116.0,43.78.0,40.151.1"}
P.entries["quest:5723"] = {n="试探敌人",s="“测试敌人的实力”是拉哈罗在雷霆崖的长者高地代表玛加萨·野性图腾委派的一项部落任务。在奥格瑞玛地下进行的一场灾难性的外交尝试以使节被屠杀而告终后，牛头人寻求报复，通过捕杀盘踞在怒焰裂谷中的穴居怪来实施。",h="“测试敌人的实力”是拉哈罗在雷霆崖的长者高地代表玛加萨·野性图腾委派的一项部落任务。在奥格瑞玛地下进行的一场灾难性的外交尝试以使节被屠杀而告终后，牛头人寻求报复，通过捕杀盘踞在怒焰裂谷中的穴居怪来实施。",kw={"长者高地","玛加萨·野性图腾","奥格瑞玛","怒焰裂谷","拉哈罗","测试敌人的实力","雷霆崖","穴居怪"},ang={["class:Shaman"]="穴居怪拥有自己粗陋的通灵者，他们在熔岩隧道中操纵原始元素，这与光荣的萨满传统形成了扭曲的镜像。",["faction:Horde"]="这项任务展现了跨种族的团结，雷霆崖消耗资源和派遣勇士来保卫奥格瑞玛的地基。",["race:Orc"]="虽然是由牛头人领导层指挥，但这项任务直接保护了兽人首都的心脏地带，使其免受在城市下方挖掘隧道的穴居怪的侵扰。",["race:Tauren"]="牛头人外交官的鲜血染红了怒焰裂谷的岩石，这使得此次袭击成为代表长者高地直接进行的一场复仇行动。"},sec={{t="外交遭遇野蛮",b="当地下的穴居怪首次从奥格瑞玛这座兽人首都下方的烈焰裂隙中涌出时，长者玛加萨·野性图腾发出了和平的提议。她派遣牛头人使节深入地底与这些生物谈判。回应是残酷而直接的：穴居怪毫不犹豫地屠杀了代表。玛加萨将这场屠杀视为对牛头人不可饶恕的侮辱，也是对整个部落日益增长的威胁，因此决定以果断的武力回击这种野蛮行径。"},{t="奥格瑞玛地下的威胁",b="作为玛加萨在雷霆崖的代理人，牛头人拉哈罗负责协调军事响应。他指引勇士潜入怒焰裂谷，定位穴居怪群，并消灭它们的前线战士和萨满祭司。通过深入打击它们的地下领域，部落旨在压制穴居怪的数量，防止它们通过地下隧道涌入上方奥格瑞玛的街道。"}},faq={{q="为什么奥格瑞玛地下城的任务会在雷霆崖发布？",a="这个任务源于牛头人的领导层。玛加萨·野性图腾亲自派遣外交官进入怒焰裂谷与穴居怪谈判，而在那些代表被屠杀后，她的助手拉哈罗负责组织来自雷霆崖长者高地的勇士们为他们复仇。",al={"为什么在雷霆崖","雷霆崖任务起始","拉哈罗位置"}},{q="拉哈罗是谁？",a="拉哈罗是一位位于雷霆崖长者高地的牛头人任务发布者。他代表玛加萨·野性图腾行事，协调前往怒焰裂谷的远征，以消灭穴居怪并寻回在之前失败的外交任务中丢失的圣物。",al={"拉哈罗是谁","拉哈罗npc","拉哈罗长者高地"}},{q="为什么玛加萨·野性图腾试图与穴居怪和平共处？",a="玛加萨试图将这一倡议作为一种善意的举动，试图与这些地底生物建立联系，而不是立即流血冲突。然而，穴居怪证明了它们无法或不愿进行文明交流，在使节抵达时就将他们屠戮殆尽。",al={"为什么与穴居怪和平","玛加萨穴居怪外交","为什么要与穴居怪谈判"}},{q="这个任务需要击杀哪些敌人？",a="你的任务是进入奥格瑞玛下方的怒焰裂谷，击杀怒焰穴居怪和怒焰萨满祭司，以突破它们的前线并削弱它们的施法支援。",al={"需要击杀哪些怪物","任务目标","怒焰穴居怪"}},{q="这个任务可以和其他地下城任务一起完成吗？",a="是的。拉哈罗也提供“寻找丢失的背包”任务，该任务派遣冒险者进入同一个裂谷寻找失败外交小队的遗物，因此同时进行这两个任务效率更高。",al={"其他怒焰裂谷任务","寻找丢失的背包任务","怒焰裂谷任务"}},{q="穴居怪是从哪里来的？",a="穴居怪是从杜隆塔尔深处的火山裂隙中涌出的。正如拉哈罗在任务完成时所指出的那样，部落对这些野蛮的洞穴居民的起源，或者为什么它们选择在这个时刻向上挖掘进入奥格瑞玛，知之甚少。",al={"穴居怪起源怒焰裂谷","穴居怪来自哪里","为什么穴居怪在奥格瑞玛下方"}}},fp="27,200,24.301.0,28.275.0,68.238.0,15.235.0,52.231.0,44.162.0,58.177.0,33.225.0"}
P.entries["quest:5724"] = {n="归还背包",s="这项差事终结了在奥格瑞玛地下的怒焰裂谷深处寻找玛尔·恐怖图腾的任务。冒险者们发现了紧紧抱着背包死去的牛头人，必须将找回的背包带回雷霆崖长者高地的拉哈罗那里。",h="这项差事终结了在奥格瑞玛地下的怒焰裂谷深处寻找玛尔·恐怖图腾的任务。冒险者们发现了紧紧抱着背包死去的牛头人，必须将找回的背包带回雷霆崖长者高地的拉哈罗那里。",kw={"长者高地","恐怖图腾背包","玛加萨","玛尔·恐怖图腾","怒焰裂谷","拉哈罗","归还丢失的背包","雷霆崖"},ang={["faction:Horde"]="穴居人和邪教徒威胁着奥格瑞玛下方的隧道，而恐怖图腾特工在萨尔堡垒之下的秘密行动引发了无法解答的政治疑问。",["race:Tauren"]="恐怖图腾氏族与凯恩·血蹄的子民关系紧张，这使得玛加萨的追随者在奥格瑞玛进行的任何秘密行动都会引起怀疑。"},sec={{t="恐怖的发现",b="在怒焰裂谷的红岩与烈焰深处，玛尔·恐怖图腾惨死在穴居人手中。即便在死后，他的双臂依然紧紧锁住他的个人背包，用尽最后一口气守护着其中的物品。从他僵硬的紧握中撬下背包，是了解这位恐怖图腾氏族成员为何会深入萨尔首都之下那片火山洞穴的唯一线索。"},{t="玛加萨的意图",b="当把背包交给长者高地的拉哈罗时，很明显这项任务是由玛加萨·野性图腾本人监督的。拉哈罗感激地收下了包裹，他也在寻找玛加萨的一名族人为何会枉死的答案，并交付了由这位长者先知亲自授权的奖励。玛尔携带的是什么，或者为什么玛加萨会派他进入穴居人出没的奥格瑞玛裂隙，这些只有恐怖图腾氏族的领导层才知道。"}},faq={{q="玛尔·恐怖图腾在哪里？",a="玛尔·恐怖图腾的尸体位于奥格瑞玛下方的怒焰裂谷地下城深处，周围满是敌对的穴居人。",al={"玛尔·恐怖图腾的尸体","找到玛尔·恐怖图腾","玛尔在哪里"}},{q="我该把背包交给谁？",a="必须将恐怖图腾背包带回雷霆崖长者高地的拉哈罗那里。",al={"归还丢失的背包","拉哈罗在哪里","提交背包"}},{q="为什么玛尔·恐怖图腾会在怒焰裂谷？",a="拉哈罗声称不知道为什么玛加萨的族人会枉死，但玛加萨·野性图腾亲自下令进行回收工作，这表明玛尔当时是在执行氏族事务。",al={"玛尔为什么在怒焰裂谷","玛尔的任务","玛尔在做什么"}},{q="恐怖图腾背包里装着什么？",a="具体内容从未向送货人透露。玛尔至死都拼命守护着它，背包在未开封的情况下直接以玛加萨的名义交给了拉哈罗。",al={"包里有什么","背包内容物"}},{q="是什么杀死了玛尔·恐怖图腾？",a="玛尔遭到了潜伏在怒焰裂谷隧道中的野蛮穴居人的伏击并被杀害。",al={"玛尔是怎么死的","谁杀了玛尔"}},{q="谁在幕后指使这项任务？",a="虽然拉哈罗是长者高地的联络人，但奖励和指令直接来自长者先知玛加萨·野性图腾。",al={"谁派拉哈罗来的","玛加萨的关系"}}},fp="26,155,16.281.0,18.358.1,32.100.0,32.70.0,41.188.0,37.166.0,27.72.0,24.120.0"}
P.entries["quest:5725"] = {n="毁灭之力",s="这项任务由幽暗城的恐惧魔王瓦里玛萨斯指派，它将部落的冒险者们送往奥格瑞玛地下的怒焰裂谷深处。希尔瓦娜斯·风行者（Sylvanas Windrunner）需要两本由燃烧之刃教派持有的黑暗书籍，以支持她针对天灾军团和巫妖王的长期战争。",h="这项任务由幽暗城的恐惧魔王瓦里玛萨斯指派，它将部落的冒险者们送往奥格瑞玛地下的怒焰裂谷深处。希尔瓦娜斯·风行者（Sylvanas...",kw={"扭曲虚空的魔法","巫妖王","怒焰裂谷","燃烧之刃","暗影法术研究","希尔瓦娜斯","幽暗城","瓦里玛萨斯"},ang={["class:Warlock"]="取回《暗影法术研究》和《扭曲虚空的魔法》是剥夺鲁莽教徒手中危险的军团奥术这一常见套路的缩影。",["faction:Horde"]="清理燃烧之刃有助于巩固奥格瑞玛的根基，即使这些魔法战利品被秘密运往幽暗城的宝库。",["race:Undead"]="对于被遗忘者的勇士来说，穿越无尽之海去搜刮奥格瑞玛的腹地，既服务于他们与部落的联盟，也服务于黑暗女王摧毁天灾军团的终极野心。"},sec={{t="借来的军火",b="当萨尔的兽人专注于清除潜伏在他们首都之下的燃烧之刃教派成员时，被遗忘者却从该教派的邪术储备中看到了机会。瓦里玛萨斯奉希尔瓦娜斯·风行者之命，派遣特工潜入怒焰裂谷，夺取两本恶魔魔典：《暗影法术研究》和《扭曲虚空的魔法》。在黑暗女王眼中，与其让那些低下的教徒挥霍恶魔的馈赠，倒不如让意志坚定的被遗忘者将其利用起来。"},{t="解放之战",b="在获得这些书籍后，瓦里玛萨斯揭示了它们更深层的用途。其中蕴含的黑暗魔法旨在增强希尔瓦娜斯针对天灾军团的持续战役。通过夺取每一丝禁忌的力量，被遗忘者希望能打破巫妖王对洛丹伦的控制，并将剩余的亡灵从他的精神奴役中彻底解放出来。"}},faq={{q="瓦里玛萨斯为什么要从奥格瑞玛下方索取书籍？",a="怒焰裂谷内的燃烧之刃教派成员拥有的强大恶魔魔典。希尔瓦娜斯认为这些燃烧军团的神器浪费在这些教徒手中实在可惜，她希望将这些黑暗知识转而用于对付巫妖王。",al={"为什么瓦里玛萨斯要怒焰裂谷的书","幽暗城怒焰裂谷任务原因","为什么要偷书"}},{q="你要去收集什么书籍？",a="你必须从燃烧之刃的邪教徒和术士手中夺取两本法术书：《暗影法术研究》和《扭曲虚空的魔法》。",al={"什么书","摧毁书籍的力量","怒焰裂谷书籍掉落"}},{q="瓦里玛萨斯在幽暗城的什么地方？",a="瓦里玛萨斯站在幽暗城Royal Quarter的希尔瓦娜斯·风行者身边。",al={"瓦里玛萨斯位置","瓦里玛萨斯在哪里","交付地点"}},{q="这与被遗忘者的总体目标有何关联？",a="希尔瓦娜斯正在收集一切可能的工具来与天灾军团开战。夺取禁忌的恶魔奥术为被遗忘者提供了更强的魔法手段，以粉碎巫妖王对亡灵的统治。",al={"被遗忘者动机","为什么希尔瓦娜斯需要法术","幽暗城巫妖王阴谋"}},{q="萨尔知道被遗忘者在拿这些书吗？",a="虽然奥格瑞玛的部落领导层专注于清除街道下方的叛徒和恶魔，但瓦里玛萨斯的具体取回命令被包装成黑暗女王的私下事务，而非部落的正式联合法令。",al={"萨尔知道吗","奥格瑞玛幽暗城秘密书籍","暗影议会书籍兽人反应"}},{q="燃烧之刃是谁？",a="燃烧之刃是暗影议会的一个秘密分支，直接在奥格瑞玛下方的怒焰裂谷内运作，在大酋长的眼皮底下练习黑暗的恶魔魔法。",al={"什么是燃烧之刃","燃烧之刃怒焰裂谷","怒焰裂谷教徒"}}},fp="23,245,18.404.0,22.311.0,58.178.0,35.131.0,47.90.0,53.165.0,53.225.0,26.165.0"}
P.entries["quest:5726"] = {n="隐藏的敌人",s="“隐患”是萨尔大酋长调查杜隆塔尔境内邪教渗透行动的开篇章节。萨尔敏锐地察觉到，有恶魔的同情者正在部落的眼皮底下活动，因此他指派了一位前途无量的年轻冒险者，前往骷髅石取回一枚军官的徽章，以开启一项秘密行动。",h="“隐患”是萨尔大酋长调查杜隆塔尔境内邪教渗透行动的开篇章节。萨尔敏锐地察觉到，有恶魔的同情者正在部落的眼皮底下活动，因此他指派了一位前途无量的年轻冒险者，前往骷髅石取回一枚军官的徽章，以开启一项秘密行动。",kw={"火刃氏族","杜隆塔尔","隐患","军官的徽章","奥格瑞玛","骷髅石","萨尔"},ang={["class:Warlock"]="部落的术士必须小心行事：尽管他们在萨尔的严格监管下修炼邪能艺术，但他们同样被征召去铲除那些因肆无忌惮地侍奉恶魔而威胁到奥格瑞玛生存的邪教徒。",["faction:Horde"]="这项任务标志着一个关键时刻，冒险者得到了萨尔大酋长的亲自托付，去保护新生部落的核心免受恶魔颠覆。",["race:Orc"]="对于那些努力克服嗜血狂怒和恶魔诅咒羞耻感的兽人来说，追剿火刃氏族是一场个人的战斗，目的是防止恶魔的瘟疫第二次毒害他们的人民。"},sec={{t="杜隆塔尔内部的腐化",b="尽管新生部落正在努力于杜隆塔尔开辟一个安全的家园，但萨尔大酋长面临的阴险威胁远比半人马的突袭或野猪人的进犯更为致命：内部的背叛。被称为火刃氏族的恶魔邪教在奥格瑞玛大门外扎下了根，利用残存的恶魔腐化和对黑暗力量的渴求进行诱惑。萨尔意识到，派遣正式的库卡隆卫士或知名的指挥官只会打草惊蛇，让邪教徒藏得更深。他需要一个没有显赫背景、不会引起注意的人，来充当他的耳目。"},{t="渗透骷髅石",b="奥格瑞玛东面是骷髅石，那是一处布满术士、虚空行者和狂热邪教徒的崎岖洞穴。萨尔将冒险者直接送入了这个巢穴，并下达了一项明确的任务：从一名火刃氏族首领身上夺取一枚军官的徽章。这枚徽章不仅仅是战场上的战利品，更是进入邪教阴影层级的关键凭证，使他们能够开展更深层次的卧底行动，揭开是谁在幕后指使这些邪教徒的活动。"}},faq={{q="谁发布了“隐患”任务？",a="该任务由萨尔大酋长亲自发布，他在奥格瑞玛的智慧谷内等你，前提是你已经向奥戈尼尔·魂痕报到过。",al={"隐患任务发布者","谁开启隐患任务","在哪里接隐患任务"}},{q="“隐患”的任务目标是什么？",a="萨尔指派你前往位于奥格瑞玛东部的骷髅石，消灭火刃氏族的邪教徒，并带回一枚军官的徽章。",al={"隐患任务目标","隐患任务需要什么"}},{q="为什么萨尔不直接派遣精锐卫队去清理骷髅石？",a="萨尔担心公开的军事行动会惊动真正的阴谋家，让他们逃脱并隐藏得更深。一个默默无闻的冒险者可以悄悄获取凭证，渗透进他们的网络，而不会引起在幕后操纵的高层叛徒的警觉。",al={"为什么萨尔需要冒险者","为什么不派遣军队"}},{q="什么是骷髅石？",a="骷髅石是一个位于杜隆塔尔东海岸、奥格瑞玛东北方的隐蔽洞穴系统。它是火刃氏族邪教的秘密据点和召唤巢穴。",al={"骷髅石在哪里","什么是骷髅石洞穴"}},{q="军官的徽章有什么用？",a="这枚徽章是邪教徒等级的证明。萨尔计划利用它来伪装并安插一名卧底进入火刃氏族的内部，以查明是谁在策划他们的行动。",al={"徽章有什么用","军官的徽章用途"}},{q="还有哪些任务可以和这个任务一起完成？",a="进入骷髅石的冒险者通常会完成收集邪教徒项圈的任务“骷髅石”，并且可以从邪教首领加兹兹身上拾取“燃影之眼”以开启任务“燃烧的阴影”。",al={"骷髅石任务","骷髅石里的任务"}}},fx={aa12f8a2={q="萨尔为什么要调查火刃氏族？",a="萨尔认为，火刃氏族教派是年轻的部落面临的最大内患。这个崇拜恶魔的背叛者团伙就在奥格瑞玛家门口滋生，动摇着兽人在杜隆塔尔浴血建立的一切。大酋长不愿在不了解对方势力范围的情况下贸然出击，而是要查明腐化渗透得有多深，并在它吞噬新家园之前连根拔除。",al={"萨尔为什么要这样做","萨尔在隐藏的敌人任务中的动机","为什么调查火刃氏族"}},d2691c1c={q="骷髅石里的火刃氏族教徒是谁？",a="你要追捕的是藏在奥格瑞玛以东骷髅石中的火刃氏族成员和术士。这个残余势力曾是一个令人骄傲的兽人氏族，如今却堕落成一个崇拜恶魔腐化、擅长暗中操纵的暗影教派。他们盘踞在首都附近的秘密洞穴中，编织着背叛、贪婪与黑暗魔法之网，企图从内部颠覆萨尔的新部落。",al={"骷髅石里的火刃氏族是谁","骷髅石的敌人","隐藏的敌人任务的目标"}}},fp="14,320,22.586.0,23.509.0,35.146.0,35.145.0,66.266.0,19.185.0,43.198.0,54.199.0"}
P.entries["quest:5727"] = {n="隐藏的敌人",s="在发现骷髅石有邪教活动后，大酋长萨尔指派你潜入奥格瑞玛内部的火刃氏族。通过向术士尼鲁·火刃出示一枚邪教军官的徽章，你试探了他的忠诚，并揭开了在城市地底运作的暗影议会的面纱。",h="在发现骷髅石有邪教活动后，大酋长萨尔指派你潜入奥格瑞玛内部的火刃氏族。通过向术士尼鲁·火刃出示一枚邪教军官的徽章，你试探了他的忠诚，并揭开了在城市地底运作的暗影议会的面纱。",kw={"火刃氏族","cleft of shadow","徽章","尼鲁·火刃","奥格瑞玛","怒焰裂谷","暗影议会","萨尔"},ang={["class:Warlock"]="尼鲁声称要为在部落寻求合法地位的术士们代言，但他的背叛行为极有可能为所有在萨尔统治下研习邪能艺术的人招致严厉的谴责。",["faction:Horde"]="邪教在奥格瑞玛的基石下公开运作这一事实，威胁到了年轻部落的生存。",["race:Orc"]="对于那些努力摆脱嗜血诅咒和恶魔腐化阴影的兽人来说，暗影议会在他们首都之下的死灰复燃，是他们在德拉诺那段黑暗往事的一声冰冷回响。"},sec={{t="大酋长的计策",b="萨尔没有直接打击潜藏在大断崖中的邪恶势力，而是选择了智取。他非常清楚尼鲁·火刃是在假装忠诚，实则暗中为邪教徒效力。若是立即铲除尼鲁，只会惊动他的主子，并切断追踪这场阴谋的线索。相反，萨尔交给你从杜隆塔尔的邪教徒手中缴获的徽章，让你伪装成一名新招募的邪教徒，以查清尼鲁究竟知道些什么。"},{t="大断崖中的幕后黑手",b="在大断崖阴暗的洞穴里，怒焰裂谷入口外，尼鲁·火刃很快便上了钩。他以为你是他教派中新晋的军官，便对萨尔的愚蠢嗤之以鼻。他透露说，火刃氏族以及灼热之刃等分支机构只不过是直属于暗影议会的幌子组织，而暗影议会则是在为燃烧军团的意志服务。他夸耀自己是如何诱骗大酋长派忠诚的士兵去怒焰裂谷对抗邪教徒，并借萨尔军队之手清除异己。"}},faq={{q="既然萨尔知道尼鲁是个叛徒，为什么还要留他性命？",a="萨尔留着尼鲁是因为一个暴露的叛徒比死人更有价值。如果立即处决他，暗影议会只会换上一个更难察觉的人。通过将尼鲁置于监视之下，萨尔将这名术士变成了一个不知情的奥格瑞玛邪教动向情报来源。",al={"萨尔为何信任尼鲁","为何留尼鲁性命","尼鲁是叛徒"}},{q="尼鲁·火刃是谁？",a="尼鲁·火刃是一名居住在大断崖的兽人术士。表面上，他假装帮助萨尔将术士改造成部落尽职尽责的仆人。暗地里，他是火刃氏族邪教的头目，以暗影议会的名义在城市地底策划背叛活动。",al={"尼鲁背景故事","尼鲁是谁"}},{q="火刃氏族和暗影议会之间是什么关系？",a="正如尼鲁所言，火刃氏族并非独立的教派，而是暗影议会的分支。议会维持着几个附属邪教——包括怒焰裂谷内的灼热之刃——旨在分化、误导和控制那些雄心勃勃的施法者，使其最终臣服于燃烧军团的统治之下。",al={"火刃氏族与暗影议会的关系","火刃氏族是否属于暗影议会"}},{q="谁领导着怒焰裂谷里的邪教徒？",a="在奥格瑞玛下方裂谷中运作的灼热之刃教派由一名叫巴扎兰的萨特和一名叫祈求者耶戈什的兽人术士共同领导。尼鲁利用萨尔的冒险者去对抗他们，既通过冲突消耗部落的忠诚者，又借机考验他的下属。",al={"怒焰裂谷的领袖","灼热之刃的领袖"}},{q="我是如何获得军官的徽章的？",a="这枚徽章是在萨尔最初调查杜隆塔尔境内的邪教活动时，专门从那些在骷髅石运作的火刃氏族邪教徒身上回收的。",al={"军官徽章的来源","徽章出处"}}},fp="14,191,21.381.0,25.458.1,61.237.1,23.215.1,74.233.1,45.202.0,43.155.0"}
P.entries["quest:5728"] = {n="隐藏的敌人",s="“隐秘的敌人”是萨尔大酋长指派的一项关键渗透任务，目的是铲除奥格瑞玛地底之下滋生的阴险邪教。在欺骗了狡诈的尼鲁·火刃，使其误以为你是盟友之后，萨尔将你送入怒焰裂谷的熔岩深处，去刺杀灼热之刃的高层指挥官。",h="“隐秘的敌人”是萨尔大酋长指派的一项关键渗透任务，目的是铲除奥格瑞玛地底之下滋生的阴险邪教。在欺骗了狡诈的尼鲁·火刃，使其误以为你是盟友之后，萨尔将你送入怒焰裂谷的熔岩深处，去刺杀灼热之刃的高层指挥官。",kw={"巴扎兰","cleft of shadow","隐秘的敌人","祈求者耶戈什","尼鲁·火刃","怒焰裂谷","灼热之刃","暗影议会","萨尔"},ang={["class:Warlock"]="虽然萨尔容忍术士为了部落的防卫而修习黑魔法，但耶戈什和灼热之刃已经越界，投靠恶魔主人成为了叛徒。",["faction:Horde"]="杜隆塔尔心脏地带的恶魔腐化威胁着新部落奋斗建立的一切；肃清怒焰裂谷对于维护他们来之不易的自主权至关重要。",["race:Orc"]="对于那些寻求从嗜血诅咒中获得救赎的兽人来说，铲除奥格瑞玛地底的暗影议会残党关乎深刻的文化生存与荣誉。"},sec={{t="街巷之下的毒瘤",b="奥格瑞玛建立之初是作为自由兽人种族的避风港，但其地基之下却潜藏着古老的恶魔枷锁。在熙熙攘攘的集市下方是大断崖，由此可以通往地下的怒焰裂谷隧道。在这些火山深处，被称为“灼热之刃”的暗影议会残党正积蓄力量，他们修炼黑魔法，图谋从内部颠覆年轻的部落，夺取其首都。"},{t="扮演双重间谍",b="没有情报的直接攻击只会让暗影议会的网络得以保存。萨尔策划了一场卧底计谋，利用你从大断崖里看似配合的术士尼鲁·火刃那里套取情报。尼鲁坚信你忠于他们扭曲的事业，不知不觉中交出了该邪教地下首领的名单：腐化的萨特巴扎兰和术士祈求者耶戈什。"},{t="斩首灼热之刃",b="萨尔指派你潜入怒焰裂谷，屠戮巴扎兰和耶戈什，让邪教徒陷入混乱。至关重要的是，这些刺杀行动必须保持不可追查性——尼鲁绝不能发现是谁执行了屠杀，因为萨尔打算继续监视这名术士。消灭这些头目会在邪教内部引发剧烈震荡，为部落这方初生的城市争取宝贵的喘息空间。"}},faq={{q="是谁下令在“隐秘的敌人”中进行刺杀？",a="萨尔大酋长直接在奥格瑞玛的智慧谷指挥这项任务，选择信任你执行敏感的间谍活动，以确保城市地底的安全。",al={"隐秘的敌人任务领取者","隐秘的敌人任务发布者","萨尔怒焰裂谷任务"}},{q="为什么萨尔不直接处决尼鲁·火刃？",a="萨尔倾向于让尼鲁活着并处于监视之下。了解叛徒的身份可以让大酋长的斥候监控暗影议会的通信，预判未来的阴谋，而不是让一个隐藏的继任者取而代之。",al={"为什么不杀尼鲁","为什么留着尼鲁","尼鲁·火刃叛徒"}},{q="巴扎兰和祈求者耶戈什在哪里？",a="这两名领袖都盘踞在怒焰裂谷深处，该地下城可以通过奥格瑞玛的大断崖进入。耶戈什占据着一个指挥邪教徒的火山岩架，而萨特巴扎兰则潜伏在附近一个高处的洞穴里。",al={"巴扎兰在哪","耶戈什在哪","怒焰裂谷首领"}},{q="灼热之刃是什么组织？",a="灼热之刃是一个与火刃氏族和暗影议会结盟的本地教派。他们崇拜恶魔力量，在奥格瑞玛地底修习邪能魔法，其终极目标是推翻萨尔，并让部落再次沦为奴隶。",al={"什么是灼热之刃","灼热之刃邪教","奥格瑞玛火刃氏族"}},{q="为什么像巴扎兰这样的萨特会在兽人城市地底活动？",a="萨特是燃烧军团的古老仆从。巴扎兰担任恶魔驯兽师和煽动者，引导灼热之刃的凡人教徒在萨尔的眼皮底下直接执行军团的意志。",al={"为什么奥格瑞玛有萨特","巴扎兰背景故事","怒焰裂谷的萨特"}},{q="这个任务如何融入更广泛的怒焰裂谷副本流程？",a="“隐秘的敌人”是萨尔渗透任务链的高潮。它与针对怒焰裂谷的其他多个地下城任务相一致，引导玩家在一次协调的打击中消灭地下城的主要人形首领。",al={"隐秘的敌人是怒焰裂谷任务吗","怒焰裂谷任务线","隐秘的敌人任务链"}}},fp="14,199,28.376.0,24.365.1,30.333.2,37.140.0,48.204.1,51.217.0,26.218.0,57.219.0,60.179.0"}
P.entries["quest:5729"] = {n="隐藏的敌人",s="“隐藏的敌人”是萨尔酋长调查奥格瑞玛内部邪教渗透的关键一步。在处决了城市下方的灼热之刃的首领后，玩家被派去进一步潜伏，成为尼鲁·火刃的亲信。",h="“隐藏的敌人”是萨尔酋长调查奥格瑞玛内部邪教渗透的关键一步。在处决了城市下方的灼热之刃的首领后，玩家被派去进一步潜伏，成为尼鲁·火刃的亲信。",kw={"巴扎兰","火刃氏族","cleft of shadow","隐藏的敌人","祈求者耶戈什","尼鲁·火刃","奥格瑞玛","怒焰裂谷","暗影议会","萨尔"},ang={["class:Rogue"]="这项任务是经典的渗透任务教科书：清除目标的网络，并立即介入成为他们最信任的亲信。",["class:Warlock"]="尼鲁·火刃公开站在暗影裂口的术士训练师中，这表明萨尔的新部落在不屈服于彻底腐化的情况下，与黑暗魔法的距离有多么接近。",["faction:Horde"]="这项任务突显了萨尔务实的外交和治国方略，利用反间谍手段从内部保卫奥格瑞玛，而不是仅仅依靠武力。",["race:Orc"]="对于努力摆脱旧部落恶魔遗产的兽人来说，将火刃氏族从奥格瑞玛的根基中铲除，对于保护他们的荣誉至关重要。"},sec={{t="萨尔的计策",b="在怒焰裂谷刺杀巴扎兰和祈求者耶戈什后，萨尔意识到一个机会。酋长并没有直接揭发尼鲁·火刃，而是决定放长线钓大鱼。尼鲁对地下副手突然丧命感到痛苦，这在当地邪教内部造成了领导权真空。萨尔派你回到暗影裂口的阴影处，将自己伪装成一个可以填补这一空缺的可靠盟友。"},{t="术士的骗局",b="当你在暗影裂口接近尼鲁·火刃时，他因同谋突然落败而暴跳如雷。尼鲁并不知道站在他面前的正是执行萨尔命令的冒险者，他诅咒着那些让怒焰裂谷陷入混乱的“多管闲事者”。由于被打了个措手不及，尼鲁开始对玩家放松警惕，这为萨尔从奥格瑞玛内部直接监视暗影议会的影响力铺平了道路。"}},faq={{q="为什么萨尔不直接处决尼鲁·火刃？",a="萨尔更愿意把暴露的敌人留在眼皮底下监视。通过让尼鲁继续潜伏并让他以为自己的伪装天衣无缝，萨尔可以利用玩家作为内部特工，监控火刃氏族的通讯并追踪他们与暗影议会的联系。",al={"为什么要放过尼鲁","为什么萨尔让尼鲁活着","尼鲁还活着"}},{q="巴扎兰和祈求者耶戈什是谁？",a="巴扎兰是一个萨特，而祈求者耶戈什是一个兽人术士。他们在奥格瑞玛下方的怒焰裂谷深处活动，在萨尔下令处决他们之前，他们一直领导着灼热之刃邪教。",al={"巴扎兰","祈求者耶戈什","谁在怒焰裂谷中死了"}},{q="尼鲁知道是你杀了他的副手吗？",a="不知道。尼鲁在发泄愤怒时，认为萨尔派出的不知名特工突袭并杀害了他们，完全没有意识到那个向他表示慰问并提供帮助的冒险者就是行凶者。",al={"尼鲁知道吗","尼鲁知道是谁杀了他们"}},{q="尼鲁·火刃在哪里？",a="尼鲁·火刃居住在暗影裂口，这是一个位于奥格瑞玛中心下方的地下洞穴，术士、潜行者和暗影施法者聚集于此，远离城市的其他区域。",al={"尼鲁的位置","找到尼鲁","尼鲁·火刃在哪里"}},{q="什么是火刃氏族？",a="火刃氏族最初是德拉诺的一个凶猛氏族，后来沦为受暗影议会操纵的恶魔邪教。在卡利姆多，其残余势力试图破坏萨尔的新部落，并恢复恶魔的奴役。",al={"火刃氏族","火刃氏族邪教"}},{q="与尼鲁交谈后会发生什么？",a="在赢得了尼鲁的信任并听取了他对怒焰裂谷损失的沮丧抱怨后，你会回到Grommash Hold向萨尔报告你的成功，并结束这个渗透任务链。",al={"接下来做什么","任务后续"}}},fp="14,183,15.316.0,23.356.1,60.207.0,30.178.0,46.169.0,33.165.0,26.210.0,37.188.1"}
P.entries["quest:573"] = {n="摩克萨尔丁的魔法",s="先知摩克萨尔丁需要最后一样神圣的材料，才能在格罗姆高营地完成仪式项圈的附魔。他指引你前往西部海滨南部峭壁上的一处高地圣泉，那里已经引起了一支敌对纳迦探险队的注意。",h="先知摩克萨尔丁需要最后一样神圣的材料，才能在格罗姆高营地完成仪式项圈的附魔。他指引你前往西部海滨南部峭壁上的一处高地圣泉，那里已经引起了一支敌对纳迦探险队的注意。",kw={"仪式项圈","格罗姆高","圣泉","圣泉水","摩克萨尔丁","纳迦探险者","荆棘谷"},ang={["faction:Horde"]="先知摩克萨尔丁请求部落的勇士们协助完成一件旨在向大酋长致敬并保护部落的仪式项圈。"},sec={{t="被争夺的圣泉",b="在摩克萨尔丁的附魔过程的前几个阶段之后，这位先知需要从位于荆棘谷南部边缘、靠近西海岸的高处峭壁上的圣泉取水。这个地点是神秘学和神学学者们争论的焦点，艾泽拉斯的每一个种族都声称这圣水是专门为他们自己的族人而净化的。"},{t="纳迦入侵",b="一群纳迦探险者已经潜入圣泉，必须将他们解决掉。摩克萨尔丁要求杀死十名这种蛇人入侵者，并取来一瓶圣泉水，以便以大酋长的名义完成仪式项圈的准备工作。"}},faq={{q="圣泉在哪里？",a="圣泉位于荆棘谷南部地区，靠近西海岸的峭壁顶端。",al={"圣泉位置","圣泉水在哪里","圣泉峭壁"}},{q="为什么圣泉很重要？",a="宗教和神秘学学者们对圣泉争论不休，因为艾泽拉斯的每一个种族都坚称这神圣的泉水是专门为他们而净化的。",al={"为什么泉水是神圣的","圣泉的重要性"}},{q="是谁在争夺圣泉？",a="一支纳迦探险队已经推进到圣泉周围的峭壁上，威胁着该地区。",al={"谁袭击了圣泉","圣泉的敌人"}},{q="这水有什么用？",a="这水是先知摩克萨尔丁为了保卫部落，准备和附魔仪式项圈所需的最后一样试剂。",al={"为什么需要圣泉水","圣泉水的用途"}}},fp="25,280,18.386.0,18.253.0,33.112.0,44.162.0,34.108.0,33.138.0"}
P.entries["quest:5730"] = {n="隐藏的敌人",s="“隐藏的敌人”是大酋长萨尔为了渗透并评估潜伏在奥格瑞玛内部的火刃集会所而实施的行动的最高潮。在获取尼鲁·火刃的信任并向萨尔汇报后，你为这个教派在卡利姆多的扩张势力提供了关键的情报。",h="“隐藏的敌人”是大酋长萨尔为了渗透并评估潜伏在奥格瑞玛内部的火刃集会所而实施的行动的最高潮。在获取尼鲁·火刃的信任并向萨尔汇报后，你为这个教派在卡利姆多的扩张势力提供了关键的情报。",kw={"灰谷","贫瘠之地","火刃氏族","cleft of shadow","隐藏的敌人","尼鲁·火刃","怒焰裂谷","灼热之刃","暗影议会","萨尔"},ang={["class:Rogue"]="这项任务代表了部落早期的间谍手段，即比起直接对抗，更优先考虑深层潜伏、反间谍工作和耐心。",["class:Warlock"]="尼鲁·火刃代表了邪能实践中的危险边缘，展示了黑暗艺术是如何轻易地从国家认可的实用工具滑向对暗影议会的彻底奴役。",["faction:Horde"]="在奥格瑞玛内部发现叛乱证明，新生部落在与外部敌人作战的同时，也必须提防内部古老的恶魔腐化。"},sec={{t="揭开邪教的面纱",b="应大酋长萨尔的要求，一名特工将从骷髅石夺得的军官的徽章带给了在大断崖公然居住的术士尼鲁·火刃，随后又重创了怒焰裂谷深处的灼热之刃领导层。通过扮演一名自愿加入的邪教徒并带着阵亡邪教徒的徽章，这名特工赢得了火刃的信任，导致这名术士无意中透露了支持他行动的更广泛的网络。"},{t="暗影议会的低语",b="尼鲁·火刃以为自己获得了一名忠诚的副官，他承认怒焰裂谷的损失对灼热之刃来说是一次挫折，但声称暗影议会的宏大计划依然完好无损。他透露他的主子不仅在贫瘠之地有活跃的特工，甚至在更深处的灰谷森林中也有行动。将此消息报告给萨尔令大酋长感到意外，同时也揭示了这场恶魔阴谋早已延伸到了首都地下的隧道之外。"},{t="大酋长的警惕",b="萨尔并没有立即处决尼鲁，而是选择了一条谨慎的道路。让尼鲁在不知不觉中被利用，可以让部落监控他的通信，并追踪该教派在杜隆塔尔、贫瘠之地和灰谷的触角。大酋长指示他的斥候和间谍去调查这些区域分支，因为他意识到铲除恶魔腐化需要精准的手段，而不是鲁莽的急躁。"}},faq={{q="这个任务的目标是什么？",a="你必须从大断崖前往奥格瑞玛的智慧谷，并与大酋长萨尔交谈，汇报尼鲁·火刃关于暗影议会计划所透露的内容。",al={"隐藏的敌人目标","隐藏的敌人任务怎么做","萨尔任务交接"}},{q="为什么尼鲁·火刃信任我？",a="在“隐藏的敌人”任务链中，你从骷髅石的火刃氏族成员身上搜集到了军官的徽章，并以雄心勃勃的教派新人的身份将其呈现给尼鲁，从而让他相信你是忠诚的资产。",al={"为什么尼鲁信任我","欺骗尼鲁","火刃渗透"}},{q="为什么萨尔没有立即逮捕或处决尼鲁·火刃？",a="活着的、被蒙在鼓里的尼鲁比死了更有价值。通过让他以为自己的伪装完好无损，萨尔的斥候就能监控尼鲁的消息，并将他的联系人追溯到卡利姆多各地更大的暗影议会支部。",al={"为什么尼鲁还活着","为什么不杀尼鲁","为什么萨尔留着尼鲁"}},{q="萨尔从这份报告中学到了什么新信息？",a="萨尔得知奥格瑞玛地下的邪教背后有暗影议会撑腰，而且他们的特工正在积极策划在贫瘠之地和灰谷森林中的行动。",al={"萨尔学到了什么","暗影议会灰谷","尼鲁的秘密"}},{q="火刃氏族和灼热之刃是同一个组织吗？",a="灼热之刃是奥格瑞玛地下怒焰裂谷内活动的一个地方性教派，它是更广泛的火刃氏族邪教的一个分支，而火刃氏族则是由暗影议会策划的。",al={"火刃氏族与灼热之刃的区别","怒焰裂谷邪教","邪教差异"}},{q="这个任务链后续还有吗？",a="萨尔会让你去休息，并承诺之后会再次征召你，但目前没有直接延续这一特定卧底渗透路线的任务。",al={"隐藏的敌人后续","隐藏的敌人之后的任务","萨尔接下来派你去哪"}}},fp="14,168,15.385.1,30.384.2,24.354.1,31.173.0,34.166.1,64.190.1,56.150.1,57.162.0,40.127.0"}
P.entries["quest:574"] = {n="特种部队",s="在削减了那位叛变上校的普通士兵后，尤瓦中士请求你以营地里的精英核心为目标。你被派往储藏洞穴消灭突击队员和猎头者，然后向多伦上尉汇报。",h="在削减了那位叛变上校的普通士兵后，尤瓦中士请求你以营地里的精英核心为目标。你被派往储藏洞穴消灭突击队员和猎头者，然后向多伦上尉汇报。",kw={"库尔森突击队员","库尔森营地","库尔森猎头者","多伦上尉","反抗军营地","尤瓦中士","特殊部队","储藏洞穴"},sec={{t="打击储藏洞穴",b="随着第二次反抗军的努力，库尔森营地的正规军数量已大为减少，尤瓦中士将目标对准了上校的精英专家们。她亲身了解许多库尔森的部队，称他们技术精湛、忠诚且残暴。当他们不在荒野中屠杀反抗军士兵时，他们就待在营地后方一个叫作储藏洞穴的地方。为了瓦解他们的力量，你被派往洞穴中除掉十名库尔森突击队员和六名库尔森猎头者。"},{t="向指挥部汇报",b="战斗结束后，尤瓦中士让你向反抗军营地的指挥官多伦上尉汇报，他希望第一时间了解你的战况。"}},faq={{q="是谁下令攻击库尔森的精锐部队的？",a="在协助削弱了库尔森的正规步兵后，位于北荆棘谷反抗军营地的尤瓦中士请求你进行这次突袭。",al={"谁给予特殊部队任务","特殊部队任务发布者","在哪里开始特殊部队"}},{q="库尔森的突击队员和猎头者在哪里？",a="他们位于库尔森营地后方一个叫作储藏洞穴的地方，不过他们也会游荡到荒野中猎杀反抗军。",al={"猎头者在哪里","储藏洞穴在哪里","库尔森突击队员位置"}},{q="清理洞穴后你要向谁汇报？",a="你要向驻扎在反抗军营地的指挥官多伦上尉提交你的第一手报告。",al={"向谁交任务","多伦在哪里","谁完成特殊部队"}},{q="在反抗军战役中，这次突袭之前发生了什么？",a="这项任务是在“第二次反抗军”之后进行的，在那次任务中，你削弱了库尔森上校在营地各处的正规部队。",al={"特殊部队前置任务","什么任务在特殊部队之前"}}},fp="14,256,22.515.0,20.153.0,47.152.0,55.144.0,46.106.0,53.118.0"}
P.entries["quest:5741"] = {n="圣光节杖",s="阿佐尔·奥达蒙特听说东边的雷斧堡垒里的火刃氏族现在拥有光之权杖，据说这东西是从娜迦手中抢来的。传说它能让整座城市沉入大海，阿佐尔绝不允许火刃氏族掌握这种力量。他要求你把它带回艾瑟雷索交给那里的人。",h="阿佐尔·奥达蒙特听说东边的雷斧堡垒里的火刃氏族现在拥有光之权杖，据说这东西是从娜迦手中抢来的。传说它能让整座城市沉入大海，阿佐尔绝不允许火刃氏族掌握这种力量。他要求你把它带回艾瑟雷索交给那里的人。",kw={"阿佐尔·奥达蒙特","火刃氏族","凄凉之地","艾瑟雷索","娜迦","光之权杖","先知","雷斧堡垒"},sec={{t="娜迦的权杖",b="有消息称，娜迦的光之权杖落入了雷斧堡垒的火刃氏族手中。传说它能让整座城市沉入大海。阿佐尔·奥达蒙特认为绝不能让火刃氏族拥有这种力量。"},{t="先知的塔楼",b="一名火刃氏族先知正守着这把权杖，并在堡垒的一座瞭望塔顶端研究它。阿佐尔要你亲自去把它取回来，并带回艾瑟雷索的塔楼。"}},faq={{q="光之权杖拥有什么力量？",a="传说它能让整座城市沉入大海。据说它是火刃氏族从娜迦手中得到的。",al={"光之权杖有什么作用","光之权杖背景故事","光之权杖有多强大"}},{q="谁现在持有光之权杖？",a="一名火刃氏族先知，他把权杖保存在雷斧堡垒的瞭望塔里并对其进行研究。",al={"谁拥有光之权杖","光之权杖在哪里","谁掉落光之权杖"}},{q="谁要求取回光之权杖？",a="艾瑟雷索塔楼的阿佐尔·奥达蒙特。",al={"谁发布光之权杖的任务","去哪里获取光之权杖"}},{q="火刃氏族是如何得到权杖的？",a="据说他们是从娜迦手中获得的。",al={"火刃氏族如何得到权杖","火刃氏族与娜迦的联系"}}},fp="16,330,21.249.0,16.197.0,45.117.0,41.106.0,34.45.0,42.44.0"}
P.entries["quest:575"] = {n="供与求",s="崔斯里克，藏宝海湾的一位制皮师，号称自己是南海最好的制皮师。工匠互助会的里德尔沃克斯主管订购了十二双卓越牌长靴，崔斯里克需要从荆棘谷北部河流旁的鳄鱼身上获取皮革，才能开始制作这些靴子。",h="崔斯里克，藏宝海湾的一位制皮师，号称自己是南海最好的制皮师。工匠互助会的里德尔沃克斯主管订购了十二双卓越牌长靴，崔斯里克需要从荆棘谷北部河流旁的鳄鱼身上获取皮革，才能开始制作这些靴子。",kw={"藏宝海湾","鳄鱼","崔斯里克","卓越","制皮","里德尔沃克斯","荆棘谷","工匠互助会"},sec={{t="来自工匠互助会的订单",b="崔斯里克吹嘘说，他的皮革制品因其精美而闻名遐迩，是行家眼中的首选。最新的订单来自工匠互助会的首席发明家里德尔沃克斯主管，他想要一打他所青睐的卓越牌长靴，这些长靴可是崔斯里克最畅销的产品之一。为了开始制作，崔斯里克需要从荆棘谷北部河流旁的鳄鱼身上获取皮革。设备已经准备就绪，如果让这样一位重要的顾客感到不满，那可不是什么明智之举。"},{t="当皮革送达时",b="崔斯里克认为这些皮革相当不错。它们好不好其实并不重要，因为它们将构成靴子的内层，不过它们必须足够舒适。如果发现皮革太硬，可以用虎血软化，这是业内的一个小窍门。"}},faq={{q="崔斯里克是谁？",a="崔斯里克是藏宝海湾的一位制皮师，他自称是南海乃至更广阔地区最好的制皮师。",al={"崔斯里克 藏宝海湾","藏宝海湾制皮师"}},{q="谁订购了卓越牌长靴？",a="工匠互助会的首席发明家里德尔沃克斯主管订购了十二双卓越牌长靴。",al={"谁订购了靴子","里德尔沃克斯主管","工匠互助会订单"}},{q="去哪里寻找用于此委托的鳄鱼？",a="崔斯里克指明了荆棘谷北部的河流，鳄鱼就栖息在那里。",al={"鳄鱼位置","河流鳄鱼在哪里","我在哪里能找到皮革"}},{q="崔斯里克需要多少张皮革？",a="两张大型鳄鱼皮。",al={"需要多少鳄鱼皮","大型鳄鱼皮"}}},fp="17,277,32.466.0,21.254.1,16.102.0,32.93.0,51.79.0,34.32.0"}
P.entries["quest:576"] = {n="海盗的眼睛",s="在藏宝海湾，老海员独眼迪兹在战斗中失去了视力，只能通过一只特殊的附魔玻璃义眼来看东西。血帆海盗昨晚伏击了他并抢走了这只眼睛，迪兹请求帮忙找回它。",h="在藏宝海湾，老海员独眼迪兹在战斗中失去了视力，只能通过一只特殊的附魔玻璃义眼来看东西。血帆海盗昨晚伏击了他并抢走了这只眼睛，迪兹请求帮忙找回它。",kw={"血帆","藏宝海湾","海盗","迪兹","玻璃义眼","米奈希尔","独眼","荆棘谷"},sec={{t="附魔义眼",b="独眼迪兹在战斗中失去了双眼。幸运的是，迪兹的船停靠在米奈希尔港时，一位路过的法师为他制作了一只特殊的附魔玻璃义眼，让他重获光明。失去了它，迪兹觉得自己毫无用处，并回想起曾经在瞭望台上工作的时光。"},{t="被海盗抢走",b="昨晚，血帆海盗在迪兹外出时伏击了他并抢走了义眼。看来血帆海盗已经混进了藏宝海湾。迪兹担心一旦义眼丢失的消息传出去，船长会对他处以龙骨鞭刑，他觉得一个看不见的瞭望员可能只配去刷舱底。所以，迪兹请求帮忙从血帆海盗手中找回这只义眼。"}},faq={{q="独眼迪兹是谁？",a="独眼迪兹是藏宝海湾的一位老海员，曾担任瞭望员。迪兹在战斗中失去了双眼，只能通过一只附魔玻璃义眼看东西。",al={"独眼迪兹","谁发布了留心观察任务","迪兹是谁"}},{q="迪兹从哪里得到的魔法义眼？",a="迪兹的船停靠在米奈希尔港时，一位路过的法师为他制作了一只特殊的附魔玻璃义眼，让他重获光明。",al={"迪兹如何得到义眼","迪兹附魔义眼的来源","玻璃义眼法师"}},{q="谁抢走了迪兹的义眼？",a="血帆海盗昨晚在迪兹外出时伏击了他，并抢走了义眼。",al={"谁偷走了义眼","谁抢走了迪兹的义眼","谁拿走了迪兹的义眼"}},{q="迪兹担心失去义眼后会发生什么？",a="迪兹担心船长会因此对他处以龙骨鞭刑，他觉得一个看不见的瞭望员可能只配去刷舱底。",al={"如果迪兹失去义眼会怎样","迪兹船长的惩罚"}}},fp="15,225,17.259.0,23.370.0,21.146.0,36.124.0,21.79.0,49.131.0"}
P.entries["quest:5761"] = {n="饥饿者塔拉加曼",s="奥格瑞玛暗影裂口的一位术士，兽人尼鲁·火刃，指引部落的冒险者们深入怒焰裂谷，去猎杀饥饿者塔拉加曼。尼鲁声称这是奉大酋长萨尔的命令，并要求取得这只高大的恶魔卫士的心脏，作为邪教覆灭的证据。",h="奥格瑞玛暗影裂口的一位术士，兽人尼鲁·火刃，指引部落的冒险者们深入怒焰裂谷，去猎杀饥饿者塔拉加曼。尼鲁声称这是奉大酋长萨尔的命令，并要求取得这只高大的恶魔卫士的心脏，作为邪教覆灭的证据。",kw={"cleft of shadow","恶魔卫士","尼鲁·火刃","奥格瑞玛","怒焰裂谷","燃烧之刃","消灭野兽","塔拉加曼"},ang={["class:Warlock"]="在暗影裂口与尼鲁一起行动的术士们，亲眼目睹了在萨尔警惕的目光下修习邪能魔法所需的政治平衡。",["faction:Horde"]="清除在部落首都之下滋生的恶魔，对奥格瑞玛的每一个种族来说，都是事关生死存亡的当务之急。",["race:Orc"]="对于那些努力摆脱恶魔之血诅咒阴影的兽人来说，发现一个恶魔卫士和恶魔邪教竟然就潜伏在萨尔的王座之下，这是一种不可容忍的耻辱。"},sec={{t="城下的威胁",b="在奥格瑞玛红色的土路之下，坐落着怒焰裂谷，这是一道炽热的地下裂隙，里面充斥着穴居人、野兽和燃烧之刃的潜伏特工。在位于上方的暗影裂口，尼鲁·火刃自称是萨尔指派的忠诚仆从，负责清理这些恶魔的腐败。他明确指向怒焰裂谷中心的一位巨大的恶魔卫士——饥饿者塔拉加曼，称其为这个地下邪教的幕后主使。"},{t="术士的欺骗",b="将塔拉加曼的心脏带回给尼鲁·火刃会获得极高的赞誉，并得到萨尔会对此感到满意的承诺。事实上，塔拉加曼并非邪教真正的首领，而仅仅是一个可有可无的蛮兵。尼鲁将部落英雄的注意力引向这只恶魔，是为了给萨尔提供一个显眼的胜利来平息怀疑，同时掩护燃烧之刃真正的领导层，并确保其在奥格瑞玛下的更深层行动不被严密审查。"}},faq={{q="饥饿者塔拉加曼是谁？",a="饥饿者塔拉加曼是一位强大的恶魔卫士，驻扎在怒焰裂谷中心的一块岩石平台上。尼鲁·火刃指称他是盘踞在奥格瑞玛地下的燃烧之刃邪教徒的首领。",al={"谁是塔拉加曼","塔拉加曼是什么","塔拉加曼背景故事"}},{q="是谁发布了“消灭野兽”这个任务？",a="尼鲁·火刃在奥格瑞玛暗影裂口（术士的聚集地）的帐篷中发布此任务。",al={"消灭野兽任务发布者","谁发布了这个任务","尼鲁·火刃任务"}},{q="为什么尼鲁想要塔拉加曼的心脏？",a="尼鲁声称这颗心脏是必须的，以向大酋长萨尔证明奥格瑞玛地下的恶魔威胁已经被消灭了。",al={"为什么要获取心脏","塔拉加曼的心脏用途","为什么尼鲁想要心脏"}},{q="塔拉加曼真的是燃烧之刃的首领吗？",a="尼鲁·火刃称他是他们的首领。塔拉加曼是一个凶猛的恶魔卫士，居住在怒焰裂谷中心的燃烧之刃邪教徒之中。",al={"塔拉加曼是真正的首领吗","谁领导着燃烧之刃","塔拉加曼首领"}},{q="塔拉加曼在哪里？",a="饥饿者塔拉加曼站在怒焰裂谷中层被熔岩环绕的岩石平台上，周围环绕着燃烧之刃邪教徒。",al={"塔拉加曼位置","野兽在哪里","哪里可以找到塔拉加曼"}},{q="这个任务与“隐藏的敌人”有什么联系？",a="在“隐藏的敌人”任务线中，萨尔正在调查暗影议会对奥格瑞玛的渗透，并密切关注着尼鲁·火刃。尼鲁提供这个任务是为了向萨尔展示对抗燃烧之刃的可见成果。",al={"与隐藏的敌人任务的联系","隐藏的敌人任务线","萨尔与尼鲁"}}},fp="17,250,25.425.0,23.392.1,30.186.0,38.115.0,38.122.1,54.145.1,27.131.0,46.219.1"}
P.entries["quest:5762"] = {n="赫米特·奈辛瓦里",s="这项差事将旅行者从卡利姆多的盐碱平原带到了荆棘谷的蒸汽丛林。沙漠赛道的机会主义商人克拉维尔·浓须委托冒险者将一份早已逾期的特种补给品包裹，送交到著名的狩猎大师赫米特·奈辛瓦里手中。",h="这项差事将旅行者从卡利姆多的盐碱平原带到了荆棘谷的蒸汽丛林。沙漠赛道的机会主义商人克拉维尔·浓须委托冒险者将一份早已逾期的特种补给品包裹，送交到著名的狩猎大师赫米特·奈辛瓦里手中。",kw={"弹药","赫米特·奈辛瓦里","克拉维尔·浓须","克拉维尔的箱子","沙漠赛道","闪光平原","荆棘谷"},ang={["class:Hunter"]="将特制弹药直接送到赫米特·奈辛瓦里手中，能让寻踪者们踏入艾泽拉斯最负盛名的大型猎物狩猎活动。",["race:Dwarf"]="在两个狡猾的矮人熟人之间运送定制弹药，展示了铁炉堡的侨民为了追求金钱和猎物会散布到多么遥远的地方。"},sec={{t="跨大陆的快递",b="在闪光平原那刺眼的广袤大地之上，生意往来十分迅速，但货物运输有时会滞后。克拉维尔·浓须最终收到了一份迟到的箱子，收件人是他的一位富有客户：赫米特·奈辛瓦里。赫米特在包裹到达之前就已经离开了千针石林，他提前付了款，要求将包裹转送到他位于荆棘谷的荒野狩猎营地。克拉维尔不想亲自进行这趟艰苦的跋涉，于是招募了愿意跨越大洋的流浪冒险者。"},{t="狩猎弹药",b="在格罗姆高营地北面找到奈辛瓦里远征队营地后，箱子里的物品真相大白：那是用于猎杀丛林中潜伏的危险掠食者所必需的特制大口径弹药。赫米特一眼就认出了信使装备上附着的独特白色盐渍，他很高兴自己与那个狡猾的克拉维尔之间的旧交情，为他的狩猎队提供了急需的火力。"}},faq={{q="这次运输的起点和终点在哪里？",a="运输始于千针石林南部闪光平原沙漠赛道的克拉维尔·浓须。终于世界另一端的荆棘谷北部，位于格罗姆高营地北侧的奈辛瓦里远征队营地。",al={"任务开始与结束","赫米特在哪里","我要去哪里"}},{q="克拉维尔的箱子里装的是什么？",a="箱子里装的是专门为大型猎物枪械定制的特制口径弹药。赫米特·奈辛瓦里订购了这些弹药，用来贯穿荆棘谷最凶猛野兽的厚皮。",al={"箱子里有什么","箱子内容物","克拉维尔的包裹"}},{q="为什么克拉维尔不亲自送货？",a="克拉维尔是一位精明的矮人商人，正忙于在沙漠赛道照看他的投资和计划。他宁愿雇佣路过的冒险者使用奈辛瓦里预付的钱，也不愿放弃自己的岗位去跨越重洋。",al={"为什么克拉维尔要雇人","为什么克拉维尔需要帮助"}},{q="赫米特是怎么知道信使从哪里来的？",a="在收到包裹后，赫米特立即闻到了信使衣服上附着的独特盐层，并辨认出来，他指出这东西直接来自闪光平原，而不是普通的沙漠尘土。",al={"沙漠盐渍","赫米特关于盐的对话"}},{q="克拉维尔和赫米特是什么关系？",a="赫米特是克拉维尔的一位老客户，且出手阔绰。虽然克拉维尔很看重赫米特的深厚财力，但赫米特对克拉维尔的评价则是一个“顽固的老”流氓，永远在搞些歪门邪道。",al={"克拉维尔和赫米特的历史","他们认识吗"}},{q="赫米特·奈辛瓦里是谁？",a="赫米特·奈辛瓦里是一位著名的矮人神射手、作家和狩猎大师，他带领着一支狩猎队在荆棘谷的险境中进行着长期的远征。",al={"谁是赫米特","奈辛瓦里背景故事"}}},fx={["4f3179a4"]={q="为什么克拉维尔·浓须要把这箱货物送给Hemet？",a="克拉维尔要维持一笔利润丰厚的生意。Hemet Nesingwary是一位极其富有的矮人，克拉维尔知道，让这样富裕的客户满意会带来丰厚回报。Hemet已预先付钱，要求货箱抵达后转运到他的狩猎营地，因此履行约定既能维护克拉维尔的声誉，也能保证日后继续赚钱。",al={"为什么要送克拉维尔的货箱","克拉维尔·浓须的动机","为什么要把货箱送给hemet"}}},fp="16,316,27.507.0,23.417.0,39.265.0,30.179.0,44.241.0,48.209.0,51.178.0,24.157.0"}
P.entries["quest:5763"] = {n="荆棘谷狩猎",s="鲁恩·蛮鬃，凄凉之地的牛头人，曾与一名叫赫米特的矮人一同狩猎。现在鲁恩交给你一只科多兽角，让你前往荆棘谷，去寻找格罗姆高营地北部的赫米特·奈辛瓦里。",h="鲁恩·蛮鬃，凄凉之地的牛头人，曾与一名叫赫米特的矮人一同狩猎。现在鲁恩交给你一只科多兽角，让你前往荆棘谷，去寻找格罗姆高营地北部的赫米特·奈辛瓦里。",kw={"凄凉之地","格罗姆高","赫米特·奈辛瓦里","科多兽角","鲁恩·蛮鬃","荆棘谷"},sec={{t="猎人之间的信物",b="很久以前，一名叫赫米特的矮人来到凄凉之地，渴望猎杀大型野兽。赫米特的枪法出神入化，两位猎人在一起度过了许多日子，他们种族间古老的仇恨被抛之脑后。当赫米特前往荆棘谷时，鲁恩发誓总有一天会欢迎赫米特回来再次进行狩猎，而鲁恩认为时机已到。你要将鲁恩的科多兽角带给赫米特，他一眼就能认出这是谁的东西。去荆棘谷，在格罗姆高营地以北寻找他。"},{t="赫米特的回答",b="赫米特立刻认出这只角是属于牛头人鲁恩·蛮鬃的，并回想起他们在凄凉之地的野兽群中共同狩猎的美好时光。赫米特现在正深陷丛林之中，但他感谢你，并认为下一次远征可能会回到半人马居住的凄凉之地。"}},faq={{q="赫米特是谁？",a="一名来到凄凉之地渴望猎杀大型野兽的矮人。赫米特的枪法出神入化，在前往荆棘谷之前，赫米特和鲁恩·蛮鬃曾在一起狩猎多日。",al={"赫米特·奈辛瓦里","赫米特是谁"}},{q="为什么鲁恩·蛮鬃会在意一个矮人？",a="他们曾在一起狩猎多日，他们种族间的仇恨已被遗忘。鲁恩发誓要欢迎赫米特回来，这样他们就能再次一同狩猎。",al={"为什么要帮助矮人","鲁恩·蛮鬃的矮人朋友"}},{q="赫米特在哪里？",a="在荆棘谷，格罗姆高营地以北。",al={"赫米特在哪里","赫米特的位置","荆棘谷狩猎营地"}},{q="科多兽角有什么用？",a="鲁恩·蛮鬃把它送给赫米特，赫米特就会知道这是鲁恩送来的。",al={"科多兽角的用途","为什么要递送科多兽角"}}},fp="24,191,23.471.0,14.272.1,13.186.0,42.149.0,23.46.0,37.63.0"}
P.entries["quest:577"] = {n="收集鳄鱼皮",s="在藏宝海湾，崔斯里克报告说靴子已经初具雏形，但你提供的皮革无法覆盖内层。崔斯里克建议用纳菲瑞提湖附近鳄鱼身上更便宜、更厚的皮来填充。",h="在藏宝海湾，崔斯里克报告说靴子已经初具雏形，但你提供的皮革无法覆盖内层。崔斯里克建议用纳菲瑞提湖附近鳄鱼身上更便宜、更厚的皮来填充。",kw={"靴子","藏宝海湾","鳄鱼","崔斯里克","纳菲瑞提湖","快咬鳄鱼","荆棘谷"},sec={{t="填满靴子",b="崔斯里克已经确定了靴子的粗略形状，并表示制作进展顺利，但《供需关系》任务中提供的皮革不足以覆盖靴子内部。反正没人会看到那些内层，所以崔斯里克打算用纳菲瑞提湖附近鳄鱼身上更厚、更便宜的皮来凑合。"},{t="销售说辞",b="崔斯里克的销售说辞承诺了最精湛的工艺，以及纯正、顶级咸水鳄鱼皮制成的靴子。崔斯里克将这些靴子比作香肠：看起来很棒，尝起来很棒，据说里面只包含最好的配料。信任制造者而不去深究里面到底是什么，会更安全，也更让人愉快。"}},faq={{q="谁需要这些皮革？",a="藏宝海湾的崔斯里克，他正在制作Excelsior靴子，在交付了《供需关系》中的皮革后，他还需要更多的皮革。",al={"任务发布者","谁发布了组装需求","崔斯里克位置"}},{q="崔斯里克需要什么皮革？",a="五张快咬鳄鱼皮。",al={"我需要什么皮革","鳄鱼皮类型","哪种鳄鱼"}},{q="在哪里可以找到所需的鳄鱼？",a="崔斯里克让你去寻找纳菲瑞提湖周围的鳄鱼。",al={"纳菲瑞提湖位置","快咬鳄鱼在哪里","去哪找鳄鱼"}},{q="为什么崔斯里克想要更便宜的皮革？",a="靴子的内层不为人所见，所以崔斯里克很乐意用更厚、更便宜的皮来填充它们。",al={"为什么用更便宜的皮","为什么用快咬鳄鱼皮","靴子填充物"}}},fp="22,223,17.291.0,15.341.1,30.125.0,30.29.0,40.59.0,37.119.0"}
P.entries["quest:578"] = {n="海潮之石",s="由于有传言称丛林海岸外的一座岛屿闹鬼，大财主里维加兹怀疑是一件古老的巨魔圣物重现世间。他指示探险者前往勘察这片神秘的陆地，并提供了一份通行证，以便在暴风城的档案馆中研究这件文物。",h="由于有传言称丛林海岸外的一座岛屿闹鬼，大财主里维加兹怀疑是一件古老的巨魔圣物重现世间。他指示探险者前往勘察这片神秘的陆地，并提供了一份通行证，以便在暴风城的档案馆中研究这件文物。",kw={"大财主里维加兹","藏宝海湾","丹亚·托瓦尔德","加兹班","古拉巴什","海潮之石","暴风城图书馆","荆棘谷"},sec={{t="大财主的野心",b="在得知荆棘谷附近的一座离岛上出现了奇怪的幻象和水元素后，大财主里维加兹看到了一个机会。他怀疑地精法师加兹班可能发现了传说中的海潮之石，于是这位藏宝海湾的统治者派你去找到那座岛屿，查明传言是否属实。为了满足对这件圣物的好奇心，他提供了一份可以在暴风城的学者中间兑换的图书馆手稿。"},{t="古老的结界",b="证实了岛上存在超自然现象，也就证实了大财主最大的期望：这件传说中的文物是真实存在的。然而，想要获取它并非易事。海潮之石上附带着一种强大的魔法诅咒，里维加兹意识到单凭自己无法破解，在开始回收工作之前，他需要一位经验丰富的法师的专业知识。"}},faq={{q="谁让你去寻找那座闹鬼的岛屿？",a="藏宝海湾的领袖大财主里维加兹在听闻海岸外的奇怪活动传言后派你前往。",al={"谁给予任务","海潮之石任务给予者","谁派你去的"}},{q="闹鬼的岛屿位于何处？",a="这座岛屿位于荆棘谷的海岸外，你需要自行寻找这片海域中的岛屿。",al={"岛屿在哪里","岛屿位置","寻找闹鬼的岛屿"}},{q="海潮之石是什么？",a="这是一件传说中的巨魔文物，里维加兹希望能将其收入自己的收藏品中，这个传说他最初是在一本古书中看到的。",al={"海潮之石是什么","海潮之石背景故事","海潮之石简介"}},{q="为什么大财主里维加兹想要这件文物？",a="这位大财主想要夺取这件强大的巨魔圣物，将其加入他丰富的古代文物和遗迹收藏中。",al={"为什么里维加兹想要它","里维加兹的动机"}},{q="图书馆手稿有什么用途？",a="这份手稿可以交给暴风城图书馆的丹亚·托瓦尔德，以获取大财主最初阅读到相关传说的那本书的副本。",al={"什么是图书馆手稿","暴风城图书馆手稿","去哪里提交手稿"}},{q="这个任务链的上一步是什么？",a="这次调查直接承接“闹鬼的岛屿”，正是该任务首次将这些异常现象的消息带给了大财主。",al={"前置任务是什么","前置任务"}}},fp="22,253,20.443.0,15.331.1,42.101.0,36.110.0,31.124.0,42.120.0,35.140.0,41.117.0"}
P.entries["quest:579"] = {n="暴风城图书馆",s="在Stormwind Keep的Royal Library深处，图书管理员Donyal Tovald管理着一系列历史文献和地区记录。遵照安度因·乌瑞恩国王的旨意，王国拨出专款，为携带官方Library Scrip的公民和学者誊抄这些文献的副本。这项服务让探险者能够第一手研究艾泽拉斯的历史、阵营和传奇故事。",h="在Stormwind Keep的Royal Library深处，图书管理员Donyal Tovald管理着一系列历史文献和地区记录。遵照安度因·乌瑞恩国王的旨意，王国拨出专款，为携带官方Library...",kw={"安度因·乌瑞恩国王","书籍","丹亚·托瓦尔德","图书馆手稿","知识卷轴","stormwind keep","暴风城图书馆","誊抄"},ang={["class:Mage"]="对于奥术修行者来说，Royal Library代表了王国中一个重要的世俗档案库，保存了与Mage Quarter进行的奥术研究相辅相成的非魔法历史记录。",["faction:Alliance"]="图书馆保存了洛丹伦联盟共同的胜利与悲剧，提醒着公民们人类、矮人、侏儒和高等精灵之间历史上的纽带。",["race:Human"]="由于在第一次战争中旧暴风城被洗劫时丢失了无数档案，人类学者非常珍视保存和复制在王国重建后幸存下来的任何历史记录。"},sec={{t="皇家知识法令",b="当伯瓦尔·弗塔根公爵和女伯爵卡特拉娜·普瑞斯托在瓦里安国王缺席期间负责处理防御和宫廷政治时，年轻的安度因国王将王室资源用于教育。安度因认识到了解历史对王国未来至关重要，因此资助了古代手稿和历史日志的誊抄工作。Royal Library坐落在Stormwind Keep的大厅中，它不仅仅是国家机密的皇家宝库，更是为那些为王室服务的人保存和复制记载文献的场所。"},{t="手稿交换",b="手工誊抄脆弱的羊皮纸需要大量的时间、墨水和皇家批准。为了管理这种分发，图书管理员Donyal Tovald会接收发给联盟各地探险者和学者的官方Library Scrip。作为交换，Tovald会提供历史书籍的忠实副本，内容涵盖从东部王国的古老历史到遥远之地的记述，为首都城墙之外正在进行的冲突提供背景信息。"}},faq={{q="Stormwind Library任务的目的是什么？",a="这个任务允许你向图书管理员Donyal Tovald上交Library Scrip，以换取可阅读的知识书籍。它提供了关于整个艾泽拉斯各个联盟故事线、人物和地区的背景历史。",al={"这个任务有什么用","暴风城图书馆任务目的","为什么要完成这个任务"}},{q="Donyal Tovald是谁？",a="Donyal Tovald是负责监管Stormwind Keep内Royal Library的图书管理员。他管理着王国的书面历史收藏，并执行安度因国王的指示，向有资格的学者和探险者分发副本。",al={"donyal tovald是谁","暴风城图书管理员","谁提供书籍"}},{q="从哪里可以获得Library Scrip？",a="Library Scrip是通过在联盟领地处理涉及学者、法官或官员的具体任务时获得的，他们会奖励那些对广阔世界进行研究和保持好奇心的人。",al={"哪里可以获得图书馆手稿","如何获得图书馆手稿","图书馆手稿来源"}},{q="为什么年轻的安度因国王要资助图书馆？",a="安度因·乌瑞恩国王非常看重学习和教育。即使在年幼时期，在摄政王Bolvar Fordragon的指导下执政时，他也拨出皇家资金，使王国的历史书籍副本能够公开供大众查阅。",al={"为什么安度因关心书籍","安度因图书馆资助","安度因国王书籍"}},{q="图书馆在暴风城的什么位置？",a="Royal Library位于占据城市东部的宏伟要塞Stormwind Keep内。你可以在里面的高大书架和阅读桌旁找到Donyal Tovald。",al={"暴风城图书馆在哪里","皇家图书馆位置","donyal tovald在哪里"}},{q="我能阅读收到的书籍吗？",a="可以。从图书馆收到的每一本书都是游戏内可阅读的物品，提供了关于魔兽世界中各种传奇和历史事件的风味文本、叙事背景和语境。",al={"书籍可以阅读吗","你能打开书吗","书有什么作用"}}},fp="17,220,29.410.0,18.372.0,51.165.0,21.156.0,36.134.0,45.240.0,42.160.0,31.114.0"}
P.entries["quest:58"] = {n="守夜人",s="这是指挥官阿尔泰娅·埃伯洛克发布的最后一个任务，引导联盟的冒险者前往乌鸦岭墓地东部的地下墓穴。由于守夜人兵力捉襟见肘，只能勉强防守夜色镇，因此必须由外来的冒险者进入墓穴，消灭那些成群结队的瘟疫传播者。这标志着镇卫队为遏制亡灵泛滥而发起的直接军事行动达到了高潮。",h="这是指挥官阿尔泰娅·埃伯洛克发布的最后一个任务，引导联盟的冒险者前往乌鸦岭墓地东部的地下墓穴。由于守夜人兵力捉襟见肘，只能勉强防守夜色镇，因此必须由外来的冒险者进入墓穴，消灭那些成群结队的瘟疫传播者。这标志着镇卫队为遏制...",kw={"althea ebonlocke","夜色镇","暮色森林","食尸鬼","陵墓","守夜人","瘟疫传播者","乌鸦岭","亡灵"},ang={["class:Paladin"]="乌鸦岭那布满瘟疫的墓穴是对神圣安葬仪式的亵渎，因此，圣光的仆从们必须将其清扫干净。",["class:Priest"]="东部陵墓中的食尸鬼散布着邪恶的传染病，这是对圣光神圣性的挑战，必须进行精神上和肉体上的双重净化。",["faction:Alliance"]="暴风城的皇室对暮色森林的求援置若罔闻，联盟的勇士们必须挺身而出，拯救忠诚的公民免遭亡灵的蹂躏。"},sec={{t="绝望的前线",b="夜色镇几乎完全处于孤立无援的状态，暴风城的军队早已撤走，只能完全依靠本地的平民民兵——守夜人来维持治安。指挥官阿尔泰娅·埃伯洛克手中有限的兵力仅够守卫十字路口、城镇周边和补给线，这早已让她精疲力竭。随着暮色森林各处的亡灵不断增加，指挥官别无选择，只能招募往来的勇士，深入乌鸦岭阴暗的角落展开战斗。"},{t="肃清陵墓",b="乌鸦岭墓地的东部陵墓是该地区亡灵最为猖獗、危险程度最高的地方之一。与外面的露天墓穴不同，这座石制地下墓穴中挤满了瘟疫传播者——这些食尸鬼携带着腐蚀性的疾病，足以让生者染病。消灭二十只这种憎恶生物能为疲惫不堪的守夜人争取宝贵的喘息之机，确保夜色镇不会遭到来自西方的亡灵联军突袭。"}},faq={{q="为什么守夜人派冒险者去，而不是他们自己人？",a="守夜人的兵力在整个暮色森林分散得太薄了。暴风城没有提供任何正规军，指挥官阿尔泰娅·埃伯洛克仅有的守卫勉强维持着夜色镇的防御和道路巡逻，根本抽不出人手来清理像乌鸦岭这样深处且防御严密的地下墓穴。",al={"为什么要帮助夜色镇","为什么守夜人需要帮助","守夜人兵力不足"}},{q="东部陵墓在哪里？",a="它位于乌鸦岭墓地的东部，坐落在暮色森林的西北方。入口通往地下的石制墓穴，那里聚集着大量的瘟疫传播者。",al={"瘟疫传播者在哪里","东部陵墓的位置","陵墓在哪里"}},{q="为什么瘟疫传播者很危险？",a="瘟疫传播者是贪婪的食尸鬼，携带着致命的腐烂病菌。如果不加以控制，这种恶臭的瘟疫可能会蔓延到墓地之外，污染夜色镇的幸存居民。",al={"为什么要杀死瘟疫传播者","什么是瘟疫传播者"}},{q="指挥官阿尔泰娅·埃伯洛克是谁？",a="阿尔泰娅·埃伯洛克是守夜人的指挥官和领袖，也是夜色镇镇长艾尔罗·埃伯洛克公爵的亲戚。她负责在夜色镇内部组织暮色森林的防御工作。",al={"阿尔泰娅是谁","埃伯洛克指挥官","谁领导着守夜人"}},{q="完成这个系列任务能终结暮色森林的亡灵威胁吗？",a="不能。虽然清理陵墓缓解了夜色镇眼前的压力，但乌鸦岭依然被亡灵彻底侵占，且暮色森林各地更黑暗的力量仍在不断唤醒死者。",al={"乌鸦岭安全了吗","夜色镇现在安全吗"}},{q="这在守夜人任务线中处于什么位置？",a="这是指挥官埃伯洛克直接发布的“守夜人”军事系列任务中的第三章，也是最后一章。任务从开阔的道路转向墓地外围，最终深入陵墓内部。",al={"这是什么系列任务","这是最后一个守夜人任务吗"}}},fx={f0d896f3={q="为什么指挥官阿尔泰娅·埃伯洛克要完成这件事？",al={"为什么要杀死瘟疫散播者","埃伯洛克在暮色森林的动机","为什么又派我去乌鸦岭"}},["0678b7f2"]={q="陵墓中的瘟疫散播者是什么？",a="瘟疫散播者是徘徊在乌鸦岭墓地被亵渎的坟墓中的腐烂复生尸体。它们浑身充斥着邪恶的疫病与腐烂气息，潜伏在东部陵墓深处，亵渎暮色森林死者的坟墓，并威胁要把污秽传遍森林。它们逗留不去，使古老墓地成为亡灵力量源源不绝的温床。",al={"瘟疫散播者是什么","暮色森林的瘟疫散播者","东部陵墓中的亡灵"}}},fp="15,358,20.458.0,21.438.0,68.281.0,39.175.0,42.187.0,34.190.0,61.180.0,49.193.0"}
P.entries["quest:580"] = {n="威士忌斯利姆的酒",s="在海盗避风港藏宝海湾，威士忌斯利姆发现自己与船长之间出了大麻烦。在辛特兰海岸外一场猛烈的风暴中，斯利姆偷喝了一箱缴获的紫葡萄酒，结果却把酒瓶弄丢进了波涛汹涌的大海里。为了逃避残酷的鞭刑，他需要一位冒险者帮他找回这些遗失的烈酒。",h="在海盗避风港藏宝海湾，威士忌斯利姆发现自己与船长之间出了大麻烦。在辛特兰海岸外一场猛烈的风暴中，斯利姆偷喝了一箱缴获的紫葡萄酒，结果却把酒瓶弄丢进了波涛汹涌的大海里。为了逃避残酷的鞭刑，他需要一位冒险者帮他找回这些遗失的...",kw={"藏宝海湾","烈酒","辛特兰","眺望台悬崖","私掠者","紫葡萄酒","暴风城","威士忌斯利姆"},sec={{t="辛特兰外的风暴",b="当威士忌斯利姆的船员在眺望台悬崖外遭遇恶劣天气，且辛特兰的海岸近在咫尺时，这位水手寻求了一点“液态勇气”。他的船刚刚从一艘驶向暴风城的私掠船上缴获了一箱紫葡萄酒。面对仿佛要将整艘船吞没的巨浪，斯利姆撬开了船长的箱子，但一阵突如其来的涌浪将酒瓶卷下了船舷。"},{t="水手的绝望",b="回到藏宝海湾，随着船只准备起航，时间一分一秒地流逝。斯利姆非常担心一旦指挥官发现缴获的紫葡萄酒不见了，自己会遭受九尾鞭的惩罚。他正在寻找愿意帮他在偷窃行径败露前找回十二瓶酒的人。"}},faq={{q="威士忌斯利姆是谁？",a="威士忌斯利姆是居住在藏宝海湾的一名水手，因为在海上风暴中弄丢了船长失窃的酒，他现在陷入了大麻烦。",al={"威士忌斯利姆","谁提供遗失烈酒任务","谁是斯利姆"}},{q="烈酒是从哪里来的？",a="这箱紫葡萄酒是斯利姆的船员从一艘正驶往暴风城的私掠船上强行夺取的。",al={"紫葡萄酒来源","斯利姆从哪里得到的烈酒","私掠船酒水"}},{q="威士忌斯利姆在哪里弄丢了酒瓶？",a="在眺望台悬崖外，靠近辛特兰海岸的地方，当巨浪袭击船只时，斯利姆不慎将酒瓶丢进了海里。",al={"烈酒在哪里遗失","眺望台悬崖风暴","辛特兰烈酒位置"}},{q="为什么威士忌斯利姆需要尽快找回酒瓶？",a="他的船即将离港，一旦船长发现紫葡萄酒丢失，斯利姆担心自己会遭受九尾鞭的惩罚。",al={"为什么要帮助斯利姆","斯利姆会遭遇什么","鞭刑"}}},fp="24,336,29.424.0,22.280.0,20.140.0,29.121.0,40.150.0,55.159.0"}
P.entries["quest:5801"] = {n="火羽山",s="克林科·古德斯迪尔指引你去往安戈洛环形山西部的火羽山，那是一座闷烧的火山，山顶的熔岩湖温度极高，足以锻造骷髅钥匙的钥匙柄。之后，你需要把它带给西瘟疫之地冰风岗的化学家阿尔比顿。",h="克林科·古德斯迪尔指引你去往安戈洛环形山西部的火羽山，那是一座闷烧的火山，山顶的熔岩湖温度极高，足以锻造骷髅钥匙的钥匙柄。之后，你需要把它带给西瘟疫之地冰风岗的化学家阿尔比顿。",kw={"化学家阿尔比顿","冰风岗","火羽山","克林科·古德斯迪尔","骷髅钥匙模具","瑟银","安戈洛环形山","未完工的骷髅钥匙"},sec={{t="钥匙柄之火",b="锻造钥匙柄需要两块瑟银锭和极高的热量。瑟银锭需要你自己去寻找，但克林科·古德斯迪尔可以帮你解决热量的问题。你的金币已经买到了模具，只需要把它浸入火羽山顶部的熔岩湖中即可。熔岩会完成剩下的工作，将瑟银和骨头融合在一起。"},{t="回到阿尔比顿身边",b="克林科·古德斯迪尔已经完成了他的任务。为了完成这把钥匙，你需要再次前往西瘟疫之地的冰风岗与化学家阿尔比顿交谈。从熔岩中取出的钥匙还未完工，目前的工作只是为了后续的进攻做准备。"},{t="前方的挑战",b="阿尔比顿称这把钥匙造价不菲，但它仍然没有完工。所有这些工作所针对的敌人就在Andorhal：召唤者阿拉基，他是一位在天灾军团中地位极高的巫妖。"}},faq={{q="钥匙柄在哪里锻造？",a="在安戈洛环形山西部、克林科·古德斯迪尔所在位置西侧的一座闷烧火山——火羽山顶部的熔岩湖中。",al={"钥匙锻造地点","火羽山锻造位置","熔岩湖位置"}},{q="锻造钥匙柄需要什么？",a="骷髅钥匙模具和两块瑟银锭。瑟银锭需要你自己去寻找。",al={"我需要什么材料","钥匙材料","瑟银需求"}},{q="谁会接收这把未完工的钥匙？",a="西瘟疫之地冰风岗的化学家阿尔比顿。",al={"我该把这个交给谁","阿尔比顿位置","未完工的钥匙交给谁"}}},fp="17,268,21.304.0,17.249.0,15.202.1,29.110.0,37.78.0,32.67.0"}
P.entries["quest:5802"] = {n="火羽山",s="克林科·古德斯迪尔指引你去安戈洛环形山西部的火羽山，那是一座冒着热气的火山，山顶的熔岩湖温度足以铸造骷髅钥匙的柄。之后，你需要把它带给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",h="克林科·古德斯迪尔指引你去安戈洛环形山西部的火羽山，那是一座冒着热气的火山，山顶的熔岩湖温度足以铸造骷髅钥匙的柄。之后，你需要把它带给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",kw={"andorhal","药剂师迪瑟斯","亡灵壁垒","火羽山","克林科·古德斯迪尔","骷髅钥匙模具","瑟银锭","安戈洛环形山","未完成的骷髅钥匙"},sec={{t="钥匙柄的火焰",b="铸造钥匙柄需要两根瑟银锭和极高的温度。瑟银需要你自己去寻找，但克林科·古德斯迪尔可以提供高温方面的帮助。你付出的金币买到了一个模具，只需要把它浸入火羽山顶的熔岩湖中即可。熔岩会完成剩下的工序，将瑟银和骨头融合在一起。"},{t="回到迪瑟斯那里",b="克林科·古德斯迪尔已经完成了他的工作。要完成这把钥匙，你需要再次与西瘟疫之地亡灵壁垒的药剂师迪瑟斯交谈。从熔岩中取出的钥匙尚未完工，目前的工作只是在为突袭做准备。"},{t="前方有何凶险",b="迪瑟斯说这把钥匙代价高昂，但目前仍未完工。所有这些努力所针对的敌人都在Andorhal：召唤者阿拉基，他是天灾军团中最强大的巫妖之一。"}},faq={{q="钥匙柄在哪里铸造？",a="在火羽山顶的熔岩湖，那是安戈洛环形山的一座冒着热气的火山，位于克林科·古德斯迪尔的西面。",al={"钥匙在哪里铸造","熔岩湖位置","火羽山熔岩"}},{q="铸造钥匙柄需要什么？",a="骷髅钥匙模具和两根瑟银锭。瑟银需要你自己去寻找。",al={"我需要什么","钥匙材料","需要的瑟银"}},{q="谁来接收未完成的钥匙？",a="西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",al={"找谁交任务","钥匙交给谁","交钥匙"}}},fp="17,263,21.304.0,15.244.0,15.200.1,29.110.0,37.78.0,32.62.0"}
P.entries["quest:581"] = {n="耶尼库的下落",s="尼姆布亚从奥格瑞玛回到了荆棘谷的丛林，寻找他的酋长最小的儿子耶尼库。这位侦察兵怀疑血顶部落囚禁了这个年轻人，他请求你去猎杀他们的战士并带回獠牙，以证明你的实力。",h="尼姆布亚从奥格瑞玛回到了荆棘谷的丛林，寻找他的酋长最小的儿子耶尼库。这位侦察兵怀疑血顶部落囚禁了这个年轻人，他请求你去猎杀他们的战士并带回獠牙，以证明你的实力。",kw={"血顶","暗矛","格罗姆高","寻找耶尼库","尼姆布亚","荆棘谷","獠牙","耶尼库","祖尔格拉布"},ang={["faction:Horde"]="尼姆布亚直接受命于奥格瑞玛，他依靠格罗姆高营地的部落盟友来帮助营救暗矛酋长的亲人。",["race:Troll"]="对于暗矛巨魔来说，响应尼姆布亚的号召意味着帮助他们自己的酋长家庭，并猎杀可能囚禁着耶尼库的血顶巨魔。"},sec={{t="酋长失踪的儿子",b="在格罗姆高营地，尼姆布亚谈到了暗矛巨魔酋长最小的儿子耶尼库所面临的严峻命运。按照古老的部落习俗，这个男孩曾被送往祖尔格拉布的古拉巴什巨魔那里。当暗矛部族跟随兽人酋长萨尔离开家园时，耶尼库被留在了那里并失踪了。尼姆布亚被从遥远的奥格瑞玛派回，承担起了寻找酋长之子并将其安全带回的责任。"},{t="猎杀血顶巨魔",b="尼姆布亚相信耶尼库现在被血顶部落扣押。他要求冒险者证明自己有足够的实力去猎杀他们。你被派往北方猎杀血顶巨魔并收集九根獠牙。将这些战利品带回格罗姆高营地将证明你的武勇，并开启寻找酋长之子的漫长任务，直接通往名为“猎头者”的狩猎行动。"}},faq={{q="耶尼库是谁？",a="耶尼库是暗矛部族酋长最小的儿子。按照部落习俗，他被送往祖尔格拉布的古拉巴什巨魔那里，但在暗矛部族离开该地区时，他与族人失散了。",al={"耶尼库背景故事","耶尼库是谁","酋长之子"}},{q="为什么耶尼库被留在了荆棘谷？",a="按照部落习俗，耶尼库被送往祖尔格拉布的古拉巴什巨魔那里。当暗矛部族与萨尔结盟并离开时，这个年轻人就被他们遗失了。",al={"耶尼库为何留下","耶尼库如何失踪","为何祖尔格拉布"}},{q="尼姆布亚是谁？",a="尼姆布亚是一位驻扎在格罗姆高营地的暗矛巨魔。他被从遥远的奥格瑞玛派回荆棘谷，寻找他酋长失踪的儿子。",al={"谁发布了寻找耶尼库的任务","尼姆布亚","格罗姆高侦察兵"}},{q="为什么要收集血顶巨魔的獠牙？",a="尼姆布亚怀疑血顶部落抓走了耶尼库。他需要九根血顶巨魔的獠牙作为证明，以确认你有足够的实力去猎杀这些敌对的巨魔，然后再继续寻找。",al={"血顶獠牙的用途","为何要獠牙","寻找耶尼库獠牙"}},{q="血顶巨魔在哪里？",a="尼姆布亚指引猎人前往格罗姆高营地以北的领地寻找血顶部落。",al={"去哪里找血顶巨魔","血顶巨魔位置","血顶巨魔在哪里"}}},fp="16,280,22.478.0,23.395.0,15.209.0,45.154.0,15.169.0,44.188.0,40.109.0"}
P.entries["quest:582"] = {n="猎头行动",s="格罗姆高营地的尼姆布亚需要确定暗矛酋长的儿子耶尼库是否已经遇害。冒险者们被要求去猎杀血顶猎头者并收缴他们的缩颅，以便尼姆布亚进行检查。",h="格罗姆高营地的尼姆布亚需要确定暗矛酋长的儿子耶尼库是否已经遇害。冒险者们被要求去猎杀血顶猎头者并收缴他们的缩颅，以便尼姆布亚进行检查。",kw={"血顶","加祖拉","格罗姆高营地","猎头行动","尼姆布亚","缩颅","耶尼库","祖尔昆达","祖尔达亚"},ang={["faction:Horde"]="部落军队以格罗姆高营地为基地，协助他们的暗矛盟友查明酋长失踪的儿子是否还活着。",["race:Troll"]="酋长儿子的命运对暗矛部族来说事关重大，他们必须面对血顶部族来了解究竟发生了什么。"},sec={{t="搜寻战利品",b="在“寻找耶尼库”的任务开始搜寻之后，尼姆布亚担心酋长的儿子可能已经死在了血顶巨魔的手中。为了查明真相，他要求你去猎杀游荡在北方海岸祖尔达亚和祖尔昆达废墟中的血顶猎头者。通过从他们身上收集二十个缩颅，尼姆布亚希望能通过检查这些可怕的战利品来确认耶尼库是否遭遇了不幸，如果这名年轻人确实被杀害，他将诅咒血顶酋长加祖拉。"}},faq={{q="谁在寻找耶尼库？",a="格罗姆高营地的尼姆布亚正在寻找耶尼库，他是暗矛部族酋长的儿子。",al={"谁发布了猎头行动","尼姆布亚的目的","为什么要寻找耶尼库"}},{q="为什么尼姆布亚想要缩颅？",a="尼姆布亚计划检查从血顶猎头者身上获取的缩颅，以核实耶尼库的头颅是否在他们的战利品之中。",al={"为什么要收集缩颅","缩颅的用途","尼姆布亚用这些头颅做什么"}},{q="在哪里可以找到血顶猎头者？",a="血顶猎头者聚集在荆棘谷的北海岸，特别是祖尔达亚和祖尔昆达的废墟周围。",al={"猎头者的位置","祖尔达亚和祖尔昆达在哪里","去哪里寻找缩颅"}},{q="文中提到的血顶部族由谁领导？",a="血顶部族由酋长加祖拉领导，如果耶尼库确实死了，尼姆布亚希望能对其灵魂施加六百年的诅咒。",al={"血顶酋长","加祖拉是谁","酋长加祖拉"}}},fp="11,225,22.487.0,27.106.0,37.135.0,46.134.0,46.125.0"}
P.entries["quest:5821"] = {n="雇佣保镖",s="考克·基泽尔顿和里格原本会带着他们的科多兽经过科尔卡半人马村，但每当听到半人马的战鼓声时，他们就会停下来。考克请求你护送商队穿过科尔卡村，酬劳会在前方不远处的瑟卡布斯库的营地由斯米德·瑟卡布斯库支付。",h="考克·基泽尔顿和里格原本会带着他们的科多兽经过科尔卡半人马村，但每当听到半人马的战鼓声时，他们就会停下来。考克请求你护送商队穿过科尔卡村，酬劳会在前方不远处的瑟卡布斯库的营地由斯米德·瑟卡布斯库支付。",kw={"保镖","半人马","考克·基泽尔顿","凄凉之地","基泽尔顿商队","科尔卡","里格","斯米德·瑟卡布斯库"},sec={{t="战鼓",b="考克·基泽尔顿和里格原本会直接带着他们的科多兽经过科尔卡半人马的地盘。偶尔半人马的战鼓声响起，商队就会停下来，因为死掉的商人是赚不到钱的。考克请求你护送商队穿过科尔卡村，虽然距离不长，但请务必让商队完整无损。商队正等在科尔卡村的北面，雷斧堡垒的东南方。"},{t="斯米德·瑟卡布斯库",b="酬劳在前方不远处的瑟卡布斯库的营地由斯米德·瑟卡布斯库支付。斯米德和基泽尔顿商队做些小生意。"}},faq={{q="谁是考克·基泽尔顿？",a="考克·基泽尔顿与里格一起带领着一支科多兽商队穿过凄凉之地。每当半人马的战鼓声响起，他们就会停下来。",al={"考克·基泽尔顿","谁发布了雇佣保镖任务","谁开启此任务"}},{q="为什么商队需要护送？",a="考克和里格每当听到半人马的战鼓声就会停下来，因为死掉的商人是赚不到钱的。",al={"为什么要雇佣保镖","为什么商队停下了","他们为什么要等待"}},{q="这次护送任务从哪里开始？",a="科尔卡村的北面，以及雷斧堡垒的东南方。",al={"雇佣保镖任务地点","商队从哪里出发","护送起始点"}},{q="报酬在哪里领取？",a="在前方不远处的瑟卡布斯库的营地，由斯米德·瑟卡布斯库发放。斯米德和考克做些小生意。",al={"谁给奖励","在哪里交任务","斯米德是谁"}}},fp="18,276,9.384.0,19.140.0,21.132.0,37.95.0,29.67.0,29.110.0"}
P.entries["quest:583"] = {n="欢迎来到丛林",s="巴尼尔·石罐欢迎来到荆棘谷北部狩猎营地的新手。他看出你是一位久经沙场的流浪者，于是为你引荐了探险队的领袖，著名猎人赫米特·奈辛瓦里。",h="巴尼尔·石罐欢迎来到荆棘谷北部狩猎营地的新手。他看出你是一位久经沙场的流浪者，于是为你引荐了探险队的领袖，著名猎人赫米特·奈辛瓦里。",kw={"巴尼尔","赫米特","奈辛瓦里","豹","迅猛龙","石罐","荆棘谷","虎"},ang={["class:Hunter"]="对于一名在荆棘谷丛林中游荡的猎人来说，赫米特·奈辛瓦里或许会有一些狩猎技巧可以分享。",["faction:Alliance"]="巴尼尔·石罐指出，赫米特·奈辛瓦里是一位著名的联盟战争英雄，对同行老兵格外青睐。",["race:Dwarf"]="营地著名的猎人赫米特·奈辛瓦里和你一样是矮人，巴尼尔·石罐特别向你推荐他为大型猎物狩猎大师。"},sec={{t="觐见大师",b="巴尼尔·石罐在荆棘谷丛林的营地欢迎新来者，他一眼就能认出经验丰富的战士。他为你指出了赫米特·奈辛瓦里——一位著名的联盟战争英雄和无与伦比的追踪者。奈辛瓦里只接纳久经考验的老兵，而巴尼尔认为，这位老神枪手或许愿意向一位经历过战斗考验的人传授他的狩猎智慧。"},{t="探险队的试炼",b="奈辛瓦里热情地欢迎了你，并指出在这片荒野见到你这样的职业是非常罕见的。他解释说，他的探险队聚集在这里只有一个目标：追捕一头传说中难以捉摸的丛林野兽。虽然他愿意让你加入这场伟大的狩猎，但信任必须通过猎杀低级猎物来赢取。奈辛瓦里亲自负责追踪迅猛龙的行动，而他的同伴阿杰克和埃尔格丁爵士则会指导猎人如何对付老虎和豹子。"}},faq={{q="赫米特·奈辛瓦里是谁？",a="赫米特·奈辛瓦里是一位著名的联盟战争老兵，也是一位享有盛誉的大型猎物猎人。他带领着一支探险队驻扎在荆棘谷的丛林中。",al={"赫米特·奈辛瓦里","赫米特是谁","奈辛瓦里背景故事"}},{q="是谁派你去找奈辛瓦里谈话的？",a="巴尼尔·石罐，驻扎在丛林营地的成员之一，在认出冒险家的战斗经验后，会引导他们去向奈辛瓦里致意。",al={"巴尼尔·石罐","任务发布者","谁开启了欢迎来到丛林"}},{q="和奈辛瓦里谈话后会发生什么？",a="将会开启几项狩猎任务：迅猛龙狩猎、虎王狩猎、豹王狩猎和荆棘谷的青山。",al={"如何加入狩猎","奈辛瓦里的试炼","狩猎课程"}}},fp="21,236,27.408.0,28.475.1,24.151.0,39.163.0,42.107.0"}
P.entries["quest:584"] = {n="血顶之颅",s="在整理完丛林中收集的战利品后，尼姆布亚证实失踪的年轻巨魔耶尼库并不在其中。为了查明耶尼库命运的真相，暗矛部族试图从敌对的血顶氏族首领那里强行索取答案。",h="在整理完丛林中收集的战利品后，尼姆布亚证实失踪的年轻巨魔耶尼库并不在其中。为了查明耶尼库命运的真相，暗矛部族试图从敌对的血顶氏族首领那里强行索取答案。",kw={"血顶氏族","大熔炉","暗矛部族","甘祖拉","格罗姆高","内兹里奥克","尼姆布亚","耶尼库","祖昆达"},ang={["faction:Horde"]="格罗姆高营地的部落战士为暗矛部族搜寻耶尼库提供了支援。",["race:Troll"]="对于暗矛部族而言，对抗血顶氏族酋长意味着要面对一个敌对部族的首领。"},sec={{t="从死者口中索求答案",b="在之前的狩猎行动证实耶尼库并不在血顶氏族的战利品中之后，尼姆布亚将目光投向了更高层的首领来寻求答案。血顶氏族酋长甘祖拉和他的巫医恐怖的内兹里奥克是暗矛部族的敌人，绝不会心甘情愿地开口。尼姆布亚打算从他们死后的尸体上强行逼问出真相，将他们的头颅带到格罗姆高营地的大熔炉里，好让他们开口说话。"},{t="进入祖昆达",b="两位血顶氏族的首领都栖身于荆棘谷西北部的祖昆达废墟深处。尼姆布亚打算夺取他们的头颅并将其投入沸腾的药水之中，以此逼迫他们说出关于耶尼库的消息。"}},faq={{q="为什么尼姆布亚想要甘祖拉和内兹里奥克的头颅？",a="耶尼库仍然下落不明，尼姆布亚相信只有血顶氏族的酋长和他的巫医掌握着真相。由于这些首领是暗矛部族的敌人，绝不会主动开口，尼姆布亚计划利用大熔炉从他们死后的唇间强行逼问出真相。",al={"为什么要杀死血顶氏族首领","为什么要用割下的头颅","尼姆布亚的动机"}},{q="甘祖拉和内兹里奥克在哪里？",a="这两位巨魔首领都居住在荆棘谷西北部，靠近海滩的祖昆达废墟深处。",al={"甘祖拉在哪里","内兹里奥克在哪里","寻找血顶氏族酋长","祖昆达的位置"}},{q="头颅交付后会发生什么？",a="割下的头颅会被直接放入格罗姆高营地翻滚的大熔炉中，这样就能让这两位首领开口说话了。",al={"头颅要送到哪里","我该如何处理这些头颅","翻滚的大熔炉任务交付"}},{q="这与搜寻耶尼库有什么关联？",a="这项调查始于对年轻耶尼库的搜寻。在之前的搜集头颅行动证明他不在那些普通的死者中之后，审问血顶氏族的首领便成了追查他下落的下一步努力。",al={"耶尼库任务线","与狩猎耶尼库的关联"}}},fp="21,257,31.405.0,14.214.0,58.265.0,41.111.0,42.127.0,48.206.0"}
P.entries["quest:585"] = {n="奈兹里奥克",s="在击败了Bloodscalp的巫医之后，他被砍下的头颅在格罗姆高营地的一个沸腾的大锅中说话。他声称知道失踪的暗矛巨魔的孩子被带到了哪里，但拒绝在没有残酷贡品的情况下泄露秘密。",h="在击败了Bloodscalp的巫医之后，他被砍下的头颅在格罗姆高营地的一个沸腾的大锅中说话。他声称知道失踪的暗矛巨魔的孩子被带到了哪里，但拒绝在没有残酷贡品的情况下泄露秘密。",kw={"balia'mah","bloodscalp","大锅","格罗姆高","nezzliok","裂颅者","荆棘谷","耶尼库","ziata'jai","zul'mamwe"},ang={["faction:Horde"]="部落依靠在格罗姆高营地与一个被束缚的敌对灵魂进行谈判，来揭开暗矛酋长之子耶尼库失踪的真相。",["race:Troll"]="暗矛巨魔必须与一颗敌对的Bloodscalp巫医的断头进行交易，以揭开他们酋长失踪儿子的下落。"},sec={{t="灵魂的代价",b="尽管在搜寻Bloodscalp氏族首领的过程中，Nezzliok的灵魂被束缚在沸腾的大锅里，但他一点也不配合。他承认知道耶尼库被带到了哪里，但在透露信息之前，他要求进行安抚。他命令从敌对的裂颅者部族那里取回三颗战利品骷髅，并带到他安息的地方，以确保他离去的灵魂能在虚空中统御奴仆。"},{t="敌人的头颅",b="Nezzliok要求从Balia'mah的裂颅者战利品堆中直接拿一颗头颅，从Ziata'jai拿第二颗，从Zul'Mamwe拿第三颗。只有当这三件贡品都摆在他的头颅旁边时，这位已死的巫医才会认为他的灵魂得到了满足。"}},faq={{q="谁是Nezzliok？",a="Nezzliok曾是Bloodscalp部族的一名巫医。在战斗中倒下后，他被砍下的头颅被放置在格罗姆高营地的一个沸腾大锅中，他被束缚的灵魂在那里继续说话。",al={"nezzliok","巫医nezzliok","nezzliok的背景故事"}},{q="Nezzliok要求什么？",a="他要求从他所憎恨的对手——裂颅者的营地中偷取三颗战利品骷髅：一颗来自Balia'mah，一颗来自Ziata'jai，一颗来自Zul'Mamwe。",al={"nezzliok想要什么","nezzliok的战利品","与nezzliok交谈的任务目标"}},{q="为什么Nezzliok想要裂颅者的战利品？",a="Nezzliok想要将这些战利品骷髅放在他身边，这样当他的灵魂进入虚空时，他就能拥有三个在死后受他奴役的仆人。",al={"为什么需要头颅战利品","为什么nezzliok需要头颅"}},{q="这件事发生在什么地方？",a="这个事件发生在荆棘谷深处，格罗姆高营地的一口沸腾的大锅旁。",al={"nezzliok在哪里","沸腾大锅的位置"}}},fp="22,239,16.408.0,20.259.0,16.196.0,26.157.0,46.150.0,23.110.0"}
P.entries["quest:586"] = {n="甘祖拉恩",s="即便是在格罗姆高营地的沸腾药水中身首异处，血顶巨魔酋长加兹瑞拉依然怒火中烧。为了平息他那挥之不去的怒火，这个残缺的灵魂要求杀死他那苦大仇深的裂颅者对手，并毁掉他们的统治者：残忍的安娜塞克。",h="即便是在格罗姆高营地的沸腾药水中身首异处，血顶巨魔酋长加兹瑞拉依然怒火中烧。为了平息他那挥之不去的怒火，这个残缺的灵魂要求杀死他那苦大仇深的裂颅者对手，并毁掉他们的统治者：残忍的安娜塞克。",kw={"ana'thek","狂暴者","血顶","大熔炉","加兹瑞拉","格罗姆高","猎头者","裂颅者","荆棘谷"},ang={["faction:Horde"]="加兹瑞拉的头颅位于格罗姆高营地的大锅中，他派遣部落勇士去对抗他的裂颅者敌人。",["race:Troll"]="对于暗矛巨魔来说，看着像血顶和裂颅者酋长这样的世仇将他们不灭的仇恨转向彼此，是对丛林残酷纷争的一声沉痛提醒。"},sec={{t="酋长的复仇",b="在收集了血顶氏族的首领头颅之后，加兹瑞拉的断头继续诅咒着每一个站在沸腾大锅旁的人。由于对捕获者和世仇的双重仇恨，这位死去的酋长指引了一条平息他沸腾怒火的道路：袭击裂颅者部落的东部据点。他要求屠杀他们的猎手、猎头者和狂暴者，并怂恿旅行者去对抗他们凶猛的战团，直至战死。"},{t="破碎的护甲",b="加兹瑞拉预料到这场袭击会以惨败告终，他深信残忍的安娜塞克酋长会撕碎任何胆敢挑战他的入侵者。他要求必须从裂颅者统治者身上剥下破碎的护甲作为胜利的证明。只有将这个战利品带回格罗姆高营地的大熔炉，才能满足这位死去的酋长的怨念。"},{t="不安的和平",b="献上安娜塞克的破碎护甲平息了加兹瑞拉的侮辱。面对对手倒台的现实，酋长那复仇的怒火终于消退了。虽然他承认了击败安娜塞克所需要的力量，但他承诺这场胜利只是推迟了他们清算的日子，发誓要在虚空中再次交锋。"}},faq={{q="加兹瑞拉想让你去哪里？",a="加兹瑞拉指示你向东进入裂颅者的领地中心，前往残忍的安娜塞克指挥下战士们聚集的定居点。",al={"裂颅者在哪里","与加兹瑞拉交谈要去哪里","裂颅者位置"}},{q="谁是残忍的安娜塞克？",a="残忍的安娜塞克是裂颅者巨魔的酋长，也是加兹瑞拉和血顶部落的宿敌。",al={"安娜塞克是谁","谁是裂颅者酋长","残忍的安娜塞克背景故事"}},{q="为什么加兹瑞拉还能说话？",a="加兹瑞拉的断头被浸泡在格罗姆高营地的附魔大锅中，这让他的灵魂能够在他死后发出挥之不去的诅咒和要求。",al={"加兹瑞拉如何说话","为什么头颅在说话","加兹瑞拉大锅"}},{q="加兹瑞拉索要什么战利品？",a="他要求从残忍的安娜塞克酋长身上剥下破碎的护甲，并屠杀裂颅者的猎手、猎头者和狂暴者。",al={"加兹瑞拉需要什么物品","安娜塞克的破碎护甲","加兹瑞拉任务提交物品"}},{q="帮助加兹瑞拉后接下来会发生什么？",a="在解决了各部落酋长之后，探索将继续深入，通过“耶尼库的命运”来揭开这位年轻的暗矛巨魔的下落。",al={"与加兹瑞拉交谈后接什么","加兹瑞拉后的下一个任务","与加兹瑞拉交谈后续"}}},fp="23,275,23.466.0,16.376.0,15.331.1,36.164.0,26.117.0,30.172.0,34.142.0,40.141.0"}
P.entries["quest:5863"] = {n="砂槌食人魔",s="加基森的安迪·利恩警告说，最近有一大群游荡的食人魔抵达了塔纳利斯。他们在镇子南面建立了一个营地，安迪·利恩希望在他们积蓄力量之前将其摧毁。",h="加基森的安迪·利恩警告说，最近有一大群游荡的食人魔抵达了塔纳利斯。他们在镇子南面建立了一个营地，安迪·利恩希望在他们积蓄力量之前将其摧毁。",kw={"安迪·利恩","砂槌","砂槌蛮兵","砂槌营地","砂槌执法者","加基森","蹂躏者戈尔玛洛克","食人魔","塔纳利斯"},sec={{t="沙漠里的食人魔",b="最近，一大群游荡的食人魔抵达了塔纳利斯。他们在加基森南面占据了大片沙漠，并建立了砂槌营地。还有几支较小的食人魔队伍在沙漠中游荡，其中一些甚至入侵了古老的巨魔废墟。安迪·利恩说，绝不能让这些食人魔积蓄力量。"},{t="擒贼先擒王",b="安迪·利恩希望你消灭十个砂槌蛮兵和十个砂槌执法者。这群食人魔的领袖是蹂躏者戈尔玛洛克，安迪·利恩认为，一旦他失去了指挥权，这些食人魔就会开始土崩瓦解。"}},faq={{q="谁要求摧毁砂槌营地？",a="加基森的安迪·利恩。",al={"安迪·利恩","任务发布者是谁","任务发布者"}},{q="砂槌营地在哪里？",a="在加基森南面，食人魔占据的那片广阔沙漠区域中。",al={"砂槌营地位置","食人魔在哪里"}},{q="谁在领导砂槌食人魔？",a="蹂躏者戈尔玛洛克是这群食人魔的领袖。安迪·利恩认为，只要他不再指挥，这些食人魔就会开始崩溃。",al={"食人魔领袖","戈尔玛洛克是谁","蹂躏者戈尔玛洛克"}},{q="为什么安迪·利恩认为这些食人魔很危险？",a="安迪·利恩说，绝不能让这些食人魔积蓄力量。一大群食人魔在镇子南面占据了一个营地，其他较小的队伍也在沙漠中游荡，其中一些还侵占了古老的巨魔废墟。",al={"为什么要杀食人魔","塔纳利斯的食人魔威胁"}}},fp="21,207,19.313.0,20.210.0,51.24.0,31.76.0,29.115.0,45.180.0"}
P.entries["quest:587"] = {n="鼻烟",s="在藏宝海湾，海盗迪格在港口时总喜欢来上一瓶格罗格酒和一点上好的鼻烟，但镇上的草药商却卖光了。草药商说血帆海盗劫持了这批货物，迪格想让你给他带十五份鼻烟来。",h="在藏宝海湾，海盗迪格在港口时总喜欢来上一瓶格罗格酒和一点上好的鼻烟，但镇上的草药商却卖光了。草药商说血帆海盗劫持了这批货物，迪格想让你给他带十五份鼻烟来。",kw={"血帆","藏宝海湾","迪格","格罗格酒","草药商","鼻烟"},sec={{t="岸上的恶习",b="迪格承认海上生活可能并不算什么美好生活，但这却是迪格唯一的生活方式。在港口时，迪格总是寻找格罗格酒和优质的鼻烟：虽然是坏习惯，但海盗总得有点自己的消遣。迪格得知藏宝海湾的草药商那里已经没有存货时感到非常沮丧。草药商声称血帆海盗劫持了那批货物。迪格觉得一位无所畏惧的冒险者或许能说服海盗分享战利品，他需要十五份鼻烟。"},{t="迪格的感谢",b="迪格对这些鼻烟感到非常满意，很高兴能在起航前及时收到，并像对待老朋友一样热切地感谢你。"}},faq={{q="迪格是谁？",a="迪格是藏宝海湾的一名海盗，在港口时总喜欢寻找格罗格酒和上好的鼻烟。",al={"迪格 藏宝海湾","谁发布了岸上的恶习"}},{q="为什么草药商没有鼻烟了？",a="据草药商所说，那一批鼻烟被血帆海盗劫持了。",al={"为什么没有鼻烟","草药商 货物被劫"}},{q="谁有鼻烟？",a="据草药商所说，血帆海盗劫持了那批货物，迪格希望能说服他们分享一些。",al={"谁拿走了鼻烟","血帆鼻烟"}},{q="迪格需要多少鼻烟？",a="十五份鼻烟，送到藏宝海湾给迪格。",al={"多少鼻烟","岸上的恶习需求"}}},fp="11,239,12.420.0,13.119.1,12.81.0,34.88.0,18.119.0,30.54.0"}
P.entries["quest:588"] = {n="耶尼库的命运",s="在格罗姆高营地，奈兹里奥克的头颅从冒泡的大熔炉中说话，准备讲述年轻的暗矛巨魔耶尼库遭遇了什么。肯维雷站在锅边，等待着倾听灵魂的话语。",h="在格罗姆高营地，奈兹里奥克的头颅从冒泡的大熔炉中说话，准备讲述年轻的暗矛巨魔耶尼库遭遇了什么。肯维雷站在锅边，等待着倾听灵魂的话语。",kw={"大熔炉","格罗姆高","肯维雷","奈兹里奥克","耶尼库","赞吉尔"},ang={["faction:Horde"]="找回酋长的儿子对于暗矛部族及其驻扎在格罗姆高营地的盟友来说至关重要。"},sec={{t="锅中的话语",b="在安抚了甘祖拉和奈兹里奥克的灵魂之后，你倾听着冒泡的大熔炉里的头颅终于揭示了它的秘密。肯维雷正站在大熔炉边，等待着听这一切。"},{t="头颅揭示的内容",b="奈兹里奥克宣称耶尼库已经脱离了他的部族，被放逐者赞吉尔带走了。赞吉尔已经彻底束缚了这个男孩，除非有非常强大的魔法，否则无法让他重获自由。肯维雷听后，只剩下了一线希望。"}},faq={{q="谁揭示了耶尼库的下落？",a="奈兹里奥克的头颅通过冒泡的大熔炉开口，揭示了耶尼库的遭遇。",al={"谁在大熔炉中说话","谁揭示了耶尼库的命运","大熔炉的声音"}},{q="应该把奈兹里奥克的话告诉谁？",a="肯维雷站在格罗姆高营地北缘的冒泡大熔炉旁，他需要知道奈兹里奥克揭示了什么。",al={"我该和谁交谈","耶尼库的命运任务交付","肯维雷的位置"}}},fp="19,212,21.199.0,22.244.1,34.95.0,43.139.0"}
P.entries["quest:5881"] = {n="召回卫兵",s="“召唤预备役”是一个部落信使任务，委托给正在烈日石居休息的冒险者。马格兰让你前往贫瘠之地南部的边缘，命令你替换掉一名守卫升降梯、已精疲力竭的哨兵。",h="“召唤预备役”是一个部落信使任务，委托给正在烈日石居休息的冒险者。马格兰让你前往贫瘠之地南部的边缘，命令你替换掉一名守卫升降梯、已精疲力竭的哨兵。",kw={"召唤预备役","升降梯","瑞什·远行者","马格兰","石爪山脉","烈日石居","贫瘠之地","千针石林"},ang={["faction:Horde"]="这项任务展示了部落指挥官如何管理卡利姆多边境的部队，通过轮换哨兵来保持士气和哨所的稳定。",["race:Tauren"]="协助轮换升降梯的哨兵，有助于维持连接卡利姆多南部区域与雷霆崖更广阔领土的这条重要通道。"},sec={{t="期待已久的换防",b="即使在第三次战争后的相对繁荣时期，维持卡利姆多中部的驻军依然在考验着部落的资源。在石爪山脉的烈日石居，马格兰负责监督后勤和部队福利。马格兰意识到久经沙场的老兵在漫无止境的守卫任务下早已疲惫不堪，于是向南方的升降梯寄出一封调任信，而那里的一名年轻哨兵瑞什·远行者已经远离家乡，独自驻守多时。"},{t="守卫升降梯",b="升降梯是连接南贫瘠之地的高原与千针石林风蚀峡谷的唯一工程动脉。将这封信交给瑞什，将让他从孤立且单调的升降梯机械守卫工作中解脱出来，使他最终能够回到家人身边，并让新的预备役人员接替岗位。"}},faq={{q="谁发放这个任务？",a="马格兰在坐落于石爪山脉高处的烈日石居发放该任务。",al={"任务发布者","如何获取召唤预备役","马格兰位置"}},{q="我该把马格兰的信件送到哪里？",a="你必须带着马格兰的信件穿过贫瘠之地，一路向南前往升降梯，这是一座位于边界处、俯瞰千针石林的巨大木制升降结构。",al={"瑞什·远行者位置","瑞什在哪里","升降梯在哪里"}},{q="瑞什·远行者为什么要换防？",a="瑞什独自驻守升降梯机械已有一段时间了。他早些时候正式提交了换防请求，以便能够回家探望家人。",al={"瑞什背景故事","瑞什为何离开","升降梯哨兵任务"}},{q="这个任务需要战斗吗？",a="不需要战斗。这纯粹是一个信使任务，旨在引导旅行者向南前往千针石林。",al={"我需要战斗吗","和平任务","信使任务"}},{q="完成该任务会获得哪个阵营的声望？",a="将信件交给瑞什可以获得雷霆崖声望，这反映了牛头人对这条路线的管辖和管理。",al={"声望奖励","这个任务奖励什么声望","雷霆崖声望"}},{q="这个任务接下来会导向哪里？",a="这次递送会把你直接带到升降梯顶部，使你能够乘电梯下到千针石林的峡谷中，以探索更多的部落哨站。",al={"后续任务","之后去哪里","千针石林指引任务"}}},fx={["39c5e94c"]={q="为什么马格兰要完成这件事？",a="马格兰以部落的繁荣，以及部落轮换和补充士兵的做法为荣。瑞什·远行者前阵子申请休假，想回家与家人团聚，而马格兰终于准备好了一名后备战士，可以接替他驻守在升降梯顶端的偏远岗位。",al={"为什么要送这封信","马格兰的后备战士信件有什么用","为什么要派人接替瑞什"}}},fp="23,234,21.467.0,17.366.0,22.102.0,36.185.0,38.180.0,44.111.0,52.134.0,32.174.0"}
P.entries["quest:589"] = {n="歌唱水晶",s="肯维雷正在寻找营救年轻的耶尼库的方法，以让他摆脱侵蚀他的黑暗。在了解了耶尼库的困境后，这位巫医计划找到一颗被称为“心灵之眼”的传奇宝石，并派遣你去收集掌握其力量所需的共鸣碎片。",h="肯维雷正在寻找营救年轻的耶尼库的方法，以让他摆脱侵蚀他的黑暗。在了解了耶尼库的困境后，这位巫医计划找到一颗被称为“心灵之眼”的传奇宝石，并派遣你去收集掌握其力量所需的共鸣碎片。",kw={"水晶矿洞","格罗姆高","铁颚蛇颈龙","肯维雷","心灵之眼","脉动的蓝色碎片","荆棘谷","耶尼库"},ang={["faction:Horde"]="这一努力旨在帮助格罗姆高营地的暗矛部族，以协助他们全力营救暗矛酋长失踪儿子的绝望斗争。"},sec={{t="心灵之眼的回响",b="在得知耶尼库的可怕遭遇后，医药师肯维雷转向古老的丛林传说寻求答案。传说中提到的心灵之眼是一颗隐藏在荆棘谷深处的宝石，拥有巨大的魔法力量。肯维雷相信这块宝石可能掌握着让这位年轻巨魔灵魂获得自由的秘密。在他向丛林之灵寻求指引以确定其位置的同时，他需要稀有的催化剂来安全地驾驭这颗宝石的强大魔法。"},{t="水晶矿洞",b="肯维雷指引你前往东南方向的水晶矿洞，那里生活着栖息于地下的铁颚蛇颈龙。你需要从这些生物身上找回三块脉动的蓝色碎片。肯维雷打算在最后的仪式中引导这些鸣响之石的固有魔法，以便在找回心灵之眼后将其强大的力量纳入掌控。"}},faq={{q="谁发布了这个任务？",a="肯维雷，一位驻扎在荆棘谷格罗姆高营地的巨魔医药师，发布了这项任务。",al={"谁发布了鸣响之水晶","任务发布者","在哪里开始鸣响之水晶任务"}},{q="为什么需要脉动的蓝色碎片？",a="肯维雷需要利用它们的魔法来控制心灵之眼，他打算用这颗强大的宝石将耶尼库从束缚他的黑暗力量中解救出来。",al={"为什么需要蓝色碎片","碎片有什么用","脉动的蓝色碎片的作用"}},{q="在哪里可以找到铁颚蛇颈龙？",a="它们栖息在水晶矿洞内，该矿洞位于格罗姆高营地东南方，古拉巴什竞技场东面的山峰之上。",al={"铁颚蛇颈龙位置","铁颚蛇颈龙在哪里","水晶矿洞在哪里"}},{q="这个任务的前置任务是什么？",a="这个任务紧接在“耶尼库的命运”之后，该任务说明了这位年轻巨魔的危急处境。",al={"鸣响之水晶前置任务","上一个任务"}},{q="当你去收集碎片时，肯维雷在做什么？",a="他正在与丛林之灵沟通，以发掘心灵之眼的具体藏身之处，并找出守护它的东西。",al={"肯维雷在做什么","肯维雷的作用"}}},fp="20,275,24.488.0,23.353.0,21.110.0,39.150.0,41.127.0,27.89.0,53.125.0"}
P.entries["quest:59"] = {n="布甲和皮甲",s="“布甲与皮甲”是闪金镇的治安官杜汉委派的一项任务。由于对一名冒险者的表现印象深刻，杜汉签发了一张正式的暴风城护甲标记，可以在当地工匠萨拉·迪博雷恩处兑换。这项任务指引新兵向东穿过卫兵托马斯把守的桥梁，前往东谷伐木场，从而获得装备以保卫王国。",h="“布甲与皮甲”是闪金镇的治安官杜汉委派的一项任务。由于对一名冒险者的表现印象深刻，杜汉签发了一张正式的暴风城护甲标记，可以在当地工匠萨拉·迪博雷恩处兑换。这项任务指引新兵向东穿过卫兵托马斯把守的桥梁，前往东谷伐木场，从而...",kw={"护甲标记","布甲与皮甲","东谷","艾尔文森林","卫兵托马斯","伐木场","治安官杜汉","萨拉·迪博雷恩","暴风城军队"},ang={["faction:Alliance"]="通过当地合同为保卫者提供装备，展示了艾尔文森林的乡村社区如何在首都政治瘫痪的情况下维持联盟的运作。",["profession:Tailoring"]="萨拉·迪博雷恩与军队的委任关系表明，布甲制作是王国中一项关键的、官方赞助的军事贸易。",["race:Human"]="为治安官杜汉效力并与萨拉·迪博雷恩进行交易，反映了将艾尔文森林的小型家园凝聚在一起的共同公民纽带。"},sec={{t="治安官的信物",b="卫兵托马斯在艾尔文森林东部的河边桥梁处站岗，守卫边境，抵御敌对的鱼人和游荡的豺狼人。当有能力的旅者将他的报告带到闪金镇时，治安官杜汉会以一张正式的暴风城护甲标记作为奖励，而不是从驻军本就稀缺的储备中调拨装备。此标记作为一份军事征用凭证，正式认可了持有者对王国的贡献。"},{t="东谷的织造者",b="穿过东边的桥梁就是东谷伐木场，这是艾尔文森林主要的木材作业点。萨拉·迪博雷恩在这个定居点工作，她持有暴风城军队的正式委任状，负责生产布甲和皮甲装备。由于王国的中央军械库资源紧张、捉襟见肘，像萨拉这样的当地工匠对于为前线的部队和辅助侦察兵配备装备至关重要。"}},faq={{q="什么是暴风城护甲标记？",a="这是一张由像治安官杜汉这样的军官签发的正式军事征用单。军官们不会在哨所储备笨重的护甲套装，而是随身携带标记，允许受信任的新兵从受委任的民间工匠那里领取量身定制的护甲。",al={"护甲标记","暴风城凭证","什么是标记"}},{q="萨拉·迪博雷恩是谁？",a="萨拉·迪博雷恩是一位居住在东谷伐木场的裁缝和工匠。她与暴风城军队签有合同，为王国人员和获准的辅助战斗人员制作布甲和皮甲装备。",al={"萨拉·迪博雷恩","东谷裁缝","谁制作护甲"}},{q="东谷伐木场在哪里？",a="东谷伐木场位于艾尔文森林的最东端。从卫兵托马斯的河桥哨所出发，沿路向东进入林木繁茂的山谷，那里有伐木工在为王国采伐木材。",al={"东谷位置","东谷在哪里","如何找到迪博雷恩"}},{q="为什么治安官杜汉要把冒险者派往东谷？",a="杜汉不会直接从他在闪金镇的哨所分发成品装备。相反，他通过将新兵派往萨拉·迪博雷恩处来奖励勇敢的行为，在指引旅者前往东谷的同时，确保他们得到妥善的保护，以保卫艾尔文森林。",al={"为什么杜汉给标记","杜汉的目的","为什么去东谷"}},{q="为什么军队要依靠当地裁缝来提供补给？",a="由于瓦里安·乌瑞恩国王失踪，且暴风城的兵力在应对迪菲亚兄弟会的活动和野生兽群时捉襟见肘，当地防卫哨所极度依赖与区域工人的合同来维持供应线。",al={"暴风城补给问题","为什么需要当地工匠","军队后勤"}},{q="卫兵托马斯在防范谁？",a="卫兵托马斯监视着艾尔文森林的东部边界，守护着桥梁，防止来自河栖鱼人、潜行野兽以及毗邻赤脊山的危险荒野的入侵。",al={"卫兵托马斯的敌人","桥梁的威胁","艾尔文森林东部威胁"}}},fp="23,269,19.402.0,22.335.0,33.275.0,23.210.0,35.188.0,53.231.0,54.214.0,38.162.0"}
P.entries["quest:590"] = {n="潜行者的交易",s="“盗贼的交易”是与丧钟镇的卡尔文·蒙泰古之间的一场对峙。在以财富为诱饵向新复生的被遗忘者提供工作后，当索要报酬时，这位狡猾盗贼的真实意图便暴露无遗。",h="“盗贼的交易”是与丧钟镇的卡尔文·蒙泰古之间的一场对峙。在以财富为诱饵向新复生的被遗忘者提供工作后，当索要报酬时，这位狡猾盗贼的真实意图便暴露无遗。",kw={"盗贼的交易","斗殴","卡尔文·蒙泰古","丧钟镇","被遗忘者盗贼","诈骗","提瑞斯法林地"},ang={["class:Rogue"]="与卡尔文·蒙泰古打交道给年轻的盗贼上了一堂职业风险课：不要相信任何人，看好你的钱袋，永远不要让其他无赖带着你的那一份报酬溜走。",["race:Undead"]="在丧钟镇醒来很快就证明了死亡并不能剥夺人类最卑劣的恶习；被遗忘者扒手坑骗自己同类的速度和活着的强盗一样快。"},sec={{t="不光彩的承诺",b="卡尔文·蒙泰古徘徊在丧钟镇的墓穴附近，向新复生的被遗忘者提供看似轻松的工作。蒙泰古谎称只要送一封信就能赚取丰厚的报酬，从而将涉世未深的冒险者置于险境。然而，当差事完成后，蒙泰古却对支付报酬的承诺装傻充愣，假装对任何约定或欠款一无所知。"},{t="付出代价",b="当被迫履行承诺时，蒙泰古露出了真面目。他不仅不愿交出银币，反而拔出武器，赌定自己能轻易干掉一个毫无经验的新手。通过武力教训这名盗贼迫使他屈服。鼻青脸肿的他吐出了一部分钱财，并坦率承认他撒谎是因为觉得可以侥幸逃脱报酬。"}},faq={{q="为什么卡尔文·蒙泰古在被索要报酬时会发动攻击？",a="卡尔文·蒙泰古是一个毫无职业道德的盗贼，他从未打算分享他的钱财。当因为背信弃义被质问时，他试图永远让他的合伙人闭嘴，而不是支付报酬，因为他认定刚复生的被遗忘者是个容易对付的目标。",al={"为什么卡尔文会战斗","卡尔文·蒙泰古敌对","为什么盗贼会攻击"}},{q="这场对峙发生在哪里？",a="对峙直接发生在丧钟镇，即提瑞斯法林地西南部的一座废弃村庄，那里是新复生的被遗忘者最初醒来的地方。",al={"卡尔文·蒙泰古在哪里","卡尔文·蒙泰古位置","盗贼的交易在哪里"}},{q="卡尔文·蒙泰古真的支付了他承诺的报酬吗？",a="没有。在战斗中落败后，卡尔文投降并交出了一些钱币，但他承认这比他最初承诺的要少得多，因为他从一开始就在报酬金额上撒了谎。",al={"卡尔文的奖励","卡尔文会付钱吗","他是否在钱币上撒谎"}},{q="这项后续任务是如何解锁的？",a="在完成了卡尔文·蒙泰古最初的送信差事后，返回并再次与他交谈，索要他承诺的钱币。质疑他的欺诈行为会立即触发战斗。",al={"如何获得第二部分","解锁盗贼交易战斗","秘密盗贼任务"}},{q="卡尔文·蒙泰古在被打败后会死吗？",a="不会。蒙泰古在受到致命一击前就会投降，他会大肆恭维你的战斗技巧，并心不甘情不愿地打开钱袋以保住性命。",al={"我杀死了卡尔文吗","卡尔文死了吗","卡尔文投降"}},{q="这次遭遇给新的被遗忘者提供了什么教训？",a="它成为了被遗忘者残酷现实的一堂早期实践课：亡灵之间荣誉匮乏，言语廉价，尊重只能通过武力来赢得。",al={"盗贼交易的意义","盗贼的交易背后的故事"}}},fx={["80d08ba4"]={q="为什么你必须与卡尔文·蒙泰古战斗？",a="卡尔文·蒙泰古是个彻头彻尾的盗贼。他用财富的虚假承诺诱骗你替他干脏活，等你回来讨要报酬时却装作不知情。他不想付出银币，觉得直接攻击你更便宜、更容易，还指望你会成为任他宰割的猎物。想要拿回应得的报酬，你就得打到他服气，让他乖乖付钱。",al={"为什么要和卡尔文·蒙泰古战斗","卡尔文·蒙泰古要对付谁","为什么要攻击卡尔文"}}},fp="14,216,22.368.0,16.390.1,55.244.1,41.145.0,51.177.1,33.183.1,39.153.1,54.183.0"}
P.entries["quest:591"] = {n="心灵之眼",s="格罗姆高营地的肯维雷正在寻找一颗被称为“心灵之眼”的强力宝石，这件神器对于营救年轻的耶尼库至关重要。这块宝石现在落入了强大的食人魔施法者玛兹拉什手中，他居住在莫什奥格食人魔山深处。",h="格罗姆高营地的肯维雷正在寻找一颗被称为“心灵之眼”的强力宝石，这件神器对于营救年轻的耶尼库至关重要。这块宝石现在落入了强大的食人魔施法者玛兹拉什手中，他居住在莫什奥格食人魔山深处。",kw={"暗矛巨魔","格罗姆高","肯维雷","玛兹拉什","心灵之眼","莫什奥格","食人魔山","耶尼库"},ang={["faction:Horde"]="这次行动以格罗姆高营地为基地，代表暗矛巨魔直接向莫什奥格食人魔据点发起冲击。",["race:Troll"]="寻回心灵之眼对于释放暗矛酋长的儿子耶尼库至关重要。"},sec={{t="强力宝石",b="在寻回了歌唱水晶之后，肯维雷将注意力转向了获取心灵之眼。这件强大的神器是帮助营救暗矛巨魔酋长之子耶尼库的唯一工具。然而，这块宝石目前被玛兹拉什持有，这是一位残忍的食人魔术士，肯维雷还记得他在部落早期在丛林中活动时对方的存在。"},{t="莫什奥格的深处",b="玛兹拉什居住在格罗姆高东面的莫什奥格食人魔山深处。即使在获得心灵之眼之前，他的魔法造诣也已十分强大，而这块宝石更是增强了他的力量。在食人魔的据点中与他对抗充满了危险，但从他手中夺回这件神器依然是解救那名年轻巨魔的唯一希望。"},{t="进入虚空",b="随着宝石的寻回，肯维雷指出，击败玛兹拉什将把这位食人魔术士从血肉的世界放逐到虚空之中。虽然他的肉体威胁已经消除，但肯维雷心中仍隐约担心，玛兹拉什可能会在灵界开辟新的领地。不过，眼下这些担忧先被放到了一边，以便巫医可以准备拯救耶尼库所需的仪式。"}},faq={{q="谁拥有心灵之眼？",a="心灵之眼由玛兹拉什持有，这是一位将巢穴设在格罗姆高营地以东的莫什奥格食人魔山深处的食人魔术士。",al={"谁拥有心灵之眼","心灵之眼在哪里","谁掉落心灵之眼"}},{q="肯维雷为什么需要心灵之眼？",a="肯维雷需要这件神器来举行一场仪式，他认为这是拯救暗矛酋长失踪的儿子耶尼库的唯一方法。",al={"为什么需要心灵之眼","心灵之眼的用途","为什么要获取心灵之眼"}},{q="这在寻找耶尼库的任务中处于什么位置？",a="这紧随“歌唱水晶”任务之后。一旦心灵之眼到手，通往下一步“拯救耶尼库”的道路就会打开。",al={"心灵之眼的前置任务是什么","心灵之眼之前的任务","歌唱水晶之后是什么任务"}},{q="玛兹拉什是谁？",a="玛兹拉什是一位凶残的食人魔术士，肯维雷在暗矛巨魔居住在丛林的那个时代就已认识他。他的魔法非常强大，而心灵之眼的力量又进一步放大了他的能力。",al={"玛兹拉什是谁","关于玛兹拉什","玛兹拉什背景故事"}}},fp="14,250,14.387.0,22.354.0,15.405.1,29.131.0,40.141.0,48.116.0,16.197.0"}
P.entries["quest:592"] = {n="拯救耶尼库",s="在获得心灵之眼后，肯维雷将其制作成一颗特殊的灵魂宝石，以从Zanzil the Outcast手中救出年轻的巨魔耶尼库。这个附魔容器旨在击晕耶尼库并捕获他的灵魂，让他能够被解救并带回给尼姆布亚。",h="在获得心灵之眼后，肯维雷将其制作成一颗特殊的灵魂宝石，以从Zanzil the Outcast手中救出年轻的巨魔耶尼库。这个附魔容器旨在击晕耶尼库并捕获他的灵魂，让他能够被解救并带回给尼姆布亚。",kw={"阿博拉兹","肯维雷","尼姆布亚","拯救耶尼库","灵魂宝石","荆棘谷","耶尼库","zanzil"},ang={["faction:Horde"]="来自格罗姆高营地的部落冒险者们带着尼姆布亚对耶尼库的搜寻任务前往阿博拉兹废墟寻找Zanzil the Outcast。",["race:Troll"]="对于Darkspear tribe来说，将年轻的耶尼库从Zanzil the Outcast的邪恶魔法中解救出来，意味着将一名被俘的Darkspear青年带回他的族人身边。"},sec={{t="灵魂容器",b="在找回心灵之眼后，肯维雷将这一强大的圣物重塑为一颗魔法灵魂宝石。它的双重附魔可以让冒险者先击晕耶尼库，然后将宝石放在他的头上，将他游离的灵魂捕获其中。一旦男孩的本质被封存在宝石内，就可以安全地将他送回格罗姆高营地的族人那里。"},{t="驱逐者的巢穴",b="耶尼库与Zanzil the Outcast一起居住在阿博拉兹废墟，这里位于荆棘谷海角南端的水晶海岸沿岸。要救出这名堕落的年轻人，需要冒险进入Zanzil the Outcast的领地，使用制作好的容器打破巫医对他的控制，并将装满的灵魂宝石带回给尼姆布亚。"}},faq={{q="是谁为这项任务提供了灵魂宝石？",a="肯维雷在重塑找回的心灵之眼后制作并提供了灵魂宝石，并派你去取回耶尼库的灵魂。",al={"谁给予灵魂宝石","在哪里获得灵魂宝石","谁开启了拯救耶尼库的任务"}},{q="耶尼库在哪里？",a="耶尼库可以在荆棘谷海角远处的阿博拉兹废墟，位于水晶海岸的Zanzil the Outcast身边找到。",al={"耶尼库在哪里","耶尼库位置","阿博拉兹废墟位置"}},{q="灵魂宝石是如何运作的？",a="经过重塑的宝石有两种附魔：首先用于击晕耶尼库，然后直接放在他的头上将他的灵魂吸入其中。",al={"如何使用灵魂宝石","灵魂宝石有什么用","荆棘谷灵魂宝石"}},{q="一旦耶尼库被救出，谁会接收装满的灵魂宝石？",a="一旦耶尼库的灵魂被安全地困在宝石中，就必须将其送回格罗姆高营地的尼姆布亚那里。",al={"在哪里交还装满的灵魂宝石","谁接收宝石","耶尼库交付地点"}}},fp="14,266,23.356.0,18.342.0,40.130.0,25.128.0,27.141.0,57.113.0"}
P.entries["quest:5921"] = {n="月光林地",s="月光林地是年轻的暗夜精灵德鲁伊学习与卡利姆多的神圣土地进行交流的入门仪式。在达纳苏斯的玛斯雷·驭熊者指导下，新手们学会了魔法传送咒语，将自己传送到世界另一端的月光林地，去会见永夜港的德迪利特·星焰。这标志着他们迈向掌握熊形态力量的精神之旅的开始。",h="月光林地是年轻的暗夜精灵德鲁伊学习与卡利姆多的神圣土地进行交流的入门仪式。在达纳苏斯的玛斯雷·驭熊者指导下，新手们学会了魔法传送咒语，将自己传送到世界另一端的月光林地，去会见永夜港的德迪利特·星焰。这标志着他们迈向掌握熊...",kw={"熊","塞纳里奥","德迪利特","玛斯雷","月光林地","永夜港","remulos","星焰","传送"},ang={["class:Druid"]="这段旅程代表了你对全球德鲁伊传统的觉醒，为你提供了一条通往塞纳里奥议会宁静核心的永恒生命线。",["faction:Alliance"]="虽然达纳苏斯代表了联盟，但踏入月光林地提醒了暗夜精灵德鲁伊，有一种超越世俗阵营的更古老、更高的使命。",["race:NightElf"]="离开泰达希尔的枝叶前往古老的月光林地，将年轻的卡多雷与大分裂前保留下来的祖先家园直接联系在了一起。"},sec={{t="神圣的避难所",b="月光林地作为一处致力于塞纳留斯教诲的古老圣地，在艾泽拉斯的其他地方显得格外独特。在守护者Remulos的监管下，这里宁静的树林提供了安宁以及与自然的深度交流。对于一名年轻的德鲁伊来说，学习通过传送咒语将自己的灵魂跨越大地投射到月光林地是关键的一步，它使德鲁伊无论相隔多远都能随时获取德鲁伊智慧的核心。"},{t="议会政治",b="虽然月光林地向所有追寻荒野之路的人敞开大门，但这里也并非没有紧张气氛。在大德鲁伊范达尔·鹿盔与月光林地的守护者Remulos之间，围绕着自然治理和泰达希尔的创建问题，产生了一道日益加深的裂痕。尽管塞纳里奥议会内部存在这些哲学上的分歧，但年轻的学徒们依然受到永夜港无条件的欢迎，来此进行神圣的修行。"},{t="熊之道",b="抵达永夜港后，新手将来到德迪利特·星焰面前，这位长者负责引导新晋德鲁伊走上利爪之道。在任何学徒获取熊的斗篷之前，他们必须沉浸在熊的视角中：坚韧、狂怒以及对荒野毫不动摇的防守。星焰怀着对塞纳留斯大人的崇敬之情接待每一位新学生，并开启伟大的熊之灵的试炼。"}},faq={{q="德鲁伊为什么要学习传送到月光林地？",a="传送到月光林地能让德鲁伊直接连接到他们教派的核心。由于训练、与灵魂的交流以及高层会议都在永夜港进行，拥有一种瞬时的精神通道确保了每位修行者都能随时返回去学习和补充他们的精神能量。",al={"为什么要传送到月光林地","传送月光林地的目的","为什么要去月光林地"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位驻扎在永夜港主要旅店上层的长者德鲁伊。他负责监督抵达月光林地的学徒，开启他们掌握动物视角的试炼——从原始的熊之灵开始。",al={"德迪利特·星焰的作用","德迪利特是谁","德迪利特·星焰"}},{q="范达尔·鹿盔和守护者Remulos之间存在什么紧张关系？",a="大德鲁伊范达尔·鹿盔在没有获得龙类守护巨龙祝福的情况下领导了泰达希尔的种植，为暗夜精灵追求一种更激进、更民族主义的姿态。而守护者Remulos和月光林地的传统主义者仍然致力于塞纳留斯古老、中立的道路，这在塞纳里奥议会内部造成了意识形态上的摩擦。",al={"鹿盔与remulos的紧张关系","范达尔对决remulos","议会分裂"}},{q="部落德鲁伊也能访问月光林地吗？",a="是的。月光林地是一个由守护者Remulos和塞纳里奥议会保护的中立避难所。暗夜精灵和牛头人德鲁伊都受到欢迎来到永夜港共同学习荒野之道，在塞纳留斯的和平庇护下放下阵营间的敌意。",al={"部落月光林地","牛头人可以去月光林地吗","月光林地是中立的吗"}},{q="见到德迪利特·星焰后会发生什么？",a="一旦你向德迪利特·星焰报到，他就会引导你进入伟大的熊之灵的仪式试炼。这种精神上的对抗将考验你的决心和理解力，之后你才被允许驾驭熊的原始力量。",al={"月光林地任务之后","熊形态下一步","熊任务后续"}},{q="德迪利特在永夜港的什么位置？",a="德迪利特·星焰位于永夜港中心附近主要的暗夜精灵旅店内，站在二楼阳台上俯瞰着整个村庄。",al={"寻找德迪利特·星焰","德迪利特·星焰位置","德迪利特在哪里"}}},fp="9,263,15.346.0,22.324.0,20.312.0,45.234.0,26.190.0,64.315.0,41.204.0,47.203.0,40.137.0"}
P.entries["quest:5922"] = {n="月光林地",s="这个任务标志着一位年轻的牛头人德鲁伊初次接触月光林地，这里是塞纳里奥德鲁伊教义的神圣庇护所。在雷霆崖的图拉克·符文图腾指导下，这位新成员学会了穿越清醒的世界，直接与自然的远古守护者进行交流。",h="这个任务标志着一位年轻的牛头人德鲁伊初次接触月光林地，这里是塞纳里奥德鲁伊教义的神圣庇护所。在雷霆崖的图拉克·符文图腾指导下，这位新成员学会了穿越清醒的世界，直接与自然的远古守护者进行交流。",kw={"熊形态","塞纳留斯","德迪利特·星焰","月光林地","永夜港","remulos","传送月光林地","图拉克·符文图腾"},ang={["class:Druid"]="这一通过仪式架起了传统部落信仰与塞纳里奥议会更广泛教义之间的桥梁，为开启远古变形形态打开了大门。",["faction:Horde"]="尽管卡利姆多各地局势紧张，但部落德鲁伊发现月光林地是世上少有的几个可以与暗夜精灵同伴和平相遇的地方之一。",["race:Tauren"]="对于牛头人初学者而言，抵达月光林地是一次深度的觉醒：这证明了他们与大地母亲的古老联系与塞纳留斯的教义有着深刻的共鸣。"},sec={{t="超越阵营的神圣避难所",b="月光林地超然于卡利姆多动荡的政治之外。这片远古山谷坐落在原始的林木之下，由塞纳留斯之子，守护者Remulos所看护，它是一切遵循自然之道者的中立避难所。无论是暗夜精灵还是牛头人，任何进入永夜港的德鲁伊，在塞纳里奥议会永恒的庇护下，都是平等的同侪。"},{t="跨越卡利姆多的飞跃",b="为了辅助你的精神与战斗成长，图拉克·符文图腾会教给你一种与这片山谷相连的独特传送法术。通过祈唤德鲁伊与自然世界之间的神秘纽带，你可以在瞬间跨越数百里。这片圣地将作为你旅途中的学习之所和永恒的避难所。"},{t="觉醒巨熊",b="到达永夜港后，你会见到德迪利特·星焰，一位等待新学员的暗夜精灵德鲁伊长者。在他的指引下，你职业生涯的第一次真正考验开始了：寻求巨熊的视角。想要掌握利爪之道，就必须在巨熊之灵面前证明自己的力量、勇气与平衡。"}},faq={{q="为什么牛头人可以造访像月光林地这样的暗夜精灵避难所？",a="月光林地是在塞纳里奥议会管理下的主权神圣土地，由守护者Remulos指引。在它的边界之内，对自然和塞纳留斯的奉献完全超越了部落与联盟之间的阵营冲突，使得牛头人和暗夜精灵德鲁伊能够在此和平共处与修行。",al={"为什么牛头人会在月光林地","部落能否进入月光林地","月光林地是中立的吗"}},{q="谁是德迪利特·星焰？",a="德迪利特·星焰是一位驻扎在永夜港定居点的暗夜精灵德鲁伊长者。他负责指导新抵达的两个种族的初学者，在他们与远古动物之灵建立调和的过程中，主持他们的早期试炼。",al={"德迪利特·星焰","德迪利特是谁","暗夜精灵任务发布者"}},{q="谁是守护者Remulos？",a="守护者Remulos是一位强大的林地守护者，也是半神塞纳留斯之子。他担任月光林地的最高守护者，看守着沉睡的德鲁伊们进行休眠的神圣兽穴，并确保这片山谷的圣洁不容亵渎。",al={"守护者remulos","remulos月光林地","谁保护月光林地"}},{q="到达月光林地后该做什么？",a="与德迪利特·星焰交谈即可开启你的巨熊之灵试炼。他会指引你前往月光林地西北方的灵魂家园，去学习身体的力量与心灵的力量，这是解锁巨熊形态奥秘的第一步。",al={"接下来我该做什么","巨熊任务线","月光林地任务之后"}},{q="传送：月光林地在背景设定中是如何运作的？",a="德鲁伊编织自然的脉线能量以及他们与塞纳里奥议会的精神联结，从而瞬间跨越他们所在位置与月光林地中心之间的距离。这是一种精神锚点，让他们在被召唤时能够随时返回接受指导或寻求慰藉。",al={"传送月光林地背景","德鲁伊传送法术"}},{q="图拉克·符文图腾在哪里？",a="图拉克·符文图腾位于雷霆崖的长者高地上，他负责指导那些响应自然召唤的年轻牛头人，并在之后将他们引向月光林地。",al={"图拉克·符文图腾位置","图拉克在哪里"}}},fx={cadcf30c={q="为什么图拉克·符文图腾派你去月光林地？",a="你即将开始学习利爪之道，具体来说，是学会与熊之形态沟通并接纳它。图拉克·符文图腾无法独自在雷霆崖引导你完成这项神圣的启蒙仪式；你必须亲自踏上月光林地的圣地，在德迪利特·星焰的指导下修习，与自然的野性精魂建立真正的联系。",al={"为什么图拉克派我去月光林地","图拉克·符文图腾的动机","为什么要去月光林地"}},["979ecc1c"]={q="为什么你必须亲自前往月光林地朝圣？",a="德鲁伊之道要求每个人亲自与自然精魂沟通。月光林地是塞纳里奥德鲁伊直接与古老森林精魂以及塞纳留斯的教诲交流的圣所。接纳熊之精魂是一场亲密而个人的考验，关乎品性与自然魔法，没有哪位长老或导师能代你完成。",al={"为什么我必须去月光林地","为什么图拉克不能在这里训练我","为什么选我去月光林地"}}},fp="9,253,29.367.0,24.339.0,18.320.1,54.310.0,26.218.0,22.251.0,38.257.0,44.275.0,33.155.0"}
P.entries["quest:5923"] = {n="响应召唤",s="“响应号召”标志着一位暗夜精灵德鲁伊学徒终于进入了塞纳里奥议会高层领导的视野。这位年轻的入门者被召集到达纳苏斯去觐见玛斯雷·驭熊者，由此开启了掌握其第一个动物形态——熊——的神圣之路。",h="“响应号召”标志着一位暗夜精灵德鲁伊学徒终于进入了塞纳里奥议会高层领导的视野。这位年轻的入门者被召集到达纳苏斯去觐见玛斯雷·驭熊者，由此开启了掌握其第一个动物形态——熊——的神圣之路。",kw={"熊形态","塞纳里奥区","达纳苏斯","德纳萨里安","德鲁伊任务","范达尔·鹿盔","响应号召","卡尔","玛斯雷·驭熊者","瑟利德兰"},ang={["class:Druid"]="此任务代表你正式从一个只会编织根须与愤怒法术的单纯新手，蜕变为一个正在学习卡利姆多灵魂的真正变形者。",["faction:Alliance"]="能从暴风城的瑟利德兰处接到此任务，体现了泰达希尔的卡多雷与他们东部人类盟友之间日益增长的协调性。",["race:NightElf"]="响应召唤将引导你进入达纳苏斯塞纳里奥区的中心，在范达尔·鹿盔的圈子注视下，向延续千年的卡多雷传统致敬。"},sec={{t="来自塞纳里奥区的召唤",b="在泰达希尔磨练技艺，或者在暴风城等遥远国度求学的德鲁伊新手，最终都会收到个人的召唤。多兰纳尔的卡尔、达纳苏斯的德纳萨里安，或是无尽之海彼岸的瑟利德兰等导师会传达消息，称玛斯雷·驭熊者希望亲自指导他们的训练。作为大德鲁伊范达尔·鹿盔的直接助手，玛斯雷是暗夜精灵中最受尊敬且学识渊博的导师之一，他的关注无疑表明这位学徒已经准备好迎接真正的考验了。"},{t="熊之道",b="在塞纳里奥区找到位于范达尔·鹿盔高耸居所上层的玛斯雷，将为你打开通往更深奥秘的大门。为了更好地侍奉自然，德鲁伊必须学会体现其生命形态，而不仅仅是观察它们。玛斯雷欢迎候选人并告知他们，他们的第一个重大任务将是拥抱熊的力量、耐力和精神——这将是一段带他们远赴泰达希尔之外的神圣祖地之旅。"}},faq={{q="谁会派发这个任务给我？",a="当你达到足够的等级后，可以从多位德鲁伊训练师处接到此召唤：多兰纳尔的卡尔、达纳苏斯的德纳萨里安，或是暴风城的公园区的瑟利德兰。",al={"任务发放者","谁开启任务","在哪里接到任务"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位资深的暗夜精灵德鲁伊，也是大德鲁伊范达尔·鹿盔的直接助手。他居住在达纳苏斯的塞纳里奥区，是寻求掌握动物形态的入门者的首席导师。",al={"玛斯雷","玛斯雷是谁","驭熊者"}},{q="我在达纳苏斯哪里可以找到玛斯雷·驭熊者？",a="他在达纳苏斯西北部的塞纳里奥区。你会发现他在那棵作为大德鲁伊范达尔·鹿盔圣殿的大型生命之树的二楼等你。",al={"玛斯雷位置","玛斯雷在哪里","塞纳里奥区位置"}},{q="这个任务会指引我进行什么样的训练？",a="向玛斯雷报到即开启了熊形态的神圣试炼。他会指引你跨越卡利姆多前往神圣的避难所月光林地，学习与伟大的熊灵交流所需的体魄与心智。",al={"what comes next","我能得到什么","后续任务"}},{q="为什么我能在暴风城接到这个任务？",a="暗夜精灵使者和德鲁伊（例如瑟利德兰）在暴风城的公园区维护着一座圣殿，以协助联盟盟友。如果一位年轻的德鲁伊正在艾尔文森林的大海上冒险，瑟利德兰可以将此召唤传达给他们，指引他们回到泰达希尔。",al={"暴风城任务","瑟利德兰","能在暴风城接吗"}},{q="为什么熊形态是第一个教授的动物形态？",a="德鲁伊认为自然既需要守护者也需要照料者。熊代表着原始的韧性、肉体的力量，以及保护平衡不受伤害的勇气，这使它成为在危险的荒野试炼中生存的基础形态。",al={"为什么是熊形态","德鲁伊熊形态背景"}}},fx={["7976a971"]={q="为什么要派我去找玛斯雷·驭熊者？",a="你的德鲁伊导师认为，你的基础学徒训练已经完成，已经可以接受进阶教导。玛斯雷·驭熊者直接听命于大德鲁伊范达尔·鹿盔，并负责监督与巨熊精魂沟通的重要仪式。训练师指引你去找他，让你开始学习变形，获得保护自然平衡所需的身心力量。",al={"为什么找玛斯雷","为什么响应召唤","响应召唤的原因","为什么denatharion派我去"}},fad6f2dc={q="为什么玛斯雷·驭熊者想要我，而不是其他人？",a="这不是国家事务或军事防务，而是与你作为德鲁伊见习者的道路息息相关的个人成年礼。玛斯雷·驭熊者正在寻找有潜力引导野性精魂的年轻德鲁伊。只有你能与守护精魂沟通，并经受掌握第一个动物形态所需的精神考验。",al={"为什么响应召唤的人是我","为什么选我","为什么玛斯雷需要我"}}},fp="16,278,26.560.0,20.479.0,27.197.0,29.235.0,52.204.0,38.222.0,38.246.0,52.241.0"}
P.entries["quest:5925"] = {n="响应召唤",s="“听从召唤”是一项关键的传唤，指引见习暗夜精灵德鲁伊前往达纳苏斯。大德鲁伊范达尔·鹿盔的直属助手玛斯雷·驭熊者召集新手，以推进他们的训练并为熊的试炼做准备。",h="“听从召唤”是一项关键的传唤，指引见习暗夜精灵德鲁伊前往达纳苏斯。大德鲁伊范达尔·鹿盔的直属助手玛斯雷·驭熊者召集新手，以推进他们的训练并为熊的试炼做准备。",kw={"熊形态","塞纳里奥区","达纳苏斯","德鲁伊训练","范达尔·鹿盔","听从召唤","玛斯雷·驭熊者","泰达希尔"},ang={["class:Druid"]="这次传唤标志着你从基础新手训练过渡到与自然形态的更深层交流，而这一切将直接在大德鲁伊鹿盔的私人助手的指导下开始。",["faction:Alliance"]="在达纳苏斯响应塞纳里奥召唤的暗夜精灵德鲁伊，巩固了联盟在卡利姆多古老的魔法与自然根基。",["race:NightElf"]="这次传唤发生在达纳苏斯中心的塞纳里奥区，强调了塞纳里奥德鲁伊教义在卡多雷社会中的深层融合。"},sec={{t="达纳苏斯的传唤",b="当一位年轻的德鲁伊在泰达希尔的枝叶间完成基础训练后，消息传来，玛斯雷·驭熊者希望能亲自与他交谈。玛斯雷并非普通的导师——他是大德鲁伊范达尔·鹿盔的直属助手，也是塞纳里奥区中最受尊敬和睿智的人物之一。这次传唤标志着新手的训练已准备好迎接更宏大的目标，超越基础的守望职责，迈向更深奥的自然神圣艺术。"},{t="熊之道",b="旅程直接通往达纳苏斯的塞纳里奥区，登上大德鲁伊鹿盔巨树的二层。驭熊者欢迎这位新手，并申明每一位响应塞纳留斯召唤的追随者都必须尊重草木与野兽，视其为同伴与责任。致力于维护自然的平衡不仅仅需要静谧的冥想，更需要学习野生熊之道，掌握身心真正的力量。"}},faq={{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位庄严而睿智的德鲁伊，担任大德鲁伊范达尔·鹿盔的直属助手。他负责监管达纳苏斯有前途的德鲁伊们的高阶训练。",al={"谁想和我交谈","玛斯雷是谁","玛斯雷·驭熊者是谁"}},{q="玛斯雷·驭熊者在哪里？",a="他位于达纳苏斯塞纳里奥区内范达尔·鹿盔的树屋二层，那里是塞纳里奥议会的高阶成员在泰达希尔集会的地方。",al={"我在哪里可以找到驭熊者","玛斯雷在哪里","塞纳里奥区位置"}},{q="为什么我会被传唤去与玛斯雷交谈？",a="你被传唤是因为你的基础训练已经完成，作为一名德鲁伊，你的道路即将拓展。玛斯雷将亲自负责引导你深入探索自然的深奥领域。",al={"我为什么被传唤","这个任务是为了什么","为什么要听从召唤"}},{q="我能从玛斯雷·驭熊者那里学到什么？",a="玛斯雷将开始传授你熊之道，教导你获得身心的力量，以成为自然平衡的守护者。",al={"玛斯雷会教我什么","接下来我学什么","我会获得什么形态"}},{q="成为“塞纳留斯之子”意味着什么？",a="塞纳留斯是自然的守护半神，也是第一批德鲁伊的导师。他的追随者认为所有德鲁伊都有共同的职责，那就是保护艾泽拉斯的野生草木与野兽。",al={"塞纳留斯是谁","塞纳留斯之子的含义"}},{q="范达尔·鹿盔的树是指什么？",a="那是指达纳苏斯塞纳里奥区内的一棵巨大的空心生命之树，大德鲁伊范达尔·鹿盔和他的核心圈子在那里指挥泰达希尔各处的塞纳里奥事务。",al={"他在哪棵树里","鹿盔之树的位置"}}},fp="16,252,22.478.0,20.462.0,29.186.0,39.166.0,44.190.0,45.143.0,51.180.0,32.170.0"}
P.entries["quest:5926"] = {n="响应召唤",s="“听从召唤”标志着一位德鲁伊新手被传唤至雷霆崖的长者高地，接受高级的个人指导。通过部落定居点各地的旅店老板和族人转达，这项召唤指引着有抱负的变形者去找图拉克·符文图腾。这次会面开启了掌握熊的形态与精神所必需的神圣试炼。",h="“听从召唤”标志着一位德鲁伊新手被传唤至雷霆崖的长者高地，接受高级的个人指导。通过部落定居点各地的旅店老板和族人转达，这项召唤指引着有抱负的变形者去找图拉克·符文图腾。这次会面开启了掌握熊的形态与精神所必需的神圣试炼。",kw={"熊形态","血蹄村","塞纳里奥议会","德鲁伊","长者高地","gennia runetotem","听从召唤","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这个任务是你掌握动物形态道路上至关重要的第一步，开启了获取熊之精神与坚韧的神圣旅程。",["faction:Horde"]="兽人和牛头人领地各处的旅店老板帮助确保新晋德鲁伊收到他们的召唤，促进了部落与大地之野性之间至关重要的联系。",["race:Tauren"]="对于牛头人来说，在长者高地跟随图拉克学习，重申了他们与塞纳里奥议会及卡利姆多野性之灵之间深厚的祖先联系。"},sec={{t="旅店中的传言",b="消息在莫高雷的平原和奥格瑞玛尘土飞扬的街道上迅速传播开来。无论你是从兽人那里的旅店老板格雷什卡口中，还是从雷霆崖的旅店老板帕拉，或是血蹄村的Gennia Runetotem口中得知，消息都是一样的：图拉克·符文图腾已经注意到了你早期的进步。塞纳里奥议会绝不会轻易传唤修行者，这份邀请标志着你简单的草药采集和基础施法日子已经结束，你已经赢得了与自然狂野之灵更深层次交流的机会。"},{t="长者高地上的议会",b="图拉克·符文图腾是大德鲁伊哈缪尔·符文图腾的助手，在长者高地的塞纳里奥大帐篷内指引着年轻的牛头人履行他们的祖先职责。图拉克欢迎初学者进入对塞纳留斯遗产更广泛的认知领域，并教导他们动植物既是盟友也是庄严的责任。与他会面是仪式的开端：超越基础的指导，去面对与巨熊之灵直接沟通所必需的身心试炼。"}},faq={{q="谁指派我去和图拉克·符文图腾交谈？",a="这项传唤可以通过几位不同的联络人传达：血蹄村的Gennia Runetotem、雷霆崖的旅店老板帕拉，或是奥格瑞玛的旅店老板格雷什卡。每个人都收到了消息，称图拉克希望亲自指导你的训练。",al={"谁发布听从召唤","听从召唤任务发布者","如何开始听从召唤"}},{q="我在哪里可以找到图拉克·符文图腾？",a="图拉克居住在雷霆崖的长者高地。他就在城中其他德鲁伊导师附近的塞纳里奥议会大帐篷里。",al={"图拉克·符文图腾位置","图拉克在哪里","如何找到图拉克"}},{q="为什么这项传唤对年轻的德鲁伊如此重要？",a="这项传唤标志着你正式变形试炼的开始。图拉克·符文图腾会指引你前往月光林地的神圣之地，这样你就可以学习熊之道，并获得你的第一个动物形态。",al={"为什么需要找图拉克","这个任务是为了什么","部落德鲁伊10级任务"}},{q="图拉克·符文图腾在塞纳里奥议会的阶层中是什么地位？",a="图拉克是一位受人尊敬的牛头人德鲁伊，也是大德鲁伊哈缪尔·符文图腾值得信赖的助手。他因在教导年轻初学者自然平衡时的耐心和智慧而闻名。",al={"图拉克·符文图腾是谁","图拉克背景故事"}},{q="其他职业可以接受这个任务吗？",a="不能。这个任务仅供达到十级经验的德鲁伊接取，作为他们进入变形之路的成人礼。",al={"听从召唤是德鲁伊专属任务吗","萨满可以做这个任务吗"}},{q="我与图拉克交谈后会发生什么？",a="图拉克会欢迎你加入塞纳留斯的侍从行列，并派遣你前往神圣的德鲁伊避难所月光林地，去寻找德迪利特·星焰，开始与巨熊之灵的沟通。",al={"听从召唤之后是什么","图拉克之后的下一个任务"}}},fx={["309dc9df"]={q="为什么要派我去找图拉克·符文图腾？",a="各个聚居地已经听说，图拉克·符文图腾——大德鲁伊的助手——正在寻找有潜质、需要更深入教导的年轻德鲁伊。任务发布者只是代为传话，确保你不会错过他的召唤。图拉克愿意亲自指导你，这标志着你的初步训练将迈向与自然真正沟通、领悟野性之道的新阶段。",al={"为什么派我去找图拉克","为什么gennia要我去找图拉克谈谈","为什么要见图拉克·符文图腾"}}},fp="16,326,17.516.0,24.497.0,43.242.0,33.149.0,50.184.0,49.181.0,36.151.0,36.176.1"}
P.entries["quest:5929"] = {n="巨熊之灵",s="巨熊之灵是月光林地德鲁伊的一项基础导师任务，指引初学者前往西北方的荒野中寻找一位古老而高贵的灵魂。与该灵魂交流能够传授关于熊的本性和力量的关键智慧，这标志着德鲁伊精神与武艺训练中的关键一步。",h="巨熊之灵是月光林地德鲁伊的一项基础导师任务，指引初学者前往西北方的荒野中寻找一位古老而高贵的灵魂。与该灵魂交流能够传授关于熊的本性和力量的关键智慧，这标志着德鲁伊精神与武艺训练中的关键一步。",kw={"熊形态","德迪利特·星焰","德鲁伊任务","巨熊之灵","月光林地","永夜港"},ang={["class:Druid"]="与巨熊之灵的交流是每一位德鲁伊必经的成人仪式，它传授了获得熊之韧性所需的自然智慧和精神基础。"},sec={{t="月光林地的高贵导师",b="巨熊之灵栖息在月光林地的西北荒野中，远离了永夜港那宁静的小径。作为一位备受尊敬的高贵古老导师，该灵魂是所有试图理解熊之自然本质的初学者的基础导师。寻求它的祝福与智慧是每一位行走于自然之道的德鲁伊所共同遵守的神圣传统。"},{t="原始专注的仪式",b="在永夜港德迪利特·星焰的指引下，年轻的德鲁伊们踏上旅程，前往山丘之中向这位灵魂觐见。与巨熊之灵的交流传授了原始的智慧和对自然力量的感知。在归来后，德迪利特会考验他们的专注力，并指出尽管这次相遇灌注了原始的力量和明确的意图，但德鲁伊仍需学习如何将那股内在的力量引导至日常工作中。"}},faq={{q="在哪里可以找到巨熊之灵？",a="巨熊之灵居住在月光林地的西北方，远离了永夜港的定居点，栖息在这一神圣避难所更为荒野的边缘地带。",al={"巨熊之灵的位置","寻找月光林地巨熊之灵","巨熊之灵坐标"}},{q="是谁指引德鲁伊去寻找巨熊之灵的？",a="驻扎在永夜港的德鲁伊长者德迪利特·星焰会指引初学者与该灵魂进行交流，以此作为他们自然训练的一部分。",al={"谁指引去见巨熊之灵","德迪利特·星焰的作用","巨熊之灵任务给予者"}},{q="什么是巨熊之灵？",a="巨熊之灵被尊为一位睿智而高贵的实体，它为所有修行中的德鲁伊提供关于熊之原始理解的指引、教导和辅导。",al={"什么是巨熊之灵","巨熊之灵背景故事","巨熊之灵是谁"}},{q="为什么德鲁伊必须与巨熊之灵交流？",a="初学者寻找该灵魂是为了了解熊的核心本性，吸收其原始的力量、韧性和智慧，然后再回去将这些特质运用到自己的修行之中。",al={"为什么要与巨熊之灵交谈","巨熊之灵任务目的","从巨熊之灵那里学到什么"}},{q="当巨熊之灵感到满意后会发生什么？",a="在与灵魂交流后，初学者会回到永夜港找德迪利特·星焰，他会认可他们新获得的领悟，并让他们准备好驾驭和专注于那股力量。",al={"巨熊之灵之后发生什么","灵魂试炼后的德迪利特","拜访巨熊之灵后"}},{q="所有德鲁伊都需要寻求该灵魂的智慧吗？",a="每一位德鲁伊最终都必须寻求巨熊之灵的教诲，因为与该灵魂的交流被视为掌握动物形态和自然力量的一个基础步骤。",al={"所有德鲁伊都要拜访巨熊之灵吗","巨熊之灵是必须的吗","谁会去拜访巨熊之灵"}}},fp="17,335,29.379.0,22.422.0,41.164.0,51.139.0,30.170.0,51.184.0,54.186.0,47.174.0"}
P.entries["quest:593"] = {n="灵魂宝石",s="在荆棘谷茂密的丛林深处，有人试图挽救年轻的巨魔耶尼库。当这名年轻人陷入恍惚状态时，有人拿出一颗准备好的灵魂宝石，试图捕捉他的灵魂。",h="在荆棘谷茂密的丛林深处，有人试图挽救年轻的巨魔耶尼库。当这名年轻人陷入恍惚状态时，有人拿出一颗准备好的灵魂宝石，试图捕捉他的灵魂。",kw={"拯救耶尼库","灵魂宝石","荆棘谷","巨魔","耶尼库"},sec={{t="丛林中的恍惚",b="在尝试拯救耶尼库之后，你与荆棘谷中的这名年轻巨魔面对面。他的心智已经迷失，完全被困在了另一个地方，而他的身体却依然在你面前一动不动。唯一的解决办法是使用那颗专门为容纳他的灵魂而准备的附魔宝石。"},{t="容器",b="将宝石按在耶尼库的额头上，会将他的灵魂直接吸入石中。随着灵魂被抽离，他的肉体战栗着瘫倒在地，变成了一具空洞、毫无心智的躯壳。"}},faq={{q="当你找到耶尼库时，他的状态如何？",a="耶尼库处于昏迷且无反应的状态，他的意识远离了他的躯体。",al={"耶尼库状态","耶尼库怎么了","耶尼库昏迷"}},{q="什么物品被用在了耶尼库身上？",a="一颗从荆棘谷带来的灵魂宝石被用来与这名年轻巨魔互动。",al={"需要什么物品","用在耶尼库身上的宝石","耶尼库物品"}},{q="在此之前发生了什么？",a="这次遭遇紧接在荆棘谷丛林中“拯救耶尼库”的任务之后。",al={"前置任务","填充灵魂宝石的前提条件","导致此结果的原因"}}},fp="20,192,22.287.0,10.182.1,48.99.0,29.84.0,29.98.0"}
P.entries["quest:5931"] = {n="返回达纳苏斯",s="此任务标志着一位暗夜精灵德鲁伊新手从月光林地的圣所归来，抵达达纳苏斯。在与巨熊之灵沟通后，这位新兵需要向塞纳里奥区的玛斯雷·驭熊者汇报，以开始实际的变形试炼。",h="此任务标志着一位暗夜精灵德鲁伊新手从月光林地的圣所归来，抵达达纳苏斯。在与巨熊之灵沟通后，这位新兵需要向塞纳里奥区的玛斯雷·驭熊者汇报，以开始实际的变形试炼。",kw={"巨熊之灵","驭熊者","塞纳里奥区","达纳苏斯","德迪利特","玛斯雷","月光林地","变形","星焰"},ang={["class:Druid"]="这趟旅程代表了年轻德鲁伊的关键成人礼，标志着从理论上的精神沟通到物理变形的转变。",["race:NightElf"]="在古老的月光林地圣所和新种植的世界之树泰达希尔之间穿梭，反映了卡多雷千年传承与其目前职责之间的平衡。"},sec={{t="圣所之间的旅程",b="在与月光林地的巨熊之灵沟通后，年轻的德鲁伊必须在永恒的自然圣所与动荡的世界之间架起桥梁。德迪利特·星焰会派新兵从永夜港返回达纳苏斯，将下一阶段的训练托付给守护泰达希尔的当地导师。"},{t="利爪之路",b="玛斯雷·驭熊者在塞纳里奥区等待着，即使在平衡受到威胁的地方，他依然守护着自然。接受巨熊之灵的祝福仅仅是第一步；玛斯雷会通过对身体和心灵的严苛考验，让新兵学会将那种狂野的先祖智慧转化为物理形态。"}},faq={{q="为什么我需要回到达纳苏斯？",a="月光林地提供的是与巨熊之灵的精神交流，但你的直接导师玛斯雷·驭熊者居住在达纳苏斯的塞纳里奥区。他将指导你掌握新获得的力量所需的实际测试。",al={"为何返回达纳苏斯","为何离开月光林地","德迪利特派我去哪"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位经验丰富的暗夜精灵德鲁伊训练师，驻扎在达纳苏斯的塞纳里奥区。他专门指导年轻的新兵通过利爪之路并掌握熊形态。",al={"玛斯雷是谁","玛斯雷·驭熊者背景故事","驭熊者"}},{q="我该如何从月光林地回到达纳苏斯？",a="位于永夜港西南部的角鹰兽管理员席尔瓦·菲尔纳维斯可以为新兵提供直飞回海对岸鲁瑟兰村的航班，你可以从那里通过传送门前往达纳苏斯。",al={"如何离开永夜港","月光林地返程飞行","席尔瓦·菲尔纳维斯"}},{q="我和玛斯雷交谈后会发生什么？",a="玛斯雷将指派你进行第一次真正的目的测试，让你前往黑海岸奥伯丁东部的枭兽石面对月爪，以证明你的身体和心灵已做好驾驭熊形态的准备。",al={"返回达纳苏斯后的下一个任务","what comes next"}},{q="什么是利爪之路？",a="利爪之路是德鲁伊的传统，专注于引导熊的狂暴、坚韧和力量，并通过与古老的原始灵魂沟通来实现这一点。",al={"利爪之路","德鲁伊利爪背景知识"}},{q="为什么德迪利特提到平衡在达纳苏斯附近动摇？",a="泰达希尔还很年轻，没有受到龙类的祝福，这使其枝叶极易受到各种奇怪的腐蚀、熊怪的疯狂和不断逼近的黑暗侵害，而塞纳里奥区的德鲁伊们正在积极对抗这些威胁。",al={"达纳苏斯平衡动摇","泰达希尔腐化"}}},fp="17,215,29.348.0,20.287.0,37.206.0,29.172.0,46.163.0,41.195.0,29.150.0,59.208.0"}
P.entries["quest:5932"] = {n="返回雷霆崖",s="“回到雷霆崖”是牛头人德鲁伊学徒从神圣的月光林地归来后必经的重要仪式。在与伟大的熊之灵交流后，学徒会被德迪利特·星焰送回长者高地，继续在图拉克·符文图腾的教导下进行训练。",h="“回到雷霆崖”是牛头人德鲁伊学徒从神圣的月光林地归来后必经的重要仪式。在与伟大的熊之灵交流后，学徒会被德迪利特·星焰送回长者高地，继续在图拉克·符文图腾的教导下进行训练。",kw={"回到雷霆崖","熊形态","德迪利特·星焰","长者高地","伟大的熊之灵","月光林地","永夜港","图拉克·符文图腾"},ang={["class:Druid"]="你旅程的这一段将古老隐秘的避难所月光林地与风吹日晒的雷霆崖高地连接了起来，标志着你在利爪之路上又迈进了一步。",["faction:Horde"]="从月光林地带回的知识确保了部落在卡利姆多的平原上拥有强大的变形防御者。",["race:Tauren"]="回到长者高地，将古老之灵的智慧带回家园，从而造福并保护你遍布莫高雷的部落。"},sec={{t="跨越种族的友谊",b="月光林地超然于凡世的阵营纷争之外，作为一处避难所，暗夜精灵与牛头人的自然魔法修行者在此汇聚，组成了塞纳里奥议会。在与伟大的熊之灵交流后，暗夜精灵导师德迪利特·星焰会将年轻的牛头人送回他们的族人身边。尽管暗夜精灵通常视牛头人为塞纳留斯教义的学习新手，但星焰导师十分认可图拉克·符文图腾所展现的深邃智慧与平衡之道。"},{t="返回雷霆崖",b="当回到雷霆崖长者高地那广阔的高地时，这位学徒已经脱胎换骨，站在了图拉克·符文图腾的面前。与伟大的熊之灵等古老的图腾之灵交流在牛头人文化中根深蒂固，而踏上利爪之路则标志着一种严肃的承诺。随着精神连接的建立，图拉克正在准备让这位德鲁伊将新获得的力量与耐力付诸实践。"}},faq={{q="为什么暗夜精灵会在月光林地教导牛头人？",a="塞纳里奥议会保持中立，完全致力于保护自然。在月光林地内，部落与联盟之间的政治敌对被严格搁置，这使得像德迪利特·星焰这样的暗夜精灵长者能够指引年轻的牛头人德鲁伊。",al={"德迪利特·星焰 部落","为什么暗夜精灵是导师","塞纳里奥议会 牛头人"}},{q="谁是图拉克·符文图腾？",a="图拉克·符文图腾是一位受人尊敬的牛头人德鲁伊，他是大德鲁伊的助手之一，驻扎在雷霆崖的长者高地。他负责监督那些寻求走上自然与利爪之路的年轻牛头人的训练，是塞纳里奥议会的关键联络人。",al={"图拉克·符文图腾职责","长者高地 德鲁伊领袖"}},{q="在此任务之前，这位年轻的德鲁伊做了什么？",a="在被送回莫高雷之前，学徒前往月光林地寻找并与古老的伟大的熊之灵进行了交流，获得了它的祝福，并掌握了熊形态的精神核心。",al={"回到雷霆崖之前","伟大的熊之灵任务"}},{q="年轻的德鲁伊如何从月光林地返回雷霆崖？",a="位于永夜港西南方的Bunthen Plainswind提供了专门的飞行管理员服务，在仪式结束后安全地将牛头人德鲁伊送回雷霆崖。",al={"如何从月光林地返回","月光林地 返回飞行"}},{q="这位德鲁伊接下来的训练是什么？",a="返回后，图拉克·符文图腾会交给学徒任务“身与心”，派遣他们前往贫瘠之地与莫高雷交界处的枭兽石，迎接体能挑战，以证明他们能够将灵体的力量转化为真正的野兽形态。",al={"下一个德鲁伊任务","回到雷霆崖之后"}},{q="为什么德迪利特·星焰称牛头人在塞纳留斯之道的修行上尚显稚嫩？",a="虽然牛头人的传说追溯到世界黎明时与塞纳留斯的古老交流，但正式的塞纳里奥德鲁伊教义是由暗夜精灵在过去一万年间发展并维持的。牛头人只是最近才在塞纳里奥议会的指导下重新建立了系统性的学习。",al={"牛头人是新德鲁伊吗","牛头人德鲁伊历史 塞纳留斯"}}},fx={["9396c536"]={q="为什么德迪利特·星焰要你返回雷霆崖？",a="你在月光林地与巨熊精魂的初次沟通，只是觉醒的第一步。德迪利特·星焰明白，要将野性的教诲付诸实践，你还需要自己的导师亲自指导。他把下一阶段的训练托付给图拉克·符文图腾——一位恪守深刻平衡之道的牛头人德鲁伊——让你证明自己配得上熊之精魂永恒的力量。",al={"为什么派我去找图拉克","德迪利特·星焰的动机","为什么要回雷霆崖"}}},fp="21,276,20.491.0,20.427.0,51.262.0,23.261.0,52.198.0,64.183.0,40.244.0,72.261.0"}
P.entries["quest:594"] = {n="瓶中信",s="一个被冲上荆棘谷海岸的瓶子中装有一份紧急求援信。写信者声称自己被困在南海一座孤岛上，被一只巨大的野兽囚禁着。",h="一个被冲上荆棘谷海岸的瓶子中装有一份紧急求援信。写信者声称自己被困在南海一座孤岛上，被一只巨大的野兽囚禁着。",kw={"半埋的瓶子","瓶中信","普巴尔公主","天鬃兽","南海","荆棘谷","蛮荒海岸"},sec={{t="来自波涛的呼唤",b="在一个半埋在沙子里的玻璃容器中，躺着一张字迹工整的字条，上面写着请求立即援助的内容。被囚禁者报告称，自己被困在异国岛屿上，头顶是茂密的丛林树冠，看守她的是一只巨大的天鬃兽。透过树木的缝隙只能隐约看到模糊的地标：西北方可以看到蛮荒海岸，而西南方则有大型帆船漂流经过。"},{t="字条的作者",b="根据航海指示越过水域到达一座近海岛屿，写下这封信的人就在那里等待。被困的俘虏是普巴尔公主，她迫切希望能有一位冒险者最终找到她，给予她重获自由的机会。"}},faq={{q="瓶子里的字条写了什么？",a="这条消息是一封用清晰字迹写就的紧急求援信。信中解释说作者被一只巨大的天鬃兽囚禁在南海的一座岛屿上，并恳求捡到这封信的人予以营救。",al={"字条内容","瓶中信","瓶子里写了什么"}},{q="写信者说岛屿位于何处？",a="虽然丛林树木遮挡了夜空，但被囚禁者提到，在晴朗的日子里，西北方向可以看到蛮荒海岸，西南方向则会出现大型帆船。",al={"岛屿位置","如何找到被俘者","岛屿地标"}},{q="是什么囚禁了作者？",a="字条上写着，一只被称为“巨大的天鬃兽”的生物将作者囚禁在了岛上。",al={"谁俘虏了作者","是什么囚禁了作者","天鬃兽俘虏"}},{q="这会引出后续的冒险吗？",a="找到寄信人是两步任务链的第一部分，一旦找到被俘者，便会直接触发第二部分。",al={"后续任务","是否有后续","之后会发生什么"}}},fp="19,192,21.379.0,22.233.1,37.202.0,48.179.0,35.102.0,37.120.0"}
P.entries["quest:5943"] = {n="基泽尔顿车队",s="里格·基泽尔顿和科克为了发财而组建了商队，却发现贸易比他们预想的要危险得多。玛诺洛克集会所就在前方，里格想要一位能干的冒险者来护送商队安全通过。",h="里格·基泽尔顿和科克为了发财而组建了商队，却发现贸易比他们预想的要危险得多。玛诺洛克集会所就在前方，里格想要一位能干的冒险者来护送商队安全通过。",kw={"商队","科克","集会所","凄凉之地","基泽尔顿","科多兽","玛诺洛克","里格","瑟卡布斯库","斯米德"},sec={{t="穿过玛诺洛克集会所",b="里格·基泽尔顿和科克组建商队是为了赚大钱，他们根本不知道获利的过程竟然如此冒险。玛诺洛克集会所就在前方。恶魔们通常不会理会商队，但这次科多兽却受惊了。如果你能护送商队通过集会所，里格愿意支付报酬。一旦商队安全通过，你的报酬可以在瑟卡布斯库的营地找他们的商业伙伴斯米德领取。"},{t="斯米德的忧虑",b="在瑟卡布斯库的营地，斯米德擦着汗说，如果商队失踪他会破产，所以很高兴听到它没有丢。他不确定花这么多钱去保护一个每周只能赚一个金币的商队是否有意义。不过，只要科克和里格继续为他的科多兽付钱，他就不在乎他们怎么经营生意。"}},faq={{q="谁是里格·基泽尔顿？",a="一个和科克一起创办了基泽尔顿商队的商队老板，希望能赚大钱。",al={"里格是谁","基泽尔顿背景","里格·基泽尔顿"}},{q="为什么商队需要护送通过玛诺洛克集会所？",a="里格说那里的恶魔通常会无视商队，但这次有什么东西让科多兽受惊了。",al={"为什么护送商队","玛诺洛克集会所危险","为什么要保护商队"}},{q="谁为你护送商队支付报酬？",a="斯米德，基泽尔顿在瑟卡布斯库的营地的商业伙伴，商队安全通过集会所后向他领取。",al={"谁付钱给我","基泽尔顿商队任务在哪里交","斯米德报酬"}},{q="谁是科克？",a="里格·基泽尔顿的商队合伙人。",al={"考克·基泽尔顿","科克是谁"}}},fp="16,210,19.399.0,18.360.1,23.85.0,57.103.0,40.108.0,12.41.0"}
P.entries["quest:595"] = {n="血帆海盗",s="黑水强盗的大副克拉兹需要一位冒险者去调查有关敌对海盗的传闻。由于他的船员们都在藏宝海湾忙着喝酒寻欢，他请求你去野人海岸附近的一个小海湾，打探血帆海盗的踪迹。",h="黑水强盗的大副克拉兹需要一位冒险者去调查有关敌对海盗的传闻。由于他的船员们都在藏宝海湾忙着喝酒寻欢，他请求你去野人海岸附近的一个小海湾，打探血帆海盗的踪迹。",kw={"黑水强盗","血帆海盗","藏宝海湾","通信","大副克拉兹","野人海岸","荆棘谷"},sec={{t="野人海岸的斥候",b="黑水强盗刚在藏宝海湾停靠，就听说他们的死对头——血帆海盗——在荆棘谷南部出没的消息。由于其他船员正沉迷于朗姆酒和岸上的享乐，大副克拉兹只能向外人求助。他让你沿着野人海岸向北走，去探查一个小海湾，看看血帆海盗究竟在搞什么鬼。"},{t="海湾的迹象",b="在搜索海湾时，你发现了一个木桶，上面放着一些钱币和一张画满潦草笔记的地图。"}},faq={{q="大副克拉兹是谁？",a="大副克拉兹是驻扎在藏宝海湾的黑水强盗的一名军官。面对敌对海盗的传闻和缺乏干劲的船员，他只能雇佣路过的冒险者去海岸侦察。",al={"大副克拉兹","谁给予任务","克拉兹是谁"}},{q="为什么大副克拉兹需要外人帮忙？",a="黑水强盗的船员才刚刚靠岸，他们正忙着在岸上寻欢作乐，根本无暇分身去进行任何侦察任务。",al={"为什么要雇佣冒险者","为什么他的船员不能去","为什么要帮助克拉兹"}},{q="克拉兹让你去哪里调查？",a="他指引你去侦察藏宝海湾以北，也就是被称为野人海岸的那片区域内的一个小海湾。",al={"我该去哪里","海湾在哪里","血帆海盗在哪里"}},{q="黑水强盗面临着怎样的敌对势力？",a="黑水强盗与血帆海盗之间有着深仇大恨，最近有人发现血帆海盗正在向荆棘谷南部大举扩张。",al={"谁是竞争对手","为什么要憎恨血帆海盗","血帆竞争"}}},fp="24,261,30.402.0,17.118.1,24.192.0,43.131.0,41.116.0,49.162.0"}
P.entries["quest:596"] = {n="染血的白骨项链",s="位于格罗姆高营地的肯维雷在荆棘谷另有打算，不仅仅是为了协助尼姆布亚。他试图通过收集鲜血头皮部族战士的战利品，来削弱这个敌对部族的力量。",h="位于格罗姆高营地的肯维雷在荆棘谷另有打算，不仅仅是为了协助尼姆布亚。他试图通过收集鲜血头皮部族战士的战利品，来削弱这个敌对部族的力量。",kw={"鲜血头皮","暗矛","格罗姆高","肯维雷","项链","尼姆布亚","荆棘谷"},ang={["faction:Horde"]="肯维雷被派往格罗姆高营地是为了协助尼姆布亚，并利用在那里待命的时间猎杀北方的鲜血头皮部族。",["race:Troll"]="对于暗矛部族来说，猎杀鲜血头皮部族是为了获得对敌对部族的控制力量。"},sec={{t="战争的战利品",b="尽管肯维雷来到格罗姆高营地这个丛林前哨是为了帮助尼姆布亚，但他仍有自己的私心。居住在北方的鲜血头皮巨魔是暗矛部族的敌人。肯维雷相信，从倒下的敌人身上获取私人战利品可以获得凌驾于他们之上的灵魂力量，因此他要求旅行者去猎杀鲜血头皮战士，并取下他们颈间佩戴的血色骨质项链。"},{t="汲取灵魂",b="在收到采集来的骨质饰品后，肯维雷打算将它们煮沸并萃取成糊状。通过这种仪式，他旨在直接枯竭并削弱鲜血头皮部族亡者的残余灵魂。"}},faq={{q="谁想要这些骨质项链？",a="肯维雷在荆棘谷的格罗姆高营地提供这项任务。尽管他被派往那里是为了协助尼姆布亚，但他利用这个营地来执行他自己的灵魂复仇计划。",al={"任务发布者","谁提供血色骨质项链任务","肯维雷任务"}},{q="为什么肯维雷想要鲜血头皮部族的战利品？",a="鲜血头皮部族是暗矛部族的死敌。肯维雷相信从死去的敌人身上获取战利品可以获得控制他们的力量，让暗矛部族确立对竞争对手的统治地位。",al={"为什么要收集项链","鲜血头皮项链的用途","为什么要猎杀鲜血头皮"}},{q="鲜血头皮部族在哪里？",a="鲜血头皮巨魔居住在格罗姆高营地以北的土地上，遍布荆棘谷北部。",al={"去哪里寻找鲜血头皮","鲜血头皮位置","巨魔在哪里"}},{q="这次狩猎之后会发生什么？",a="在这项任务之后，肯维雷会派遣冒险者去执行后续任务：分裂的骨质项链。",al={"下一个任务","血色骨质项链后续","血色骨质项链之后做什么"}}},fp="21,188,15.417.0,20.236.1,32.173.0,60.201.0,34.115.0,32.87.0"}
P.entries["quest:597"] = {n="血帆海盗",s="从血帆海盗那里缴获的信件里有一张藏宝海湾的地图，上面写着命令，要求他们在那处标记点建立一个隐秘的营地，并等待来自他们南方指挥所的信号后再发动进攻。",h="从血帆海盗那里缴获的信件里有一张藏宝海湾的地图，上面写着命令，要求他们在那处标记点建立一个隐秘的营地，并等待来自他们南方指挥所的信号后再发动进攻。",kw={"血帆海盗","血帆信件","藏宝海湾","大副克拉兹","南方指挥所","荆棘谷"},sec={{t="揭露阴谋",b="继你之前对血帆海盗的调查之后，一份截获的地图和书面命令揭示了海盗们的近期计划。藏宝海湾地图上的一个红色叉号标记了海盗们预定建立营地的确切地点。命令要求船员们悄悄驻守原地，消灭任何靠近的人，并等待从南方指挥所发出的进攻信号。"},{t="向港口汇报",b="将这些书面发现带回藏宝海湾，意味着直接向大副克拉兹报告情报，正是他当初派你去侦察的。海盗们显然是在等待进攻信号。"}},faq={{q="血帆海盗的信件上写了什么？",a="信件指示海盗船员在标记地点建立一个隐秘的营地，杀死任何靠近的人，并等待来自他们南方指挥所的信号以发动突袭。",al={"血帆计划书内容","字条上写了什么","血帆地图详情"}},{q="地图指向哪里？",a="这张缴获的藏宝海湾地图上有一个红色的叉号，那就是海盗们打算安营扎寨的地方。",al={"血帆地图叉号","红色叉号代表什么","营地在哪里"}},{q="谁需要了解这一发现？",a="这份情报必须直接报告给藏宝海湾的大副克拉兹，他还记得曾派你去侦察该区域。",al={"我该找谁交任务","谁会收到血帆地图","向大副克拉兹报告"}},{q="在找到这封信之前发生了什么？",a="这项调查直接承接大副克拉兹在藏宝海湾下达的关于血帆海盗的初始任务。",al={"前置任务","之前的血帆任务","血帆任务线起始"}}},fp="24,215,15.385.0,23.205.0,48.186.0,25.105.0,39.121.0,45.133.0"}
P.entries["quest:598"] = {n="裂骨项链",s="格罗姆高营地的肯维雷号召部落盟友去猎杀东南方的裂颅者部族。虽然暗矛巨魔已经离开了荆棘谷，但他们与这些丛林宿敌之间古老的冲突仍未解决。带回二十五条裂颅者骨项链将有助于暗矛巨魔的战争，并能赢得他们的友谊。",h="格罗姆高营地的肯维雷号召部落盟友去猎杀东南方的裂颅者部族。虽然暗矛巨魔已经离开了荆棘谷，但他们与这些丛林宿敌之间古老的冲突仍未解决。带回二十五条裂颅者骨项链将有助于暗矛巨魔的战争，并能赢得他们的友谊。",kw={"暗矛巨魔","格罗姆高营地","肯维雷","裂颅者","裂颅者骨项链","荆棘谷"},ang={["faction:Horde"]="在格罗姆高营地协助肯维雷进行针对裂颅者的战争，可以赢得暗矛巨魔的友谊。",["race:Troll"]="对于暗矛巨魔来说，从裂颅者那里获取战利品延续了一场漫长的战争，这场战争并没有随着部族离开荆棘谷而结束。"},sec={{t="一场未了的世仇",b="在收集了血顶巨魔的战利品后，肯维雷将注意力转向了另一个长期以来的敌人。裂颅者部族居住在格罗姆高营地的东南方，多年来他们一直与暗矛巨魔发生冲突。尽管暗矛巨魔不再居住在荆棘谷的丛林中，但他们依然被这场持久的战争所束缚。"},{t="战争的战利品",b="为了赢得暗矛部族的友谊和尊重，冒险者必须挺进裂颅者的领地，并夺取二十五条他们标志性的裂颅者骨项链。肯维雷以看到这些敌对巨魔像被蛇颈龙砍倒的幼苗一样被消灭而自豪，并将每一件回收的战利品视为对他的人民的一场胜利。"}},faq={{q="是谁提供了这次狩猎，他在哪里？",a="肯维雷在荆棘谷西海岸的部落前哨站格罗姆高营地提供这次狩猎任务。",al={"谁给予裂颅者骨项链任务","肯维雷位置","裂颅者骨项链任务发布者"}},{q="这项任务之前发生了什么？",a="这项任务是在“血顶骨项链”之后进行的，那是一次早期的狩猎，当时肯维雷指派冒险者从血顶部族那里收集战利品。",al={"裂颅者骨项链前置条件","裂颅者骨项链的前一个任务","上一步任务"}},{q="既然暗矛巨魔已经离开了荆棘谷，为什么他们还要与裂颅者作战？",a="暗矛巨魔和裂颅者在丛林中交战多年。尽管暗矛部族已经迁离了荆棘谷，但肯维雷解释说，他们仍然受到这场冲突的束缚，并决心让他们的敌人为当初的挑衅感到后悔。",al={"为什么暗矛巨魔憎恨裂颅者","裂颅者战争背景","暗矛巨魔与裂颅者的冲突"}},{q="在哪里可以找到裂颅者部族？",a="裂颅者居住在荆棘谷格罗姆高营地东南方的领地中。",al={"裂颅者位置","裂颅者在哪里","裂颅者营地"}},{q="肯维雷要求从这次狩猎中提供什么证明？",a="肯维雷要求从倒下的裂颅者巨魔身上直接获取二十五条裂颅者骨项链。",al={"肯维雷需要什么物品","裂颅者骨项链物品","需要多少条项链"}}},fp="19,345,16.374.0,15.336.0,46.111.0,27.152.0,79.275.0,43.108.0,48.101.0"}
P.entries["quest:599"] = {n="血帆海盗",s="大副克拉兹已经得知血帆海盗打算对藏宝海湾发动袭击。威胁的规模需要引起Blackwater Raiders指挥官舰队指挥官卡拉·海角的注意，他需要立即听到这个警告。",h="大副克拉兹已经得知血帆海盗打算对藏宝海湾发动袭击。威胁的规模需要引起Blackwater Raiders指挥官舰队指挥官卡拉·海角的注意，他需要立即听到这个警告。",kw={"blackwater raiders","血帆海盗","藏宝海湾","大副克拉兹","舰队指挥官卡拉·海角","荆棘谷"},sec={{t="给舰队指挥官的警告",b="在发现血帆海盗计划直接袭击藏宝海湾后，大副克拉兹意识到事情比他想象的要严重。他指示你寻找舰队指挥官卡拉·海角，他就在这个港口城市里的某个地方，并在敌对海盗采取行动之前通知他这场迫在眉睫的袭击。"},{t="海角的蔑视",b="当看到有关计划袭击的报告时，舰队指挥官卡拉·海角对这些敌对海盗的野心嗤之以鼻，宣称攻击藏宝海湾就像从眺望台悬崖跳下去一样愚蠢。尽管如此，他还是承认了这份情报的价值，并代表Blackwater Raiders向你表示感谢。"}},faq={{q="是谁派你去警告舰队指挥官卡拉·海角的？",a="大副克拉兹在得知血帆海盗针对该港口的敌对计划的严重性后，派你去警告卡拉·海角。",al={"谁开启了这个任务","大副克拉兹任务","血帆海盗任务发布者"}},{q="舰队指挥官卡拉·海角在哪里？",a="舰队指挥官卡拉·海角驻扎在荆棘谷南部的海盗避风港藏宝海湾内。",al={"卡拉·海角在哪里","卡拉·海角位置","舰队指挥官卡拉·海角城镇"}},{q="血帆海盗的计划是什么？",a="血帆海盗正在准备对藏宝海湾进行全面攻击，挑战Blackwater Raiders对该镇的统治。",al={"血帆海盗在做什么","血帆海盗攻击计划","血帆海盗阴谋"}},{q="哪个阵营控制着藏宝海湾？",a="藏宝海湾由Blackwater Raiders控制和运营，他们极力保护这个港口免受血帆海盗对手的侵害。",al={"谁管理藏宝海湾","藏宝海湾海盗阵营"}}},fp="24,254,30.306.0,18.301.1,43.129.0,40.102.0,41.132.0,33.116.0"}
P.entries["quest:6"] = {n="加瑞克·帕德弗特的赏金",s="“悬赏加瑞克·帕德弗特”是北郡修道院的维里副队长发布的一份联盟悬赏契约。契约指示年轻的新兵去搜捕一名臭名昭著的当地窃贼，此人一直在农场附近的一间偏僻棚屋骚扰艾尔文森林的农民和商人们。",h="“悬赏加瑞克·帕德弗特”是北郡修道院的维里副队长发布的一份联盟悬赏契约。契约指示年轻的新兵去搜捕一名臭名昭著的当地窃贼，此人一直在农场附近的一间偏僻棚屋骚扰艾尔文森林的农民和商人们。",kw={"悬赏","恶棍","艾尔文","加瑞克","北郡","帕德弗特","窃贼","农场","willem"},ang={["class:Rogue"]="对于潜行者来说，加瑞克·帕德弗特让他们初步了解了不法之徒如何在艾尔文森林的阴影中运作，同时也表明了藏匿不当的据点只会招致快刀。",["faction:Alliance"]="除掉加瑞克·帕德弗特是有志向的联盟冒险者为恢复暴风王国稳定所做的第一次直接服务之一。",["race:Human"]="对于在王国成长起来的人类来说，清除帕德弗特这样的恶棍是保护他们家园神圣土地和当地农民的私事。"},sec={{t="山谷之灾",b="北郡山谷曾被视为训练新兵和照料圣地农场的安全避难所，但最近艾尔文森林各地法律和秩序的崩溃使这里暴露在了危险之中。成群的窃贼潜入了山谷，一个名叫加瑞克·帕德弗特（Garrick Padfoot）的恶棍很快便纠集了他们。数周以来，加瑞克和他的团伙一直在劫掠货物、在路上抢劫商人，并威胁当地的农民。"},{t="维里副队长的正义",b="由于暴风城的守卫兵力分散在保卫首都和外围边界，当地的治安官和副队长们必须依靠热心的志愿者来维持北郡的和平。维里副队长发出了针对加瑞克的悬赏令，以彻底清除山谷中的这个团伙。在河东岸的简陋棚屋里除掉帕德弗特，是对渗透进人类核心地带的广泛无法无天现象的一次先发制人的打击。"}},faq={{q="加瑞克·帕德弗特是谁？",a="加瑞克·帕德弗特是一名在北郡山谷活动的强盗和恶棍。他花了数周时间骚扰当地农民并伏击商人，在他周围聚集了一小群暴徒，企图在农场附近占据地盘。",al={"加瑞克·帕德弗特","加瑞克是谁","帕德弗特"}},{q="在哪里可以找到加瑞克·帕德弗特？",a="他躲藏在北郡修道院东侧的一间小木棚里，穿过河上的桥，靠近农场的地方。他有同伙的暴徒守卫。",al={"加瑞克·帕德弗特在哪里","加瑞克位置","加瑞克的棚屋"}},{q="谁发布了针对加瑞克的悬赏？",a="驻扎在北郡修道院外的维里副队长发布了这份悬赏。由于缺乏足够的城市卫兵来维持山谷的治安，维里雇佣流浪的新兵来将此歹徒绳之以法。",al={"谁发布了针对加瑞克·帕德弗特的悬赏","维里的悬赏"}},{q="为什么暴风城不派正规士兵去处理他？",a="暴风城的军队兵力不足。随着瓦里安·乌瑞恩国王失踪，艾尔文森林及其他地区局势日益紧张，首都无法为每一个小混混分出资深驻军，只能让当地的副队长招募新兵。",al={"为什么守卫不杀加瑞克","暴风城的守卫在哪里"}},{q="加瑞克·帕德弗特是单独行动的吗？",a="不是。加瑞克身边围拢了一小群不法之徒和强盗，他们驻扎在他北郡农场附近的棚屋周围，以保护他。",al={"加瑞克是一个人吗","帕德弗特团伙"}},{q="维里副队长需要什么证据？",a="在支付赏金之前，维里副队长要求提供实物证据，具体来说就是需要你带回加瑞克·帕德弗特的头颅到北郡修道院。",al={"加瑞克死亡证明","加瑞克的头颅"}}},fp="25,166,22.328.0,23.381.0,23.180.0,35.143.0,33.178.0,63.235.0,33.132.0,38.124.0"}
P.entries["quest:60"] = {n="狗头人的蜡烛",s="“狗头人的蜡烛”是威廉·匹斯特在闪金镇的Lion's Pride Inn提供的一项早期任务。作为一名来自暴风城的炼金师，匹斯特需要狗头人头顶上那种大蜡烛的厚蜡，这些狗头人已经挤满了艾尔文森林的当地矿洞。对于冒险者来说，这是对这些侵蚀王国珍贵金矿脉的地下害虫的初步了解。",h="“狗头人的蜡烛”是威廉·匹斯特在闪金镇的Lion's Pride...",kw={"药剂师","蜡烛","艾尔文","法戈第","闪金镇","玉石","狗头人","蜡","威廉·匹斯特"},ang={["faction:Alliance"]="由于皇室军队因内部政治斗争和缺编的王室部队而兵力吃紧，保障当地基础设施的安全便落在了平民志愿者和往来的冒险者肩上。",["profession:Mining"]="为了收集蜡烛而清理狗头人，能将勘探者直接引入艾尔文森林最丰富的铜矿脉和金矿脉，这些矿脉此前已被人类矿工废弃。",["race:Human"]="收复被窃的艾尔文矿洞并为暴风城的本土工匠提供货物，是王国年轻臣民的早期职责。"},sec={{t="药剂师的跑腿",b="威廉·匹斯特与他的兄弟一起在暴风城的Trade District经营着匹斯特药剂店。在调制药剂、药膏和合剂时，像蜡这样的原材料总是供不应求。与其从城市商人那里采购精致的蜡烛，匹斯特意识到那些困扰艾尔文森林的害虫额头上顶着令人惊讶的、厚实的牛脂和蜡——如果冒险者愿意将其撬下来，这些材料唾手可得。"},{t="艾尔文的矿洞",b="狗头人已经彻底占据了闪金镇南部的法戈第矿洞和东北部的玉石矿洞。这些嗅来嗅去的地下生物几乎视蜡烛为生命，利用那摇曳的烛光在黑暗的矿井中穿行，挖掘金矿和闪亮的饰品。掠夺这些蜡烛不仅能满足匹斯特的炼金库存，还能削弱那些正在扼杀王国珍贵矿脉的害虫。"}},faq={{q="威廉·匹斯特为什么需要狗头人蜡烛？",a="威廉·匹斯特和他的兄弟在暴风城的Trade District经营着一家药剂店。他们使用从大蜡烛中提炼出的牛脂和蜡作为密封、药膏以及各种炼金制品的原料。",al={"匹斯特为什么想要蜡烛","蜡烛的用途","蜡烛的蜡的用途"}},{q="去哪里寻找大蜡烛？",a="蜡烛是由栖息在艾尔文森林矿洞中的狗头人苦工、害虫和挖掘者携带的，主要位于闪金镇南部的法戈第矿洞和东部的玉石矿洞内。",al={"哪里有狗头人蜡烛","蜡烛位置","如何获得大蜡烛"}},{q="为什么狗头人如此痴迷于蜡烛？",a="狗头人生活在漆黑的地下隧道中，依靠绑在头上的小火焰在挖掘时照明。他们对黑暗怀有一种近乎疯狂的迷信恐惧，并会拼死保护自己的蜡烛，不让任何人夺走。",al={"为什么狗头人有蜡烛","你不能拿走蜡烛是什么意思","狗头人蜡烛背景故事"}},{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位来自暴风城的人类商人和炼金师。当他不在城市Trade District的店铺工作时，他会前往闪金镇从往来的冒险者那里获取廉价材料。",al={"威廉·匹斯特是谁","威廉·匹斯特背景故事","闪金镇匹斯特"}},{q="这个任务与艾尔文森林的其他麻烦有关吗？",a="是的。法戈第矿洞和玉石矿洞的虫害对闪金镇和暴风城构成了重大的经济威胁。人类矿工已被驱逐，确保矿洞的安全是杜汉元帅的首要任务之一。",al={"艾尔文森林矿洞问题","为什么狗头人在矿洞里","闪金镇狗头人威胁"}},{q="艾尔文森林还有其他被狗头人占据的矿洞吗？",a="法戈第矿洞和玉石矿洞是闪金镇附近的两个主要地点，但狗头人的活动也蔓延到了森林的河岸边以及向东通往赤脊山的边界处。",al={"其他狗头人矿洞","艾尔文森林矿洞列表"}}},fp="14,312,20.381.0,19.389.0,44.190.0,36.160.0,41.248.0,22.192.0,52.209.0,56.181.0"}
P.entries["quest:600"] = {n="风险投资公司",s="在藏宝海湾，地精克兰克·菲兹巴布希望有人能打击荆棘谷地精在北荆棘谷的行动。他们在水晶矿洞附近的挖掘点源源不断地从附近的山丘中产出珍贵的歌唱蓝水晶，克兰克要求你带回十块这样的石头。",h="在藏宝海湾，地精克兰克·菲兹巴布希望有人能打击荆棘谷地精在北荆棘谷的行动。他们在水晶矿洞附近的挖掘点源源不断地从附近的山丘中产出珍贵的歌唱蓝水晶，克兰克要求你带回十块这样的石头。",kw={"藏宝海湾","克兰克·菲兹巴布","水晶矿洞","歌唱蓝水晶","荆棘谷","荆棘谷地精"},sec={{t="扰乱竞争",b="在你之前收集了歌唱蓝碎片之后，克兰克·菲兹巴布把目标指向了一个更大的竞争对手。荆棘谷地精在整个丛林中开展业务，侵占了独立地精的利润。虽然大量的蛇怪让矿工们无法踏入水晶矿洞，但工人们仍在周围的山坡上挖掘以提取歌唱蓝水晶。克兰克要求你从这些矿工手中夺取水晶，并将其带回藏宝海湾，作为他们受挫的证明。"},{t="水晶送达之后",b="虽然克兰克把这个请求说成是对无情卡特尔的正义报复，但当他看到收集来的歌唱蓝水晶时所表现出的兴奋，暴露了他真正的意图。他并非仅仅想让荆棘谷地精受挫，而是打算在藏宝海湾将这些回收的石头卖个大价钱。"}},faq={{q="谁发布了“扰乱竞争”任务？",a="在完成“歌唱蓝碎片”任务后，可以在藏宝海湾找到地精克兰克·菲兹巴布并接受该任务。",al={"谁发布了扰乱竞争任务","扰乱竞争任务发布者"}},{q="矿工们在什么地方挖掘这些水晶？",a="荆棘谷地精正在北荆棘谷的水晶矿洞附近作业，在矿洞周围的山丘上进行挖掘。",al={"扰乱竞争任务地点","荆棘谷水晶矿洞位置"}},{q="为什么荆棘谷地精的矿工不在矿洞里？",a="克兰克解释说，水晶矿洞里有大量的蛇怪，阻止了矿工进入，迫使他们只能在周边山丘上挖掘。",al={"为什么不去水晶矿洞里面","水晶矿洞蛇怪"}},{q="克兰克·菲兹巴布让你带给他什么？",a="他要求带回十块从在水晶矿洞附近作业的荆棘谷地精矿工手中夺来的歌唱蓝水晶。",al={"扰乱竞争任务需求物品","克兰克·菲兹巴布需要的物品"}},{q="“扰乱竞争”的前置任务是什么？",a="该任务序列的前一个任务是“歌唱蓝碎片”，克兰克会让你先在荆棘谷收集较小的水晶碎片。",al={"扰乱竞争任务链","扰乱竞争前置任务"}}},fp="22,304,26.502.0,25.304.1,43.101.0,48.135.0,54.152.0,47.106.0,40.138.0"}
P.entries["quest:6001"] = {n="身心之力",s="“身与心”是年轻暗夜精灵德鲁伊进行爪之教派入会仪式的终极考验。在达纳苏斯的玛斯雷·驭熊者的指导下，初学者必须前往黑海岸的荒野，召唤枭兽守护者月爪，在获得熊形态之前证明自己兼具内在的坚韧与武力。",h="“身与心”是年轻暗夜精灵德鲁伊进行爪之教派入会仪式的终极考验。在达纳苏斯的玛斯雷·驭熊者的指导下，初学者必须前往黑海岸的荒野，召唤枭兽守护者月爪，在获得熊形态之前证明自己兼具内在的坚韧与武力。",kw={"奥伯丁","熊形态","身与心","塞纳里奥月尘","爪之德鲁伊","月爪","玛斯雷·驭熊者","枭兽之石"},ang={["class:Druid"]="这项仪式代表了早期德鲁伊训练的决定性门槛，将新手施法者转变为能够承担起强大的熊形态的变形保护者。",["race:NightElf"]="对于暗夜精灵来说，与古老的野兽之灵沟通并尊崇黑海岸的神圣石块，重申了数千年前建立的塞纳里奥习俗。"},sec={{t="月爪的试炼",b="达纳苏斯的玛斯雷·驭熊者会指引暗夜精灵德鲁伊初学者前往奥伯丁海岸定居点以东的地区。在那里，藏在栖息着野生枭兽的天然洞穴中，坐落着一块古老的枭兽之石。通过将塞纳里奥月尘涂抹在这块神圣的巨石上，初学者可以唤醒月爪，这位守护着石头、并将挑战任何希望继承神圣之爪力量的祈求者的古老卫士。"},{t="身与心的力量",b="想要披上熊的斗篷，需要的远不止蛮力。虽然巨熊之灵传授了自然狂野的基础教诲，但与月爪的战斗考验的是初学者是否拥有驯服并驾驭这种原始力量所需的坚定内心。通过在战斗中战胜这位守护者并铭记灵魂残留的智慧，德鲁伊证明了自己已经准备好使用熊形态，而不会迷失在野兽的本能之中。"}},faq={{q="月爪是谁？",a="月爪是一只凶猛的枭兽灵魂守护者，栖息在黑海岸奥伯丁正东方的洞穴中。它保卫着神圣的枭兽之石，并会回应那些在圣物上撒下塞纳里奥月尘的初学者的召唤。",al={"什么是月爪","月爪背景故事","奥伯丁枭兽首领"}},{q="这个试炼的目的是什么？",a="这项通过仪式是暗夜精灵初学者寻求加入爪之德鲁伊行列的最终测试。征服月爪证明了初学者拥有获得熊之灵和熊形态所需的身体韧性和精神沉着的平衡。",al={"为什么要完成身与心任务","这个任务有什么用","熊形态任务背景"}},{q="谁给予这个任务？",a="玛斯雷·驭熊者，一位位于达纳苏斯塞纳里奥区的德鲁伊训练师长辈。一旦初学者与巨熊之灵沟通，他就会将这项试炼交给他们。",al={"身与心任务发布者","谁提供熊形态任务"}},{q="什么是塞纳里奥月尘？",a="塞纳里奥月尘是长辈们给予初学者的一种神圣仪式粉末。当撒在枭兽之石上时，其魔法属性会唤醒月爪并开启仪式战斗。",al={"什么是月尘","塞纳里奥月尘背景"}},{q="这项试炼在哪里进行？",a="试炼在黑海岸奥伯丁以东的一个洞穴中进行，那里有野生枭兽在一块古老的雕刻枭兽之石周围筑巢。",al={"枭兽之石在哪里","奥伯丁枭兽洞穴"}},{q="击败月爪后会发生什么？",a="在击败这个生物后，月爪的灵魂会显现在其躯体之上，给予祝福并认可这位德鲁伊在返回达纳苏斯之前所展现出的身与心的双重力量。",al={"击杀月爪后发生什么","月爪之灵"}}},fp="14,240,21.354.0,26.355.1,16.190.0,34.225.0,21.160.0,26.192.0,33.129.0,40.193.1"}
P.entries["quest:6002"] = {n="身心之力",s="“身与心”是牛头人德鲁伊学徒掌握熊形态的终极试炼。在雷霆崖的图拉克·符文图腾指引下，学徒必须前往莫高雷与贫瘠之地的交界处，在月光枭兽之石前召唤并击败月爪。",h="“身与心”是牛头人德鲁伊学徒掌握熊形态的终极试炼。在雷霆崖的图拉克·符文图腾指引下，学徒必须前往莫高雷与贫瘠之地的交界处，在月光枭兽之石前召唤并击败月爪。",kw={"贫瘠之地","熊形态","身与心","陶拉祖营地","赛纳里奥银尘","月爪","月光枭兽之石","莫高雷","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这一成人礼架起了暗夜精灵塞纳里奥教义与牛头人传统之间的桥梁，使年轻的德鲁伊终于能够展现出熊形态那凶猛的韧性。",["faction:Horde"]="牛头人德鲁伊为部落的前线带来了至关重要的韧性，将部落的魔法力量根植于深厚的荒野守护之中。",["race:Tauren"]="对于舒哈鲁人来说，唤醒心中的熊既是与自然之灵的神圣沟通，也是保护莫高雷平原免受威胁的切实手段。"},sec={{t="利爪之道",b="为了真正走上利爪德鲁伊之路，牛头人学徒必须将精神信念与肉体韧性结合起来。在月光林地与伟大熊灵沟通后，德鲁伊的训练便迎来了一次实战考验。雷霆崖长者高地上的资深德鲁伊训练师图拉克·符文图腾会将赛纳里奥银尘赐予有资格的学徒，并指引他们前往莫高雷与贫瘠之地接壤的荒芜边境寻找一块神圣之石。"},{t="月爪的试炼",b="月光枭兽之石位于陶拉祖营地以西，是卡利姆多南部一处罕见的塞纳里奥遗迹。月光枭兽并非卡利姆多中部烈日灼烤平原的原生物种，因此守护兽月爪在此出现意义深远。德鲁伊将银尘洒在古老的纪念碑上，便能召唤月爪进行战斗。击败这只生物证明了学徒既有强健的体魄，又有清澈的心灵，从而赢得了野兽的祝福，解开了熊的内在精髓。"}},faq={{q="这项试炼的目的是什么？",a="这项任务是部落德鲁伊获得熊形态的最后一步。完成这一挑战，即证明了你有资格在图拉克·符文图腾的教导下承担起利爪德鲁伊的职责。",al={"为什么要进行身与心试炼","身与心试炼有什么作用","完成身与心试炼有什么奖励"}},{q="月光枭兽之石在哪里？",a="月光枭兽之石位于贫瘠之地，陶拉祖营地以西，通往莫高雷大门的道路旁。在那条路南边，一顶孤零零的帐篷旁，藏在树后便是那块神圣之石。",al={"月光枭兽之石的位置","月光枭兽之石在哪里","如何找到月光枭兽之石"}},{q="月爪是谁？",a="月爪是一只凶猛的月光枭兽守护者，与月光枭兽之石绑定。它可以通过赛纳里奥银尘召唤出来，旨在测试德鲁伊是否拥有运用熊之力所必需的原始韧性和情绪自控力。",al={"月爪是谁","什么是月爪"}},{q="如果我在与月爪的战斗中失败了怎么办？",a="如果你被击败，你的赛纳里奥银尘就会消耗掉。你必须回到雷霆崖长者高地找图拉克·符文图腾领取另一袋银尘，然后才能再次进行召唤。",al={"月爪挑战失败","银尘丢失","死于月爪之手"}},{q="月光枭兽是贫瘠之地的原生物种吗？",a="不是。正如图拉克·符文图腾所言，月光枭兽并非贫瘠之地或莫高雷的原生生物。这种生物出现在稀树草原上显得很不自然，它们与塞纳里奥仪式和古老的天界力量遗迹有着特殊的联系。",al={"贫瘠之地有月光枭兽吗","为什么这里会有月光枭兽","贫瘠之地的月光枭兽"}},{q="谁发放“身与心”任务？",a="该任务由位于雷霆崖长者高地的资深德鲁伊训练师图拉克·符文图腾发放，就在学徒从月光林地归来之后。",al={"谁发放身与心任务","身与心任务发放人"}}},fx={["928957c5"]={q="为什么图拉克·符文图腾要你去面对月爪？",a="图拉克·符文图腾是你在雷霆崖的导师，他必须确保你已做好准备，踏上利爪德鲁伊之路。德鲁伊不能直接得到变形为熊的奥秘；你必须证明自己既有坚韧的内心，也有驾驭熊形态原始力量所需的体魄。只有召唤并战胜月爪，证明自己身心足够强大，他才会教导你。",al={"图拉克·符文图腾的动机","为什么要打败月爪","图拉克试炼的目的"}},ac0863bb={q="为什么必须独自完成这场试炼，而不是派卫兵去？",a="这是你作为一名见习德鲁伊，在自身精神旅程中必须经历的神圣成年礼。图拉克不能代你完成仪式，雷霆崖的勇士也无法相助，因为试炼的目的不是消灭威胁，而是领悟精神上的教诲。月爪带来力量的沟通，只有通过你亲自与守护者较量，考验自己的平衡、决心和信念，才能赢得。",al={"为什么身心试炼由我参加","为什么我必须独自迎战月爪","卫兵能帮忙对付月爪吗"}}},fp="14,256,19.461.0,21.507.0,34.205.0,35.199.0,16.218.0,51.201.0,34.205.0,35.155.0"}
P.entries["quest:601"] = {n="水元素",s="在有了关于海潮之石的发现后，大财主里维加兹一直在寻找对抗该神器诅咒的方法。他派遣冒险者重返岛屿，从召唤出的水元素身上收集护腕，以便专家能检查其上的魔法残余。",h="在有了关于海潮之石的发现后，大财主里维加兹一直在寻找对抗该神器诅咒的方法。他派遣冒险者重返岛屿，从召唤出的水元素身上收集护腕，以便专家能检查其上的魔法残余。",kw={"藏宝海湾","护腕","诅咒","达拉然","加兹班","里维加兹","海潮之石","水元素"},sec={{t="遏制诅咒",b="大财主里维加兹认为这些水元素是由地精法师加兹班召唤的，并怀疑它们身上的魔法残余隐藏着处理海潮之石的关键线索。据说这块石头会诅咒任何持有它的人，使持有者在现实中忽隐忽现。为了找到对策，里维加兹指引你重返近海岛屿，收集元素护腕，以便达拉然的博学法师们进行研究。"},{t="藏宝海湾的主人",b="在收到护腕后，里维加兹承认他缺乏专业的知识来判断它们是否有用。他并不打算亲自前往达拉然——他可不愿为了和那帮讨厌的老法师闲聊而离开藏宝海湾——于是他派遣你前往北方，请一位法师来鉴定它们。"}},faq={{q="谁想要这些水元素护腕？",a="藏宝海湾黑水强盗的领袖大财主里维加兹需要这些护腕，以调查围绕着海潮之石的魔法。",al={"谁给予水元素任务","大财主里维加兹任务","谁想要护腕"}},{q="大财主里维加兹为什么需要元素护腕？",a="他希望研究护腕上的魔法残余能揭示出对抗海潮之石诅咒的方法，这种诅咒会导致持有者在现实中忽隐忽现。",al={"为什么要收集护腕","水元素护腕的用途","海潮之石的诅咒"}},{q="是谁召唤了这些水元素？",a="大财主里维加兹认为它们是由加兹班召唤的，据传这位地精法师发现了海潮之石。",al={"谁召唤了元素","加兹班背景","地精法师"}},{q="这项任务接下去要做什么？",a="接下来是魔法分析：里维加兹会将护腕送往北方的达拉然，让法师检查上面的残余。",al={"水元素任务之后是什么","下一个任务","护腕会被送到哪里"}},{q="为什么里维加兹不亲自将护腕送到达拉然？",a="他不想为了和那帮讨厌的老法师闲聊而离开藏宝海湾，而且他坚称自己无惧任何潜在的竞争对手。",al={"里维加兹为什么不去","里维加兹 达拉然","为什么要留在藏宝海湾"}}},fp="16,262,17.440.0,18.277.0,38.144.0,47.185.0,36.112.0,31.109.0,57.131.0"}
P.entries["quest:602"] = {n="魔法分析",s="大财主里维加兹指引你从藏宝海湾向北出发，去达拉然咨询肯瑞托。你带着一袋水元素护腕，前往寻找大法师安斯雷姆·鲁因维沃尔，以破译与海潮之石有关的奥术诅咒。",h="大财主里维加兹指引你从藏宝海湾向北出发，去达拉然咨询肯瑞托。你带着一袋水元素护腕，前往寻找大法师安斯雷姆·鲁因维沃尔，以破译与海潮之石有关的奥术诅咒。",kw={"大法师安斯雷姆·鲁因维沃尔","大财主里维加兹","藏宝海湾","达拉然","古拉巴什帝国","魔法分析","海潮之石","水元素护腕"},ang={["class:Mage"]="将奥术神器交给肯瑞托的大法师很适合法师，正如大财主里维加兹自己所说，法师无法抗拒魔法谜题。"},sec={{t="前往达拉然的请求",b="在你搜集完水元素护腕后，大财主里维加兹交给你一捆护腕。这位地精领袖知道，想要解开海潮之石背后的诅咒，需要比藏宝海湾所能提供的更深奥的魔法知识。他指引你向北前往达拉然的废墟，那里的法师们正忙于重建他们破碎的王国。里维加兹确信奥术学者无法抗拒这种引人入胜的谜题，因此建议你直接去寻找大法师安斯雷姆·鲁因维沃尔，因为他过去曾与这位知识渊博的法师有过往来。"},{t="大法师的学识",b="在达拉然繁忙的重建工作中找到安斯雷姆·鲁因维沃尔后，这位忙碌的大法师在听说这件遗物时停下了手中的工作。多年前，鲁因维沃尔曾撰写过一篇关于古拉巴什帝国古代传说的学术论文，这使他对该遗物的历史有着罕见的深刻见解。在检查这些护腕时，他发现了适合研究的微量魔法残留，于是放下手头的工作，开始揭开这些附魔中隐藏的秘密。"}},faq={{q="是谁派你去达拉然进行这项研究的？",a="藏宝海湾的大财主里维加兹给了你那袋元素护腕，并指示你去咨询达拉然的法师们。",al={"谁提供魔法分析","魔法分析任务发布者","谁开始魔法分析"}},{q="为什么大财主里维加兹选择了大法师安斯雷姆·鲁因维沃尔？",a="里维加兹以前和鲁因维沃尔打过交道，深知这位大法师知识渊博；他也相信法师们无法抗拒魔法谜题。",al={"为什么是安斯雷姆","里维加兹与安斯雷姆的关系","为什么是大法师安斯雷姆·鲁因维沃尔"}},{q="在前往达拉然之前发生了什么？",a="这个任务紧接着“水元素”任务，你在该任务中为大财主里维加兹收集了水元素护腕。",al={"前置任务","魔法分析前置条件","什么任务引导至此"}},{q="在找到大法师之后接下来要做什么？",a="交出护腕后，任务将引导至“安斯雷姆的钥匙”。",al={"后续任务","魔法分析之后是什么","交付护腕后"}}},fp="16,231,17.569.0,19.405.1,40.119.0,57.143.0,41.113.0,44.51.0"}
P.entries["quest:6027"] = {n="上古之书",s="位于艾瑟雷索高塔的阿佐尔·奥达蒙特托付给你一颗宝石。将它安放在拉纳加尔岛上一座蛇形雕像的手中，那座岛就在高塔的西北方，它会召唤出《古人之书》的守护者。这本书里记载着纳迦数个世纪以来保守的秘密。",h="位于艾瑟雷索高塔的阿佐尔·奥达蒙特托付给你一颗宝石。将它安放在拉纳加尔岛上一座蛇形雕像的手中，那座岛就在高塔的西北方，它会召唤出《古人之书》的守护者。这本书里记载着纳迦数个世纪以来保守的秘密。",kw={"阿佐尔·奥达蒙特","古人之书","艾瑟雷索","毒蛇宝石","纳迦","拉纳加尔岛","蛇形雕像"},sec={{t="蛇形雕像",b="在完成“光之权杖”任务后，阿佐尔·奥达蒙特会交给你毒蛇宝石。在艾瑟雷索高塔西北方的一座小岛——拉纳加尔岛上，矗立着一座蛇形雕像，这颗宝石需要安放在它的手上。这样做会引出《古人之书》的守护者，这本书里记载着纳迦数个世纪以来保守的秘密。阿佐尔希望它能让我们更多地了解这些鳞片敌人。"}},faq={{q="阿佐尔·奥达蒙特是谁？",a="艾瑟雷索高塔的看守者，他希望了解更多关于纳迦的信息，阿佐尔称他们为“鳞片敌人”。",al={"阿佐尔·奥达蒙特","谁给予古人之书任务","艾瑟雷索高塔的人"}},{q="什么是《古人之书》？",a="一本记载了纳迦数个世纪以来保守秘密的书籍。有人在守护着它。",al={"什么是古人之书","书籍背景","凄凉之地纳迦之书"}},{q="拉纳加尔岛在哪里？",a="位于艾瑟雷索高塔西北方的一座小岛。",al={"拉纳加尔岛位置","拉纳加尔岛在哪里","带着宝石去哪"}},{q="毒蛇宝石有什么用？",a="将它安放在拉纳加尔岛上的蛇形雕像手中，便会引出《古人之书》的守护者。",al={"毒蛇宝石","蛇形雕像的手","如何召唤守护者"}},{q="在此之前发生了什么？",a="在此步骤之前是“光之权杖”任务。",al={"前置任务","光之权杖任务线","先决条件"}}},fp="20,250,18.378.0,22.110.0,33.81.0,23.51.0,35.113.0,22.47.0"}
P.entries["quest:603"] = {n="安斯雷姆的钥匙",s="经过魔法测试后，大法师安斯雷姆·鲁因维沃尔指出了这把上古巨魔匕首，它能够干扰增强海潮之石的聚焦祭坛。很久以前，他把这把匕首交给了他的女儿凯特琳，一个倔强的女孩，她为了加入藏宝海湾的海盗而离家出走。",h="经过魔法测试后，大法师安斯雷姆·鲁因维沃尔指出了这把上古巨魔匕首，它能够干扰增强海潮之石的聚焦祭坛。很久以前，他把这把匕首交给了他的女儿凯特琳，一个倔强的女孩，她为了加入藏宝海湾的海盗而离家出走。",kw={"安斯雷姆","藏宝海湾","凯特琳","匕首","鲁因维沃尔","海潮之石","巨魔遗物"},sec={{t="误入歧途的女儿",b="安斯雷姆·鲁因维沃尔断定，有一个祭坛或焦点正在放大海潮之石的力量。要压制这种魔法，需要另一件巨魔遗物：一把他在荆棘谷研究时发现的上古匕首。很久以前，他把这把匕首交给了他的女儿凯特琳，一个倔强的女孩，她为了加入藏宝海湾的海盗而离家出走。"},{t="缴械的战士",b="抵达藏宝海湾后发现，匕首已经不在凯特琳的腰间了。她曾是这个定居点最犀利的刀客，但在与一名血帆海盗的决斗中战败了。胜者将那把巨魔刀刃当作战利品抢走，让她落得个被缴械、受羞辱的下场，还遭到了其他海盗同伙的冷嘲热讽。"}},faq={{q="为什么大法师安斯雷姆需要那把巨魔匕首？",a="持有海潮之石的法师正通过一座祭坛引导其魔法。安斯雷姆打算通过压制来干扰这种能量增强，而他知道一把上古巨魔匕首可以做到这一点。",al={"为什么需要匕首","安斯雷姆之钥的目的","匕首的用途"}},{q="凯特琳是谁？",a="凯特琳是大法师安斯雷姆·鲁因维沃尔那倔强的女儿。她抛下了父亲，跑到藏宝海湾过起了海盗生活。",al={"凯特琳是谁","安斯雷姆的女儿","利刃凯特琳"}},{q="安斯雷姆最初是在哪里找到这把匕首的？",a="安斯雷姆是在荆棘谷的丛林中进行研究时发现了这件遗物，随后将其交给了女儿。",al={"匕首的起源","安斯雷姆在哪里找到的匕首"}},{q="在哪里可以找到凯特琳？",a="她住在荆棘谷南端的藏宝海湾，那是一处海盗避风港。",al={"凯特琳在哪里","凯特琳的位置"}}},fp="13,282,18.332.0,18.332.1,48.201.0,15.147.0,45.124.0,27.92.0"}
P.entries["quest:604"] = {n="血帆海盗",s="舰队指挥官卡拉·海角信任黑水强盗的忠实盟友，委托其突袭血帆海盗在蛮荒海岸所谓的南方指挥所。夺回他们的海图和书面计划书将揭示这些海盗到底在谋划什么。",h="舰队指挥官卡拉·海角信任黑水强盗的忠实盟友，委托其突袭血帆海盗在蛮荒海岸所谓的南方指挥所。夺回他们的海图和书面计划书将揭示这些海盗到底在谋划什么。",kw={"黑水强盗","血帆海盗","血帆海图","血帆计划书","藏宝海湾","舰队指挥官卡拉·海角","蛮荒海岸"},sec={{t="突袭蛮荒海岸",b="在完成了克拉兹早先的任务后，舰队指挥官卡拉·海角注意到了你对黑水强盗的忠诚。血帆海盗在蛮荒海岸建立了他们所谓的南方指挥所。卡拉·海角指派你去突袭这个营地，消灭他们的剑客，并夺取他们的航海图和书面计划书，以便舰队能够了解他们的企图。"},{t="揭露海盗的阴谋",b="拿到海图和计划书后，卡拉·海角了解了血帆海盗的计划，并断定这伙海盗已经在海角附近抛锚驻扎。"}},faq={{q="谁发布了这个突袭任务？",a="在听闻克拉兹对你的奉献精神大加赞赏后，舰队指挥官卡拉·海角在藏宝海湾发布了这项任务。",al={"谁发布了血帆海盗任务","卡拉·海角任务"}},{q="血帆海盗的指挥所在哪里？",a="血帆海盗在荆棘谷藏宝海湾南部的蛮荒海岸建立了他们的南方指挥营地。",al={"血帆南方指挥所位置","蛮荒海岸在哪里"}},{q="从血帆营地需要取回什么物品？",a="卡拉·海角要求取回血帆海图和他们的书面血帆计划书，以解读这些敌对海盗的意图。",al={"卡拉·海角需要什么文件","血帆计划书和海图"}},{q="为什么舰队指挥官卡拉·海角想要他们的海图和计划书？",a="卡拉·海角想要确切地了解血帆海盗到底在策划什么。",al={"为什么要突袭蛮荒海岸","卡拉·海角想要知道什么"}}},fp="24,248,22.372.0,29.133.1,22.112.0,44.118.0,52.124.0,59.69.0"}
P.entries["quest:605"] = {n="歌唱水晶碎片",s="克兰克·菲兹巴布正在寻找一位有进取心的冒险者，从荆棘谷的石化蜥蜴身上收集歌唱水晶碎片。与荆棘谷地精的竞争使他无法直接开采矿床，因此石化蜥蜴皮成了次优选择。他承诺将利润的一部分分给任何愿意为他带来十个合格样本的人。",h="克兰克·菲兹巴布正在寻找一位有进取心的冒险者，从荆棘谷的石化蜥蜴身上收集歌唱水晶碎片。与荆棘谷地精的竞争使他无法直接开采矿床，因此石化蜥蜴皮成了次优选择。他承诺将利润的一部分分给任何愿意为他带来十个合格样本的人。",kw={"石化蜥蜴","克兰克·菲兹巴布","歌唱蓝色水晶","歌唱水晶","荆棘谷","荆棘谷地精","祖昆达"},sec={{t="有利可图的机会",b="克兰克·菲兹巴布发现荆棘谷独有的歌唱水晶市场非常广阔。但不幸的是，荆棘谷地精的强势存在让他难以在野外直接收集原始水晶。为了绕过他的竞争对手，菲兹巴布转向了一种替代方法：石化蜥蜴会吞食这些水晶，并将其矿物质融入到它们坚硬的皮中，从而可以从它们身上获得可用的碎片。"},{t="海岸狩猎",b="虽然丛林中的任何石化蜥蜴都可能掉落合适的水晶碎片，但菲兹巴布说，在祖昆达以南、北部海岸一带能找到更温顺的石化蜥蜴。收集到十个碎片后，他就可以继续与买家进行交易，此后他的商业重心将转向荆棘谷地精的行动本身。"}},faq={{q="克兰克·菲兹巴布为什么要歌唱水晶碎片？",a="歌唱水晶是荆棘谷独有的，对某些特定的买家来说非常有价值。克兰克·菲兹巴布说他可以将其出售，并承诺分给冒险者一部分利润。",al={"为什么需要歌唱水晶","克兰克·菲兹巴布的目的","歌唱水晶的用途"}},{q="为什么克兰克·菲兹巴布不能直接开采水晶？",a="菲兹巴布将原因归咎于荆棘谷地精，认为他们让像他这样的诚实商人很难亲自收集原始水晶。",al={"为什么要杀石化蜥蜴","荆棘谷地精的问题","为什么不能直接开采水晶"}},{q="为什么石化蜥蜴会有这些水晶？",a="荆棘谷的石化蜥蜴以这些水晶为食，水晶会逐渐融入它们的皮中，使它们长出坚硬的岩石状皮肤。",al={"石化蜥蜴与水晶的背景故事","为什么石化蜥蜴会掉落水晶"}},{q="克兰克·菲兹巴布建议在哪里寻找石化蜥蜴？",a="菲兹巴布说任何石化蜥蜴都能产出碎片，但更温顺的石化蜥蜴生活在祖昆达以南的北部海岸沿线。",al={"哪里可以找到碎片","石化蜥蜴的位置","祖昆达的石化蜥蜴"}},{q="上交碎片后会发生什么？",a="在收到十个碎片后，菲兹巴布会支付承诺的利润分成，并将注意力直接转向荆棘谷地精的活动。",al={"完成歌唱蓝色水晶后的后续","歌唱蓝色水晶后续任务"}}},fp="19,354,23.463.0,17.321.0,53.163.0,57.121.0,37.142.0,57.118.0,41.159.1"}
P.entries["quest:606"] = {n="吓唬病鬼",s="“海狼”马克基雷无法忍受未偿还的赌债，而且很多人都欠他的钱。首先就是藏宝海湾码头附近的“病鬼”菲利普，他在上周的赌局中还欠下一大笔钱。马克基雷的计划是恐吓一下，利用年长的迷雾谷大猩猩的杂碎。",h="“海狼”马克基雷无法忍受未偿还的赌债，而且很多人都欠他的钱。首先就是藏宝海湾码头附近的“病鬼”菲利普，他在上周的赌局中还欠下一大笔钱。马克基雷的计划是恐吓一下，利用年长的迷雾谷大猩猩的杂碎。",kw={"藏宝海湾","赌债","迷雾谷杂碎","迷雾谷大猩猩","恐吓“病鬼”","“海狼”马克基雷","“病鬼”菲利普","荆棘谷"},sec={{t="收债",b="“海狼”马克基雷无法容忍未偿还的赌债，有很多人都欠他的钱。其中首当其冲的就是“病鬼”菲利普，他就在码头附近，他在上周的赌局中欠下了巨额债务。收债的方法就是恐吓菲利普。你被派到城外去猎杀年长的迷雾谷大猩猩，并带回一大堆杂碎交给菲利普。马克基雷希望保密这些杂碎来自动物，好让菲利普往最坏处想。"},{t="菲利普的反应",b="菲利普对那些杂碎感到退缩，也不想知道它们是从哪里来的。然后，菲利普询问是不是“海狼”派你来的。"}},faq={{q="谁是“海狼”马克基雷？",a="马克基雷被许多人欠着赌债，他想要人帮忙收债，首先就是从“病鬼”菲利普开始。",al={"马克基雷是谁","“海狼”马克基雷","谁给予恐吓“病鬼”任务"}},{q="为什么马克基雷要恐吓“病鬼”菲利普？",a="菲利普在上周的赌局中还欠马克基雷一大笔钱，而马克基雷认为恐吓一下是讨债的好办法。",al={"为什么要恐吓“病鬼”","“病鬼”菲利普的债务","为什么要针对菲利普"}},{q="什么生物会掉落这些杂碎？",a="年长的迷雾谷大猩猩，马克基雷说它们在城外。",al={"杂碎从哪里来","迷雾谷杂碎来源","为了杂碎要杀什么"}},{q="哪里可以找到“病鬼”菲利普？",a="在藏宝海湾的码头边。",al={"“病鬼”菲利普在哪里","“病鬼”的位置","寻找“病鬼”菲利普"}},{q="关于这些杂碎，你应该告诉菲利普什么？",a="什么都别说。马克基雷希望菲利普往最坏处想，所以不能提这些杂碎是来自动物的。",al={"我需要告诉“病鬼”杂碎的来源吗"}}},fp="13,261,17.438.0,19.125.1,28.111.0,50.118.0,35.69.0,36.31.0,48.109.0"}
P.entries["quest:6061"] = {n="驯服野兽",s="Taming the Beast是血蹄村年轻牛头人猎人的基础成年仪式。在训练师雅文·刺鬃的指导下，猎人会深入莫高雷去驯服一只成年平原陆行鸟，这是与大地母亲的生物建立精神纽带的第一步。",h="Taming the Beast是血蹄村年轻牛头人猎人的基础成年仪式。在训练师雅文·刺鬃的指导下，猎人会深入莫高雷去驯服一只成年平原陆行鸟，这是与大地母亲的生物建立精神纽带的第一步。",kw={"血蹄村","大地母亲","猎人任务","莫高雷","平原陆行鸟","驯服","驯兽棒","雅文·刺鬃"},ang={["class:Hunter"]="这项仪式标志着从初出茅庐的追踪者向真正的兽王转变，教导你如何在大地母亲的指引下与动物交流。",["race:Tauren"]="驯服野兽是莫高雷游牧狩猎传统中的核心祖先实践，它加强了猎人与自然之间的纽带。"},sec={{t="与荒野的神圣纽带",b="对牛头人来说，狩猎从来不仅仅是为了肉和皮毛而猎杀野兽。祖先的传统认为，征服并与莫高雷的野生动物交流，可以让猎人吸收它们的精神，从而更接近大地母亲。驯服一头伴侣野兽升华了这种联系，将原本可能是对手的生物变成与平原的自然平衡相一致的终身伙伴。"},{t="初次试炼",b="雅文·刺鬃对新手的指导并不是从凶猛的顶级掠食者开始，而是从漫步在莫高雷草原上敏捷且警觉的平原陆行鸟开始。猎人带着一根附魔的驯兽棒，必须面对一只成年平原陆行鸟，平复它野性的本能，并赢得它的信任。这次初期的试炼旨在证明猎人的决心，并为他们后续更具挑战性的驯服任务做好准备。"}},faq={{q="这项试炼的目的是什么？",a="这个任务是初出茅庐的牛头人猎人学习动物伙伴艺术的第一次实践测试。通过使用驯兽棒来安抚一只成年平原陆行鸟，猎人可以学习与野兽建立精神和工作联系的基本原则。",al={"为什么要驯服平原陆行鸟","任务目的","牛头人宠物任务目的"}},{q="谁发布了这个任务，他们在哪里？",a="该任务由位于莫高雷中部平原血蹄村的猎人训练师雅文·刺鬃发布。",al={"谁发布任务","任务发布者位置","雅文·刺鬃位置"}},{q="我会永久保留这只成年平原陆行鸟吗？",a="不会。在雅文·刺鬃最初的三次试炼中驯服的野兽只是临时的练习伙伴。当你完成整个训练链并掌握驯服野兽的技巧后，你就可以出去永久驯服任何兼容的伴侣了。",al={"宠物是永久的吗","我会保留平原陆行鸟吗","任务后保留野兽"}},{q="为什么牛头人认为驯服野兽是一种精神行为？",a="牛头人的传统教导说，与野生生物互动并战胜它们，可以让猎人吸收它们的精神，并与自然世界合而为一。驯服一头野兽体现了对大地母亲创造物的相互尊重与团结。",al={"牛头人宠物知识","大地母亲驯服知识","为什么牛头人要驯服野兽"}},{q="在哪里可以找到成年平原陆行鸟？",a="成年平原陆行鸟广泛分布在莫高雷血蹄村周围起伏的稀树草原和山谷中。",al={"平原陆行鸟在哪里","平原陆行鸟位置","寻找成年平原陆行鸟"}},{q="这个任务之后是什么？",a="将驯兽棒交还给雅文·刺鬃会开启下一个试炼，任务要求你驯服一只潜伏者，接着是一只攻击性更强的峭壁鸟，之后才能学习永久驯服野兽的艺术。",al={"下一步是什么","后续任务链","驯服的下一步"}}},fx={fd2667bc={q="为什么雅文·刺鬃要我驯服一只平原陆行鸟？",a="雅文·刺鬃正在引导你了解牛头人猎人的神圣传统。对牛头人而言，战胜并驯服野兽是一种精神修行，能让猎人更加亲近大地母亲，并与自然和谐共处。他让你从莫高雷敏捷的成年平原陆行鸟开始训练，以便在与永久伙伴结下羁绊前，掌握所需的耐心和精神专注。",al={"为什么驯服平原陆行鸟","雅文·刺鬃的动机","为什么选成年平原陆行鸟"}},fe0439d7={q="为什么雅文·刺鬃让我接受这场试炼，而不是他自己去做？",a="这是每位见习猎人都必须亲自经历的成年礼。雅文·刺鬃是经验丰富的导师，肩负传授祖先习俗的职责，而不是替你完成任务。驯服野兽需要你亲自与自然建立精神联系，并敞开心扉感受大地母亲的存在。任何长者或卫兵都无法代你建立这种羁绊。",al={"为什么派我去","雅文·刺鬃为什么需要我","为什么必须驯服野兽"}}},fp="16,289,27.405.0,14.390.0,34.268.0,48.125.0,45.233.0,52.239.0,39.118.0,28.198.0"}
P.entries["quest:6062"] = {n="驯服野兽",s="这个试炼标志着年轻的部落猎人向驯兽艺术迈出了第一步。在剃刀岭的资深猎人索塔尔的指导下，初出茅庐的猎人们使用一根附魔驯兽棒来制服并驯化一头凶猛的杂斑野猪。",h="这个试炼标志着年轻的部落猎人向驯兽艺术迈出了第一步。在剃刀岭的资深猎人索塔尔的指导下，初出茅庐的猎人们使用一根附魔驯兽棒来制服并驯化一头凶猛的杂斑野猪。",kw={"杂斑野猪","杜隆塔尔","猎人任务","宠物驯服","剃刀岭","驯兽棒","索塔尔"},ang={["class:Hunter"]="这项成人礼架起了从一名普通神射手到真正野兽大师之间的桥梁，解锁了猎人与动物同伴之间决定性的羁绊。",["race:Orc"]="对于兽人来说，指挥野兽体现了意志的力量和对杜隆塔尔新家园恶劣荒野的掌控力。",["race:Troll"]="暗矛猎人利用这种训练将他们的精神与卡利姆多崎岖的野生动物相协调，延续他们古老的追踪传统。"},sec={{t="猎人的成人礼",b="对于在杜隆塔尔成年的兽人和暗矛巨魔猎人来说，独自在荒野中生存仅仅是考验的一半。一名真正的荒野大师必须学会对自然本身施加权威，将敌对的野兽变成忠诚的盟友。猎人训练师索塔尔将一根附魔驯兽棒交给新手，并要求他们面对一头凶猛的野猪，而不使用致命的箭矢。"},{t="杜隆塔尔的野猪",b="杂斑野猪游荡在剃刀岭周围干旱的灌木丛中。虽然它们粗野且脾气暴躁，但其韧性和凶猛使它们成为理想的入门驯服对象。在引导驯兽棒力量的同时，承受它们的冲锋和暴躁，需要耐心和钢铁般的意志——这是任何部落追踪者必备的品德。"}},faq={{q="这项试炼的目的是什么？",a="这是年轻猎人在杜隆塔尔进行的第一次实践测试，教导他们如何通过驯兽棒引导自己的意志来制服野兽，而不是仅仅将其杀死。",al={"为什么要完成这个任务","驯服野猪任务的原因","taming the beast的任务重点"}},{q="谁发布这个任务？",a="一旦你在杜隆塔尔证明了自己的基本生存技能，驻扎在剃刀岭的猎人训练师索塔尔就会提供这项任务。",al={"任务发布者","谁发布了taming the beast","在哪里获得野猪任务"}},{q="在哪里可以找到杂斑野猪？",a="杂斑野猪可以在杜隆塔尔中部剃刀岭的栅栏外干旱的灌木丛中找到。",al={"野猪位置","杂斑野猪在哪里","在哪里寻找野猪"}},{q="完成任务后我可以永久保留这头野猪吗？",a="不能。在这个初步练习中驯服的野猪仅用于练习。一旦归还给索塔尔，它就会离开，因为你必须在形成持久的羁绊之前继续你与其他生物的训练。",al={"我能保留这头野猪吗","这头野猪是我的永久宠物吗","保留杂斑野猪"}},{q="这项任务之后是什么？",a="一旦你回到索塔尔那里，他会测试你对在杜隆塔尔发现的其他致命捕食者的控制能力，包括冲浪爬行者和装甲蝎子。",al={"后续任务","驯服野猪之后做什么","驯服任务链的下一步"}},{q="为什么要使用驯兽棒而不是纯粹的直觉？",a="新手猎人缺乏直接与野兽建立联系所需的精炼精神和身体纪律。附魔驯兽棒充当了一个焦点，帮助新手将权威投射到野兽的精神上，直到他们彻底掌握这门艺术。",al={"为什么使用驯兽棒","驯兽棒有什么作用","驯兽棒的背景故事"}}},fp="16,164,26.293.0,20.246.0,34.140.0,21.121.0,39.95.0,50.146.0,27.138.0,46.193.0"}
P.entries["quest:6063"] = {n="驯服野兽",s="此任务是暗夜精灵猎人通往掌握野兽伙伴之路的第一次试炼。在多兰纳尔的达扎拉指导下，有志成为猎人的新兵必须使用一根附魔的驯兽棒与一只野生的网林潜伏者建立联系。这考验了猎人尊重并与自然交流的能力，而非试图暴力征服。",h="此任务是暗夜精灵猎人通往掌握野兽伙伴之路的第一次试炼。在多兰纳尔的达扎拉指导下，有志成为猎人的新兵必须使用一根附魔的驯兽棒与一只野生的网林潜伏者建立联系。这考验了猎人尊重并与自然交流的能力，而非试图暴力征服。",kw={"达扎拉","多兰纳尔","猎人宠物","卡多雷","驯服","驯兽棒","泰达希尔","网林潜伏者"},ang={["class:Hunter"]="这一成人礼标志着猎人从孤独的弓箭手转变为荒野的真正伙伴，与森林的野兽结下羁绊。",["race:NightElf"]="这种驯服宠物的做法反映了卡多雷的哲学，强调与自然的交流和对自然的敬畏，而非征服和统治。"},sec={{t="神圣的羁绊",b="对于卡多雷来说，狩猎不仅仅是追踪猎物或在荒野中生存；它与自然之间存在着一种神圣的关系。像达扎拉这样的猎人训练师教导说，自然远比任何凡人个体都要伟大。动物不是驮兽，也不是可以强行屈从于个人意志的工具，而是需要相互尊重的独立生物。为了证明自己已经准备好迎接终身的野兽伙伴，新手猎人必须通过古老的技术，而不是蛮力，来证明他们能够掌控当地野生动物的原始本能。"},{t="第一次试炼",b="试炼始于泰达希尔枝干上出没的巨型蛛类。达扎拉将一根特制的驯兽棒交给猎人，指引他们去寻找一只网林潜伏者。猎人必须深入阴影丛林，面对剧毒蜘蛛，并在抵挡其攻击的同时建立共情通道。成功建立起这座临时的心灵之桥，证明了猎人甚至可以与世界之树那些令人毛骨悚然、爬行的掠食者进行交流。"}},faq={{q="此任务的目的是什么？",a="此任务启动了暗夜精灵猎人永久驯服动物伙伴所需的训练序列。通过对指定的当地野兽使用驯兽棒，猎人证明了他们拥有与野生掠食者交流的性情和技巧。",al={"为什么要进行此任务","宠物任务目的","驯服野兽提供什么"}},{q="谁提供此任务？",a="达扎拉，这位居住在泰达希尔多兰纳尔定居点的猎人训练师，会向那些在该领域达到足够经验的年轻暗夜精灵猎人提供此任务。",al={"任务提供者","在哪里接取驯服任务","谁开启驯服野兽任务"}},{q="在此试炼中必须驯服什么生物？",a="你的任务是驯服一只网林潜伏者，它们是居住在多兰纳尔外围荒野丛林中的剧毒巨型蜘蛛之一。",al={"驯服哪种宠物","网林潜伏者目标","我驯服什么野兽"}},{q="我能永久保留网林潜伏者吗？",a="不能。在此任务中驯服的网林潜伏者只是一个临时伙伴，仅用于练习宠物处理的基础知识。一旦回到达扎拉那里，当你准备进行下一次试炼时，这种羁绊就会解除。",al={"我可以保留这只蜘蛛吗","网林潜伏者可以永久保留吗","保留宠物"}},{q="为什么暗夜精灵先用蜘蛛来测试猎人？",a="网林潜伏者具有掠食性和攻击性，这使其成为了对新手心态的严峻考验。能够掌控这种看似非自然的蛛类，证明了猎人能够将自己的意识与自然界中各种敌对的表象连接起来。",al={"为什么是网林潜伏者","为什么驯服蜘蛛","蜘蛛驯服背景知识"}},{q="回到达扎拉那里之后要做什么？",a="达扎拉会派遣猎人去测试他们与泰达希尔其他本土动物——特别是夜刃豹潜行者和夜枭尖啸者——之间的羁绊，之后才会授予永久驯服能力。",al={"接下来做什么","驯服野兽任务之后","下一次试炼"}}},fp="16,206,13.403.0,15.336.0,34.186.0,21.124.0,42.106.0,41.161.0,51.182.0,38.180.1"}
P.entries["quest:6064"] = {n="驯服野兽",s="Taming the Beast 是矮人猎人踏上驯服野兽旅程后的第一个试炼，地点位于丹莫罗。在卡拉诺斯的格瑞夫指导下，年轻的追踪者们将学习如何使用一根附魔的驯兽棒，来安抚并与凶猛的大型岩鬃野猪建立羁绊。",h="Taming the Beast 是矮人猎人踏上驯服野兽旅程后的第一个试炼，地点位于丹莫罗。在卡拉诺斯的格瑞夫指导下，年轻的追踪者们将学习如何使用一根附魔的驯兽棒，来安抚并与凶猛的大型岩鬃野猪建立羁绊。",kw={"野兽","野猪","岩鬃野猪","丹莫罗","格瑞夫","猎人","卡拉诺斯","驯服","驯兽棒"},ang={["class:Hunter"]="这个任务标志着新手神枪手向真正的兽王猎人迈出的决定性一步，同时也开启了解锁永久动物伙伴的试炼序列。",["race:Dwarf"]="铁炉堡的登山者崇敬那些能在丹莫罗严寒中生存的野兽；从顽强的岩鬃野猪开始，正体现了矮人对坚毅和韧性的推崇。"},sec={{t="猎人的伙伴",b="在此之前，矮人登山者和追踪者主要依靠枪械、陷阱和野外求生本能。然而，猎人真正的灵魂在于与野生猛兽建立终身的伙伴关系。常驻于卡拉诺斯雷酒酿制厂外的格瑞夫，负责监督这一成年仪式。格瑞夫并没有要求新手永久束缚他们遇到的第一只野兽，而是指导他们先测试自己对付丹莫罗几种原生野兽时的耐心与决心。"},{t="岩鬃野猪",b="第一个试炼要求追踪者对付一只大型岩鬃野猪，这种皮糙肉厚的野猪漫步在丹莫罗白雪皑皑的山脚下。它们覆盖着刚毛，肉体坚韧，性格顽固且好斗，是测试意志力的绝佳初始目标。猎人必须挥舞格瑞夫提供的附魔驯兽棒，抵挡野猪的冲锋，并平息它的凶性，直到它服从命令为止。"}},faq={{q="是谁提供了这项试炼？",a="该试炼由格瑞夫提供，他是一位资深的矮人猎人训练师，位于卡拉诺斯的雷酒酿制厂外。",al={"任务发放者","谁开启taming the beast","格瑞夫位置"}},{q="为什么我首先要驯服大型岩鬃野猪？",a="大型岩鬃野猪在丹莫罗的雪岭中随处可见，它们身体强壮且顽固。制服这样一种耐寒、皮厚的生物，是学习如何以冷静的权威来驾驭凶猛野兽的基础练习。",al={"为什么选择岩鬃野猪","我该驯服什么野兽","驯服野猪"}},{q="我能永远拥有这只野猪吗？",a="不能。这项试炼纯粹是练习。用驯兽棒建立的羁绊是暂时的，让你在归还驯兽棒并尝试其他物种之前，体验指挥野兽的感觉。",al={"这只野猪是永久的吗","保留岩鬃野猪","我能留着这只宠物吗"}},{q="我在哪里可以找到大型岩鬃野猪？",a="大型岩鬃野猪广泛分布在卡拉诺斯周边的开阔雪原和松树林，以及丹莫罗的冻土坡地中。",al={"野猪位置","大型岩鬃野猪在哪里","大型岩鬃野猪刷新点"}},{q="驯服岩鬃野猪之后该做什么？",a="回到格瑞夫处完成这一最初的课程，便会直接进行第二个试炼，你需要驯服一只雪豹。",al={"下一个试炼","在这个任务之后做什么","猎人后续任务链"}},{q="驯兽棒是如何工作的？",a="驯兽棒是猎人训练师提供的一种附魔工具，旨在帮助新手引导他们的意志并安抚野兽的本能，而无需进行高深的魔法训练或拥有终身的驭兽经验。",al={"驯兽棒背景","什么是驯兽棒","我该如何驯服"}}},fx={["49cdd252"]={q="为什么格瑞夫要你驯服一只野兽？",a="格瑞夫·野心正在训练你掌握成为真正矮人猎人的基本功。在他看来，学会与野兽伙伴建立羁绊并指挥它，与保养武器同样重要。他认为，学习驯服野兽的正当方式是在野外亲身实践，让你面对当地不同种类的生物，检验自己的耐心和本领，然后再选择永久的伙伴。",al={"格瑞夫·野心的动机","为什么要驯服野兽","格瑞夫·野心安排训练的原因"}}},fp="16,251,20.493.0,13.427.0,22.127.0,38.231.0,35.190.0,34.124.0,38.144.0,29.209.0"}
P.entries["quest:6065"] = {n="猎人之道",s="“猎人之道”是莫高雷年轻牛头人猎人生命中至关重要的里程碑，它指引他们开始学习更进阶的野兽伙伴训练。当新手猎人们展现出基础的射击和追踪能力后，他们会收到导师的指派，前往血蹄村寻求猎人训练师雅文·刺鬃的指点。这段旅程标志着他们将开始进行驯服和结交野兽伙伴所需的精神与实践试炼。",h="“猎人之道”是莫高雷年轻牛头人猎人生命中至关重要的里程碑，它指引他们开始学习更进阶的野兽伙伴训练。当新手猎人们展现出基础的射击和追踪能力后，他们会收到导师的指派，前往血蹄村寻求猎人训练师雅文·刺鬃的指点。这段旅程标志着他...",kw={"野兽","血蹄村","纳拉其营地","猎人之道","莫高雷","宠物任务","驯服","雅文·刺鬃"},ang={["class:Hunter"]="这项任务标志着一名弓箭手或火枪手向真正的兽王转变的时刻，并迈出了获得忠诚战斗伙伴的第一步。",["faction:Horde"]="部落猎人极其依赖凶猛的边境野兽，让它们在卡利姆多严酷的荒野中充当前线防御者和追踪者。",["race:Tauren"]="对于舒哈鲁而言，学习驯服野兽是他们对自然以及大地母亲创造万物所怀的崇敬之情的精神延伸。"},sec={{t="成人礼",b="对于游牧的舒哈鲁（牛头人）来说，狩猎不仅是一项运动，更是神圣的仪式。猎人必须理解自然的平衡，尊崇平原上的灵魂，并尊重那些供养部族的动物。当年轻的猎人在野外生存和弓箭或枪械的使用上证明了自己的能力，长者们便会认可他们已经做好了超越单纯追踪的准备。前往寻求经验丰富的导师指引，标志着牛头人文化中真正成年人的门槛。"},{t="通往血蹄村之路",b="这条路引领着新手们穿越莫高雷辽阔的草地，来到石牛湖畔的中央集散地——血蹄村。在那里等待他们的是雅文·刺鬃，一位对当地动物习性了如指掌的资深猎人。与刺鬃交谈绝非仅仅是走过场；它象征着猎人已经准备好承担艰巨的野兽驯服试炼，学习如何与掠食者沟通，而不仅仅是猎杀它们。"}},faq={{q="“猎人之道”的目的是什么？",a="这项任务是正式邀请新手牛头人猎人开启他们的驯兽试炼。它指引猎人前往血蹄村与雅文·刺鬃交谈，由他来监督与动物伙伴建立联系所需的仪式。",al={"为什么要接这个任务","猎人之道的目标","猎人宠物任务起始"}},{q="谁会指派这项任务给你？",a="当有志向的猎人获得足够的经验并掌握了基础的生存与射击技巧后，这项任务会由牛头人猎人训练师（例如雷霆崖的卡尔·雷角）提供。",al={"谁提供猎人之道","猎人训练师任务"}},{q="雅文·刺鬃是谁？",a="雅文·刺鬃是一位受人尊敬的牛头人猎人训练师，居住在血蹄村。他肩负着教导年轻猎人如何接近、安抚并驯服莫高雷荒野野兽的危险技艺的职责。",al={"谁是刺鬃","雅文·刺鬃的作用"}},{q="完成这项任务后会发生什么？",a="在向雅文·刺鬃报到后，他会开始一系列“驯服野兽”的试炼。这些任务要求猎人携带驯兽棒进入野外，在获得训练永久伙伴的权利之前，先安抚几只当地的生物。",al={"what comes next","猎人之道后续任务"}},{q="为什么牛头人猎人要与野兽建立联系，而不只是狩猎它们？",a="在牛头人的传统中，野兽是大地母亲的同胞灵魂。结伴的动物并非仆从，而是伙伴和狩猎搭档，体现了双方在平原上共同生存的相互尊重。",al={"牛头人宠物背景故事","牛头人为何驯服宠物"}},{q="其他种族的猎人可以接取这个特定的任务吗？",a="这个版本的任务是专门为在莫高雷受训的牛头人猎人量身定制的。其他的部落种族，如兽人和巨魔，会在他们各自的家园领地，如杜隆塔尔，收到相应的训练指引。",al={"这是牛头人专属吗","兽人可以做牛头人的猎人之道吗"}}},fx={a380c02c={q="为什么你的训练师要你去找雅文·刺鬃？",a="你的训练师认为，你在野外积累了足够的经验，可以迈出猎人生涯中至关重要的下一步：与动物伙伴建立羁绊并训练它。他们让你去血蹄村找雅文·刺鬃，因为他掌握着引导你完成驯兽试炼所需的专门知识和古老传统。",al={"为什么要见雅文·刺鬃","猎人之路的训练师动机","为什么派我去血蹄村"}}},fp="17,421,17.483.0,29.455.0,41.243.0,28.203.0,21.207.0,41.250.0,68.203.0,52.228.0"}
P.entries["quest:6068"] = {n="猎人之道",s="“猎人之道”是一项指引年轻兽人和巨魔猎人前往剃刀岭的成年礼。在猎人大师索塔尔的指导下，初出茅庐的追踪者们将学习驾驭野生猛兽这一至关重要的本领。",h="“猎人之道”是一项指引年轻兽人和巨魔猎人前往剃刀岭的成年礼。在猎人大师索塔尔的指导下，初出茅庐的追踪者们将学习驾驭野生猛兽这一至关重要的本领。",kw={"杜隆塔尔","猎人训练师","猎人之道","宠物任务","剃刀岭","驯服野兽","索塔尔"},ang={["class:Hunter"]="这次召唤标志着你旅途中最关键的转折点：从一名孤军奋战的神射手转变为真正的野兽大师。",["faction:Horde"]="部落依靠其斥候和追踪者来驯服地区的捕食者，将杜隆塔尔严酷的生态环境转化为一种资产。",["race:Orc"]="对于兽人来说，与凶猛的同伴并肩作战，呼应着追溯至德拉诺狼骑兵的古老传统。",["race:Troll"]="暗矛猎人视驯服当地的迅猛龙和野猪为在杜隆塔尔险恶荒野中站稳脚跟的关键。"},sec={{t="猎人的觉醒",b="在此之前，杜隆塔尔的猎人学徒只能依靠自己的弓箭和智慧。在红土峡谷和严酷的灌木丛中追踪猎物可以磨练耐心，但若想在部落中成为真正的大师，就必须与这片土地上未被驯服的野兽建立羁绊。职业训练师在认定学生拥有足够的资格后，便会指引他们直接前往剃刀岭。"},{t="剃刀岭的大师",b="在剃刀岭等待着的是索塔尔，一位精通杜隆塔尔野生生物知识的资深猎人。索塔尔担任导师，负责指导新手进行这项危险的仪式：在不摧毁野兽精神的前提下将其制服。见到他，就是你迈向与忠诚伙伴一同行走于荒野之路的第一步。"}},faq={{q="“猎人之道”的目的是什么？",a="这是一项入门级的召唤任务，旨在指引兽人和巨魔猎人前往剃刀岭，以便他们开始野兽驯服训练。",al={"为何要进行猎人之道","猎人之道任务目的","这个任务有什么作用"}},{q="索塔尔是谁？",a="索塔尔是位于剃刀岭的一位经验丰富的猎人，他负责监督年轻的部落追踪者完成与野生猛兽建立羁绊并对其进行指挥所需的试炼。",al={"索塔尔是谁","谁是索塔尔","索塔尔 剃刀岭"}},{q="为什么年轻的猎人不能立即驯服宠物？",a="控制危险的捕食者需要深厚的纪律、耐心和专业的驯服技巧。在猎人展示出基本的生存技能之前，尝试束缚野兽只会导致被野兽撕碎或死亡。",al={"为什么1级不能带宠物","为什么猎人必须等待才能获得宠物","猎人何时获得宠物"}},{q="哪些种族需要进行这项特殊的试炼？",a="这个版本的试炼专门针对在杜隆塔尔成年的兽人和暗矛巨魔，而牛头人猎人则是在莫高雷进行类似的试炼。",al={"谁会接到这个任务","这是兽人和巨魔专有的吗","哪些种族进行此试炼"}},{q="向索塔尔报到后会发生什么？",a="索塔尔会立即指派猎人去追踪并制服杜隆塔尔各地的土生捕食者，以此证明他们的驯服能力。",al={"what comes next","猎人之道之后","索塔尔之后的下一个任务"}},{q="这项训练在哪里进行？",a="试炼的核心区域是剃刀岭，这是杜隆塔尔中部的主要定居点，位于试炼谷和奥格瑞玛之间。",al={"剃刀岭在哪里","索塔尔位置","去哪里"}}},fp="17,129,20.321.0,24.213.0,41.103.0,14.111.0,46.158.0,42.110.0,39.130.0,36.119.0"}
P.entries["quest:607"] = {n="向马克基雷回报",s="在被内脏吓坏之后，“病鬼”菲利普递给你一个钱袋，让你带给“海狼”马克基雷。菲利普发誓说这笔债务一直都打算偿还，并补充说没必要动粗。",h="在被内脏吓坏之后，“病鬼”菲利普递给你一个钱袋，让你带给“海狼”马克基雷。菲利普发誓说这笔债务一直都打算偿还，并补充说没必要动粗。",kw={"债务","马克基雷","海狼","病鬼菲利普","荆棘谷"},sec={{t="病鬼的恳求",b="菲利普把一袋偿还给海狼的钱塞给你。菲利普要你转告马克基雷，这笔债务一直都打算偿还，他对此发誓。菲利普将其归咎于喝醉了酒迷了路，并说马克基雷会理解的，没必要动粗。"},{t="海狼听故事",b="马克基雷轻声笑了笑，问你给菲利普看内脏的时候，他抖得有多厉害。马克基雷补充说菲利普这人太好懂了，跟他打牌，赢起来毫不费力。"}},faq={{q="是谁给了你钱袋？",a="“病鬼”菲利普给了你这个给海狼马克基雷的钱袋。",al={"谁给的返回马克基雷任务","我在哪里开始返回马克基雷任务"}},{q="菲利普为没付钱找了什么借口？",a="菲利普将其归咎于喝醉了酒迷了路，并誓言说这笔债务一直都是要偿还的。",al={"为什么病鬼没付钱","菲利普的借口","为什么病鬼菲利普迟到了"}},{q="这步任务之前发生了什么？",a="这是继“吓唬病鬼”之后的后续，在那个任务里，马克基雷让你用内脏去吓唬菲利普。",al={"返回马克基雷之前是什么任务","前置任务"}}},fp="19,198,12.292.0,23.191.1,24.71.0,46.118.0,27.83.0"}
P.entries["quest:6074"] = {n="猎人之道",s="“猎人之道”是丹莫罗的矮人猎人新手在掌握了基本的追踪和射击技巧后所要经历的成年仪式。当地训练师会指引他们的学徒去找卡拉诺斯的格瑞夫，开始学习驯服野生动物并使其成为忠实伙伴的技艺。",h="“猎人之道”是丹莫罗的矮人猎人新手在掌握了基本的追踪和射击技巧后所要经历的成年仪式。当地训练师会指引他们的学徒去找卡拉诺斯的格瑞夫，开始学习驯服野生动物并使其成为忠实伙伴的技艺。",kw={"丹莫罗","格瑞夫","猎人","卡拉诺斯","olmin burningbeard","宠物任务","驯服","tristane shadowstone"},ang={["class:Hunter"]="这个任务标志着从孤独的追踪者向能够驾驭野生掠食者的真正驯兽师的决定性转变。",["race:Dwarf"]="长期以来，矮人登山家一直将熊和野猪作为他们穿越丹莫罗雪峰时值得信赖的侦察伙伴。"},sec={{t="猎人的真正使命",b="在掌握驯兽之术前，猎人只能独自走在丹莫罗的雪山上，依靠斧头、步枪或弓箭生存。像Olmin Burningbeard和Tristane Shadowstone这样的训练师会密切观察他们的学员，直到他们表现出足以在不杀死野兽的前提下直面凶猛生物的沉稳。一旦新手表现出足够的纪律性，他们就会被派往山下的卡拉诺斯。"},{t="向格瑞夫报到",b="在卡拉诺斯，格瑞夫负责监督矮人猎人训练的最终试炼。驯服野兽被认为比为了肉食或毛皮而猎杀野兽要困难得多；它需要耐心、耐力，以及与山中野生捕食者之间直觉性的联结。格瑞夫是这些试炼的引路人，为猎人进行磨练意志的准备，以应对丹莫罗最凶猛的野生动物。"}},faq={{q="这个任务的目的是什么？",a="它是正式的召唤，将成熟的猎人派往卡拉诺斯，在格瑞夫的指导下开始他们的宠物驯服试炼。",al={"为什么要完成这个任务","什么是猎人之道","猎人宠物任务起始"}},{q="谁指引我踏上这条道路？",a="猎人训练师——包括铁炉堡Hall of Arms的Olmin Burningbeard、Tristane Shadowstone以及Einris Brightspear——会指引他们的学员接受这项任务。",al={"任务发布者","谁给予猎人之道任务","在哪里接取任务"}},{q="在哪里可以找到格瑞夫？",a="格瑞夫就驻扎在卡拉诺斯的雷酒酿制厂外，位于丹莫罗的雪谷之中。",al={"格瑞夫的位置","格瑞夫在哪里","卡拉诺斯猎人训练师"}},{q="为什么猎人需要训练师来驯服野兽？",a="驯服野兽需要专门的技术和驯兽棒，以便与掠食性生物沟通，而不会引发不死不休的战斗。格瑞夫教授的正是这些传统技艺。",al={"为什么需要驯服训练","宠物驯服的背景知识","为什么我还不能驯服野兽"}},{q="向格瑞夫报到后会发生什么？",a="格瑞夫会立即考验你的勇气，派你带着驯兽棒进入荒野，去制服几种丹莫罗特有的野兽。",al={"下一个任务","猎人之道之后是什么","后续任务链"}},{q="任何猎人都能接取这个特殊任务吗？",a="这个特别的召唤专为在丹莫罗活动的矮人猎人量身定制，指引他们前往卡拉诺斯的当地训练师处。",al={"这是矮人专属吗","暗夜精灵可以做这个吗","种族限制"}}},fx={["5e8bda0f"]={q="为什么猎人训练师要你去找格瑞夫·野心？",a="你的训练师认为，你已经具备与野兽沟通并驾驭它们的基本本领。他们没有让你继续接受常规武技训练，而是指引你去卡拉诺斯找格瑞夫·野心，接受专门训练。在他们看来，掌握与野兽结伴的技艺，是你成长为真正猎人过程中必经的重要阶段。",al={"为什么派我去找格瑞夫","猎人训练师的动机","为什么要见格瑞夫·野心"}}},fp="17,296,23.404.0,27.430.0,34.124.0,26.164.0,32.114.0,45.184.0,47.153.0,40.129.0"}
P.entries["quest:608"] = {n="血帆海盗",s="随着血帆海盗准备发起进攻，舰队指挥官卡拉·海角决定不派遣他的整个舰队进行反击。相反，他指挥一支冒险者小队潜入登陆地点，在海盗发动攻击前除掉他们的最高领导层。",h="随着血帆海盗准备发起进攻，舰队指挥官卡拉·海角决定不派遣他的整个舰队进行反击。相反，他指挥一支冒险者小队潜入登陆地点，在海盗发动攻击前除掉他们的最高领导层。",kw={"黑水","血帆","藏宝海湾","菲拉隆","基尔霍尔","海盗","海角","斯提尔沃特"},sec={{t="斩首海盗舰队",b="在获悉了海盗的入侵计划后，舰队指挥官卡拉·海角拒绝坐等敌人集结兵力发起进攻。海角嘲讽了舰队指挥官菲拉隆的航海技术，旨在通过除掉敌方指挥官来迅速消除威胁。他没有冒着进行全面海军交战的风险，而是直接派遣一支打击小队前往菲拉隆的登陆营地，斩杀菲拉隆以及斯提尔沃特船长和基尔霍尔船长，确保海盗部队因群龙无首而土崩瓦解。"}},faq={{q="是谁下令对血帆海盗领导层进行打击的？",a="藏宝海湾的舰队指挥官卡拉·海角指挥了这次突袭，意在敌方舰队发动攻击前将其瓦解。",al={"谁发布血帆海盗任务","血帆海盗任务发布者","谁派你去对付菲拉隆"}},{q="需要消灭哪些海盗指挥官？",a="目标是领导血帆海盗部队的舰队指挥官菲拉隆、斯提尔沃特船长和基尔霍尔船长。",al={"血帆海盗的目标","需要击杀的血帆指挥官","血帆的首领是谁"}},{q="为什么舰队指挥官卡拉·海角派遣冒险者而不是他的船只？",a="海角认为一支有能力的冒险者小队可以突袭登陆营地并暗杀敌方军官，从而导致敌方舰队在不危及他自身船只的情况下瓦解。",al={"为什么派冒险者去对付菲拉隆","为什么不派黑水舰队","海角的计划"}},{q="这次冲突在与血帆海盗的更广泛对抗中处于什么位置？",a="这场对抗发生在荆棘谷血帆海盗调查的早期阶段，发现了海盗的书面攻击计划之后。",al={"之前的血帆任务","这个任务之前是什么任务","血帆任务链顺序"}}},fp="24,281,29.478.0,50.116.0,49.111.0,68.179.0,85.156.0"}
P.entries["quest:6081"] = {n="训练野兽",s="Training the Beast 是杜隆塔尔年轻兽人和巨魔猎人的最终成人礼。在证明了自己能够驾驭平原上的野兽后，猎人们会被派往剃刀岭，前往奥格瑞玛拜师于资深猎人奥玛克。完成这段旅程将教会新手如何照料、喂养他们的终生动物伙伴，并磨练它们的技能。",h="Training the Beast...",kw={"杜隆塔尔","猎人宠物","奥格瑞玛","奥玛克","剃刀岭","索塔尔","training the beast","valley of honor"},ang={["class:Hunter"]="这个任务标志着你的宠物成为了一个永久的、可靠的盟友，而不再是一个短暂的召唤物，它解锁了“喂养宠物”和“复活宠物”这些至关重要的艺术。",["faction:Horde"]="部落依靠其斥候和野兽来保卫杜隆塔尔和贫瘠之地脆弱的边界，抵御半人马、野猪人和联盟的入侵。",["race:Orc"]="兽人将与狩猎伙伴的羁绊视为一种军事荣誉和职责，这是一种在杜隆塔尔严酷的前线战场上经过考验的伙伴关系。",["race:Troll"]="对于在卡利姆多开拓新家园的暗矛巨魔来说，学习与杜隆塔尔的野蛮生物交流，对于在陌生的土地上侦察和生存至关重要。"},sec={{t="荒野之外的旅程",b="在杜隆塔尔干旱的峡谷中，掌握弓箭并能在严酷的环境下生存，仅仅是猎人职责的一半。在通过驯服杜隆塔尔凶猛的野猪、食腐蟹和装甲蝎虫证明了自己的韧性后，年轻的猎人们便做好了承担真正责任的准备。驻扎在剃刀岭的索塔尔会指引他们穿过红土峡谷，直接前往奥格瑞玛的防御要塞。"},{t="荣誉谷",b="在这座繁华的首府内，渴望成为驯兽大师的猎人们必须前往荣誉谷，那是一片战士精神与资深猎人磨练技艺的飞地。奥玛克就居住在那里，他是部落最受尊敬的大师级猎人之一。奥玛克能够透过年轻猎人的青涩，洞察他们是否拥有不仅仅是驾驭野兽，还能在饥荒、战斗和失落中支撑并呵护它们的耐心。"},{t="与荒野建立羁绊",b="通过武力获得的野兽，在猎人与伙伴之间达成默契之前依然是野性的。奥玛克传授了维持这种羁绊所需的神圣传统：了解哪些食物能够滋养每种生物的灵魂，学习传授它们致命技巧所需的纪律，以及在野兽因公殉职时将其复活所需的精神专注。"}},faq={{q="谁发布了 Training the Beast 这个任务？",a="当你成功制服了杜隆塔尔各地的全部三只测试生物后，位于剃刀岭军营外的猎人训练师索塔尔会提供这项任务。",al={"任务发布者","谁提供 training the beast","在哪里开始 training the beast"}},{q="我在哪里可以找到奥玛克？",a="奥玛克居住在奥格瑞玛主城的东区，即荣誉谷，与其他资深猎人和战士导师在一起。",al={"奥玛克位置","寻找奥玛克","奥玛克在哪里"}},{q="奥玛克会传授什么技能？",a="奥玛克会教你如何通过主动和被动技能来训练你的伙伴，如何喂养宠物以保持其忠诚和满足，以及如果它在战斗中死亡如何复活它。",al={"我能学到什么","任务奖励技能","猎人宠物技能"}},{q="为什么兽人和巨魔猎人必须为此前往奥格瑞玛？",a="像索塔尔这样的当地训练师可以传授基本的荒野生存技能，但进阶的野兽控制知识是由部落的资深斥候和像奥玛克这样受人尊敬的追踪者在主城中保留下来的。",al={"为什么要前往奥格瑞玛","为什么是奥格瑞玛","访问荣誉谷"}},{q="其他部落种族会进行这个特定的任务吗？",a="不。这个特定的仪式是专为在杜隆塔尔起步的兽人和巨魔猎人设计的。牛头人猎人会在莫高雷进行一项平行的仪式，由他们自己的部落大师指导。",al={"牛头人可以做这个吗","这是兽人专属吗","亡灵猎人"}},{q="如果猎人忽略了完成这次训练会怎样？",a="如果不完成这项指导，猎人将无法喂养、妥善训练或复活他们的伙伴，这会导致捕获的野兽变得不快乐、虚弱，并最终可能会抛弃他们。",al={"我必须做这个吗","我可以跳过 training the beast 吗"}}},fp="18,266,31.400.0,19.331.0,21.326.0,40.141.0,32.117.0,42.156.0,62.182.0,48.149.0,60.177.0"}
P.entries["quest:6082"] = {n="驯服野兽",s="这个任务标志着年轻的部落猎人在杜隆塔尔所经历的基本试炼的最后一环。在剃刀岭资深猎人索塔尔的指导下，渴望成为追踪者的猎人必须去对抗并驯服一只危险的装甲蝎。征服这只装甲掠食者，证明了其驾驭野兽的能力，并能永久解锁驯服、召唤和解散忠实伙伴的技能。",h="这个任务标志着年轻的部落猎人在杜隆塔尔所经历的基本试炼的最后一环。在剃刀岭资深猎人索塔尔的指导下，渴望成为追踪者的猎人必须去对抗并驯服一只危险的装甲蝎。征服这只装甲掠食者，证明了其驾驭野兽的能力，并能永久解锁驯服、召唤和...",kw={"装甲蝎","杜隆塔尔","猎人试炼","宠物任务","剃刀岭","驯服野兽","驯兽棒","索塔尔"},ang={["class:Hunter"]="这次成人礼是猎人早期旅程中的决定性里程碑，赋予了永久使用驯服、召唤和指挥动物伙伴的核心技术的权限。",["faction:Horde"]="杜隆塔尔的兽人和巨魔后辈必须在贫瘠之地的最凶残掠食者威胁下生存下来，才能赢得他们作为部落真正的斥候和供养者的地位。",["race:Orc"]="制服杜隆塔尔的蝎子体现了兽人的哲学，即通过坚韧的意志和严明的纪律来克服恶劣的环境。",["race:Troll"]="暗矛猎人利用敏锐的直觉和与荒野之灵的深层联系，去安抚那些会置他人于死地的毒性掠食者。"},sec={{t="最后的试炼",b="在准许猎人带着忠实的动物伙伴在卡利姆多漫游之前，他们必须证明自己有能力驾驭杜隆塔尔最凶猛的野生动物。剃刀岭的猎人训练师索塔尔会派遣学员使用一支附魔的驯兽棒去制服三种不同的生物。在测试过对付恐鬃野猪和迅捷滩行蟹的身手后，猎人们还需要面对装甲蝎——一种毒性强烈、外壳坚硬、兼具韧性与致命速度的掠食者。"},{t="与荒野结缘",b="制服装甲蝎并非单纯的杀戮，而是在遭受猛烈攻击时展现专注与统治力的表现。索塔尔敦促猎人们效仿野兽那种迅捷而自信的打击方式。成功安抚这只毒性蛛形纲动物并返回剃刀岭，证明了猎人具备维持控制所需的冷静意志。归还驯兽棒后，索塔尔会传授荒野的本能技巧，让猎人能够寻找并绑定属于自己的永久伙伴。"}},faq={{q="我在这个试炼中需要驯服什么生物？",a="你必须去寻找在杜隆塔尔赤色干旱崖壁间游荡的装甲蝎，并使用索塔尔的驯兽棒来安抚和控制它。",al={"要驯服什么野兽","目标野兽","蝎子任务"}},{q="任务完成后，我可以保留那只装甲蝎吗？",a="不能。试炼中驯服的装甲蝎是临时的，在你归还训练棒后它就会消失。然而，完成这项任务会让你习得驯服任何你想要的野生野兽的永久能力。",al={"保留蝎子","我可以保留宠物吗","永久蝎子"}},{q="谁发起了这次成人礼试炼？",a="索塔尔，位于杜隆塔尔中部剃刀岭的猎人训练师，负责监督年轻兽人和巨魔猎人的这次成人礼试炼。",al={"任务发布者","谁发布了驯服野兽任务","索塔尔位置"}},{q="为什么索塔尔特别要求猎人驯服装甲蝎？",a="索塔尔认为装甲蝎因其自信、迅捷的打击和天生的韧性，是猎人效仿的理想对象。征服这样危险的掠食者证明了猎人已经做好准备，去驾驭荒野中的任何野兽。",al={"为什么是蝎子","蝎子的目的"}},{q="完成任务后能学到什么技能？",a="完成这项试炼将赋予经验丰富的兽王猎人最基础的能力：驯服野兽、召唤宠物和解散宠物。",al={"奖励","我能获得什么法术","解锁驯服技能"}},{q="这次试炼之后是什么？",a="一旦你学会了如何驯服和召唤自己的伙伴，索塔尔就会指导你进行宠物训练，并派遣你去完成后续任务“驯服野兽”，以掌握喂养和指挥盟友的技巧。",al={"下一个任务","接下来做什么","驯服三个目标之后"}}},fp="16,258,15.411.0,21.442.0,47.110.0,63.182.0,35.112.0,69.165.0,52.48.0,28.148.0"}
P.entries["quest:6083"] = {n="驯服野兽",s="这是年轻猎人在杜隆塔尔进行的第二项掌握试炼，由剃刀岭的训练师索塔尔指导。有抱负的兽人和巨魔猎人会被派往回音群岛附近的海岸线，去平息一只冲浪蟹，将他们的羁绊从陆地野兽扩展到沿海野生生物。",h="这是年轻猎人在杜隆塔尔进行的第二项掌握试炼，由剃刀岭的训练师索塔尔指导。有抱负的兽人和巨魔猎人会被派往回音群岛附近的海岸线，去平息一只冲浪蟹，将他们的羁绊从陆地野兽扩展到沿海野生生物。",kw={"杜隆塔尔","回音群岛","宠物驯服","剃刀岭","森金村","冲浪蟹","驯兽棒","索塔尔"},ang={["class:Hunter"]="这项试炼灌输了指挥防御型野兽所需的基本准则，展示了野兽的天然护甲和坚韧如何与远程射手相辅相成。",["race:Orc"]="对于在杜隆塔尔开辟永久家园的兽人来说，制服海岸线耐寒的动物群加强了他们对这片崎岖土地的掌控。",["race:Troll"]="暗矛巨魔对回音群岛和森金村附近的水域非常熟悉，这使得这项试炼成为他们与其沿海避难所中熟悉的野生动物的一次邂逅。"},sec={{t="与海岸结缘",b="在成功驯服了一只凶猛的杂斑野猪后，初出茅庐的猎人会接到索塔尔的任务，将注意力转向大海。杜隆塔尔恶劣的环境包括锯齿状的海岸和充满装甲甲壳类动物的浅滩。面对冲浪蟹需要耐心和坚韧，因为这些装甲蟹会抵御对其沿海领地的入侵。"},{t="意志的延伸",b="索塔尔教导说，猎人驯服的任何野兽都必须成为其自身力量的延伸。通过使用驯兽棒制服像冲浪蟹这样的水生生物，猎人学会了在不同的性格和环境下调整自己的统御气场，证明他们已经为获得永久同伴做好了准备。"}},faq={{q="哪里可以找到冲浪蟹？",a="冲浪蟹在杜隆塔尔的东海岸疾行，具体来说是在森金村对面的浅滩，靠近通往回音群岛的水域。",al={"冲浪蟹位置","哪里有冲浪蟹","螃蟹位置"}},{q="驯服冲浪蟹的目的是什么？",a="索塔尔指定驯服冲浪蟹是为了教导猎人如何指挥多样的野兽。学会驯服一种带护甲的水生生物可以拓宽猎人的掌控范围，证明他们能像掌握陆地动物一样轻松地掌握水生动物。",al={"为什么要驯服螃蟹","冲浪蟹任务目的"}},{q="我可以永久保留这只冲浪蟹吗？",a="不能。在这些最初试炼中驯服的野兽只是通过索塔尔的驯兽棒的魔法所制服的临时练习对象。只有完成整个试炼系列后，你才能学会永久的驯服技能。",al={"我能留下这只螃蟹吗","冲浪蟹是永久的吗"}},{q="谁提供这个任务？",a="索塔尔，位于剃刀岭的猎人训练师，在你证明了自己有能力驯服一只凶猛的杂斑野猪后提供这项试炼。",al={"任务提供者","谁开启野兽之驯2"}},{q="驯服冲浪蟹之后该做什么？",a="将驯兽棒归还给索塔尔后，他会用第三项也是最后一项试炼来考验你，让你追踪并驯服一只装甲蝎，然后才会教你永久的野兽控制技能。",al={"下一个任务","任务链下一步是什么"}},{q="为什么要用驯兽棒而不是自然技能？",a="新手猎人尚未培养出永久羁绊野生野兽所需的内在精神权威。驯兽棒充当了媒介，让初学者在学习真正的技巧之前，可以安全地练习引导他们的意志。",al={"为什么要用驯兽棒","什么是驯兽棒"}}},fp="16,254,22.284.0,21.262.0,30.150.0,45.203.0,39.191.0,21.112.0,41.158.0,47.200.0"}
P.entries["quest:6084"] = {n="驯服野兽",s="这项任务是卡拉诺斯（Kharanos）的格瑞夫（Grif Wildheart）交给矮人猎人试炼的第二项。在学会了如何应付峭壁野猪那粗犷的生命力后，年轻的猎人将接受新的挑战，去驯服一种更为迅捷致命的本土生物——雪豹。",h="这项任务是卡拉诺斯（Kharanos）的格瑞夫（Grif Wildheart）交给矮人猎人试炼的第二项。在学会了如何应付峭壁野猪那粗犷的生命力后，年轻的猎人将接受新的挑战，去驯服一种更为迅捷致命的本土生物——雪豹。",kw={"丹莫罗","格瑞夫","猎人任务","卡拉诺斯","雪豹","驯兽棒","taming the beast"},ang={["class:Hunter"]="这一试炼向矮人猎人新手展示了高耐力宠物（如野猪）与迅捷、极具攻击性的伤害输出宠物（如猫科动物）之间的差异。",["race:Dwarf"]="卡兹莫丹（Khaz Modan）的登山者们长期以来一直与雪豹共享丹莫罗（Dun Morogh）的冰冻山峰，并敬畏它们隐秘且致命的狩猎本领。"},sec={{t="技巧课",b="如果说峭壁野猪教会了登山者如何承受猛烈的攻击和吸收伤害，那么格瑞夫（Grif Wildheart）强调，一名大师级猎人必须理解不同的战斗风格。他将学生指向丹莫罗（Dun Morogh）的东南方，那里徘徊着雪豹。格瑞夫将这些优雅的捕食者比作一把做工精良的步枪：外表引人注目，却在它们那纯净的白色皮毛下蕴藏着毁灭性的力量。"},{t="掌握驯兽棒",b="猎人必须使用附魔的驯兽棒去面对一只野生的雪豹，并将其狩猎本能转变为伙伴关系。雪豹考验的是敏捷、速度和敏锐的反应，而非纯粹的耐力。驯服这样一只生物证明了新手能够与那些从雪山峭壁上迅疾出击的掠食者达成和谐，这是向真正掌控荒野猛兽迈出的又一步。"}},faq={{q="这个任务的目的是什么？",a="这是矮人猎人试炼的第二阶段。猎人训练师格瑞夫（Grif Wildheart）要求他的学生在获得永久驯服动物伙伴的知识之前，必须先测试自己对抗不同荒野猛兽的能力。",al={"为什么要完成这个任务","矮人雪豹任务","驯兽师任务2"}},{q="我在哪里可以找到雪豹？",a="雪豹徘徊在丹莫罗（Dun Morogh）卡拉诺斯（Kharanos）东南部和南部的岩石峭壁与雪坡上。",al={"雪豹位置","丹莫罗雪豹在哪里"}},{q="为什么格瑞夫（Grif Wildheart）要我驯服一只雪豹？",a="格瑞夫认为猎人必须同时体验强壮的体魄和精湛的技巧。峭壁野猪依靠的是粗犷的生命力，而雪豹则教会猎人如何与迅捷、敏捷且致命的伤害输出者并肩作战。",al={"为什么选择雪豹","格瑞夫驯服雪豹的理由"}},{q="我可以永久保留这只雪豹吗？",a="不能。在这些初步试炼中驯服的野兽只是临时的训练伙伴，它们受驯兽棒的魔法所束缚。当你完成这一任务线并得到格瑞夫的认可后，你才能获得永久驯服任意野生野兽的能力。",al={"我可以保留雪豹吗","雪豹是永久的吗"}},{q="谁指派了这个试炼？",a="格瑞夫（Grif Wildheart），驻扎在丹莫罗（Dun Morogh）卡拉诺斯（Kharanos）旅店外的矮人猎人训练师。",al={"谁发布的任务","任务发布者","格瑞夫的角色"}},{q="任务链的下一步是什么？",a="在展示了对雪豹的驾驭能力后，格瑞夫会派你去进行第三次，也就是最后一次驯兽试炼，去掌握冰爪熊，之后他才会正式传授你独自驯服和训练野生野兽的方法。",al={"下一个任务","雪豹之后是什么"}}},fx={baf34ad8={q="雪豹是什么样的野兽？",a="雪豹是原生于丹莫罗雪岭的敏捷掠食者。与初次试炼中结实而倔强的山猪不同，这些大型白猫依靠灵巧、速度和致命的攻击。格瑞夫指引你去寻找它们，让你学会如何应对一位身形灵巧、性情凶猛，战斗方式与蛮力型野兽截然不同的狩猎伙伴。",al={"雪豹的背景","为什么驯服雪豹","丹莫罗的雪豹"}},["4533de88"]={q="为什么格瑞夫·野心要我亲自驯服雪豹？",a="这是你作为年轻猎人的成人礼，不是格瑞夫需要你替镇上完成的差事。驯服野兽需要与其建立个人威势和共情。格瑞夫早已掌握这门技艺；你必须亲自学会如何运用驯兽棒的魔力，并抵挡猛扑而来的掠食者，以证明自己已准备好与一位终生相伴的伙伴并肩作战。",al={"为什么要我驯服它","为什么是我用驯兽棒","格瑞夫·野心为什么派我去"}}},fp="16,259,19.416.0,24.396.0,34.251.0,34.110.0,50.228.0,47.254.0,23.91.0,29.204.1"}
P.entries["quest:6085"] = {n="驯服野兽",s="此任务标志着矮人猎人在卡拉诺斯的格瑞夫指导下完成的基础训练的最后一项试炼。通过使用一根附魔的棍棒来制服并了解一头凶猛的冰爪熊，猎人展示了对纯粹蛮力的掌控。完成这项练习将解锁驯服、召唤和解散永久野生伙伴所需的基础能力。",h="此任务标志着矮人猎人在卡拉诺斯的格瑞夫指导下完成的基础训练的最后一项试炼。通过使用一根附魔的棍棒来制服并了解一头凶猛的冰爪熊，猎人展示了对纯粹蛮力的掌控。完成这项练习将解锁驯服、召唤和解散永久野生伙伴所需的基础能力。",kw={"丹莫罗","格瑞夫","猎人任务","冰爪熊","卡拉诺斯","宠物驯服","驯兽棒","taming the beast"},ang={["class:Hunter"]="这个任务是让孤立的弓箭手转变为真正的宠物驯服猎人的必经之路，它解锁了驯服和召唤野兽的基本能力。",["race:Dwarf"]="熊长期以来一直是巡逻丹莫罗的矮人山地探险者的标志性伙伴，它们以与主人一样顽强的韧性而闻名。"},sec={{t="野性的力量",b="在整个丹莫罗，山地探险者和侦察兵长期以来都依靠强壮的野兽来忍受严寒的岩壁。在指导学生练习对付敏捷而狡猾的掠食者之后，猎手大师格瑞夫指派新手猎人去捕捉一头冰爪熊。这些巨大的野兽经常在卡拉诺斯东部的雪堆中徘徊，它们体现了原始的体力和顽强的耐力——这是每一位矮人猎手都必须学会控制的品质。"},{t="获得伙伴",b="使用驯兽棒进行的试炼纯粹是教育性的练习，旨在教导猎人野生本能如何回应意志与平静的意图。一旦驯兽棒使熊变得温顺，这种暂时的羁绊便完成了它的使命。将工具交还给格瑞夫即完成了正式的试炼，促使这位大师分享野兽控制的永久秘密：如何安抚任何兼容的野生生物，并在漫长的冒险生涯中召唤它。"}},faq={{q="我需要为了这个任务驯服什么动物？",a="你必须寻找一头冰爪熊，它在丹莫罗卡拉诺斯东部的冰冻山脚下徘徊。使用提供的驯兽棒可以制服这个生物，这样你就能体验到驾驭原始蛮力的感觉。",al={"哪种熊","目标动物","驯服目标"}},{q="我在交还任务后可以保留这头冰爪熊吗？",a="不可以。被驯兽棒制服的熊只是对纪律和技巧的临时测试。一旦你将驯兽棒交还给格瑞夫，野兽就会离开，而你将被授予真正驯服任何你选择的野生野兽的能力。",al={"可以保留熊吗","保留宠物","熊是永久的吗"}},{q="格瑞夫在哪里？",a="格瑞夫驻扎在丹莫罗卡拉诺斯的雷酒酿制厂外，他在那里训练初出茅庐的猎人，传授他们射击和野兽控制之道。",al={"格瑞夫位置","格瑞夫在哪里","卡拉诺斯猎人训练师"}},{q="完成这次试炼后我能学到什么技能？",a="完成这项最终试炼将教会你猎人的基础法术：驯服野兽、召唤宠物和解散宠物。这使你可以冒险进入世界，并与一个永久的伙伴建立羁绊。",al={"任务奖励","猎人习得技能","驯服野兽奖励"}},{q="完成这个任务后的下一步是什么？",a="格瑞夫会让你继续进行“训练野兽”任务，指导你学习如何喂养、培育和正确指示你的新伙伴，以便它在战斗中保持忠诚。",al={"后续任务","what comes next","training the beast"}},{q="为什么格瑞夫要让猎人测试多种类型的野兽？",a="三项试炼让新手猎人接触到不同的战斗风格——敏捷、狡诈和蛮力。体验这些不同的性情，能让山地探险者为自己的狩猎风格选择最佳伙伴。",al={"为什么是三种野兽","试炼的目的","三种动物"}}},fx={d0a90924={q="什么是 Ice Claw Bear？它们为什么会出现在卡拉诺斯附近？",a="Ice Claw Bear 是原生于丹莫罗雪山的强壮掠食者，长着厚厚的毛皮，常在卡拉诺斯东面的荒野中出没。格瑞夫·野心认为，它们原始的耐力和蛮力使其成为猎人成长道路上的理想伙伴。面对一只 Ice Claw Bear，你必须证明自己能抵挡强大的力量，并在完全掌握驯服野兽的本领前，征服一只真正强悍的山地野兽。",al={"ice claw bear 的背景","为什么驯服 ice claw bear","丹莫罗的 ice claw bear"}}},fp="16,364,24.446.0,19.439.0,45.200.0,55.227.0,32.168.0,52.198.0,50.177.0,57.223.0"}
P.entries["quest:6086"] = {n="训练野兽",s="Training the Beast 是丹莫罗年轻矮人猎人的最终成人礼。在掌握了安抚并驯服白雪皑皑的山脊中野生猛兽的艺术后，新手游侠们被指引前往铁炉堡的中心，学习如何维持、训练和照料终生的动物伙伴。",h="Training the Beast 是丹莫罗年轻矮人猎人的最终成人礼。在掌握了安抚并驯服白雪皑皑的山脊中野生猛兽的艺术后，新手游侠们被指引前往铁炉堡的中心，学习如何维持、训练和照料终生的动物伙伴。",kw={"贝莉亚·雷岩","丹莫罗","矮人猎人","格瑞夫","hall of arms","铁炉堡","宠物训练","training the beast"},ang={["class:Hunter"]="这一里程碑解锁了猎人职业的核心定义：正确喂养、指挥和复活永久动物伙伴的能力。",["faction:Alliance"]="铁炉堡的兽王们为联盟的侦察部队做出了巨大贡献，他们依靠忠诚的荒野伙伴在严寒的山路上进行巡逻。",["race:Dwarf"]="矮人视狩猎为卡兹莫丹多山荒野的一种持久传统，将熊、野猪和山猫视为探索与防御中值得尊敬的伙伴。"},sec={{t="从荒野到熔炉",b="在证明了自己有能力对抗丹莫罗的凶猛野兽——用驯兽棒安抚大型岩鬃野猪、雪豹和强壮的冰爪熊——之后，猎人学徒们在卡拉诺斯附近的格瑞夫注视下完成了他们的试炼。然而，捕获动物的野性之心只是羁绊的一半。格瑞夫将他刚历练过的新手学员派上山路，前往铁炉堡，去寻找被称为 Hall of Arms 的军事区。"},{t="贝莉亚·雷岩的教导",b="在铁炉堡 Hall of Arms 的石拱顶下，站着矮人王国最受尊敬的野兽训练大师之一，贝莉亚·雷岩。贝莉亚传授了关键的知识，将一头野性、惊恐的野兽变成忠诚的战斗伙伴。她的教导远不止简单的命令：她向年轻的猎人展示了如何喂养宠物、传授它们新的战斗技能，甚至在它们为保卫主人而倒下时，如何从死亡边缘将它们的灵魂召唤回来。"},{t="矮人猎人的羁绊",b="矮人传统强调，驯服野兽的核心在于尊重而非征服。贝莉亚提醒每一位年轻的猎人，动物伙伴反映了它所受到的照料。如果喂养得当、受到尊重并经过适当的训练，野兽将在对抗穴居人、冰霜巨魔以及任何敢于威胁卡兹莫丹的敌人时，展现出坚定不移的忠诚。"}},faq={{q="这个任务的目的是什么？",a="这个任务标志着矮人猎人基础训练的最后一步。它将奖励你维护永久战斗宠物的核心知识，使你能够喂养它、训练它的能力、召唤它到你身边，并在它死亡时复活它。",al={"为什么要完成这个任务","training the beast 任务目的","猎人宠物任务奖励"}},{q="谁是贝莉亚·雷岩？",a="贝莉亚·雷岩是一位受人尊敬的野兽训练大师，驻扎在铁炉堡的 Hall of Arms。她是矮人游侠的高级教官，负责传授他们将驯服的野生动物变成终生盟友所需的纪律、饮食和命令。",al={"谁是贝莉亚","贝莉亚·雷岩背景故事","铁炉堡猎人训练师"}},{q="我在哪里可以找到贝莉亚·雷岩？",a="贝莉亚·雷岩位于铁炉堡的 Hall of Arms 内，这是该市的军事区，矮人和侏儒的战士、猎人以及圣骑士都在这里聚集和训练。",al={"贝莉亚位置","贝莉亚·雷岩在哪里","铁炉堡 hall of arms 在哪里"}},{q="矮人猎人在接受这项训练前会驯服哪些野兽？",a="在通往此任务的试炼过程中，格瑞夫通过要求年轻猎人使用附魔棒暂时安抚丹莫罗各地的大型岩鬃野猪、雪豹和冰爪熊，来考验他们。",al={"你会驯服什么野兽","矮人宠物试炼野兽","先导任务野兽"}},{q="为什么矮人猎人必须喂养他们的宠物？",a="矮人的野兽知识认为，动物伙伴是伙伴，而不是工具。忽视野兽的饥饿会导致其情绪恶化并削弱其战斗意愿，而保持良好的喂养则能确保它们在战斗中展现出凶猛的忠诚和最大的效力。",al={"为什么要喂养宠物","宠物快乐度背景知识","矮人野兽忠诚度"}},{q="谁发布了这个任务？",a="格瑞夫，那位驻扎在丹莫罗卡拉诺斯东侧路边的资深猎人训练师，会在你成功完成第三次驯服试炼后发布这个任务。",al={"谁开启 training the beast","格瑞夫的角色","任务发布者"}}},fx={["5ee43731"]={q="格瑞夫·野心为什么要派你去铁炉堡？",a="格瑞夫·野心引导你在丹莫罗的山岭间完成基础试炼，教你驯服野兽。然而，要掌握照料、喂养和管教野兽伙伴，还需要更高深的技艺。格瑞夫派你前往铁炉堡，让Hall of Arms中备受矮人尊敬的大师级训练师贝莉亚·雷岩完成你的训练，确保你的宠物成为可靠的盟友。",al={"格瑞夫为什么派你去","格瑞夫·野心的用意","猎人为什么要去铁炉堡"}}},fp="18,311,26.447.0,32.466.0,25.360.0,34.249.0,28.258.0,37.166.0,67.211.0,41.254.0,21.184.0"}
P.entries["quest:6087"] = {n="驯服野兽",s="这一试炼标志着牛头人猎人驯兽艺术启蒙的第二阶段。在血蹄村猎人训练师雅文·刺鬃的指引下，新手被要求驯服迅捷而无畏的草原巡行者。",h="这一试炼标志着牛头人猎人驯兽艺术启蒙的第二阶段。在血蹄村猎人训练师雅文·刺鬃的指引下，新手被要求驯服迅捷而无畏的草原巡行者。",kw={"血蹄村","猎人试炼","莫高雷","草原巡行者","驯兽棒","taming the beast","牛头人猎人","雅文·刺鬃"},ang={["class:Hunter"]="这次成年礼将基础的生存技巧与进攻性协作连接起来，教导你如何与快速攻击的伙伴并肩作战。",["race:Tauren"]="与那些纯粹将宠物视为工作动物的文化不同，舒哈鲁视驯兽为在大地母亲的慈爱注视下建立神圣的亲属关系。"},sec={{t="巡行者的课程",b="在成功掌握了成年陆行鸟的防御耐力后，雅文·刺鬃挑战这位年轻的猎人，要求其超越单纯的生存本能。草原巡行者代表了完全不同的狩猎哲学：无情的速度、狼群般的协作以及无畏的攻击性。驯服它需要以不间断的步调接近这只狡猾的捕食者，效仿狼本身那种果断的天性。"},{t="肌肉与肌肉的较量",b="对于牛头人来说，与野兽一同狩猎从不是关于奴役或单纯的征服。雅文·刺鬃强调，猎人和捕食者必须作为一个紧密的整体并肩作战，通过相互尊重和共同的节奏连接在一起。通过在莫高雷的广阔天空下与草原巡行者建立羁绊，猎人学会了在战斗的白热化阶段与伙伴的攻势相辅相成，并同步移动。"}},faq={{q="雅文·刺鬃要求我在这次试炼中驯服什么动物？",a="这第二堂课要求你驯服一只草原巡行者，这是一种游荡在莫高雷草海平原上的迅捷野狼。",al={"我要驯服什么野兽","下一个宠物是谁","驯服草原巡行者"}},{q="为什么牛头人猎人要学习驯服狼？",a="雅文·刺鬃教导说，草原巡行者体现了速度与无畏。通过与这样的捕食者建立羁绊，猎人能够将这些特质内化，学会如何与迅捷的狩猎伙伴无缝衔接，协同攻击。",al={"为什么要选狼","草原巡行者背景故事","为什么驯服狼"}},{q="通常能在哪里找到草原巡行者？",a="草原巡行者游荡在莫高雷中部和北部的草地平原上，经常在血蹄村周边的草原上徘徊。",al={"草原巡行者位置","草原巡行者在哪里","寻找草原巡行者"}},{q="任务完成后我可以留下这只草原巡行者吗？",a="不能。驯兽棒仅仅为了训练目的创造了一种暂时的羁绊。当你完成整个系列的试炼后，你将获得永久驯服你所选择的任何野生伙伴的能力。",al={"我可以留下这只狼吗","留下草原巡行者","这是我的永久宠物吗"}},{q="雅文·刺鬃是谁？",a="雅文·刺鬃是驻扎在血蹄村的猎人训练师。他引导年轻的牛头人完成掌握莫高雷荒野所需的精神和实践上的里程碑。",al={"雅文是谁","刺鬃背景故事","雅文血蹄"}},{q="驯服草原巡行者之后要做什么？",a="一旦雅文·刺鬃确认你已经驯服了这头野狼，他会派你去完成整个试炼链的第三项也是最后一项任务，考验你面对潜行掠翼者时的决心。",al={"下一个任务","草原巡行者之后是什么","第三个驯兽任务"}}},fx={f904daad={q="雅文·刺鬃为什么要我去驯服野兽，而不是自己动手？",a="这不是可以委派的任务或差事，而是你作为猎人接受训练时神圣的成人礼。雅文·刺鬃早已熟知荒野之道，也已与自然建立了自己的联系。要成为大地母亲真正的猎人，你必须亲自踏上这条道路，亲身面对迅捷无畏的掠食者，并将彼此的心灵联结起来，成为一个整体。",al={"雅文·刺鬃为什么选我","为什么必须驯服 prairie stalker","雅文为什么不自己驯服"}}},fp="16,233,21.405.0,16.376.0,60.124.0,46.237.0,44.136.0,53.198.0,21.187.0,44.173.0"}
P.entries["quest:6088"] = {n="驯服野兽",s="这次试炼是血蹄村的雅文·刺鬃指导下的牛头人猎手训练的最后一课。通过使用驯兽棒与一只野生迅猛龙建立羁绊，猎手证明了自己对空中生物的掌控力，并获得了大地母亲神圣的信任。完成此项任务将使你获得永久性的知识，学会驯服和指挥一位终生的伙伴。",h="这次试炼是血蹄村的雅文·刺鬃指导下的牛头人猎手训练的最后一课。通过使用驯兽棒与一只野生迅猛龙建立羁绊，猎手证明了自己对空中生物的掌控力，并获得了大地母亲神圣的信任。完成此项任务将使你获得永久性的知识，学会驯服和指挥一位终...",kw={"血蹄村","大地母亲","猎手宠物","莫高雷","迅猛龙","驯兽棒","taming the beast","雅文·刺鬃"},ang={["class:Hunter"]="这个任务完成了基础训练链，解锁了永久的野兽驯服，标志着你从一名学徒成长为一名完全能够独立生存的荒野斥候。",["race:Tauren"]="对于舒哈鲁人来说，与一只野生野兽建立羁绊是受到大地母亲祝福的精神交流行为，在莫高雷的平原上具有深远的文化意义。"},sec={{t="天空的掌控",b="在已经征服了莫高雷草海平原上的地面掠食者后，雅文·刺鬃将你的注意力转向了广阔的天空。迅猛龙是一种凶猛、拥有锐利喙部的猛禽，以其迅猛的俯冲和威慑性的姿态而闻名。将这种野生的空中猎手驯服是对你反应能力和冷静程度的考验，它要求你在承受其利爪攻击的同时，使用附魔的驯兽棒将你的精神与它的本能调和一致。"},{t="大地母亲的馈赠",b="对于牛头人来说，狩猎和驯养动物本质上是一种精神追求，而非仅仅是征服。通过掌握大地和天空的生物，你展现了在平原上行走而又不破坏自然所需的平衡与尊重。雅文·刺鬃认可了你的成熟，收回了他临时的驯兽棒，并将召唤、解散和永久驯服你所选伙伴的持久技巧传授给你。"}},faq={{q="为什么最终试炼必须要驯服一只迅猛龙？",a="雅文·刺鬃想要测试你面对空中生物的能力。迅猛龙拥有敏捷而锐利的攻击，且具有威慑力，这证明了猎手在获得真正的独立之前，既能应对空中掠食者，也能应对地面野兽。",al={"为什么要驯服迅猛龙","驯服迅猛龙的目的","为什么是迅猛龙"}},{q="在这个任务中驯服的迅猛龙我可以留下吗？",a="不能。作为仪式训练的一部分，迅猛龙是使用雅文·刺鬃的驯兽棒暂时驯服的。一旦你完成了任务，你将获得真正的能力，可以驯服任何你想永久保留的野生野兽。",al={"迅猛龙可以留下来吗","迅猛龙是我的宠物吗","我可以留下这只鸟吗"}},{q="谁发布了这个任务，他在哪里？",a="雅文·刺鬃，位于莫高雷中部血蹄村的猎手训练师，他发布了这个任务，这是你最初野兽驯服试炼的第三步，也是最后一步。",al={"任务发布者","谁开启了这个任务","雅文·刺鬃在哪里"}},{q="我归还驯兽棒之后会发生什么？",a="雅文·刺鬃会教给你独自驯服、召唤和解散野兽的固有能力。他还将引导你前往雷霆崖，学习如何正确地训练和照顾你所选的伙伴。",al={"接下来我学什么","完成任务的奖励","这个任务之后是什么"}},{q="我在莫高雷哪里可以找到野生的迅猛龙？",a="迅猛龙在莫高雷中部的开阔草原和台地边缘游荡，经常在血蹄村外的平原上盘旋。",al={"迅猛龙位置","迅猛龙在哪里","寻找迅猛龙"}},{q="为什么宠物驯服被认为是牛头人的成人礼？",a="牛头人文化不将野兽视为工具，而是视为大地母亲的子民。学习与伙伴建立羁绊需要耐心、相互尊重和精神平衡，而不是纯粹的力量。",al={"牛头人猎手传说","猎手的精神之路","大地母亲的联系"}}},fx={["8301e163"]={q="雅文·刺鬃为什么要我驯服一只 swoop？",a="雅文·刺鬃正引导你完成猎人训练的最后试炼。学会驯服天空中的生物，就能证明你已掌握驾驭各类野兽的本领。在大地母亲的恩泽下通过这最后的考验后，雅文终于可以赐予你永久的力量，让你驯服、召唤和解散一只由你选择的伙伴野兽。",al={"雅文·刺鬃的用意","为什么驯服 swoop","雅文为什么要我完成这件事"}},fc772ddc={q="雅文·刺鬃为什么要我参加这场试炼，而不是自己动手？",a="雅文·刺鬃早已精通猎人的道路；如今，他在血蹄村担任训练师和长者导师。驯服野兽不是可以交给村庄卫兵或导师代办的差事，而是至关重要的个人成人礼。在获得一位终生相伴的动物伙伴之前，你必须证明自己的心志，以及你与自然的联系。",al={"为什么是我来驯服野兽","雅文·刺鬃为什么派我去","为什么必须驯服 swoop"}}},fp="16,362,18.438.0,22.453.0,50.249.0,45.209.0,48.161.0,43.207.0,40.132.0,58.199.0"}
P.entries["quest:6089"] = {n="训练野兽",s="“Training the Beast”是莫高雷年轻牛头人猎人的最终成人礼。在展示了安抚平原野兽所需的精神耐心与决心后，猎人们将被派往雷霆崖，学习如何与一只终生的动物伙伴建立羁绊、喂养它并指挥它的终身纪律。",h="“Training the Beast”是莫高雷年轻牛头人猎人的最终成人礼。在展示了安抚平原野兽所需的精神耐心与决心后，猎人们将被派往雷霆崖，学习如何与一只终生的动物伙伴建立羁绊、喂养它并指挥它的终身纪律。",kw={"野兽训练","浩特·雷角","猎人高地","莫高雷","牛头人猎人","雷霆崖","training the beast","雅文·刺鬃"},ang={["class:Hunter"]="这项仪式标志着你从独自战斗转向与忠诚的伙伴并肩作战，完成了你作为荒野守护者的基础训练。",["race:Tauren"]="对于舒哈鲁而言，带着动物同伴参加战斗，肩负着神圣的守护职责，并承载着对大地母亲造物的尊重。"},sec={{t="通往大崖之路",b="在成功地针对莫高雷的危险掠食者——平原陆行鸟、草原狼和扫荡者——试炼过自己的精神后，牛头人猎人被认为已具备了传承猎人衣钵的资格。血蹄村的导师雅文·刺鬃会将这位新手托付给雷霆崖猎人高地的旅程。那里驻守着浩特·雷角，他是舒哈鲁中极具传奇色彩的人物，他对自然界的共鸣声誉仅次于他对大地母亲的虔诚。"},{t="神圣的羁绊",b="对牛头人而言，野兽并非简单的武器或奴隶；它是通过与自然世界和谐共处而获得的伙伴。浩特·雷角传授了维持这种伙伴关系所需的关键知识。猎人不仅必须学习如何引导生物的战斗本能，还要学习如何通过定期喂食来滋养它的身体、治愈它的伤口，并在它为保卫同伴而倒在平原上时唤回它的灵魂。"}},faq={{q="我该向谁交付这个任务？",a="你必须与雷霆崖猎人高地顶端的狩猎大师浩特·雷角交谈。一旦你在莫高雷驯服野兽的初步试炼完成，雅文·刺鬃就会指引你去找他。",al={"任务交付","浩特·雷角是谁","浩特在哪里"}},{q="牛头人猎人在完成此任务后能学会什么技能？",a="浩特·雷角会教你如何训练你的宠物学习新技能、如何喂养你的伙伴以保持其忠诚与满足，以及如何在宠物在战斗中阵亡时将其复活。",al={"我能获得什么能力","任务奖励技能","浩特教什么"}},{q="此任务在牛头人猎人任务链中处于什么位置？",a="这是该序列中的最后一个任务。它紧随“猎人之道”以及三部分的“Taming the Beast”试炼之后，在那些试炼中，猎人需要暂时安抚平原各处的一只成年平原陆行鸟、一只草原狼和一只扫荡者。",al={"猎人任务链","莫高雷宠物任务","training the beast系列任务"}},{q="为什么浩特·雷角在牛头人猎人中享有如此高的地位？",a="浩特一生都在对抗艾泽拉斯最凶猛的野兽来磨练自己，他能指挥多只强大的同伴，同时与大地母亲保持着深厚的精神纽带。他的智慧使他成为雷霆崖年轻舒哈鲁猎人的首席导师。",al={"浩特·雷角背景故事","浩特是谁"}},{q="猎人能在交付此任务前驯服他们的永久宠物吗？",a="你从之前的试炼中已经获得了驯服野兽的能力，但在与浩特·雷角交谈之前，你还缺乏喂养、复活所选同伴或教导其技能的知识。",al={"我现在能驯服宠物吗","我什么时候能得到宠物","我需要完成training the beast吗"}},{q="为什么在牛头人文化中，宠物照料与大地母亲有关？",a="牛头人将所有生物视为大地母亲的孩子。猎人不是靠纯粹的意志力来征服野兽，而是订立了一份精神契约，猎人提供食物和照料，以换取动物的忠诚和保护。",al={"牛头人宠物背景故事","大地母亲的野兽"}}},fx={["44ef2a73"]={q="雅文·刺鬃为什么要派你去找浩特·雷角？",a="雅文·刺鬃教会了你如何驯服野兽，但要驾驭并培育它们，还需要更深厚的智慧。他不愿让你的训练半途而废，因此指引你前往雷霆崖的猎人高地寻找浩特·雷角。浩特是牛头人中最受尊崇的猎人之一，曾在艾泽拉斯各地战胜凶猛的生物。只有像他这样与大地母亲有着深厚联系的人，才能恰当地赋予你养育和训练动物伙伴的神圣职责。",al={"雅文为什么要你离开","雅文·刺鬃的用意","为什么要去雷霆崖"}}},fp="18,336,27.484.0,13.429.0,33.201.0,63.180.0,53.226.0,71.272.0,66.194.0,58.257.0"}
P.entries["quest:609"] = {n="讨债行动",s="身处藏宝海湾的“海狼”马克基雷需要向三位老相识追讨欠债，以结清他的账目。尽管有传言称这些人受到了诅咒和蛊惑，在古老的丛林废墟中游荡，但马克基雷不在乎他们的悲惨命运，只要求你找回他们珍贵的财物。",h="身处藏宝海湾的“海狼”马克基雷需要向三位老相识追讨欠债，以结清他的账目。尽管有传言称这些人受到了诅咒和蛊惑，在古老的丛林废墟中游荡，但马克基雷不在乎他们的悲惨命运，只要求你找回他们珍贵的财物。",kw={"藏宝海湾","十指苏克","乌鸦乔乔","畸形足玛雷·威尔金斯","阿博拉兹废墟","朱布瓦尔废墟","海狼马克基雷","荆棘谷","巫毒之债"},sec={{t="未付的账目",b="在你之前为“海狼”马克基雷完成了一些收债任务后，这位海盗手中仍然有一份未结清的欠债清单。三名特定的债务人——“畸形足”玛雷·威尔金斯、乌鸦乔乔和“十指”苏克——已经拖欠债务数月之久。马克基雷起初以为这三人只是为了逃债而离开了藏宝海湾，但后来他听说他们在丛林深处遭遇了更加诡异的命运。"},{t="废墟中的诅咒",b="有传言称这三名债务人受到了蛊惑和诅咒，导致他们徘徊在藏宝海湾东北方的古代石构建筑区域，即阿博拉兹废墟和朱布瓦尔废墟。马克基雷并不关心他们的不幸，他指示你前往废墟，找到这三个人，并收回他们身上显眼的贵重物品：乔乔的金色望远镜、苏克的巨型戒指和玛雷的畸形足。"}},faq={{q="是谁要求追讨这些债务？",a="“海狼”马克基雷在他位于藏宝海湾的据点提出了这个请求。他正在清理一份欠债名单，绝不容许这些债务就此勾销。",al={"谁给予巫毒之债任务","海狼马克基雷任务"}},{q="这三名债务人是谁？",a="这三名债务人分别是“畸形足”玛雷·威尔金斯、乌鸦乔乔和“十指”苏克。他们的欠款已经拖欠了数月。",al={"谁欠马克基雷的钱","巫毒之债的目标"}},{q="在哪里可以找到这三名债务人？",a="他们徘徊在藏宝海湾东北方的古代石构建筑中，具体来说是在阿博拉兹废墟和朱布瓦尔废墟内。",al={"债务人在哪里","阿博拉兹和朱布瓦尔在哪里"}},{q="这三个人发生了什么事？",a="据传到马克基雷耳中的消息，这三个人受到了蛊惑和诅咒，现在在丛林废墟中游荡，而不是回到港口。",al={"为什么他们被诅咒了","他们出了什么问题"}},{q="需要找回哪些特定的物品？",a="马克基雷需要三件特定的贵重物品：乔乔的金色望远镜、苏克的巨型戒指和玛雷的畸形足。",al={"马克基雷想要什么物品","巫毒之债任务物品"}},{q="在这个任务链之前还有什么任务？",a="这是继“吓唬谢基”和“回到马克基雷那里”之后的任务，你将继续协助这位海盗完成他的收债清单。",al={"巫毒之债的前置任务","上一个任务"}}},fp="11,294,15.437.0,22.387.0,37.172.0,26.142.0,37.130.0,31.138.0,38.117.0,40.122.0"}
P.entries["quest:61"] = {n="送往暴风城的货物",s="“运往暴风城”是一个联盟的运送任务，它结束了威廉·匹斯特在艾尔文森林的蜡烛生意。在从当地的狗头人害虫那里收集了大蜡烛后，冒险者将包装好的货物沿着大路带入暴风城的贸易区，交给威廉的兄弟摩根·匹斯特。",h="“运往暴风城”是一个联盟的运送任务，它结束了威廉·匹斯特在艾尔文森林的蜡烛生意。在从当地的狗头人害虫那里收集了大蜡烛后，冒险者将包装好的货物沿着大路带入暴风城的贸易区，交给威廉的兄弟摩根·匹斯特。",kw={"艾尔文森林","闪金镇","狗头人蜡烛","摩根·匹斯特","匹斯特药店","运往暴风城","trade district","威廉·匹斯特"},ang={["faction:Alliance"]="带着物资沿着国王大道进入暴风城，对于从乡村小规模战斗转向繁华首都的年轻联盟勇士来说，是一次经典的试炼。",["profession:Herbalism"]="匹斯特家族的生意与艾尔文森林当地的试剂紧密相连，在他们的暴风城店铺停留是采集者和药剂师们熟悉的一项日常。"},sec={{t="家族生意",b="匹斯特兄弟在艾尔文森林的田园村落和暴风城繁华的大街之间维持着炼金贸易。威廉在闪金镇收集草药、试剂和原材料，而他的兄弟摩根则在首都的贸易区经营着匹斯特药店。由于威廉无法轻易离开他在Lion's Pride Inn的岗位，他便委托前往城门的旅行者来负责运送工作。"},{t="从狗头人蜡烛到首都药剂",b="威廉的包裹里装着从艾尔文森林矿洞里的狗头人身上收集的大蜡烛。他和摩根在暴风城经营着一家药店，威廉说他收集这些蜡烛是为了它们的蜡。完成这批货物的运送，就把这些物资带给了贸易区的摩根。"}},faq={{q="威廉的货物里有什么？",a="这批货物里装着从艾尔文森林的狗头人身上收集的蜡烛。威廉收集它们是为了获得蜡，并将它们打包好送到匹斯特药店交给摩根。",al={"货物内容","包裹里有什么","威廉寄了什么"}},{q="我在哪里可以找到摩根·匹斯特？",a="摩根·匹斯特在匹斯特药店里工作，该药店位于暴风城的贸易区，就在穿过正门后不远的地方。",al={"摩根·匹斯特位置","摩根在哪里","找到摩根·匹斯特"}},{q="威廉和摩根·匹斯特是什么关系？",a="威廉·匹斯特和摩根·匹斯特是兄弟，他们共同经营着一家炼金企业。威廉在艾尔文森林采购材料，而摩根则在暴风城经营他们的店铺。",al={"匹斯特兄弟","谁是威廉·匹斯特的兄弟"}},{q="为什么威廉不亲自去送包裹？",a="威廉忙于经营他的生意和在闪金镇收集炼金材料。他更倾向于雇佣路过的冒险者，这些冒险者正好要向北前往首都城门。",al={"为什么威廉不去暴风城","为什么要雇佣快递员"}},{q="狗头人蜡烛真的有炼金用途吗？",a="威廉说他和他的兄弟需要这些蜡烛的蜡。任务中并没有具体描述他们在药店里是如何使用这些蜡的。",al={"为什么是狗头人蜡烛","狗头人蜡烛炼金"}},{q="交付货物后接下来要做什么？",a="这次交付结束了从收集艾尔文森林狗头人蜡烛开始的简短任务链。摩根只是支付了你的快递费用，并欢迎你在他的店里进行交易。",al={"运往暴风城之后做什么","运往暴风城后续任务"}}},fp="21,176,14.276.0,34.219.0,34.157.0,30.116.0,42.173.0,48.166.0,48.119.0,41.188.0"}
P.entries["quest:610"] = {n="帅小伙子邓肯",s="在受她父亲之托追踪到利刃凯特琳后，一位冒险者得知她的武器已经不在她手中了。她要求在进一步合作之前，必须先从一个名叫“漂亮男孩”邓肯的海盗手中找回她丢失的匕首。",h="在受她父亲之托追踪到利刃凯特琳后，一位冒险者得知她的武器已经不在她手中了。她要求在进一步合作之前，必须先从一个名叫“漂亮男孩”邓肯的海盗手中找回她丢失的匕首。",kw={"血帆海盗","藏宝海湾","利刃凯特琳","凯特琳的利刃","漂亮男孩邓肯","荆棘谷"},ang={["class:Mage"]="凯特琳明确地嘲弄奥术学者，声称她离家出走正是为了避免整日被那些古板、灰发的施法者所包围。"},sec={{t="海盗的怨恨",b="顺着安斯雷姆的钥匙的线索，直接找到了利刃凯特琳。她为了逃离与法师们为伴、整日沉浸在陈旧书籍与学术研究中的平静生活而离家出走。她无法应她父亲的要求交出匕首，因为她已经没有那把匕首了。如果有人想要拿到她的利刃，就必须先去对付那个夺走它的血帆海盗。"},{t="被窃的钢刃",b="凯特琳在“漂亮男孩”邓肯手中遭遇了一场不同寻常的失败，邓肯打晕了她并拿走了她的标志性武器。作为一个依赖随身匕首战斗的战士，她坚持在进行任何后续行动之前，必须从那个血帆海盗手中夺回那把武器。"}},faq={{q="“漂亮男孩”邓肯是谁？",a="“漂亮男孩”邓肯是活跃在藏宝海湾附近的一名血帆海盗。他在战斗中击败了利刃凯特琳，将她打晕并夺走了她的匕首。",al={"漂亮男孩邓肯","邓肯是谁","邓肯海盗"}},{q="为什么凯特琳想要找回她的匕首？",a="凯特琳在战斗中完全依赖她的匕首，并拒绝使用其他武器。在与邓肯的匕首决斗中输掉武器后，她在帮助任何找上门来的人之前，都一定要先拿回这把刀。",al={"凯特琳匕首","凯特琳小刀","为什么要找回利刃"}},{q="凯特琳为什么要离家出走？",a="凯特琳抛弃了她的家庭，是为了逃离那种整日阅读古书并与刻板、年迈的法师为伍的枯燥生活；她拒绝过那种无聊的日子。",al={"凯特琳为何离家出走","安斯雷姆的女儿","凯特琳背景故事"}},{q="这一步在搜索过程中处于什么位置？",a="这次对抗发生在找回安斯雷姆的钥匙之后，在揭开潮汐诅咒之前。",al={"任务线","什么引向了漂亮男孩邓肯"}}},fp="19,241,20.347.0,16.294.0,25.164.0,38.189.0,35.161.0,41.111.0"}
P.entries["quest:6101"] = {n="驯服野兽",s="这一试炼标志着暗夜精灵猎人在多兰纳尔的达扎拉指导下进行宠物驯服训练的第二阶段。猎人的任务是使用一根附魔的驯兽棒去制服一只夜刃豹潜行者，以此更好地理解野生野兽不断变化的习性。这加深了泰达希尔的荒野与行走在树冠下的哨兵追踪者之间的理解纽带。",h="这一试炼标志着暗夜精灵猎人在多兰纳尔的达扎拉指导下进行宠物驯服训练的第二阶段。猎人的任务是使用一根附魔的驯兽棒去制服一只夜刃豹潜行者，以此更好地理解野生野兽不断变化的习性。这加深了泰达希尔的荒野与行走在树冠下的哨兵追踪者...",kw={"野兽驯服","达扎拉","多兰纳尔","猎人","夜刃豹潜行者","驯兽棒","泰达希尔"},ang={["class:Hunter"]="这一仪式代表了猎人教育的核心，在你被托付给终身同伴之前，教导你如何尊重不同动物的脾气。",["race:NightElf"]="夜刃豹与卡多雷的历史和文化紧密交织，使得驯服一头潜行者成为当地林地侦察兵的传统里程碑。"},sec={{t="野兽多变的本性",b="虽然早期的课程侧重于理解基本的本能，但达扎拉强调自然的唯一不变就是其持续的变化。森林中的每一个物种都有独特的脾气，猎人必须学会相应地调整自己的意志。在泰达希尔的树冠阴影下，这意味着要与那些狡猾、隐秘且比单纯的蛛网怪更具掠食性的生物打交道。"},{t="制服夜刃豹",b="夜刃豹被卡多雷奉为神圣的掠食者、凶猛的守护者，以及哨兵们隐秘的同伴。对于新手猎人来说，要对抗一只夜刃豹潜行者并引导驯兽棒的力量，需要坚定的意志和冷静的权威。通过将潜行者的掠食攻击性转化为一种接纳的纽带，猎人证明了他们不仅能驾驭温顺或弱小的林地生物。"}},faq={{q="这个任务的目的是什么？",a="这是暗夜精灵猎人任务链中的中间试炼，完成后可以解锁永久的野兽驯服能力。达扎拉会派你去驯服一只夜刃豹潜行者，让你观察不同掠食性生物之间的脾气差异。",al={"为什么要做这个任务","宠物驯服任务2","夜刃豹驯服目标"}},{q="哪里可以找到夜刃豹潜行者？",a="夜刃豹潜行者游荡在泰达希尔中部多兰纳尔以南的林间小径和灌木丛中。",al={"夜刃豹潜行者在哪里","潜行者位置","去哪里找猫"}},{q="我可以把这只夜刃豹潜行者留作我的永久宠物吗？",a="不能。用驯兽棒驯服的野兽是临时的，仅作为练习对象。当全部三个部分的试炼完成后并归还驯兽棒，你将学会真正的驯服技能，届时可以选择永久的同伴。",al={"我可以留下宠物吗","我可以留下夜刃豹吗","这是我永远的宠物吗"}},{q="谁发布了这个任务？",a="达扎拉，位于泰达希尔多兰纳尔的猎人训练师。在你完成第一次驯服测试后，他会发布这个指令。",al={"任务发布者","谁开始这个任务","达扎拉的位置"}},{q="为什么暗夜精灵如此推崇夜刃豹？",a="数千年来，夜刃豹一直与卡多雷共同生活，作为哨兵和艾露恩的祭司们的同伴、侦察兵和战骑。驯服一头夜刃豹被视为卡多雷精通林地生活的骄傲标志。",al={"暗夜精灵猫类背景","为什么夜刃豹很重要","夜刃豹背景资料"}},{q="完成这个任务后接下来做什么？",a="达扎拉会给予最后一个涉及泰达希尔另一种生物的驯服任务，在那之后才会教你驯服、喂养和管理艾泽拉斯各地永久同伴野兽的先天能力。",al={"下一个任务","夜刃豹潜行者之后是什么","猎人试炼后续"}}},fp="16,165,29.277.0,23.299.0,34.207.0,39.99.0,60.161.0,21.110.0,48.196.0,38.170.0"}
P.entries["quest:6102"] = {n="驯服野兽",s="这个任务标志着年轻的暗夜精灵猎人基础训练的最终试炼。在多兰纳尔的达扎拉的指导下，猎人必须驯服一只天空中的掠食猫头鹰，才能解锁选择真正终身伙伴的能力。",h="这个任务标志着年轻的暗夜精灵猎人基础训练的最终试炼。在多兰纳尔的达扎拉的指导下，猎人必须驯服一只天空中的掠食猫头鹰，才能解锁选择真正终身伙伴的能力。",kw={"野兽","达扎拉","多兰纳尔","猎人宠物","screecher","strigid screecher","驯服","驯兽棒","泰达希尔"},ang={["class:Hunter"]="这个成年礼是猎人从孤军奋战到与野生伙伴建立终身合作关系的转折点。",["race:NightElf"]="驯服泰达希尔本土的野生动物，反映了卡多雷与自然和谐共处，而非以武力征服的道路。"},sec={{t="树冠的掌控",b="在完成最初的野兽技艺之前，暗夜精灵猎人必须与泰达希尔生态系统各个角落的生物建立和谐关系。在证明了对抗林下野兽的意志之后，达扎拉要求猎人制服天空之灵：Strigid Screecher。这些警觉的猛禽栖息在多兰纳尔西侧高处的枝干上，需要耐心和稳定的神经才能用附魔的驯兽棒将其安抚。"},{t="猎人的羁绊",b="成功制服Strigid Screecher意味着完成了卡多雷猎人与自然沟通的古老课程。当学徒将用过的棒子还给达扎拉时，他们就结束了训练，并获得了在艾泽拉斯召唤、遣散以及永久驯服自己选择的野兽的完整技艺。"}},faq={{q="Strigid Screecher在哪里？",a="Strigid Screecher栖息在多兰纳尔西侧的树林里。猎人必须在村外树冠和根须间寻找这些掠食鸟类，以测试他们的驯兽棒。",al={"screecher位置","strigid screecher在哪里","猫头鹰位置"}},{q="达扎拉是谁？",a="达扎拉是一位驻扎在多兰纳尔的暗夜精灵猎人训练师。他负责指导那些在射箭和追踪方面达到基本水平的年轻卡多雷，在赋予他们绑定真正动物伙伴的能力之前，先测试他们对陆地和天空野兽的应对能力。",al={"达扎拉的角色","谁在多兰纳尔教授驯兽","多兰纳尔的猎人训练师"}},{q="我能把Strigid Screecher留作宠物吗？",a="不能。在此试炼中驯服的Screecher只是暂时的，仅受驯兽棒魔法的束缚。一旦试炼完成，驯兽棒就会上交，猎人将学习如何在这个世界上驯服自己选择的永久伙伴。",al={"保留猫头鹰","screecher是永久的吗","我能保留这只宠物吗"}},{q="完成这个试炼后会发生什么？",a="达扎拉会永久解锁你驯服、召唤和遣散野兽的能力。他还指引你去达纳苏斯接受进一步的训练，以学习喂养和在战斗中教导伙伴的重要技巧。",al={"what comes next","taming the beast任务之后","猎人宠物任务完成"}},{q="为什么暗夜精灵特别驯服猫头鹰？",a="猫头鹰之类的猛禽在卡多雷文化中具有深远的意义，它们是警觉的黑夜猎手和值得信赖的侦察兵。征服一种天空生物证明了猎人不仅了解陆地野兽，也了解空中掠食者。",al={"猫头鹰的暗夜精灵背景","为什么选择猫头鹰","strigid screecher的重要性"}},{q="猎人在完成这个任务后可以选择任何动物吗？",a="是的。一旦达扎拉教授了永久驯服能力，猎人就可以自由寻找泰达希尔乃至更广阔天地中任何可驯服的陆地、水下或天空野兽。",al={"我可以获得什么宠物","选择第一只宠物","所有野兽都可以驯服吗"}}},fp="16,227,21.382.0,15.315.0,35.156.0,15.231.0,49.244.0,41.193.0,42.253.0,47.145.0"}
P.entries["quest:6103"] = {n="训练野兽",s="Training the Beast是泰达希尔的新手暗夜精灵猎人的最终成人礼。在通过驯服各地树枝上的野兽证明了自己的掌控能力后，猎人们会被派往达纳苏斯，向祖卡斯特学习更深奥的宠物护理和驯服技巧。",h="Training the Beast是泰达希尔的新手暗夜精灵猎人的最终成人礼。在通过驯服各地树枝上的野兽证明了自己的掌控能力后，猎人们会被派往达纳苏斯，向祖卡斯特学习更深奥的宠物护理和驯服技巧。",kw={"塞纳里奥区","达纳苏斯","达扎拉","猎人宠物","祖卡斯特","泰达希尔","training the beast"},ang={["class:Hunter"]="这项仪式标志着你从一名新手追踪者毕业，成为了一名真正的野兽大师，解锁了训练、喂养和复活你伙伴的能力。",["race:NightElf"]="卡多雷的野兽伙伴传统以尊重与共存为核心，反映了达纳苏斯和塞纳里奥区传授的教义。"},sec={{t="猎人的成人礼",b="在暗夜精灵猎人能够带着忠诚的伙伴漫游卡利姆多之前，他们必须掌握的不仅仅是驯兽棒。虽然制服一只野兽能证明基本的实力和意志，但未经训练的野兽仍然是一个不可预测的隐患。一旦新兵在多兰纳尔周边的荒野中展现了自己的能力，达扎拉就会指引他们前往达纳苏斯完成训练。"},{t="塞纳里奥区的指导",b="在塞纳里奥区宁静的树林中，受人尊敬的猎人祖卡斯特传授着伙伴关系的重要技艺。她教导年轻的猎人如何适当地喂养宠物，在悲剧发生时如何复活它，并通过训练培养它的战斗本能。对暗夜精灵来说，这种关系植根于对自然的深切敬畏，而非单纯的支配。"}},faq={{q="这个任务的目的是什么？",a="此任务是暗夜精灵猎人初始宠物任务线的最后一环。它会指引你前往达纳苏斯，解锁维持和训练你的永久动物伙伴所需的核心技能。",al={"为什么要完成这个任务","暗夜精灵宠物训练任务","training the beast有什么用"}},{q="我在哪里可以找到祖卡斯特？",a="祖卡斯特住在达纳苏斯的塞纳里奥区，位于这座首都西北部高耸的树木和猎人小屋之间。",al={"祖卡斯特在哪里","祖卡斯特的位置","寻找祖卡斯特"}},{q="谁发布这个任务？",a="在你完成泰达希尔各地的全部三项驯服考验后，多兰纳尔的猎人训练师达扎拉会提供此任务。",al={"任务发布者","谁发布training the beast","达扎拉的位置"}},{q="你可以从祖卡斯特那里学到什么技能？",a="与祖卡斯特交谈将解锁野兽掌握的核心技艺：喂养你的伙伴，在它战斗中倒下时将其复活，以及通过训练赋予它新的能力。",al={"我可以获得什么能力","祖卡斯特的奖励","猎人宠物法术"}},{q="为什么暗夜精灵文化强调宠物训练？",a="卡多雷猎人将他们的宠物视为伙伴而非从属工具。适当的训练和护理反映了该种族与自然和谐共处并敬畏自然的这一核心哲学。",al={"暗夜精灵猎人背景故事","为什么暗夜精灵要训练野兽"}},{q="其他种族可以接取此任务吗？",a="这趟前往达纳苏斯的特殊旅程是暗夜精灵猎人独有的。其他种族的猎人会在各自种族的导师指导下进行同等的训练仪式。",al={"矮人能做这个任务吗","部落能做training the beast吗"}}},fp="18,173,26.306.0,32.258.0,34.172.0,24.112.0,21.116.0,38.107.0,50.133.0,39.131.0"}
P.entries["quest:611"] = {n="海潮的诅咒",s="利刃凯特琳从Pretty Boy Duncan那里找回了她的匕首，并借出了这件巨魔神器，以便将其用于摧毁海岸外的一座沉没祭坛。藏宝海湾的大财主里维加兹想要得到海潮之石，以充实他的古代巨魔神器收藏。",h="利刃凯特琳从Pretty Boy Duncan那里找回了她的匕首，并借出了这件巨魔神器，以便将其用于摧毁海岸外的一座沉没祭坛。藏宝海湾的大财主里维加兹想要得到海潮之石，以充实他的古代巨魔神器收藏。",kw={"海潮之石的祭坛","大财主里维加兹","藏宝海湾","利刃凯特琳","加兹班","海潮之石","荆棘谷","暗礁海"},ang={["faction:Alliance"]="联盟冒险者完成了大财主里维加兹对这件古代圣物的搜寻，深入靠近部落格罗姆高营地的水域。"},sec={{t="沉没的祭坛",b="利刃凯特琳借出了她找回的那把巨魔匕首，用来破坏一座深埋在波浪之下的祭坛。虽然她不像她父亲那样是研究巨魔遗迹的专家，但她听说过一座沉没的巨魔城市，并指出了它的位置，就在格罗姆高营地西北方的暗礁海附近。在暗礁海的水下遗迹中，海潮之石的祭坛静静伫立，在一片海洋生物和鱼人之间散发着独特的蓝色光芒。"},{t="被困的法师",b="用利刃凯特琳的匕首击打海潮之石的祭坛会粉碎其魔法，并引出加兹班，一个携带着海潮之石的地精法师，他在受到挑战时会化身为水元素。一旦击败他，这块石头便可与借来的匕首一同带回藏宝海湾。在那里，大财主里维加兹准备了一个特别的展示台，将这件圣物所蕴含的海洋魔法展示在他的珍贵藏品中。"}},faq={{q="海潮之石的祭坛位于何处？",a="祭坛位于暗礁海深处的海底，是一处沉没的遗迹，坐落在格罗姆高营地西北方的海岸外。它在水下散发着显眼的蓝色光芒。",al={"祭坛在哪里","海潮之石的祭坛位置","我该去哪里找到祭坛"}},{q="大财主里维加兹为什么要这块石头？",a="大财主里维加兹是一位狂热的古代巨魔文物收藏家，他特意清理了空间并购买了一个精美的展示台，专门用来展示这件圣物。",al={"里维加兹的石头","为什么里维加兹想要石头","里维加兹怎么处理它"}},{q="利刃凯特琳为什么要借出她的匕首？",a="在从Duncan那里找回了她那把特殊的匕首后，利刃凯特琳借出了这件巨魔圣物来粉碎祭坛，并要求在事情办完后将其安全归还。",al={"凯特琳的匕首","为什么要借出匕首","利刃凯特琳"}}},fp="22,251,16.404.0,16.424.1,40.176.0,39.146.0,32.158.0"}
P.entries["quest:6121"] = {n="新的课程",s="“新的课程”是达纳苏斯的玛斯雷·驭熊者给予暗夜精灵德鲁伊新手的入门任务。它指引新手前往神圣的月光林地，与德迪利特·星焰会面，并开始学习净化毒素和毒液的艺术。",h="“新的课程”是达纳苏斯的玛斯雷·驭熊者给予暗夜精灵德鲁伊新手的入门任务。它指引新手前往神圣的月光林地，与德迪利特·星焰会面，并开始学习净化毒素和毒液的艺术。",kw={"奥伯丁","塞纳留斯","治疗毒素","德迪利特·星焰","“新的课程”","玛斯雷·驭熊者","月光林地","永夜港","解毒之力"},ang={["class:Druid"]="这次成人礼标志着你从基础的变形与生存过渡到真正成为荒野的守护者，教会你从自然中解除致命的枯萎与毒素。",["faction:Alliance"]="威胁奥伯丁的危机突显了德鲁伊的援助对于保卫黑海岸北部脆弱的联盟定居点是多么至关重要。",["race:NightElf"]="该任务由达纳苏斯的塞纳里奥区发布，将年轻的卡多雷直接与月光林地和黑海岸更深层次的祖先责任联系起来。"},sec={{t="塞纳留斯的礼物",b="德鲁伊与生灵世界有着神圣的联系，这种联系是通过半神塞纳留斯的教导与祝福传承下来的。这些天赋之一便是能够通过简单的咒语来清除污秽的毒素。然而，如此强大的天赋绝不会轻易授予新手。为了真正尊重魔法艺术带来的非凡便利，年轻的德鲁伊必须首先了解在没有自然之力直接干预的情况下，通过艰苦的世俗劳作来对抗毒素的必要性。"},{t="前往永夜港的召唤",b="居住在达纳苏斯塞纳里奥区的德鲁伊训练师玛斯雷·驭熊者指示他的学生跳过本地的练习，直接前往月光林地。在那里，在宁静的永夜港，德迪利特·星焰负责协调塞纳里奥议会的广泛事务，并准备好为新手分配一项紧急的实战任务。"},{t="现实世界的危机",b="到达永夜港后，新手们会了解到他们的试炼并非某种精心编排的测试或刻板的仪式。黑海岸的奥伯丁定居点正面临严重的动物中毒事件，当地人对此束手无策。德迪利特·星焰指派新手去调查并援助黑海岸，将他们直接推向一个生死攸关的现实危机之中。"}},faq={{q="谁提供了“新的课程”这个任务？",a="该任务由达纳苏斯塞纳里奥区的暗夜精灵德鲁伊训练师玛斯雷·驭熊者提供。",al={"谁提供“新的课程”","“新的课程”任务给予者","玛斯雷·驭熊者任务"}},{q="我需要去哪里完成这个任务？",a="你必须前往神圣的德鲁伊领域月光林地，并向位于宁静的永夜港定居点的德迪利特·星焰汇报。",al={"我要去哪里","德迪利特·星焰在哪里","“新的课程”交任务地点"}},{q="为什么德鲁伊必须首先像外行一样学习治疗毒素？",a="德鲁伊导师们认为，仅仅通过念咒就能获得塞纳留斯治疗毒液的神奇天赋，可能会滋生自满情绪。通过让新手首先学习并使用草药和世俗方法来解决毒素危机，他们确保德鲁伊能够真正尊重毒素所带来的负担和痛苦。",al={"为什么要像外行一样学习","为什么要在没有魔法的情况下治疗毒素","塞纳留斯的毒素教诲"}},{q="奥伯丁发生了什么问题？",a="奥伯丁正遭受黑海岸沿岸严重的动物中毒事件的困扰。当地的暗夜精灵无法治愈这种病痛，促使他们向月光林地的塞纳里奥议会发出求援。",al={"奥伯丁的毒素问题","奥伯丁发生了什么","黑海岸动物中毒事件"}},{q="这个任务链最终会奖励什么技能？",a="该任务开启了“解毒之力”任务链，教导德鲁伊掌握关键的“解毒术”法术，使他们能够通过魔法清除盟友身上的毒素。",al={"我能获得什么奖励","治疗毒素任务","“解毒之力”任务链"}},{q="部落的德鲁伊可以接这个任务吗？",a="不可以。“新的课程”是专属于达纳苏斯的联盟版本任务。牛头人德鲁伊在雷霆崖会接到一个平行的任务，同样指引他们前往月光林地学习治疗毒素的艺术。",al={"部落的“新的课程”","牛头人可以做这个任务吗","牛头人的“新的课程”"}}},fp="12,167,20.322.0,21.251.0,19.277.1,34.94.0,45.67.0,58.217.0,42.166.0,52.124.0,40.178.0"}
P.entries["quest:6122"] = {n="毒水之源",s="“源头之水”是年轻暗夜精灵德鲁伊了解并修复自然界的重要试炼。德鲁伊学徒受月光林地的德迪利特·星焰派遣，必须从黑海岸的壁泉河收集被污染的水，以帮助奥伯丁的博物学家奥兰达利亚·夜歌阻止一场在林中鹿群间蔓延的瘟疫。",h="“源头之水”是年轻暗夜精灵德鲁伊了解并修复自然界的重要试炼。德鲁伊学徒受月光林地的德迪利特·星焰派遣，必须从黑海岸的壁泉河收集被污染的水，以帮助奥伯丁的博物学家奥兰达利亚·夜歌阻止一场在林中鹿群间蔓延的瘟疫。",kw={"奥兰达利亚·夜歌","奥伯丁","塞纳里奥议会","峭壁之泉","治愈毒素","黑海岸","德迪利特·星焰","娜迦","祛除毒素"},ang={["class:Druid"]="这项任务是基础德鲁伊试炼的一部分。通过对抗壁泉河的生态衰退并配制解毒剂，你将唤醒在野外治愈毒素所需的精神和植物学知识。",["race:NightElf"]="对于奥伯丁的卡多雷来说，壁泉河的腐蚀是对他们祖先森林的直接亵渎，要求立即采取干预措施以保护这片土地上无辜的生灵。"},sec={{t="被污染的生命之源",b="壁泉河是黑海岸北部地区主要的淡水来源。当野生动物——特别是当地的鹿群——开始感染一种非自然、持续性的疾病时，塞纳里奥议会将目光转向了这条河流。德迪利特·星焰怀疑含水层本身受到了影响，因此委托新手德鲁伊去壁泉河瀑布下的洞穴入口，采集一份未受干扰的污染水样，这是一项至关重要的任务。"},{t="瀑布下的阴影",b="取水的过程并非没有危险。邪恶的娜迦已经在壁泉河洞穴内盘踞，并在瀑布源头附近筑巢。它们在地底泉水附近的存在，对任何调查这起枯萎病的人构成了直接威胁。尽管危险重重，但从洞口获取一份未受污染的样本，是塞纳里奥议会研究导致荒野染病之源的唯一途径。"},{t="更深层的疾病",b="当把样本送到奥伯丁的奥兰达利亚·夜歌手中后，水的污秽证实了议会最担心的事。然而，检查这种肮脏的液体揭示了一个令人不安的事实：虽然被污染的瀑布确实是毒害河岸的主要源头，但在远离其直接路径的地方也发现了受感染的鹿。这些水是制作解毒剂的重要试剂，但奥兰达利亚怀疑一种更深、更广泛的腐蚀正在蔓延至黑海岸整个地下水系。"}},faq={{q="为什么壁泉河对黑海岸如此重要？",a="壁泉河是黑海岸北部主要的天然饮用水源。由于其水流供给当地的溪流、河流以及周边的植被和动物，任何在源头引入的污染物都会迅速扩散到整个地区生态系统中。",al={"壁泉河的重要性","黑海岸的水源"}},{q="为什么黑海岸的鹿会生病？",a="当地的鹿直接饮用壁泉河及其支流的水。一种剧毒污染物污染了源头的地下水系，导致这些林中生物遭受了严重的、衰弱性的疾病。",al={"为什么鹿会生病","黑海岸生病的鹿","是什么毒害了鹿"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位居住在神圣避难所月光林地的德鲁伊导师。他作为进阶德鲁伊的向导，监控着整个卡利姆多的动乱，并协调塞纳里奥议会对自然危机的应对。",al={"德迪利特·星焰背景","谁给了我这个任务","星焰月光林地"}},{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位驻扎在奥伯丁的暗夜精灵博物学家。她对黑海岸蔓延的腐蚀和饱受折磨的动物群感到忧心忡忡，于是向月光林地的塞纳里奥议会请求有经验的援助，以研究这种疾病并制定治疗方法。",al={"谁是奥兰达利亚·夜歌","夜歌奥伯丁"}},{q="为什么娜迦会出现在壁泉河？",a="来自黑海岸沿岸的娜迦已经深入内陆，占据了壁泉河后的洞穴系统。它们日益逼近的存在，对任何试图进入源头调查水源的人来说都构成了极大的威胁。",al={"壁泉河洞穴中的娜迦","为什么娜迦在这里","壁泉河娜迦"}},{q="这项任务帮助德鲁伊学习什么能力？",a="这项调查是“祛除毒素”试炼的一部分。通过诊断这种野生动物瘟疫，并与奥兰达利亚·夜歌一起合成解毒剂，德鲁伊学徒可以学习治愈毒素这一重要的魔法艺术。",al={"这个任务奖励什么法术","德鲁伊去毒任务","去毒任务线"}}},fp="20,228,26.317.0,20.243.0,15.334.1,51.184.0,42.156.0,26.190.0,29.221.0,34.192.0,47.185.0"}
P.entries["quest:6123"] = {n="收集解药",s="“搜集治疗材料”是年轻的暗夜精灵德鲁伊在黑海岸学习驾驭自然治疗之力的重要试炼。在奥伯丁的奥兰达利亚·夜歌指导下，德鲁伊收集关键的天然试剂，为该地区患病的野生动物配制修复药膏。这项任务为理解草药如何对抗毒素和疾病奠定了实践基础。",h="“搜集治疗材料”是年轻的暗夜精灵德鲁伊在黑海岸学习驾驭自然治疗之力的重要试炼。在奥伯丁的奥兰达利亚·夜歌指导下，德鲁伊收集关键的天然试剂，为该地区患病的野生动物配制修复药膏。这项任务为理解草药如何对抗毒素和疾病奠定了实践...",kw={"奥兰达利亚·夜歌","奥伯丁","解除中毒","黑海岸","德鲁伊任务","地根草","搜集治疗材料","月亮菇","枭兽洞穴"},ang={["class:Druid"]="这一成人礼教会年轻的德鲁伊凡人医学是如何与自然毒素相互作用的，为在没有世俗工具的情况下引导原始治疗能量奠定了基础。",["profession:Herbalism"]="奥兰达利亚特别指出了草药师的价值，他们拥有直接从大地中采集地根草所需的训练有素的眼光。",["race:NightElf"]="保护黑海岸的神圣树林和动物是卡多雷的神圣职责，他们崇敬艾露恩和荒野的灵魂。"},sec={{t="黑海岸野生动物的救星",b="在发现当地野生动物受污染的水源困扰后，奥伯丁的奥兰达利亚·夜歌着手调制一种有效的治疗药膏。虽然采样到的崖泉水构成了混合物的基础，但真正的疗效需要强效的天然催化剂。受感染的林地鹿无法自行恢复，这使得收集有益的治疗材料成为塞纳里奥议会的当务之急。"},{t="根茎与月亮之花",b="这种修复药膏需要两种关键植物：地根草和月亮菇。地根草具有纯粹的治疗功效，需要草药师受过训练的眼睛才能从岩石土壤中采集。为了增强混合物的药效，奥兰达利亚派遣德鲁伊前往附近的东部洞穴，收集那些在黑暗中繁茂生长，并隐藏在日益具有领地意识且焦躁不安的枭兽群中的真菌花朵。"},{t="净化毒素之路",b="为每种毒素合成特定的解毒剂是一项细致且艰巨的任务。通过引导新手完成物理原料的精细采集和酿造过程，奥兰达利亚展示了传统医学所付出的巨大努力。这种亲手制作的过程是通往掌握德鲁伊通过自然魔法净化毒素的先天艺术的垫脚石。"}},faq={{q="“搜集治疗材料”的目的是什么？",a="该任务要求德鲁伊新手为奥伯丁的奥兰达利亚·夜歌收集地根草和月亮菇。这些试剂用于制作治疗药膏，以治疗黑海岸患病的鹿，作为学习中和毒素的教学步骤。",al={"为什么要完成这个任务","搜集治疗材料目标","搜集治疗材料的用途"}},{q="月亮菇在哪里生长？",a="月亮菇生长在奥伯丁正东方山丘内的洞穴中。德鲁伊必须小心地穿过这些巢穴，因为居住在那里的野生枭兽已经变得富有领地意识且具有攻击性。",al={"月亮菇在哪里","月亮菇位置","如何找到月亮菇"}},{q="我需要成为草药师才能获得地根草吗？",a="你不需要自己学习草药学，尽管地根草是从野外草药节点采集的。如果你没有学习该专业，你必须与草药师交易或从他人处获取，以完成奥兰达利亚的配方。",al={"地根草需要草药学吗","非草药师能获得地根草吗","无需专业获取地根草"}},{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位驻扎在奥伯丁的暗夜精灵，她向塞纳里奥议会寻求帮助。她监测着黑海岸动植物的健康状况，引导年轻的德鲁伊完成最初的试炼，以净化和保护这片荒野。",al={"奥兰达利亚是谁","奥兰达利亚·夜歌背景故事"}},{q="为什么黑海岸的鹿会生病？",a="这些鹿食用了荒野中受污染泉水的水。由此产生的毒素使它们丧失能力并遭受痛苦，需要一种有效的治疗药膏来缓解它们的症状。",al={"为什么鹿会中毒","黑海岸生病的鹿","是什么毒害了鹿"}},{q="这个任务如何帮助我学习“解除中毒”？",a="该任务是更大的“毒素之力”训练的一部分。通过向新手展示为各种毒素准备草药解毒剂是多么费力，塞纳里奥议会让他们准备好引导原始的自然魔法，从而能够毫不费力地中和毒素。",al={"德鲁伊解除中毒任务","学习解除中毒","毒素之力系列任务"}}},fx={["0cfb14cd"]={q="奥兰达利亚·夜歌为什么要你完成这件事？",a="作为一名在奥伯丁守望黑海岸的德鲁伊，奥兰达利亚无法眼看当地野生动物受苦而袖手旁观。当地的鹿染上了一种令人衰弱的疾病，无法自行康复。她眼下最要紧的是配制有效的疗伤膏，尽快结束它们的痛苦，并恢复这片遭到污染的森林的平衡。",al={"奥兰达利亚的动机","为什么要帮助病鹿","奥兰达利亚为什么在意"}},e3b496ec={q="大地之根有什么用？",a="奥兰达利亚用大地之根为疗伤膏注入恢复活力的特性。将它混入取自峭壁之泉的水样中——那是药膏的基底——这种草药天然的药性便能抵消使黑海岸的鹿染病的毒素。",al={"为什么要大地之根","大地之根有什么作用","大地之根药膏"}},["74e6ce3c"]={q="月亮菇有什么用？",a="月亮菇能为药膏提供必要的效力。它强大的天然生长力可以增强混合物的疗效，确保药剂足以清除患病鹿体内根深蒂固的毒素。",al={"为什么要月亮菇","月亮菇的用途","药膏为什么需要月亮菇"}}},fp="18,378,33.428.0,22.396.0,28.386.1,42.269.0,33.196.0,46.214.0,29.248.0,35.204.0,46.260.0"}
P.entries["quest:6124"] = {n="消除疾病",s="“治愈伤病者”是年轻的联盟德鲁伊的一项基本试炼，要求他们使用准备好的药膏去治疗徘徊在Darkshore的受毒害野生动物。通过直接缓解患病鹿群的痛苦，初学者们在向月光林地的塞纳里奥议会报告之前，解决了困扰卡利姆多北部地区那日益严重的颓势。",h="“治愈伤病者”是年轻的联盟德鲁伊的一项基本试炼，要求他们使用准备好的药膏去治疗徘徊在Darkshore的受毒害野生动物。通过直接缓解患病鹿群的痛苦，初学者们在向月光林地的塞纳里奥议会报告之前，解决了困扰卡利姆多北部地区那...",kw={"奥兰达利亚·夜歌","奥伯丁","塞纳里奥议会","壁泉河","动物医疗药膏","治愈伤病者","darkshore","德迪利特·星焰","毒素","生病的鹿"},ang={["class:Druid"]="这次成人礼测试了初学者对于维护平衡的承诺，并作为获得用德鲁伊魔法净化毒素的天赋能力的桥梁。",["race:NightElf"]="Darkshore代表了现代暗夜精灵定居点的祖先边界，这使得鹿群中突然出现的枯萎病对Kaldorei来说是一个不祥之兆。"},sec={{t="林地中的瘟疫",b="在Darkshore阴暗的森林中，从壁泉河的水域向南一直到灰谷的边界，当地的野生动物正遭受着持续不断的疾病折磨。患病的鹿群在雾气中漫无目的地徘徊，因渗入土壤和溪流的非自然毒素而变得虚弱。在收集了必要的试剂后，奥兰达利亚·夜歌委托一位有抱负的德鲁伊使用新鲜调制的动物医疗药膏去野外治疗那些受苦的生物。"},{t="月光林地中洞悉的目光",b="一旦治疗了十头鹿，初学者会被派往月光林地的神圣避难所，向德迪利特·星焰报告。虽然奥伯丁能稍微松一口气，但德迪利特却将这些病弱的鹿群视为席卷卡利姆多北部地区那更邪恶腐化的预兆。他警告说，当达纳苏斯的领导者们还在争论并忽视那蔓延的腐朽时，塞纳里奥议会必须对正在整个大陆扎根的生态腐化的真实规模保持警惕。"}},faq={{q="为什么Darkshore的鹿会生病？",a="鹿群正在遭受一种蔓延的生态腐化的折磨，这种腐化已经开始渗入Darkshore的水域和土壤，从壁泉河一直延伸到南部的灰谷。作为野生食草动物，这些鹿无意中食用了被污染的植物和河水，因此变得虚弱且染病。",al={"为什么鹿会生病","darkshore生病的鹿","是什么毒害了鹿"}},{q="是谁制作了用于治疗鹿群的动物医疗药膏？",a="奥兰达利亚·夜歌，一位驻扎在暗夜精灵城镇奥伯丁的暗夜精灵，用德鲁伊初学者收集的稀有试剂制作动物医疗药膏。她调制的一批药膏提供了十剂，可以立即治疗受苦的动物，同时她也在尝试与镇民们一起制作更多药膏。",al={"谁制作了治疗药膏","奥兰达利亚的药膏","动物医疗药膏制作者"}},{q="为什么德迪利特·星焰会关心这些鹿？",a="德迪利特·星焰代表月光林地的塞纳里奥议会监督德鲁伊的训练。对他而言，照料野生动物既是对德鲁伊职责的实践检验，也是一种鲜明的证据，表明某种更广泛、更危险的腐化正在接管卡利姆多的荒野。",al={"为什么是德迪利特和月光林地","塞纳里奥议会对鹿群的关注","德迪利特·星焰的职责"}},{q="德迪利特·星焰暗示了怎样的政治紧张局势？",a="在完成任务后，德迪利特指出，虽然达纳苏斯的一些暗夜精灵当局承认日益严重的环境腐化，但其他人却固执地忽视了这些警告信号。他敦促初学者永远不要对自然界面临的不适事实视而不见。",al={"达纳苏斯的紧张局势","谁忽视了这种腐化","达纳苏斯的视而不见"}},{q="哪里可以找到生病的鹿？",a="生病的鹿在几乎整个Darkshore四处徘徊。它们分布在奥伯丁以北的壁泉河南部，并一路向南在整个沿海森林中游荡，直到灰谷的边界。",al={"生病的鹿的位置","鹿在哪里","darkshore鹿的位置"}},{q="德鲁伊从完成这项任务中学到了什么？",a="这个任务构成了德鲁伊毒素净化学习的实践高潮。通过目睹森林动物的苦难并应用物理治疗，德鲁伊架起了连接植物疗法和对毒素的精神掌控之间的桥梁。",al={"这对德鲁伊的教导","德鲁伊净化毒素训练","治愈伤病者的教训"}}},fp="15,202,25.289.0,26.349.1,35.214.0,49.192.0,48.208.0,55.181.0,35.128.0,50.167.0"}
P.entries["quest:6125"] = {n="解毒之术",s="“驾驭毒素”标志着一名年轻德鲁伊掌握剧毒苦难试炼的终章。在黑海岸亲手学会调制草药疗法后，初学者回到达纳苏斯，接受塞纳里奥议会的魔法祝福，从而能随心所欲地净化毒素。",h="“驾驭毒素”标志着一名年轻德鲁伊掌握剧毒苦难试炼的终章。在黑海岸亲手学会调制草药疗法后，初学者回到达纳苏斯，接受塞纳里奥议会的魔法祝福，从而能随心所欲地净化毒素。",kw={"奥伯丁","塞纳里奥区","驱散毒素","达纳苏斯","德迪利特·星焰","玛斯雷·驭熊者","月光林地","驾驭毒素"},ang={["class:Druid"]="这一通过仪式架起了谦逊的草药学与神圣的恢复魔法之间的桥梁，标志着德鲁伊获得了凭借自然恩典中和剧毒的直接力量。",["race:NightElf"]="这项试炼在达纳苏斯的塞纳里奥区进行，反映了卡多雷对平衡的敬畏，以及他们对古老森林的庄严守护。"},sec={{t="学徒的谦卑",b="在赋予德鲁伊净化毒素的天生魔法能力之前，塞纳里奥议会要求初学者理解平民所遭受的痛苦。在黑海岸，奥兰达利亚·夜歌指派年轻的修行者手动采集地根草和月亮菇，调制出可以治愈患病野生动物的草药膏。这一课确保了德鲁伊在引导自然之力治愈毒素时，能够对那些必须在没有精神干预的情况下与剧毒抗争的生灵怀有深刻的同理心。"},{t="回到塞纳里奥区",b="一旦物理疗法在奥伯丁证明有效，星焰便会将德鲁伊送回海对岸的达纳苏斯。在塞纳里奥区的树枝间，玛斯雷·驭熊者正在等待他们的归来。玛斯雷对初学者在压力下的从容表现感到满意，正式传授了自然净化的艺术，赋予了他们永久驾驭毒素的能力。然而，这次试炼也带来了令人不安的消息：奥伯丁周边荒野中存在的致命毒素表明，某种非自然的枯萎病正在破坏这片土地微妙的平衡。"}},faq={{q="这个任务的目的是什么？",a="该任务是德鲁伊“治愈毒素”试炼的终点。在月光林地和黑海岸成功为德迪利特·星焰制备了物理治疗药剂后，学生回到达纳苏斯的玛斯雷·驭熊者处，学习天生魔法技能“驱散毒素”。",al={"为何要做驾驭毒素任务","驾驭毒素任务目标","驱散毒素任务"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位驻扎在月光林地神圣避难所——永夜港的德鲁伊长者。他引导初学者完成精神试炼，在将他们送回各自的导师处之前，考验他们的耐心以及对自然的奉献精神。",al={"德迪利特·星焰的角色","谁发布了驾驭毒素任务"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位居住在达纳苏斯塞纳里奥区的德鲁伊导师。他负责监管泰达希尔枝叶间暗夜精灵德鲁伊的成长，传授变形术、恢复系法术以及塞纳里奥议会的庄严职责。",al={"玛斯雷·驭熊者背景故事","驭熊者达纳苏斯"}},{q="为什么德鲁伊首先需要亲手制作解毒剂？",a="德迪利特·星焰教导说，德鲁伊必须了解毒素带来的身体痛苦，以及在没有魔法辅助的情况下治疗它所需的辛劳。通过采集普通草药并亲手帮助病患，初学者学会了谦卑，并懂得了感激他们即将获得的自然恩赐。",al={"为何要制作草药解毒剂","驾驭毒素的教训"}},{q="玛斯雷对奥伯丁的情况有何担忧？",a="玛斯雷指出，奥伯丁周围黑海岸荒野中突然出现的致命毒素是不自然的。对当地野生动物和植物群的破坏威胁到了生态平衡，暗示这片多雾的海岸上存在着某种腐蚀性的力量。",al={"奥伯丁毒素背景","玛斯雷的担忧"}}},fp="17,167,22.403.0,21.402.0,34.185.0,26.202.0,29.207.0,56.265.0,58.210.0"}
P.entries["quest:6126"] = {n="新的课程",s="“新的课程”是年轻牛头人德鲁伊的成人仪式，由雷霆崖长者高地的图拉克·符文图腾发起。它指引学徒前往月光林地的圣地，开始掌握净化自然与非自然毒素的艺术。在暗夜精灵德迪利特·星焰的指导下，这门课程摒弃了模拟演练，转而面对一场紧迫的、现实世界的中毒危机。",h="“新的课程”是年轻牛头人德鲁伊的成人仪式，由雷霆崖长者高地的图拉克·符文图腾发起。它指引学徒前往月光林地的圣地，开始掌握净化自然与非自然毒素的艺术。在暗夜精灵德迪利特·星焰的指导下，这门课程摒弃了模拟演练，转而面对一场紧...",kw={"塞纳里奥议会","十字路口","驱毒术","德迪利特·星焰","新的课程","月光林地","永夜港","图拉克·符文图腾"},ang={["class:Druid"]="这个任务标志着你从基本的变形和小型冲突转变为荒野的真正管家，开启了掌握驱毒术的旅程。",["faction:Horde"]="当部落勇士在灰谷与暗夜精灵发生冲突时，部落德鲁伊在塞纳里奥议会的神圣庇护下，在月光林地获得了安全的港湾。",["race:Tauren"]="对于牛头人来说，这次朝圣展示了大地母亲的孩子们是如何与他们的暗夜精灵同伴一起，重新与塞纳留斯的教义紧密连接的。"},sec={{t="塞纳留斯的馈赠",b="德鲁伊肩负着守护荒野的神圣使命，其中包括塞纳留斯赐予的、通过简单咒语即可净化剧毒的神奇能力。然而，如此强大的魔法并非唾手可得。图拉克·符文图腾坚持认为，在引导神圣能量轻松驱散枯萎之前，德鲁伊必须了解毒素造成的生理痛苦，并学会通过扎实的世俗手段来治疗它。"},{t="前往永夜港的召唤",b="与其仅仅在莫高雷的断崖上进行训练，有前途的侍僧会被送往北方，穿过神圣的小径前往月光林地。在那里，在宁静的永夜港村庄中，像德迪利特·星焰这样的古老暗夜精灵导师会监督精灵和牛头人修行者的教育。这种共同教学凸显了塞纳里奥议会内部存在的微妙休战，超越了部落与联盟之间的政治冲突。"},{t="贫瘠之地的真实危机",b="虽然以前的入会者是在受控条件下练习净化仪式，但星焰没有时间进行人为的演习。贫瘠之地干旱的十字路口附近爆发了一场无法控制的动物中毒事件。来自十字路口的绝望求援将一场学术性的成人仪式转变为了一项紧急实地任务，要求年轻的德鲁伊直接面对野生动物的苦难。"}},faq={{q="谁发布了这个任务，我该去哪里找他？",a="该任务由雷霆崖长者高地的牛头人德鲁伊训练师图拉克·符文图腾发布。他呼吁那些已经证明自己对塞纳里奥教义有初步承诺的入会者。",al={"谁发布新的课程","在哪里领取新的课程","新的课程任务发布者"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位居住在月光林地永夜港的年长暗夜精灵德鲁伊。尽管暗夜精灵和牛头人之间存在广泛的阵营紧张关系，但他仍在塞纳里奥议会的传统下指导两个种族的年轻德鲁伊。",al={"德迪利特是谁","德迪利特·星焰的角色","月光林地的暗夜精灵是谁"}},{q="这个任务教给我什么力量？",a="这个任务线开启了你对“驱毒术”的指导。它教导德鲁伊理解毒素的生理和魔法本质，使他们能够从盟友和他们照料的野生生物身上清除有害的折磨。",al={"我学会了什么技能","这是什么法术的任务","驱毒任务"}},{q="为什么牛头人必须在暗夜精灵门下学习？",a="塞纳里奥议会是一个致力于自然平衡的中立兄弟会。虽然暗夜精灵是第一批在塞纳留斯麾下将现代德鲁伊教义正规化的种族，但他们欢迎牛头人重回教团，尽管存在阵营战争，依然共享月光林地这样的圣地。",al={"为什么是暗夜精灵训练师","牛头人暗夜精灵德鲁伊","塞纳里奥议会阵营"}},{q="十字路口发生了什么？",a="贫瘠之地十字路口附近的当地野生动物正遭受一波猛烈的中毒浪潮，当地的驯兽师无法遏制。德迪利特·星焰将你的训练直接转向实地，以查明来源并合成补救措施。",al={"十字路口的问题","什么在毒害动物","十字路口的疾病"}},{q="完成这个任务去月光林地的最快方法是什么？",a="作为一名德鲁伊，你拥有传送技能：月光林地，它可以直接将你送入永夜港的圣所，而无需徒步穿越危险的争议领土。",al={"如何前往月光林地","前往永夜港","传送月光林地"}}},fx={be063b64={q="图拉克·符文图腾为什么让你去月光林地？",a="图拉克认为你终于准备好继承塞纳留斯赐予德鲁伊的至高祝福之一：以咒语驱除致命毒素的技艺。这种神圣魔法不会轻易传授。为了确保你尊重这份力量，图拉克要求你先像普通治疗者那样了解毒药，并指引你前往月光林地向德迪利特·星焰开始正式学习。",al={"图拉克为什么派我去","图拉克·符文图腾的动机","为什么去月光林地"}}},fp="12,403,20.427.0,21.458.0,28.418.1,47.199.0,26.236.0,37.234.0,50.276.0,36.257.0,59.191.0"}
P.entries["quest:6127"] = {n="毒水之源",s="“主要源头”是月光林地的德迪利特·星焰发布的一项部落德鲁伊任务。它派遣初出茅庐的德鲁伊前往贫瘠之地北部的鬼雾峰，采集受污染的池水，并将其带给十字路口的图加·符文图腾。该样本提供了了解这一地区野生动物所遭受的蔓延毒素所需的根本依据。",h="“主要源头”是月光林地的德迪利特·星焰发布的一项部落德鲁伊任务。它派遣初出茅庐的德鲁伊前往贫瘠之地北部的鬼雾峰，采集受污染的池水，并将其带给十字路口的图加·符文图腾。该样本提供了了解这一地区野生动物所遭受的蔓延毒素所需的...",kw={"贫瘠之地","塞纳里奥议会","十字路口","德迪利特·星焰","鬼雾峰","毒素的克星","主要源头","生病的瞪羚","图加·符文图腾"},ang={["class:Druid"]="这项成年仪式是你作为荒野守护者道路上的重要一步，证明你能够追溯腐败的源头，并在魔法毒素摧毁整个生态系统之前将其隔离。",["faction:Horde"]="十字路口是部落在卡利姆多存在的基础物流枢纽，因此其后院中不受控制地蔓延的恶魔枯萎病对贸易和生存构成了直接威胁。",["race:Tauren"]="贫瘠之地是卡利姆多各族的祖居之地；净化水源有助于保护那些世世代代供养你们族人的瞪羚群免受恶魔腐蚀。"},sec={{t="被污染的高山",b="鬼雾峰矗立在十字路口的西北方，山势极高，其高处的泉水和池塘影响着周围的天气模式和干旱的贫瘠之地北部的自然湿度。不幸的是，信奉恶魔的火刃氏族邪教徒已经在山脊上扎了根。德迪利特·星焰意识到，在如此重要的自然制高点上进行的邪恶巫术可能会污染整个周围盆地。"},{t="平原上的瘟疫",b="在整个北方草原上，人们看到生病的瞪羚在东西向主干道十字路口的北侧蹒跚而行。图加·符文图腾代表当地牛头人寻求援助，联系了塞纳里奥议会，以帮助查明是什么毒害了牛群。通过勇敢地登上山峰并取回纯净的受污染水样，德鲁伊为图加提供了分析病情和酿造解药所需的关键催化剂。"}},faq={{q="我在哪里可以获得这个任务的水样？",a="水必须从位于贫瘠之地十字路口西北方鬼雾峰最顶端的池塘中汲取。你必须到达火刃氏族邪教徒聚集的山顶池塘，并使用德迪利特·星焰提供的采样器。",al={"鬼雾峰水池位置","水池在哪里","主要源头水样"}},{q="为什么鬼雾峰的水对贫瘠之地如此重要？",a="鬼雾峰空气清新的高处拥有的池塘直接影响着当地的天气模式和水雾。当恶魔邪教徒污染这些水源时，带毒的蒸汽和径流会向下漂移，腐蚀下方的平原，使整个贫瘠之地北部的野生动物患病。",al={"为什么鬼雾峰很重要","贫瘠之地天气水池","鬼雾峰水池"}},{q="图加·符文图腾是谁？",a="图加·符文图腾是一位驻扎在贫瘠之地十字路口的牛头人德鲁伊。他对在当地瞪羚中蔓延的不自然疾病深感担忧，因此向月光林地的塞纳里奥议会请求协助，以诊断和净化这片土地。",al={"图加是谁","图加·符文图腾的作用","十字路口德鲁伊"}},{q="是谁在污染山顶的水？",a="水源已被火刃氏族污染，这是一个信奉恶魔的术士和邪能使用者的阴暗邪教，他们占据了鬼雾峰蜿蜒的小径和山顶。",al={"谁污染了池塘","鬼雾峰邪教徒","火刃氏族鬼雾峰"}},{q="完成这个任务链会教授什么能力？",a="此项任务是年轻部落德鲁伊“毒素的克星”仪式中较大环节的一部分，最终将掌握在野外治愈毒素所需的精神和草药知识。",al={"毒素的克星奖励","德鲁伊驱毒法术","贫瘠之地驱毒任务"}},{q="联盟德鲁伊可以完成这个任务吗？",a="不能。“主要源头”是专门针对部落的试炼版本，派遣玩家前往贫瘠之地协助图加·符文图腾。联盟德鲁伊将在黑海岸进行类似的旅程，以获得他们的解毒能力。",al={"联盟对应任务","暗夜精灵可以完成主要源头吗","联盟毒素任务"}}},fp="20,210,18.326.0,22.366.0,47.191.0,63.202.0,23.207.0,40.150.0,46.128.0,34.180.0"}
P.entries["quest:6128"] = {n="收集解药",s="“收集解药”是对于驻扎在十字路口的牛头人德鲁伊学徒来说是一项神圣的试炼。在图加·符文图腾的指派下，德鲁伊需要收集地根草和结实的科多兽角，为贫瘠之地中毒的瞪羚调制治疗药膏。",h="“收集解药”是对于驻扎在十字路口的牛头人德鲁伊学徒来说是一项神圣的试炼。在图加·符文图腾的指派下，德鲁伊需要收集地根草和结实的科多兽角，为贫瘠之地中毒的瞪羚调制治疗药膏。",kw={"贫瘠之地","十字路口","德鲁伊任务","地根草","收集解药","瞪羚","科多兽角","药膏","图加·符文图腾"},ang={["class:Druid"]="这项任务是关键试炼的一部分，德鲁伊通过试炼学习超越凡人的草药学，并引导自然魔法直接驱除毒素。",["faction:Horde"]="协助图加有助于保护十字路口周围的野生动物，为部落在这一地区的中心前哨确保稳定的生态环境。",["profession:Herbalism"]="该任务依赖于地根草，强调了从大草原多岩石的山坡上采集野生药用根茎的持久价值。"},sec={{t="救治配方",b="在获得了鬼雾峰的水样后，图加·符文图腾需要原始试剂来调制一种有效的物理抗毒剂。天然泉水是药膏的基础，普通的地根草提供了基本的药用功效，而研磨后的科多兽角则赋予了药膏所需的复原效力，足以将毒素从生物体内驱除。对于年轻的德鲁伊来说，获取这些原料意味着要依赖大地的馈赠并猎杀当地的野兽。"},{t="净化课程",b="炼金术和草药学是抵御特定毒素的传统手段，但每种独特的毒素通常都需要精确、定制的解药。图加利用这种费力的准备工作来教导学徒们物理药物的局限性。真正掌控自然毒素的能力并非来自于携带无穷无尽的干草药和兽角，而是直接与自然的治愈能量共鸣——这是一门意义深远的课程，它将直接引向德鲁伊的“解毒术”技能。"}},faq={{q="图加·符文图腾需要什么原料？",a="图加要求收集五捆地根草和五根完整的科多兽角。地根草提供治疗性的草药属性，而兽角则提供中和当地瞪羚体内毒素所必需的强大效力。",al={"收集解药物品","我需要什么试剂","解药材料"}},{q="去哪里寻找科多兽角？",a="科多兽游荡在贫瘠之地北部和中部的干旱平原上，经常在十字路口周围的道路附近吃草。图加强调，只有从这些野兽身上获取完整、结实的兽角才能用于药膏，易碎的残片是无法使用的。",al={"科多兽在哪里","科多兽角位置","在贫瘠之地寻找科多兽"}},{q="我必须要是草药师才能获得地根草吗？",a="不需要，你本身并不需要草药学专业。虽然草药师可以在贫瘠之地的悬崖和岩石缝隙中采集地根草，但如果德鲁伊缺乏直接采集的技能，也可以从其他旅者或贸易站获得。",al={"我需要草药学吗","无需草药学采集地根草","地根草专业要求"}},{q="为什么图加要准备一种物理药膏？",a="图加正在准备一种物理抗毒剂，以治疗在贫瘠之地北部受毒害的瞪羚。他还利用这种制作特定物理药剂的繁琐过程，来演示学习先天的魔法净化法术所具有的巨大优势。",al={"为什么要制作抗毒剂","药膏的用途","为什么不使用魔法"}},{q="图加·符文图腾是谁？",a="图加·符文图腾是一位驻扎在贫瘠之地十字路口的年长牛头人德鲁伊。他负责调查该地区水源中蔓延的腐蚀，并引导年轻的德鲁伊掌握自然平衡。",al={"谁发布收集解药任务","图加·符文图腾的角色","图加是谁"}},{q="收集完这些原料后要做什么？",a="当图加用试剂调制好药膏后，他会派德鲁伊前往大草原，直接将混合物涂抹在患病的瞪羚身上，以此在传授更深奥的魔法净化艺术之前先测试这种疗法。",al={"收集解药之后是什么","收集解药的后续任务","完成收集解药之后"}}},fp="18,195,19.376.0,20.332.0,46.187.0,34.158.0,49.221.0,40.190.0,23.197.0,45.170.1"}
P.entries["quest:6129"] = {n="消除疾病",s="“医治病患”是部落年轻德鲁伊的一项基本考验，任务要求他们治疗贫瘠之地北部受感染的野生动物。通过为患病的瞪羚涂抹新鲜配制的草药药膏，新兵们展示了他们实地的医疗技术以及维护自然平衡的决心。完成这项职责直接向月光林地的塞纳里奥议会证明了他们的忠诚。",h="“医治病患”是部落年轻德鲁伊的一项基本考验，任务要求他们治疗贫瘠之地北部受感染的野生动物。通过为患病的瞪羚涂抹新鲜配制的草药药膏，新兵们展示了他们实地的医疗技术以及维护自然平衡的决心。完成这项职责直接向月光林地的塞纳里奥...",kw={"贫瘠之地","塞纳里奥议会","十字路口","动物医疗药膏","净化毒素","医治病患","德迪利特·星焰","月光林地","患病的瞪羚","图加·符文图腾"},ang={["class:Druid"]="这项治疗仪式标志着你从一名草药学学生转变为了一名积极的自然守护者，证明了你已准备好运用生命魔法对抗致命的毒素。",["faction:Horde"]="通过在十字路口附近治疗受感染的野生动物，牛头人德鲁伊帮助保护了重要的狩猎场和交通走廊，支持了部落在卡利姆多中部的立足点。",["race:Tauren"]="随着你们的人民重燃与塞纳里奥议会的古老纽带，治愈贫瘠之地证明了大地之母的孩子们是有资格维持平衡的守护者。"},sec={{t="兽群之灾",b="在贫瘠之地的北部草原上，成群的瞪羚开始死于一种非自然的疾病。在收集了地根草和科多兽角以配置治疗药剂后，十字路口的图加·符文图腾会将野外治疗的任务托付给一位年轻的德鲁伊。新兵必须在主要路口以北搜寻，找到十只受苦的动物并进行医治，在腐化进一步深入生态系统之前提供紧急救助。"},{t="议会的祝福",b="药膏分发完毕后，德鲁伊的道路将指引他们回到月光林地那宁静的枝叶下。在那里，德迪利特·星焰会认可这位新兵的同情心与警觉性。他指出，瞪羚的苦难仅仅是潜伏在卡利姆多荒野中的某种更深层、更阴险的腐化的症状。通过照料这些最卑微的野兽，牛头人德鲁伊证明了他们对塞纳留斯的崇敬超越了部落的界限，从而获得了更多关于净化毒素与自然魔法的秘密。"}},faq={{q="哪里可以找到患病的瞪羚？",a="受感染的瞪羚在贫瘠之地北部的干旱平原上游荡，主要位于十字路口交汇的东西向主要贸易路线以北。",al={"瞪羚位置","患病瞪羚在哪里","贫瘠之地瞪羚"}},{q="谁发放这个任务？",a="图加·符文图腾，一位驻扎在贫瘠之地十字路口的牛头人德鲁伊，在完成他收集试剂的任务后，会提供此任务并提供动物医疗药膏。",al={"谁给予医治病患","任务发布者","图加·符文图腾位置"}},{q="治好动物后我该向谁报告？",a="你需要向月光林地德鲁伊圣地的德迪利特·星焰交付任务，使用你的传送魔法到达那片神圣的林地。",al={"我在哪里交付任务","任务交付","德迪利特·星焰位置"}},{q="为什么塞纳里奥议会对贫瘠之地感兴趣？",a="塞纳里奥议会守护着大地的和谐。野生瞪羚中蔓延的疾病反映了某种正在卡利姆多渗透的广泛腐化，如果不加以遏制，将威胁到自然秩序的稳定。",al={"为什么德鲁伊关心贫瘠之地","塞纳里奥议会贫瘠之地"}},{q="这个任务链解锁什么技能？",a="这项考验构成了德鲁伊成年仪式的后半部分，最终将奖励新兵净化自身及盟友身上毒素与毒药的能力。",al={"净化毒素任务奖励","为什么德鲁伊要做这个任务"}},{q="非德鲁伊职业可以治疗这些瞪羚吗？",a="不可以。这个任务线是德鲁伊专属的，作为一项由塞纳里奥议会直接监督的职业考验。",al={"这是德鲁伊专属吗","谁可以做医治病患"}}},fx={f2ed6f7d={q="图加·符文图腾为什么要你治好这些瞪羚？",a="一股蔓延的腐化正在侵蚀贫瘠之地北部的野生动物，当地的瞪羚因此染上了令人衰弱的疾病。图加·符文图腾已经配制出疗伤膏来对抗病症，但大自然等不起。他需要你立即为受苦的动物带去救治，在污秽进一步破坏这片土地脆弱的平衡之前遏止它。",al={"为什么要治瞪羚","图加·符文图腾的动机","为什么帮助患病的瞪羚"}},f6349169={q="图加·符文图腾为什么需要你帮忙，而不亲自救治瞪羚？",a="图加只来得及配制出十剂药膏，必须留在十字路口与当地官员协调，准备更多药剂。作为一名踏上塞纳留斯之路的见习德鲁伊，你与自然的联系能让你找到四散患病的动物，并在不给它们增添痛苦的情况下施用药剂。",al={"图加·符文图腾为什么找我","图加为什么需要帮手","为什么不让当地卫兵去"}}},fp="15,397,23.459.0,21.483.0,36.158.0,22.180.0,44.140.0,53.218.0,42.180.0,35.122.0"}
P.entries["quest:613"] = {n="玛雷的腿",s="“海狼”马克基雷取回了他已故债务人莫里的脚，却发现他被欠下的财物被锁在里面了。为了索回欠款，他指引旅行者前往荆棘谷的莫什奥格食人魔山去寻找丢失的钥匙。",h="“海狼”马克基雷取回了他已故债务人莫里的脚，却发现他被欠下的财物被锁在里面了。为了索回欠款，他指引旅行者前往荆棘谷的莫什奥格食人魔山去寻找丢失的钥匙。",kw={"藏宝海湾","钥匙","马克基雷","莫里","莫什奥格","食人魔","海狼","荆棘谷"},sec={{t="上锁的奖品",b="在“巫医的代价”任务中取回莫里的脚之后，“海狼”马克基雷在藏宝海湾遇到了意想不到的麻烦。这位已故的债务人在他的脚上加了一把锁，而他欠下的财物就封在里面。"},{t="食人魔土堆",b="莫里喜欢和东北方向莫什奥格食人魔山的食人魔们赌博。马克基雷记得莫里曾说，在他赢了太多之后，食人魔把他赶走了，所以他怀疑食人魔现在持有钥匙，于是派遣旅行者去寻找。"}},faq={{q="为什么“海狼”马克基雷需要莫里的钥匙？",a="莫里把自己欠下的东西封在了自己的脚里，并加上了一把锁。没有开锁的钥匙，马克基雷无法拿到欠他的债款。",al={"为什么需要钥匙","钥匙是做什么用的","莫里钥匙的目的"}},{q="莫里的钥匙被认为在哪里？",a="马克基雷怀疑这把钥匙可能被藏宝海湾东北方向的莫什奥格食人魔山的食人魔所持有。",al={"钥匙在哪里","钥匙位置","哪里寻找莫里钥匙"}},{q="为什么莫什奥格食人魔会有这把钥匙？",a="莫里经常与莫什奥格食人魔赌博，马克基雷记得食人魔在莫里赢了一大笔钱后就把他赶走了。这就是他猜测钥匙可能在他们手里的原因。",al={"为什么食人魔有钥匙","莫里与食人魔的关系","莫里认识食人魔吗"}},{q="在马克基雷的这些生意中，之前发生了什么？",a="这是继“巫医的代价”之后的任务，而在那之前，围绕藏宝海湾的债务结算工作还包括“恐吓谢基”和“回到马克基雷那里”。",al={"前置任务","任务链顺序","首先发生什么"}}},fp="21,248,14.208.0,16.238.0,47.142.0,35.114.0,42.161.0,47.145.0"}
P.entries["quest:6130"] = {n="解毒之术",s="“毒素掌控”是年轻部落德鲁伊掌握恢复自然魔法的试炼中的最终仪式。在只使用草药混合剂治愈了十字路口附近的患病羚羊后，学徒将回到雷霆崖长者高地，向图拉克·符文图腾汇报，从而获得“解毒术”的真正天赋。",h="“毒素掌控”是年轻部落德鲁伊掌握恢复自然魔法的试炼中的最终仪式。在只使用草药混合剂治愈了十字路口附近的患病羚羊后，学徒将回到雷霆崖长者高地，向图拉克·符文图腾汇报，从而获得“解毒术”的真正天赋。",kw={"贫瘠之地","十字路口","解毒术","德迪利特·星焰","长者高地","月光林地","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这次成人礼将卡利姆多的物理草药学与天生的自然魔法连接起来，赋予了德鲁伊永久清除盟友体内毒素的能力。",["faction:Horde"]="围绕十字路口的试炼展示了部落在保护卡利姆多中部荒野免受非自然腐蚀方面日益增长的作用。",["race:Tauren"]="对于牛头人新手来说，完成这个任务证明了他们对塞纳里奥议会的奉献，同时也让大地母亲的智慧在长者高地上得以延续。"},sec={{t="苦难的课程",b="在赋予年轻的德鲁伊净化毒素的天生魔法力量之前，塞纳里奥议会要求他们理解苦难的物理本质。德迪利特·星焰将新手派往十字路口，图加·符文图腾在那里让他们收集大地试剂，并亲手制作治疗药膏。只有在没有精神力量辅助的情况下治疗贫瘠之地中毒的平原羚羊，学生才能见证普通生物在对抗自然与非自然毒素时所面临的痛苦挣扎。"},{t="回到长者高地",b="试炼完成后，德迪利特将学徒送回雷霆崖长者高地，去寻找居住在那里的德鲁伊导师图拉克·符文图腾。图拉克指出，十字路口附近出现的奇怪、剧毒的毒素正在威胁平原的自然平衡，这值得严重关注。为了嘉奖学徒在压力下的优雅表现，图拉克永久传授了解除毒素的精神艺术，并委托他们守护卡利姆多的所有生物。"}},faq={{q="这个任务的目的是什么？",a="这个任务标志着部落德鲁伊解毒试炼的结束。在通过准备凡俗药物来挽救受苦的羚羊展现出纪律性之后，学徒回到图拉克·符文图腾身边，通过德鲁伊的交流直接学习“解毒术”。",al={"为什么要做毒素掌控","这个任务做什么","德鲁伊解毒任务目的"}},{q="图拉克·符文图腾在哪里？",a="图拉克·符文图腾居住在雷霆崖的长者高地上。他的家位于牛头人德鲁伊交流和修行的帐篷和中空栖木之中。",al={"图拉克·符文图腾位置","图拉克在哪里","寻找图拉克·符文图腾"}},{q="是谁把德鲁伊送回雷霆崖的？",a="德迪利特·星焰，一位驻扎在月光林地圣地的塞纳里奥议会暗夜精灵德鲁伊，在学徒成功治愈了十字路口附近的野生动物后，将他们送回导师身边。",al={"谁给予毒素掌控任务","任务给予者","德迪利特·星焰"}},{q="为什么塞纳里奥议会要让德鲁伊先手动治疗野兽？",a="德迪利特·星焰强调，德鲁伊在运用轻松的精神魔法之前，必须通过纯粹的劳动和凡人的局限来理解治愈毒素的意义。体验患病生物的困境能教导人们对自然平衡的同理心与尊重。",al={"为什么手动治愈病人","为什么要先用药膏","德鲁伊毒素课程"}},{q="图拉克·符文图腾对十字路口有什么担忧？",a="图拉克深感忧虑地指出，非自然的、具有侵略性的毒素正在被引入十字路口附近的贫瘠之地野生动物体内。他认为这种污染是对土地平衡的严重破坏，需要未来保持警惕。",al={"图拉克对十字路口的担忧","十字路口毒素平衡"}},{q="这个任务联盟德鲁伊可以做吗？",a="联盟德鲁伊会进行一个同名的平行试炼。暗夜精灵新手不是向长者高地的图拉克·符文图腾汇报，而是回到达纳苏斯向玛斯雷·驭熊者汇报来完成课程。",al={"暗夜精灵可以做这个吗","联盟毒素掌控"}}},fp="17,300,21.494.0,24.465.0,34.271.0,33.158.0,42.206.0,70.273.0,51.234.0,43.215.0"}
P.entries["quest:6132"] = {n="救我出去！",s="梅丽萨·霍恩尼兹深入长矛谷，希望能与玛洛迪人做生意，但对方拒绝沟通，她担心自己会被吃掉。她请求你带她离开那里；她的兄弟霍恩尼兹会给你丰厚的报酬。",h="梅丽萨·霍恩尼兹深入长矛谷，希望能与玛洛迪人做生意，但对方拒绝沟通，她担心自己会被吃掉。她请求你带她离开那里；她的兄弟霍恩尼兹会给你丰厚的报酬。",kw={"半人马","凄凉之地","霍恩尼兹","科多兽坟场","玛洛迪","梅丽萨","长矛谷"},sec={{t="Trouble in the Valley",b="梅丽萨走进长矛谷想要和玛洛迪人谈谈，本以为能达成一笔交易。但他们根本不理会，她怀疑他们宁愿把她吃掉。她说几分钟前才刚听到半人马在商量要把柴火丢进锅里，她想尽快离开。"},{t="她兄弟的营地",b="霍恩尼兹·布林巴兹尔正在东边的家族营地等候，就在科多兽坟场旁边。梅丽萨承诺，如果你能带她离开山谷，她的兄弟会付给你优厚的报酬。"},{t="回到营地",b="霍恩尼兹说梅丽萨告诉他你会来，并感谢你帮她解了围。他猜她现在肯定又惹上新麻烦了。梅丽萨冲到前面，抱怨玛洛迪人太难打交道，说她打算去找盖尔基斯人，他们讲理多了。"}},faq={{q="为什么梅丽萨·布林巴兹尔会有麻烦？",a="梅丽萨走进长矛谷，希望能与玛洛迪人做生意。但他们不愿沟通，她觉得他们想吃掉她。",al={"梅丽萨为什么被困","梅丽萨·布林巴兹尔的故事","梅丽萨发生了什么事"}},{q="玛洛迪人是谁？",a="玛洛迪人是凄凉之地的半人马。梅丽萨就是去长矛谷试图与他们做生意的。",al={"玛洛迪半人马","玛洛迪人是谁","玛洛迪氏族"}},{q="霍恩尼兹·布林巴兹尔在哪里？",a="霍恩尼兹·布林巴兹尔在凄凉之地的布林巴兹尔营地等候，位于科多兽坟场以东。",al={"霍恩尼兹的位置","霍恩尼兹在哪里","霍恩尼兹·布林巴兹尔营地"}},{q="为什么梅丽萨说她兄弟会给你报酬？",a="她承诺，如果你能带她离开山谷，她的兄弟霍恩尼兹会给你丰厚的报酬。",al={"梅丽萨的奖励","霍恩尼兹支付什么"}}},fp="19,240,21.280.0,18.176.0,16.271.1,37.141.0,23.116.0,36.100.0,46.95.0"}
P.entries["quest:6134"] = {n="幽灵电浆",s="霍恩尼兹觉得白骨之谷的鬼魂里藏着商机。他认为玛格拉姆半人马愿意花大价钱购买鬼魂能量，于是他给了你一箱用来引诱鬼魂的幽灵磁铁。",h="霍恩尼兹觉得白骨之谷的鬼魂里藏着商机。他认为玛格拉姆半人马愿意花大价钱购买鬼魂能量，于是他给了你一箱用来引诱鬼魂的幽灵磁铁。",kw={"巨兽残骸","凄凉之地","幽灵磁铁","幽灵质","霍恩尼兹","玛格拉姆","幽灵","白骨之谷"},sec={{t="闹鬼的山谷",b="霍恩尼兹指引你前往东南方的白骨之谷，那里游荡着玛格拉姆的鬼魂。他承认这听起来很吓人，但对玛格拉姆人来说肯定更可怕。他确信在那里收集到的鬼魂能量对那些半人马来说价值连城。"},{t="在巨兽残骸之间",b="他交给你一箱幽灵磁铁。把它放置在山谷中两具巨大的骸骨之间（即所谓的巨兽残骸），磁铁就会引诱鬼魂靠近。从它们身上你可以提取出幽灵质，这正是霍恩尼兹打算卖给玛格拉姆人的东西。他需要你带回八份幽灵质，以及那个箱子。"},{t="满载而归",b="当你回来时，霍恩尼兹注意到你身上沾到了一些幽灵质，并称其为粘糊糊的玩意儿。他认为只要能说服半人马，这东西就能让他发大财。"}},faq={{q="霍恩尼兹是谁？",a="霍恩尼兹在凄凉之地的科多兽坟场西南方设立了一个营地。他想要把鬼魂能量卖给玛格拉姆半人马。",al={"霍恩尼兹","布里姆巴兹","谁发布了搜集幽灵质任务"}},{q="白骨之谷在哪里？",a="霍恩尼兹说白骨之谷在东南方。那两具用来放置磁铁的巨大骸骨——巨兽残骸，就位于山谷的南端。",al={"白骨之谷位置","哪里可以找到鬼魂","巨兽残骸位置"}},{q="霍恩尼兹为什么想要幽灵质？",a="他确信玛格拉姆半人马会花大价钱购买在闹鬼的白骨之谷中捕获的鬼魂能量，而幽灵质正是他打算卖给它们的东西。",al={"为什么要收集鬼魂能量","谁会购买幽灵质","半人马幽灵质"}},{q="幽灵磁铁是如何运作的？",a="将磁铁放置在两具巨兽残骸之间可以吸引山谷里的鬼魂靠近，而这些鬼魂会产生幽灵质。",al={"如何使用幽灵磁铁","在哪里放置幽灵磁铁","吸引玛格拉姆鬼魂"}}},fp="22,211,16.245.0,25.316.0,18.202.1,26.135.0,29.145.0,36.154.0,31.118.0"}
P.entries["quest:6141"] = {n="安东修士",s="克罗雷修士提到了安东修士，那是一位战士同袍。他听说遥远的卡利姆多出现了亡灵，便立刻启程前往消灭它们。安东正在寻找勇敢且坚定的人，他在凄凉之地的尼耶尔前哨站等待着。",h="克罗雷修士提到了安东修士，那是一位战士同袍。他听说遥远的卡利姆多出现了亡灵，便立刻启程前往消灭它们。安东正在寻找勇敢且坚定的人，他在凄凉之地的尼耶尔前哨站等待着。",kw={"安东修士","克罗雷修士","凄凉之地","尼耶尔前哨站","血色","亡灵"},sec={{t="远方的修士",b="克罗雷修士说，关于遥远的卡利姆多大陆上的凄凉之地出现亡灵侵扰的传言传到了安东耳中，他随即动身前往，誓要寻出并消灭这些威胁。安东希望得到那些勇敢且意志坚定的人的帮助。克罗雷告诉你，如果你的内心坚定，就去凄凉之地的联盟城镇尼耶尔前哨站与安东交谈。"},{t="来自东方的消息",b="安东修士已经收到消息说会有援军从东方赶来。他询问你是否就是那些传言的来源，以及你是否是来协助血色十字军的远征的。"}},faq={{q="安东修士是谁？",a="安东修士是克罗雷修士的战友。他听说凄凉之地遭到了亡灵的侵扰，便动身前往那里去消灭它们。",al={"安东是谁","安东修士背景故事","安东 凄凉之地"}},{q="在哪里可以找到安东修士？",a="安东修士位于凄凉之地的联盟城镇尼耶尔前哨站。",al={"安东修士在哪里","安东位置","安东修士地点"}},{q="安东修士为什么去卡利姆多？",a="因为有传言称卡利姆多的凄凉之地遭到了亡灵的侵扰，他随即动身前往那里去消灭它们。",al={"安东为什么在凄凉之地","安东在凄凉之地的任务","安东为什么旅行"}}},fp="13,237,16.335.0,18.202.1,21.143.0,33.65.0,37.115.0"}
P.entries["quest:6142"] = {n="蚌肉鱼饵",s="葬影村的麦拉斯一生都在捕鱼，他说最好的鱼饵是软壳蛤肉，没有任何鱼能抗拒。他想要十份，可以在北边沿海的一艘失事船只附近找到。",h="葬影村的麦拉斯一生都在捕鱼，他说最好的鱼饵是软壳蛤肉，没有任何鱼能抗拒。他想要十份，可以在北边沿海的一艘失事船只附近找到。",kw={"蛤肉鱼饵","凄凉之地","钓鱼鱼饵","麦拉斯","葬影村","失事船只","软壳蛤"},sec={{t="最好的鱼饵",b="麦拉斯一生都在捕鱼，他坚信软壳蛤肉是最好的鱼饵，因为鱼儿无法抗拒它的诱惑。在北边的海岸外有一艘失事船只，那片区域散布着软壳蛤。他请求你带给他十份蛤肉。"},{t="麦拉斯怎么说",b="麦拉斯说巫医给他的头痛建议就是这样：去钓鱼，他就会感觉好些。他确实已经感觉好多了。"}},faq={{q="谁是麦拉斯？",a="麦拉斯是凄凉之地海岸上葬影村的一名渔夫。他一生都在捕鱼。",al={"麦拉斯","谁需要蛤肉鱼饵","葬影村的渔夫"}},{q="去哪里可以找到软壳蛤？",a="在葬影村北面，海岸外的一艘失事船只周围，那里散布着软壳蛤。",al={"蛤肉鱼饵位置","失事船只在哪里","软壳蛤肉位置"}},{q="为什么麦拉斯想要蛤肉？",a="他说软壳蛤肉是最好的鱼饵，鱼儿无法抗拒它。",al={"为什么用蛤肉鱼饵","为什么需要蛤肉"}},{q="麦拉斯需要多少蛤肉？",a="十份蛤肉。",al={"需要多少蛤肉","蛤肉数量"}}},fp="9,213,13.261.0,19.137.1,17.97.0,42.116.0,34.88.0,39.28.0"}
P.entries["quest:6143"] = {n="另一种鱼",s="凄凉之地的葬影村有一位名叫杜泽加尔的渔夫，他在拉纳加尔岛附近捕鱼时，整支船队都被纳迦杀害了。杜泽加尔深感愧疚，他请求你前去对付那些滑刃纳迦。",h="凄凉之地的葬影村有一位名叫杜泽加尔的渔夫，他在拉纳加尔岛附近捕鱼时，整支船队都被纳迦杀害了。杜泽加尔深感愧疚，他请求你前去对付那些滑刃纳迦。",kw={"凄凉之地","杜泽加尔","海妖","纳迦","煎炸纳迦","拉纳加尔岛","葬影村","斯卡格胡克","滑刃","女巫"},sec={{t="失去的船队",b="杜泽加尔和他的船员们经常在海岸边一处沉船残骸北面的拉纳加尔岛附近捕鱼。一天早上，纳迦发动了袭击，除了杜泽加尔外，所有人都丧生了。自那以后，杜泽加尔满脑子想的都是复仇，且深感愧疚，痛苦不堪。"},{t="煎炸纳迦",b="杜泽加尔想要消灭七个滑刃海妖、七个滑刃纳迦和五个滑刃女巫。杜泽加尔因为膝盖有伤，无法亲自前去。他说，纳迦通常潜伏在海浪下的珊瑚礁深处，如果你能完成任务，他定会重谢。"}},faq={{q="杜泽加尔是谁？",a="他是凄凉之地葬影村的一名渔夫。他的船队在拉纳加尔岛附近被纳迦杀害，他是唯一的幸存者。",al={"杜泽加尔","谁发布了煎炸纳迦任务"}},{q="杜泽加尔的船队在哪里遇袭？",a="在拉纳加尔岛旁边，海岸上一处沉船残骸的北面。船员们经常在那里捕鱼，直到一天早上纳迦发动了袭击。",al={"渔夫在哪里遇袭","船队遇袭地点","拉纳加尔岛伏击"}},{q="为什么杜泽加尔不亲自去对付纳迦？",a="杜泽加尔膝盖有伤，他说如果不是因为这样，他一定会帮你去杀纳迦。失去船员的愧疚让他深受折磨。",al={"为什么杜泽加尔不能战斗","杜泽加尔膝盖有伤"}},{q="滑刃纳迦潜伏在哪里？",a="杜泽加尔说它们通常潜伏在海浪下的珊瑚礁深处。船队遇袭的地点就在拉纳加尔岛附近。",al={"滑刃纳迦位置","哪里寻找滑刃纳迦","凄凉之地纳迦位置"}},{q="杜泽加尔想要消灭哪些纳迦？",a="七个滑刃海妖、七个滑刃纳迦和五个滑刃女巫。",al={"需要杀掉哪些纳迦","煎炸纳迦任务目标","滑刃纳迦任务要求"}}},fp="17,204,11.280.0,12.277.0,27.133.0,48.116.0,45.143.0,36.134.0,42.88.0"}
P.entries["quest:616"] = {n="幽灵岛",s="克拉兹克代表大财主里维加兹，在藏宝海湾四处打探各种不同寻常的流言。酒馆水手们分享的一个故事提到了离岸的一座闹鬼岛屿，岛上居住着水元素，还有一个语无伦次的鬼魂地精。将这个流言传达给大财主里维加兹，引起了他对一个古老巨魔传说的兴趣。",h="克拉兹克代表大财主里维加兹，在藏宝海湾四处打探各种不同寻常的流言。酒馆水手们分享的一个故事提到了离岸的一座闹鬼岛屿，岛上居住着水元素，还有一个语无伦次的鬼魂地精。将这个流言传达给大财主里维加兹，引起了他对一个古老巨魔传说...",kw={"大财主里维加兹","藏宝海湾","地精鬼魂","克拉兹克","海潮之石","荆棘谷","巨魔传说","水元素"},sec={{t="藏宝海湾的酒馆故事",b="在繁忙的藏宝海湾港口，克拉兹克受大财主里维加兹之托，搜集荆棘谷各地发生的任何异常消息。虽然克拉兹克通常不太在意鬼怪流言，但当地酒馆里水手们的谈话引起了他的注意。他们谈到了一座被水元素占据且有语无伦次的地精鬼魂出没的离岸岛屿，于是他请你将这个故事转达给大财主。"},{t="一个巨魔传说",b="听到克拉兹克关于闹鬼岛屿的报告后，大财主里维加兹回忆起他曾在一本书中读到的一个古老巨魔传说。水元素和地精鬼魂的出现让大财主怀疑，一件古代圣物“海潮之石”可能终于可以被他收入私人藏品中了。"}},faq={{q="是谁派你去和大财主里维加兹谈话的？",a="在藏宝海湾酒馆听到当地水手讲述了一个不安的故事后，克拉兹克请你将这个流言转达给大财主里维加兹。",al={"谁发布了闹鬼岛屿任务","闹鬼岛屿任务发布者","克拉兹克的流言"}},{q="水手们分享了什么流言？",a="水手们报告称，离岸有一座岛屿到处都是水元素，还有一个语无伦次的地精鬼魂在那里徘徊。",al={"岛上有什么","闹鬼岛屿流言","水手故事"}},{q="为什么大财主里维加兹关心鬼故事？",a="大财主回想起一本旧书中记载的巨魔传说。岛上奇怪的描述暗示，一件被称为“海潮之石”的远古圣物可能真的就在那里。",al={"为什么里维加兹想知道","里维加兹的反应","对海潮之石的兴趣"}},{q="这项调查接下来会指向哪里？",a="大财主里维加兹将你的注意力转向圣物本身，在下一步“The Stone of the Tides”中继续追寻。",al={"下一个任务是什么","闹鬼岛屿后续","闹鬼岛屿之后的步骤"}}},fp="16,323,25.428.0,14.337.0,43.135.0,34.127.0,49.189.0,40.135.0"}
P.entries["quest:6161"] = {n="拉克摩尔的财宝！",s="拉克摩尔的航海日志中提到，一艘开往羽月要塞的船只遭到了海洋生物的袭击。为了不让敌人得到财宝，拉克摩尔将箱子藏在了拉纳加尔岛上，而开启箱子的拉克摩尔的金钥匙和拉克摩尔的银钥匙却下落不明。",h="拉克摩尔的航海日志中提到，一艘开往羽月要塞的船只遭到了海洋生物的袭击。为了不让敌人得到财宝，拉克摩尔将箱子藏在了拉纳加尔岛上，而开启箱子的拉克摩尔的金钥匙和拉克摩尔的银钥匙却下落不明。",kw={"箱子","凄凉之地","羽月要塞","金钥匙","拉克摩尔","拉纳加尔岛","银钥匙"},sec={{t="隐藏的箱子",b="航海日志里写着，当拉克摩尔的船只在前往羽月要塞的途中遭到海洋生物袭击时，为了不让敌人得到财宝，他将箱子藏在了拉纳加尔岛上。开启箱子需要两把钥匙，一把银钥匙和一把金钥匙，两把钥匙都已丢失。如果有人能找到钥匙和箱子，就能获得财宝。"}},faq={{q="拉克摩尔的船只在遭到袭击时正航向何处？",a="他的日志记载，他的船在前往羽月要塞的途中遭到了海洋生物的袭击。",al={"拉克摩尔目的地","拉克摩尔要去哪里","拉克摩尔航线"}},{q="拉克摩尔的箱子藏在哪里？",a="在拉纳加尔岛上，那是拉克摩尔藏匿箱子的地方。",al={"拉克摩尔的箱子在哪里","拉克摩尔箱子位置","拉纳加尔岛箱子"}},{q="开启箱子需要什么？",a="两把钥匙，拉克摩尔的银钥匙和拉克摩尔的金钥匙。两把钥匙都已丢失。",al={"拉克摩尔箱子钥匙","如何打开拉克摩尔的箱子","开启拉克摩尔箱子的物品"}},{q="拉克摩尔为什么要藏起他的财宝？",a="他的船受到了攻击，为了不让财宝落入敌人之手，他将箱子藏在了拉纳加尔岛上。",al={"为什么要隐藏拉克摩尔的财宝","拉克摩尔财宝动机"}}},fp="26,243,14.314.0,55.97.0,33.40.0,35.74.0,35.114.0"}
P.entries["quest:617"] = {n="一捆海蛇草",s="藏宝海湾的海盗布劳兹正在寻找一批珍贵的阿基里斯芦苇，送给一位名叫格罗伊的同伙。这些植物必须从纳迦手中夺取，最后一次有人见到他们是在北边的海滩上。",h="藏宝海湾的海盗布劳兹正在寻找一批珍贵的阿基里斯芦苇，送给一位名叫格罗伊的同伙。这些植物必须从纳迦手中夺取，最后一次有人见到他们是在北边的海滩上。",kw={"阿基里斯芦苇","藏宝海湾","格罗伊","纳迦","海盗布劳兹","芦苇","荆棘谷"},sec={{t="一种有利可图的海洋植物",b="海盗布劳兹在藏宝海湾为愿意从事海滨冒险的人提供工作。一位名叫格罗伊的同伙出高价收购阿基里斯芦苇，这是一种生长在海边、被纳迦称为这个名字的芦苇。布劳兹不知道格罗伊为什么要这些芦苇，只知道需要十株，而且纳迦最后一次出现是在北边的海滩上。"}},faq={{q="谁是海盗布劳兹？",a="海盗布劳兹是藏宝海湾的一名私掠者，他为那些寻求工作的人提供机会。",al={"布劳兹","谁发布阿基里斯芦苇任务","布劳兹是谁"}},{q="什么是阿基里斯芦苇？",a="阿基里斯芦苇是纳迦对一种珍贵海洋芦苇的称呼。虽然海盗布劳兹不知道其确切用途，但收藏家们愿意出高价购买这种芦苇。",al={"阿基里斯芦苇","什么是阿基里斯芦苇","阿基里斯芦苇的用途"}},{q="哪里可以找到持有芦苇的纳迦？",a="持有芦苇的纳迦在藏宝海湾以北，沿着荆棘谷的海岸线徘徊。",al={"纳迦在哪里","哪里获得阿基里斯芦苇","阿基里斯芦苇位置"}},{q="谁从海盗布劳兹那里购买芦苇？",a="布劳兹代表一位名叫格罗伊的同伙收集这些芦苇，格罗伊通过出售这些收获的海洋芦苇赚取了可观的利润。",al={"格罗伊是谁","谁需要阿基里斯芦苇","布劳兹的买家"}}},fp="20,201,24.356.0,24.76.0,23.164.0,46.110.0,41.130.0"}
P.entries["quest:618"] = {n="挑战奈古拉什",s="追踪着海克拜瑞·斯莫特船长丢失武器的线索，斯普罗格揭露了一个计划：利用那头巨兽最爱的佳肴来诱捕巨大的内戈拉什。通过在荆棘谷海岸的一艘遇难救生艇上摆下一场宴席，冒险者们可以引出这头野兽，夺回船长被偷走的弯刀。",h="追踪着海克拜瑞·斯莫特船长丢失武器的线索，斯普罗格揭露了一个计划：利用那头巨兽最爱的佳肴来诱捕巨大的内戈拉什。通过在荆棘谷海岸的一艘遇难救生艇上摆下一场宴席，冒险者们可以引出这头野兽，夺回船长被偷走的弯刀。",kw={"荒芜之地","秃鹫翅膀","斯莫特船长","密林葡萄酒","内戈拉什","斯莫特的弯刀","斯普罗格","荆棘谷"},ang={["profession:Cooking"]="整个计划都依赖于斯普罗格的烹饪手艺，特别是那道他远赴荒芜之地才学会的烤秃鹫翅膀的特制配方。"},sec={{t="饥饿的巨人",b="当巨人们摧毁了斯莫特船长的船只时，一头名叫内戈拉什的野兽径直冲向了厨房。与他的同类不同，他想要的并非船员，而是食物。斯普罗格发现内戈拉什想要的是葡萄酒和烤秃鹫翅膀——这是斯普罗格的独门秘制配方，他甚至为了学习这道菜专门去了一趟荒芜之地。"},{t="救生艇上的陷阱",b="为了诱捕这头巨人，斯普罗格设计了一场令人无法抗拒的盛宴。冒险者必须将十份烤秃鹫翅膀和五瓶葡萄酒搬到位于东南海岸线的船长失事救生艇上。被宴席气味吸引的内戈拉什将自投罗网，冒险者可以将他击杀，并剥取船长的宝剑。"}},faq={{q="内戈拉什是谁？",a="内戈拉什是一头饥饿的巨人，他参与了摧毁斯莫特船长船只的行动。他没有去猎杀船员，而是洗劫了船上的厨房，搜刮食物和酒水。",al={"什么是内戈拉什","巨人是谁","内戈拉什背景故事"}},{q="为什么斯普罗格知道如何诱捕内戈拉什？",a="斯普罗格目睹了巨人在沉船时洗劫他的厨房。内戈拉什表现出对斯普罗格的烤秃鹫翅膀和密林葡萄酒的执着，这使得这些储备成为了理想的诱饵。",al={"如何诱捕内戈拉什","为什么选择秃鹫翅膀","内戈拉什的食物"}},{q="对决在哪里进行？",a="宴席必须摆放在斯莫特船长那艘古老的废弃救生艇中，它搁浅在斯普罗格位置东南方的海岸线上。",al={"内戈拉什在哪里","食物放在哪里","救生艇位置"}},{q="这项任务之前发生了什么？",a="这场对决是一条任务线的终点，这条线索始于“绣字腰带”，并延续至“船长的弯刀”。",al={"前置任务是什么","面对内戈拉什之前的任务","内戈拉什的前置条件"}}},fp="15,311,14.300.0,24.316.0,16.150.0,44.214.0,40.136.0,27.130.0"}
P.entries["quest:6181"] = {n="快递消息",s="哨兵岭的军需官刘易斯急需从暴风城运送护甲，以装备人民民兵。由于西部荒野几乎得不到任何官方的军事援助，他派遣你去找狮鹫管理员索尔，将一份紧急征用说明通过航空送往首都。",h="哨兵岭的军需官刘易斯急需从暴风城运送护甲，以装备人民民兵。由于西部荒野几乎得不到任何官方的军事援助，他派遣你去找狮鹫管理员索尔，将一份紧急征用说明通过航空送往首都。",kw={"护甲","飞行管理员","狮鹫","old town","奥斯瑞克·斯图恩","人民民兵","军需官刘易斯","哨兵岭","暴风城","索尔"},ang={["faction:Alliance"]="这次差事揭示了宏伟的暴风城首都与其在西部荒野苦苦挣扎的边境哨所之间深重的后勤断层。",["race:Human"]="对于王国的居民（人类）来说，携带刘易斯的信件凸显了暴风城各省的紧张局势，并介绍了连接家园领土的重要狮鹫航线。"},sec={{t="天际的呼唤",b="哨兵岭在迪菲亚兄弟会暴徒和豺狼人的威胁下孤立无援，极度缺乏来自暴风城的直接军事援助。军需官刘易斯依靠在首都的私人关系来维持人民民兵的武器和护甲补给。装备即将耗尽，他唯一的救命稻草是位于Old Town的护甲商奥斯瑞克·斯图恩。将紧急征用说明送到他手中需要快速的交通，因此刘易斯请求旅行者联系西部荒野的狮鹫管理员索尔。"},{t="飞行网络",b="狮鹫为暴风王国提供了一套极其宝贵的快速交通和信使网络。索尔驻守在哨兵岭，负责管理该哨站与首都之间的空中联络。将刘易斯的信件交给索尔便开启了西部荒野与王城之间的空中航线，这证明了狮鹫骑士对于维持那些无法获得正式援助的边境哨所而言是何等重要。"}},faq={{q="军需官刘易斯为什么要给暴风城送信？",a="西部荒野从暴风城政府得到的直接军事援助很少，导致人民民兵的护甲严重短缺。刘易斯必须联系城内的一位可靠商人，即奥斯瑞克·斯图恩，以确保获得新的补给。",al={"为什么送信","刘易斯的信件目的","为什么要联系暴风城"}},{q="谁是奥斯瑞克·斯图恩？",a="奥斯瑞克·斯图恩是一位护甲商，他的商店“有限免疫”（Limited Immunity）位于暴风城的Old Town。当官方渠道失效时，他就是刘易斯可靠的私人供货商。",al={"奥斯瑞克·斯图恩","谁是奥斯瑞克","有限免疫店主"}},{q="谁是索尔？",a="索尔是驻守在哨兵岭的狮鹫管理员。他负责管理连接西部荒野和暴风城的飞行坐骑，从而实现快速的信使传送和旅行。",al={"谁是索尔","西部荒野飞行管理员","狮鹫管理员索尔"}},{q="为什么暴风城不直接向西部荒野派遣士兵和提供装备？",a="随着瓦里安·乌瑞恩国王失踪，资源捉襟见肘，暴风城的领导层在很大程度上忽视了偏远的农田。像哨兵岭这样的边境哨所必须依靠志愿民兵和私人安排来生存。",al={"为什么没有暴风城的援助","为什么暴风城忽视西部荒野","军队在哪里"}},{q="任何冒险者都能承担这个任务吗？",a="这一任务专门委托给在西部荒野证明了自己的冒险者，作为人类使用王国狮鹫飞行网络的入门介绍。",al={"谁能接受这个任务","人类专属任务","矮人能做这个任务吗"}},{q="这个送信任务接下来要去哪里？",a="将信件交给索尔后，他会安排一次直飞暴风城的狮鹫航程，你将在首都的Gryphon Roost降落，然后前往Old Town寻找奥斯瑞克·斯图恩。",al={"下一步","找过索尔后会发生什么","我接下来去哪"}}},fx={be76534e={q="军需官刘易斯为什么要你帮他送信？",a="西部荒野的守军捉襟见肘，被王室弃之不顾，还遭到遍布平原的迪菲亚暴徒围攻。军需官刘易斯不能离开哨兵岭的补给站，而人民民兵也无法抽调宣誓效忠的守卫去当普通信使，因为防线上每一把武器都不可或缺。一位正前往首都的可靠旅人，能以最快、最安全的方式安排重要补给，同时不让哨站人手短缺。",al={"刘易斯为什么需要我","为什么不派卫兵去暴风城","为什么要送刘易斯的信"}}},fp="15,269,23.481.0,18.370.0,62.223.0,20.175.0,12.161.0,67.235.0,39.172.0,42.176.0"}
P.entries["quest:619"] = {n="引诱奈古拉什",s="在荆棘谷的海岸边，停留着一艘废弃的救生艇，上面刻着已经模糊不清的字样：斯莫茨的复仇号。将烤秃鹫翅膀和密林葡萄酒堆放在这艘残骸上，便能引诱出巨兽尼格拉什。",h="在荆棘谷的海岸边，停留着一艘废弃的救生艇，上面刻着已经模糊不清的字样：斯莫茨的复仇号。将烤秃鹫翅膀和密林葡萄酒堆放在这艘残骸上，便能引诱出巨兽尼格拉什。",kw={"烤秃鹫翅膀","密林葡萄酒","尼格拉什","废弃的救生艇","斯莫茨的复仇号","荆棘谷"},sec={{t="诱人的祭品",b="这艘小船的残骸被遗弃在此，上面仅留着一行风化的刻字，写着斯莫茨的复仇号。为了在狩猎尼格拉什的过程中吸引它的注意，必须将这艘船变成诱饵，堆上十份烤秃鹫翅膀和五瓶密林葡萄酒。"}},faq={{q="什么是废弃的救生艇？",a="这是一艘废弃的破船，上面刻着模糊的斯莫茨的复仇号字样，被用作放置食物和饮料的平台，以引诱尼格拉什。",al={"斯莫茨的复仇号小船","荆棘谷救生艇","什么是斯莫茨的复仇号"}},{q="祭品需要什么物资？",a="祭品需要十份烤秃鹫翅膀以及五瓶密林葡萄酒，并将它们直接堆叠在船骸上。",al={"需要什么食物","诱人的尼格拉什物品","尼格拉什需要什么物品"}},{q="这项任务何时可以进行？",a="这项祭品只能在进行狩猎并面对尼格拉什的任务期间准备。",al={"什么时候可以做诱人的尼格拉什","面对尼格拉什的前提条件","如何解锁诱人的尼格拉什"}}},fp="17,224,19.285.0,28.141.0,46.144.0,37.79.0"}
P.entries["quest:62"] = {n="法戈第矿洞",s="闪金镇的治安官杜汉指派侦察兵去调查有关法戈第矿洞被狗头人占领的报告。该矿洞位于城镇南部的斯通菲尔德农场和马科伦农场之间，它的陷落预示着整个艾尔文森林的虫害问题正在加剧。",h="闪金镇的治安官杜汉指派侦察兵去调查有关法戈第矿洞被狗头人占领的报告。该矿洞位于城镇南部的斯通菲尔德农场和马科伦农场之间，它的陷落预示着整个艾尔文森林的虫害问题正在加剧。",kw={"杜汉","艾尔文","法戈第","闪金镇","玉石矿洞","狗头人","马科伦","斯通菲尔德"},ang={["faction:Alliance"]="矿洞的失守是暴风城在艾尔文森林统治力下降的又一个明显迹象，当地守卫正努力保护重要的基础设施。",["profession:Mining"]="法戈第矿洞内丰富的铜矿脉对初级铁匠至关重要，但开采它们需要清理掉领地意识极强的狗头人。"},sec={{t="闪金镇南部的麻烦",b="当北郡山谷还在处理自身的害虫问题时，令人不安的报告传到了闪金镇，称狗头人已经占据了另一个重要据点。法戈第矿洞坐落在镇南面互相争斗的斯通菲尔德和马科伦农场之间，曾经是该地区石料和矿石的来源。如今，潮湿的隧道里充斥着尖锐的叽叽喳喳声和摇曳的牛脂烛光，促使治安官杜汉派遣冒险者前去侦察矿洞深处，以确认最糟糕的情况。"},{t="紧张的卫兵",b="确认了虫害情况只会让暴风城卫兵更加头疼。由于正规部队忙于防范迪菲亚兄弟会的强盗和豺狼人的入侵，人手捉襟见肘，守卫无法直接清理矿洞。在得到确认后，杜汉那阴沉的反应凸显了核心地带控制权的逐渐丧失，这让他立刻开始担忧东北方向像玉石矿洞那样的其他矿点。"}},faq={{q="法戈第矿洞在哪里？",a="法戈第矿洞位于艾尔文森林闪金镇的正南方，就在斯通菲尔德农场和马科伦农场之间。",al={"法戈第位置","法戈第矿洞在哪里","法戈第矿洞地图"}},{q="谁派你去侦察法戈第矿洞？",a="驻扎在闪金镇的暴风城卫兵指挥官治安官杜汉，将侦察隧道任务交给了你。",al={"谁发布法戈第任务","治安官杜汉任务"}},{q="什么生物占领了矿洞？",a="矿洞已经被狗头人完全占领，它们在里面扎根，点燃蜡烛，并驱逐了人类工人。",al={"法戈第里有什么","法戈第里的怪物"}},{q="为什么治安官杜汉需要冒险者去检查矿洞？",a="暴风城卫兵为了应对当地的强盗、兽人残党和豺狼人突袭已经疲于奔命，杜汉连派遣士兵去核实常规侦察报告的人手都抽调不出来。",al={"为什么要派侦察兵","为什么守卫不亲自去"}},{q="侦察法戈第矿洞后会发生什么？",a="当你向治安官杜汉报告这个坏消息后，他担心问题已经扩散，并派遣你去东北方向调查玉石矿洞。",al={"法戈第之后的任务","what comes next"}},{q="为什么法戈第矿洞的虫害如此严重？",a="法戈第矿洞的陷落证明北郡的狗头人虫害并非孤立事件。这显示了野外威胁正以何等速度侵蚀暴风城门外已经定居的农田。",al={"为什么法戈第很重要","法戈第矿洞背景故事"}}},fp="18,172,26.389.0,16.318.0,36.118.0,42.102.0,40.83.0,59.156.0,47.133.1,53.184.0"}
P.entries["quest:621"] = {n="赞吉尔的秘密",s="在藏宝海湾，地精克兰克·菲兹巴布看中了被放逐的巨魔赞吉尔所酿造的一种强效混合剂。赞吉尔利用这种植物混合物来控制附近丛林废墟中追随者的思想，并增强他们的体质。菲兹巴布认为这种物质对于任何想要控制他人的人来说都极具价值，因此他想要获得一些样本供自己使用。",h="在藏宝海湾，地精克兰克·菲兹巴布看中了被放逐的巨魔赞吉尔所酿造的一种强效混合剂。赞吉尔利用这种植物混合物来控制附近丛林废墟中追随者的思想，并增强他们的体质。菲兹巴布认为这种物质对于任何想要控制他人的人来说都极具价值，因此...",kw={"aboraz","藏宝海湾","菲兹巴布","朱布瓦尔","混合剂","荆棘谷","赞吉尔"},sec={{t="精神控制药剂",b="在藏宝海湾东北方，名为赞吉尔的被放逐巨魔在朱布瓦尔废墟和Aboraz建立了一个避难所。他因被部落领袖忌惮其对他人的精神控制能力而被放逐，如今赞吉尔完全通过从丛林植物中提取的混合剂来指挥着一群追随者。这些混合剂在增强他们体力的同时消磨了他们的意志，将他们变成了温顺而强壮的奴隶。"},{t="一种有利可图的混合剂",b="克兰克·菲兹巴布从这位流亡者的技艺中看到了明显的商机。任何想要控制他人的人都会为这种药剂付出高昂的代价，这促使这名地精直接从废墟中寻求供应。只要运送者对这笔交易守口如瓶，交付足够的样本不仅能获得常规的金币报酬，还能获得一笔额外的封口费。"}},faq={{q="谁是被放逐者赞吉尔？",a="赞吉尔是一位居住在藏宝海湾东北部废墟中的被放逐巨魔。他之前的领袖因恐惧他对他人的精神控制能力而将他流放。",al={"谁是赞吉尔","赞吉尔背景故事","赞吉尔为何被放逐"}},{q="赞吉尔的药剂究竟有什么作用？",a="这种混合剂由原生丛林植物酿制而成，它能摧毁并压制饮用者的自由意志，同时不自然地增强他们的体力。",al={"什么是赞吉尔的药剂","赞吉尔药剂的效果","赞吉尔药水效果"}},{q="赞吉尔居住在哪里？",a="赞吉尔和他的追随者居住在位于荆棘谷、藏宝海湾东北部的朱布瓦尔废墟和Aboraz。",al={"赞吉尔位置","赞吉尔在哪里","废墟在哪里"}},{q="为什么克兰克·菲兹巴布想要这种混合剂？",a="克兰克·菲兹巴布认为，这种混合剂在那些想要控制他人的人群中能卖出高价，他打算寻找它的用途。",al={"克兰克为何想要混合剂","克兰克将如何使用赞吉尔的药剂"}},{q="为什么克兰克在交付时支付了额外费用？",a="克兰克提供额外的奖金明确是为了换取谨慎，确保这种精神控制药剂的获取过程保持为一项私人的商业事务。",al={"克兰克·菲兹巴布的额外报酬","克兰克的封口费"}}},fp="15,382,21.419.0,19.334.0,26.156.0,39.159.0,25.121.0,42.138.0,38.150.1"}
P.entries["quest:622"] = {n="向卡雷布下士回报",s="克拉兹克已经修好了锅，还加装了一个蒸汽哨，并在底部安装了一个新的斩骨刀，可以轻易切开腿骨。现在这口锅必须送回给反抗军营地的卡雷布下士。",h="克拉兹克已经修好了锅，还加装了一个蒸汽哨，并在底部安装了一个新的斩骨刀，可以轻易切开腿骨。现在这口锅必须送回给反抗军营地的卡雷布下士。",kw={"藏宝海湾","卡雷布下士","炖锅","克拉兹克","反抗军营地","荆棘谷"},sec={{t="更好的锅",b="克拉兹克已经完成了你送来的锅的修理工作。它现在多了一个蒸汽哨，底部还装了一把可以切开腿骨的新斩骨刀。克拉兹克称它是大厨的绝对心头好，相信主人一定会满意。必须把它送回给反抗军营地的卡雷布下士。"},{t="回到营地",b="卡雷布很高兴看到这口锅又能用了，因为晚饭终于可以开火了。卡雷布随后询问你在藏宝海湾过得如何，称那里是个混乱的城镇，并传达了一个谣言：地精有时会把醉酒的水手拖走，送上驶向未知地点的奴隶船。"}},faq={{q="卡雷布下士是谁？",a="卡雷布下士在反抗军营地，等待着藏宝海湾的克拉兹克修理好的烹饪锅。",al={"卡雷布下士","卡雷布是谁","卡雷布 反抗军营地","卡雷布下士在哪","卡雷布位置"}},{q="克拉兹克对这口锅做了什么？",a="克拉兹克修复了它，然后加装了第二个蒸汽哨，并在底部安装了一把可以切断腿骨的斩骨刀。",al={"克拉兹克的锅升级","克拉兹克修理了什么","克拉兹克的炖锅"}},{q="这一步之前发生了什么？",a="首先完成了克拉兹克的请求。",al={"前置任务","是什么导致了回到卡雷布下士任务"}}},fp="24,185,12.290.0,16.272.1,22.101.0,30.117.0,27.28.0"}
P.entries["quest:623"] = {n="一捆海蛇草",s="位于荆棘谷的海盗布劳兹需要将一捆新鲜的阿基里斯芦苇运过大海，送往尘泥沼泽。他的联络人水手格罗伊在塞拉摩岛有一位客户，急需更多的芦苇，而布劳兹自己要过一周才会启程前往那里。",h="位于荆棘谷的海盗布劳兹需要将一捆新鲜的阿基里斯芦苇运过大海，送往尘泥沼泽。他的联络人水手格罗伊在塞拉摩岛有一位客户，急需更多的芦苇，而布劳兹自己要过一周才会启程前往那里。",kw={"阿基里斯","布劳兹","尘泥","格罗伊","海盗","芦苇","荆棘谷","塞拉摩"},ang={["faction:Alliance"]="塞拉摩岛是尘泥沼泽的一座联盟据点，不过海盗布劳兹警告说，如果游客属于不招人待见的那类人，在这里依然会遇到麻烦。"},sec={{t="前往塞拉摩的航程",b="你离开的时候，海上传来了消息。塞拉摩岛的水手格罗伊给海盗布劳兹捎来口信，表示对之前那批阿基里斯芦苇很满意，并提到有客户急需更多货源。由于布劳兹计划在一周后才会启航前往尘泥沼泽，他便将这捆芦苇托付给你，让你亲自送达。"},{t="码头交货",b="水手格罗伊在塞拉摩的码头上等待着。虽然一开始对陌生人表现得有些冷淡，但在得知是布劳兹安排的送货后，格罗伊仔细检查了货物。他对芦苇的品质感到满意，付了一些钱作为跑腿费，并立刻警告旅客不要在他的码头附近闲逛。"}},faq={{q="水手格罗伊是谁？",a="水手格罗伊是尘泥沼泽塞拉摩岛上的一名海盗布劳兹的联络人，有一位客户想要更多的阿基里斯芦苇。",al={"谁是格罗伊","格罗伊 塞拉摩","水手格罗伊"}},{q="为什么海盗布劳兹需要一名信使？",a="布劳兹收到消息，格罗伊有一位急切的买家正在等待另一捆阿基里斯芦苇。由于布劳兹计划在一周后才会启航前往尘泥沼泽，他只能依靠旅行者立即出发进行运送。",al={"为什么要运送芦苇","为什么要塞拉摩","布劳兹的送货"}},{q="这批货物需要送到哪里？",a="这捆芦苇必须通过海路运往塞拉摩岛，那是一座位于尘泥沼泽的联盟港口。",al={"把芦苇带到哪里","阿基里斯交付地点","尘泥沼泽交付"}},{q="这次行程之前发生了什么？",a="这次运送是在荆棘谷的初步采集工作之后进行的，在那之前，人们采集了阿基里斯芦苇并将其带给了海盗布劳兹。",al={"前置任务","阿基里斯芦苇任务线","先决条件"}}},fp="20,269,23.387.0,21.318.1,22.130.0,41.227.0,36.110.0,30.157.0"}
P.entries["quest:624"] = {n="科泰罗的谜题",s="在一张于蛮荒海岸的血帆海盗船只上发现的隐藏羊皮纸上，记录着科泰罗那晦涩难懂的诗句。解开这首诗的谜题将指引旅行者去寻找那座华丽桥梁下所隐藏的线索。",h="在一张于蛮荒海岸的血帆海盗船只上发现的隐藏羊皮纸上，记录着科泰罗那晦涩难懂的诗句。解开这首诗的谜题将指引旅行者去寻找那座华丽桥梁下所隐藏的线索。",kw={"血帆海盗","桥","科泰罗","谜题","卷轴","悲伤沼泽","蛮荒海岸"},sec={{t="海盗的谜题",b="在停泊于荆棘谷南海岸的血帆舰队船只上，散落着写有诗句的笔记。科泰罗的诗句描述了一座做工精细、人来人往的桥梁，它位于逆风小径以东，赤脊山以南。任何想要解开这个谜团的人都必须遵循诗中的指引，走出丛林，进入沼泽，去寻找那桥下之物。"},{t="沼泽之渡",b="循着诗句的指引，会来到悲伤沼泽中一座横跨于浑浊水面之上的华丽桥梁下方。在桥底静静躺着一张浸湿的羊皮纸，等待着揭示科泰罗谜题的下一步。"}},faq={{q="这个谜团从哪里开始？",a="谜题始于一张羊皮纸碎片，它是从停泊在藏宝海湾以南、蛮荒海岸外的血帆海盗舰队周围发现的。",al={"科泰罗的谜题从哪里开始","科泰罗的谜题起始位置","科泰罗的谜题在哪里能找到"}},{q="谜题描述了什么地点？",a="这首诗指向位于悲伤沼泽的一座人来人往的华丽桥梁，它地处逆风小径以东，赤脊山以南。",al={"科泰罗的谜题中是哪座桥","谜题指向哪里","逆风小径以东赤脊山以南的桥"}},{q="你在桥下寻找什么？",a="谜题中说桥下有东西在等待着，那是一个在那里停留了无数个日夜的暗示或线索。",al={"你在悲伤沼泽中找到了什么","科泰罗桥下的线索","桥下有什么"}},{q="谁写下了这个谜题？",a="这个谜题以科泰罗之名流传，但羊皮纸上并未提及关于他身份的更多信息。",al={"谁是科泰罗","科泰罗背景故事","谁制作了科泰罗的谜题"}}},fp="17,205,20.366.0,18.204.1,30.138.0,41.151.0,46.110.0,21.92.0"}
P.entries["quest:625"] = {n="科泰罗的谜题",s="循着在悲伤沼泽中发现的一份浸水的羊皮纸所留下的线索，第二段神秘的诗句指引旅行者前往卡利姆多的一片遥远之地。解读这些诗句会将寻宝者引向尘泥沼泽西南方的一个洞穴。",h="循着在悲伤沼泽中发现的一份浸水的羊皮纸所留下的线索，第二段神秘的诗句指引旅行者前往卡利姆多的一片遥远之地。解读这些诗句会将寻宝者引向尘泥沼泽西南方的一个洞穴。",kw={"鲜血沼泽墓穴","cortello","cortello的谜题","尘泥沼泽","发霉的卷轴","浸湿的卷轴","荆棘谷"},sec={{t="指向海对岸的诗句",b="Cortello留下的第二段诗句指引寻找者前往遥远的卡利姆多大陆。这首诗描述了一片位于贫瘠之地东侧、危险而阴郁的区域：潮湿且险恶的尘泥沼泽。"},{t="西南方的洞穴",b="根据谜题，线索就藏在沼泽西南方的一个洞穴里。"},{t="诗句指引何处",b="沼泽西南方的洞穴就是鲜血沼泽墓穴，一份发霉的卷轴就在那里等待被发现。"}},faq={{q="这个谜题把旅行者引向何处？",a="这首诗把寻找者引向卡利姆多，具体来说是位于贫瘠之地东侧的尘泥沼泽。",al={"cortello的谜题去哪","cortello第二部分位置","第二个谜题线索在哪里"}},{q="线索藏在尘泥沼泽的什么地方？",a="诗句指出线索位于沼泽西南方的一个洞穴中。",al={"尘泥沼泽的洞穴在哪里","尘泥沼泽谜题洞穴","鲜血沼泽墓穴谜题"}},{q="什么物品开启了这一步线索？",a="这一步始于在第一段谜题的终点，即悲伤沼泽中发现的一份浸湿的卷轴。",al={"任务如何开始","什么开启了cortello的谜题2"}}},fp="17,253,31.224.0,20.90.0,21.98.1,38.104.0,45.66.0,43.107.0"}
P.entries["quest:626"] = {n="科泰罗的谜题",s="一张发霉的神秘卷轴上写着Cortello留下的最后一组诗句。这些押韵的指示指引寻宝者一路向北，前往饱受战火蹂躏的洛丹伦大陆，并在辛特兰的海岸瀑布旁找到了线索的终点。",h="一张发霉的神秘卷轴上写着Cortello留下的最后一组诗句。这些押韵的指示指引寻宝者一路向北，前往饱受战火蹂躏的洛丹伦大陆，并在辛特兰的海岸瀑布旁找到了线索的终点。",kw={"cortello","cortello的谜题","辛特兰","洛丹伦","发霉的卷轴","俯瞰悬崖","宝藏","瀑布"},sec={{t="最终线索",b="遵循之前的卷轴，这张风化的文本指引寻宝者离开南方的热带地区，前往战乱不断的洛丹伦。谜题要求寻宝者去寻找北方巨大的动荡，并承诺只要勇于面对那种动荡并沿着海岸线探索，这场漫长的追寻就会结束。"},{t="瀑布之下",b="诗句明确指出，最后的宝藏位于辛特兰的海岸边。在巨大的瀑布底部，宝藏就藏在水下。"}},faq={{q="这个谜题指向哪里？",a="诗句指向洛丹伦的辛特兰海岸，指引寻宝者去查看悬崖上奔流而下的巨大瀑布底部的水下区域。",al={"cortello谜题终点在哪里","cortello谜题3该去哪里","cortello辛特兰位置"}},{q="什么开启了这一部分的搜索？",a="这最后一条谜题出自一张发霉的卷轴，它是从Cortello寻宝任务的早期步骤中发现的。",al={"如何开始cortello谜题第三部分","在哪里获取卷轴"}},{q="谁写了这些诗句？",a="这些谜题和隐藏的卷轴是一位名叫Cortello的人留下的，他引导寻宝者去寻找他隐藏的宝藏。",al={"谁是cortello","谁制作了cortello谜题"}}},fp="17,266,14.285.0,19.143.0,28.160.0,36.109.0,23.117.0"}
P.entries["quest:6261"] = {n="杜加尔·朗德瑞克",s="这项任务旨在向冒险者介绍暴风城的首席狮鹫管理员邓加尔·长饮。在从奥斯瑞克·斯图恩处收集紧急物资后，信使必须安排快速的空中交通，将装备运送回西部荒野的受困守军手中。",h="这项任务旨在向冒险者介绍暴风城的首席狮鹫管理员邓加尔·长饮。在从奥斯瑞克·斯图恩处收集紧急物资后，信使必须安排快速的空中交通，将装备运送回西部荒野的受困守军手中。",kw={"邓加尔·长饮","狮鹫管理员","奥斯瑞克·斯图恩","奥斯瑞克的箱子","哨兵岭","暴风城","索尔","trade district","西部荒野"},ang={["faction:Alliance"]="在王国中央军队缺席的情况下，建立暴风城与区域定居点之间的狮鹫航线对于维持秩序至关重要。",["race:Dwarf"]="像邓加尔·长饮和索尔这样的人类驯养员将矮人与狮鹫之间古老的羁绊带入了人类王国的中心。",["race:Human"]="由于西部荒野被暴风城贵族议会所忽视，个体商人和当地的驯养员必须直接合作，以确保前哨站拥有充足的武装。"},sec={{t="一条至关重要的补给线",b="西部荒野正被迪菲亚兄弟会的暴徒和狂暴的收割傀儡逼入绝境，使得军需官刘易斯和人民民兵组织急需补给。当刘易斯向首都发出请求新鲜装备的消息时，军械士奥斯瑞克·斯图恩打包了所有请求的物资。通过布满强盗的艾尔文森林和西部荒野的道路步行运送军事货物需要耗费宝贵的时间，这使得王国新建成的空中航线成为了一条至关重要的生命线。"},{t="狮鹫管理员",b="邓加尔·长饮坐镇在Trade District，负责协调暴风城的信使和载客狮鹫。这些雄伟的野兽传统上由蛮锤矮人饲养和驯化，只要两端的栖息地互相连通，就能在人类领地之间提供可靠的交通。通过将奥斯瑞克的重型板条箱直接带给邓加尔，信使们可以了解空中物流的运作方式，从而在首都的储备物资和像哨兵岭这样的前哨站之间建立直接联系。"}},faq={{q="邓加尔·长饮是谁？",a="邓加尔·长饮是暴风城的狮鹫管理员，驻扎在Trade District的飞行点。他负责管理首都的信使野兽，并监管洛丹伦南部和艾泽拉斯整个联盟领地的客运飞行。",al={"邓加尔","邓加尔是谁","暴风城狮鹫管理员"}},{q="为什么奥斯瑞克要通过狮鹫运送这个板条箱？",a="西部荒野的军需官刘易斯和人民民兵组织的装备严重短缺，难以抵御强盗。步行或用马车运送重型物资需要数天时间，且面临伏击的风险，而训练有素的狮鹫可以在几分钟内将奥斯瑞克的物资跨越边境运抵目的地。",al={"为什么要用狮鹫","为什么不步行","奥斯瑞克板条箱运输"}},{q="索尔是谁，为什么我必须先和他谈谈？",a="索尔是驻扎在西部荒野哨兵岭的狮鹫管理员。狮鹫是沿着特定的点对点航线进行训练的，这意味着只有当你已经在另一端通过与索尔联络规划好路径后，邓加尔的坐骑才能把你载回西部荒野。",al={"索尔是谁","为什么要见索尔","索尔狮鹫"}},{q="邓加尔接受了板条箱之后会发生什么？",a="一旦邓加尔检查完货物，他就会准备好狮鹫供你飞行，并指引你将板条箱直接送给哨兵岭的军需官刘易斯。",al={"接下来做什么","回到刘易斯","下一个任务"}},{q="这个任务在飞行链中处于什么位置？",a="它是飞行网络入门教程的第三步，该教程始于西部荒野的“迅捷的信使”，通过“前往暴风城”将你带到暴风城，与邓加尔会面，并以“回到刘易斯身边”结束。",al={"任务链","飞行任务线","有多少个任务"}},{q="为什么暴风城依赖矮人的狮鹫？",a="自从第二次战争将洛丹伦联盟与辛特兰的蛮锤部族团结在一起后，狮鹫就成为了联盟各领域最出色的侦察兵和运输工具，它们提供的快速交通绕过了荒废的道路和敌对的封锁。",al={"暴风城为何使用狮鹫","联盟狮鹫背景故事"}}},fp="16,140,20.410.0,23.462.0,24.206.0,44.250.0,47.227.0,44.130.0,48.216.0,44.233.0"}
P.entries["quest:627"] = {n="克拉兹克的要求",s="当克拉兹克在藏宝海湾修理一只送来的瓦罐时，他要求你帮个忙作为回报。他想要在修理好炊具交给你之前，先从北边山峦中一个遥远的洞穴里取回稀有的次级血石矿。",h="当克拉兹克在藏宝海湾修理一只送来的瓦罐时，他要求你帮个忙作为回报。他想要在修理好炊具交给你之前，先从北边山峦中一个遥远的洞穴里取回稀有的次级血石矿。",kw={"阿拉希高地","血石","藏宝海湾","枯须峡谷","克拉兹克的帮忙","克拉兹克","次级血石矿","荆棘谷"},ang={["profession:Mining"]="克拉兹克明确指出，采集这种矿石需要采矿专长，并警告说任何缺乏该技能的人都需要找到有能力开采矿脉的人。"},sec={{t="北方的交易",b="在藏宝海湾交出破损的炊具后，克拉兹克停下手中的修理工作，向你提出了一笔交易。他没有免费修理这口锅，而是指引你向北远行至阿拉希高地。在枯须峡谷的一个洞穴中藏有次级血石矿，这是一种低品位但被知情者所珍视的矿物。"},{t="峡谷中的矿石",b="克拉兹克答应在你进行漫长的北方之旅时修理这口锅。他要求你带回四份血石矿回港口，并表示如果你带回了足够的样本，他会为你这次帮忙提供报酬。他还明确表示，如果你没有开采矿石所需的知识，你就需要寻找懂得开采的人帮忙。"}},faq={{q="克拉兹克是谁，他想要什么？",a="克拉兹克是在藏宝海湾的一名地精。在修理送来的破瓦罐时，他要求你从北方运回四份稀有的血石矿。",al={"克拉兹克是谁","克拉兹克的要求"}},{q="血石矿在哪里？",a="次级血石矿位于阿拉希高地北部深处的枯须峡谷里的一个山洞中。",al={"血石矿在哪里","血石位置","枯须峡谷位置"}},{q="为什么克拉兹克想要低品位的矿石？",a="尽管洞穴里的矿床质量不是最高的，但克拉兹克指出，即使是低品位的血石，对于那些拥有工艺和知识来利用它的人来说，也具有相当大的价值。",al={"为什么是次级血石","血石价值"}},{q="在这个任务之前发生了什么？",a="在克拉兹克提出这个要求之前，你被派往藏宝海湾，在“克拉兹克的烹饪”任务中运送破损的容器。",al={"前一个任务","之前发生了什么"}},{q="收集到血石后会发生什么？",a="一旦克拉兹克收到四份矿石并支付报酬，旅程将继续进行，接下来的任务是“返回卡雷布下士处”。",al={"下一个任务","what comes next"}}},fp="16,244,18.339.0,18.350.0,36.175.0,36.141.0,35.193.0,30.109.0,44.127.0"}
P.entries["quest:628"] = {n="刨花皮靴",s="在藏宝海湾，崔斯里克已经完成了Excelsior靴子的内部结构，现在需要一张老盐水鳄鱼皮来制作外部。",h="在藏宝海湾，崔斯里克已经完成了Excelsior靴子的内部结构，现在需要一张老盐水鳄鱼皮来制作外部。",kw={"藏宝海湾","鳄鱼","崔斯里克","年长鳄鱼","excelsior","盐水鳄鱼","荆棘谷"},sec={{t="外层",b="内部结构已经完成，现在只剩下外层了。为此，崔斯里克只使用最上等的年长鳄鱼皮，因为它们更坚韧，能为Excelsior系列的图案和装饰提供更好的表面。唯一符合崔斯里克计划的皮肤就是年长盐水鳄鱼的皮，找到这种鳄鱼非常困难，因为这种年长的鳄鱼只会在保护其他盐水鳄鱼时才会现身。崔斯里克还在某处读到过，盐水鳄鱼的数量正在减少，这会影响生意。"},{t="崔斯里克的感谢",b="崔斯里克很高兴：订单可以完成了，并且能搭上下一班开往安德麦的船运往里德尔沃克斯主管那里，而且还是提前完成的。崔斯里克还多做了一些，并送给你一双作为你辛苦劳作的报酬，他坚称没有哪双靴子能比得上Excelsior系列。"}},faq={{q="谁是崔斯里克？",a="崔斯里克是藏宝海湾的一位制鞋匠，专门制作Excelsior系列的靴子。",al={"崔斯里克","藏宝海湾制鞋匠","崔斯里克npc"}},{q="为什么崔斯里克需要年长盐水鳄鱼皮？",a="崔斯里克说，年长鳄鱼的皮更坚韧，能为Excelsior系列的图案和装饰提供更好的表面，而且只有年长盐水鳄鱼的皮才符合他的计划。",al={"为什么需要鳄鱼皮","excelsior靴子材料","年长鳄鱼皮的用途"}},{q="为什么年长盐水鳄鱼很难找？",a="崔斯里克说，年长的鳄鱼只会在保卫其他盐水鳄鱼时才现身。",al={"哪里有年长鳄鱼","寻找年长盐水鳄鱼","如何召唤年长鳄鱼"}},{q="这个任务之前是什么任务？",a="之前是“需要组装”。",al={"前置任务","excelsior前置条件","需要组装关联"}},{q="崔斯里克对盐水鳄鱼有什么担忧？",a="崔斯里克读到过盐水鳄鱼的数量正在减少，这对生意不利。",al={"鳄鱼是否正在灭绝","盐水鳄鱼数量","鳄鱼灭绝"}}},fp="9,145,15.506.0,17.256.1,16.75.0,57.172.0,48.72.0,30.34.0,59.101.0"}
P.entries["quest:6281"] = {n="赶赴暴风城",s="这个任务向西部荒野的冒险者们介绍了暴风城王国的狮鹫网络，既快速又方便。旅行者们带着哨兵岭急需的征用物资，直接飞往Old Town，将消息传达给商人奥斯瑞克·斯图恩。",h="这个任务向西部荒野的冒险者们介绍了暴风城王国的狮鹫网络，既快速又方便。旅行者们带着哨兵岭急需的征用物资，直接飞往Old Town，将消息传达给商人奥斯瑞克·斯图恩。",kw={"飞行点","狮鹫","刘易斯的便笺","limited immunity","old town","奥斯瑞克·斯图恩","哨兵岭","索尔"},ang={["faction:Alliance"]="由狮鹫管理员维护的飞行网络将联盟分散的前哨站连接在一起，使偏远的驻军与首都保持紧密联系。",["race:Human"]="回到Old Town后，人们可以感受到普通公民和孤立的前线人员对宏伟的贵族议会政治感到多么疏离。"},sec={{t="展翅高飞",b="在哨兵岭的军需官刘易斯准备好征用便笺后，当地的狮鹫管理员索尔会提供离开这片纷争平原的最快路径。只需支付少量费用，旅行者便可骑上一只受过训练的狮鹫，翱翔在尘土飞扬的农田、作为艾尔文森林边界的河流，以及暴风城高耸洁白的城墙之上。"},{t="Old Town补给线",b="降落在首都的贸易栖木后，信使前往Old Town，在他名为Limited Immunity的商店找到奥斯瑞克·斯图恩。奥斯瑞克为前线提供装备和补给，但他冷淡的态度凸显了西部荒野陷入困境的人民民兵与暴风城中分心于政务的统治者之间日益加深的隔阂。"}},faq={{q="这个任务的目的是什么？",a="该任务是作为联盟狮鹫航线的实践入门，教导冒险者如何在遥远的前哨站和首都之间快速往返。",al={"为什么要完成此任务","任务目的","前往暴风城任务目标"}},{q="奥斯瑞克·斯图恩在哪里？",a="奥斯瑞克·斯图恩经营着Limited Immunity商店，位于暴风城内Old Town蜿蜒的街道旁。",al={"奥斯瑞克·斯图恩在哪里","寻找奥斯瑞克·斯图恩","limited immunity位置"}},{q="为什么哨兵岭需要来自暴风城的补给？",a="哨兵岭的人民民兵正在与迪菲亚潜行者苦战，却从首都获得了极少的正式军事援助，这迫使军需官刘易斯不得不直接向民间商人购买装备。",al={"为什么需要补给","西部荒野补给问题","哨兵岭装备"}},{q="索尔是谁？",a="索尔是驻扎在哨兵岭的联盟狮鹫管理员，负责管理连接西部荒野与暴风城及其他友方据点的飞行路线。",al={"索尔是谁","西部荒野狮鹫管理员","索尔 西部荒野"}},{q="刘易斯的便笺里写了什么？",a="这是一份来自军需官刘易斯的紧急征用单，详细列出了维持哨兵岭驻军装备所需的物资和补给。",al={"刘易斯的便笺","便笺上写了什么","便笺内容"}},{q="交付便笺后会发生什么？",a="收到征用单后，奥斯瑞克会指示你去找暴风城的狮鹫管理员邓加·长酒，安排将订购的物资运回西部荒野。",al={"接下来做什么","后续任务","奥斯瑞克·斯图恩之后"}}},fp="21,106,11.325.0,21.288.0,34.129.0,30.70.0,52.204.0,12.125.0,27.145.0,39.173.0"}
P.entries["quest:6282"] = {n="鹰身人的威胁",s="“鹰身人威胁”是一个部落任务，由石爪山脉烈日石居的马格兰提供。秉承牛头人作为大地守护者的天职，冒险者们将受命前往西部的焦炭谷，削减血怒鹰身人部族不断壮大的势力。",h="“鹰身人威胁”是一个部落任务，由石爪山脉烈日石居的马格兰提供。秉承牛头人作为大地守护者的天职，冒险者们将受命前往西部的焦炭谷，削减血怒鹰身人部族不断壮大的势力。",kw={"伏击者","血怒","焦炭谷","部族","鹰身人威胁","马格兰","暴羽者","杀戮者","石爪山脉","烈日石居"},ang={["class:Druid"]="血怒部族那扭曲的存在，亵渎了焦炭谷原本就脆弱不堪、饱受火灾蹂躏的生态环境。",["class:Shaman"]="在马格兰的号令下，萨满们响应召唤，肃清那些破坏自然元素平衡的邪恶亵渎者。",["faction:Horde"]="清扫焦炭谷的天空，巩固了部落在烈日石居的立足点，以抵御栖息在石爪山脉中的危险野外势力。",["race:Tauren"]="对于牛头人角色而言，剿灭这些不断蚕食领地的血怒鹰身人，是履行他们作为卡利姆多荒野守护者的祖先誓言的荣誉职责。"},sec={{t="大地的守护者",b="烈日石居的牛头人肩负着保卫石爪山脉的神圣职责，他们维护着自然平衡，并保护着过往的旅人免受当地危险的侵害。烈日石居的领袖长者马格兰正忧心忡忡地注视着当地鹰身人数量的疯狂增长。血怒部族已经遍布了焦炭谷那片焦灼的荒地，不仅袭扰过往的野兽，还切断了交通要道。如果不加遏制，这些掠食成性的族群迟早会彻底切断烈日石居与外界的联系。"},{t="扫荡焦炭谷",b="烈日石居的西侧是焦炭谷，那是一片由灰烬、焦土和残木构成的荒凉废墟，是灾难性大火后留下的伤痕。血怒鹰身人在此处古老林木的焦骸高处筑巢，建立了据点。马格兰委派部落勇士深入这片充满敌意的火山口，去削减数十名血怒伏击者、血怒杀戮者和血怒暴羽者的数量。削弱它们的族群可以打破该部族对山谷的即时掌控，从而为直接对抗她们的母系首领铺平道路。"}},faq={{q="谁发放“鹰身人威胁”任务？",a="该任务由马格兰发放，他是位于石爪山脉烈日石居中央水池附近的一名牛头人。",al={"鹰身人威胁任务发布者","在哪里接取鹰身人威胁","马格兰任务"}},{q="血怒鹰身人在哪里？",a="血怒鹰身人栖息在焦炭谷各地，这是一片位于烈日石居西侧的焦灼荒原。烈日石居后方的一条山路可直通山谷。",al={"血怒鹰身人在哪里","血怒鹰身人位置","焦炭谷鹰身人"}},{q="为什么牛头人要消灭鹰身人？",a="牛头人视自己为石爪山脉自然平衡的守护者。马格兰担心血怒鹰身人正在卡利姆多大举扩张，不仅袭击无辜者，还阻碍生物在土地上的自由迁徙。",al={"为什么要杀鹰身人","牛头人与鹰身人的冲突","为什么马格兰痛恨鹰身人"}},{q="完成“鹰身人威胁”后还有什么任务？",a="完成“鹰身人威胁”后将解锁后续任务“血怒血统”，马格兰会派遣你去消灭血怒部族的统治核心。",al={"鹰身人威胁的后续任务","鹰身人威胁后续","鹰身人威胁之后做什么"}},{q="这个任务是部落专属的吗？",a="是的。该任务仅向烈日石居营地的部落成员开放。",al={"联盟可以做鹰身人威胁吗","鹰身人威胁部落专属","联盟鹰身人威胁"}},{q="必须杀死哪些种类的鹰身人？",a="你必须在焦炭谷杀死七名血怒鹰身人、七名血怒伏击者、七名血怒杀戮者和七名血怒暴羽者。",al={"要杀哪种鹰身人","焦炭谷鹰身人种类","鹰身人威胁目标"}}},fx={["34ac97e1"]={q="血怒鹰身人是谁？为什么她们构成威胁？",a="血怒鹰身人是一群凶残的鹰身人，盘踞在焦炭谷。据大地缚灵马格兰所说，她们是卡利姆多各地鹰身人数量激增的主要原因。她们不断侵占周边荒野，将无辜的旅人和野生动物困在自己的势力范围内。",al={"血怒鹰身人","血怒鹰身人是谁","为什么要杀血怒鹰身人"}}},fp="16,287,22.518.0,25.537.0,37.139.0,40.173.0,42.251.0,45.175.0,25.91.0,36.149.0"}
P.entries["quest:6283"] = {n="血怒一族",s="血怒血脉是部落的一项任务，由烈日石居的马格兰发布，要求击杀血怒鹰身人的领袖。这是马格兰净化焦炭谷的最终努力，旨在打破这些鹰身人对这片荒凉之地的凶残统治。",h="血怒血脉是部落的一项任务，由烈日石居的马格兰发布，要求击杀血怒鹰身人的领袖。这是马格兰净化焦炭谷的最终努力，旨在打破这些鹰身人对这片荒凉之地的凶残统治。",kw={"血怒血脉","血怒撕裂者","焦炭谷","鹰身人","马格兰","石爪山脉","烈日石居"},ang={["faction:Horde"]="确保烈日石居周边的安全，对于保护这座坐落在充满争端的石爪山脉深处的部落避风港至关重要。",["race:Tauren"]="石爪山脉满目疮痍的景象让牛头人感到痛苦，而除掉凶残的鹰身人女王，能让像马格兰这样的当地长者重新将心思投入到和谐与疗愈之中。"},sec={{t="击杀女族长",b="在焦炭谷边缘猎杀那些弱小的鹰身人只能给烈日石居带来暂时的喘息。马格兰认为，要遏制她们的侵略行为，唯一持久的方法就是除掉她们的女族长——血怒撕裂者。鹰身人们视她为女王，并直接听命于她，在崎岖的西侧山脊上展现出残忍的协调性和大胆的攻势。"},{t="大地归于平静",b="一旦血怒撕裂者倒下，并将她的尸骸作为证明带回，烈日石居所面临的直接威胁便会平息。随着她们的族群女王被消灭，这些失去组织的鹰身人将更容易被阻挡。这场胜利也卸下了马格兰本人心灵上的重担，让他不再时刻保持警惕，从而能回归牛头人追求和谐与平衡的传统之道。"}},faq={{q="谁发布了“血怒血脉”任务？",a="该任务由烈日石居的牛头人首领马格兰发布，你可以在烈日石居内的水池旁找到他。",al={"血怒血脉任务发布者","谁开启血怒血脉","马格兰任务"}},{q="在解锁此次狩猎前，必须完成什么前置任务？",a="你必须完成“鹰身人的威胁”，在那项任务中，马格兰会第一次派你去焦炭谷削减血怒鹰身人的数量。",al={"血怒血脉前置任务","血怒血脉任务条件","鹰身人的威胁后续"}},{q="血怒撕裂者在哪里？",a="她徘徊在焦炭谷西北边缘的岩石山丘上。她有着独特的蓝色皮肤，这使她与族群中的其他鹰身人区别开来。",al={"血怒撕裂者位置","寻找血怒撕裂者","血怒撕裂者刷新点"}},{q="为什么马格兰想杀死血怒撕裂者？",a="马格兰认定血怒撕裂者是引领该族群进行凶残领土扩张的女王。杀掉她可以瓦解她们的领导核心，并永久削弱她们对焦炭谷的控制。",al={"为什么要杀血怒撕裂者","焦炭谷鹰身人领袖背景","马格兰动机"}},{q="血怒撕裂者的死亡如何影响烈日石居的牛头人？",a="她的死让马格兰获得内心的平静，使他从挥之不去的愤怒和对即将到来的攻击的恐惧中解脱出来，这样他就可以将重心重新转向治愈这片土地。",al={"石爪山脉鹰身人威胁背景","血怒撕裂者死后会发生什么","马格兰的反应"}},{q="从烈日石居前往焦炭谷最快的路径是什么？",a="烈日石居后方有一条直接通往山上的小径，可以绕过石爪山脉蜿蜒的大路，直达焦炭谷。",al={"如何从烈日石居去焦炭谷","烈日石居后路","焦炭谷近路"}}},fx={["174da5a4"]={q="血怒撕裂者的遗体有什么用？",a="大地缚灵马格兰索要血怒撕裂者的遗体，只是为了证明你完成了任务。鹰身人女王从焦炭谷深处指挥血怒鹰身人。马格兰需要确凿的证据，确认她确实已经伏诛，才能安心相信烈日石居面临的威胁已经消除。",al={"血怒撕裂者遗体的用途","为什么要保留鹰身人遗体","血怒遗体的用途"}},["0ac0712d"]={q="血怒撕裂者是谁？",a="血怒撕裂者是血怒鹰身人的首领和族母，她们栖息在焦炭谷西部的山丘间。她的族群视她为女王，由她指挥这些凶残的生物威胁石爪山脉。即使部落努力削减她们的数量，她也确保这股侵略势头持续下去。",al={"血怒鹰身人首领是谁","血怒撕裂者背景","血怒女王"}}},fp="19,275,19.400.0,18.386.0,40.138.0,60.141.0,34.148.0,44.195.0,72.172.1,74.159.0"}
P.entries["quest:6284"] = {n="贝瑟莱斯",s="“蜘蛛恐惧症”是一个部落悬赏任务，目标是贝瑟莱斯——一只盘踞在石爪山脉南部、古老而巨大的掠食者。这份悬赏张贴在狂风峭壁附近的一处路边公告牌上，指引冒险者进入希塞尔山谷，并为烈日石居的马格兰带回这只蜘蛛女王的牙齿。终结她的统治能让山路对夜间行者来说更加安全。",h="“蜘蛛恐惧症”是一个部落悬赏任务，目标是贝瑟莱斯——一只盘踞在石爪山脉南部、古老而巨大的掠食者。这份悬赏张贴在狂风峭壁附近的一处路边公告牌上，指引冒险者进入希塞尔山谷，并为烈日石居的马格兰带回这只蜘蛛女王的牙齿。终结她的...",kw={"蜘蛛恐惧症","贝瑟莱斯","悬赏","马格兰","希塞尔山谷","蜘蛛","石爪山脉","烈日石居","蛛网小径"},ang={["class:Hunter"]="在希塞尔山谷的阴影峭壁中追踪这只难以捉摸的巨大蛛形纲生物，是山地追踪能力的一次真正考验。",["faction:Horde"]="清除贝瑟莱斯能够稳定通往烈日石居的交通，保护部落在石爪山脉中央峭壁的关键据点。",["race:Tauren"]="马格兰身上带着贝瑟莱斯毒液留下的痛苦伤疤，使得这次狩猎也成为了向大地之子致敬并提供协助的任务。"},sec={{t="路边的警告",b="在狂风峭壁以南的主干道上，旅行者会发现一张饱经风霜的通缉令，警告着西方的危险。希塞尔山谷和蛛网小径已被八条腿的掠食者完全占领。在这张蛛网威胁的中心，盘踞着贝瑟莱斯，一只异常巨大、有着橙色外壳的蜘蛛。她指挥着自己的族群，并在日落后伏击任何胆敢偏离道路的人。"},{t="马格兰的冤屈",b="这份针对贝瑟莱斯的悬赏由烈日石居的牛头人马格兰提出。马格兰与这位女王有一笔私人旧账要算：在之前的一次遭遇中，他曾被贝瑟莱斯巨大的两英尺长的牙齿击中，险些丧命。虽然他设法击退了她并一瘸一拐地逃到了安全地带，但留下的伤口时刻提醒着他峡谷阴影中潜伏的危险。通过让冒险者带回贝瑟莱斯的牙齿，马格兰希望能确保通道的安全，让往返于烈日石居的贸易和旅行不再受到恐惧的威胁。"}},faq={{q="“蜘蛛恐惧症”任务从哪里开始？",a="该任务通过调查石爪山脉主路西侧、狂风峭壁入口以南的一张通缉令开始。",al={"如何领取蜘蛛恐惧症","通缉令贝瑟莱斯位置","如何开启蜘蛛恐惧症任务"}},{q="在哪里可以找到贝瑟莱斯？",a="贝瑟莱斯栖息在希塞尔山谷内，位于路边通缉令的西侧。她和她的蜘蛛后代在满是蛛网的峡谷地面上游荡。",al={"贝瑟莱斯位置","贝瑟莱斯在哪里","寻找贝瑟莱斯蜘蛛"}},{q="马格兰是谁？",a="马格兰是一位位于石爪山脉烈日石居的牛头人。他曾亲身幸免于贝瑟莱斯的毒牙攻击，并发布了悬赏以铲除峡谷中这一威胁。",al={"马格兰是谁","马格兰的角色","谁交还蜘蛛恐惧症任务"}},{q="为什么贝瑟莱斯会对该地区构成如此大的威胁？",a="贝瑟莱斯是一只极其巨大且冷酷的蜘蛛，潜伏在希塞尔山谷和邻近的蛛网小径中。她和她的族群在夜幕的掩护下捕食旅行者，威胁着任何试图前往烈日石居的人。",al={"为什么要杀贝瑟莱斯","贝瑟莱斯做了什么"}},{q="领取悬赏需要什么证明？",a="你必须杀死贝瑟莱斯并割下她那巨大的两英尺长的牙齿。将贝瑟莱斯的牙齿交给烈日石居的马格兰即可完成悬赏。",al={"贝瑟莱斯的证明","贝瑟莱斯任务物品","贝瑟莱斯掉落什么"}},{q="联盟可以接取这个任务吗？",a="不能。这份通缉令奖励的是烈日石居（一个部落营地）的马格兰，因此“蜘蛛恐惧症”是部落专属任务。",al={"联盟能做蜘蛛恐惧症吗","联盟蜘蛛恐惧症任务"}}},fx={["28337efe"]={q="为什么要悬赏贝瑟莱斯？",a="贝瑟莱斯和她的蛛群已经占据希塞尔山谷，夜间捕食沿附近小路行走的无辜旅人。大地缚灵马格兰本人曾遭她袭击，被她的毒牙所伤，险些丧命。他张贴悬赏，是为了铲除这项威胁，让旅人能够安全抵达烈日石居。",al={"为什么要杀贝瑟莱斯","为什么马格兰想让贝瑟莱斯死","贝瑟莱斯悬赏原因"}},["4849c04d"]={q="贝瑟莱斯的牙齿有什么用？",a="这颗毒牙是巨型蜘蛛覆灭的确凿证据。大地缚灵马格兰要求你带回这件带毒的战利品，之后才会给你悬赏奖励，并宣布你是森林的勇士。",al={"贝瑟莱斯的牙齿有什么用","为什么要收集贝瑟莱斯的牙齿","牙齿有什么用"}},["9c85495e"]={q="为什么大地缚灵马格兰需要冒险者去猎杀贝瑟莱斯？",a="马格兰曾亲自尝试对付这只巨型蜘蛛，结果险些丧命，还因她的毒咬留下了久不愈合的伤口。他在烈日石居养伤时，沿路张贴了公开悬赏，希望有本领的猎手能完成他未能做到的事。",al={"为什么马格兰不杀贝瑟莱斯","为什么是我去对付蜘蛛","为什么要雇佣冒险者"}}},fp="13,392,20.398.0,27.556.0,41.169.0,29.162.0,27.200.0,45.237.0,43.162.0,40.153.0"}
P.entries["quest:6285"] = {n="返回西部荒野",s="“回到刘易斯处”是新手信使飞行任务的最后一程，将从暴风城急需的盔甲直接运送到哨兵岭。在受托于邓加尔·长饮并带上奥斯瑞克的箱子后，信使们骑着狮鹫飞越艾尔文森林和西部荒野的天空，为身陷苦战的人民民兵补充物资。",h="“回到刘易斯处”是新手信使飞行任务的最后一程，将从暴风城急需的盔甲直接运送到哨兵岭。在受托于邓加尔·长饮并带上奥斯瑞克的箱子后，信使们骑着狮鹫飞越艾尔文森林和西部荒野的天空，为身陷苦战的人民民兵补充物资。",kw={"邓加尔·长饮","飞行航线","狮鹫","奥斯瑞克","奥斯瑞克的箱子","人民民兵","军需官刘易斯","哨兵岭","索尔","西部荒野"},ang={["class:Warrior"]="每一箱飞往哨兵岭的胸甲和胫甲，都意味着又多了一名能够抵挡迪菲亚匪徒攻击的民兵战士。",["faction:Alliance"]="在暴风城和像哨兵岭这样的偏远定居点之间建立狮鹫航线，对于维系日益分裂的王国至关重要。",["race:Dwarf"]="王国的空中交通依靠狮鹫——这种矮人的古老坐骑——从邓加尔·长饮位于首都的巢穴飞往西部荒野的索尔处。"},sec={{t="空中的生命线",b="西部荒野正逐渐脱离王国的掌控，受到迪菲亚潜行者、贪婪的豺狼人和机械收割机的围攻。由于陆路补给线受到骚扰，道路对于单行的马车来说过于危险，飞行管理员网络提供了一条至关重要的生命线。奥斯瑞克，一位位于暴风城 Old Town 的护甲商，准备了一箱沉重的盔甲，旨在支援哨兵岭受挫的人民民兵志愿者。"},{t="狮鹫的习性",b="狮鹫是极其忠诚且训练有素的野兽，但驾驶它们穿越各地需要建立一定的熟悉度。正如邓加尔·长饮向新手信使解释的那样，虽然狮鹫本能地知道如何飞回它们在暴风城的首都巢穴，但只有当旅行者亲自拜访过目的地的飞行管理员后，它们才会载着骑手前往遥远的前哨站。在之前与哨兵岭的索尔报到后，边境之上的天空便为快速运输敞开了大门。"},{t="民兵的补给",b="抵达哨兵岭后，运送的箱子由军需官刘易斯接收，他是负责为格里安·斯托曼的志愿军装备物资的军官。刘易斯立即着手将盔甲分发给边境守卫者。对于哨兵岭而言，与首都之间可靠的空中联系意味着坚守防线与被迪菲亚潜行者彻底淹没之间的区别。"}},faq={{q="奥斯瑞克的箱子里有什么？",a="箱子里装有由暴风城护甲商奥斯瑞克准备的新制造的盔甲。哨兵岭的人民民兵迫切需要这些物资，他们缺乏标准的皇家供给，只能依靠捐赠和私人运输来装备他们的志愿战士。",al={"奥斯瑞克的箱子内容","箱子里有什么","我要运送什么"}},{q="军需官刘易斯是谁？",a="军需官刘易斯是人民民兵的补给军官，驻扎在哨兵岭的塔楼旁。他负责管理在西部荒野对抗迪菲亚潜行者的志愿守卫者的口粮、装备和武器。",al={"刘易斯 西部荒野","军需官刘易斯的职责","刘易斯是谁"}},{q="邓加尔·长饮是谁？",a="邓加尔·长饮是暴风城的资深人类狮鹫管理员，位于首都 Trade District 的巢穴中。他负责监管王国的空中信使和客运航线。",al={"邓加尔 暴风城","暴风城狮鹫管理员","暴风城飞行管理员"}},{q="为什么狮鹫只飞往你去过的地方？",a="根据邓加尔的说法，狮鹫经过天性训练可以笔直飞回首都，但在将骑手运送到像哨兵岭索尔的站点这样的偏远边境巢穴之前，它们依赖于已建立的航点和个人的熟悉度。",al={"狮鹫飞行规则","飞行航线如何运作","为什么要先拜访索尔"}},{q="索尔是谁？",a="索尔是驻扎在西部荒野哨兵岭的飞行管理员。他照料着前哨站的狮鹫，并接收从暴风城抵达的空中信使。",al={"索尔 西部荒野","哨兵岭狮鹫管理员","飞行管理员索尔"}},{q="为什么暴风城不能直接派皇家马车运送补给？",a="连接艾尔文森林和西部荒野的道路受到迪菲亚潜行者、河爪豺狼人和盗贼的严重骚扰。陆路补给车队面临被伏击和抢劫的风险，因此空中狮鹫航线要快得多，也安全得多。",al={"为什么要使用狮鹫","为什么不用陆路运输","西部荒野的道路"}}},fp="15,186,17.412.0,20.433.0,24.362.0,29.255.0,27.216.0,24.170.0,58.226.0,12.142.0,57.210.0"}
P.entries["quest:629"] = {n="暗礁海",s="格罗姆高营地的肯维雷正在寻找一块位于野人海岸深处的远古石碑碎片。这座被称为暗礁海的沉没之城中盘踞着极具攻击性的鱼人，并记载着格里雷克的传奇历史，暗矛巨魔部族希望将其珍藏在奥格瑞玛。",h="格罗姆高营地的肯维雷正在寻找一块位于野人海岸深处的远古石碑碎片。这座被称为暗礁海的沉没之城中盘踞着极具攻击性的鱼人，并记载着格里雷克的传奇历史，暗矛巨魔部族希望将其珍藏在奥格瑞玛。",kw={"暗矛","格里雷克","格罗姆高营地","肯维雷","鱼人","野人海岸","荆棘谷","石碑碎片","暗礁海"},ang={["faction:Horde"]="帮助肯维雷为奥格瑞玛找回这件遗物，能够加强部落与暗矛部族之间的信任纽带。",["race:Troll"]="对于暗矛部族而言，找回这块碎片能让他们的古老传统以及对伟大英雄格里雷克的崇敬在奥格瑞玛的新家园中得以延续。"},sec={{t="沉没的传说",b="在格罗姆高营地的西北方，很久以前一场剧烈的地震震碎了大地，导致一座远古巨魔城市滑入了野人海岸的水下。如今这里被称为暗礁海，被洪水淹没的废墟中爬满了敌对的鱼人，它们会袭击任何胆敢靠近的人。在废墟深处的海床上，立着一块巨大的石碑，上面刻着巨魔英雄格里雷克的生平故事，对于暗矛部族来说，这段记忆是神圣的。"},{t="奥格瑞玛的纪念品",b="由于这座完整的纪念碑实在太过巨大，无法从深海中搬运出来，肯维雷请求你从石碑上敲下一块碎片。他打算将这块碎片带回奥格瑞玛，并将其供奉在神圣的地方，这样暗矛部族就不会忘记格里雷克的伟力和荣誉。"}},faq={{q="暗礁海位于何处？",a="暗礁海位于荆棘谷格罗姆高营地西北方的野人海岸水下。",al={"暗礁海位置","暗礁海在哪里","如何找到暗礁海"}},{q="为什么肯维雷想要石碑碎片？",a="这块石碑保留了巨魔英雄格里雷克的神圣传说。肯维雷计划将碎片带回奥格瑞玛并放置在神圣的地点，以便暗矛部族能在他们的新家园中缅怀先祖。",al={"为什么要获取石碑碎片","石碑碎片的用途","为什么格里雷克石碑"}},{q="暗礁海的古城发生了什么事？",a="很久以前，一场剧烈的地震震撼了野人海岸，导致整座巨魔城市沉入了海浪之下。",al={"暗礁海发生了什么","暗礁海是如何沉没的","沉没的巨魔城市历史"}},{q="现在的暗礁海里有什么生物？",a="敌对的鱼人已在沉没的废墟中安家，并会攻击任何靠近这座沉没之城的人。",al={"暗礁海里的怪物","暗礁海的敌人","谁住在暗礁海"}},{q="谁是格里雷克？",a="格里雷克是一位传奇的巨魔英雄，他的事迹刻在野人海岸下方的沉没石碑上，被暗矛部族视为神圣。",al={"谁是格里雷克","格里雷克背景故事","英雄格里雷克"}},{q="为什么要拿碎片而不是整块石碑？",a="海床上的雕刻纪念碑实在太庞大了，无法从废墟中打捞上来，因此取下一块破碎的残片是将这份传说带回奥格瑞玛的唯一可行办法。",al={"为什么只要碎片","可以带走整块石碑吗","带走整块石碑"}}},fp="13,292,14.444.0,24.287.0,31.108.0,42.215.0,51.122.0,41.112.0,15.143.0,50.185.0"}
P.entries["quest:63"] = {n="水之召唤",s="这一至关重要的试炼指引萨满祭司从贫瘠之地出发，跨越无尽之海，前往饱受摧残的银松森林海岸。为了赢得与水之灵沟通的资格，试炼者必须直面一个腐化的元素，并净化一座被天灾瘟疫所污染的古老海岸神龛。",h="这一至关重要的试炼指引萨满祭司从贫瘠之地出发，跨越无尽之海，前往饱受摧残的银松森林海岸。为了赢得与水之灵沟通的资格，试炼者必须直面一个腐化的元素，并净化一座被天灾瘟疫所污染的古老海岸神龛。",kw={"永恒之泉火盆","布莱恩","call of water","腐化显像","水之先知伊斯伦","瑟伯切尔","银松森林","水之图腾"},ang={["class:Shaman"]="这一仪式证明了萨满祭司不仅是风暴的召唤者，更是破碎之地的治愈者，肩负着净化精神腐化的重任。",["faction:Horde"]="前往银松森林的旅程，迫使来自卡利姆多的兽人和牛头人亲眼目睹了他们的被遗忘者盟友所面临的残酷、饱受瘟疫蹂躏的苦难。"},sec={{t="跨海朝圣",b="在隐士布莱恩的指引下收集到纯净之水后，萨满祭司回到了位于贫瘠之地海岸的水之先知伊斯伦身边。随后，伊斯伦交给了试炼者一项更为艰巨的任务：将这种净化过的精华带过海洋，送往银松森林那片闹鬼的海岸，那里位于被遗忘者避难所——瑟伯切尔的西侧。"},{t="净化永恒之泉",b="被选中的圣所是永恒之泉火盆，这是一个古老的元素焦点，其水域在洛丹伦瘟疫的弥漫侵蚀下变得扭曲而充满敌意。驻守于此的水之灵已变得沉默且狂暴。通过击败束缚在那里的腐化显像，并将它的护腕与最纯净的水一同献给火盆的火焰，萨满祭司便能打破瘟疫的束缚，召唤出一只未受玷污的潮汐之灵。"}},faq={{q="为什么萨满祭司必须远赴银松森林？",a="水之先知伊斯伦要求萨满祭司证明他们有能力掌控腐化，而不仅仅是学习如何保持宁静。瑟伯切尔西侧的海岸神龛已沦为洛丹伦瘟疫的牺牲品，这给予了试炼者一个机会去治愈元素圣所，并唤醒那些拒绝与其他任何人沟通的水之灵。",al={"为什么要前往银松森林","为什么要跨海旅行","银松森林水之任务的原因"}},{q="使用永恒之泉火盆会发生什么？",a="将击败的元素护腕与剩余的最纯净的水一同置于火焰中，会触发伊斯伦传授的净化仪式。噼啪作响的祭品会净化当地的水池，并召唤出一只纯净的水之显像，它将乐于赐予你祝福。",al={"永恒之泉火盆事件","火盆的作用","如何净化水池"}},{q="是谁在腐化银松森林的水之神龛？",a="水源受到了洛丹伦沦陷王国中挥之不去的弥漫瘟疫所扭曲。从山丘渗下的腐化玷污了当地的泉水，并使原生的水之灵扭曲成了狂暴、充满敌意的恶魔。",al={"谁腐化了神龛","为什么显像会被腐化","银松森林水之腐化"}},{q="完成这项试炼后你能得到什么？",a="净化永恒之泉火盆后，你便能与一只纯净的水之灵进行沟通。将净化的证据带回贫瘠之地交给水之先知伊斯伦，最终就能获得你的水之图腾，并完成漫长的Call of Water试炼。",al={"call of water奖励","如何解锁水之图腾","我能得到什么"}},{q="神龛具体在哪里？",a="神龛坐落在银松森林的西侧海岸线上，就在瑟伯切尔以西的腐化山脊上方。",al={"永恒之泉火盆位置","神龛在哪里","银松森林神龛坐标"}},{q="谁是水之先知伊斯伦？",a="水之先知伊斯伦是一位居住在贫瘠之地商旅海岸的牛头人萨满，位于棘齿城以南。她是一位受人尊敬的精神向导，指导年轻的部落萨满完成与水元素调和所需的艰苦仪式。",al={"谁是伊斯伦","水之先知伊斯伦背景","贫瘠之地水之训练师"}}},fp="13,178,27.268.0,23.373.1,66.227.0,51.207.0,49.174.0,48.226.0,36.107.0,23.214.0"}
P.entries["quest:630"] = {n="瓶中信",s="响应了一次来自海洋的求救后，你在荆棘谷海岸外一座孤岛上发现了被锁链囚禁的普巴尔公主。巨猿穆克拉大王统治着当地的野兽，并囚禁了她。你需要击败它才能拿到解开锁链的钥匙。",h="响应了一次来自海洋的求救后，你在荆棘谷海岸外一座孤岛上发现了被锁链囚禁的普巴尔公主。巨猿穆克拉大王统治着当地的野兽，并囚禁了她。你需要击败它才能拿到解开锁链的钥匙。",kw={"加基森群岛","穆克拉大王","普巴尔公主","锁链钥匙","天鬃","荆棘谷"},sec={{t="岛上的囚犯",b="沿着漂流瓶中的信息指引，你直接找到了被沉重锁链强行囚禁的普巴尔公主。天鬃大猩猩穆克拉大王统治着岛上徘徊的生物，并监视着对她的囚禁。普巴尔相信你有能力对抗这只可怕的猿猴，并夺回解开她束缚所需的钥匙。"},{t="东南方的野兽",b="普巴尔提到，经常能听到她的俘获者在岛屿东南侧徘徊。与穆克拉大王对峙绝非易事，但击败它是夺取锁链钥匙并确保普巴尔获救的唯一途径。"},{t="拯救与感激",b="带回锁链钥匙后，普巴尔公主从囚禁中获得了解放，免受了她所认为的奇耻大辱。虽然她没有能力让你完全加入她的部族，但她还是为你展现出的勇气献上了一份谢礼。"}},faq={{q="普巴尔公主是谁？",a="普巴尔公主是一位部族俘虏，被铁链锁在荆棘谷海岸外的一座岛屿上。在发出漂流瓶求救信息后，她一直在等待着有胆识的人来击败俘获者并解开她的锁链。",al={"普巴尔","普巴尔是谁","普巴尔公主背景故事"}},{q="是谁囚禁了普巴尔公主？",a="她是被天鬃大猩猩穆克拉大王所囚禁的，这只巨大的猿猴统治着岛上周围的野兽。",al={"谁俘虏了普巴尔","普巴尔的俘获者","穆克拉大王俘虏"}},{q="穆克拉大王在哪里？",a="普巴尔公主提到，经常能听到穆克拉大王在岛屿东南侧徘徊。",al={"穆克拉在哪里","穆克拉位置","寻找穆克拉大王"}},{q="解救普巴尔公主需要什么？",a="你需要击败穆克拉大王并找到她的锁链钥匙，然后将其带回以解开束缚她的锁链。",al={"普巴尔锁链钥匙","如何解救普巴尔","解救普巴尔公主的钥匙"}},{q="这一步骤在故事中处于什么位置？",a="这紧接在漂流瓶中的原始求救信息之后，是与穆克拉大王直接对峙，以解救普巴尔公主脱离锁链束缚的关键环节。",al={"漂流瓶任务链","漂流瓶第二部分","普巴尔任务线"}}},fp="19,264,21.348.0,26.231.0,25.243.1,23.220.0,34.118.0,26.116.0,39.114.0,38.148.0"}
P.entries["quest:6301"] = {n="生生不息",s="“重生之环”是部落的一项任务，由烈日石居的塔姆拉·荒原委派，要求收集暗色湖岸边稀有的盖亚之种。面对工业贪婪和石爪山脉战火造成的惨重代价，塔姆拉感到痛心疾首。她试图利用萨满之力为这些坚韧的种子祈福，以恢复山脉被破坏的土壤。这是旨在治愈这片伤痕累累的荒野的修复工作中，至关重要的第一步。",h="“重生之环”是部落的一项任务，由烈日石居的塔姆拉·荒原委派，要求收集暗色湖岸边稀有的盖亚之种。面对工业贪婪和石爪山脉战火造成的惨重代价，塔姆拉感到痛心疾首。她试图利用萨满之力为这些坚韧的种子祈福，以恢复山脉被破坏的土壤。...",kw={"焦炭谷","重生之环","大地母亲","盖亚之种","暗色湖","新生命","石爪山脉","烈日石居","塔姆拉·荒原"},ang={["class:Druid"]="德鲁伊会赞赏这种对自然循环和种子培育的共同关注，因为恢复贫瘠土地的行动与塞纳里奥议会的职责不谋而合。",["class:Shaman"]="塔姆拉的努力体现了萨满修复生态失衡的召唤，证明了灵魂和大地母亲能够修复工业掠夺所造成的破坏。",["race:Tauren"]="对于舒哈鲁人来说，治愈石爪山脉受伤的土壤是向大地母亲尽的一种精神义务，以回应鲁莽的伐木和阵营战争所造成的破坏。"},sec={{t="伤痕累累的荒野",b="石爪山脉的山峰承受着商业开发和连绵战火所留下的深深创伤。在疯狂的伐木行动和敌对阵营的冲突之间，大片的森林已被烧焦、砍伐殆尽，或化为灰烬。对于驻扎在烈日石居的牛头人来说，亲眼目睹自然世界如此迅速地毁灭是一种极大的痛苦。与其仅仅为了守住阵地而战，像塔姆拉·荒原这样的萨满更着眼于古老的自然秩序，努力践行大地母亲的复苏循环。"},{t="暗色湖的种子",b="想要让贫瘠的土地恢复生机，就需要非凡的生命力，而塔姆拉在暗色湖周围发现的稀有盖亚之种正具备这种力量。该湖位于烈日石居以北，其湖岸边孕育着这些坚韧的种子荚。尽管周围地区危机四伏，但这些种子却拥有石爪山脉独有的韧性。一旦回收，塔姆拉就会将祖先的萨满祝福灌注到每一粒种子中，唤醒它们潜藏的力量，为接下来的工作加速生长。"}},faq={{q="收集盖亚之种的目的是什么？",a="盖亚之种拥有非凡的自然生命力，这使它们非常适合用于修复荒芜的土地。塔姆拉·荒原收集它们是为了用大地母亲的祝福和萨满力量对其进行加持，让它们能够迅速发芽，并补充石爪山脉因工业和战争而遭到破坏的地区。",al={"为什么要盖亚之种","盖亚之种的用途","重生之环的目标"}},{q="盖亚之种在哪里？",a="盖亚之种散落在暗色湖的岸边，该湖位于石爪山脉的烈日石居正北方。它们静静地躺在湖泊周围的水边泥土中。",al={"盖亚之种位置","哪里找盖亚之种","暗色湖种子"}},{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是一位居住在烈日石居的牛头人萨满。由于战火和伐木集团对石爪山脉造成的森林砍伐与破坏，她深感痛苦，因此致力于通过大地母亲的祝福来治愈这片土地。",al={"塔姆拉是谁","塔姆拉·荒原背景"}},{q="种子归还后塔姆拉会做什么？",a="在收到十颗盖亚之种后，塔姆拉会开始诵读神圣的咒语，将萨满能量注入种子，激发它们潜在的自然生长力，以便将它们种植在受灾地区。",al={"种子会怎样","重生之环交任务"}},{q="“重生之环”之后的任务是什么？",a="完成“重生之环”后，可以直接接到任务“新生命”，届时被赋予力量的种子将被带到荒凉的焦炭谷，开始重新培育植被。",al={"重生之环后续","重生之环后的任务","重生之环之后做什么"}},{q="为什么石爪山脉的土地需要治愈？",a="石爪山脉因连绵不断的战争和工业伐木企业的过度砍伐而遭受了严重的环境破坏，留下了难以自然复苏的焦土荒野和伤痕累累的山谷。",al={"石爪山脉为何荒废","石爪山脉发生了什么"}}},fx={a7be4203={q="为什么塔姆拉·荒原要收集盖亚之种？",a="石爪山脉各地因工业贪欲与战争而遭受持续破坏，这让塔姆拉深感痛心。伐木者和战火在大地上留下了伤痕，她相信只有大地之母的治愈之力才能修复如此深重的创伤。她希望通过收集并祝福这些种子，重启自然的再生循环，让受损的荒野重新焕发生机。",al={"塔姆拉的动机","塔姆拉为什么要收集种子","塔姆拉·荒原的理由"}}},fp="16,429,20.546.0,23.520.0,45.309.0,33.224.0,24.255.0,48.196.0,36.166.0,49.232.0"}
P.entries["quest:631"] = {n="萨多尔大桥",s="在一场震撼了湿地北部的毁灭性爆炸发生后，拉格·加玛森请求旅行者在萨多尔大桥的废墟中搜寻一名失踪的矮人侦察兵。黑铁部族对丹莫德发动了残酷的袭击，切断了通信，使当地守军在没有增援的情况下陷入困境。找到老锈锁是揭开破坏活动全貌的第一步。",h="在一场震撼了湿地北部的毁灭性爆炸发生后，拉格·加玛森请求旅行者在萨多尔大桥的废墟中搜寻一名失踪的矮人侦察兵。黑铁部族对丹莫德发动了残酷的袭击，切断了通信，使当地守军在没有增援的情况下陷入困境。找到老锈锁是揭开破坏活动全貌...",kw={"黑铁","丹莫德","加玛森","长须","锈锁","大桥","萨多尔","湿地"},ang={["faction:Alliance"]="萨多尔大桥是连接暴风城、铁炉堡与坚守在阿拉希及希尔斯布莱德的联盟部队的唯一陆路补给走廊。",["race:Dwarf"]="萨多尔大桥的毁灭不仅是对矮人石匠工艺的侮辱，也是黑铁矮人对卡兹莫丹同胞发动的直接打击。"},sec={{t="桥上的雷鸣",b="一场灾难性的爆炸最近摧毁了萨多尔大桥，震碎了连接湿地与阿拉希高地的巨大石桥。当黑铁矮人伏击丹莫德时，驻扎在边境的铜须士兵在破坏中遭受了重创。随着兵力减员和要塞被围，布莱德·长须率领的幸存者被迫针对袭击者进行绝望的防御坚守。"},{t="派往东方的侦察兵",b="为了抢修一条通道并确定向北的道路是否还能使用，布莱德·长须派遣资深侦察兵埃比尼泽·锈锁去检查东侧桥梁。数天过去了，却没有任何报告。由于丹莫德正处于被围困状态，拉格·加玛森和驻军缺乏足够的士兵进入敌方控制的废墟中展开救援远征。"},{t="冷酷的发现",b="冒险进入损毁的桥梁，便能看到黑铁袭击所带来的代价。老锈锁不仅没有带回侦察消息，反而死在了东侧大桥的瓦砾之中。他的尸体以及紧攥在手中的羊皮纸证实了最糟糕的情况：他遭遇了黑铁部族的伏击，而黑铁矮人对这条连接卡兹莫丹与洛丹伦的重要命脉的破坏活动尚未结束。"}},faq={{q="什么是萨多尔大桥？",a="萨多尔大桥是一座巨大的矮人桥梁结构，横跨湿地北部与阿拉希高地之间的裂谷。它是连接卡兹莫丹与北方洛丹伦地区的主要陆路通道。",al={"萨多尔大桥","什么是萨多尔大桥","湿地大桥"}},{q="是谁袭击了萨多尔大桥？",a="黑铁矮人部族袭击了这座大桥以及附近的丹莫德哨所。他们引爆了炸药截断了大桥，使联盟的交通瘫痪，并让铜须守军措手不及。",al={"是谁炸毁了大桥","萨多尔大桥爆炸","谁袭击了丹莫德"}},{q="老锈锁是谁？",a="埃比尼泽·锈锁是为布莱德·长须效力的一名值得信赖的矮人侦察兵。他被派去评估爆炸后东侧大桥的情况，但在任务期间被黑铁部队压制并杀害。",al={"埃比尼泽·锈锁","锈锁是谁","失踪的侦察兵"}},{q="拉格·加玛森在哪里？",a="拉格·加玛森驻扎在饱受战火的丹莫德定居点附近，就在湿地北部的萨多尔大桥南侧。在驻军与铁炉堡失去联系期间，他协助协调防御工作。",al={"拉格·加玛森位置","拉格在哪里","丹莫德任务发布者"}},{q="为什么铁炉堡没有派兵支援丹莫德？",a="袭击的突然性，加上大桥的损毁和丹莫德的被围，导致驻军陷入孤立无援的状态。守军兵力捉襟见肘，无法派出信使或调动部队，只能寄望于过往的冒险者来传递消息。",al={"为什么没有增援","铁炉堡支援湿地","丹莫德增援"}},{q="发现锈锁的尸体后会发生什么？",a="锈锁的遗物中有一份羊皮纸，显示袭击的幕后主使卡姆·深怒在大桥对面藏匿了一批炸药。这开启了一项行动，旨在炸毁这批炸药以免其威胁到剩余的桥体，并最终通过向避难谷地的联盟营地求援来寻求帮助。",al={"锈锁之后的任务","萨多尔大桥后续","萨多尔大桥之后"}}},fx={["60853ee9"]={q="为什么拉格·加玛森要寻找老锈锁？",a="萨多尔大桥发生了一场猛烈爆炸，许多矮人守军在黑铁矮人发动袭击前便已丧生。混乱之中，长须派老锈锁去侦察东桥，确认能否守住或夺回阵地，但几天过去了，仍没有任何消息。拉格·加玛森和幸存者迫切想知道锈锁的下落，以及这座桥是否还能用于防守。",al={"为什么要寻找锈锁","拉格·加玛森的动机","为什么要搜索锈锁"}},["8b9f1c8c"]={q="为什么拉格·加玛森需要冒险者帮忙？",a="丹莫德正遭到黑铁矮人的围攻，幸存的守军已不堪重负。铁炉堡没有派来增援，伤亡还在不断增加，拉格·加玛森和他的士兵们无法从防线上抽出哪怕一名卫兵，派人越过大桥搜索。",al={"为什么拉格·加玛森找我","为什么矮人找不到锈锁","为什么要帮助丹莫德"}}},fp="16,413,21.432.0,17.358.0,14.380.1,25.226.0,30.202.0,21.231.1,31.206.0,43.267.0,46.305.1"}
P.entries["quest:632"] = {n="萨多尔大桥",s="拉格·加玛森指派冒险者去查看老埃本尼泽·锈锁的情况，他是一名被派去视察萨多尔大桥这座巨大石制跨海大桥的侦察兵，在与他失去联络后被派往此处。调查大桥拱门下方的情况揭示了他失踪的真相，以及对北部补给线的威胁。",h="拉格·加玛森指派冒险者去查看老埃本尼泽·锈锁的情况，他是一名被派去视察萨多尔大桥这座巨大石制跨海大桥的侦察兵，在与他失去联络后被派往此处。调查大桥拱门下方的情况揭示了他失踪的真相，以及对北部补给线的威胁。",kw={"阿拉希","黑铁","深怒","埃本尼泽·锈锁","拉格·加玛森","萨多尔大桥","湿地"},ang={["faction:Alliance"]="萨多尔大桥是连接铁炉堡和暴风城与北部联盟据点的大动脉，这使得锈锁的发现对大陆安全至关重要。",["race:Dwarf"]="发现黑铁矮人在灼热峡谷以北如此远的地方活动，证明了他们阴险的渗透触角伸得有多深，这威胁到了铁炉堡的同胞。"},sec={{t="侦察兵的最后一战",b="布莱德·长须最初派遣埃本尼泽·锈锁去监视萨多尔大桥的结构完整性和安全性。当与这名侦察兵的联络中断时，人们立刻担心他遭到了暗算。在拱门下方的凹处进行探索，会发现锈锁已经遇害，他在从阴影中突然发起的残忍伏击中倒下，伏击者是黑铁矮人入侵者。"},{t="深怒的命令",b="从锈锁紧握的手指附近撬出了一份写着“深怒”名字的指令。这绝非简单的抢劫或孤立的边境冲突，这份羊皮纸勾勒出了黑铁矮人旨在破坏大桥的蓄意行动。将这份证据带回给加玛森，将使驻军的姿态从例行搜寻转变为紧急的战时防御。"}},faq={{q="埃本尼泽·锈锁是谁？",a="埃本尼泽“老”锈锁是一名联盟矮人，被派去侦察并守卫萨多尔大桥。他在桥下潜行时被黑铁矮人伏击杀害。",al={"谁是锈锁","老锈锁","埃本尼泽·锈锁"}},{q="谁杀了锈锁？",a="他在萨多尔大桥下遭到黑铁矮人特工的伏击，那些特工执行的是卡姆·深怒发布的指令。",al={"谁杀了锈锁","谁伏击了锈锁","锈锁的尸体"}},{q="在锈锁的尸体上发现了什么？",a="在他紧握的拳头旁放着一张羊皮纸，上面写着《深怒的命令》，记录了黑铁矮人针对这座关键北部大桥的秘密阴谋。",al={"他手里有什么","深怒的命令","锈锁身上的羊皮纸"}},{q="拉格·加玛森是谁？",a="拉格·加玛森是一名驻扎在湿地萨多尔大桥南侧的联盟军官，负责确保矮人领地与北方之间的交通安全。",al={"拉格·加玛森","谁是加玛森"}},{q="为什么萨多尔大桥争夺如此激烈？",a="萨多尔大桥是连接卡兹莫丹矮人领地和湿地，通往阿拉希高地和洛丹伦的唯一陆路大桥。保卫它是联盟后勤的关键。",al={"为什么萨多尔大桥很重要","萨多尔大桥的重要性"}},{q="把命令交给拉格·加玛森后会发生什么？",a="意识到威胁的严重性，拉格·加玛森会派你去摧毁一处储存在萨多尔大桥另一侧阿拉希高地的黑铁矮人炸药库，以挫败他们的破坏行动。",al={"接下来发生什么","萨多尔大桥后续"}}},fx={d453191c={q="为什么必须把锈锁尸体旁的命令带回来？",a="埃比尼泽·锈锁已经无法开口，也不能再传递警告，但他紧握的拳头旁那张羊皮纸表明，黑铁矮人已针对萨多尔大桥展开行动。若拉格·加玛森不了解这场伏击，也不检查深怒的书面命令，守卫大桥的联盟军队就会对脚下正在发生的破坏活动一无所知。",al={"为什么要报告锈锁尸体的情况","为什么要带回深怒的命令","锈锁尸体的缘由"}}},fp="16,322,21.357.0,17.380.1,27.191.1,21.123.1,34.141.1,21.184.0,45.196.0,54.184.1"}
P.entries["quest:6321"] = {n="瑟伯切尔的补给",s="“补给瑟伯切尔”是亡灵卫兵博迪瑞格在银松森林的瑟伯切尔发布的一项后勤任务。为了让当地的亡灵卫兵部队拥有足够的装备来对抗森林中潜伏的野兽和天灾军团，必须通过蝙蝠管理员卡洛斯·拉佐克将一份紧急的武器征用订单送往幽暗城的武器供应商处。",h="“补给瑟伯切尔”是亡灵卫兵博迪瑞格在银松森林的瑟伯切尔发布的一项后勤任务。为了让当地的亡灵卫兵部队拥有足够的装备来对抗森林中潜伏的野兽和天灾军团，必须通过蝙蝠管理员卡洛斯·拉佐克将一份紧急的武器征用订单送往幽暗城的武器供...",kw={"蝙蝠管理员","亡灵卫兵","高顿·温德哈姆","哈德瑞克","卡洛斯·拉佐克","博迪瑞格","征用","瑟伯切尔","银松","幽暗城"},ang={["faction:Horde"]="在据点与主城之间建立并维护可靠的飞行网络，是协调各个受争议地区军事防御的根本。",["race:Undead"]="维护像瑟伯切尔这样的前哨站，能确保被遗忘者将势力投射到提瑞斯法林地之外，并为黑暗女王守卫周围的荒野。"},sec={{t="武装前线",b="虽然亡灵卫兵博迪瑞格报告说瑟伯切尔的物资储备相对充足，但银松森林持续不断的消耗导致装备损耗速度惊人。在野兽、游荡的天灾余孽以及好斗的当地威胁的多重压力下，前线装备在战斗中不断损毁或丢失。在执行官哈德瑞克的命令下，博迪瑞格起草了一份直接寄给高顿·温德哈姆的征用订单，这位武器商人就在首都经营业务。如果被遗忘者希望在提瑞斯法林地之外保持他们那脆弱的立足点，确保替换武器和护甲的稳定供应至关重要。"},{t="飞行网络",b="在银松森林那雾气弥漫的道路上徒步运送重要信件和军用物资不仅速度缓慢，而且极易遭到伏击。为了避开这些危险，被遗忘者依靠被捕获并驯养的吸血蝙蝠。将博迪瑞格的征用订单交给蝙蝠管理员卡洛斯·拉佐克，能将地面部队纳入幽暗城更广阔的空中后勤网络，从而建立起将偏远据点与希尔瓦娜斯的首都直接连接起来的空中运输线。"}},faq={{q="博迪瑞格的订单目的是什么？",a="亡灵卫兵博迪瑞格代表执行官哈德瑞克视察了瑟伯切尔的军械库。虽然口粮和一般装备尚可，但仍需要武器来补充在与天灾军团和其他森林威胁的冲突中损毁或丢失的装备。",al={"博迪瑞格为何下令","什么是博迪瑞格的征用订单","补给瑟伯切尔的目的"}},{q="高顿·温德哈姆是谁？",a="高顿·温德哈姆是一位驻扎在幽暗城的武器商人。博迪瑞格特别将这份征用订单寄给他，以满足驻军对新武器的需求。",al={"高顿·温德哈姆是谁","高顿·温德哈姆幽暗城"}},{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻扎在瑟伯切尔的蝙蝠管理员。他负责管理那些用于在洛丹伦各地运送信使、侦察兵和物资的恐惧蝙蝠。",al={"卡洛斯·拉佐克的职责","谁是蝙蝠管理员"}},{q="为什么要用蝙蝠而不是陆路信使？",a="银松森林中到处都是敌对野兽、游荡的天灾军团和其他危险派系。走陆路的信使会面临不断的伏击，因此空中的蝙蝠航线是通往幽暗城最快、最安全的路径。",al={"为何要飞往幽暗城","为何使用蝙蝠"}},{q="瑟伯切尔面临哪些威胁？",a="瑟伯切尔被敌对势力包围，包括残留的天灾亡灵、狼人、野生野兽以及当地的人类派系，这使得他们必须保持时刻战斗的状态，并需要稳定的装备补给。",al={"瑟伯切尔的威胁","为何亡灵卫兵需要武器"}},{q="这项任务接下来会指向哪里？",a="将订单交给卡洛斯·拉佐克会促使他安排直飞幽暗城的运输，征用订单可以直接送达高顿·温德哈姆手中。",al={"下一个任务是什么","补给瑟伯切尔之后"}}},fx={f1c1132b={q="为什么亡灵卫兵博迪瑞格要送交这份补给订单？",a="亡灵卫兵博迪瑞格奉执行官哈德瑞克之命清点库存，确保瑟伯切尔的军备充足。普通物资尚且稳定，但在银松森林与天灾军团及其他徘徊威胁的持续冲突中，卫兵们有许多武器遗失在战场上。为了避免哨所陷入无力自保的境地，博迪瑞格急需将这份采购单送到幽暗城的高顿·温德哈姆手中，以便补充武器。",al={"博迪瑞格为什么要你完成这件事","博迪瑞格的动机","为什么要订购武器"}},ade30847={q="为什么博迪瑞格派你去，而不是亲自送货？",a="博迪瑞格正与执行官哈德瑞克一同值守，维护瑟伯切尔的防御。敌对的天灾军团在周围树林中游荡，每一名亡灵卫兵都必须负责守卫营地周边并坚守阵地。让一位身体健壮的旅人担任信使，既能联系蝙蝠管理员，也不用抽走任何一名士兵离岗。",al={"为什么派我去","博迪瑞格为什么不亲自去","为什么要依靠冒险者"}}},fp="23,328,21.597.0,18.443.0,38.243.0,22.159.0,19.163.0,38.216.0,37.207.0,31.167.0"}
P.entries["quest:6322"] = {n="迈克尔·加勒特",s="Michael Garrett是一个简单的快递任务，连接了幽暗城的贸易与被遗忘者的飞行网络。在收集了由高顿·温德哈姆在Trade Quarter打包的补给品后，你需要将箱子交给蝙蝠管理员Michael Garrett，以安排飞往瑟伯切尔的空中运输。这突显了被遗忘者如何利用训练有素的吸血蝙蝠，将他们的首都与洛丹伦各地的哨站连接起来。",h="Michael Garrett是一个简单的快递任务，连接了幽暗城的贸易与被遗忘者的飞行网络。在收集了由高顿·温德哈姆在Trade Quarter打包的补给品后，你需要将箱子交给蝙蝠管理员Michael...",kw={"蝙蝠管理员","飞行管理员","高顿·温德哈姆","高顿的箱子","michael garrett","瑟伯切尔","银松森林","幽暗城"},ang={["faction:Horde"]="对于从卡利姆多抵达的旅行者来说，被遗忘者的蝙蝠网络是横跨东部王国北部地区的主要快速交通方式。",["race:Undead"]="了解由像Michael Garrett这样的管理员运营的空中补给线，对于维持希尔瓦娜斯在提瑞斯法林地之外的存在至关重要。"},sec={{t="哨站补给",b="在洛丹伦废墟上建立一个新兴王国需要持续的后勤支持。像银松森林中的瑟伯切尔这样的哨站，非常依赖从幽暗城运出的货物、军需品和补给。高顿·温德哈姆在城市的Trade Quarter将必要的野外补给打包成一个箱子，但通过陆路穿过被瘟疫感染的森林运输货物不仅缓慢，而且容易遭到天灾残党或野兽的伏击。"},{t="被遗忘者的羽翼",b="为了避开道路上的危险，被遗忘者依赖由熟练的驯养师饲养和照料的俘获吸血蝙蝠。Michael Garrett在幽暗城的Trade Quarter的栖息处照看这些带翼野兽。将货物交给他，就能确保补给品被绑在蝙蝠身上，直接飞越群山前往银松森林，这也教会了新快递员首都如何与遥远的定居点进行协调。"}},faq={{q="Michael Garrett是谁？",a="Michael Garrett是幽暗城的蝙蝠管理员，驻扎在Trade Quarter。他管理着飞行网络中的吸血蝙蝠，负责安排被遗忘者首都与洛丹伦各地联盟飞行管理员之间的旅行和空中运输。",al={"michael garrett","幽暗城蝙蝠管理员","garrett是谁"}},{q="高顿的箱子里装了什么？",a="该箱子装有由高顿·温德哈姆在Trade Quarter收集的重要物资和野外补给，专门为驻扎在银松森林瑟伯切尔的被遗忘者部队准备。",al={"高顿的箱子","有什么补给","瑟伯切尔箱子"}},{q="为什么要用蝙蝠而不是马车或马匹？",a="从提瑞斯法林地蜿蜒而出进入银松森林的陆路充满了危险，包括游荡的天灾野兽、敌对人类和险恶的地形。通过受过训练的巨型蝙蝠进行空中飞行要快得多，并且可以完全避开地面伏击。",al={"为什么进行蝙蝠飞行","为什么要用蝙蝠","空运补给"}},{q="交给Michael Garrett后，货物会送到哪里？",a="一旦Michael Garrett收到高顿的箱子，货物就会被准备好，由蝙蝠直接飞往驻扎在银松森林瑟伯切尔的蝙蝠管理员处，从而完成整个后勤链。",al={"下一步","michael garrett之后","蝙蝠飞往哪里"}},{q="在幽暗城哪里可以找到Michael Garrett？",a="他位于Trade Quarter的西南部，也是从瑟伯切尔飞来的蝙蝠降落的区域。",al={"garrett在哪里","寻找蝙蝠管理员","幽暗城飞行管理员位置"}},{q="在做这个任务之前需要先去过瑟伯切尔吗？",a="要想在运送货物的同时亲自乘坐蝙蝠，你必须此前与瑟伯切尔的飞行管理员交谈过以解锁航线；否则，你将不得不步行前往那里。",al={"需要瑟伯切尔飞行点","我可以立刻飞行吗"}}},fx={["2851daa3"]={q="为什么高顿·温德哈姆希望你完成这件事？",a="高顿·温德哈姆负责协调送往被遗忘者哨所瑟伯切尔的重要军需。由于他必须留在幽暗城的贸易站管理货物，因此需要你把装好的箱子交给迈克尔·加勒特，以便尽快通过他们的空中信使路线运送出去。",al={"为什么要送高顿的箱子","高顿·温德哈姆的动机","为什么要把箱子送给迈克尔·加勒特"}}},fp="15,424,22.451.0,21.410.0,23.236.0,26.199.0,40.281.0,49.188.0,48.122.0,60.197.0"}
P.entries["quest:6323"] = {n="飞往幽暗城",s="“前往幽暗城”任务旨在向初出茅庐的被遗忘者冒险者介绍部落在洛丹伦的空中飞行网络。信使携带来自饱受战火蹂躏的瑟伯切尔前哨站的武器征用令，搭乘恐惧蝙蝠直飞幽暗城的贸易区，为地区守军补充补给。",h="“前往幽暗城”任务旨在向初出茅庐的被遗忘者冒险者介绍部落在洛丹伦的空中飞行网络。信使携带来自饱受战火蹂躏的瑟伯切尔前哨站的武器征用令，搭乘恐惧蝙蝠直飞幽暗城的贸易区，为地区守军补充补给。",kw={"恐惧蝙蝠","飞行管理员","高顿·温德哈姆","卡洛斯·拉佐克","博迪瑞格的订单","前往幽暗城","瑟伯切尔","trade quarter"},ang={["faction:Horde"]="飞行管理员构成了部落领土扩张不可或缺的连接纽带，将艰苦的荒野跋涉转变为快速的战术部署。",["profession:Blacksmithing"]="向高顿·温德哈姆运送订单，让铁匠们得以一窥洛丹伦的后勤脊梁，在这里，每一件铁器都保持着锋利，时刻准备投入战争。",["race:Undead"]="从银松森林飞往首都，彰显了黑暗女王网络的触角和组织能力，确保了孤立的驻军永远不会与幽暗城的工业脱节。"},sec={{t="银松森林之上",b="在被遗忘者的首都与其前线哨所之间保持通讯畅通，需要快速、可靠的交通方式。卡洛斯·拉佐克是驻扎在银松森林瑟伯切尔的蝙蝠管理员，负责管理训练有素的恐惧蝙蝠，这些蝙蝠负责在瘟疫肆虐的土地上运送信使和补给。由于道路上到处都是敌对野兽、月怒狼人以及天灾军团的残余势力，乘空飞行是确保紧急军事请求能够送达首都的最安全、最快捷的方式。"},{t="武装前线",b="当信使降落在幽暗城繁忙的贸易区后，会将博迪瑞格的装备征用令直接交给高顿·温德哈姆。作为一名致力于效忠黑暗女王的幽暗城武器匠，温德哈姆确保了像瑟伯切尔这样的地区哨所始终配备着干净、随时可用的战备武器。对于正在加固边界以抵御周围敌人的新兴被遗忘者政权来说，维持这些防御枢纽至关重要。"}},faq={{q="这次飞往幽暗城的任务目的是什么？",a="这项任务旨在将亡灵卫兵博迪瑞格从瑟伯切尔发出的正式武器征用令直接送交至幽暗城贸易区的一名武器商人高顿·温德哈姆手中，同时教导新的勇士如何使用被遗忘者的飞行网络。",al={"为什么要前往幽暗城","前往幽暗城任务目标","博迪瑞格的订单用途"}},{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻扎在银松森林瑟伯切尔的蝙蝠管理员。他负责监管被遗忘者所使用的恐惧蝙蝠巢穴，以维持与幽暗城之间的快速交通和通讯。",al={"卡洛斯·拉佐克的职责","瑟伯切尔的蝙蝠管理员是谁"}},{q="高顿·温德哈姆是谁？",a="高顿·温德哈姆是一位位于幽暗城贸易区的被遗忘者武器匠，就在蝙蝠管理员的降落平台附近。他以能让武器保持清洁、锋利并随时供希尔瓦娜斯女王的前线部队使用为荣。",al={"高顿·温德哈姆","高顿·温德哈姆在哪里"}},{q="为什么被遗忘者使用蝙蝠进行交通运输？",a="恐惧蝙蝠是洛丹伦枯萎天空中土生土长的夜行性捕食者。它们提供了在险恶的地表危险之上快速通行的手段，例如野生的狼人、敌对的腐皮豺狼人和天灾军团。",al={"为什么要使用蝙蝠","被遗忘者飞行坐骑"}},{q="完成交付后会发生什么？",a="在收到订单后，高顿·温德哈姆会指引信使去找幽暗城的蝙蝠管理员迈克尔·加勒特，从而建立起一条返回瑟伯切尔的返程飞行路线。",al={"what comes next","前往幽暗城的后续任务"}},{q="恐惧蝙蝠在幽暗城的什么地方降落？",a="恐惧蝙蝠降落在幽暗城贸易区中心位置上方高处的蝙蝠栖木上，可以直接通往城里的工匠和补给商人处。",al={"幽暗城蝙蝠降落点","蝙蝠在哪里降落"}}},fx={d629dc0f={q="为什么卡洛斯·拉佐克希望你完成这件事？",a="卡洛斯·拉佐克是驻扎在瑟伯切尔的飞行管理员，负责管理连接银松森林与首都的空中信使网络。像瑟伯切尔这样的哨所完全依靠稳定的补给线和迅速的通信，才能抵御周围的威胁。你将亡灵卫兵博迪瑞格的装备采购单直接送到幽暗城的武器供应商手中，便能确保守卫王国的前线哨兵得到他们急需的武器和护甲。",al={"为什么要送交博迪瑞格的订单","卡洛斯·拉佐克的动机","为什么要骑乘前往幽暗城"}}},fp="21,294,21.489.0,16.446.0,52.261.0,19.198.0,22.239.0,41.202.0,43.166.0,47.181.0"}
P.entries["quest:6324"] = {n="向博迪瑞格回报",s="“回到博迪瑞格身边”是一个物流任务，旨在完成银松森林与幽暗城之间的快递运输。在将一份急件送达首都后，快递员被委以运送一箱武器的重任，利用被遗忘者的蝙蝠管理员网络，将其送回瑟伯切尔的亡灵卫兵博迪瑞格手中。",h="“回到博迪瑞格身边”是一个物流任务，旨在完成银松森林与幽暗城之间的快递运输。在将一份急件送达首都后，快递员被委以运送一箱武器的重任，利用被遗忘者的蝙蝠管理员网络，将其送回瑟伯切尔的亡灵卫兵博迪瑞格手中。",kw={"蝙蝠管理员","高顿的箱子","卡洛斯·拉佐克","迈克尔·加勒特","博迪瑞格","瑟伯切尔","银松森林","幽暗城"},ang={["faction:Horde"]="这项任务展示了连接幽暗城与北部大陆各偏远哨站的后勤框架。",["race:Undead"]="保持前线驻军的武装对于保卫洛丹伦和巩固希尔瓦娜斯女王初创的疆域至关重要。"},sec={{t="幽暗城的补给线",b="洛丹伦各地的哨站都严重依赖来自幽暗城的定期补给以维持运转。在银松森林的瑟伯切尔，亡灵卫兵哨兵面临着当地狼人、达拉然残党和天灾军团残部的压力。为偏远驻军提供新锻造的军火，对于确保该地区处于被遗忘者的控制之下至关重要。"},{t="被遗忘者之翼",b="蝙蝠管理员迈克尔·加勒特经营着位于幽暗城贸易区的中央栖木，这里是被遗忘者空中旅行的枢纽。虽然蝙蝠会自然返回首都，但骑手在规划前往偏远哨站的航线之前，必须先与像卡洛斯·拉佐克这样的当地管理员协调。将高顿的箱子运送在洛丹伦的天空之上，教会了快递员被遗忘者是如何将他们分散的据点连接在一起的。"}},faq={{q="高顿的箱子里装的是什么？",a="箱子里装的是幽暗城生产的全新武器，以确保驻扎在瑟伯切尔的亡灵卫兵能够装备精良，应对周围的威胁。",al={"高顿的箱子内容物","我正在给博迪瑞格送什么"}},{q="亡灵卫兵博迪瑞格是谁？",a="亡灵卫兵博迪瑞格是一名驻扎在银松森林瑟伯切尔的被遗忘者士兵，负责管理当地驻军的后勤和防御职责。",al={"博迪瑞格","博迪瑞格是谁"}},{q="迈克尔·加勒特是谁？",a="迈克尔·加勒特是驻扎在幽暗城贸易区的被遗忘者蝙蝠管理员，负责协调横跨洛丹伦的飞行路径。",al={"迈克尔·加勒特","幽暗城蝙蝠管理员"}},{q="为什么在飞往某地之前必须与蝙蝠管理员交谈？",a="被遗忘者的蝙蝠会自然知道回到幽暗城中央栖木的路，但外出的飞行需要先与区域管理员建立航线，以确保顺利到达。",al={"飞行路径规则","蝙蝠管理员的工作方式"}},{q="为什么瑟伯切尔的补给如此重要？",a="瑟伯切尔是被遗忘者在银松森林的主要前哨基地。它稳固了他们针对该地区的狼人族群、月怒威胁和达拉然势力的军事存在。",al={"为什么瑟伯切尔很重要","瑟伯切尔的重要性"}},{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻扎在银松森林瑟伯切尔的蝙蝠管理员，管理着连接该哨站与幽暗城的栖木蝙蝠。",al={"卡洛斯·拉佐克","瑟伯切尔蝙蝠管理员"}}},fx={["02244cab"]={q="迈克尔·加勒特为什么想让你办这件事？",a="作为幽暗城的蝙蝠管理员，迈克尔·加勒特负责被遗忘者领地内的空中运输和信使路线。亡灵卫兵博迪瑞格和驻守银松森林瑟伯切尔的士兵急需首都运来的新式武器。加勒特确保这些至关重要的武器通过蝙蝠网络高效运送，以加强暗影女士的边境哨站，抵御附近的威胁。",al={"迈克尔·加勒特为什么要送箱子","加勒特安排返回博迪瑞格的原因","为什么要把箱子送到瑟伯切尔"}},eed737b1={q="迈克尔·加勒特为什么派你去，而不亲自前往？",a="加勒特必须留在幽暗城的蝙蝠栖所照料这些坐骑，并协调进出首都的航班。你是一名能干的信使，正好要返回银松森林，因此把箱子交给你，就能确保货物送达，也不必调走宝贵的飞行管理员或守卫，让他们离开各自的重要岗位。",al={"为什么派我去","加勒特为什么不亲自送","返回博迪瑞格为什么选我"}}},fp="16,292,25.353.0,21.419.0,26.156.0,25.154.0,23.151.0,65.183.0,44.178.0,19.143.0"}
P.entries["quest:633"] = {n="萨多尔大桥",s="这项关键的联盟任务要求勇士们守卫萨多尔大桥上唯一幸存的一座桥梁。在Ebenezer Rustlocke不幸遇害后，拉格·加玛森发现叛徒卡姆·深怒正企图引爆炸药，切断铁炉堡通往北方的生命线。",h="这项关键的联盟任务要求勇士们守卫萨多尔大桥上唯一幸存的一座桥梁。在Ebenezer Rustlocke不幸遇害后，拉格·加玛森发现叛徒卡姆·深怒正企图引爆炸药，切断铁炉堡通往北方的生命线。",kw={"阿拉希高地","dark iron","ebenezer rustlocke","炸药","卡姆·深怒","magni bronzebeard","拉格·加玛森","萨多尔大桥","wetlands"},ang={["faction:Alliance"]="守住大桥对于大陆安全至关重要；如果这个渡口失守，将联盟军队和资源运往阿拉希高地和Lordaeron将变得极其危险。",["profession:Engineering"]="工程师们可以体会到卡姆·深怒的弹药据点所具备的纯粹破坏力，它们是为摧毁巨大的Titan风格矮人石造建筑而建造的。",["race:Dwarf"]="对于铁炉堡的子民来说，保卫萨多尔大桥不仅能保护King Magni通往北方盟友的生命线，还能打击叛变的Dark Iron渗透者。"},sec={{t="阴谋败露",b="在萨多尔大桥的下层结构中发现了Ebenezer Rustlocke的惨状后，一份回收的文件揭露了更黑暗的企图。Dark Iron煽动者卡姆·深怒，这座大桥最初被毁的始作俑者，并未就此罢手。在摧毁了其中一座宏伟的石桥之后，他的破坏网络在阿拉希高地的北部边界处又安放了第二批重型弹药，准备彻底完成破坏。"},{t="拯救生命线",b="萨多尔大桥是将Khaz Modan和暴风城这两个南方王国与战火纷飞的北方领土连接起来的主要陆路通道。为了保护这条路线，拉格·加玛森下令在卡姆·深怒的同谋者部署这些炸药之前，对阿拉希高地的破坏据点进行先发制人的打击。引爆炸药消除了眼前的危险，保留了铁炉堡通往北方的通路，但加玛森仍然极度缺乏防守这一缺口的部队。"}},faq={{q="卡姆·深怒是谁？",a="卡姆·深怒是策划破坏萨多尔大桥的Dark Iron矮人主谋。他不满足于摧毁第一座拱桥，还在阿拉希高地的深渊对岸隐藏了额外的炸药，企图摧毁剩下的大桥。",al={"卡姆·深怒","谁炸毁了萨多尔大桥","萨多尔大桥幕后主谋"}},{q="萨多尔大桥为什么在战略上如此重要？",a="这座大桥是跨越Wetlands和阿拉希高地之间巨大深渊的唯一陆路桥梁。如果被切断，联盟将失去在铁炉堡、暴风城以及他们在Lordaeron北部坚守阵地的盟友之间的主要陆路补给线。",al={"为什么萨多尔大桥很重要","萨多尔大桥背景故事"}},{q="Ebenezer Rustlocke发生了什么事？",a="Ebenezer Rustlocke是一位在桥下深处被谋杀的铁炉堡守卫。正是通过他的调查以及从他的遗体旁回收的文件，拉格·加玛森才发现了卡姆·深怒隐藏的炸药据点。",al={"ebenezer rustlocke之死","rustlocke是谁"}},{q="炸药据点藏在哪里？",a="炸药被藏在大桥另一侧的阿拉希高地边界，位置靠近，足以让卡姆·深怒的同谋者迅速将其运送到尚存的桥梁结构处。",al={"炸药位置","炸药在哪里","补给点位置"}},{q="是谁下令摧毁这些炸药？",a="驻扎在Wetlands一侧萨多尔大桥的矮人军官拉格·加玛森下达了定位并摧毁该据点的命令，以纪念Rustlocke的牺牲并保护剩下的大桥。",al={"谁发布了这个任务","拉格·加玛森"}},{q="弹药被摧毁后会发生什么？",a="虽然眼前的破坏企图被挫败，但拉格·加玛森意识到他的驻军在没有援助的情况下无法长期守住这座受损的大桥。在等待铁炉堡的预备队时，他向避难谷地联盟营地的尼艾丝队长发出了增援请求。",al={"萨多尔大桥之后发生什么","联盟的请求任务"}}},fx={a60c1dfd={q="拉格·加玛森为什么要摧毁炸药？",a="拉格·加玛森从找回的锈锁遗书中得知，卡姆·深怒计划利用桥对岸的一处隐蔽储藏点再次引爆炸药。萨多尔大桥的一处桥段已经被炸毁；如果黑铁阴谋者成功炸毁剩余的桥段，连接卡兹莫丹、洛丹伦和阿拉希高地的重要联盟补给路线就会彻底中断。",al={"拉格·加玛森的动机","为什么要摧毁炸药","萨多尔大桥为什么要摧毁炸药"}},b9ac4adc={q="拉格·加玛森为什么派冒险者去，而不是派自己的卫兵？",a="拉格和桥头堡仅剩的几名矮人守卫已捉襟见肘，他们一边坚守阵地抵御敌人的进攻，一边焦急等待援军。埃比尼泽·锈锁已经死于阴谋者之手，拉格无法从防线上抽调人手潜入阿拉希的敌占区，因此只有你能帮他们避免灾难。",al={"为什么选我","为什么派我去","拉格为什么不派卫兵"}}},fp="16,308,15.456.0,19.482.1,20.252.0,47.268.0,36.222.1,40.195.0,46.196.0,47.287.1"}
P.entries["quest:634"] = {n="请求援助",s="《给联盟的求援信》包含了来自丹莫德幸存矮人守军的一份绝望请求，要求横跨萨多尔大桥向阿拉希高地派遣援军。在驻地遭到黑铁矮人渗透者的屠杀后，这些矮人向驻扎在避难谷地的人类部队寻求援助，却发现联盟已自顾不暇。",h="《给联盟的求援信》包含了来自丹莫德幸存矮人守军的一份绝望请求，要求横跨萨多尔大桥向阿拉希高地派遣援军。在驻地遭到黑铁矮人渗透者的屠杀后，这些矮人向驻扎在避难谷地的人类部队寻求援助，却发现联盟已自顾不暇。",kw={"阿拉希高地","尼艾丝队长","黑铁","丹莫德","布莱德","避难谷地","拉格·加玛森","激流堡","萨多尔大桥"},ang={["faction:Alliance"]="这次交流凸显了联盟在东部王国北部依然处于分裂状态，当地守军各自为战，陷入了孤立无援的绝望战斗中。",["race:Dwarf"]="对于矮人而言，这次任务凸显了像丹莫德这样的北方驻地所遭受的痛苦孤立，证明了即使是长期的人类盟友，也因深陷重围而无力伸出援手。",["race:Human"]="人类旅行者亲眼目睹了尼艾丝队长的苦涩与悲伤，他正面临着在坚守联盟兄弟情谊与为保卫沦陷的激流堡而战之间的抉择。"},sec={{t="深渊彼端的呼喊",b="在丹莫德遭到摧毁且萨多尔大桥被黑铁矮人破坏之后，矮人幸存者在湿地的北缘维持着一个岌岌可危的据点。由于铁炉堡的主力预备队尚未抵达，拉格·加玛森和布莱德·长须将目光投向了北方的阿拉希高地。在得知联盟在避难谷地建立了一个营地后，加玛森派遣了一名信使穿过那座支离破碎的桥梁，恳求尼艾丝队长提供紧急军事援助。"},{t="激流堡的困境",b="当抵达避难谷地时，北方联盟严峻的现实便显露无疑。尼艾丝队长向布莱德·长须的士兵们表示了深切的同情，但他无法抽调哪怕一名战士。激流堡本身已成废墟，被辛迪加潜行者、石拳食人魔和枯木巨魔所淹没。激流堡的幸存守军正全力以赴地收复他们的祖国首都。受制于荣誉与自身绝望的处境，尼艾丝被迫传话回去，告知大桥上的矮人们必须孤军奋战。"}},faq={{q="是谁向避难谷地发出了求援信？",a="拉格·加玛森，驻扎在湿地边界萨多尔大桥被毁的桥头堡附近，代表布莱德·长须及丹莫德的残余守军发出了这份求援信。",al={"谁发出了给联盟的求援信","拉格·加玛森任务","谁在寻求帮助"}},{q="为什么矮人需要避难谷地的帮助？",a="丹莫德遭到黑铁氏族渗透者突如其来的残酷攻击而陷落，这些渗透者还破坏了萨多尔大桥。虽然幸存者们正在等待来自铁炉堡的重兵支援，但他们目前的人数太少，无法独自夺回定居点并守住通道。",al={"为什么需要联盟的帮助","为什么请求避难谷地","丹莫德援军"}},{q="为什么尼艾丝队长拒绝派遣士兵？",a="尼艾丝队长无法抽调任何部队，因为激流堡王国本身已经分崩离析，化为废墟。避难谷地的人类部队正全力投入到从辛迪加、食人魔和森林巨魔手中夺回激流堡的绝望战役中。",al={"为什么尼艾丝不提供帮助","为什么避难谷地拒绝","尼艾丝队长的回答"}},{q="避难谷地在哪里？",a="避难谷地位于阿拉希高地中部的主干道旁，在湿地与阿拉希之间萨多尔大桥通道的北面。",al={"避难谷地位置","尼艾丝队长在哪里","如何找到避难谷地"}},{q="丹莫德发生了什么事？",a="丹莫德被黑铁氏族攻陷并洗劫，他们通过群山渗透进来，切断了南部矮人领地与北方联盟领土之间的陆路通道。",al={"丹莫德背景资料","丹莫德发生了什么","谁袭击了丹莫德"}},{q="尼艾丝队长拒绝请求后发生了什么？",a="尼艾丝队长向布莱德·长须表示遗憾，确认不会有人类援军到来。桥上的矮人幸存者必须依靠自己的智谋、游荡的冒险者以及来自远方铁炉堡的增援。",al={"给联盟的求援信后续","求援信任务后的下一个任务","任务线延续"}}},fx={["0e006c4d"]={q="拉格·加玛森为什么让你送信求援，而不亲自前往？",a="拉格·加玛森和幸存的矮人山地卫士被困在萨多尔大桥摇摇欲坠的据点里。丹莫德已被攻陷，而铁炉堡的援军仍远在途中，他们不能抽出哪怕一个矮人离开岗位，冒险穿越危险地带北上。",al={"为什么选我送联盟求援信","拉格为什么派你去","拉格为什么不能去避难谷地"}}},fp="20,349,22.482.0,24.543.0,36.182.0,48.264.0,47.248.0,31.142.0,26.194.0,56.232.0"}
P.entries["quest:6341"] = {n="泰达希尔的渔业",s="“泰达希尔的馈赠”是由鲁瑟兰村的妮莎·影歌发布的一项初步任务。为了比较岛上鱼类异常庞大的体型和丰富的数量与大陆沿岸鱼类的差异，她准备了一袋鱼骨和鳞片，打算将其跨过海峡运往黑海岸。将这个包裹交给当地的角鹰兽管理员，是跨海前往奥伯丁的第一步。",h="“泰达希尔的馈赠”是由鲁瑟兰村的妮莎·影歌发布的一项初步任务。为了比较岛上鱼类异常庞大的体型和丰富的数量与大陆沿岸鱼类的差异，她准备了一袋鱼骨和鳞片，打算将其跨过海峡运往黑海岸。将这个包裹交给当地的角鹰兽管理员，是跨海前...",kw={"奥伯丁","泰达希尔的馈赠","黑海岸","角鹰兽","莱尔德","妮莎·影歌","鲁瑟兰村","维斯派塔斯"},ang={["faction:Alliance"]="鲁瑟兰和奥伯丁之间的路线是连接暗夜精灵主城与卡利姆多北部其余地区的重要交通动脉。",["race:NightElf"]="对于暗夜精灵旅行者来说，这段旅程标志着从泰达希尔安全的高地，向黑海岸阴影笼罩的大陆海岸过渡的传统路径。"},sec={{t="渔夫的研究",b="在世界之树巨大的枝干下，鲁瑟兰村周围受庇护的水域中栖息着体型惊人且数量庞大的海洋生物。妮莎·影歌观察到当地渔民捕获的丰厚渔获，希望能探明这种生命力是延伸到了古老的大陆海岸，还是仅仅局限于泰达希尔滋养的水域。为了验证她的理论，她准备了一袋鳞片和鱼骨，让跨海峡位于奥伯丁的同行鱼贩莱尔德进行检查。"},{t="安排行程",b="在岛屿枝干与卡利姆多大陆之间的广阔海峡运送货物和旅客，需要可靠的飞行坐骑。妮莎没有选择用小船运送包裹，而是让旅客直接去找村里的角鹰兽管理员维斯派塔斯。将收藏品交给他，旅客就能安排好必要的物流，骑上训练有素的野兽，直接将样本运送到黑海岸的码头。"}},faq={{q="妮莎想要调查什么？",a="妮莎·影歌注意到鲁瑟兰村周围水域捕获的鱼类异常巨大且数量丰富。她想把这些骨头和鳞片样本送到海的另一边，将泰达希尔的渔获与黑海岸大陆沿岸的鱼类进行比较。",al={"妮莎的目标","为什么要比较鱼类","泰达希尔的馈赠任务目的"}},{q="谁在奥伯丁接收这些鱼类样本？",a="这些收藏品是寄给莱尔德的，他是一位驻扎在黑海岸大陆沿岸奥伯丁村的鱼贩。",al={"谁接收妮莎的收集品","黑海岸的莱尔德","奥伯丁鱼贩"}},{q="为什么要将包裹交给维斯派塔斯，而不是直接前往奥伯丁？",a="维斯派塔斯是鲁瑟兰村的角鹰兽管理员。将收藏品交给他可以安排直接的空中运输，让你能够乘坐角鹰兽横跨大海前往黑海岸。",al={"为什么找维斯派塔斯","维斯派塔斯是谁","鲁瑟兰角鹰兽管理员"}},{q="鲁瑟兰村相对于泰达希尔的位置在哪里？",a="鲁瑟兰村位于泰达希尔南部的海平面基座上，通过翡翠传送门与达纳苏斯相连。它是进出世界之树的船舶和角鹰兽的主要沿海避风港和港口。",al={"鲁瑟兰位置","妮莎·影歌在哪里","如何到达鲁瑟兰"}},{q="将收藏品交给维斯派塔斯后会发生什么？",a="维斯派塔斯会收下收藏品并提供后续任务“飞往奥伯丁”，让你骑着角鹰兽飞越海峡，直接抵达黑海岸。",al={"下一步飞往奥伯丁","泰达希尔的馈赠之后","维斯派塔斯做什么"}},{q="这是暗夜精灵离开新手区的任务吗？",a="是的。这个任务线向年轻的暗夜精灵冒险者介绍了飞行点，并引导他们离开岛屿树冠，前往卡利姆多大陆，继续他们在黑海岸的旅程。",al={"离开泰达希尔","10级暗夜精灵任务","前往黑海岸"}}},fp="24,205,19.314.0,17.202.0,36.188.0,47.75.0,77.153.0,62.200.0,55.135.0,58.152.0"}
P.entries["quest:6342"] = {n="飞往奥伯丁",s="这项任务旨在向离开泰达希尔的冒险者介绍暗夜精灵的空中交通网络。在鲁瑟兰村接受了角鹰兽管理员维斯派塔斯的委托后，旅客们将飞越海洋，把一捆硕大的海洋标本送到奥伯丁的莱尔德手中。",h="这项任务旨在向离开泰达希尔的冒险者介绍暗夜精灵的空中交通网络。在鲁瑟兰村接受了角鹰兽管理员维斯派塔斯的委托后，旅客们将飞越海洋，把一捆硕大的海洋标本送到奥伯丁的莱尔德手中。",kw={"奥伯丁","黑海岸","飞行航线","飞往奥伯丁","角鹰兽","莱尔德","奈莎·影歌","鲁瑟兰村","泰达希尔","维斯派塔斯"},ang={["faction:Alliance"]="角鹰兽是联盟在卡利姆多北部的主要空中交通网络，将沿海哨所直接与首都连接起来。",["race:NightElf"]="乘坐角鹰兽飞往奥伯丁，对于从泰达希尔踏上祖先所在大陆的年轻卡多雷来说，是一个标志性的成年礼。"},sec={{t="飞往黑海岸",b="对于许多离开泰达希尔枝干的年轻冒险者来说，鲁瑟兰村标志着避风港与广阔世界之间的分界线。虽然有一艘普通的渡轮往返于这座岛屿避风港和卡利姆多大陆之间，但暗夜精灵同样依赖他们驯养的角鹰兽。受奈莎·影歌之托，旅客们带着一包稀有的鱼类标本，骑上这些长着翅膀的野兽，建立起他们通往黑海岸的第一条飞行航线。"},{t="奇怪的渔获",b="这次运送的东西引起了黑海岸渔民们浓厚的兴趣。莱尔德在奥伯丁码头等待着奈莎的研究成果，当他检查这些渔获时，发现鱼鳞竟有拳头那么大，而颌骨更是比大陆的标本大出近一倍。世界之树底部周围的岛屿水域似乎孕育着变异或异常巨大的生物，这种奇观暗示着泰达希尔本身所蕴含的强大而躁动的力量。"}},faq={{q="这次飞行的目的是什么？",a="这段旅程是一堂关于连接各定居点飞行航线的实践课，同时也负责将鲁瑟兰村附近捕获的异常鱼类研究样本送到奥伯丁的莱尔德手中。",al={"为什么我要飞往奥伯丁","飞往奥伯丁任务目标","为什么要飞行"}},{q="是谁寄送了包裹，里面装的是什么？",a="这个包裹来自渔夫奈莎·影歌。里面装有鲁瑟兰村周边水域的鱼类标本，包括巨大的鱼鳞和一块超大的颌骨。",al={"尼莎的货物","包裹里有什么","谁寄送了包裹"}},{q="为什么泰达希尔的鱼如此巨大？",a="莱尔德注意到那块颌骨的尺寸几乎是正常鱼类的两倍，而鱼鳞则有拳头那么大。与黑海岸的大陆海岸相比，环绕着泰达希尔世界之树的水域似乎孕育着体型异常巨大的野生生物。",al={"为什么鱼体型巨大","鲁瑟兰鱼类尺寸","巨大的鱼鳞"}},{q="维斯派塔斯是谁？",a="维斯派塔斯是驻扎在鲁瑟兰村的角鹰兽管理员。他负责照料暗夜精灵的坐骑，并协调跨越海面飞往卡利姆多大陆的空中旅行。",al={"维斯派塔斯背景故事","谁是角鹰兽管理员"}},{q="莱尔德是谁？",a="莱尔德是一位常驻黑海岸奥伯丁的暗夜精灵渔夫。他研究当地的水生生物，并将大陆的渔获与在泰达希尔附近捕获的渔获进行对比。",al={"莱尔德背景故事","莱尔德是谁","黑海岸的莱尔德"}},{q="不坐飞机能在鲁瑟兰和奥伯丁之间旅行吗？",a="可以。有一艘定期渡轮往返于鲁瑟兰村码头和奥伯丁码头之间，提供了一种除角鹰兽飞行之外的交通方式。",al={"前往奥伯丁的船","前往黑海岸的渡轮","前往奥伯丁的其他方式"}}},fp="19,160,24.351.0,15.314.0,35.133.0,44.159.0,42.195.0,18.153.0,13.158.0,63.142.0"}
P.entries["quest:6343"] = {n="飞回泰达希尔",s="这个任务指引年轻的旅行者从奥伯丁回到鲁瑟兰村，将莱尔德的调查结果交给娜萨·影歌。它是一项入门跑腿任务，旨在教导冒险者如何往返于卡利姆多大陆与泰达希尔之间。",h="这个任务指引年轻的旅行者从奥伯丁回到鲁瑟兰村，将莱尔德的调查结果交给娜萨·影歌。它是一项入门跑腿任务，旨在教导冒险者如何往返于卡利姆多大陆与泰达希尔之间。",kw={"奥伯丁","卡莱斯·月羽","黑海岸","莱尔德","娜萨·影歌","返回娜萨处","鲁瑟兰村","泰达希尔"},ang={["faction:Alliance"]="奥伯丁和鲁瑟兰村构成了至关重要的海上门户，将卡利姆多北部的暗夜精灵定居点与艾泽拉斯各地更广泛的联盟利益连接起来。",["race:NightElf"]="对于第一次离开泰达希尔枝干去冒险的暗夜精灵来说，这次交流标志着他们第一次正式的差事，将新的岛屿避风港与古老的黑海岸大陆连接了起来。"},sec={{t="跨海信使",b="在将娜萨·影歌最初的询问传达给奥伯丁的莱尔德之后，旅行者受托将他的书面观察带回水域另一端。莱尔德注意到黑海岸和泰达希尔海岸之间的渔获存在显著差异，他怀疑伟大的世界之树本身改变了当地的海洋生物。为了回到鲁瑟兰村，冒险者既可以从角鹰兽管理员卡莱斯·月羽那里租借飞行坐骑，也可以登上定期往返于奥伯丁码头的渡轮。"},{t="奇特的赏赐",b="在鲁瑟兰村收到莱尔德的回复后，娜萨对海洋生物的显著差异表现出了极大的兴趣。虽然世界之树附近鱼类的巨大体型为当地渔民带来了直接的好处，但其根本原因在卡多雷之中仍然是一个未解之谜。娜萨决定将这一发现与村民们分享，并满足于目前收获丰富的海产，同时密切关注真正导致这种现象的力量。"}},faq={{q="谁发放和完成这个任务？",a="这个任务由黑海岸奥伯丁的渔夫莱尔德发放。任务在泰达希尔脚下的鲁瑟兰村由娜萨·影歌处交还。",al={"任务发放者","任务交还地点","谁发布任务"}},{q="回到鲁瑟兰村最快的方法是什么？",a="你可以与奥伯丁的卡莱斯·月羽交谈进行快速的角鹰兽飞行，或者走上长长的码头搭乘定期的客运渡轮回到鲁瑟兰村的码头。",al={"如何返回","前往鲁瑟兰村","渡轮或角鹰兽"}},{q="为什么莱尔德要研究这些鱼？",a="莱尔德注意到黑海岸沿岸的渔获与泰达希尔周围收获的鱼类有很大不同。他怀疑世界之树的蓬勃生长和独特的能量正在直接改变周围的野生生物。",al={"为什么研究鱼类","鱼类差异","莱尔德的回复背景"}},{q="娜萨有没有弄清楚为什么这些鱼如此怪异？",a="并不是立刻就弄清楚了。娜萨注意到了这种显著的差异，并认为有必要进行进一步的调查，但目前她满足于与当地村民分享这份报告，并在此期间享受丰盛的渔获。",al={"为什么鱼会变大","泰达希尔鱼类之谜"}},{q="这个任务之前有什么？",a="该任务直接承接“飞往奥伯丁”，该任务指引旅行者从鲁瑟兰村前往黑海岸，将娜萨原本给莱尔德的信送达。",al={"前置任务","上一个任务","飞往奥伯丁"}},{q="这个任务链的目的是什么？",a="除了介绍泰达希尔对当地野生动物的神秘生态影响外，这个运送任务链还是一项通过仪式，教导年轻的暗夜精灵冒险者如何通过船只和飞行管理员在他们的岛屿家园和卡利姆多大陆之间通勤。",al={"为什么要完成这个任务","旅行任务"}}},fp="15,202,26.388.0,16.417.0,36.137.0,51.152.0,31.187.0,48.219.0,29.128.0,40.205.0"}
P.entries["quest:6344"] = {n="尼莎·影歌",s="“内莎·影歌”是一个引导性送信任务，由达纳苏斯的迈德兰努尔提供。它引导初出茅庐的冒险者从世界之树向下前往鲁瑟兰村，去见鱼类商人内莎·影歌。这项任务是将这座树冠之城与下方的海岸和港口连接起来的第一步。",h="“内莎·影歌”是一个引导性送信任务，由达纳苏斯的迈德兰努尔提供。它引导初出茅庐的冒险者从世界之树向下前往鲁瑟兰村，去见鱼类商人内莎·影歌。这项任务是将这座树冠之城与下方的海岸和港口连接起来的第一步。",kw={"奥伯丁","信使","黑海岸","达纳苏斯","迈德兰努尔","内莎·影歌","传送门","鲁瑟兰村","神殿花园"},ang={["faction:Alliance"]="这项任务引入了将孤立的泰达希尔岛与卡利姆多上其余联盟领土连接起来的关键物流网络。",["race:NightElf"]="对于暗夜精灵冒险者来说，这段旅程标志着他们从达纳苏斯宁静的高处，向连通着家园与古老黑海岸的繁忙沿海路线的传统迈进。"},sec={{t="树冠之外的跑腿任务",b="在达纳苏斯，迈德兰努尔一直在关注着寻找工作和目标的旅行者。当鱼类商人内莎·影歌需要将一个包裹送往海对岸的黑海岸时，迈德兰努尔就会把能干的信使指引向海岸方向。虽然许多年轻的暗夜精灵在旅途初期完全待在泰达希尔的枝叶间，但这个简单的请求鼓励他们放眼看向大陆。"},{t="前往码头",b="要到达鲁瑟兰村，需要穿过神殿花园附近城市西侧的闪光树根传送门。传送门穿过世界之树，直达海平面的根部，那里的渔港和角鹰兽栖息地将泰达希尔与卡利姆多的其他地区连接起来。内莎·影歌就在那里从事贸易，准备发往奥伯丁港口的货物。"}},faq={{q="谁提供这个任务？",a="该任务由位于达纳苏斯战士区的迈德兰努尔提供。",al={"任务发布者","如何获取内莎·影歌任务","迈德兰努尔位置"}},{q="我该如何前往鲁瑟兰村？",a="前往达纳苏斯神殿花园的西边。穿过巨大的发光树门，即可立即传送到泰达希尔底部的鲁瑟兰村。",al={"如何到达鲁瑟兰村","鲁瑟兰传送门","离开达纳苏斯"}},{q="内莎·影歌是谁？",a="内莎·影歌是一位驻扎在鲁瑟兰村码头的精灵鱼类供货商。她负责监督泰达希尔与黑海岸大陆之间的货物和包裹运输。",al={"内莎·影歌角色","内莎负责的工作","内莎·影歌npc"}},{q="这个任务链通向哪里？",a="与内莎交谈后会立即开启“泰达希尔的馈赠”，该任务会引导冒险者找到飞行管理员，并提供他们第一次跨越海面飞往奥伯丁的飞行服务。",al={"内莎·影歌后续任务","任务链后续","泰达希尔飞行任务链"}},{q="内莎与玛维·影歌有关联吗？",a="虽然她们都姓影歌，但没有记录表明内莎——一位平凡的码头鱼类商人，与传奇守望者玛维·影歌之间存在任何个人联系。",al={"内莎与玛维的关系","影歌家族","内莎是玛维的亲戚吗"}},{q="为什么这个跑腿任务对年轻的冒险者很重要？",a="它起到了主要的导航指引作用，教会新英雄如何离开泰达希尔的顶端，发现下方的码头，并学会使用角鹰兽飞行点到达卡利姆多大陆。",al={"为什么要完成此任务","任务意义"}}},fp="16,182,26.324.0,23.299.0,22.69.0,35.149.0,24.146.0,33.150.0,37.169.0,51.159.0"}
P.entries["quest:635"] = {n="山中的水晶",s="密斯莱尔坠饰在你手中跳动，一股恳求的意念传入你的脑海，仿佛有人迫切需要你的帮助。幻象向你展示了一颗从阿拉希北部山脉地面升起的闪亮水晶，你感到自己被那个地方所吸引。",h="密斯莱尔坠饰在你手中跳动，一股恳求的意念传入你的脑海，仿佛有人迫切需要你的帮助。幻象向你展示了一颗从阿拉希北部山脉地面升起的闪亮水晶，你感到自己被那个地方所吸引。",kw={"阿拉希高地","水晶","山中的水晶","密斯莱尔坠饰","密斯莱尔碎片","幻象"},sec={{t="无声的恳求",b="当你握住这枚坠饰时，它开始跳动。一股恳求的意念从中传来，仿佛有人正试图联系你并迫切需要你的帮助。随后，一个幻象在你眼前展开：那是阿拉希北部的群山，还有一颗从地面突出的闪亮水晶。你感到自己被那个地方所吸引。"},{t="在水晶处",b="当你找到这颗水晶时，它开始跳动，仿佛有一股活着的生命力被困在其中。"}},faq={{q="是什么开启了这段旅程？",a="这段旅程始于密斯莱尔坠饰。当你握住它时，它会跳动，并且你会感受到来自某位迫切需要你帮助之人的恳求。",al={"如何获得山中的水晶","密斯莱尔坠饰来自哪里","山中的水晶起始"}},{q="幻象将你引向何方？",a="它将你引向阿拉希北部山脉中矗立的一颗闪亮水晶，你感到自己被那个地方所吸引。",al={"水晶在哪里","山中的水晶位置","从幻象中寻找水晶"}}},fp="24,238,13.288.0,14.82.1,25.136.0,27.110.0"}
P.entries["quest:6361"] = {n="一捆兽皮",s="“一捆兽皮”是贫瘠之地的一项入门级运送任务，由十字路口的牛头人加翰·鹰翼发布。他请求旅行者将腌制好的野兽毛皮带过卡利姆多中部，送往雷霆崖进行制皮。这项差事旨在向部落新信使介绍十字路口的双足飞龙管理员及其飞行运输机制。",h="“一捆兽皮”是贫瘠之地的一项入门级运送任务，由十字路口的牛头人加翰·鹰翼发布。他请求旅行者将腌制好的野兽毛皮带过卡利姆多中部，送往雷霆崖进行制皮。这项差事旨在向部落新信使介绍十字路口的双足飞龙管理员及其飞行运输机制。",kw={"安哈努","一捆兽皮","十字路口","迪弗拉克","加翰·鹰翼","制皮","贫瘠之地","雷霆崖","双足飞龙"},ang={["faction:Horde"]="这次运送突显了连接卡利姆多部落基地的后勤工作，依靠像迪弗拉克这样的兽人兽栏管理员来跨越盟军领土之间的地理距离。",["race:Tauren"]="对于牛头人旅行者来说，这项差事代表了游荡在祖先之地贫瘠之地的猎人与定居在雷霆崖巨大台地上的工匠之间持续的合作关系。"},sec={{t="穿越大草原的贸易",b="十字路口是整个贫瘠之地商业与旅行的繁华中心，将兽人、巨魔和牛头人连接在干旱的平原上。猎人们不断地从大草原游荡的野兽身上采集毛皮和肉，但当地哨所缺乏就地加工所有原材料的设施。加翰·鹰翼收集区域狩猎得来的毛皮，并依靠路过的旅行者将其运往西边的雷霆崖，那里的制皮大师可以为部落制作重要的装备。"},{t="飞上蓝天",b="徒步背着沉重的货物穿过贫瘠之地崎岖的小路，再爬上莫高雷，是一段艰苦的旅程，还要时刻面临野猪人的伏击和捕食者。为了加快贸易速度，加翰指示信使直接去找十字路口的双足飞龙管理员迪弗拉克。将货物托付给迪弗拉克，并乘坐受过训练的双足飞龙起飞，这展示了将部落分散的定居点连接在一起的重要后勤网络。"}},faq={{q="谁发布了“一捆兽皮”任务？",a="加翰·鹰翼，一位位于贫瘠之地十字路口的牛头人，提供了这个任务。他收集了当地动物的毛皮，并寻找一位可靠的信使帮助将它们运往雷霆崖。",al={"任务发布者","谁发布一捆兽皮","在哪里获取一捆兽皮"}},{q="我应该把一捆兽皮带给谁？",a="你需要将包裹直接带给迪弗拉克，他是驻扎在十字路口站点的兽人双足飞龙管理员。他负责处理十字路口与其他主要部落枢纽之间的空中交通。",al={"任务提交人","兽皮要送到哪里","该找谁对话"}},{q="把毛皮交给迪弗拉克之后会发生什么？",a="迪弗拉克会提供后续任务，指示你骑上双足飞龙，直接将货物运送给安哈努，他是一位在雷霆崖高耸的峭壁之上等待的制皮师。",al={"下一个任务","一捆兽皮后续","后续任务"}},{q="为什么要把这些毛皮送到雷霆崖？",a="加翰·鹰翼与雷霆崖的一位名叫安哈努的同事合作，他将贫瘠之地野兽的生毛皮加工成成品皮甲和商品，供牛头人及其部落盟友使用。",al={"为什么去雷霆崖","安哈努与兽皮","兽皮的作用"}},{q="为什么要使用双足飞龙而不是步行？",a="徒步穿越广阔的贫瘠之地并攀登巨大的雷霆崖台地既危险又缓慢。双足飞龙可以提供快速、安全的交通方式，飞越充满敌意的大草原野生动物和野猪人部族。",al={"为什么要飞往雷霆崖","双足飞龙旅行"}},{q="这需要先有飞行管理员经验吗？",a="这个任务旨在为部落冒险者提供飞行管理员系统的早期介绍，让你熟悉迪弗拉克的站点，以便你能利用双足飞龙进行长距离的区域旅行。",al={"飞行点需求","是否需要飞行点"}}},fp="17,184,24.286.0,19.282.0,38.192.0,42.151.0,46.147.0,48.151.0,40.175.0,49.137.0"}
P.entries["quest:6362"] = {n="飞往雷霆崖",s="这个任务引导年轻的部落冒险者搭乘双足飞龙，完成他们在卡利姆多的首次飞行点航行。旅行者们带着一捆鞣制好的兽皮，从贫瘠之地干燥的十字路口出发，将贵重的皮革补给品直接运送到雷霆崖的高地。",h="这个任务引导年轻的部落冒险者搭乘双足飞龙，完成他们在卡利姆多的首次飞行点航行。旅行者们带着一捆鞣制好的兽皮，从贫瘠之地干燥的十字路口出发，将贵重的皮革补给品直接运送到雷霆崖的高地。",kw={"安哈努","贫瘠之地","一捆兽皮","十字路口","迪弗拉克","赫瓦军需处","飞往雷霆崖","双足飞龙"},ang={["faction:Horde"]="通过双足飞龙进行可靠的空中旅行，对于将贫瘠之地偏远的哨站与杜隆塔尔和莫高雷的主要堡垒连接起来至关重要。",["race:Tauren"]="对于从贫瘠之地归来的年轻牛头人来说，这次飞行让他们可以轻松地直抵他们民族宏伟首府的最高点。"},sec={{t="飞越热带草原",b="对于许多穿越贫瘠之地的旅行者来说，预订迪弗拉克的飞行服务，标志着他们第一次背负着双足飞龙翱翔于天空。这些长着翅膀的飞龙在部落初创时期分散的定居点之间提供了至关重要的空中交通，避开了充满危险、被野猪人和半人马部落潜伏的地面路线。"},{t="军需处的兽皮",b="这批货物是一捆在贫瘠之地加工好的兽皮，目的地是雷霆崖赫瓦军需处工作的工匠安哈努。安哈努的工坊位于中部高地的巨大双足飞龙栖息处正下方，他依靠从各地平原狩猎哨站运来的原始补给品，为当地的战士和猎人装备护甲。"}},faq={{q="谁发布了“飞往雷霆崖”这个任务？",a="贫瘠之地十字路口的双足飞龙管理员迪弗拉克，会向收集到一捆兽皮的旅行者提供这项任务。",al={"任务发布者","飞往雷霆崖任务起点","迪弗拉克位置"}},{q="安哈努是谁，他在哪里可以找到？",a="安哈努是一位驻扎在雷霆崖赫瓦军需处的牛头人工匠，工坊就在城市双足飞龙栖息处的正下方。",al={"安哈努在哪里","安哈努位置","赫瓦军需处"}},{q="这次运输的是什么物品？",a="你携带的是从贫瘠之地送来的一捆加工过的兽皮，安哈努打算立即将其用于皮革加工和护甲制作。",al={"我运送的是什么","一捆兽皮"}},{q="为什么要乘坐双足飞龙而不是步行？",a="双足飞龙可以直接飞越贫瘠之地抵达雷霆崖的高地，避开了进入莫高雷漫长的地面旅程，并直接降落在城市的双足飞龙塔上。",al={"为什么乘飞机去雷霆崖","飞行点的好处"}},{q="这条运送任务链从哪里开始？",a="这次运送始于十字路口的加翰·鹰翼，他在前置任务“一捆兽皮”中整理好了这捆鞣制好的兽皮。",al={"前置任务","兽皮任务线"}},{q="交付兽皮之后接下来要做什么？",a="收到兽皮后，安哈努会指引旅行者上楼直接与雷霆崖的双足飞龙管理员塔尔交谈。",al={"后续任务","飞往雷霆崖的后续"}}},fx={ae176b23={q="迪弗拉克为什么让你带着兽皮去雷霆崖？",a="作为十字路口的飞行管理员，迪弗拉克负责管理连接卡利姆多各处部落定居点的风骑士。一名信使带着急需送往雷霆崖安哈努那里的兽皮包裹赶来时，迪弗拉克的职责就是为其提供快速旅程，并在旅客抵达高耸的台地后指引他们前往目的地。",al={"迪弗拉克为什么想让你办这件事","迪弗拉克的动机","为什么要送一捆兽皮"}},["1fe41edb"]={q="迪弗拉克为什么需要你送兽皮，而不亲自处理？",a="迪弗拉克必须留在十字路口的栖所，管理风骑士，并照料进出卡利姆多中部的旅客。他不能离开岗位跑去莫高雷办事，因此，正好要去那个方向的自愿旅客自然是完成这趟送货的合适人选。",al={"迪弗拉克为什么不亲自送","迪弗拉克为什么派我去","迪弗拉克为什么需要旅客帮忙"}}},fp="21,284,25.339.0,20.343.0,42.141.0,39.134.0,43.148.0,39.166.0,37.143.0,43.127.0"}
P.entries["quest:6363"] = {n="双足飞龙管理员塔尔",s="“风骑士训练师塔尔”是一项简单的信使任务，旨在将莫高雷的制皮师与贫瘠之地的商人们联系起来。制皮师安哈努委托将一包裹成品兽皮运出雷霆崖。将包裹直接送到位于台地上的飞行管理员塔尔手中，可以引导初出茅庐的部落旅行者了解风骑士运输网络。",h="“风骑士训练师塔尔”是一项简单的信使任务，旨在将莫高雷的制皮师与贫瘠之地的商人们联系起来。制皮师安哈努委托将一包裹成品兽皮运出雷霆崖。将包裹直接送到位于台地上的飞行管理员塔尔手中，可以引导初出茅庐的部落旅行者了解风骑士运...",kw={"安哈努","十字路口","迪弗拉克","飞行管理员","加翰","皮革制品","塔尔","雷霆崖","风骑士"},ang={["faction:Horde"]="在贫瘠之地和雷霆崖之间建立稳定的飞行航线，可以确保增援部队、贸易商品和信息能够迅速在卡利姆多中部流动。",["race:Tauren"]="栖息在雷霆崖峭壁上的风骑士，代表着让凯恩·血蹄那与世隔绝的族人融入更广泛的部落联盟的重要纽带。"},sec={{t="十字路口的补给",b="莫高雷与贫瘠之地干旱灌木丛之间的贸易对于年轻的部落至关重要。安哈努是一位在雷霆崖下层高地兜售货物的制皮师，他生产的耐用皮革制品是提供给十字路口加翰·鹰翼的贸易摊位的。由于步行走下峭壁并穿越金色平原需要数小时，商人们依赖有翼的信使，通过崎岖的分界线运送易碎或紧急的包裹。"},{t="台地栖木的主人",b="塔尔栖身于雷霆崖最高的中央平台，照料着城里的风骑士群——也就是双足飞龙。这些聪慧、长着皮质翅膀的野兽非常适合在卡利姆多不可预测的热气流和崎岖的山峰间穿行。塔尔负责协调飞往十字路口等哨所的航班，确保信使和货物能迅速往来于牛头人主城与他们的兽人盟友之间。"}},faq={{q="塔尔是谁？",a="塔尔是雷霆崖的飞行管理员，负责监管位于中央台地的风骑士栖木。他管理着往返于贫瘠之地及更远地区的旅行者和信使的空中运输。",al={"塔尔是谁","雷霆崖的塔尔","风骑士训练师塔尔"}},{q="安哈努是谁？",a="安哈努是一位居住在雷霆崖的牛头人制皮匠。他制作大宗皮革制品，并将它们打包运往卡利姆多各处的哨所供应商，包括十字路口的加翰·鹰翼。",al={"安哈努","安哈努是谁","雷霆崖的安哈努"}},{q="为什么货物需要运往十字路口？",a="十字路口是贫瘠之地重要的贸易和军事交汇处。在莫高雷平静的庇护下生产的货物，如兽皮和皮革服装，会被运往那里以供应旅行者、猎人和部落巡逻队。",al={"为什么是十字路口","十字路口的皮革制品","加翰的皮革"}},{q="我能带着这个包裹直接飞往十字路口吗？",a="你只有在已经访问过该定居点并与当地的风骑士训练师迪弗拉克建立联系后，才能飞往十字路口。如果你还没有解锁该航线，你必须步行前往。",al={"我能飞往十字路口吗","塔尔的飞行路线","如何飞往十字路口"}},{q="什么是风骑士？",a="风骑士，通常被称为双足飞龙，是卡利姆多岩石地带原生的感知型、有毒的带翼掠食者。自第三次战争以来，它们与部落结盟，成为该阵营主要的空中坐骑。",al={"双足飞龙","什么是风骑士","牛头人坐骑"}},{q="这个信使差事接下来要去哪？",a="一旦你将货物交给塔尔，他会指示你找一只坐骑，将安哈努的包裹运过平原，送到在十字路口等待的加翰·鹰翼手中。",al={"下一个任务","塔尔之后做什么","皮革制品去向"}}},fx={["989dcaf5"]={q="安哈努为什么想让你办这件事？",a="安哈努制作了一批成品皮革制品，准备交给在贫瘠之地十字路口经商的商人加翰。为了让莫高雷与部落其他领地之间的贸易持续进行，像安哈努这样的工匠要依靠可靠的信使和风骑士，将商品运过崎岖的广袤土地。",al={"安哈努的动机","为什么要送皮革制品","安哈努送货给加翰"}}},fp="25,339,27.439.0,26.421.0,11.198.0,13.208.0,46.235.0,54.220.0,21.204.0,41.159.0"}
P.entries["quest:6364"] = {n="向加翰回复",s="“回到加翰身边”是部落在莫高雷与贫瘠之地之间双足飞龙航线介绍任务的最终环节。在前往雷霆崖将皮革交给剥皮训练师安哈努之后，旅行者会带着加工好的皮制品乘坐双足飞龙返回十字路口，交付给商人加翰·鹰翼。",h="“回到加翰身边”是部落在莫高雷与贫瘠之地之间双足飞龙航线介绍任务的最终环节。在前往雷霆崖将皮革交给剥皮训练师安哈努之后，旅行者会带着加工好的皮制品乘坐双足飞龙返回十字路口，交付给商人加翰·鹰翼。",kw={"安哈努","贫瘠之地","十字路口","迪弗拉克","加翰·鹰翼","塔尔","雷霆崖","双足飞龙"},ang={["faction:Horde"]="莫高雷、杜隆塔尔和贫瘠之地之间的双足飞龙航线是连接部落卡利姆多中部领地的生命动脉。",["race:Tauren"]="莫高雷制皮工匠与贫瘠之地哨所之间的贸易链展示了团结的部族如何支持部落的边境扩张。"},sec={{t="卡利姆多的双翼",b="对于许多旅行者来说，这趟差事是他们第一次体验骑乘训练有素的双足飞龙。塔尔是雷霆崖的风骑士训练师，他驻守在雷霆崖中央台地的高处，负责安排往返于卡利姆多中部的飞行航线。只要旅行者已经在其他定居点——比如位于十字路口的迪弗拉克——的栖息地建立了联系，这些长着翅膀的野兽就能轻而易举地跨越那些原本需要跋山涉水、穿越赤色石和北部贫瘠之地的险峻路途。"},{t="十字路口的贸易",b="这趟快递任务除了让玩家熟悉飞行航线，还具有经济意义。加翰·鹰翼在繁华的十字路口定居点经营生意，每天都有猎人、侦察兵和雇佣兵聚集于此。从雷霆崖高处寄给安哈努的生皮会被加工成耐用的护甲和装备，随后通过飞行航线送回尘土飞扬的贫瘠之地十字路口，以供应部落不断扩张的边境需求。"}},faq={{q="加翰·鹰翼是谁？",a="加翰·鹰翼是一位驻扎在贫瘠之地十字路口的牛头人商人。他负责买卖皮制品，依赖雷霆崖的工匠将兽皮加工成装备，供外出冒险的勇士们使用。",al={"加翰","加翰·鹰翼背景","加翰是谁"}},{q="为什么我需要乘双足飞龙回到十字路口？",a="这趟旅程是为了演示飞行网络是如何运作的。像雷霆崖的塔尔这样的风骑士训练师只能将快递员和乘客派往他们亲自侦察过或建立过联系的定居点，例如十字路口的迪弗拉克的栖息地。",al={"为什么要飞回去","双足飞龙返程","飞行点如何运作"}},{q="安哈努是谁？",a="安哈努是一位技艺精湛的制皮师和剥皮训练师，位于雷霆崖的高地之上。他负责接收从贫瘠之地的猎人那里运来的兽皮，将其加工成成品，然后再送回各处进行销售。",al={"安哈努","安哈努雷霆崖","谁制作了商品"}},{q="迪弗拉克是谁？",a="迪弗拉克是驻扎在十字路口的兽人风骑士训练师。他负责管理连接贫瘠之地与奥格瑞玛和雷霆崖等部落主要据点的飞行栖息地。",al={"迪弗拉克","十字路口飞行点","风骑士训练师迪弗拉克"}},{q="我能在不先与目的地训练师交谈的情况下使用双足飞龙吗？",a="不能。双足飞龙只能被派往旅行者已经拜访过当地风骑士训练师并完成注册的哨所，以此建立栖息地之间的航线连接。",al={"飞行航线规则","解锁飞行点","我可以飞往任何地方吗"}},{q="把皮革制品交给加翰后会发生什么？",a="交付完加工好的商品，就完成了莫高雷和贫瘠之地之间的快递链，此时旅行者已经熟悉了空中交通，可以自由地继续协助十字路口的守军和商人们。",al={"后续任务","接下来做什么","完成回到加翰身边之后"}}},fx={["65054dbe"]={q="塔尔为什么要把皮革制品送回给加翰？",a="作为雷霆崖的风骑士管理员，塔尔负责台地与十字路口等前哨定居点之间的空中交通。他派你骑乘坐骑回去，把安哈努制作的皮革制品送到加翰那里，既能证明风骑士的高效，也能完成高地工匠与山下加翰·鹰翼兴旺商铺之间的贸易往来。",al={"塔尔为什么想让你办这件事","塔尔的动机","为什么要把皮革送给加翰"}}},fp="15,313,19.511.0,26.408.0,22.219.0,58.249.0,13.212.0,14.179.0,74.176.0,56.211.0"}
P.entries["quest:6365"] = {n="送往奥格瑞玛的肉",s="“运往奥格瑞玛的肉”是由扎尔夫在十字路口提供的一个简短的介绍性后勤任务。他请求年轻的兽人和巨魔冒险者将一包上好的贫瘠之地肉块交给定居点的风骑士训练师迪弗拉克，从而向他们介绍返回部落首都的飞行交通方式。",h="“运往奥格瑞玛的肉”是由扎尔夫在十字路口提供的一个简短的介绍性后勤任务。他请求年轻的兽人和巨魔冒险者将一包上好的贫瘠之地肉块交给定居点的风骑士训练师迪弗拉克，从而向他们介绍返回部落首都的飞行交通方式。",kw={"贫瘠之地","十字路口","迪弗拉克","飞行管理员","格里什卡","肉类配送","奥格瑞玛","风骑士","扎尔夫"},ang={["profession:Cooking"]="将贫瘠之地平原的新鲜肉块补给到格里什卡的奥格瑞玛旅店，可以保证首都里为来访勇士准备的浓汤锅总是满满当当的。",["race:Orc"]="对于离开杜隆塔尔前往贫瘠之地狩猎的年轻兽人来说，运送扎尔夫的包裹提供了一种快速建立回到大酋长首都的空中航线的方法。",["race:Troll"]="在十字路口活动的暗矛巨魔利用这个跑腿任务，将不断扩张的荒野前哨站与奥格瑞玛的后勤补给线连接起来。"},sec={{t="来自贫瘠之地的新鲜野味",b="贫瘠之地广袤的平原上栖息着丰富的野生动物，从斑马和平原陆行鸟到科多兽和雷霆蜥蜴，应有尽有。扎尔夫准备了几块精选肉块，打算亲自送给奥格瑞玛力量谷里忙碌的旅店老板格里什卡。为了保持肉的新鲜并避免长途跋涉，跨越怒水河进入杜隆塔尔，扎尔夫让跑腿的人穿过十字路口，直接去寻找风骑士。"},{t="草原之上的双翼",b="找到迪弗拉克，标志着年轻的部落勇士第一次正式接触风骑士飞行网络。通过与风骑士训练师合作，部落将像十字路口这样的偏远前哨站直接与奥格瑞玛这座坚固的权力中心连接起来。迪弗拉克正在为这次横跨大草原的快速空中飞行准备快递员和货物。"}},faq={{q="扎尔夫要把这些肉送给谁？",a="扎尔夫把这些肉块送给他的朋友格里什卡，她是一位广受欢迎的旅店老板，经营着奥格瑞玛力量谷的主要旅店。",al={"谁收到了肉","肉是给谁的","扎尔夫的肉接收者"}},{q="为什么只有兽人和巨魔能接这个任务？",a="这个任务作为文化飞行介绍，旨在将兽人和暗矛巨魔重新连接到他们共同的首都奥格瑞玛。牛头人通过任务“一捆兽皮”被指引前往雷霆崖，而亡灵角色则通过“补给瑟伯切尔”被指引前往银松森林。",al={"为什么牛头人接不到这个任务","亡灵肉类任务","种族限制"}},{q="迪弗拉克是谁？",a="迪弗拉克是驻扎在贫瘠之地十字路口的兽人风骑士训练师。他负责管理双足飞龙，这些飞龙负责在整个卡利姆多运送消息、补给和旅客。",al={"迪弗拉克十字路口","迪弗拉克是谁"}},{q="把肉交给迪弗拉克之后会发生什么？",a="迪弗拉克会收下这批货物，并为你安排一次风骑士飞行，让你将肉送到奥格瑞玛的天空塔，并通过后续任务“前往奥格瑞玛”将其交给旅店里的格里什卡。",al={"运往奥格瑞玛的肉的后续任务","迪弗拉克是做什么的"}},{q="扎尔夫在哪里？",a="扎尔夫驻扎在十字路口，这是位于贫瘠之地主要路口的部落中央贸易枢纽。",al={"扎尔夫的位置","扎尔夫在哪里"}},{q="为什么要用风骑士而不是步行？",a="风骑士可以提供横跨贫瘠之地严酷荒野和河流峡谷进入杜隆塔尔的快速交通，确保像新鲜肉类这样娇贵的货物在变质前就能运抵奥格瑞玛。",al={"为什么要飞往奥格瑞玛","风骑士肉类"}}},fp="18,208,27.345.0,22.277.0,34.92.0,45.234.0,14.169.0,45.184.0,23.92.0,40.171.0"}
P.entries["quest:637"] = {n="苏利·巴鲁的信",s="这封浸水的信是从萨多尔大桥破碎的拱门下的一具溺亡骷髅身上找回的，其中包含了名为苏利·巴鲁的矮人士兵的临终遗言。这封信写给他在铁炉堡的妻子萨拉，承载了一名在桥梁保卫战中失踪于冰冷河水下的守卫者最后的思绪。",h="这封浸水的信是从萨多尔大桥破碎的拱门下的一具溺亡骷髅身上找回的，其中包含了名为苏利·巴鲁的矮人士兵的临终遗言。这封信写给他在铁炉堡的妻子萨拉，承载了一名在桥梁保卫战中失踪于冰冷河水下的守卫者最后的思绪。",kw={"阿拉希","矮人士兵","铁炉堡","萨拉·巴鲁","骷髅","苏利·巴鲁","萨多尔大桥","浸水的信封","湿地"},ang={["faction:Alliance"]="这封信深刻地提醒着人们，普通的在一线保卫着南部与北部联盟领地之间脆弱陆路连接的士兵们所付出的个人牺牲。",["race:Dwarf"]="对于铁炉堡的矮人来说，带回苏利的遗言是对一位战友的敬意，他为了守卫宏伟的矮人石匠杰作抵御北方威胁而献出了生命。"},sec={{t="河床之音",b="在支撑萨多尔大桥——连接湿地与阿拉希高地的关键陆路桥梁——的巨大石桩下，静卧着一具阵亡矮人的溺亡骷髅。他那枯骨般的手中紧紧抓着一个几乎无法触碰的水浸信封。信件是在战火中费尽心思写下的，开篇即是那句温柔的“亲爱的萨拉……”，在潮水将他带走许久之后，依然保留着这位士兵的声音。"},{t="大桥的代价",b="萨多尔大桥见证了联盟军队与其敌人之间激烈的战斗，从黑铁矮人破坏者到争夺边境地区的劫掠战队，不一而足。苏利·巴鲁是被派往北方保卫这一交通要道的众多矮人士兵之一。当他葬身波涛之下时，他的家人们对此一无所知，直到一位潜水员最终找回了他的遗嘱。"},{t="铁炉堡的遗孀",b="将找回的信件带回铁炉堡，给苏利的遗孀萨拉·巴鲁带来了沉痛的打击。生活在繁华的矮人首都，她一直徘徊在悲伤与一线希望之间，不知道丈夫是失踪了还是永远离开了。面对他亲笔写下的文字，得知他最终长眠于水下，她终于不得不面对他已死亡的残酷现实。"}},faq={{q="苏利·巴鲁的信在哪里可以找到？",a="这封信握在一具淹没在萨多尔大桥（连接湿地与阿拉希高地）巨石桥墩正下方的深处河床上的骷髅手中。",al={"信件位置","苏利·巴鲁在哪里","萨多尔大桥骷髅"}},{q="苏利·巴鲁是谁？",a="苏利·巴鲁是一名在保卫萨多尔大桥时阵亡的联盟矮人士兵。在开始守卫大桥之前，他写了一封告别信给他的妻子萨拉，这封信在他遗骸的冰冷水下被发现时，仍被紧紧攥在手中。",al={"苏利是谁","苏利·巴鲁背景故事","苏利·巴鲁生平"}},{q="萨拉·巴鲁是谁？",a="萨拉·巴鲁是苏利的遗孀，居住在伟大的矮人首都铁炉堡。她已经在期盼中度过了数月，等待着她在北方前线的丈夫的消息。",al={"萨拉·巴鲁在哪里","萨拉是谁","萨拉·巴鲁位置"}},{q="送交这封信后会发生什么？",a="在收到苏利死亡的心碎确认后，萨拉·巴鲁悲痛欲绝，并请求为他立碑纪念，故事也会通过铁炉堡后续的任务请求继续展开。",al={"后续任务","苏利任务线","送信之后"}},{q="为什么信在水下还能保持完整？",a="这封信被保护在士兵遗骸紧紧攥着的信封里。虽然在被找回时已经部分溶解且浸透了水，但几页写着工整字迹的信纸仍然清晰可辨。",al={"为什么信件可读","信封如何保存下来"}},{q="这个任务背后的现实世界灵感是什么？",a="这个任务是为了向美国内战期间罗德岛第2步兵团的萨利文·巴卢少校致敬，他在第一次奔牛河之战阵亡前不久，曾写下一封感人至深的告别信给他的妻子。",al={"苏利·巴鲁趣闻","萨利文·巴卢","内战致敬"}}},fp="21,327,25.455.0,21.403.0,20.428.1,37.197.0,21.225.0,19.167.0,42.203.1,43.229.0,49.228.0"}
P.entries["quest:638"] = {n="巨魔之敌",s="沃金已下令暗矛巨魔从人类废墟王国激流堡中找回远古之剑托卡拉尔。随着托尔贝恩国王的陨落，这柄利刃将服务于部落，以应对未来与祖尔格拉布巨魔的冲突。",h="沃金已下令暗矛巨魔从人类废墟王国激流堡中找回远古之剑托卡拉尔。随着托尔贝恩国王的陨落，这柄利刃将服务于部落，以应对未来与祖尔格拉布巨魔的冲突。",kw={"落锤镇","尼姆布亚","激流堡","托卡拉尔","托尔贝恩","沃金","森古","祖尔格拉布"},ang={["faction:Horde"]="部落的猎人森古正在落锤镇等待，希望能看到这柄传奇之剑从人类手中夺回。",["race:Troll"]="沃金专门寻求托卡拉尔，是为了武装暗矛部族以对抗他们祖尔格拉布的远古族人。"},sec={{t="国王陨落，利刃渴求",b="在托尔贝恩国王去世、激流堡沦为废墟之后，沃金酋长已下令尽一切努力夺回托卡拉尔。这柄传奇之剑长期以来一直掌握在人类手中，但暗矛部族希望能将其夺回，以应对即将在祖尔格拉布展开的与丛林巨魔的战争。"},{t="前往落锤镇",b="为了执行沃金的指令，一位经验丰富的猎人名叫森古被派往阿拉希高地东北部的部落哨站落锤镇。尼姆布亚指引从荆棘谷前来的旅行者去寻找森古，并协助夺回这件传奇武器。"}},faq={{q="为什么沃金想要托卡拉尔之剑？",a="沃金打算在即将到来与祖尔格拉布敌对丛林巨魔的战斗中使用托卡拉尔。",al={"为何需要托卡拉尔","为何需要托尔贝恩之剑","托卡拉尔的用途"}},{q="森古是谁？",a="森古是一位经验丰富的猎人，由暗矛巨魔派遣至阿拉希高地的落锤镇，负责监督托卡拉尔的回收工作。",al={"谁是森古","森古的任务","猎人森古"}},{q="这段旅程将指引你去向何处？",a="旅程将引领你离开荆棘谷向北前往阿拉希高地东北部的哨站——落锤镇。",al={"去往何处","任务目的地","森古在哪里"}},{q="激流堡发生了什么？",a="在统治者托尔贝恩国王去世后，激流堡已成为一片废墟。",al={"激流堡现状","托尔贝恩国王发生了什么"}}},fp="9,251,30.339.0,21.283.0,43.103.0,13.135.0,33.113.0,28.82.0"}
P.entries["quest:6381"] = {n="新的生命",s="“新生命”是一个部落的恢复性任务，由烈日石居的塔姆拉·荒原提供。在收集了附有魔法的盖亚之种后，玩家将向西前往焦炭谷的灰烬废墟，将种子播撒在肥沃的土地上。这一仪式旨在让这片土地在充满敌意的元素生物和鹰身人中恢复生机。",h="“新生命”是一个部落的恢复性任务，由烈日石居的塔姆拉·荒原提供。在收集了附有魔法的盖亚之种后，玩家将向西前往焦炭谷的灰烬废墟，将种子播撒在肥沃的土地上。这一仪式旨在让这片土地在充满敌意的元素生物和鹰身人中恢复生机。",kw={"血怒鹰身人","焦炭谷","重生之环","土堆","火元素","盖亚之种","石爪山脉","烈日石居","塔姆拉·荒原"},ang={["class:Druid"]="德鲁伊与塔姆拉的使命有着密切的联系，他们将焦炭谷的更新视为对自然脆弱平衡的一次重要恢复。",["class:Shaman"]="萨满明白，除非这片饱受摧残的土地开始自我治愈，否则游荡在山谷中的焦躁火元素将永远无法获得平静。",["profession:Herbalism"]="草药师们能够领会这种坚韧种子所蕴含的深奥力量，它们能让在完全死寂的土壤中焕发出繁茂的植被。",["race:Tauren"]="对于牛头人来说，在满目疮痍的土地上播撒附有魔法的种子，是一种与大地母亲进行精神交流的行为，履行了他们治愈受伤土地的神圣职责。"},sec={{t="治愈焦土",b="焦炭谷是近期破坏惨状的悲剧见证，这里充斥着煤烟、狂暴的火元素和四处觅食的鹰身人。塔姆拉·荒原拒绝让该地区彻底荒废。依靠大地母亲古老的复原力，她派遣旅行者前往那片焦黑山谷的中心，寻找盖亚之土堆——那些在大火中幸存下来的肥沃表土。"},{t="未来的立足点",b="种在焦土中的附有魔法的盖亚之种旨在抵御挥之不去的元素腐蚀。通过生根发芽，它们开始编织一种至关重要的生态锚点，能够抵御衰败并引回谷中的植被。塔姆拉预想了一个长期的治愈过程：随着活着的根系慢慢收复这片盆地，焦躁的火灵将会平息，鹰身人将失去它们荒凉的栖息地，而荆棘谷地精贪婪的伐木作业最终也将被赶出去。"}},faq={{q="种植盖亚之种的目的是什么？",a="附有魔法的盖亚之种旨在焦炭谷伤痕累累的土地上生根发芽。它们可以抵御腐蚀，并建立起最初的生机勃勃的植被立足点，为森林逐渐恢复和治愈奠定基础。",al={"为什么要种植种子","“新生命”任务目的","盖亚之种的作用"}},{q="我需要去哪里种植种子？",a="你必须从烈日石居向西前往焦炭谷。种子需要种植在散布于焦黑盆地各处的小型盖亚之土堆中。",al={"焦炭谷在哪里","在哪里种植盖亚之种","种子位置"}},{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是一位居住在石爪山脉烈日石居的牛头人博物学家。她致力于安抚这片土地上受伤的灵魂，并修复被元素之怒和工业贪婪所蹂躏的区域。",al={"谁提供“新生命”任务","塔姆拉任务发布者","塔姆拉·荒原背景故事"}},{q="在种植时，有哪些威胁在焦炭谷游荡？",a="焦炭谷居住着因近期破坏而被惊动的流浪火元素，以及在烧焦的树木间筑巢的、极具攻击性的血怒鹰身人。",al={"焦炭谷的敌人","焦炭谷的攻击者","焦炭谷的危险"}},{q="在“新生命”之前的任务是什么？",a="“新生命”直接承接任务“重生之环”，在该任务中，你将帮助塔姆拉收集制备附有魔法的盖亚之种所需的关键材料。",al={"“新生命”前置任务","“重生之环”任务","如何开启“新生命”"}},{q="塔姆拉希望石爪山脉在长期内发生什么变化？",a="塔姆拉希望重新生长出来的土地最终能平息愤怒的火元素，排挤走掠食性的鹰身人，并熬过荆棘谷地精的伐木作业，让群山恢复成郁郁葱葱、宁静祥和的森林。",al={"石爪山脉的未来","塔姆拉的目标","焦炭谷的未来"}}},fx={c43560c5={q="盖亚泥土堆有什么用？",a="这些土堆是散布在焦炭谷焦黑土地上的一块块肥沃土壤。塔姆拉·荒原需要你把附有魔法的盖亚之种埋进土堆里，让种子生根、抵御当地的腐化，并催生新的植被，逐渐收复这片荒废的土地。",al={"盖亚泥土堆的用途","什么是盖亚泥土堆","为什么要把种子种在泥土堆里"}}},fp="8,321,26.399.0,25.486.0,47.240.0,41.153.0,24.235.0,50.166.0,33.152.0,58.228.0"}
P.entries["quest:6382"] = {n="灰谷狩猎",s="“灰谷狩猎”是一项指引部落中久经考验的冒险者离开干旱的贫瘠之地，北上进入灰谷茂密森林的任务。在陶拉祖营地的塞娜尼·雷心（原文为Jorn Skyseer，此处遵照名录更正为塞娜尼·雷心，注：原文此处似乎有误，应为Jorn Skyseer委托前往Splintertree Post协助Senani Thunderheart，已按语境调整）委托下，旅行者们会被派往碎木岗哨协助塞娜尼·雷心，并在这一片充满野性与争端的土地上磨炼追踪技巧。",h="“灰谷狩猎”是一项指引部落中久经考验的冒险者离开干旱的贫瘠之地，北上进入灰谷茂密森林的任务。在陶拉祖营地的塞娜尼·雷心（原文为Jorn Skyseer，此处遵照名录更正为塞娜尼·雷心，注：原文此处似乎有误，应为Jorn...",kw={"灰谷","灰谷狩猎","贫瘠之地","陶拉祖营地","乔恩·天视","塞娜尼·雷心","碎木岗哨"},ang={["class:Hunter"]="从卡利姆多的平原进入灰谷，意味着地形的巨大转变，在浓密的林冠之下，有无数充满异国情调的野兽等待着你去追踪、研究和驯服。",["faction:Horde"]="灰谷是一个至关重要的战略前沿；在这里建立立足点，可以为杜隆塔尔和贫瘠之地的各个定居点提供维持运作所需的木材和食物补给。",["race:Tauren"]="乔恩·天视和塞娜尼·雷心共同指引着这段旅程，他们并不将狩猎仅仅视为屠戮，而是将其视为一种精神上的平衡，一种向荒野致敬的方式。"},sec={{t="深入古木天顶",b="在贫瘠之地那阳光灼烧的平原上证明了自己的狩猎实力后，部落的猎人和勇士们会被指引前往一个完全不同的试炼场。当旅行者们已不再满足于狩猎本地的野兽时，乔恩·天视就会为他们指明方向，让他们北上前往灰谷。对于年轻的部落成员来说，这些古老的林地既意味着丰富的资源，也是他们必须学习去理解和征服的一片深奥的政治与精神前沿。"},{t="碎木岗哨",b="沿着蜿蜒的道路向北，经过莫尔杉壁垒，旅行者们便会抵达碎木岗哨。这是一个深藏在林线之内的设防部落营地。在那里，牛头人女猎手塞娜尼·雷心欢迎着那些寻求更高生存挑战的资深勇士。为了在灰谷生存，部落依赖于那些能够追踪敌对掠食者，以及避开森林守护者警惕目光的熟练追踪者。"}},faq={{q="谁派我去执行“灰谷狩猎”？",a="乔恩·天视是一位驻扎在南贫瘠之地陶拉祖营地的牛头人猎人，当你证明了自己在本地狩猎野兽的技巧后，他便会提供这项任务。",al={"谁给予灰谷狩猎任务","灰谷狩猎任务发放者","乔恩·天视任务"}},{q="碎木岗哨在哪里？",a="碎木岗哨位于灰谷的中东部。如果你沿着主路从贫瘠之地向北走，经过莫尔杉壁垒并继续深入丛林，这个设防的前哨站就坐落在道路的北侧。",al={"碎木岗哨位置","塞娜尼·雷心在哪里","寻找碎木岗哨"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是一位驻扎在碎木岗哨的牛头人女猎手。她负责协调整个灰谷的狩猎工作，教导新来的部落冒险者如何去追踪古老森林中最凶猛的掠食者和灵魂。",al={"塞娜尼·雷心","塞娜尼是谁","女猎手塞娜尼"}},{q="灰谷附近还有其他部落前哨站吗？",a="除了碎木岗哨，部落在东部还设有战歌伐木营地，并在最西端的佐拉姆海岸设有佐拉姆加前哨站。",al={"部落在灰谷的基地","灰谷的其他营地"}},{q="为什么部落对在灰谷狩猎感兴趣？",a="这片未经驯化的荒野提供了杜隆塔尔和贫瘠之地所缺乏的关键肉类、毛皮和资源。面对森林中危险的野兽，对于部落的勇士和猎人来说，也被视为是对意志和精神力量的重要考验。",al={"为什么要在灰谷狩猎","部落在灰谷的动机"}},{q="这段旅程之后还有什么挑战？",a="塞娜尼·雷心会招募老练的猎人去追踪林地中显眼的威胁，派他们深入林冠去狩猎顶级的掠食者，例如巨熊乌萨诺斯、猫科动物沙德拉以及角鹰兽尖爪。",al={"灰谷狩猎后的下一个任务","塞娜尼给予什么"}}},fx={["854a1b41"]={q="乔恩·星眼为什么派你去灰谷？",a="乔恩·星眼看出你的实力正在增长，也看出你愿意接受贫瘠之地的狩猎考验。在他看来，你已经超越了当地的试炼，准备好去争取更大的荣誉。灰谷茂密的森林是一片荒野边境，部落正努力在那里争取精神上的精进和政治上的控制权。他希望像你这样有能力的猎人能助部落确立优势。",al={"乔恩·星眼为什么想让你办这件事","乔恩·星眼的动机","为什么要去灰谷"}},["2c1005c5"]={q="乔恩·星眼为什么选你参加这次狩猎？",a="乔恩见证了你在贫瘠之地证明自己的本领和胆识。作为驻守陶拉祖营地的资深向导和长者，他的职责是发掘新晋战士的潜力，并把他们派往部落最需要力量的地方。灰谷需要的是经受过考验、能干的猎人，而不是那些被困在前哨防务岗位上、毫无经验的卫兵。",al={"灰谷狩猎为什么选我","乔恩为什么选我","为什么要派冒险者"}}},fp="18,317,23.443.0,17.452.0,35.159.0,35.225.0,27.226.0,50.149.0,52.252.0,36.227.0"}
P.entries["quest:6383"] = {n="灰谷狩猎",s="灰谷狩猎是由塞娜尼·雷心在碎木岗哨主持的一项传统仪式。部落猎人们接受挑战，去追踪并战胜徘徊在这片古老森林中的三头传奇掠食者：巨熊乌萨戈斯、夜刃豹莎德拉，以及凶猛的角鹰兽锐爪。这不仅仅是对武艺的考验，更是一段学习狡诈、尊重与自我认知的旅程。",h="灰谷狩猎是由塞娜尼·雷心在碎木岗哨主持的一项传统仪式。部落猎人们接受挑战，去追踪并战胜徘徊在这片古老森林中的三头传奇掠食者：巨熊乌萨戈斯、夜刃豹莎德拉，以及凶猛的角鹰兽锐爪。这不仅仅是对武艺的考验，更是一段学习狡诈、尊重...",kw={"灰谷狩猎","林中树居","塞娜尼·雷心","莎德拉","锐爪","碎木岗哨","石爪小径","乌萨戈斯"},ang={["class:Hunter"]="这场狩猎是一项经典的成年仪式，迫使追踪者在广袤的森林中搜寻、解读地形，并与足以轻易击败粗心侦察兵的野兽进行战斗。",["faction:Horde"]="与战歌氏族对森林的破坏性砍伐形成对比，这场狩猎为部落在纷争不断的灰谷中提供了一条兼具武艺荣誉与精神融合的道路。",["race:Tauren"]="对于牛头人猎人而言，追踪乌萨戈斯、莎德拉和锐爪体现了对大地母亲造物的传统敬畏，在对自然凶猛本能的尊重与追踪之道的荣誉之间达成了平衡。"},sec={{t="古老森林中的牛头人传统",b="随着部落在灰谷深处建立立足点，大地母亲的精神教诲通过塞娜尼·雷心得到了体现。与兽人们激进的伐木活动不同，塞娜尼的狩猎将阴影笼罩的林地视为神圣的试炼场。通过与森林中顶尖掠食者的博弈，猎人们有望与这片原始荒野进行心灵交流，并培养在灰谷生存所必需的沉静谦逊。"},{t="三大巨兽",b="狩猎的核心是三头游荡在林间的孤独传奇生物。在石爪小径附近徘徊着乌萨戈斯，这是一头体型巨大的长者巨熊，它的力量考验着猎人的肉体韧性。再向东，在那靠近林中树居以及难以捉摸的欢笑姐妹的边界地带，潜伏着莎德拉，这是一头因其狡诈而备受敬畏的潜行夜刃豹。最后，在碎木岗哨以南盘旋着锐爪，这是一头凶猛的角鹰兽，它对森林树冠的掌控为这场试炼画上了句点。"}},faq={{q="谁发起了灰谷狩猎？",a="这项狩猎由驻扎在灰谷的牛头人猎人塞娜尼·雷心主持。她向那些寻求在荒野中证明自己生存技能的部落旅行者们发出挑战。",al={"灰谷狩猎任务发布者","谁发起狩猎","塞娜尼·雷心任务"}},{q="我需要追踪哪些野兽？",a="你必须追踪并击杀三头传奇掠食者：巨熊乌萨戈斯、夜刃豹莎德拉，以及凶猛的角鹰兽锐爪。",al={"需要杀死的动物","三大野兽","灰谷狩猎目标"}},{q="乌萨戈斯在哪里可以找到？",a="乌萨戈斯在石爪小径以西不远处的一小片领地内游荡，它会在林地其他野生熊群中来回踱步。",al={"乌萨戈斯位置","熊在哪里","找到乌萨戈斯"}},{q="莎德拉在哪里徘徊？",a="莎德拉在林中树居以南的地区徘徊，它常在被称为欢笑姐妹的树妖们所居住的道路附近进行狩猎。",al={"莎德拉位置","莎德拉在哪里","夜刃豹位置"}},{q="锐爪可以在哪里被追踪到？",a="锐爪在碎木岗哨以南的一大片广阔区域内巡逻，它在树木和空地之间盘旋。",al={"锐爪位置","锐爪在哪里","角鹰兽位置"}},{q="为什么塞娜尼·雷心要派猎人去猎杀这些野兽？",a="塞娜尼将这场狩猎视为一种荣誉试炼，而非肆意的屠杀。通过让猎人们与森林中最致命的自然居民进行较量，他们可以更深刻地了解荒野，并深入洞察自身的内在力量。",al={"为什么要进行狩猎","狩猎目的","狩猎背景故事"}}},fx={e25adf54={q="灰谷狩猎的目标是什么野兽？",a="这场狩猎要求你追踪三只栖息在灰谷古老森林里的传奇掠食者：乌萨苟斯，一头在石爪小径附近徘徊的巨大凶猛巨熊；萨杜布拉，一只在林中树居以南的森林中出没、行踪难觅的夜刃豹；以及夏雷纳尔，一只在碎木岗哨以南盘旋的凶猛角鹰兽。它们分别代表了森林本身那未受驯服的力量与狡诈。",al={"我要猎杀哪些野兽","灰谷狩猎的目标","这些野兽是谁"}},a64a5cc6={q="为什么塞娜尼·雷心让冒险者去狩猎，而不是派当地卫兵？",a="灰谷狩猎并非军事任务，也不是号召消灭某个族群。这是一项传统的成年礼，旨在考验猎人在荒野中的个人机智、力量与意志。碎木岗哨的驻军负责保卫部落在敌对领土上的前哨，而这场试炼是一段独自踏上的旅程，你要寻找森林中最凶猛的野兽，以证明自己的价值。",al={"为什么派我去","为什么是冒险者","为什么不派碎木岗哨卫兵"}}},fp="18,403,39.442.0,22.458.0,30.191.0,36.144.0,29.119.0,28.127.0,32.115.0,61.244.0"}
P.entries["quest:6384"] = {n="飞往奥格瑞玛",s="这项差事向部落冒险者介绍了卡利姆多的空中旅行方式，玩家需要委托一名双足飞龙管理员从十字路口飞往奥格瑞玛。冒险者将带着扎尔夫的新鲜肉排，降落在奥格瑞玛的天空塔，并将包裹直接交给旅店老板格雷什卡。",h="这项差事向部落冒险者介绍了卡利姆多的空中旅行方式，玩家需要委托一名双足飞龙管理员从十字路口飞往奥格瑞玛。冒险者将带着扎尔夫的新鲜肉排，降落在奥格瑞玛的天空塔，并将包裹直接交给旅店老板格雷什卡。",kw={"贫瘠之地","十字路口","迪弗拉克","多拉斯","格雷什卡","奥格瑞玛","天空塔","双足飞龙","扎尔夫"},ang={["faction:Horde"]="十字路口和奥格瑞玛之间的双足飞龙航线是连接贫瘠之地中部与大酋长萨尔权力中心的重要命脉。",["profession:Cooking"]="格雷什卡在收到扎尔夫的礼物后，明确表达了她的烹饪偏好：卡利姆多最上等的野兽肉应该做成半熟，以保持其鲜味。"},sec={{t="草原之翼",b="在十字路口和杜隆塔尔红色的悬崖之间，徒步穿越干旱的荒原十分艰苦，但部落拥有一套可靠的双足飞龙网络来缩短距离。十字路口飞行管理员迪弗拉克负责监管这些双足飞龙，将信使和旅行者送往尘土飞扬的峡谷小径上方，直接将重要的公文和贸易货物送到首都。"},{t="给格雷什卡的特别快递",b="这次飞行不仅仅是一次观光之旅；它还带着一份私人心意。十字路口的扎尔夫准备了一份上好的生肉排，目的地是奥格瑞玛Valley of Strength的旅店老板格雷什卡。当双足飞龙降落在奥格瑞玛中央的天空塔时，格雷什卡的旅店就在不远处，她会欣然接受这份礼物——并满怀爱意地表示，扎尔夫确实很懂得如何俘获女士的芳心。"}},faq={{q="这次飞行的目的是什么？",a="这趟旅程是部落双足飞龙旅行网络的实践介绍。你支付给迪弗拉克费用，从十字路口乘骑飞往奥格瑞玛，将扎尔夫的新鲜肉排送给旅店老板格雷什卡。",al={"为什么要飞往奥格瑞玛","飞往奥格瑞玛的目的","为什么要送肉到奥格瑞玛"}},{q="双足飞龙在奥格瑞玛的哪里降落？",a="双足飞龙降落在奥格瑞玛的天空塔，它高耸在Valley of Strength之上。从塔台出发，你可以走下坡道到达主广场、附近的商贩以及格雷什卡的旅店。",al={"在奥格瑞玛哪里降落","天空塔位置","奥格瑞玛飞行降落点"}},{q="格雷什卡是谁？",a="旅店老板格雷什卡管理着奥格瑞玛Valley of Strength中繁忙的旅店。她欢迎疲惫的旅行者来到首都，并与扎尔夫保持着良好的友谊，扎尔夫经常为她的厨房提供上好的生肉。",al={"旅店老板格雷什卡","格雷什卡是谁","格雷什卡的位置"}},{q="迪弗拉克是谁？",a="迪弗拉克是驻扎在贫瘠之地十字路口的双足飞龙管理员。他照看双足飞龙并协调连接贫瘠之地前哨站与杜隆塔尔及其他部落定居点的空中交通。",al={"迪弗拉克与十字路口","迪弗拉克是谁","十字路口双足飞龙管理员"}},{q="扎尔夫为什么要给格雷什卡送生肉？",a="扎尔夫认为来自贫瘠之地的新鲜猎物是一份珍贵的礼物。格雷什卡非常欣赏这份礼物，并指出上好的稀有肉排是俘获她芳心的绝佳方式。",al={"扎尔夫的肉","为什么给格雷什卡送肉","扎尔夫和格雷什卡"}},{q="送完肉后我该做什么？",a="在旅店完成送货后，格雷什卡会指引旅行者回到天空塔，与奥格瑞玛的双足飞龙管理员多拉斯交谈，为返程做准备。",al={"飞往奥格瑞玛后做什么","格雷什卡之后的任务","送货后去哪里"}}},fp="17,188,22.334.0,28.252.0,35.182.0,44.150.0,15.173.0,14.172.0,41.124.0,43.145.0"}
P.entries["quest:6385"] = {n="双足飞龙管理员多拉斯",s="奥格瑞玛的旅店老板格雷什卡写了一封感谢信给十字路口的扎尔夫，并需要一名信使把它空运回贫瘠之地。为了安排行程，她指引旅行者前往城市的飞行塔，去咨询部落的首席风骑士训练师多拉斯。",h="奥格瑞玛的旅店老板格雷什卡写了一封感谢信给十字路口的扎尔夫，并需要一名信使把它空运回贫瘠之地。为了安排行程，她指引旅行者前往城市的飞行塔，去咨询部落的首席风骑士训练师多拉斯。",kw={"贫瘠之地","十字路口","多拉斯","飞行管理员","格雷什卡","奥格瑞玛","双足飞龙","扎尔夫"},ang={["faction:Horde"]="双足飞龙网络将奥格瑞玛与关键的地区驻军连接起来，充当了连接的纽带，使年轻的部落能够在卡利姆多的荒野中投射兵力和运送补给。",["race:Orc"]="兽人在抵达这片大陆后，便与卡利姆多本土的双足飞龙建立了深厚的羁绊，依靠它们的敏捷和力量作为飞行坐骑和驮兽信使。"},sec={{t="信使的回复",b="在收到从贫瘠之地的狩猎场空运来的一批新鲜肉类后，旅店老板格雷什卡起草了一封给屠夫扎尔夫的正式感谢信。由于没有时间亲自经由杜隆塔尔进行陆路跋涉，她依靠卡利姆多各主要部落定居点之间建立的空中信使网络，将她的信息迅速送回边境。"},{t="巢穴主管",b="多拉斯负责监管奥格瑞玛位于Valley of Strength飞行塔顶部的风骑士巢穴。他训练的双足飞龙是部落军事通讯和后勤的生命线，它们在首都和十字路口这样的边远哨所之间架起了桥梁，所花费的时间仅为步行或乘坐科多兽大车所需时间的一小部分。"}},faq={{q="谁是多拉斯？",a="多拉斯是驻扎在奥格瑞玛的主要风骑士训练师。他管理着城市的双足飞龙训练马厩，并协调前往卡利姆多中部各地偏远部落枢纽的空中旅行。",al={"多拉斯","谁是多拉斯","奥格瑞玛飞行管理员"}},{q="为什么旅店老板格雷什卡要寄这封信？",a="格雷什卡正在给十字路口的屠夫扎尔夫寄一封感谢信，以确认送到她奥格瑞玛旅店的肉类补给已安全抵达。",al={"为什么要寄信","格雷什卡的信","信是用来做什么的"}},{q="在哪里可以找到多拉斯？",a="多拉斯驻扎在奥格瑞玛Valley of Strength上方的中央飞行塔顶端，可以通过塔内的木制坡道到达。",al={"多拉斯在哪里","多拉斯的位置","寻找多拉斯"}},{q="把格雷什卡的信交给多拉斯后会发生什么？",a="一旦你咨询了多拉斯，他就会准备一只双足飞龙带你回到贫瘠之地，这样你就可以直接把格雷什卡的信亲手交给十字路口的扎尔夫。",al={"接下来做什么","多拉斯之后","下一个任务"}},{q="谁是扎尔夫？",a="扎尔夫是一位常驻贫瘠之地十字路口的兽人屠夫，也是格雷什卡的朋友，他曾送给她一些精选的贫瘠之地肉类作为礼物。",al={"扎尔夫","谁是扎尔夫"}},{q="为什么要骑乘双足飞龙而不是步行？",a="从奥格瑞玛穿过杜隆塔尔，越过怒水河进入贫瘠之地的陆路旅程缓慢且充满危险。驯服的双足飞龙为部落提供了一种在定居点之间派遣侦察兵、传达命令和运送信件的快速、可靠的方式。",al={"为什么要飞行","双足飞龙的作用","飞行点背景故事"}}},fp="27,199,17.289.0,23.260.0,13.162.0,45.143.0,25.122.0,52.153.0,13.132.0,39.219.0"}
P.entries["quest:6386"] = {n="返回十字路口",s="这个差事完成了杜隆塔尔与贫瘠之地之间的一次信使投递，将格雷什卡的回复带回给了十字路口的扎尔夫。它展示了双足飞龙管理员是如何作为部落在整个卡利姆多各定居点之间的重要空中骨干发挥作用的。",h="这个差事完成了杜隆塔尔与贫瘠之地之间的一次信使投递，将格雷什卡的回复带回给了十字路口的扎尔夫。它展示了双足飞龙管理员是如何作为部落在整个卡利姆多各定居点之间的重要空中骨干发挥作用的。",kw={"贫瘠之地","十字路口","迪弗拉克","多拉斯","格雷什卡","信","奥格瑞玛","双足飞龙","飞龙","扎尔夫"},ang={["faction:Horde"]="奥格瑞玛和十字路口的双足飞龙栖息地构成了连接部落首府与卡利姆多危险荒原的经济与后勤脊梁。",["race:Orc"]="丰盛的新鲜野味仍然是兽人猎人向未来的伴侣表达爱意和尊重的最好信物之一。"},sec={{t="翼上归途",b="将一份上等肉块送到奥格瑞玛的格雷什卡手中后，你受托将她的亲笔回信带给扎尔夫。多拉斯，这位栖息在奥格瑞玛高耸峭壁上的双足飞龙管理员，为你提供了一匹回贫瘠之地的坐骑。因为你已经与十字路口的迪弗拉克建立了联系，多拉斯的双足飞龙认识飞行路线，从而将一次艰苦的穿越怒水河的陆路跋涉，变成了一段飞越荒漠天空的迅捷旅程。"},{t="贫瘠之地的良缘",b="扎尔夫大胆的烹饪求爱攻势成功了。格雷什卡那热情的回复证实了没有什么比优质的补给更能打动一位兽人，这促使扎尔夫欣喜若狂，甚至开始憧憬即将到来的婚礼。除了浪漫的胜利，这次旅程还巩固了旅行者进入贫瘠之地中央交通枢纽的权限。"}},faq={{q="为什么我必须使用双足飞龙返回？",a="多拉斯利用这次投递来演示部落的飞行网络。既然你之前拜访过十字路口的迪弗拉克，双足飞龙就能在两个栖息地之间直接飞行，既节省了时间，又确保了补给线的安全。",al={"为什么飞回去","需要双足飞龙","我可以走路吗"}},{q="格雷什卡是谁？",a="格雷什卡是奥格瑞玛力量谷的旅店老板。扎尔夫送给她一些精选的贫瘠之地肉块，希望能赢得她的青睐。",al={"格雷什卡背景故事","格雷什卡是谁","奥格瑞玛的送肉女士"}},{q="扎尔夫送肉去奥格瑞玛的目的是什么？",a="扎尔夫想要追求格雷什卡。在兽人文化中，赠送来自贫瘠之地荒原的丰盛优质野味被认为是一种盛大的浪漫姿态。",al={"为什么扎尔夫要送肉","扎尔夫的动机","扎尔夫的信"}},{q="这个任务在哪里结束？",a="任务在贫瘠之地的十字路口完成，你将在那里把格雷什卡的信交还给岗哨和马厩附近的扎尔夫。",al={"在哪里交任务","返回地点","谁收到格雷什卡的信"}},{q="多拉斯是谁？",a="多拉斯是驻扎在奥格瑞玛力量谷上方飞行栖息地的双足飞龙管理员，负责管理往来于卡利姆多的空中坐骑。",al={"双足飞龙管理员多拉斯","多拉斯的位置","奥格瑞玛飞行管理员"}},{q="这个任务之后会发生什么？",a="这次投递标志着“送肉去奥格瑞玛”信使任务线的终结。在连接了奥格瑞玛和十字路口后，你已经完全准备好去探索贫瘠之地更深处的地方了。",al={"后续任务","返回后的下一个任务","送肉去奥格瑞玛的后续"}}},fp="25,149,15.387.0,27.220.0,44.177.0,15.125.0,51.122.0,26.118.0,13.146.0,30.138.0"}
P.entries["quest:6387"] = {n="荣誉学员",s="采矿训练师布洛克·寻石者会奖励塞尔萨玛那些表现优异的年轻学徒，授予他们荣誉锄。为了安排从铁炉堡运送这些工具，他指引冒险者去寻求当地狮鹫管理员索格拉姆·伯雷森的帮助。",h="采矿训练师布洛克·寻石者会奖励塞尔萨玛那些表现优异的年轻学徒，授予他们荣誉锄。为了安排从铁炉堡运送这些工具，他指引冒险者去寻求当地狮鹫管理员索格拉姆·伯雷森的帮助。",kw={"布洛克·寻石者","高尼尔·石趾","狮鹫","矿工的馈赠","铁炉堡","洛克莫丹","采矿","塞尔萨玛","索格拉姆·伯雷森"},ang={["faction:Alliance"]="这项请求向洛克莫丹的旅人们介绍了联盟至关重要的飞行管理员和空中快递网络。",["profession:Mining"]="这个任务凸显了矮人对采矿这一严谨工艺的尊重，精通矿石和矿脉的技艺可以获得大师级导师实实在在的认可。",["race:Dwarf"]="对于矮人冒险者来说，这个任务反映了像塞尔萨玛这样的边境定居点与首都深山大厅之间的紧密联系。"},sec={{t="矿工的馈赠",b="在矮人城镇塞尔萨玛，采矿不仅仅是一项职业，更是他们日常生活和矮人自豪感的基石。布洛克·寻石者看着一批又一批的新兵通过他的训练，向他们传授岩石构成和隧道安全的知识。对于那些表现出众的学生，传统要求以一把做工精良的荣誉锄作为奖励。由于当地物资有限，获得这些锄头需要跨越卡兹莫丹，直抵铁炉堡的心脏地带。"},{t="飞向蓝天",b="布洛克并不指望人们通过漫长而艰难的山路徒步走回丹莫罗，而是依靠王国的空中快递网络。索格拉姆·伯雷森负责照看塞尔萨玛旁的狮鹫点，提供前往首都的快速交通。将布洛克的订单交给索格拉姆，就可以开启一次快递行程，将偏远的边境训练基地与矮人首都伟大的铸造厂直接连接起来。"}},faq={{q="布洛克·寻石者是谁？",a="布洛克·寻石者是一位居住在塞尔萨玛的采矿训练师。他向新手传授挖掘和石艺的基础技能。",al={"布洛克·寻石者","布洛克是谁","塞尔萨玛采矿训练师"}},{q="为什么布洛克需要从铁炉堡运来锄头？",a="布洛克编制了一份获得荣誉锄的高成就采矿学徒名单。为了兑现这些奖励，订单必须送到驻扎在铁炉堡的采矿用品商人高尼尔·石趾手中。",al={"为什么要去铁炉堡","为什么需要锄头","布洛克的名单"}},{q="索格拉姆·伯雷森在这一任务中扮演什么角色？",a="索格拉姆·伯雷森是塞尔萨玛的狮鹫管理员。布洛克指示快递员将订单名单交给他，以便他们安排前往铁炉堡的快速空中运输。",al={"索格拉姆·伯雷森","索格拉姆是谁","塞尔萨玛狮鹫管理员"}},{q="谁在铁炉堡接收名单？",a="这份名单最终将送达铁炉堡的高尼尔·石趾手中，他会为布洛克那些卓有成就的学生准备好这些仪式用的锄头。",al={"谁接收名单","高尼尔·石趾","铁炉堡联系人"}},{q="这个任务接下来要去哪？",a="一旦你与索格拉姆·伯雷森交谈，他就会安排狮鹫直飞铁炉堡，这样你就可以亲手将订单交给高尼尔·石趾。",al={"下一步","矿工的馈赠后续","布洛克的名单之后"}},{q="这个任务在哪里进行？",a="任务的开始和结束都在塞尔萨玛定居点内，该定居点坐落在洛克莫丹连绵的群山之中。",al={"任务地点","塞尔萨玛在哪里","矿工的馈赠起始点"}}},fx={["7a941756"]={q="为什么布洛克·寻石者请冒险者帮忙，而不亲自送名单？",a="布洛克正忙着在塞尔萨玛训练有志成为矿工的人，教新学徒技艺，还要照看自己的熔炉。若离开岗位远赴铁炉堡，当地学徒的课程就会停滞，因此由一位路过的冒险者替他把名单送到城里再合适不过。",al={"布洛克为什么找我帮忙","布洛克为什么不去铁炉堡","布洛克为什么不亲自送名单"}}},fp="14,251,13.512.0,19.394.0,25.138.0,41.212.0,52.168.0,35.136.0,33.146.0,32.112.0"}
P.entries["quest:6388"] = {n="格莱斯·瑟登",s="这项任务旨在向冒险者们介绍铁炉堡的狮鹫网，要求他们将一捆仪式用具送交至城市的狮鹫管理员处。这捆荣誉锄是由高尼尔·石趾托付给跑腿者的，他必须将其送交至格里瑟·索丹手中，以便通过空运送回洛克莫丹。",h="这项任务旨在向冒险者们介绍铁炉堡的狮鹫网，要求他们将一捆仪式用具送交至城市的狮鹫管理员处。这捆荣誉锄是由高尼尔·石趾托付给跑腿者的，他必须将其送交至格里瑟·索丹手中，以便通过空运送回洛克莫丹。",kw={"飞行管理员","高尼尔·石趾","格里瑟·索丹","荣誉锄","铁炉堡","洛克莫丹","塞尔萨玛","索格拉姆·伯雷森"},ang={["faction:Alliance"]="铁炉堡的狮鹫停驻点是联盟使节往返于丹莫罗、洛克莫丹以及更广阔的王国之间不可或缺的交通枢纽。",["profession:Mining"]="这次运送直接帮助了洛克莫丹的布洛克·寻石者的采矿学徒，用在首府铸造的荣誉锄来庆祝他们的技艺。",["race:Dwarf"]="对于矮人来说，依靠狮鹫既是一种祖传的骄傲，也是一种现实的需要，它将穿过险峻山峰的各个山厅连接了起来。"},sec={{t="矿工的跑腿差事",b="在从洛克莫丹前往Great Forge之后，跑腿者会从高尼尔·石趾那里收到一捆荣誉锄，这是为了布洛克·寻石者的采矿学徒们准备的。高尼尔建议利用矮人的狮鹫网络，而不是徒步翻越山口走回去，他让信使穿过城市去与铁炉堡的首席驯兽师进行协调。"},{t="飞往塞尔萨玛",b="格里瑟·索丹负责管理这座大山厅内的飞行点，连接着铁炉堡与卡兹莫丹各处的矮人定居点。只要冒险者已经勘探过路线并与当地的驯兽师交谈过，索丹就同意安排前往塞尔萨玛索格拉姆·伯雷森处的运输。这次交付让初出茅庐的英雄们了解到了空中信使在连接矮人王国方面所起的至关重要的作用。"}},faq={{q="荣誉锄是用来做什么的？",a="荣誉锄是高尼尔·石趾在铁炉堡打造的仪式用具，旨在送给驻扎在塞尔萨玛的采矿指导员布洛克·寻石者的学生们使用。",al={"荣誉锄","荣誉锄的作用","送给布洛克的锄头"}},{q="格里瑟·索丹是谁？",a="格里瑟·索丹是驻扎在铁炉堡的首席狮鹫管理员。他负责监管连接着这座矮人首府与整个卡兹莫丹及其他地区周边定居点的飞行路线。",al={"格里瑟·索丹是谁","铁炉堡狮鹫管理员","格里瑟·索丹背景"}},{q="格里瑟·索丹在铁炉堡的什么位置？",a="格里瑟·索丹位于Great Forge的飞行点，靠近中央主干道和铁炉堡大门。",al={"格里瑟·索丹位置","格里瑟·索丹在哪里","铁炉堡飞行管理员"}},{q="为什么我需要先与索格拉姆·伯雷森交谈？",a="狮鹫管理员只会派骑手沿着规划好的路线飞行。在格里瑟·索丹能派遣骑手前往塞尔萨玛之前，旅行者必须已经与驻扎在洛克莫丹的管理员索格拉姆·伯雷森建立了联系。",al={"索格拉姆·伯雷森的前置条件","为什么需要塞尔萨玛飞行点","无法飞往塞尔萨玛"}},{q="把锄头交给格里瑟·索丹后会发生什么？",a="一旦格里瑟检查完包裹，他就会安排一次狮鹫飞行，让你返回塞尔萨玛，将这些工具直接送到布洛克·寻石者手中。",al={"格里瑟·索丹之后做什么","格里瑟·索丹后的下一个任务"}},{q="是谁派你去找格里瑟·索丹的？",a="高尼尔·石趾，一位在铁炉堡Great Forge附近工作的工匠，他会把锄头交给你并指引你去找格里瑟。",al={"谁开启了格里瑟·索丹任务","谁发布了这个任务"}}},fx={["05b277d3"]={q="为什么高尼尔·石趾让你去找格瑞斯·瑟罗姆？",a="高尼尔·石趾已经备好了荣誉锄，准备送给远在塞尔萨玛的布洛克·寻石者的采矿学徒。高尼尔没有让你徒步穿过积雪的山口返回，而是指引你去找铁炉堡的狮鹫管理员格瑞斯·瑟罗姆，让你学会如何安排狮鹫飞行，直接飞越群山返回。",al={"为什么让人去找格瑞斯","高尼尔·石趾的动机","格瑞斯·瑟罗姆为什么要锄头"}}},fp="13,303,24.384.0,24.418.0,32.164.0,21.185.0,44.120.0,50.216.0,53.149.0,31.126.0"}
P.entries["quest:639"] = {n="激流堡符印",s="落锤镇的森古想要夺回守护托卡拉尔的印记，那可是伊格纳斯·托尔贝恩领主之剑。第一枚印记，也就是斯托姆印记，被辛迪加夺走了。斯托姆加德的一个辛迪加特工很有可能携带着它。",h="落锤镇的森古想要夺回守护托卡拉尔的印记，那可是伊格纳斯·托尔贝恩领主之剑。第一枚印记，也就是斯托姆印记，被辛迪加夺走了。斯托姆加德的一个辛迪加特工很有可能携带着它。",kw={"阿拉希高地","落锤镇","伊格纳斯","斯托姆印记","斯托姆加德","辛迪加","托卡拉尔","托尔贝恩","森古"},sec={{t="托尔贝恩的遗产",b="远古时期，巨魔与阿拉索帝国交战，而他们最强大的敌人就是来自斯托姆的伊格纳斯领主，人称“巨魔之敌”。他持剑托卡拉尔投入战斗，这个名字在巨魔的古语中意为“巨魔杀手”。如今，托尔贝恩的后代已经衰弱，他们的堡垒也已沦为废墟。"},{t="第一枚印记",b="有数枚印记守护着这把剑，斯托姆加德的幸存者们各自保管着一部分。森古说必须将它们全部找回。辛迪加夺走了第一枚，森古认为斯托姆加德的某个特工手里就有它。把它带回落锤镇交给森古。"}},faq={{q="森古是谁？",a="森古位于阿拉希的落锤镇。他正在收集守护伊格纳斯·托尔贝恩领主之剑——托卡拉尔的印记。",al={"谁给予斯托姆印记任务","落锤镇的森古"}},{q="什么是托卡拉尔？",a="托卡拉尔在巨魔的古语中意为“巨魔杀手”。来自斯托姆的伊格纳斯领主，也就是人称“巨魔之敌”的那位，曾手持此剑与巨魔作战。",al={"什么是托卡拉尔","托卡拉尔的含义","托尔贝恩之剑"}},{q="为什么要找斯托姆印记？",a="这把剑由数枚印记守护，斯托姆加德的幸存者们将它们分散保管。森古想要集齐所有印记，而斯托姆印记是第一枚。",al={"为什么要收集印记","斯托姆印记的用途"}},{q="谁持有斯托姆印记？",a="辛迪加夺走了它。它很可能就在斯托姆加德的某个辛迪加特工身上。",al={"谁拥有斯托姆印记","斯托姆印记在哪里","辛迪加印记"}}},fp="14,213,23.292.0,15.259.0,13.123.0,19.146.0,33.155.0,29.86.0"}
P.entries["quest:6391"] = {n="飞往铁炉堡",s="“前往铁炉堡”是一项入门级的信使任务，引导刚完成训练的冒险者搭乘他们的第一次狮鹫航班，从洛克莫丹的塞尔萨玛飞往矮人的首都。旅行者受布洛克·寻石者之托，携带一份列有最优秀采矿学员名单的文书，将其直接送交到位于Great Forge的高尼尔·石趾手中。",h="“前往铁炉堡”是一项入门级的信使任务，引导刚完成训练的冒险者搭乘他们的第一次狮鹫航班，从洛克莫丹的塞尔萨玛飞往矮人的首都。旅行者受布洛克·寻石者之托，携带一份列有最优秀采矿学员名单的文书，将其直接送交到位于Great...",kw={"布洛克的名单","深山矿业公会","高尼尔·石趾","great forge","狮鹫","卡拉诺斯","前往铁炉堡任务","索格拉姆·伯雷森"},ang={["faction:Alliance"]="狮鹫飞行网络构成了卡兹莫丹联盟后勤的基石，将前线驻地与宏伟的首都无缝连接起来。",["profession:Mining"]="这项任务直接突显了深山矿业公会的传统，即对从洛克莫丹矿坑中脱颖而出的有前途的矿工进行表彰并镌刻荣誉。",["race:Dwarf"]="对于年轻的铜须矮人来说，骑着狮鹫飞入Great Forge是往返于乡村前哨与王国心脏地带之间的一种令人自豪的成人仪式。"},sec={{t="飞向蓝天",b="对于许多年轻的山地探险者和旅行者来说，从塞尔萨玛飞往铁炉堡的航程是他们第一次骑乘狮鹫的旅途。这段短途航线由狮鹫管理员索格拉姆·伯雷森负责，带领旅行者飞越丹莫罗白雪皑皑的山脊，直接进入这座山中要塞如洞穴般的入口。"},{t="深山矿业公会的荣誉",b="这项差事本身是为深山矿业公会服务的。布洛克·寻石者会定期传达他最优秀的采矿学员的消息。在高尼尔·石趾等待的Great Forge，他会将学员的名字刻在荣誉锄上，以奖励他们在洛克莫丹采石场和矿坑中的辛勤工作。"}},faq={{q="这段航线的起点和终点在哪里？",a="旅程始于洛克莫丹塞尔萨玛的飞行管理员索格拉姆·伯雷森处，并将你直接送往铁炉堡内Great Forge的飞行站。",al={"飞行航线","飞行地点","飞行目的地"}},{q="什么是布洛克的名单？",a="布洛克的名单是由塞尔萨玛的采矿训练师布洛克·寻石者汇编的一份名册。它记录了他最出色的学生，以便铁炉堡的公会能够奖励他们的勤奋。",al={"布洛克的名单背景","谁是布洛克","名单是什么"}},{q="谁是高尼尔·石趾？",a="高尼尔·石趾是深山矿业公会的代表，常驻于铁炉堡的Great Forge内。他负责接收来自当地训练师的名册，并将学生的名字凿刻在荣誉锄上。",al={"高尼尔的职责","高尼尔在哪里","谁是高尼尔·石趾"}},{q="递交名单后会发生什么？",a="一旦高尼尔收到名单，他会指引你去找铁炉堡的首席狮鹫管理员格雷斯·瑟登，让你进一步熟悉王国的空中交通网络。",al={"后续任务","之后做什么","后续"}},{q="为什么用狮鹫而不用走路？",a="虽然山路和隧道直通铁炉堡大门，但这项任务作为联盟狮鹫旅行的实用指导，向新冒险者展示了他们在各定居点之间穿梭是多么快捷。",al={"为什么要飞行","可以步行前往铁炉堡吗","为什么要骑狮鹫"}},{q="什么是荣誉锄？",a="荣誉锄是深山矿业公会制作的仪式性工具，旨在表彰那些在地区导师指导下掌握了基础挖掘和地质知识的杰出采矿学员。",al={"荣誉锄","锄头奖励","采矿锄仪式"}}},fx={d8819fd3={q="为什么索格拉姆·伯雷森要你乘坐狮鹫前往铁炉堡？",a="索格拉姆·伯雷森是洛克莫丹塞尔萨玛的狮鹫管理员，他的生意离不开从站点起飞的旅人。他安排你飞往铁炉堡，把布洛克那份列有有前途的矿工学徒的名单交给高尼尔·石趾，让你体验狮鹫旅行的快捷与便利，同时确保重要的公会信件及时送达首都。",al={"索格拉姆·伯雷森的动机","为什么派人去铁炉堡","为什么要送布洛克的名单"}}},fp="17,325,19.309.0,33.326.0,37.169.0,21.177.0,25.207.0,40.175.0,37.214.0,25.193.0"}
P.entries["quest:6392"] = {n="向布洛克回复",s="既然你已经将布洛克·寻石者的信件送到了铁炉堡，你现在受托携带一批荣誉锄返回塞尔萨玛。利用矮人的空中交通网络，你与格里希·瑟登一同乘坐狮鹫，迅速穿过群山返回。",h="既然你已经将布洛克·寻石者的信件送到了铁炉堡，你现在受托携带一批荣誉锄返回塞尔萨玛。利用矮人的空中交通网络，你与格里希·瑟登一同乘坐狮鹫，迅速穿过群山返回。",kw={"布洛克·寻石者","飞行管理员","狮鹫","格里希·瑟登","荣誉锄","铁炉堡","返回布洛克处","塞尔萨玛"},ang={["profession:Mining"]="交付这些荣誉锄将重要的工具交到了洛克莫丹最新一批矿工的手中，延续了矮人挖掘和勘探的传统。",["race:Dwarf"]="铁炉堡和塞尔萨玛之间的航线突显了蛮锤狮鹫和铁炉堡管理员在维系各矮人据点方面所发挥的重要作用。"},sec={{t="翱翔天际",b="铁炉堡这座伟大的山中堡垒依靠着协调统一的狮鹫管理员网络，来维持与洛克莫丹等边远定居点的通讯与贸易。格里希·瑟登是铁炉堡的狮鹫管理员，他在城市的中央飞行管理员平台监督着这项运输工作。由于旅客在乘机前往某处之前，必须先与当地的管理员建立联系，因此格里希确保你在启程返回之前，已经与塞尔萨玛的索格拉姆·伯雷森交谈过。"},{t="给学员的锄头",b="你的旅程除了让你了解狮鹫旅行之外，还有一个实际目的：布洛克·寻石者，塞尔萨玛的一位受人尊敬的采矿教练，需要为他的学徒提供新装备。随着荣誉锄被安全送到他手中，整个山谷的年轻矿工们就可以开始在洛克湖周围的山丘中开采丰富的铜矿和锡矿脉了。"}},faq={{q="布洛克·寻石者是谁？",a="布洛克·寻石者是一位驻扎在洛克莫丹的塞尔萨玛的矮人采矿训练师。他指导新手矿工从周围的山丘中提取原矿和石料。",al={"布洛克·寻石者","布洛克是谁","塞尔萨玛的布洛克"}},{q="为什么我需要乘坐狮鹫来完成这个任务？",a="这项任务向旅客介绍了联盟的飞行系统。格里希·瑟登解释说，狮鹫只能载你去你之前亲自拜访过的飞行点，例如索格拉姆·伯雷森在塞尔萨玛的巢穴。",al={"为什么要飞行","飞行点任务","狮鹫飞行"}},{q="荣誉锄是用来做什么的？",a="它们是布洛克·寻石者从铁炉堡订购的新锻造采矿工具，供他的新手采矿学生在洛克莫丹矿产丰富的悬崖上使用。",al={"荣誉锄","荣誉锄是什么"}},{q="格里希·瑟登是谁？",a="格里希·瑟登是铁炉堡的狮鹫管理员，驻扎在Great Forge。他负责管理这座首都进出卡兹莫丹及更远地区的飞行航线。",al={"格里希·瑟登","铁炉堡飞行管理员"}},{q="我可以直接走回塞尔萨玛，而不是飞行吗？",a="虽然这节课旨在教你如何使用飞行路线，但布洛克·寻石者只关心你能否安全地将荣誉锄带到塞尔萨玛交给他，至于你如何到达那里并不重要。",al={"我可以走回去吗","我必须乘坐狮鹫吗"}},{q="布洛克在塞尔萨玛的什么地方？",a="布洛克·寻石者可以在塞尔萨玛的锻炉和铁砧户外找到，他随时准备协助在洛克莫丹工作的矿工。",al={"布洛克在哪里","布洛克·寻石者位置","寻找布洛克"}}},fx={c8277dbd={q="为什么格瑞斯·瑟罗姆要我去送这些锄头？",a="格瑞斯·瑟罗姆管理着铁炉堡的狮鹫站，维系着王国各条飞行路线的畅通。塞尔萨玛的布洛克·寻石者正等着一批急需的荣誉锄，供他的采矿学徒使用。你已经熟悉铁炉堡与索格拉姆·伯雷森站点之间的路线，格瑞斯便借这次送货满足布洛克的需求，也让你掌握在卡兹莫丹乘坐狮鹫旅行的本领。",al={"格瑞斯为什么需要这个","格瑞斯·瑟罗姆的动机","为什么把锄头送给布洛克"}},be2b1abc={q="为什么格瑞斯·瑟罗姆派冒险者送货，而不亲自处理？",a="格瑞斯·瑟罗姆不能离开大熔炉的岗位，他在那里负责管理川流不息的乘客，并照料铁炉堡珍贵的狮鹫。你亲自把布洛克的信送进城里，也开通了返回塞尔萨玛的飞行路线，因此由你担任信使最合适；你可以检验这条新开通的线路，并把物资直接送回矿工手中。",al={"格瑞斯为什么需要我","为什么派冒险者去塞尔萨玛","为什么不派信使"}}},fp="15,270,19.498.0,20.361.0,25.171.0,55.216.0,32.159.0,21.167.0,52.195.0,36.124.0"}
P.entries["quest:6393"] = {n="元素战争",s="“元素之战”是苏纳曼委托的一项任务，他是居住在石爪山脉烈日石居的水元素使节。在猎潮者耐普图隆的意志指引下，冒险者们被派往焦炭谷焦灼的深处，去熄灭炽热的火元素，并收集它们闷燃的焚火余烬核心。这让我们得以一窥元素位面之间那场古老而永恒的纷争。",h="“元素之战”是苏纳曼委托的一项任务，他是居住在石爪山脉烈日石居的水元素使节。在猎潮者耐普图隆的意志指引下，冒险者们被派往焦炭谷焦灼的深处，去熄灭炽热的火元素，并收集它们闷燃的焚火余烬核心。这让我们得以一窥元素位面之间那场...",kw={"焦炭谷","元素之战","火元素","焚火余烬","耐普图隆","石爪山脉","烈日石居","潮汐议会","苏纳曼"},ang={["class:Shaman"]="萨满祭司尊崇元素的平衡，这使得耐普图隆的仆从与火元素之间的直接冲突，成为了原始元素纷争的生动体现。",["faction:Horde"]="鉴于苏纳曼驻扎在烈日石居，途经石爪山脉的部落冒险者们正处于协助这场元素冲突的绝佳位置。"},sec={{t="山脉中的原始纷争",b="在石爪山脉崎岖的区域，一位名叫苏纳曼的使节代表潮汐议会来到了烈日石居。在水元素领主猎潮者耐普图隆的至高意志下，苏纳曼试图对火元素同族执行一项古老的复仇。这场冲突并非为了争夺凡人的疆界，而是代表了艾泽拉斯原始力量之间无休止的碰撞。"},{t="灰烬与烈焰",b="这场争斗的主要战场是焦炭谷，这是一片位于石爪山脉南部、阴燃着的伤痕累累的荒地。火元素在灰烬中滋生，威胁着周围的地区。冒险者们被征召前往该谷地，扑灭这些烈焰缠身的实体，并收集焚火余烬——元素被击败后留下的灼热残余——以向议会证明它们的毁灭。"}},faq={{q="苏纳曼是谁？",a="苏纳曼是潮汐议会派往石爪山脉烈日石居的使者。他奉猎潮者耐普图隆之命，试图向火元素发动战争，并招募冒险者来协助消灭它们。",al={"苏纳曼是谁","苏纳曼任务发布者","烈日石居元素"}},{q="为什么耐普图隆想要消灭火元素？",a="水元素领主猎潮者耐普图隆对火元素怀有古老的敌意，并亲自关注着对它们的剿灭。苏纳曼正是受潮汐议会派遣，在石爪山脉执行这一行动。",al={"为什么要对抗火元素","元素之战缘由","耐普图隆与火元素"}},{q="焦炭谷在哪里？",a="焦炭谷是一个位于石爪山脉南部、满是灰烬的荒凉盆地。那里遍布着炽热的元素生物以及其他由烈焰与废墟中诞生的危险野兽。",al={"焦炭谷在哪里","石爪山脉火元素位置","哪里寻找焚火余烬"}},{q="什么是焚火余烬？",a="焚火余烬是焦炭谷的火元素被熄灭后留下的燃烧残余。苏纳曼收集这些核心作为它们被消灭的实证，以博取潮汐议会的青睐。",al={"什么是焚火余烬","火元素掉落","焚火余烬背景"}},{q="什么是潮汐议会？",a="潮汐议会是服务于猎潮者耐普图隆的水元素权威组织。他们指挥着元素力量和像苏纳曼这样的使节，推进猎潮者的意志，对抗敌对的元素领域。",al={"潮汐议会背景","潮汐议会是谁","水元素阵营"}},{q="猎潮者耐普图隆是谁？",a="猎潮者耐普图隆是水元素领主，统治着海洋、海域和所有的水元素。和其他元素领主一样，他与敌对元素，特别是火元素，进行着一场古老而永恒的冲突。",al={"耐普图隆是谁","水元素领主","猎潮者耐普图隆"}}},fp="13,431,31.418.0,21.425.0,16.244.0,53.263.0,34.187.0,21.223.0,34.217.0,31.224.0"}
P.entries["quest:6394"] = {n="塔兹利尔的镐",s="工头塔兹利尔在一次矿产勘测中，不小心将他最钟爱的附魔矿镐遗落在了北部洞穴深处。如今，这座被称为火刃集会所的洞穴已被危险的野兽占据，那把发光的工具正静静地等待着被寻回。",h="工头塔兹利尔在一次矿产勘测中，不小心将他最钟爱的附魔矿镐遗落在了北部洞穴深处。如今，这座被称为火刃集会所的洞穴已被危险的野兽占据，那把发光的工具正静静地等待着被寻回。",kw={"火刃集会所","杜隆塔尔","工头塔兹利尔","采矿","矿镐","塔兹利尔","试炼谷","瀑布"},ang={["faction:Horde"]="保障基础工具并清除像火刃集会所这样的敌对威胁，有助于部落在试炼谷建立稳固的立足点。",["profession:Mining"]="工头塔兹利尔依靠他的附魔矿镐在杜隆塔尔进行矿产勘测，他希望在当地的树木被清理干净后，能开辟新的采矿前景。"},sec={{t="遗失的工具",b="工头塔兹利尔是试炼谷的监工，负责监管这里的工作细节。此前他曾深入北部洞穴探寻矿脉，在勘测岩石内部结构时，不慎弄丢了他珍贵的矿镐。等他意识到并折返寻找时，凶猛的野兽和敌对的生物已经占据了洞穴，迫使这位工头不得不寻求有能力的年轻新兵协助找回他遗失的工具。"},{t="黑暗中发光",b="为了让这把珍贵的矿镐在昏暗的地下深处更易于使用，塔兹利尔为其施加了一个魔法，使它能够在黑暗中发光。这种魔法照明让冒险者可以轻易发现这把位于火刃集会所内一处瀑布室里的工具，尽管要拿回它，就必须面对潜伏在洞穴阴影中的危险生物。一旦找回，塔兹利尔希望这把矿镐能再次投入使用，在整个山谷中发掘新的采矿机遇。"}},faq={{q="谁是工头塔兹利尔？",a="工头塔兹利尔负责监管试炼谷的劳工和资源收集工作，指挥苦工伐木并为采矿作业清理土地。",al={"塔兹利尔是谁","塔兹利尔的职责","工头塔兹利尔"}},{q="塔兹利尔的矿镐为什么会发光？",a="塔兹利尔在他的矿镐上施加了魔法，使它能在黑暗中发光，这样即使在漆黑的洞穴深处也能轻易被发现。",al={"矿镐为什么特别","发光的矿镐","附魔矿镐"}},{q="火刃集会所在哪里？",a="火刃集会所是一处阴暗的洞穴网络，位于试炼谷苦工伐木营地的北面。",al={"火刃集会所在哪","集会所位置","矿镐洞穴"}},{q="塔兹利尔是怎么丢掉矿镐的？",a="塔兹利尔在勘测北部洞穴矿产时落下了他最喜欢的矿镐。当他折返去拿的时候，凶猛的野兽和黑暗的邪教徒已经侵占了那个洞穴。",al={"塔兹利尔如何丢失矿镐","为什么落下矿镐","遗落的矿镐"}},{q="矿镐被丢在洞穴里的什么位置？",a="矿镐被留在了洞穴深处的一间地下室内，那里有瀑布，也是塔兹利尔最后一次勘测岩壁的地方。",al={"洞穴内部位置","矿镐房间","瀑布室"}},{q="塔兹利尔拿回矿镐后打算做什么？",a="塔兹利尔计划等他的苦工们清理完试炼谷周边的树木后，寻找一处有产出的洞穴进行开采。",al={"塔兹利尔的未来计划","塔兹利尔要开采什么"}}},fp="16,244,11.460.0,16.485.0,25.161.0,31.143.0,33.116.0,32.179.0,40.145.0,59.132.0"}
P.entries["quest:6395"] = {n="玛拉的遗愿",s="“玛拉的遗愿”是丧钟镇的新兵艾尔雷斯给予被遗忘者玩家的早期任务。任务要求玩家去追猎被天灾军团奴役的塞缪尔·菲普斯的残骸，以便将他安葬在被他杀害的妻子玛拉身边。这个任务反映了初生的被遗忘者社会渴望缅怀人类情感，并将自己与毫无理智的天灾军团区分开来。",h="“玛拉的遗愿”是丧钟镇的新兵艾尔雷斯给予被遗忘者玩家的早期任务。任务要求玩家去追猎被天灾军团奴役的塞缪尔·菲普斯的残骸，以便将他安葬在被他杀害的妻子玛拉身边。这个任务反映了初生的被遗忘者社会渴望缅怀人类情感，并将自己与毫...",kw={"丧钟镇","坟墓","玛拉·菲普斯","玛拉的遗愿","新兵艾尔雷斯","遗骸","塞缪尔·菲普斯","天灾军团"},ang={["class:Priest"]="新兵艾尔雷斯坚持进行适当的葬礼，这直接体现了被遗忘者牧师的精神职责，他们需要直面死亡、悲伤以及洛丹伦死者所受到的亵渎。",["race:Undead"]="对于新复活的被遗忘者来说，实现玛拉的遗愿是他们与曾经人类生活的情感纽带，这证明了当洛丹伦陷落时，同情心与荣誉并未随之消亡。"},sec={{t="悲剧重逢",b="在第三次战争蹂躏洛丹伦之前，玛拉和塞缪尔·菲普斯曾是一对恩爱夫妻。当瘟疫席卷他们的土地时，塞缪尔没能幸免于难，并被复活成了天灾军团的一具无脑奴隶。虽然玛拉逃过了成为亡灵的命运，却没能逃过塞缪尔本人的毒手——他在疯狂中残忍地杀害了她。尽管死于丈夫之手，玛拉在临终前并没有心怀怨恨。新兵艾尔雷斯记得，她临终的愿望是能永远安息在丧钟镇墓地，陪伴在丈夫身边。"},{t="尊重死者",b="新兵艾尔雷斯派遣被遗忘者冒险者前往丧钟镇东北方向，寻找依然徘徊在一处废弃营地中的塞缪尔·菲普斯。终结塞缪尔的痛苦有着双重意义：既清除了山谷中入侵的天灾爪牙，也能将他的遗骸带回玛拉的安息之地。正如艾尔雷斯所强调的那样，缅怀逝者并尊重他们的遗愿，是新解放的被遗忘者与天灾军团的无脑恶意之间重要的道德分界线。"}},faq={{q="玛拉·菲普斯是谁？",a="玛拉·菲普斯是洛丹伦的一位居民，她在最初的亡灵瘟疫中幸存了下来，却在丈夫塞缪尔变成毫无理智的天灾食尸鬼后被他杀害。她临终的愿望是能与丈夫合葬。",al={"玛拉·菲普斯背景故事","玛拉是谁","玛拉的背景"}},{q="谁是塞缪尔·菲普斯？",a="塞缪尔·菲普斯是瘟疫爆发前玛拉的丈夫。他屈服于天灾军团，在巫妖王的意志下丧失了理智，并杀害了自己的妻子。他徘徊在丧钟镇东北部的一处废弃营地，直到被被遗忘者冒险者终结。",al={"塞缪尔·菲普斯背景故事","谁是塞缪尔·菲普斯","塞缪尔·菲普斯在哪里"}},{q="为什么新兵艾尔雷斯要在意将他们合葬？",a="新兵艾尔雷斯生前是玛拉的朋友。除了个人情感之外，艾尔雷斯认为，尊重死者的遗愿并有尊严地对待遗骸，证明了被遗忘者依然保留着人性与道德，这使他们与毫无理智的天灾军团区分开来。",al={"为什么要帮助玛拉","新兵艾尔雷斯的动机","为什么要安葬塞缪尔"}},{q="玛拉成为被遗忘者了吗？",a="没有。据新兵艾尔雷斯所说，玛拉并没有变成亡灵。她死于丈夫之手，死得像个凡人，并被安葬在丧钟镇的墓地里。",al={"玛拉是亡灵吗","玛拉成为了被遗忘者吗","玛拉·菲普斯与亡灵"}},{q="玛拉的墓地在哪里？",a="玛拉的坟墓位于丧钟镇主教堂外墓地的第一排。",al={"玛拉的墓地位置","玛拉葬在哪里","在哪里安葬塞缪尔"}},{q="在哪里可以找到塞缪尔·菲普斯？",a="塞缪尔·菲普斯在从丧钟镇向东北方向延伸的道路旁的一处废弃营地附近徘徊。",al={"塞缪尔·菲普斯的位置","寻找塞缪尔·菲普斯","塞缪尔在哪里"}}},fx={e919b4a2={q="塞缪尔的遗骸有什么用？",a="你收集塞缪尔的遗骸，是为了让他终于能与妻子玛拉一同入土安息。尽管塞缪尔变成了没有心智的天灾爪牙，并夺去了她的性命，玛拉临终前的愿望仍是与他长眠于丧钟镇墓地。",al={"塞缪尔的遗骸","为什么收集塞缪尔的遗骸","塞缪尔遗骸的用途"}},["74d32be4"]={q="塞缪尔·菲普斯是谁？为什么必须打败他？",a="塞缪尔·菲普斯曾是提瑞斯法林地的活人居民，后来染上亡灵瘟疫，成为天灾军团毫无思考能力的仆从。他在失去神智时杀死了自己的妻子，如今则作为游荡的食尸鬼，在丧钟镇东北方的废弃营地附近徘徊；只有被消灭，他才能得到安息。",al={"为什么杀死塞缪尔·菲普斯","玛拉的临终遗愿中要打谁","塞缪尔·菲普斯的故事"}}},fp="17,339,16.550.0,19.517.0,20.225.0,20.235.0,56.265.0,27.162.0,31.96.0,32.97.0"}
P.entries["quest:64"] = {n="遗失的怀表",s="农夫法布隆和他的妻子维娜在蒙面强盗占领了他们在西部荒野的南瓜田后被迫逃离了家园。在仓皇出逃时，法布隆将一件珍贵的传家宝遗落在了农舍的衣柜里。找回这块怀表是一次难得的机会，能让人在这片地区日益严重的混乱中挽救回一些私人物品。",h="农夫法布隆和他的妻子维娜在蒙面强盗占领了他们在西部荒野的南瓜田后被迫逃离了家园。在仓皇出逃时，法布隆将一件珍贵的传家宝遗落在了农舍的衣柜里。找回这块怀表是一次难得的机会，能让人在这片地区日益严重的混乱中挽救回一些私人物品...",kw={"benny blaanco","迪菲亚","法布隆","怀表","南瓜田","弗娜·法布隆","衣柜","西部荒野"},ang={["faction:Alliance"]="法布隆一家的困境凸显了王国粮仓社会秩序的严重崩溃，迫使联盟旅行者不得不去处理王室所忽视的问题。",["race:Human"]="对于暴风城的人类来说，看到诚实的农民在距离首都仅一日路程的地方被暴力亡命之徒驱逐，这令人清醒地意识到王国国内的动荡。"},sec={{t="午夜驱逐",b="像西部荒野的许多农场主一样，农夫法布隆和他的妻子维娜被暴力驱逐出了自己的土地。在南瓜田里响起的突如其来的叫喊声和暴力冲突中，这对夫妇从睡梦中惊醒，只来得及匆忙收拾起随身携带的少量物品就逃离了农场。在恐慌中，法布隆不得不留下了维娜的父亲在他们结婚那天送给他的怀表，并将它遗落在了他们被占领的农舍衣柜里。"},{t="田野间的流氓",b="现在的法布隆南瓜农场到处是迪菲亚暴徒、劫掠者和像Benny Blaanco这样趁火打劫的盗贼，他们在被废弃的房屋残骸中翻找。对于普通平民来说，回去找回私人财物无异于送死。通过在满目疮痍的房间里从衣柜中取回怀表，冒险者们为这个几乎失去了所有家当的家庭带去了一丝尊严，对抗着那不断高涨的无法无天之势。"}},faq={{q="为什么那块怀表对农夫法布隆如此重要？",a="这块怀表是维娜的父亲送给他们的结婚礼物。作为失去了生计、一无所有的难民，这块怀表是他们与过去的生活和家庭遗产之间仅存的极少数情感纽带之一。",al={"怀表的重要性","法布隆怀表的意义","谁送给法布隆怀表"}},{q="是谁将法布隆一家赶出了他们的农场？",a="迪菲亚强盗和劫掠者在夜间占领了农场。席卷西部荒野的动荡局势迫使许多农场家庭在暴力威胁下放弃了他们的田地和家园。",al={"谁袭击了农场","谁占领了法布隆农场","法布隆一家的遭遇"}},{q="怀表藏在哪里？",a="怀表存放在法布隆家园的一间卧室衣柜里，该农场位于法布隆路边营地以西的南瓜田。目前有非法占据者和迪菲亚歹徒占据着这处住所。",al={"怀表在哪里","寻找怀表","衣柜位置"}},{q="Benny Blaanco是谁？",a="Benny Blaanco是一个逃犯，他与迪菲亚同伙一起逗留在法布隆的农舍内，洗劫着这处废弃的住所，并守卫着这片偷来的领地，阻止原主人收复。",al={"benny blaanco背景故事","房子里的人是谁"}},{q="法布隆一家现在住在哪里？",a="逃离土地后，农夫法布隆和维娜现在流落在西部荒野的路边，避难于他们的马车旁，试图在这一地区的崩溃中生存下去。",al={"法布隆一家在哪里","农夫法布隆在哪里"}},{q="暴风城会派遣卫兵协助收复这样的农场吗？",a="由于政治上的冷漠和首都领导层的缺失，暴风城在西部荒野的官方军事存在几乎为零。哨兵岭的人民民兵缺乏人手来收复各个独立的农场，使得定居者完全处于无助的境地。",al={"暴风城援助西部荒野","为什么农场没有卫兵"}}},fp="22,209,19.358.0,23.310.0,56.216.0,45.209.0,26.205.0,21.161.0,36.141.0,59.247.0"}
P.entries["quest:640"] = {n="破碎的符印",s="在你从辛迪加手中夺回第一枚徽记后，森古指派你去取回剩下的两枚，它们正由盘踞在激流堡的民兵把守。托拉斯·托尔贝恩之子加林将索拉丁徽记打碎，你需要将碎片带给落锤镇的巨魔萨满托尔甘。",h="在你从辛迪加手中夺回第一枚徽记后，森古指派你去取回剩下的两枚，它们正由盘踞在激流堡的民兵把守。托拉斯·托尔贝恩之子加林将索拉丁徽记打碎，你需要将碎片带给落锤镇的巨魔萨满托尔甘。",kw={"阿拉希高地","破碎的徽记","加林·托尔贝恩","落锤镇","索拉丁徽记","激流堡","托拉斯·托尔贝恩","托尔甘","森古"},sec={{t="破碎的徽记",b="有三枚徽记守护着托拉斯·托尔贝恩的陵墓，你已经从辛迪加手中收回了第一枚。另外两枚更难获取，因为它们被盘踞在激流堡的民兵牢牢把守着。托拉斯之子加林将索拉丁徽记分成了十一块碎片，并分发给了激流堡的守军。"},{t="前往托尔甘处",b="森古让你从激流堡的守军手中夺回这些碎片，并把它们带给落锤镇的巨魔萨满托尔甘，他能将碎片重铸为完整的徽记。"},{t="在落锤镇",b="托尔甘说森古已经告诉他你需要帮助。看到这些碎片后，他认为工作并不困难，因为碎片都在这里，而且其魔法结构很容易复原。他让你闭上眼睛，很快就宣布索拉丁徽记已经重圆了。"}},faq={{q="什么是索拉丁徽记？",a="它是守护托拉斯·托尔贝恩陵墓的三枚徽记之一。他的儿子加林将其分成了十一块碎片，并分发给了激流堡的守军。",al={"索拉丁徽记背景知识","破碎徽记的含义","什么是破碎的徽记"}},{q="是谁打碎了徽记？",a="托拉斯·托尔贝恩之子加林将索拉丁徽记分成了十一块碎片，并分发给了激流堡的守军。",al={"谁打碎了徽记","徽记为何破碎","加林·托尔贝恩与徽记"}},{q="徽记碎片藏在哪里？",a="碎片在激流堡的守军手中，那里的民兵正固守着剩余的徽记。",al={"在哪里寻找碎片","谁持有碎片","激流堡守军徽记"}},{q="谁能修复破碎的徽记？",a="落锤镇的巨魔萨满托尔甘能够将这些碎片重铸为完整的徽记。",al={"谁能修复徽记","托尔甘与徽记","谁能重铸碎片"}},{q="在此之前发生了什么？",a="此任务紧接“斯特姆徽记”之后，在该任务中，你从辛迪加手中收回了第一枚徽记。",al={"前置任务","破碎的徽记的前置任务是什么","徽记任务链起点"}}},fp="16,277,17.321.0,10.169.0,13.271.1,30.156.0,22.135.0,35.112.0,30.97.0,22.85.0"}
P.entries["quest:6401"] = {n="卡雅还活着",s="“卡雅还活着”是石爪山脉中的一个部落短任务，标志着对卡雅·扁蹄的营救任务圆满结束。在护送这位年轻的牛头人平安穿过充满敌意的恐怖图腾土匪后，你会被派往烈日石居，将她幸存的好消息带给她焦急的姑妈——塔姆拉·荒原。",h="“卡雅还活着”是石爪山脉中的一个部落短任务，标志着对卡雅·扁蹄的营救任务圆满结束。在护送这位年轻的牛头人平安穿过充满敌意的恐怖图腾土匪后，你会被派往烈日石居，将她幸存的好消息带给她焦急的姑妈——塔姆拉·荒原。",kw={"扁蹄","恐怖图腾","卡雅","玛卡巴","保护卡雅","石爪山脉","烈日石居","塔姆拉","牛头人","荒原"},ang={["faction:Horde"]="石爪山脉是一片充满争议的荒野，部落的防线十分吃紧；传达幸存者的消息有助于维护分散的营地之间的团结。",["race:Tauren"]="恐怖图腾的威胁是舒哈鲁人心中一道痛苦的裂痕，这使得像卡雅这样无辜家人的安危显得尤为重要。"},sec={{t="松了一口气",b="石爪山脉危机四伏，特别是在那些恐怖图腾部族肆无忌惮地发起突袭的争议路段。当他们的村庄遭受残酷袭击时，人们曾担心年轻的卡雅·扁蹄已经遇害或被那些叛徒俘虏了。她的幸存和随后的获救，为这片崎岖山岭中持续不断的部族冲突带来了一丝难得的胜利与宽慰。"},{t="抵达烈日石居",b="在引导卡雅安全脱险后，玛卡巴·扁蹄委托你直接前往烈日石居传达消息。在那里，卡雅的姑妈塔姆拉·荒原正焦急地等待着来自路上的消息。带去卡雅平安的消息不仅慰藉了这个破碎的家庭，也进一步强化了往来的勇士在维系偏远部落据点联系中所发挥的重要作用。"}},faq={{q="卡雅·扁蹄是谁？",a="卡雅·扁蹄是一位年轻的牛头人，在石爪山脉的定居点遭到恐怖图腾叛军的暴力袭击后，她与族人失散并陷入了危险之中。",al={"卡雅是谁","卡雅·扁蹄","卡雅"}},{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是卡雅的姑妈，居住在石爪山脉的烈日石居。她曾担心自己的侄女在恐怖图腾的袭击中丧生。",al={"塔姆拉·荒原","塔姆拉是谁","卡雅的姑妈"}},{q="是谁袭击了卡雅的村庄？",a="卡雅的村庄遭到了好战的恐怖图腾氏族的伏击。这个崇尚孤立主义的牛头人派系因频繁掠夺敌对部落和过往路人而臭名昭著。",al={"谁袭击了卡雅","村庄遇袭","恐怖图腾袭击"}},{q="这个任务的前置任务是什么？",a="该任务紧接在“保护卡雅”之后，那是一项护送任务，你需要防卫卡雅·扁蹄，让她逃离俘虏魔爪并安全返回。",al={"前置任务","保护卡雅","护送任务"}},{q="烈日石居在哪里？",a="烈日石居坐落在石爪山脉中部的高处，沿着主路向西，穿过狭窄的山间隘口进入一个隐蔽的盆地即可到达。",al={"烈日石居位置","烈日石居在哪里","寻找烈日石居"}},{q="为什么玛卡巴·扁蹄让你去，而不是自己去？",a="玛卡巴仍然坚守在石爪山脉东南部边缘的营地，他依赖一名行动敏捷的信使，以便迅速让烈日石居的家人们放下心来。",al={"玛卡巴为什么留下","为什么派我去"}}},fx={["10e83b92"]={q="为什么玛卡巴·扁蹄想把这个消息送出去？",a="他们的村庄遭到残酷袭击，幸存者以为年轻的卡雅·扁蹄已在屠杀中丧生。如今她安然无恙，玛卡巴想立刻把消息送出去，好让卡雅的姑妈塔姆拉·荒原不再悲伤。塔姆拉正焦急地等在烈日石居，还不知道侄女幸存了下来。",al={"为什么把消息送给塔姆拉","玛卡巴·扁蹄的动机","为什么要传递消息"}}},fp="12,293,18.381.0,25.362.0,21.161.0,24.149.0,28.181.0,29.143.0,34.175.0,59.155.0"}
P.entries["quest:641"] = {n="索拉丁符印",s="托尔甘对破碎徽记的重铸工作非常完美。修复后的索拉丁徽记现在可以开启托尔贝恩之墓的封印了，他让你把它带回落锤镇交给森古。",h="托尔甘对破碎徽记的重铸工作非常完美。修复后的索拉丁徽记现在可以开启托尔贝恩之墓的封印了，他让你把它带回落锤镇交给森古。",kw={"阿拉希高地","落锤镇","索拉丁徽记","托尔甘","托尔卡拉","托尔贝恩之墓","森古"},sec={{t="修复后的徽记",b="托尔甘说重铸工作非常完美，索拉丁徽记现在已经可以开启托尔贝恩之墓的封印了。把它带回落锤镇交给森古，他肯定还有更多任务要交给你。"},{t="完成一半",b="森古问你是否拿到了第二个徽记，然后说他们离从托尔贝恩之墓取出托尔卡拉又近了一步。第三个徽记的下落尚不明确，因为持有它的人在阿拉希不断移动，但他相信你能找到它。"}},faq={{q="索拉丁徽记是用来做什么的？",a="修复后的徽记可以开启托尔贝恩之墓的封印。",al={"索拉丁徽记的用途","索拉丁徽记有什么用","为什么我们需要这个徽记"}},{q="你应该把索拉丁徽记交给谁？",a="落锤镇的森古。重铸了徽记的托尔甘让你把它带回给森古。",al={"我应该把徽记带到哪里","谁来交付索拉丁徽记","索拉丁徽记交付"}},{q="这一步在寻找托尔卡拉的过程中处于什么位置？",a="它紧接着“破碎的徽记”任务，在那个任务中，托尔甘用你带来的碎片重铸了徽记。",al={"徽记任务链进度","这个任务进行到什么程度了","这个任务的前置任务是什么"}}},fp="17,191,18.200.0,13.246.1,39.57.0,42.86.0,54.102.0"}
P.entries["quest:642"] = {n="被困的公主",s="当冒险者在阿拉希高地发现一枚虹光水晶碎片，并听到自称大地公主的米兹瑞尔被困在地底深处的哀求时，“被困的公主”便由此展开。她声称自己被敌对的巨人囚禁，并恳求旅行者前往枯须峡谷对抗这些巨人的狗头人盟友，恢复她那水晶通信网络的能量。",h="当冒险者在阿拉希高地发现一枚虹光水晶碎片，并听到自称大地公主的米兹瑞尔被困在地底深处的哀求时，“被困的公主”便由此展开。她声称自己被敌对的巨人囚禁，并恳求旅行者前往枯须峡谷对抗这些巨人的狗头人盟友，恢复她那水晶通信网络的...",kw={"阿拉希高地","枯须峡谷","枯须狗头人","大地公主","虹光碎片","米兹瑞尔微粒","米兹瑞尔","被困的公主"},ang={["class:Mage"]="利用共鸣水晶碎片和大地能量微粒进行远距离交流和能量引导，这展现了一种奇特的大地魔法。",["class:Shaman"]="作为与元素之灵沟通的修行者，萨满祭司会认出米兹瑞尔自称大地公主的说法，尽管她被囚禁在大地之下这一点值得进行严谨的元素审查。",["profession:Mining"]="冒险前往枯须峡谷附近和阿拉希地下矿脉的矿工，会发现自己不仅要面对狗头人的侵扰，还会遇到与这位公主息息相关的魔法水晶碎片。"},sec={{t="石中之声",b="散落在阿拉希高地的草海平原各处，奇怪的水晶碎片嗡嗡作响，散发着遥远的能量。靠近它们就能听到从深深的地底洞穴中传来的绝望呼唤：米兹瑞尔，一位自称大地公主的实体。她声称古老的巨人将她击落并囚禁在厚重的土壤之下，切断了她与阳光普照的地面世界的联系。嵌入地表的水晶是她与地表取得联系的唯一途径，将她的求救传达给任何愿意倾听的冒险者。"},{t="枯须之源",b="为了维持那脆弱的联系并开始突破地下的囚禁，米兹瑞尔指引旅行者向东前往枯须峡谷。峡谷里充斥着枯须狗头人，据她所说，这些生物正是囚禁她的巨人的盟友。这些狗头人携带着共鸣的米兹瑞尔微粒，并守卫着一簇显眼的虹光碎片。通过从狗头人手中夺取这些微粒并将其能量注入到晶簇中，救援者就能激活水晶簇，加深与这位被困公主的沟通。"}},faq={{q="米兹瑞尔是谁？",a="透过水晶说话的声音属于米兹瑞尔，一个声称自己是被囚禁在阿拉希高地下深处的“大地公主”。由于无法独自脱困，她向路过的冒险者求助，希望能借助他们的力量与地表进行沟通。",al={"谁是被困的公主","谁在透过水晶说话","米兹瑞尔是谁"}},{q="是谁把米兹瑞尔囚禁在高原之下？",a="据米兹瑞尔所说，她是由于巨人而被囚禁在阿拉希之下的。她声称巨人将她锁在地底深处，迫使她只能依赖散落在该地区的晶体碎片，与地面上行走的人进行沟通。",al={"谁囚禁了米兹瑞尔","谁困住了公主","为什么米兹瑞尔在地底"}},{q="什么是米兹瑞尔微粒？",a="米兹瑞尔微粒是由枯须狗头人携带的结晶或元素碎片。米兹瑞尔解释说，这些微粒蕴含着足够的潜在大地能量，可以激活并强化她与地表建立联系所需的水晶簇。",al={"为什么狗头人有微粒","枯须峡谷微粒","什么是米兹瑞尔微粒"}},{q="枯须狗头人与米兹瑞尔的囚禁者有什么关联？",a="米兹瑞尔指出，生活在枯须峡谷的枯须狗头人是囚禁她的巨人的盟友。他们守护着峡谷中的一个关键水晶簇，阻隔在公主与地表之间。",al={"为什么有狗头人参与","枯须狗头人与巨人","与巨人合作的狗头人"}},{q="米兹瑞尔是如何在地底说话的？",a="米兹瑞尔通过突起在阿拉希高地土壤中的神秘虹光水晶碎片传递她的声音。这些构造就像大地魔法的发射器，使她的灵魂或声音能够穿透地底深处，联系到地表的居民。",al={"米兹瑞尔如何说话","阿拉希虹光碎片","什么是水晶碎片"}},{q="枯须峡谷在哪里？",a="枯须峡谷是阿拉希高地东部的一处崎岖裂谷。那里居住着枯须狗头人，他们包围着虹光水晶簇，而米兹瑞尔正请求你用收集到的微粒去激活它们。",al={"枯须峡谷在哪里","去哪里交微粒","枯须碎片位置"}}},fp="20,374,22.523.0,25.532.0,15.265.0,42.218.0,30.244.0,62.214.0,46.262.0,34.216.0"}
P.entries["quest:6421"] = {n="滚岩峡谷",s="在石爪山脉深处的滚岩峡谷中，当地的狗头人开始疯狂挖掘一种被称为共鸣水晶的稀有地下矿石。摩罗加尔从大地的不安震动中察觉到了异样，于是派遣部落的冒险者去探索峡谷的洞穴系统，并取回矿石样本，以揭开埋藏在岩石之下的秘密。",h="在石爪山脉深处的滚岩峡谷中，当地的狗头人开始疯狂挖掘一种被称为共鸣水晶的稀有地下矿石。摩罗加尔从大地的不安震动中察觉到了异样，于是派遣部落的冒险者去探索峡谷的洞穴系统，并取回矿石样本，以揭开埋藏在岩石之下的秘密。",kw={"滚岩峡谷","土灵","狗头人","摩罗加尔","共鸣水晶","石爪山脉","烈日石居","泰坦"},ang={["class:Shaman"]="聆听大地的萨满祭司能够感受到那股不自然的共鸣在岩石中震动，因为狗头人正在揭开原始泰坦元素工艺的遗迹。",["profession:Mining"]="滚岩狗头人挖掘的共鸣水晶并非普通的矿石；其基质中注入了古代地下建筑者留下的古老奥术残余。",["race:Tauren"]="对于崇敬大地母亲的牛头人来说，挖掘出山脉下方的远古泰坦造物，预示着石爪山脉自然平衡的危险动荡。"},sec={{t="石中的震颤",b="牛头人摩罗加尔驻守在烈日石居，怀着深切的忧虑注视着石爪山脉的峰顶。大地本身似乎受到了惊扰，一股非自然的躁动正从东南方向蔓延开来。在那里，在滚岩峡谷的峭壁之中，当地的狗头人放弃了平时的搜寻，转而疯狂地开采一种稀有的地下矿石——共鸣水晶。为了查明这些迷信的害虫为何如此拼命地挖掘，摩罗加尔征召了部落的斥候，突破它们的防线，深入洞穴的最底层，并带回未经提炼的矿石样本。"},{t="唤醒远古",b="当原始的共鸣水晶被检查时，其真实本质显露无疑：这些晶体中回荡着古老的土灵魔法。盲目挖掘深层岩石的狗头人已经突破了世界的一层古老地壳，并挖掘出了一位土灵，这是泰坦为了塑造卡利姆多的地下基石而创造的原始岩石生物之一。狗头人眼中的矿石，竟是原始历史的遗迹，这迫使牛头人必须在埋藏的东西破土而出之前进行干预。"}},faq={{q="滚岩峡谷在哪里？",a="滚岩峡谷位于石爪山脉中烈日石居的东南方，切入山体之中。峡谷通向一个蜿蜒的洞穴系统，里面到处都是滚岩狗头人。",al={"滚岩峡谷位置","滚岩峡谷在哪里","如何找到滚岩峡谷"}},{q="谁发布了滚岩峡谷任务？",a="该任务由摩罗加尔发布，他是位于石爪山脉的主要部落哨所——烈日石居的一位牛头人。",al={"谁开启了滚岩峡谷","滚岩峡谷任务发布者","摩罗加尔任务"}},{q="什么是共鸣水晶？",a="共鸣水晶是一种深埋在滚岩洞穴系统中的稀有矿石。它携带着泰坦所造土灵魔法的残留痕迹，表明这些晶体是在靠近地下土灵遗迹的地方形成的。",al={"什么是共鸣水晶","共鸣水晶传说","共鸣水晶"}},{q="为什么狗头人要如此疯狂地挖掘共鸣水晶？",a="狗头人在挖掘时偶然发现了共鸣水晶，为了贪婪地寻找闪亮的矿石，他们深入山脉之下，直到惊动了埋藏在岩石中的远古土灵。",al={"为什么狗头人在挖掘","滚岩狗头人目标","石爪山脉狗头人阴谋"}},{q="根据牛头人的传说，什么是土灵？",a="根据摩罗加尔回忆的古老传说，土灵是泰坦在很久以前铸造的岩石生物，旨在雕琢和塑造这个世界的基岩。",al={"什么是土灵","土灵与泰坦的联系","谁是土灵"}},{q="完成这个任务后会发生什么？",a="在识别出共鸣水晶中蕴含的土灵魔法后，摩罗加尔准备了一种附魔的反制手段，并发布了后续任务“唤醒土灵”，派遣你回到洞穴去对抗那个苏醒的威胁。",al={"滚岩峡谷后的下一个任务","滚岩峡谷后续","滚岩峡谷任务后续"}}},fx={["574c7326"]={q="为什么摩罗加尔要调查这件事？",a="摩罗加尔察觉到石爪山脉中酝酿着令人不安的紧张气氛，担心山峰之下有未知的邪恶正在苏醒。狗头人开始疯狂地挖掘奇异的共鸣水晶，摩罗加尔需要从洞窟深处取得样本并进行侦察，以弄清他们可能惊动了什么远古力量。",al={"为什么调查滚岩峡谷","摩罗加尔的动机","摩罗加尔为什么在意"}},["6ccd8309"]={q="你在滚岩峡谷要对付谁？",a="你的目标是盘踞在烈日石居东南方峡谷中的滚岩狗头人。这些狗头人平时不过是些拾荒者，如今却陷入疯狂的执念，没日没夜地深入地下开采共鸣矿石；他们这么做的原因，正威胁着山岭的安宁。",al={"滚岩峡谷里有什么人","滚岩峡谷的敌人","滚岩峡谷的狗头人"}}},fp="19,347,20.608.0,22.489.1,37.181.0,40.125.0,27.225.1,51.193.1,44.165.0,41.225.1"}
P.entries["quest:643"] = {n="阿拉索符印",s="继Sigil of Thoradin任务之后，森古告诉你，人类王子将另一枚印记托付给了指挥骑兵的瓦洛卡尔中尉。找到他，并将印记带回落锤镇交给森古。",h="继Sigil of Thoradin任务之后，森古告诉你，人类王子将另一枚印记托付给了指挥骑兵的瓦洛卡尔中尉。找到他，并将印记带回落锤镇交给森古。",kw={"阿拉希高地","落锤镇","瓦洛卡尔中尉","sigil of arathor","stromgarde","trol'kalar","瓦洛卡尔","森古"},sec={{t="王子的骑兵",b="森古嘲笑道，人类连保住Stromgarde都很难，更别提整个阿拉希高地了，但他们的王子却让仅存的骑兵在乡村里四处游荡。森古无法理解原因。更重要的是，其中一枚印记在率领这些骑兵的瓦洛卡尔中尉手中。森古想要找到他，并将印记带回落锤镇。"},{t="在马背上",b="森古警告说，瓦洛卡尔很难被追上，因为他的马带着他在大地上飞驰。一旦他倒下，森古预计Stromgarde的守军将遭受重创，而部落距离夺取Trol'kalar又近了一枚印记。"}},faq={{q="是谁派你去寻找Sigil of Arathor的？",a="命令来自在落锤镇等候的森古。",al={"sigil of arathor任务发布者","谁发布了sigil of arathor任务","在哪里接取sigil of arathor任务"}},{q="是谁持有Sigil of Arathor？",a="瓦洛卡尔中尉，人类骑兵的指挥官，人类王子将印记交给了他。森古说他骑着马，很难追踪。",al={"谁持有sigil of arathor","瓦洛卡尔在哪里","瓦洛卡尔中尉位置"}},{q="为什么瓦洛卡尔中尉拥有这枚印记？",a="森古说人类王子给了他一枚印记。森古没有说明原因。",al={"为什么瓦洛卡尔拥有印记","谁给了瓦洛卡尔印记"}},{q="这在Trol'kalar任务链中处于什么位置？",a="这是漫长的Trol'kalar任务链的第五步。它位于Sigil of Thoradin之后，之后是Sigil of Trollbane。",al={"trol'kalar任务链阿拉索","sigil of arathor的前置任务","sigil of arathor的后续任务"}},{q="找到印记后该带到哪里？",a="带回落锤镇交给森古。",al={"在哪里上交sigil of arathor","sigil of arathor上交"}}},fp="16,199,20.383.0,12.240.1,43.52.0,31.159.0,45.82.0,44.124.0,46.28.0"}
P.entries["quest:644"] = {n="托尔贝恩符印",s="继阿拉索徽记之后，森古派你去杀死加林·托尔贝恩王子，并夺取最后那枚徽记——那枚可以开启他父亲托尔斯·托尔贝恩陵墓的徽记。王子将它随身携带，藏在激流堡深处。",h="继阿拉索徽记之后，森古派你去杀死加林·托尔贝恩王子，并夺取最后那枚徽记——那枚可以开启他父亲托尔斯·托尔贝恩陵墓的徽记。王子将它随身携带，藏在激流堡深处。",kw={"加林·托尔贝恩","落锤镇","阿拉索徽记","激流堡","托卡拉尔","森古","祖尔格拉布"},sec={{t="最后的徽记",b="能开启托尔斯·托尔贝恩陵墓的最后那枚徽记由托尔斯的儿子，加林王子亲自保管。他就在激流堡深处，民兵控制区内的一座教堂里。森古警告说，加林守卫森严，且是个厉害的战士，所以此行可能会非常艰难。你必须杀掉他，并将徽记带给落锤镇的森古。"},{t="森古的裁决",b="森古询问伊格纳斯·托尔贝恩的血脉是否已断绝。一旦断绝，他宣称托尔贝恩的血脉将不再困扰他的人民，而夺取托卡拉尔所需的所有徽记现在都已在他们手中。他发誓，用不了多久，他们就会向他痛恨的祖尔格拉布的巨魔发起进攻。"}},faq={{q="是谁派你去取回托尔贝恩徽记的？",a="是落锤镇的森古派你去取回的。",al={"托尔贝恩徽记任务发放者","谁发放托尔贝恩徽记任务","在哪里开始托尔贝恩徽记任务"}},{q="加林·托尔贝恩王子在哪里？",a="在激流堡深处的一座教堂里，位于民兵控制的区域内。",al={"加林·托尔贝恩王子位置","加林·托尔贝恩在哪里","激流堡的加林·托尔贝恩"}},{q="为什么要用到托尔贝恩徽记？",a="这是森古开启托尔斯·托尔贝恩陵墓所需的最后一枚徽记，由托尔斯的儿子亲自保管。",al={"托尔贝恩徽记的用途","为什么要获取托尔贝恩徽记"}},{q="获得托尔贝恩徽记之后会发生什么？",a="任务线将继续进行，接下来是托卡拉尔。",al={"托尔贝恩徽记之后的任务","托尔贝恩徽记后续"}}},fp="18,222,14.354.0,15.290.1,49.47.0,40.67.0,37.100.0,50.36.0"}
P.entries["quest:6441"] = {n="萨特的角",s="“萨特的角”是一份由游历灰谷碎木岗哨的地精皮克希尔提供的雇佣合同。皮克希尔在棘齿城的港口小镇发现了有利可图的贸易机会，于是雇佣有能力的部落冒险者去猎杀当地的萨特巢穴，收集他们珍贵的角。",h="“萨特的角”是一份由游历灰谷碎木岗哨的地精皮克希尔提供的雇佣合同。皮克希尔在棘齿城的港口小镇发现了有利可图的贸易机会，于是雇佣有能力的部落冒险者去猎杀当地的萨特巢穴，收集他们珍贵的角。",kw={"灰谷","夜道谷","皮克希尔","棘齿城","萨特的角","萨提纳尔","碎木岗哨","萨维亚"},ang={["class:Hunter"]="在萨提纳尔和夜道谷等被腐蚀的林地废墟中追踪恶魔类人生物，是对野外追踪技能的一项危险考验。",["class:Warlock"]="萨特体内灌注着强大的邪能魔法，这使得他们的躯体残骸对于那些研究恶魔力量的人来说是宝贵的奇珍。",["faction:Horde"]="清除灰谷中部的萨特可以削弱那些威胁碎木岗哨脆弱补给线的危险恶魔据点。"},sec={{t="有利可图的商机",b="在碎木岗哨这个部落前哨站休息时，一名投机的地精旅行者皮克希尔注意到边境市场有一个商机。在贫瘠之地的棘齿城，从灰谷的恶魔萨特身上获取的角需求量很大。皮克希尔不愿亲身犯险去面对那些堕落的生物，于是雇佣路过的冒险者在南下返回之前收集十六根完整的角。"},{t="堕落者的栖息地",b="灰谷的萨特居住在古老森林中四散的、被邪能污染的废墟里，这些是他们在古代大分裂期间背叛的遗迹。为了完成皮克希尔的订单，猎人们被指引前往已知的萨特据点，包括夜道谷、萨提纳尔的防御营地，以及萨维亚的阴影丛林。从这些巢穴中的任何一处进行采集，都能获得在棘齿城商铺中备受追捧的珍贵恶魔战利品。"}},faq={{q="皮克希尔是谁？",a="皮克希尔是一名进取的地精旅行者，在返回南方的中立港口棘齿城之前，他暂时停留在灰谷的碎木岗哨。",al={"任务发布者是谁","皮克希尔背景故事","碎木岗哨的地精"}},{q="为什么棘齿城需要萨特的角？",a="皮克希尔提到萨特的角在棘齿城能卖出高价。那里的商贩、炼金术士和奇异收藏家非常青睐从北部森林带回的原始恶魔试剂和奇珍材料。",al={"为什么收集萨特的角","角的用途","棘齿城的萨特角"}},{q="在灰谷哪里能找到萨特的角？",a="萨特栖息在灰谷的几处被污染的地区。著名的巢穴包括碎木岗哨西北方向的夜道谷、通往艾萨拉的大路旁的萨提纳尔，以及灰谷东北部的萨维亚。",al={"萨特位置","萨特在哪里","夜道谷 萨维亚 萨提纳尔"}},{q="什么是萨特？",a="萨特是数千年前屈服于燃烧军团恶魔腐蚀的古老暗夜精灵。他们变异成了长着蹄子和角的野兽，效忠于黑暗力量，并积极地腐蚀着周围的森林。",al={"什么是萨特","萨特背景故事","萨特是恶魔吗"}},{q="为什么这份合同在碎木岗哨处理？",a="碎木岗哨是部落在灰谷中部的核心要塞。皮克希尔将这里作为贸易路线间的一个安全休息点，并雇佣了周围那些已经卷入该地区危险冲突的部落战士。",al={"碎木岗哨萨特任务","为什么只有部落能接"}},{q="皮克希尔效忠于部落吗？",a="不。皮克希尔是一个独立的地精商人，只为了赚取利润。像许多以棘齿城为基地的地精一样，皮克希尔与任何能提供贵重贸易商品的人合作，并不关心阵营政治。",al={"皮克希尔是部落吗","皮克希尔阵营"}}},fx={["22d423d7"]={q="为什么皮克希尔想要萨特的角？",a="皮克希尔是一位精明的旅人，正前往棘齿城，并且看中了贸易机会。她知道萨特的角在地精港口能卖个好价钱，打算在完成旅程前赚上一笔。她不愿亲自面对那些危险的野兽，而是愿意付钱请能干的冒险者代劳，把货物送到手。",al={"皮克希尔为什么想要这个","皮克希尔索要萨特之角的动机","为什么收集萨特的角"}},fc903cbf={q="皮克希尔为什么不自己去猎杀萨特？",a="皮克希尔坦言，自己不是那些潜伏在灰谷废墟中的凶残施法萨特的对手。她没有足够的战斗本领，无法在萨提纳尔或萨维亚这样的地方活着脱身，因此只能依靠途经碎木岗哨的老练佣兵替她弄到货物。",al={"皮克希尔为什么需要我","皮克希尔为什么不能自己弄到角","为什么雇冒险者"}}},fp="11,283,23.425.0,23.430.0,13.161.0,34.200.0,44.204.0,16.231.0,50.226.0,44.206.0"}
P.entries["quest:6442"] = {n="佐拉姆海岸的纳迦",s="“佐拉姆海岸的娜迦”是一个部落任务，要求冒险者们清除灰谷西北海岸线上好战的蛇形入侵者。驻扎在佐拉姆加前哨站的巨魔玛鲁凯正试图通过驱逐沉没的古代佐拉姆废墟中的愤怒之尾娜迦，来确保这段备受争议的海岸线的安全。",h="“佐拉姆海岸的娜迦”是一个部落任务，要求冒险者们清除灰谷西北海岸线上好战的蛇形入侵者。驻扎在佐拉姆加前哨站的巨魔玛鲁凯正试图通过驱逐沉没的古代佐拉姆废墟中的愤怒之尾娜迦，来确保这段备受争议的海岸线的安全。",kw={"灰谷","玛鲁凯","娜迦","愤怒之尾","愤怒之尾首级","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="坚守佐拉姆加前哨站对部落在灰谷的扩张至关重要，因此清除娜迦已成了关乎军事生存的问题。",["race:Orc"]="玛鲁凯那种通过残酷击退来解决问题的直接策略，与兽人边境守军务实的尚武文化相吻合。"},sec={{t="岌岌可危的立足点",b="部落在佐拉姆海岸的处境非常不稳定。由于身处敌对暗夜精灵的领地之中，且灰谷内战火连绵，这座前哨站成了至关重要的沿海联络点。然而，突然出现的大量好战娜迦爬上岸来，威胁着要切断部落与海洋的联系，并在部落完全加固阵地之前将其守军淹没。"},{t="厄运佐拉姆的回响",b="在佐拉姆海岸的沙滩下掩埋着佐拉姆破碎的残骸。那曾是一座古老的精灵城市，在数千年前的大分裂中被大海吞没。玛鲁凯和前哨站的守军并不清楚这些愤怒之尾娜迦部族为何现在从深海沟壑中爬出来，但它们对沉没废墟突然表现出的兴趣对于任何在地面上行走的人来说都不是好兆头。"},{t="生存的代价",b="玛鲁凯以一种直截了当的生存视角看待局势：当利剑与三叉戟出鞘时，道理便不再重要。她要求收集二十颗愤怒之尾入侵者的首级，旨在以绝对武力将这些蛇形怪物赶回深海，从而为部落稳固海岸线。"}},faq={{q="谁发布了“佐拉姆海岸的娜迦”这个任务？",a="该任务由玛鲁凯发布，她是一位驻扎在灰谷西北部佐拉姆海岸的佐拉姆加前哨站的暗矛巨魔。",al={"任务发布者","谁开启任务","玛鲁凯位置"}},{q="佐拉姆海岸的背景历史是什么？",a="这段海岸线标志着古老而毁灭的佐拉姆城的安息之地。它在很久以前的大分裂时期被摧毁并沉没在无尽之海之下，如今其废墟部分位于灰谷的海岸线水下。",al={"什么是佐拉姆","佐拉姆历史","沉没之城"}},{q="为什么娜迦要攻击海岸？",a="部落驻军并不清楚愤怒之尾部族到来的确切动机，只知道这些生物从深海涌出，意图占据沉没的废墟并驱赶所有陆地居民。",al={"娜迦为何在此","愤怒之尾动机","娜迦目标"}},{q="我需要在这个任务中对抗哪些敌人？",a="你需要杀掉在佐拉姆海岸的沙滩和浪潮中爬行的愤怒之尾娜迦部族成员，并为玛鲁凯收集二十颗它们的首级。",al={"哪种娜迦","愤怒之尾首级","目标敌人"}},{q="“佐拉姆海岸的娜迦”之后是什么任务？",a="玛鲁凯在完成此任务后不会再提供后续任务；她只是感谢你，并希望能有更多像你一样的人来帮助守住海岸线。",al={"下一个任务","后续任务","玛鲁凯后续"}},{q="为什么部落关心这个偏僻的海滩？",a="灰谷是部落与暗夜精灵激烈争夺的地区。在佐拉姆海岸建立一个安全的沿海桥头堡，能让部落获得战略通路和补给线，避开密集的内陆森林。",al={"为什么部落在此","佐拉姆加前哨站目的"}}},fx={b1ee6e7c={q="为什么玛鲁凯想杀死纳迦？",a="玛鲁凯认为纳迦正对部落在海岸的驻地构成直接威胁。部落为夺取并守住灰谷海岸边的这个前哨，经历了艰苦的战斗。无论这些蛇形入侵者上岸有何神秘目的，它们日益增多的数量都可能压垮营地，必须予以削减并赶回海底。",al={"玛鲁凯为什么想要这个","玛鲁凯的动机","为什么杀死佐拉姆海岸的纳迦"}},["7626cdcb"]={q="怒尾纳迦是什么人？他们为什么会出现在佐拉姆海岸？",a="怒尾纳迦部族从海中爬上岸，占据了佐拉姆的废墟。佐拉姆是一座古老的卡多雷城市，在天崩地裂时遭到毁灭并沉入海底。部落守军尚不清楚他们更深层的意图，但他们不断蔓延的势力和沿岸的敌对袭击，已让任何靠近海岸的人面临直接威胁。",al={"怒尾纳迦是什么人","怒尾纳迦的故事","怒尾纳迦为什么在这里"}}},fp="24,312,21.388.0,22.371.0,21.317.0,45.144.0,44.218.0,37.204.0,48.166.0,44.124.0,48.217.0"}
P.entries["quest:645"] = {n="托卡拉尔",s="继巨魔克星符印之后，森古发现四枚符印已合而为一，足以破除巨魔克星陵墓上的结界。他派你去激流堡从陵墓中取回托卡拉尔。",h="继巨魔克星符印之后，森古发现四枚符印已合而为一，足以破除巨魔克星陵墓上的结界。他派你去激流堡从陵墓中取回托卡拉尔。",kw={"墓穴","密室","伊格纳乌斯符印","激流堡","托卡拉尔","巨魔克星","森古"},sec={{t="四印合一",b="森古发现四枚符印已经汇聚并形成了一枚新的符印，即伊格纳乌斯符印。他深信这枚符印能够破除施加在巨魔克星陵墓上的结界。巨魔克星安葬于激流堡教堂后的密室中，森古派你去那里取回托卡拉尔。教堂入口右侧有一条带围栏的小径，通往下方的墓穴。"},{t="陵墓开启",b="陵墓表面的刻痕与符印上发光的纹路一一对应。将两者对齐，一道闪光吞没了符印，传说之剑托卡拉尔从抓住它的石手中被解放了出来。"}},faq={{q="是谁派你去取回托卡拉尔的？",a="是森古，在他发现四枚符印合成了伊格纳乌斯符印之后。",al={"谁发布此任务","任务发布者","森古"}},{q="巨魔克星的陵墓在哪里？",a="他的遗骸安葬在激流堡教堂后的密室里。教堂入口右侧有一条带围栏的小径，通往地下的墓穴。",al={"陵墓在哪里","陵墓位置","墓穴位置"}},{q="那四枚符印发生了什么事？",a="它们合而为一，形成了伊格纳乌斯符印。森古认为这枚符印可以破除巨魔克星陵墓上的结界。",al={"符印发生了什么","伊格纳乌斯符印"}},{q="这个任务链的上一步是什么？",a="巨魔克星符印是四枚符印中的最后一枚，也是此任务的前置。",al={"上一个任务","前置任务","巨魔克星符印"}}},fp="10,205,19.371.0,14.212.1,37.62.0,34.133.0,32.129.0,40.67.0"}
P.entries["quest:646"] = {n="托卡拉尔",s="漫长的Trol'kalar任务线终于到了最后一步。光芒渐渐消散，被封印在石鞘中的Trol'kalar重见天日。将它带给落锤镇的森古。",h="漫长的Trol'kalar任务线终于到了最后一步。光芒渐渐消散，被封印在石鞘中的Trol'kalar重见天日。将它带给落锤镇的森古。",kw={"阿拉希","落锤镇","尼姆布亚","trol'kalar","托尔贝恩","森古","祖尔格拉布"},sec={{t="重获自由之剑",b="在托尔贝恩之墓，光芒渐渐消散，被封印在石鞘中的Trol'kalar重见天日。你带着这把剑鞘包裹着的剑，前往阿拉希高地落锤镇的森古那里。"},{t="森古的话",b="森古告诉你，斯托姆加德和阿拉索的军队世世代代都在捕杀巨魔，而现在他们最伟大的武器落入了他族人的手中。向祖尔格拉布潮湿丛林的缓慢推进将不再是一场苦战。他说暗矛巨魔欠你一个人情，他会负责将这把剑送到格罗姆高营地的尼姆布亚手中。"}},faq={{q="Trol'kalar需要带去哪里？",a="去阿拉希高地落锤镇找森古。你拿到这把剑时，它依然被封在石鞘里。",al={"我要把trolkalar带到哪里","trol'kalar运送","trolkalar上交"}},{q="我在哪里能找到这把剑？",a="在托尔贝恩之墓，那里消散的光芒使其从石鞘中释放了出来。",al={"trol'kalar在哪里","trolkalar位置"}},{q="这一步之前发生了什么？",a="这是漫长的Trol'kalar任务线的最后一步，它紧接着之前的Trol'kalar任务。",al={"trol'kalar前置任务","trolkalar任务线"}}},fp="10,158,16.173.0,15.357.1,33.97.0,26.82.0,27.95.0"}
P.entries["quest:6461"] = {n="盗窃的蜘蛛",s="“吸血者”是玛拉卡金暗矛巨魔定居点中的辛吉拉发布的一项部落狩猎契约。当地的巨魔在石爪山脉的坡地上找到了丰富的猎物，但屠宰猎物散发出的气味引来了大群捕食性的深苔蜘蛛，它们成群结队地侵入了营地。",h="“吸血者”是玛拉卡金暗矛巨魔定居点中的辛吉拉发布的一项部落狩猎契约。当地的巨魔在石爪山脉的坡地上找到了丰富的猎物，但屠宰猎物散发出的气味引来了大群捕食性的深苔蜘蛛，它们成群结队地侵入了营地。",kw={"吸血者","深苔爬行者","深苔毒液喷吐者","玛拉卡金","希塞尔山谷","蜘蛛","石爪山脉","辛吉拉"},ang={["class:Hunter"]="对于穿行在岩架间的资深追踪者而言，追踪那些狩猎并骚扰友好定居点的危险掠食者是顺理成章的工作。",["faction:Horde"]="玛拉卡金是部落从北部贫瘠之地进入石爪山脉的重要通路支点，保卫这个村庄也就确保了整个南部隘道的安全。",["race:Troll"]="玛拉卡金的猎人们是同胞，他们努力在卡利姆多崎岖的高地上开辟自给自足的领地，而不屈服于荒野。"},sec={{t="不受欢迎的晚餐宾客",b="在石爪山脉东南部建立玛拉卡金前哨站的巨魔们最初是为了寻找良好的狩猎场所。崎岖的山坡果然物产丰富，但他们带回的肉类和猎物很快就引起了夜行性掠食者的注意。深苔蜘蛛是北方岩架和峡谷中的原生攻击性蛛形纲动物，它们开始在夜幕的掩护下潜入营地，试图搜刮补给，甚至将猎人当作猎物。"},{t="清理岩架",b="为了确保营地的安全并保护补给，辛吉拉请求冒险者们向北追踪这些掠食者，进入山间隘口。在希塞尔山谷的岩石沟壑和蛛网密布的区域，深苔爬行者和毒液喷吐者的数量最为密集。削减它们的数量可以将蜘蛛群从玛拉卡金的边界驱赶出去，确保村庄在夜晚无需担忧遭到伏击。"}},faq={{q="谁发布了任务“吸血者”？",a="位于石爪山脉东南部玛拉卡金村的暗矛巨魔辛吉拉，向途经此地的部落勇士发布了这项任务。",al={"谁发布吸血者任务","吸血者任务发布人","辛吉拉任务"}},{q="为什么蜘蛛会攻击玛拉卡金？",a="玛拉卡金的巨魔们在当地进行了大规模狩猎。新鲜猎物和风干肉食散发的气味在夜间将深苔蜘蛛从山口引诱下来，它们以此偷窃补给并猎杀村民。",al={"为什么蜘蛛会攻击","蜘蛛袭击玛拉卡金","为什么蜘蛛在入侵"}},{q="深苔蜘蛛位于何处？",a="深苔爬行者和毒液喷吐者在玛拉卡金以北的中央隘口和岩架上游荡，其中在蛛网密布的希塞尔山谷深处聚集成群。",al={"深苔蜘蛛在哪里","深苔爬行者位置","深苔毒液喷吐者位置"}},{q="什么是玛拉卡金？",a="玛拉卡金是一个暗矛巨魔定居点，位于石爪山脉的南入口，靠近贫瘠之地边界，是部落的一个前哨狩猎基地。",al={"什么是玛拉卡金","玛拉卡金背景传说","石爪山脉巨魔村庄"}},{q="这些蜘蛛是否还引发了更大的威胁？",a="在希塞尔山谷的蛛网深处居住着一只体型巨大且致命的蜘蛛女王。峡谷外的一块告示牌警告了过往的旅行者这种危险，并鼓励小队前去铲除它。",al={"石爪山脉大蜘蛛","希塞尔山谷精英蜘蛛","石爪山脉蜘蛛女王"}},{q="清理蜘蛛后会发生什么？",a="清理掉爬行者和毒液喷吐者后，玛拉卡金的压力得以缓解，巨魔猎人可以守住肉食储备，并在夜间于营地中走动，不再时刻受到伏击的威胁。",al={"吸血者任务后续","玛拉卡金是否变安全"}}},fx={["5b921468"]={q="石爪山脉的深苔蜘蛛在做什么？",a="深苔爬行者和深苔毒蛛是石爪山脉土生土长的蛛形生物，徘徊在山崖与峡谷之间。它们一直栖居于这些山崖，但巨魔猎手带到玛拉卡金的新鲜猎物气味将它们引向了文明聚居地。如今，这些凶猛的捕食者愈发大胆，常趁夜色掩护，从崎岖的山丘中出没，袭击村庄营地。",al={"石爪山脉深苔蜘蛛","深苔爬行者和深苔毒蛛","蜘蛛为什么在这里"}}},fp="13,286,22.448.0,18.401.0,35.154.0,41.208.0,39.186.0,19.192.0,48.191.0,42.181.0"}
P.entries["quest:6462"] = {n="巨魔符咒",s="“巨魔符咒”是部落的一项任务，由位于灰谷佐拉姆加前哨站的暗矛巨魔米苏瓦提供。在一队旅行的巨魔遭到蓟皮熊怪的伏击并被屠杀后，米苏瓦请求冒险者深入它们的巢穴，找回被从死者身上偷走的圣物。",h="“巨魔符咒”是部落的一项任务，由位于灰谷佐拉姆加前哨站的暗矛巨魔米苏瓦提供。在一队旅行的巨魔遭到蓟皮熊怪的伏击并被屠杀后，米苏瓦请求冒险者深入它们的巢穴，找回被从死者身上偷走的圣物。",kw={"灰谷","暗矛","熊怪","米苏瓦","thistlefur hold","蓟皮村","巨魔符咒","佐拉姆加前哨站"},ang={["faction:Horde"]="深入蓟皮熊怪的领地是对那些伏击部落补给线和穿过灰谷的旅行者的林地威胁的反击。",["race:Troll"]="对于暗矛巨魔来说，找回符咒是一种精神职责，旨在确保神圣的祖传物品从野蛮的熊怪魔爪中被救回。"},sec={{t="遇袭的车队",b="佐拉姆加前哨站是部落在灰谷海岸西部的一处偏远避难所，这使得沿着林间小路行进充满了危险。一队前往该哨所的暗矛巨魔在途中失踪，他们遭遇了领地意识极强的蓟皮熊怪的暴力伏击。虽然米苏瓦接受了他的族人死亡这一事实，认为他们终会在来世重聚，但对他们圣物符咒的亵渎和窃取是不可容忍的侮辱。"},{t="圣物",b="在巨魔文化中，符咒和护身符与身份、精神保护以及与洛阿神的联系紧密相连。米苏瓦认为，一个没有符咒的巨魔就像一个没有战斗伤疤的兽人一样空虚且毫无价值。蓟皮熊怪将这些偷来的神器拖回了位于蓟皮村深处的Thistlefur Hold洞穴系统中，并将它们藏在箱子里，使其远离真正的主人。"}},faq={{q="谁提供这个任务，他们位于哪里？",a="该任务由米苏瓦提供，他是一名驻扎在灰谷西北海岸佐拉姆海岸的佐拉姆加前哨站的暗矛巨魔。",al={"任务提供者","米苏瓦的位置","谁开启巨魔符咒任务"}},{q="为什么巨魔符咒对米苏瓦如此重要？",a="对巨魔而言，圣物符咒具有深远的精神和文化意义。米苏瓦将没有符咒的巨魔比作没有战斗伤疤的兽人，他认为敌对的熊怪持有这些圣物是对他被杀害的族人的粗暴亵渎。",al={"符咒的重要性","为什么巨魔符咒很重要","符咒的意义"}},{q="巨魔符咒位于哪里？",a="符咒被存放在Thistlefur Hold内的箱子里，这是一个位于蓟皮村北缘的深层洞穴建筑群，坐落在暗夜精灵定居点阿斯特兰纳的北部。",al={"符咒位置","箱子在哪里","寻找符咒"}},{q="谁偷走了符咒？",a="蓟皮熊怪在米苏瓦的族人前往佐拉姆加前哨站的途中伏击并杀害了他们，洗劫了他们的财物并将圣物符咒拖入了他们的洞穴中。",al={"谁拿走了符咒","伏击元凶"}},{q="最初携带符咒的巨魔遭遇了什么？",a="他们在路上被蓟皮熊怪杀害了。米苏瓦哀悼他们的离去，但相信终有一天能在来世与他们重聚，目前他将找回他们的圣物作为首要任务。",al={"车队命运","被杀的巨魔","米苏瓦的族人"}},{q="联盟可以接这个任务吗？",a="不可以。该任务始于佐拉姆加前哨站，仅供帮助暗矛部族的部落玩家接取。",al={"联盟能接巨魔符咒吗","联盟可以做这个任务吗"}}},fx={["3db0517e"]={q="什么是巨魔符咒？",a="这些符咒是暗矛巨魔随身携带的神圣遗物。在他们的文化中，符咒象征着荣誉、身份和精神归属——正如米苏瓦所说，没有符咒的巨魔就像没有战斗伤疤的兽人一样空洞而毫无价值。虽然逝去的主人会在来世与族人团聚，但任由这些受人敬仰的信物落在野兽手中、遭受污损，是对他们记忆无法容忍的玷辱。",al={"巨魔符咒背景","巨魔符咒有什么作用","什么是巨魔符咒"}}},fp="11,292,19.467.0,15.422.0,48.142.0,49.253.0,35.190.0,21.181.0,62.205.0,40.117.0"}
P.entries["quest:647"] = {n="马克里尔的月光酒",s="马克里尔的月光酒是一个节奏紧凑的跑腿任务，受托于醉鬼马克里尔。这位矮人被困在萨多尔大桥断裂的一侧。由于贪杯喝多了自己酿的烈酒，导致在执勤时睡过了头，醉鬼马克里尔只能拜托一名联盟旅人赶紧把刚酿好的一批酒送去希尔斯布莱德，以还清他欠南海镇布鲁米·比格尔的一笔旧债。",h="马克里尔的月光酒是一个节奏紧凑的跑腿任务，受托于醉鬼马克里尔。这位矮人被困在萨多尔大桥断裂的一侧。由于贪杯喝多了自己酿的烈酒，导致在执勤时睡过了头，醉鬼马克里尔只能拜托一名联盟旅人赶紧把刚酿好的一批酒送去希尔斯布莱德，以...",kw={"比格尔","醉鬼马克里尔","布莱德·长须","马克里尔","米奈希尔","月光酒","南海镇"},ang={["faction:Alliance"]="这段快速的陆路行程突显了萨多尔大桥与希尔斯布莱德联盟控制下的南海镇之间至关重要的联系。",["race:Dwarf"]="矮人们会立刻理解那种伴随着剧烈宿醉，同时又欠同胞一笔酿酒债的双重窘境。"},sec={{t="守卫的宿醉",b="在断裂的萨多尔大桥上执勤的日子又湿又冷，而且出了名的枯燥。醉鬼马克里尔通过畅饮自己私酿的月光酒来抵御潮湿的寒意，这种酒极其猛烈，他形容喝完之后的感觉就像有一整支攻城器械部队从他的脑壳上碾过。但不幸的是，马克里尔因为喝得太多，在执勤时昏了过去。由于布莱德·长须正在指挥守卫大桥的矮人部队，马克里尔绝不能再出任何纪律上的岔子了。"},{t="与时间的赛跑",b="让马克里尔雪上加霜的是，他欠南海镇的布鲁米·比格尔一笔长期债务。马克里尔曾答应比格尔会送去一批他亲手酿的酒来抵债，但宿醉加上执勤任务，让他距离违约只剩几分钟的时间了。旅人必须依靠狮鹫和双脚，穿过阿拉希高地赶往南海镇，在比格尔认定马克里尔又一次赖账之前把酒桶送达。"}},faq={{q="醉鬼马克里尔是谁？",a="醉鬼马克里尔是一位矮人，可以在萨多尔大桥断裂的一侧找到，从阿拉希高地那一侧可以到达那里。他以酿造极其烈性的私酿月光酒而闻名，而且在执勤时往往会对自己的产品浅尝辄止得有点过头。",al={"醉鬼马克里尔","醉鬼马克里尔是谁","马克里尔任务发布者"}},{q="为什么这次送货这么紧急？",a="马克里尔因为在执勤时醉倒，导致任务严重延误。他有一个必须把月光酒送到布鲁米·比格尔手中以还清逾期债务的最后期限，从萨多尔大桥赶往南海镇的时间只剩下不到一刻钟了。",al={"为什么有计时器","为什么是15分钟","马克里尔的月光酒计时器"}},{q="布鲁米·比格尔是谁？",a="布鲁米·比格尔是一位矮人酿酒大师，在希尔斯布莱德丘陵的南海镇沿海定居点经营他的生意。他钟爱烈性酒精，并与醉鬼马克里尔有一笔未完成的商业协议。",al={"布鲁米·比格尔","比格尔是谁","比格尔 南海镇"}},{q="如何才能及时把月光酒送到南海镇？",a="从大桥没有船去南海镇。最快的路线是前往阿拉希高地，如果你知道飞行点，就从避难谷地骑狮鹫飞往南海镇，然后在计时结束前在镇子里找到布鲁米·比格尔。",al={"如何运送月光酒","马克里尔南海镇最快路线","月光酒配送路线"}},{q="长须是谁？",a="布莱德·长须是驻扎在湿地丹莫德外围的矮人指挥官，负责领导萨多尔大桥的守卫工作。马克里尔非常害怕被长须发现他在执勤时喝得不省人事。",al={"长须队长","长须 米奈希尔"}}},fx={d39890fd={q="为什么醉鬼马克里尔不能亲自送去月光酒？",a="前一晚，醉鬼马克里尔喝了太多自己酿的月光酒，结果值守时醉倒不醒。他现在头痛欲裂，还得向布莱德·长须交代擅离守卫岗位的事，而偿还布鲁米·比格尔债务的期限也所剩无几。他根本没有能力或余裕独自赶去南海镇。",al={"为什么是我找马克里尔","为什么要送月光酒","醉鬼的月光酒为什么要我送"}}},fp="20,347,18.478.0,24.441.0,22.235.0,31.267.0,26.229.0,53.246.0,17.248.0"}
P.entries["quest:648"] = {n="拯救OOX-17/TN！",s="受损的归航机器人OOX-17/TN发出了奥格索普的声音。它需要一个开阔、安全的地方来进行长时间的起飞，你被要求将其安全护送至热砂港，然后前往藏宝海湾找到奥格索普·奥布诺提斯。",h="受损的归航机器人OOX-17/TN发出了奥格索普的声音。它需要一个开阔、安全的地方来进行长时间的起飞，你被要求将其安全护送至热砂港，然后前往藏宝海湾找到奥格索普·奥布诺提斯。",kw={"藏宝海湾","归航机器人","机械小鸡","奥格索普·奥布诺提斯","oox-17/tn","热砂港","塔纳利斯"},sec={{t="护送至港口",b="奥格索普的声音再次从机器人体内传出，伴随着杂音。该机器人有内置的隐形装置，但奥格索普需要时间使其重新运作，因此它必须到达一个开阔、安全的地方，以便开始其漫长的起飞程序。热砂港正是奥格索普所想的地方，这段旅程能为他争取到修复的时间。你的任务是将机器人安全护送至那里。"},{t="前往藏宝海湾报告",b="一旦机器人安全抵达港口，你被要求在藏宝海湾寻找工程学大师奥格索普·奥布诺提斯。"},{t="感激的发明家",b="奥格索普把你当作救下OOX-17/TN的人来迎接。归航机器人系列仍需改进，但找回这一台机器节省了无数的重建时间以及大量的金币重造费用。奥格索普说，无论是机器人还是这位发明家都欠你一个人情。"}},faq={{q="需要把机器人护送到哪里？",a="送往热砂港，它可以在那里安全地开始起飞。",al={"oox-17要去哪里","oox-17护送路线","机器人目的地"}},{q="是谁在通过机器人说话？",a="奥格索普·奥布诺提斯，一位侏儒兼工程学大师，这台归航机器人就是他的。你可以在藏宝海湾找到这位发明家。",al={"谁制造了oox-17","oox-17的制造者","谁在通过机器人说话"}},{q="为什么要转移这台机器人？",a="它需要一个开阔、安全的地方来开始漫长的起飞程序。它内置的隐形装置也需要时间来重新恢复运作。",al={"为什么要转移oox-17","为什么要前往热砂港"}},{q="护送任务完成后该去哪里报告？",a="奥格索普·奥布诺提斯在藏宝海湾等待。",al={"奥格索普·奥布诺提斯在哪里","任务交给谁","oox-17任务交接地点"}}},fp="17,228,21.386.0,19.118.0,19.289.1,41.61.0,34.114.0,36.125.0,37.40.0"}
P.entries["quest:6481"] = {n="土灵的觉醒",s="在滚岩峡谷深处，萨满祭司摩罗加尔发现了一个名为Goggeroc的沉睡土灵，它被封印在一个共鸣水晶桶中。由于担心这古老的石造生物会给卡利姆多带来破坏性的力量，他派遣一名勇士去击碎水晶桶，趁Goggeroc恢复全部实力之前将其击倒。",h="在滚岩峡谷深处，萨满祭司摩罗加尔发现了一个名为Goggeroc的沉睡土灵，它被封印在一个共鸣水晶桶中。由于担心这古老的石造生物会给卡利姆多带来破坏性的力量，他派遣一名勇士去击碎水晶桶，趁Goggeroc恢复全部实力之前将...",kw={"滚岩峡谷","土灵","石中沉眠任务","goggeroc","摩罗加尔","共鸣水晶桶","萨满祭司","石爪山脉"},ang={["class:Shaman"]="摩罗加尔引导萨满力量来操纵共鸣水晶，破坏了保护桶内土灵的元素平衡。",["faction:Horde"]="通过消灭Goggeroc，部落的勇士巩固了他们在石爪山脉险峻岩脊上的立足点，同时也赢得了雷霆崖领袖们长久的尊重。",["race:Tauren"]="石爪山脉是雷霆崖各部族神圣的先祖狩猎地，在其山峰深处中和这个古老的毁灭性实体，保护了这片土地免遭荒废。"},sec={{t="石中沉眠",b="在调查滚岩峡谷的害虫侵扰时，侦察兵在狗头人中发现了一件奇怪的遗物：一个散发着超自然力量的共鸣水晶桶。摩罗加尔，一位驻扎在石爪山脉的牛头人萨满祭司，认出了这个容器的真面目——它是一个囚禁着沉睡土灵Goggeroc的监狱兼庇护所。这些原始的石造生物拥有超过凡人战士的力量，Goggeroc一旦重获自由，将对该地区构成生存威胁。"},{t="共鸣水晶",b="唤醒全盛时期的土灵对石爪山脉来说将是灾难性的。为了扭转局势，摩罗加尔改变了他所获得的共鸣水晶的混合比例，并向其中注入了萨满魔法。这种魔化共鸣水晶旨在以足够的力度击碎共鸣水晶桶，从而在Goggeroc极度虚弱的状态下将其震醒。部落的战士必须击碎容器，在泰坦造物从数百年的沉睡中清醒过来之前将其击倒。"}},faq={{q="摩罗加尔是谁？",a="摩罗加尔是一位驻扎在石爪山脉的牛头人萨满祭司。他研究该地区的异常现象，并利用他的元素魔法来评估当地害虫挖掘出的奇异古代文物和威胁。",al={"摩罗加尔","任务给予者是谁","兽人萨满摩罗加尔"}},{q="什么是土灵？",a="土灵是古代由活石锻造而成的生物，是泰坦在世界黎明时期留下的造物。它们与大地有着深厚的联系，并拥有惊人的体魄，数千年来一直沉睡在卡利姆多和东部王国的地下。",al={"什么是土灵","土灵背景知识","土灵是什么人"}},{q="摩罗加尔为什么要杀死Goggeroc？",a="摩罗加尔担心，一个活跃的土灵所拥有的无与伦比的力量会给石爪山脉和整个卡利姆多带来灾难。由于这种原始生物不可预测且力量强大，他认为在Goggeroc沉睡后的虚弱状态下将其消灭，是保护这片土地的唯一方法。",al={"为什么要杀死goggeroc","goggeroc是邪恶的吗","为什么要击杀土灵"}},{q="Goggeroc在哪里？",a="Goggeroc被封印在位于石爪山脉东南部的滚岩峡谷的洞穴深处的一个共鸣水晶桶中，周围环绕着在那挖掘洞穴的滚岩狗头人。",al={"水晶桶在哪里","goggeroc的位置","寻找共鸣水晶桶"}},{q="如何唤醒Goggeroc？",a="你需要直接在洞穴中的共鸣水晶桶上使用摩罗加尔提供的魔化共鸣水晶。这种经过魔法改造的水晶会使容器破裂，迫使沉睡的土灵现身。",al={"如何召唤goggeroc","使用魔化共鸣水晶","打开水晶桶"}},{q="击杀Goggeroc后会发生什么？",a="带着Goggeroc死亡的消息回到摩罗加尔那里，可以缓解这位萨满祭司深沉的忧虑。他将你视为英雄，你的事迹避免了一场巨大的灾难，这为你赢得了雷霆崖牛头人中崇高的荣誉和地位。",al={"任务奖励剧情","摩罗加尔的反应","提交任务石中沉眠"}}},fx={["7cc06600"]={q="戈格罗克是谁？他为什么在石爪山脉？",a="戈格罗克是一名古老的土灵，是泰坦很久以前锻造出的活石生物。他被封在滚岩峡谷深处洞穴中的一只共鸣水晶桶里，沉睡在石爪山脉之下。摩罗加尔警告说，土灵若以完整力量苏醒，其无与伦比的强大力量将对石爪山脉乃至整个卡利姆多构成灾难性威胁。砸开水晶桶，能趁他从漫长沉睡中醒来、尚未清醒且虚弱时将其擒住，这是你击败他的唯一机会。",al={"戈格罗克是谁","戈格罗克背景","戈格罗克是什么"}},["9f2ce835"]={q="摩罗加尔为什么需要你击败戈格罗克，而不是自己出手？",a="摩罗加尔在烈日石居运用萨满之力，改变你收集来的共鸣水晶。他让你带着附魔水晶返回洞穴，打开戈格罗克的水晶桶，并趁土灵刚从漫长沉睡中醒来、力量尚未恢复时发动攻击。",al={"摩罗加尔为什么不和戈格罗克战斗","为什么是我","为什么派我去对付戈格罗克"}}},fp="13,335,18.513.0,20.491.1,17.221.0,19.254.0,38.305.0,26.203.0,27.210.0,37.227.1"}
P.entries["quest:6482"] = {n="鲁尔的自由",s="在灰谷北部Thistlefur Hold的深处，一只名叫鲁尔·雪蹄的被囚禁的熊正在等待被从腐化的Thistlefur熊怪手中救出。部落的冒险者可以协助这位俘虏杀出熊怪巢穴，获得安全。",h="在灰谷北部Thistlefur Hold的深处，一只名叫鲁尔·雪蹄的被囚禁的熊正在等待被从腐化的Thistlefur熊怪手中救出。部落的冒险者可以协助这位俘虏杀出熊怪巢穴，获得安全。",kw={"灰谷","德鲁伊护送","熊怪","鲁尔·雪蹄","碎木岗哨","thistlefur hold","雅玛·雪蹄"},ang={["class:Druid"]="鲁尔的被捕是一个令人谦卑的提醒，告诫人们以动物伪装在野性领地徘徊的风险，因为在那里的腐化生物无法分辨谁是朋友，谁是猎物。",["faction:Horde"]="从灰谷北部腐化的空洞中救出的每一个灵魂，都在加强部落在碎木岗哨那摇摇欲坠的据点。",["race:Tauren"]="拯救一名塞纳里奥议会的被困兄弟，并平息他在碎木岗哨亲人的忧虑，这既是对大地母亲的尊崇，也是对部落情谊的践行。"},sec={{t="枷锁中的德鲁伊",b="当德鲁伊鲁尔·雪蹄在灰谷北部的腐化森林中冒险时，他以熊形态徘徊到了离Thistlefur Hold太近的地方。那些失去祖先智慧并受野性偏执驱使的腐化熊怪，误以为这位变形的牛头人只是一头普通的野兽。它们不仅没有对他保持敬畏，反而将他关进笼子里并让他挨饿，耗尽了他的魔法储备，使他无法独自脱身。"},{t="逃离巢穴",b="由于饥饿和囚禁而虚弱不堪，鲁尔无法变形或在没有帮助的情况下从熊怪巢穴中杀出重围。一旦被部落的盟友救出，他便依赖援救者清理出一条道路，以通过成群的敌对Thistlefur熊怪。在安全抵达碎木岗哨郊外后，他短暂地显露出牛头人的真身，表达了衷心的感谢，随后便回到荒野中去睡觉以消除疲劳。"}},faq={{q="为什么鲁尔·雪蹄会被熊怪关起来？",a="鲁尔当时正以熊的形态探索森林。腐化的Thistlefur熊怪没能认出他是一位德鲁伊，误以为他是一头野兽，便将他关进笼子里，让他挨饿，直到他没有力气逃跑。",al={"为什么鲁尔被困","鲁尔是如何被捕的","为什么被关在笼子里"}},{q="雅玛·雪蹄是谁？",a="雅玛·雪蹄是鲁尔的妹妹，驻扎在灰谷的碎木岗哨。几天前鲁尔进入森林后便没了音讯，她为此深感担忧。",al={"鲁尔的妹妹","碎木岗哨的雅玛","雅玛是谁"}},{q="为什么鲁尔不能直接变回人形逃走？",a="长期的囚禁和Thistlefur熊怪蓄意的虐待让他饥肠辘辘，鲁尔变得极度虚弱。由于缺乏食物和体力，他体内的自然能量储备完全耗尽，直到获救前都束手无策。",al={"为什么鲁尔没有变身","德鲁伊熊形态陷阱"}},{q="鲁尔到达安全地带后会发生什么？",a="一旦被护送出充满敌意的巢穴并到达碎木岗哨的边缘，鲁尔会短暂地变回牛头人的自然形态以表达感激之情，随后变回熊的形态，去寻找一个安静的地方睡觉和恢复体力。",al={"鲁尔去哪里了","鲁尔结局"}},{q="灰谷里的所有熊怪都像Thistlefur熊怪一样敌对吗？",a="不。虽然许多熊怪部族拥有高贵的传承和与自然的深厚联系，但灰谷北部的Thistlefur部族已经屈服于黑暗的腐化力量，变得具有攻击性且难以预料。",al={"熊怪是邪恶的吗","thistlefur腐化"}},{q="救援在哪里进行？",a="鲁尔被关押在Thistlefur Hold内部，这是一个位于灰谷碎木岗哨西北方山区和阿斯特兰纳北部的熊怪巢穴。",al={"鲁尔在哪里","鲁尔·雪蹄位置"}}},fx={cd4f3bf3={q="鲁尔·雪蹄为什么需要你护送，而不是自己逃出去？",a="鲁尔被困在一座刺毛熊怪的牢笼里已有数日，遭受堕落的熊怪囚禁并忍受饥饿。他的体力几乎耗尽。他虚弱不堪、营养不良，又身陷敌对的刺毛熊怪巢穴深处，无法独自杀出周围部族的包围，只能依靠你为他开辟一条自由之路。",al={"鲁尔为什么需要帮助","鲁尔为什么不能独自逃走","为什么让我找鲁尔·雪蹄"}}},fp="15,223,17.433.0,19.421.1,48.238.1,21.176.0,56.235.1,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="迪菲亚兄弟会",s="这一差事标志着揭开恐怖统治西部荒野的秘密辛迪加面纱的第一步。受哨兵岭的格里安·斯托曼派遣，旅行者被指引向东进入赤脊山，去咨询一位可能知道窃贼藏身之处的线人。",h="这一差事标志着揭开恐怖统治西部荒野的秘密辛迪加面纱的第一步。受哨兵岭的格里安·斯托曼派遣，旅行者被指引向东进入赤脊山，去咨询一位可能知道窃贼藏身之处的线人。",kw={"迪菲亚","格里安·斯托曼","湖畔镇","赤脊山","哨兵岭","西部荒野","黑衣威利"},ang={["class:Rogue"]="斯托曼认识到正规军无法瓦解一个犯罪集团；这需要一个了解阴影和街头交易的人，这直接指向了黑衣威利。",["faction:Alliance"]="从西部荒野到赤脊山的漫长旅程凸显了在首都漠不关心的情况下，暴风城的外围领地必须多么依赖彼此。"},sec={{t="尘土中的威胁",b="西部荒野已沦为废墟，农作物被洗劫一空，且到处都是戴着红色头巾的强盗。格里安·斯托曼和人民民兵团在哨兵岭抵御着近乎不断的骚扰，但他们是在盲目作战。斯托曼意识到，如果不找到这个卡特尔的核心圈子并查明幕后主使，仅靠砍杀零散的劫匪永远无法拯救这片地区。"},{t="外地的线人",b="斯托曼没有依赖官方军事渠道或暴风城那些缺位的贵族，而是动用了他的人情债。他派遣值得信任的冒险者穿过艾尔文森林进入赤脊山。在宁静的湖畔镇，潜伏在当地旅店二楼的是一名叫黑衣威利的潜行者。比起任何民兵队长，威利更了解地下世界，他是揭开迪菲亚潜行者藏身处的第一条线索。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼是人民民兵团的领袖，这是一支驻扎在西部荒野哨兵岭的乌合之众般的防御力量。由于暴风城忽视了边境地区，他负责协调剩余少数当地农民和难民的防御工作。",al={"格里安·斯托曼","谁发布了这个任务","西部荒野任务发布者"}},{q="斯托曼为什么要让你去湖畔镇？",a="人民民兵团在西部荒野内部缺乏地下线人。斯托曼动用了以前欠下的人情，要求湖畔镇旅店里的潜行者黑衣威利帮忙，希望通过地下情报网揭露谁是窃贼的头目。",al={"为什么去湖畔镇","为什么要前往赤脊山","为什么找威利"}},{q="黑衣威利是谁？",a="黑衣威利是一名潜行者，住在赤脊山的Lakeshire Inn二楼。他欠格里安·斯托曼一个人情，这使他成为传递地下传闻和犯罪消息的有用渠道。",al={"威利是谁","威利 湖畔镇","黑衣威利"}},{q="什么是迪菲亚潜行者？",a="迪菲亚潜行者是一个戴着红色面具的冷酷犯罪卡特尔，他们夺取了西部荒野的农场、道路和废弃矿井的控制权，正积极驱逐定居者并挑战暴风城的权威。",al={"迪菲亚潜行者","什么是迪菲亚","红头巾强盗"}},{q="我在湖畔镇哪里可以找到威利？",a="黑衣威利位于赤脊山湖畔镇大桥附近的Lakeshire Inn二楼。",al={"威利在哪里","寻找威利","威利位置"}},{q="这个任务需要战斗吗？",a="不需要。最初的这一步纯粹是信息收集。你只需从西部荒野的哨兵岭出发，穿过艾尔文森林前往湖畔镇的旅店与威利取得联系。",al={"这个任务难吗","迪菲亚潜行者任务有战斗吗","敌人"}}},fp="22,189,22.352.0,22.414.0,25.219.0,43.215.0,23.194.0,31.179.0,36.130.0,35.102.0"}
P.entries["quest:6503"] = {n="灰谷先驱者",s="“灰谷斥候”是库莱比在灰谷发布的一项部落巡逻拦截任务。暗夜精灵侦察兵从银翼哨站四散而出，搜集附近部落营地的情报，这促使部落发动先发制人的打击，以隐藏哨站的防御状况。通过猎杀这些潜行的侦察兵，部落可以使当地的联盟部队失去耳目，并遏制其未来的入侵企图。",h="“灰谷斥候”是库莱比在灰谷发布的一项部落巡逻拦截任务。暗夜精灵侦察兵从银翼哨站四散而出，搜集附近部落营地的情报，这促使部落发动先发制人的打击，以隐藏哨站的防御状况。通过猎杀这些潜行的侦察兵，部落可以使当地的联盟部队失去耳...",kw={"联盟","灰谷","灰谷斥候","部落","库莱比","暗夜精灵侦察兵","银翼哨站"},ang={["class:Hunter"]="在深邃的林地地形中追踪隐蔽的斥候，依靠的是敏锐的直觉、强化的追踪感官和精准的箭术。",["class:Rogue"]="消灭敌方斥候可以扭转暗夜精灵的隐身优势，确保部落的渗透者能掌控森林阴影中的主动权。",["faction:Horde"]="在灰谷中每消灭一个暗夜精灵侦察兵，都能保护当地营地和伐木作业免受联盟协同反攻的威胁。"},sec={{t="林冠之眼",b="灰谷的森林依然是一片竞争激烈的边境，每一条小径和山脊都受到严密的监视。情报如同战斧一般致命，传给库莱比的报告证实，被称为“灰谷斥候”的暗夜精灵侦察兵已经从联盟位于银翼哨站的据点溜了出来。这些侦察兵在基地以东、当地部落据点以南的茂密荒野中活动，他们在林间小径潜行，以绘制防御工事图并追踪部队动向。"},{t="致盲联盟",b="为了防止有组织的突袭，部落必须在敌方侦察兵返回基地前将其消灭。通过猎杀这些斥候，部落勇士可以阻止银翼哨站的指挥官获得有关部队兵力和哨站外围防御的重要情报。失去了前进的耳目，暗夜精灵将变得不知所措，在穿越这片争议林区时也会减少采取激进战术的意愿。"}},faq={{q="谁发布了“灰谷斥候”这个任务？",a="该任务由驻扎在灰谷的部落侦察协调员库莱比发布，他致力于追踪并反制暗夜精灵在森林各处的行动。",al={"任务发布者","谁发布任务","库莱比任务"}},{q="灰谷斥候位于何处？",a="这些斥候在银翼哨站以东、库莱比营地以南的森林中徘徊，在灌木丛中巡逻以搜集情报。",al={"斥候位置","斥候在哪里","去哪里找斥候"}},{q="为什么斥候对部落构成威胁？",a="这些斥候是从银翼哨站出发的先遣侦察兵。如果他们成功绘制了部落营地和部队兵力的地图，联盟就能针对薄弱位置协调进行精确突袭。",al={"为什么要杀斥候","斥候的威胁","斥候的目的"}},{q="什么是银翼哨站？",a="银翼哨站是暗夜精灵在灰谷的重要军事设施，作为联盟部队保卫森林和对抗部落扩张的前线基地。",al={"银翼哨站背景","什么是银翼哨站","银翼联盟"}},{q="这个任务是更长故事线的一部分吗？",a="此任务主要是一项独立的战术任务，旨在减少该区域的联盟侦察活动，奖励那些协助库莱比巩固周边防线的战士。",al={"任务链","后续任务","斥候任务链"}},{q="联盟玩家可以完成这个任务吗？",a="不可以，此任务仅限部落玩家。库莱比完全是代表部落在灰谷的前线利益行事。",al={"这是部落专属吗","联盟版本","联盟能做这个吗"}}},fx={["2873db73"]={q="库莱比为什么想杀死灰谷跑者？",a="库莱比想让联盟变成聋子瞎子，阻止他们有组织地进攻部落领地。那些跑者最近从银翼哨站溜出，开始在部落防线附近活动。如果他们摸清了你们营地的防御和部队调动，联盟的攻势几乎必然接踵而至。除掉他们，就能阻止敌人获取至关重要的战场情报。",al={"库莱比的动机","为什么杀跑者","库莱比的理由"}},["884af179"]={q="灰谷跑者是谁？",a="他们是从附近联盟据点银翼哨站派出的暗夜精灵斥候。这些敏捷的先遣斥候在茂密的森林树冠下行动，悄悄靠近部落边境，监视防御工事、侦察巡逻路线，并为联盟日后的入侵行动做好准备。",al={"什么是灰谷跑者","跑者是谁","灰谷跑者的目标"}}},fp="20,388,20.476.0,21.423.0,41.151.0,43.148.0,45.204.0,27.180.0,41.179.0,41.119.0"}
P.entries["quest:6504"] = {n="丢失的书页",s="在将一台刚从棘齿城买来的地精伐木机运往战歌伐木营地的途中，兽人古尔达·怒痕因为一阵突如其来的大风弄丢了机器的操作手册。她现在被困在碎木岗哨附近，如果不找回这些散落的书页，她根本无法操作这台复杂的工程奇迹。",h="在将一台刚从棘齿城买来的地精伐木机运往战歌伐木营地的途中，兽人古尔达·怒痕因为一阵突如其来的大风弄丢了机器的操作手册。她现在被困在碎木岗哨附近，如果不找回这些散落的书页，她根本无法操作这台复杂的工程奇迹。",kw={"灰谷","古尔达·怒痕","棘齿城","伐木机","伐木机操作手册","碎木岗哨","丢失的书页","战歌伐木营地"},ang={["faction:Horde"]="每一台运抵战歌伐木营地的伐木机，都能加快采集珍贵木材的速度，这些木材是杜隆塔尔建设围墙、小屋和战舰所必需的。",["profession:Engineering"]="工匠们会对古尔达的困境感同身受：在没有制造商指南的情况下驾驶地精制造的伐木机，很容易导致锅炉灾难性地损坏。",["race:Orc"]="体力劳动和战士传统使得人们对繁琐的地精文书工作缺乏耐心，这让古尔达因为丢失技术手册而感到懊恼显得非常真实。"},sec={{t="倒霉的一阵风",b="战歌氏族主要依靠从棘齿城港口的地精那里购买的蒸汽伐木机来清除灰谷的树木。对于普通的兽人战士来说，操作这些精巧又吵闹的装置绝非易事。当古尔达·怒痕带着一台刚买来的伐木机向北行进时，一阵突如其来的狂风从她手中卷走了说明书，十二页脆弱的羊皮纸散落在森林的地面上。"},{t="荒野中的书页",b="由于狂风将手册吹过了树冠，散落的书页散布到了整个地区，落入了游荡的生物、邪教徒和森林居民的手中。如果无法集齐这三个章节，这台复杂的机器就只是一堆静止的钢铁和旋转的锯片，古尔达也只能被困在前往碎木岗哨的路上，无法去伐木营地报到。"}},faq={{q="古尔达·怒痕是谁？",a="古尔达·怒痕是一位部落劳工，她的任务是将一台地精伐木机从棘齿城商港运送到灰谷，加入战歌伐木营地的伐木工作。",al={"古尔达","怒痕","任务发布者是谁"}},{q="为什么古尔达需要说明书才能驾驶伐木机？",a="地精工程学以挑剔和反直觉著称，依赖于不稳定的锅炉、复杂的压力阀和精密的杠杆。即使是一个急切的兽人，如果不阅读制造商的手册，也无法安全地操作这种装置。",al={"为什么需要说明书","为什么她无法驾驶伐木机","伐木机操作手册"}},{q="手册的书页是怎么散落在灰谷各处的？",a="在沿森林道路向北行驶时，一阵猛烈的狂风将书从古尔达的手中吹走。散乱的书页在树林中四散飘落，只剩下空荡荡的封皮还抓在她手里。",al={"书页是如何丢失的","风吹散了书页"}},{q="伐木机最终要去哪里？",a="这台机器的目的地是战歌伐木营地，部落在那里开展了大规模的砍伐行动，为奥格瑞玛和杜隆塔尔提供木材。",al={"伐木机要去哪里","战歌伐木机的目的地"}},{q="在哪里可以找到丢失的书页？",a="狂风将书页吹得到处都是，它们已经被在灰谷各处游荡的各种人形生物和敌对森林生物捡走了。",al={"去哪里寻找书页","谁会掉落书页"}},{q="部落为什么要从棘齿城购买机械？",a="棘齿城是最近的中立港口，拥有与地精贸易财阀相连的活跃贸易网络。部落经常购买专业的工程设备、爆破工具和蒸汽驱动的车辆来加强其军事后勤。",al={"部落的地精机械","棘齿城的部落贸易"}}},fx={["63589195"]={q="古尔达·怒痕为什么需要你寻找说明书的书页？",a="古尔达被困在碎木岗哨附近的路上，身边有一台她不会操作的闲置地精伐木机。她受命将这台昂贵的机器从棘齿城运回战歌伐木营地报到。没有说明书，她根本不知道如何驾驶；若弃车在荒野中、徒步进森林寻找书页，宝贵的部落装备就会无人看守。",al={"古尔达为什么需要帮助","古尔达为什么不能找到书页","为什么让我找遗失的书页"}}},fp="14,296,18.449.0,23.388.0,22.180.0,64.235.0,61.195.0,42.159.0,37.143.0,51.225.0"}
P.entries["quest:651"] = {n="禁锢之石",s="在“公主被困”任务完成后，来自虹色碎片的一个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。其中最强大的那一块——内缚灵石，只有使用从其他三块石头上取得的钥匙才能解锁。",h="在“公主被困”任务完成后，来自虹色碎片的一个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。其中最强大的那一块——内缚灵石，只有使用从其他三块石头上取得的钥匙才能解锁。",kw={"阿拉希高地","烈焰钥匙","海浪钥匙","虹色碎片","米兹拉尔","内缚灵石","缚灵石","雷霆钥匙"},sec={{t="四块缚灵石",b="那个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。若要松动它们，必须首先解锁最强大的一块：内缚灵石，它需要从其他三块——西缚灵石、东缚灵石和外缚灵石上收集的钥匙。这些钥匙分别是烈焰钥匙、海浪钥匙和雷霆钥匙。守护者们看守着这些石头，但聪明或幸运的人或许能找到驱逐它们的方法。收集齐钥匙后，便可将其带到内缚灵石处。"},{t="在内缚灵石处",b="这块石头传出了米兹拉尔的声音：缚灵石已被打开，枷锁正在松动，自由已近在咫尺。米兹拉尔称赞你是高尚的拯救者。"}},faq={{q="这一步来自哪里？",a="它来自虹色碎片，是在完成“公主被困”之后。",al={"缚灵石任务发布者","谁发布缚灵石任务","如何开始缚灵石任务"}},{q="四块缚灵石分别是什么？",a="西缚灵石、东缚灵石、外缚灵石，以及最强大的内缚灵石。",al={"哪些是缚灵石","阿拉希缚灵石","四块石头"}},{q="解锁内缚灵石需要哪些钥匙？",a="烈焰钥匙、海浪钥匙和雷霆钥匙，分别从西、东和外缚灵石处收集。",al={"缚灵钥匙","需要什么钥匙","内缚灵石的钥匙"}},{q="谁在看守缚灵石？",a="守护者们在看守着这些石头，不过聪明或幸运的冒险者也许能找到驱逐它们的方法。",al={"石头守护者","谁在看守石头","缚灵石保卫者"}},{q="钥匙必须送到哪里？",a="送到内缚灵石处，这是其中最强大的一块，必须先解锁它，其他石头才会打开。",al={"我该把钥匙带去哪里","交付缚灵石任务","内缚灵石位置"}}},fp="17,253,11.501.0,18.162.1,31.64.0,36.127.0,48.115.0,30.99.0,33.107.0"}
P.entries["quest:652"] = {n="打开钥匙之石",s="一旦束缚之石被开启，那个声音的禁锢便缓解了许多，但仍有一道锁将其困住。那道锁就是石环中的基石，而那个声音的囚禁者之一，岩石看守者Fozruk，持有这把钥匙。看守者们称其为秩序魔棒。",h="一旦束缚之石被开启，那个声音的禁锢便缓解了许多，但仍有一道锁将其困住。那道锁就是石环中的基石，而那个声音的囚禁者之一，岩石看守者Fozruk，持有这把钥匙。看守者们称其为秩序魔棒。",kw={"阿拉希高地","fozruk","基石","秩序魔棒","内在束缚之石","岩石看守者"},sec={{t="最后的锁",b="随着束缚之石被开启，那个声音的禁锢已经大大缓解，但仍有一道锁未解：基石，位于你周围的石环之中。它的钥匙由一名囚禁者持有，即岩石看守者Fozruk，看守者们称之为秩序魔棒。从Fozruk手中夺取魔棒并将其带到基石处，这道锁就会被解开。那个声音承诺，如果你能做到这一点，它的感激之情将震动大地的根基。基石本身充盈着巨大的地脉能量。"},{t="在基石处",b="当魔棒被插入基石时，你的脚下传来一阵颤动。"}},faq={{q="这一步之前要做什么？",a="首先是束缚之石，开启那些石头减轻了那个声音的大部分禁锢。",al={"前置条件","前置任务","束缚之石前置条件"}},{q="Fozruk是谁？",a="Fozruk是一位岩石看守者，也是那个声音的囚禁者之一，他持有基石的钥匙。",al={"fozruk是谁","fozruk背景故事","岩石看守者fozruk"}},{q="什么是秩序魔棒？",a="这是岩石看守者对基石钥匙的称呼，由Fozruk持有。",al={"秩序魔棒","什么是秩序魔棒","基石钥匙"}},{q="基石在哪里？",a="基石矗立在阿拉希高地的一处石环之中。",al={"破碎基石在哪里","基石位置","阿拉希石环"}}},fp="21,271,13.497.0,15.65.1,28.96.0,14.92.0,25.80.0,22.69.0"}
P.entries["quest:6523"] = {n="保护卡雅",s="“保护卡雅”是一个位于石爪山脉的部落护送任务。在发现卡雅·扁蹄被敌对的恐怖图腾牛头人俘虏后，冒险者将指引她穿过危险的山路，抵达阿帕拉耶营地。带回她幸存的消息，会让她焦急的父亲玛卡巴·扁蹄感到无比宽慰。",h="“保护卡雅”是一个位于石爪山脉的部落护送任务。在发现卡雅·扁蹄被敌对的恐怖图腾牛头人俘虏后，冒险者将指引她穿过危险的山路，抵达阿帕拉耶营地。带回她幸存的消息，会让她焦急的父亲玛卡巴·扁蹄感到无比宽慰。",kw={"阿帕拉耶营地","护送","恐怖图腾","卡雅·扁蹄","玛卡巴·扁蹄","保护卡雅","石爪山脉","牛头人"},ang={["faction:Horde"]="确保旅行家庭的安全可以巩固部落在石爪山脉来之不易的立足点和补给路线。",["race:Tauren"]="营救卡雅直接帮助了因恐怖图腾氏族的侵略行径而分崩离析的同胞。"},sec={{t="岩架上的囚徒",b="石爪山脉中弥漫着牛头人之间激烈的竞争，其中最尖锐的矛盾莫过于针对奸诈的恐怖图腾氏族的紧张局势。卡雅·扁蹄在敌对领地的深处被俘并遭到囚禁。徒步逃离需要穿过蜿蜒的小径，那里既有伺机而动的捕食者，又有警惕的敌人，因此武装护送是她能抵达安全地带的唯一现实希望。"},{t="前往阿帕拉耶营地",b="阿帕拉耶营地位于石爪山脉东部，卡雅知道从那里回家的路。她的目标是那个营地，并确信一旦抵达那里，她就能找到回家的路。护送她通过充满伏击的路径，可以确保她在抓捕者意识到她溜走之前避免再次被俘。"},{t="父亲的宽慰",b="玛卡巴·扁蹄在石爪山脉东南部边界等待消息，他非常担心失踪女儿的安危。当信使带来卡雅已安全抵达阿帕拉耶营地的确切消息时，玛卡巴的绝望转变成了对那些在他孩子与绑架者之间筑起防线的英雄们的无尽感激。"}},faq={{q="卡雅·扁蹄是谁？",a="卡雅·扁蹄是一位年轻的牛头人，在石爪山脉被敌对的恐怖图腾势力俘虏。她依靠路过的部落冒险者将她解救出来，并护送至安全地带。",al={"卡雅是谁","卡雅·扁蹄背景故事","卡雅"}},{q="卡雅需要被护送到哪里？",a="卡雅必须被安全地护送穿过通往石爪山脉东部阿帕拉耶营地的小径，从那里她知道回家的路。",al={"卡雅护送目的地","要把卡雅带到哪里","卡雅去哪里"}},{q="玛卡巴·扁蹄是谁？",a="玛卡巴·扁蹄是卡雅的父亲，焦急地等待在石爪山脉的东南部入口处。在冒险者带回她获救的消息之前，他一直为失踪的孩子感到绝望。",al={"玛卡巴是谁","玛卡巴·扁蹄背景故事","卡雅的父亲"}},{q="是谁俘虏了卡雅？",a="卡雅是被敌对的恐怖图腾牛头人俘虏的，他们在石爪山脉的岩架上设有营地并进行伏击。",al={"谁抓了卡雅","谁绑架了卡雅","卡雅的绑架者"}},{q="卡雅抵达阿帕拉耶营地后会发生什么？",a="一旦卡雅抵达阿帕拉耶营地，她就能找到回家的路，而玩家的任务是回到玛卡巴·扁蹄身边，传递她幸存下来的喜讯。",al={"保护卡雅之后","护送之后做什么","保护卡雅后续"}},{q="联盟玩家可以接这个任务吗？",a="不能。扁蹄家族属于热爱和平的牛头人，他们效忠于部落，因此这项救援任务仅限部落冒险者。",al={"联盟能做保护卡雅吗","卡雅是部落专属吗"}}},fx={ee59f589={q="卡雅·扁蹄为什么需要你的保护？",a="卡雅刚刚从劫持者手中逃脱，却仍被困在山中的敌方领地。如果她还没到达安全地带，劫持者就发现她逃跑了，她便会再次被抓或遭到杀害。阿帕拉耶营地是她唯一能获得庇护、并向担心她安危的父亲玛卡巴报平安的地方。",al={"为什么保护卡雅","卡雅·扁蹄的动机","卡雅为什么需要护送"}},["87bb92ff"]={q="卡雅·扁蹄为什么不能自己逃走？",a="卡雅虚弱不堪、手无寸铁，周围全是敌方领地。若没有一名强力战士在她逃跑时保护她免受巡逻队袭击，她就无法在行踪暴露之前安全地沿路前往阿帕拉耶营地。",al={"卡雅为什么需要我","卡雅为什么不能独自离开","为什么需要护送"}}},fp="12,311,22.400.0,22.295.0,17.322.1,21.195.0,36.131.0,23.190.0,18.115.0,45.162.0,44.137.0"}
P.entries["quest:653"] = {n="密斯莱尔的盟友",s="Myzrael大喊着她自由了，并且说她会躲起来积蓄力量以避开她的囚禁者。她称你为高尚的盟友，并让你去找位于铁炉堡Forlorn Cavern里的一家商店中的葛利·硬骨，他知道如何召唤她。",h="Myzrael大喊着她自由了，并且说她会躲起来积蓄力量以避开她的囚禁者。她称你为高尚的盟友，并让你去找位于铁炉堡Forlorn Cavern里的一家商店中的葛利·硬骨，他知道如何召唤她。",kw={"阿拉希高地","forlorn cavern","葛利·硬骨","巨人","铁炉堡","基石","myzrael"},sec={{t="重获自由积蓄力量",b="Myzrael自由了，她打算躲起来积蓄力量，避开她的囚禁者，因为如果现在与他们相遇，她肯定会被再次击败并囚禁起来。终有一天她要面对那些巨人，她发誓他们会后悔曾经囚禁过她。她称你为高尚的盟友，并说她会再次需要你的帮助，在她准备好时将她召唤到地表。"},{t="给葛利·硬骨的消息",b="Myzrael让你去和葛利·硬骨交谈，他的商店位于铁炉堡的Forlorn Cavern。他知道该如何召唤她。"}},faq={{q="在哪里可以找到葛利·硬骨？",a="葛利·硬骨在铁炉堡的Forlorn Cavern开了一家店。",al={"葛利·硬骨位置","葛利·硬骨在哪里","寻找葛利·硬骨"}},{q="为什么Myzrael要躲起来？",a="她需要先积蓄力量。如果她的囚禁者现在就面对她，她肯定会被再次击败并囚禁起来。",al={"为什么myzrael要躲藏","myzrael要去哪里"}},{q="Myzrael提到的囚禁者是谁？",a="是那些曾经监管她的巨人。她说终有一天她会去面对他们，他们会为此感到后悔。",al={"myzrael的囚禁者","谁囚禁了myzrael","myzrael和巨人"}},{q="为什么Myzrael让你去铁炉堡？",a="葛利·硬骨知道如何召唤她，她说当她准备好时，需要你把她召唤到地表。",al={"为什么去铁炉堡","拜访葛利的目的"}}},fp="16,237,23.352.0,24.133.0,35.64.0,35.125.0,38.106.0,39.125.0"}
P.entries["quest:654"] = {n="塔纳利斯的样本",s="开启电源后，野外测试工具包开始发光并振动。你现在有两个小时的时间来收集塔纳利斯的沙漠产物，否则数据就会丢失。",h="开启电源后，野外测试工具包开始发光并振动。你现在有两个小时的时间来收集塔纳利斯的沙漠产物，否则数据就会丢失。",kw={"蜥蜴","比格维兹","野外测试工具包","加基森","鬣狗","电源","蝎子","塔纳利斯","水业公司"},sec={{t="滴答作响的电源",b="电源启动后，工具包开始发光并振动，看起来一切运行正常。首席工程师沙克斯·比格维兹说，你需要在两小时内从塔纳利斯沙漠收集到足够的数据：从八只蜥蜴、八只鬣狗和八只蝎子身上采集的合格样本。如果时间耗尽，所有的东西都会丢失，你必须从比格维兹那里重新购买电源。在电量耗尽前，必须将该工具包带回加基森交给比格维兹。"},{t="公司的利润",b="对于任何工具包没电的人，比格维兹都不会表示同情。他唯一关心的就是加基森水业公司能赚多少钱。比格维兹愿意一直出售电源，直到公司有能力从丹莫罗的冰泉进口水源。"}},faq={{q="测试工具包需要采集哪些生物的样本？",a="从塔纳利斯沙漠的八只蜥蜴、八只鬣狗和八只蝎子身上采集的合格样本。",al={"需要测试哪些动物","样本采集目标","需要击杀什么"}},{q="完成样本采集有多少时间？",a="从电源开启的那一刻起，你有两个小时的时间。",al={"时间限制","我有多少时间","计时器"}},{q="如果电源耗尽会发生什么？",a="工具包里的一切都会损毁，你必须从加基森的首席工程师沙克斯·比格维兹那里重新购买一个电源才能重新开始。",al={"如果计时器时间到了","任务失败","电源耗尽"}},{q="装满后的测试工具包要送到哪里？",a="在电量耗尽前，送到加基森的首席工程师沙克斯·比格维兹那里。",al={"我该交给谁","交任务地点","比格维兹在哪里"}},{q="为什么比格维兹要一直出售电源？",a="比格维兹希望加基森水业公司能盈利，即使这意味着要通过出售电源来维持，直到公司有能力从丹莫罗的冰泉进口水源。",al={"比格维兹的目标","加基森水业公司的目标","为什么要采集样本"}}},fp="22,167,22.449.0,20.266.0,54.96.0,52.58.0,42.134.0,40.75.0,49.186.0"}
P.entries["quest:6541"] = {n="向卡德拉克报到",s="十字路口的索克指引有能力的部落战士前往灰谷边境附近的卡德拉克岗哨。卡德拉克负责协调部落向这座古老森林的扩张，并让新来的招募者为前方的持续冲突做好准备。",h="十字路口的索克指引有能力的部落战士前往灰谷边境附近的卡德拉克岗哨。卡德拉克负责协调部落向这座古老森林的扩张，并让新来的招募者为前方的持续冲突做好准备。",kw={"灰谷","贫瘠之地","十字路口","卡德拉克","碎木岗哨","索克","岗哨","佐拉姆海岸"},ang={["faction:Horde"]="这份调令标志着从保卫贫瘠之地已定居领土到确保北方争议森林中重要资源生命线的转变。",["race:Orc"]="灰谷是兽人至关重要的试炼场，确保了加固奥格瑞玛并在卡利姆多建立永久家园所需的木材。"},sec={{t="通往北方之路",b="当十字路口忙于应对野猪人、半人马和当地强盗时，部落更广泛的领土利益着眼于北方的灰谷茂密森林。索克充当中间人，将那些在贫瘠之地中部证明了自己的老练战士引导至卡德拉克驻守的北部边境岗哨。"},{t="边境战略",b="卡德拉克负责监管通往灰谷的南部路径，组织增援部队以巩固部落在边境线上的立足点。随着碎木岗哨和佐拉姆海岸前哨站等新营地的建立，部落尽管面临当地暗夜精灵的激烈抵抗，仍在积极巩固其在木材资源丰富的林地中的存在。"}},faq={{q="谁是索克？",a="索克是一名驻扎在贫瘠之地十字路口的兽人军官。他协助协调当地的防御工作，并将有前途的冒险者指派去参与灰谷战役等区域性的战争行动。",al={"索克 十字路口","谁给予向卡德拉克报到的任务","索克 贫瘠之地"}},{q="卡德拉克在哪里？",a="卡德拉克驻扎在贫瘠之地的北部岗哨，就在通往灰谷森林的主干道旁。",al={"卡德拉克位置","卡德拉克在哪里","卡德拉克 岗哨"}},{q="为什么部落要进军灰谷？",a="部落需要木材和资源来建设他们在杜隆塔尔和贫瘠之地的新城市。向灰谷扩张提供了至关重要的木材，尽管这使他们与暗夜精灵陷入了直接冲突。",al={"为什么是灰谷","部落在灰谷","灰谷入侵"}},{q="部落在灰谷建立了哪些前哨站？",a="卡德拉克提到，部落在通往森林的中央道路旁建立了碎木岗哨，并在更西边的佐拉姆海岸建立了另一个前哨站。",al={"部落在灰谷的基地","佐拉姆海岸基地","碎木岗哨"}},{q="向卡德拉克报到后会发生什么？",a="一旦你向卡德拉克报到，他会向你简要说明当地的军事局势，并指派你收集散布在灰谷各处的战歌伐木场哨所的报告。",al={"卡德拉克之后","卡德拉克之后的任务","卡德拉克提供什么"}},{q="除了贫瘠之地，还有其他地方能接到这个任务吗？",a="可以。石爪山脉玛拉卡金的部落战士也会接到一份几乎完全相同的去向卡德拉克报到的征召令。",al={"其他的卡德拉克任务","石爪山脉 卡德拉克任务"}}},fp="16,179,14.247.0,17.295.0,13.170.0,24.90.0,40.219.0,53.128.0,37.149.0,69.129.0"}
